REGISTRY_REVISION = 26     # 26 (provisional): the engine 100% build-out revision (N-150, N-151)

def registry_fingerprint() -> str:
    """sha256 over the canonical JSON of everything that decides a cell: the registry, the declared N/A
    rules, the N/A causes the inspector may emit, and the cell-gate list."""
    import hashlib
    blob = json.dumps(dict(registry=CRITERION_REGISTRY, na_rules=NA_RULE_DECISIONS, na_causes=NA_CAUSES,
                           cell_gates=list(CELL_GATES), rollup_order=list(ROLLUP_ORDER)),
                      sort_keys=True, default=list, separators=(",", ":"))
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()


def criterion_applicability(crit: str, layer: str, facts: dict | None = None) -> dict:
    """E6.1: is registered criterion `crit` applicable to an asset of `layer`, given the asset `facts` the
    caller SUPPLIED (`columns`: the target table's column names; `asset_kind`)?

    States: OUT_OF_LAYER (layer not declared; not part of that layer's gate), NOT_APPLICABLE (a supplied
    fact contradicts a declared pattern; carries the `rule_id` an N/A would need), UNKNOWN (the fact the
    pattern needs was not supplied — absence is never NOT_APPLICABLE), APPLIES. NOT_APPLICABLE dominates
    UNKNOWN: one disproving fact is definitive whatever the other says. Raises KeyError for an
    unregistered criterion."""
    e = CRITERION_REGISTRY[crit]
    if layer not in LAYERS:
        raise KeyError(f"unknown layer {layer!r}; expected one of {sorted(LAYERS)}")
    if layer not in e["layers"]:
        return dict(state="OUT_OF_LAYER", rule_id=None, reason=f"{crit} is not defined for {layer}")
    facts = facts or {}
    unknown = []
    for key, fact_key, label in (("columns_any", "columns", "target-table columns"),
                                 ("asset_kinds", "asset_kind", "asset_kind")):
        pattern = e[key]
        if pattern is None:
            continue
        have = facts.get(fact_key)
        if key == "columns_any":
            # evidence only when a list/tuple/set of str; an EMPTY collection counts only when the caller
            # asserts columns_known is exactly True ("the table is known and has zero columns")
            usable = (isinstance(have, (list, tuple, set)) and all(isinstance(c, str) for c in have)
                      and (bool(have) or facts.get("columns_known") is True))
        else:
            usable = isinstance(have, str) and bool(have)
        if not usable:
            unknown.append(f"{label} not supplied" if have is None else f"{label} unusable ({have!r})")
            continue
        ok = (any(c in pattern for c in have) if key == "columns_any" else have in pattern)
        if not ok:
            return dict(state="NOT_APPLICABLE", rule_id=f"{crit}#{key}",
                        reason=f"{label} {list(have) if key == 'columns_any' else have!r} match none of {list(pattern)}")
    if unknown:
        return dict(state="UNKNOWN", rule_id=None, reason="; ".join(unknown) + " — applicability undecidable")
    return dict(state="APPLIES", rule_id=None, reason="applies")


def rollup_verdicts(verdicts) -> str:
    """E6.2: worst of FAIL > ERRORED > NO_DETECTOR > PARTIAL > PASS. All N/A -> N/A. No checks ->
    NO_DETECTOR (a gate with no checks measures nothing). A verdict outside PASS/FAIL/PARTIAL/NO_DETECTOR/
    ERRORED/N/A (NOT_GENERIC included) raises ValueError: an ungradable value is never silently ranked.
    Any iterable is accepted (materialised first, so a generator is not drained by validation); a bare str
    raises TypeError (it would otherwise be iterated character by character)."""
    if isinstance(verdicts, (str, bytes)):
        raise TypeError("rollup_verdicts takes an iterable of verdicts, not a bare string")
    verdicts = list(verdicts)
    for v in verdicts:
        if v not in ROLLUP_ORDER and v != NA:
            raise ValueError(f"verdict {v!r} is outside the rollup vocabulary {list(ROLLUP_ORDER) + [NA]}")
    if not verdicts:
        return NO_DET
    graded = [v for v in verdicts if v != NA]
    if not graded:
        return NA
    return min(graded, key=ROLLUP_ORDER.index)


def narr_coupling_problem(crit: str, layer: str, meas, facts, all_meas) -> str | None:
    """NARR-GUARD (pin 16, N-94). None when the Narr check `crit` is not COUPLED (no `prose_coupling` block on its record and none declared in `facts`: every asset that does not
    declare one, exactly as before) or is coupled and honoured; else why its N/A is NOT honoured (the rollup then reads NO_DETECTOR). ONE definition, read by `_check_contribution`,
    `_na_released` (the gap ledger), the certificate writer and the E6.3 reader (run from the ref's own copy of this module).

    A coupled N/A stands only while (1) the record carries a well-formed block (`to` carriage_d1, `columns`, the D1 result key of each in `covered`) matching the declared coupling
    when `facts` carry one (a record that dropped its own block cannot slip through: the declaration is read independently), (2) the asset's EFFECTIVE Carr.D1 contribution, by this
    census's own `_check_contribution` rule (verified chunk ledger and digest, every row matched at the declared row count, a citation_state that is not unsourced / refuted), reads
    PASS, and (3) the D1 record shows a passing per-row result for every coupled column (what D1 MEASURED, independent of what any declaration says)."""
    if not (isinstance(crit, str) and crit.startswith("Narr.")) or not isinstance(meas, dict):
        return None
    blk = meas.get("prose_coupling")
    fcp = facts.get("declared_prose_coupling") if isinstance(facts, dict) else None
    if isinstance(facts, dict) and facts.get("declared_prose_coupling_missing") is True:
        return ("Narr N/A rests on Carr.D1 PASS (coupled): the asset declares prose_fields [] with a D1 transcription carriage but no prose_coupling, so nothing ties the N/A to "
                "Carr.D1 (N-94)")
    if blk is None and fcp is None:
        return None
    if not (isinstance(blk, dict) and blk.get("to") == PROSE_COUPLING_TO and isinstance(blk.get("columns"), list) and blk["columns"]
            and all(isinstance(c, str) for c in blk["columns"]) and isinstance(blk.get("covered"), dict) and set(blk["covered"]) == set(blk["columns"])):
        return ("Narr N/A rests on Carr.D1 PASS (coupled): the asset is coupled (declared or recorded) but this record carries no well-formed prose_coupling block, so what it "
                "rests on cannot be read")
    if fcp is not None and (fcp.get("to") != blk.get("to") or fcp.get("columns") != blk.get("columns") or fcp.get("covered") != blk.get("covered")):
        return ("Narr N/A rests on Carr.D1 PASS (coupled): the record's prose_coupling block (to / columns / covered) does not match the declared coupling and the D1 spec's own "
                "coverage")
    d1m = all_meas.get("Carr.D1") if isinstance(all_meas, dict) else None
    try:
        eff = _check_contribution("Carr.D1", layer, d1m, facts, all_meas) if isinstance(d1m, dict) else None
    except (KeyError, ValueError, TypeError, AttributeError) as exc:
        return f"Narr N/A rests on Carr.D1 PASS (coupled): Carr.D1 cannot be evaluated ({type(exc).__name__}: {exc})"
    reading = eff["v"] if isinstance(eff, dict) else "not measured"
    if reading != PASS:
        extra = f" (the D1 record says {d1m.get('v')}: {eff['reason']})" if isinstance(eff, dict) and d1m.get("v") != reading else ""
        return f"Narr N/A rests on Carr.D1 PASS (coupled): Carr.D1 reads {reading}{extra}"
    rows = (d1m.get("d1") or {}).get("rows") if isinstance(d1m.get("d1"), dict) else None
    if not (isinstance(rows, list) and rows):
        return "Narr N/A rests on Carr.D1 PASS (coupled): the D1 record carries no per-row results, so no coupled column is shown to have been matched"
    for col in blk["columns"]:
        key = blk["covered"].get(col)
        if not isinstance(key, str) or any(not (isinstance(r, dict) and isinstance(r.get("result"), dict) and r["result"].get(key) in (True, "NULL-ok")) for r in rows):
            return (f"Narr N/A rests on Carr.D1 PASS (coupled): the D1 record shows no passing per-row result for the coupled column {col!r} (result key {key!r}): "
                    "Carr.D1 did not measure that column")
    return None


def _check_contribution(crit: str, layer: str, meas: dict | None, facts: dict | None, all_meas: dict | None = None) -> dict | None:
    """One criterion's contribution to its gate cell, or None when it is out of layer and unmeasured. `all_meas` (the asset's whole `measurements`
    mapping; rollup_asset passes it) lets a Null check see its sibling: the Null cap lifts only when BOTH Null checks carry the verified convention (S1)."""
    e = CRITERION_REGISTRY[crit]
    ap = criterion_applicability(crit, layer, facts)
    if meas is not None:
        if ap["state"] == "OUT_OF_LAYER":
            raise ValueError(f"{crit} was measured on {layer} but the registry declares layers {list(e['layers'])}")
        v = meas["v"]
        if v not in ROLLUP_ORDER and v != NA:
            raise ValueError(f"{crit}: measured verdict {v!r} is outside the rollup vocabulary")
        if v == NA:
            cause = meas.get("cause")
            if not (isinstance(cause, str) and _CAUSE_SLUG.fullmatch(cause)):
                # N-22 principle 2: an N/A whose inspector named no usable cause cannot be keyed to any rule.
                # Reported (reason + the cause as found), never honoured — not even by an `every id declared` set.
                return dict(criterion=crit, v=NO_DET, state="MEASURED",
                            reason=f"N/A without a declared cause (cause={cause!r}): the inspector named no usable "
                                   "cause, so no rule can release it")
            rid = f"{crit}#measured:{cause}"
            if cause not in NA_CAUSES.get(crit, ()):
                return dict(criterion=crit, v=NO_DET, state="MEASURED", rule_id=rid, cause=cause,
                            reason=f"measured N/A with cause {cause!r}, which is not a registered cause of {crit}: "
                                   "never honoured")
            if rid in NA_RULE_DECISIONS:
                bad = narr_coupling_problem(crit, layer, meas, facts, all_meas)       # NARR-GUARD (pin 16): a coupled Narr N/A needs its Carr.D1 PASS
                bad = bad or prose_none_na_problem(crit, meas, facts)                         # N-150 R1: a no-prose N/A needs its CHECKED prose_none block
                bad = bad or lint_na_problem(crit, meas)                                      # N-150 R2: a lint-not-applicable N/A needs the scan's agreement
                bad = bad or no_writer_na_problem(crit, meas)                                 # N-150 R5: a no-writer N/A needs the declaration and the two agreeing facts
                bad = bad or update_only_na_problem(crit, meas)                               # SS 2026-10-05: an update-only N/A needs the declaration and the agreeing scan
                bad = bad or no_table_na_problem(crit, meas)                                  # SS 2026-10-05: a no-table N/A needs the declaration and the agreeing registry / code facts
                bad = bad or vocab_values_na_problem(crit, meas)                              # N-176: a no-vocabulary-values N/A needs its checked bounded value reading
                bad = bad or unsourced_declared_na_problem(crit, meas)                        # N-177: an unsourced-declared N/A needs its verified residual block
                if bad:
                    return dict(criterion=crit, v=NO_DET, state="MEASURED", rule_id=rid, cause=cause, reason=bad)
                return dict(criterion=crit, v=NA, state="MEASURED", rule_id=rid, cause=cause,
                            decision=NA_RULE_DECISIONS[rid], reason="measured N/A under a declared rule")
            return dict(criterion=crit, v=NO_DET, state="MEASURED", rule_id=rid, cause=cause,
                        reason="measured N/A but N/A rule undecided (N-22): an undeclared N/A is not N/A")
        if crit == "Carr.D1" and v in (PASS, PARTIAL):
            # S2 (adversarial review MED 4): a D1 verdict is honoured ONLY with its evidence: the verified chunk ledger and the digest of
            # the cut span, a citation_state that is not unsourced/refuted, and (PASS) every row matched with the declared row count.
            bad = d1_evidence_problem(meas)
            if bad:
                return dict(criterion=crit, v=NO_DET, state="MEASURED",
                            reason=f"D1 {v} without verified passage evidence ({bad}): not honoured")
        if crit == "Ldgr.source_presence" and v in (PASS, PARTIAL):
            # S3: a DECLARED source reads PASS/PARTIAL only on a citation_state that is sourced / sourced_ocr_unverified (E5.1 / E6.3 rule, as Carr.D1):
            # unsourced / refuted / unknown is never a source-correspondence PASS, and a declared record without its state is not honoured. An UNDECLARED
            # asset's legacy presence count carries no state and reads as before.
            cs = meas.get("citation_state")
            if (cs is None and meas.get("declared") is True) or (cs is not None and cs not in CITATION_STATES):
                return dict(criterion=crit, v=NO_DET, state="MEASURED",
                            reason=f"{v} with citation_state {cs!r}: a declared source carries one of {list(CITATION_STATES)}; not honoured")
            if cs in CITATION_CAPPED_STATES:
                return dict(criterion=crit, v=NO_DET, state="MEASURED", citation_state=cs,
                            reason=f"{v} with citation_state {cs!r}: a source that is {cs} is never a PASS (the column is populated, the claim is not sourced)")
        if v in (PASS, PARTIAL) and e["detector"] == "NONE":
            # E6 item i review: a check with no detector earns no graded verdict above FAIL — PARTIAL is clamped like
            # PASS (with Carr.detector gone, a measured PARTIAL on D1-D3 would otherwise have made Carr PARTIAL).
            return dict(criterion=crit, v=NO_DET, state="MEASURED",
                        reason=f"detector NONE never reaches {v}")
        if crit == "Carr.D3" and v in (PASS, PARTIAL):
            # C1-3: a D3 verdict is honoured ONLY with its evidence (population digest, independence class, declared conventions) and a PASS only when its own fields show every
            # logical row re-derived by an independent formula under the declared row count (carriage_d3.d3_evidence_problem).
            bad = _carriage_d3().d3_evidence_problem(meas)
            if bad:
                return dict(criterion=crit, v=NO_DET, state="MEASURED",
                            reason=f"D3 {v} without re-derivation evidence ({bad}): not honoured")
        # E6 packet (c): the rollup does not trust a record's own verdict where the claim cannot be established
        # (INCONCLUSIVE is a state: nothing was measured), and the two capped checks cannot read PASS (SS: Null "never
        # PASS alone"; Narr.fidelity_test structural only)
        infl = bool(meas.get("inconclusive"))
        if infl and v in (PASS, PARTIAL):
            return dict(criterion=crit, v=NO_DET, state="MEASURED", inconclusive=True,
                        reason="INCONCLUSIVE record: nothing was established, so it cannot read PASS or PARTIAL")
        if v == PASS and crit.startswith("Null.") and not _convention_lift_earned(crit, meas, all_meas) and writer_scan_earned(crit, meas, all_meas, facts):
            # E5.7 (SS N-150 R7): the cap LIFTS by the static writer scan: both Null records carry the verified writer_scan block (every write path to every declared prose column found,
            # no literal fallback, no constant write, nothing unresolved), no INCONCLUSIVE, no basis, over the asset's declared prose_fields.
            return dict(criterion=crit, v=PASS, state="MEASURED", null_writer_scan_verified=True,
                        reason="measured; PASS earned: schema_default and blank_rows are clean and the writer's source writes no literal fallback or constant to the declared prose columns")
        if v == PASS and crit == "Narr.fidelity_test" and fidelity_pass_earned(meas, facts):
            return dict(criterion=crit, v=PASS, state="MEASURED", fidelity_golden_verified=True,
                        reason="measured; PASS earned: every declared prose entry is covered by a verified golden-value test (built output asserted equal to an independent literal sentence)")
        if v == PASS and crit.startswith("Null.") and _convention_lift_earned(crit, meas, all_meas):
            # S1 (pin 13): the cap LIFTS for this asset only. Both Null checks carry the verified null_convention block (declared, evidence and reason
            # echoed, both siblings clean, the detector's verdict PASS), no INCONCLUSIVE, no basis. Anything else falls through to the cap below.
            return dict(criterion=crit, v=PASS, state="MEASURED", null_convention_verified=True,
                        reason="measured; PASS earned: schema_default and blank_rows are clean and the asset's declared null convention is verified")
        if v == PASS and crit.startswith("Null.") and forwarded_leaves_earned(crit, meas, all_meas, facts):
            # N-189 (SS): the cap LIFTS by the forwarded-leaf detector: both Null records carry the verified forwarded_leaves block (the forwarded L1 leaves equal the cited L1 facts on the measured chart's rows,
            # every cited fact_id resolves, the writer scan's only findings are the covered empty-string fallbacks / dynamic-row caveat), no INCONCLUSIVE, no basis, over the asset's declared prose_fields.
            return dict(criterion=crit, v=PASS, state="MEASURED", null_forwarded_leaves_verified=True,
                        reason="measured; PASS earned: schema_default and blank_rows are clean and the forwarded L1 leaves equal their cited L1 facts on the measured chart (forwarded-leaf detector, N-189)")
        if v == PASS and (crit.startswith("Null.") or crit == "Narr.fidelity_test"):
            return dict(criterion=crit, v=PARTIAL, state="MEASURED",
                        reason=f"{crit} is capped at PARTIAL (Null: never PASS alone; fidelity_test: structural only)")
        basis = meas.get("basis")
        if basis is not None and basis != "declaration":      # case-exact: 'Declaration' is not 'declaration'
            return dict(criterion=crit, v=NO_DET, state="MEASURED",
                        reason=f"unrecognised basis {basis!r} (the only defined basis is 'declaration', case-exact): "
                               "the verdict is not honoured")
        if v == PASS and basis == "declaration":
            return dict(criterion=crit, v=v, state="MEASURED", basis="declaration",
                        reason="PASS by declaration, not measured: no measurement stands behind this verdict")
        if v == FAIL and meas.get("transitive_only") is True:
            return dict(criterion=crit, v=v, state="MEASURED",
                        reason="measured; transitive_only: every missing edge is already reachable through a declared "
                               "dependency (ordering holds, the edge is undeclared)", **(dict(inconclusive=True) if infl else {}))
        return dict(criterion=crit, v=v, state="MEASURED", reason="measured", **(dict(inconclusive=True) if infl else {}),
                    # a D1 verdict says WHICH citation state it stands on (a sourced_ocr_unverified PASS is marked as such on the cell)
                    **({"citation_state": meas["citation_state"]} if crit in ("Carr.D1", "Ldgr.source_presence") and meas.get("citation_state") else {}))
    st = ap["state"]
    if st == "OUT_OF_LAYER":
        return None
    if st == "NOT_APPLICABLE":
        rid = ap["rule_id"]
        if rid in NA_RULE_DECISIONS:
            return dict(criterion=crit, v=NA, state=st, rule_id=rid, decision=NA_RULE_DECISIONS[rid], reason=ap["reason"])
        return dict(criterion=crit, v=NO_DET, state=st, rule_id=rid,
                    reason=f"N/A rule undecided (N-22): {ap['reason']}")
    return dict(criterion=crit, v=NO_DET, state=st, reason=f"not measured ({ap['reason']})")


def rollup_asset(layer: str, measurements: dict, facts: dict | None = None) -> dict:
    """E6.2: the nine gate cells for one asset. `measurements` is the census's per-asset
    `measurements` dict; `facts` optionally supplies `columns` and `asset_kind`. A registered criterion
    with no measurement still counts (NO_DETECTOR) unless it is out of layer or an N/A rule declared in
    NA_RULE_DECISIONS disproves it — absence is never N/A. Raises KeyError for a layer or measured
    criterion not registered, ValueError for a measurement outside its declared layers or verdict set.
    A measurement of a RETIRED criterion (a census saved before the retirement) is ignored here — it is graded
    nowhere and moves no cell (E6 item i; rollup_excluded reports it)."""
    if layer not in LAYERS:
        raise KeyError(f"unknown layer {layer!r}")
    for crit in measurements:
        if crit not in CRITERION_REGISTRY and crit not in RETIRED_CRITERIA:
            raise KeyError(f"measured criterion {crit!r} is not in CRITERION_REGISTRY")
    validate_na_rule_decisions()
    fp = registry_fingerprint()
    cells = {}
    for gate in CELL_GATES:
        checks = []
        for crit, e in CRITERION_REGISTRY.items():
            if e["gate"] != gate:
                continue
            c = _check_contribution(crit, layer, measurements.get(crit), facts, measurements)
            if c is not None:
                checks.append(c)
        cells[gate] = dict(gate=gate, v=rollup_verdicts([c["v"] for c in checks]), checks=checks,
                           registry_revision=REGISTRY_REVISION, registry_fingerprint=fp)
        declared = [c["criterion"] for c in checks if c.get("basis") == "declaration"]
        if declared:                  # a cell that rests on a declaration says so (key absent otherwise: no other cell changes)
            cells[gate]["declared_checks"] = declared
    return cells


def rollup_excluded(layer: str, measurements: dict) -> dict:
    """Measured criteria whose gate is not one of the nine cell gates: reported here, never silently
    dropped (their owner decision is a campaign question, not a rollup choice). A measured RETIRED criterion
    (a census saved before its retirement) is reported here too, with its verdict as saved: it is not graded,
    and it is not dropped either.

    N/A obeys the SAME release rule as the cells (`_na_released`: a registered cause AND its declared rule id, N-22
    principle 2): a measured N/A that no declared rule releases is reported as NO_DETECTOR, never as N/A. Every other
    verdict is reported as measured."""
    return {c: (NO_DET if mv["v"] == NA and not _na_released(c, mv) else mv["v"]) for c, mv in measurements.items()
            if c in RETIRED_CRITERIA
            or (c in CRITERION_REGISTRY and CRITERION_REGISTRY[c]["gate"] not in CELL_GATES)}


def rollup_census(census_layer: dict, facts_by_asset: dict | None = None) -> dict:
    """E6.2 over one measured layer (`measure()` output): asset_id -> nine gate cells. Read-only."""
    layer = census_layer.get("layer")
    if layer is None:
        layer = census_layer["assets"][0]["layer"]
    return {a["asset_id"]: rollup_asset(layer, a["measurements"], (facts_by_asset or {}).get(a["asset_id"]))
            for a in census_layer["assets"]}


# E6.1 packet 2a: the per-asset FACTS the rollup's applicability rules read, emitted by measure() and turned into
# the `facts` mapping by facts_for_asset(). "Could not be established" (no target table, table absent from the
# catalog, no column rows for an existing relation, blank asset_kind) is None, i.e. JSON null: an empty list never
# stands for unknown, and no string marker exists that could be read as a value (and a disproving one at that).


def _target_columns_fact(tbl: str | None, cat: dict):
    """The target table's column names as a sorted list, or None (unknown). Known only when the table is in the
    catalog's `exists` AND the catalog returned column rows for it (a materialized view is in `exists` but
    information_schema lists none: incomplete introspection is unknown, not 'zero columns')."""
    if not tbl or tbl not in cat.get("exists", ()):
        return None
    cols = cat.get("cols", {}).get(tbl)
    if not isinstance(cols, list) or not cols or not all(isinstance(c, str) and c for c in cols):
        return None
    return sorted(cols)


# E6.1 declarations packet: the per-asset DECLARED facts (N-22 ruling; SS decisions 2026-09-30). ONE versioned
# repository file, reviewed in PRs, read here; no migration, the registry CHECK is untouched. A declaration is a FACT
# and only a fact: nothing in this block makes a gate N/A, changes a criterion, or changes a verdict (rules key on
# causes, a later packet). An asset absent from the file, and a null field, are UNKNOWN: never a value.

DECLARATIONS_PATH = Path(__file__).resolve().parent / "asset_declarations.json"
DECLARED_KINDS = ("data", "service", "view", "static", "rider", "probe", "user_data")   # `multi-table` is a measured fact, not a kind
# `dag_dependents` is deliberately NOT a declared carriage field: who depends on an asset is MEASURED (the census
# blocking_radius), and a declared copy of a measurement is circular (every value was derived from it) and can only
# ever be wrong-or-redundant; it already was wrong for bg_gochara_arcs, whose real reader ka_gochara has no registry
# depends_on edge (a registry defect, recorded in the evidence file, not a declaration). Nothing overrides the radius.
CARRIAGE_FIELDS = ("served_surface",)
# E6 S2 (SS N-72 S2, N-73): the `carriage` object also holds the asset's DECLARED CARRIAGE CHECK (declaration-keyed, reviewed):
# ONE of D1/D2/D3 applies, chosen by the asset's NATURE, never by the caller of a rule: transcription of cited classical content
# -> D1 (match to a cited source; N-73 (2)), computation -> D3 (re-derivation), derivation from another asset's stored facts ->
# D3 (SS N-101 (a), C1-1: D2 is WITNESS carriage, "two independent witnesses of the same fact", as the registry and the menu define it; a
# derivation is re-derived, it is not witnessed; no nature maps to D2 until a witness adopter exists, C1-7). The validator REFUSES a mismatch. The other two checks read N/A by the cause `not-the-declared-carriage`. A ratified
# judgment seed (L0 Q13) declares nature `ratified_judgment` with a `ruling` id and no `applies`: all three read N/A by
# `ratified_judgment`. An asset with no such declaration reads exactly as before.
CARRIAGE_DECL_FIELDS = ("applies", "nature", "why", "evidence", "spec", "citation_state", "ruling", "per_witness_values")
# N-156 (SS, the declared ceiling): two more natures, each a DECLARED ceiling that releases ITS check to N/A by a declaration-keyed cause (never a column pattern, never the caller):
#   single_derivation        applies D3: the asset computes a value with no independent second route; verified by integrity checks and internal consistency (the `single` tier's honesty).
#                            Refused for an asset a reviewed D3 method serves (carriage_d3 METHODS `assets`): where a second route exists the check is MEASURED, not waived.
#   unverified_transcription applies D1: hand-typed or corpus-absent content with no passage-level spec: the transcription is not verified against a passage.
# and `per_witness_values: false` (any declared nature): the asset stores no per-witness values, so Carr.D2 reads N/A `no-per-witness-values` (supersedes N-118 "D2 required").
# and (N-156 C8) `not_a_transcription` (applies D1): the asset's SOURCE is a ratification (K2) or a derivation (K3), not a classical passage, so Carr.D1 reads N/A `not-a-transcription`: a plain N/A,
# NOT a ceiling. It is declaration-keyed AND checked: the asset's `source` declaration must exist and name only K2 / K3 / LEDGER kinds (`source_kinds`), at validation and at measure time; and
# `unverified_transcription` is refused where the source declaration is K2 / K3 only (that label is for K1 classical citations).
CARRIAGE_NATURE_CHECK = {"transcription": "D1", "computation": "D3", "derivation": "D3", "single_derivation": "D3", "unverified_transcription": "D1", "not_a_transcription": "D1"}
CEILING_NATURES = ("single_derivation", "unverified_transcription")
NOT_A_TRANSCRIPTION = "not_a_transcription"
NO_SPEC_NATURES = CEILING_NATURES + (NOT_A_TRANSCRIPTION,)     # ONE definition (C1-1, N-101 (a)): the validator, its message and the comments above read this
RATIFIED_JUDGMENT = "ratified_judgment"
CITATION_STATES = ("sourced", "sourced_ocr_unverified", "unsourced", "refuted")
CITATION_CAPPED_STATES = ("unsourced", "refuted")   # ONE cap for Carr.D1 (carriage_d1) and Ldgr.source_presence (grade_ldgr_source, _check_contribution), and nikasha CITATION_PASS_REFUSED
# N-177 (SS 2026-10-07): the CLOSED LIST of honest residual labels of Ldgr.source_presence. A residual is a named, declared, CHECKED way for a cell to read "no traceable source" without a FAIL: the cell
# reads N/A under the ruled cause below (the repo's CEILING convention, as the two Carr ceilings: a ruled N/A that certifies the asset AT a ceiling and prints on its CERTIFIED_LIST line), never PASS, never a silent
# N/A. UNSOURCED_DECLARED: the asset's declared source reading finds rows with no traceable source AND the asset DECLARES the label (`source.residual`) with its why / evidence; the detector checks the
# rows really lack one (an asset whose rows DO carry a source reads as measured, the declaration contradicted). `census_postprocess.CEILING_RULES` carries the printed label (a test pins the two together).
UNSOURCED_DECLARED = "UNSOURCED_DECLARED"
LDGR_RESIDUALS = (UNSOURCED_DECLARED,)
LDGR_RESIDUAL_CAUSE = {UNSOURCED_DECLARED: "unsourced-declared"}
LDGR_RESIDUAL_CEILING = {UNSOURCED_DECLARED: "Ldgr: unsourced (declared)"}
_RULING_ID = re.compile(r"N-[0-9]{1,6}[A-Za-z0-9._-]{0,24}")
_CARR_D1_MOD: list = []


def _carriage_d1():
    """The generic D1 engine (carriage_d1.py, a pure sibling module), loaded by file path once."""
    if not _CARR_D1_MOD:
        import importlib.util
        p = Path(__file__).resolve().parent / "carriage_d1.py"
        spec = importlib.util.spec_from_file_location("carriage_d1_for_census", p)
        mod = importlib.util.module_from_spec(spec)
        sys.modules.setdefault("carriage_d1_for_census", mod)
        spec.loader.exec_module(mod)
        _CARR_D1_MOD.append(mod)
    return _CARR_D1_MOD[0]


_CARR_D3_MOD: list = []


def _carriage_d3():
    """The generic D3 engine (carriage_d3.py, a pure sibling module; its methods load from carriage_d3_methods.py), loaded by file path once."""
    if not _CARR_D3_MOD:
        import importlib.util
        p = Path(__file__).resolve().parent / "carriage_d3.py"
        spec = importlib.util.spec_from_file_location("carriage_d3_for_census", p)
        mod = importlib.util.module_from_spec(spec)
        sys.modules.setdefault("carriage_d3_for_census", mod)
        spec.loader.exec_module(mod)
        _CARR_D3_MOD.append(mod)
    return _CARR_D3_MOD[0]


def source_kinds(src) -> set:
    """The set of source kinds an asset's `source` declaration names: a table-level kind, or the union of every row-level entry's `kinds`; empty for an undeclared source or an na form."""
    if not isinstance(src, dict) or src.get("na") is not None:
        return set()
    if src.get("level") == "table":
        return {src["kind"]} if isinstance(src.get("kind"), str) else set()
    out = set()
    for c in src.get("columns") or []:
        if isinstance(c, dict):
            out |= {k for k in (c.get("kinds") or []) if isinstance(k, str)}
    return out


def not_a_transcription_problem(src):
    """None when the source declaration supports `not_a_transcription` (it names at least one kind and every kind is K2, K3 or LEDGER), else why not."""
    ks = source_kinds(src)
    if not ks:
        return "the asset's `source` declaration is absent or names no kind: not_a_transcription is checked against it, never declared alone"
    if ks - {"K2", "K3", "LEDGER"}:
        return f"the asset's source declaration names {sorted(ks)}: a K1 classical citation makes it a (possibly unverified) transcription, not a ratification or derivation"
    return None


def _carriage_d3_served_assets() -> dict:
    """{asset id: method id} for every asset a reviewed D3 method serves (carriage_d3 METHODS `assets`): such an asset cannot declare single_derivation."""
    out = {}
    if not (Path(__file__).resolve().parent / "carriage_d3.py").is_file():
        return out                      # a tree without the D3 engine (the T1 fixture tree copies only the D1 runtime files) has no reviewed D3 method, so no served asset
    for mid, meth in _carriage_d3().load_methods().items():       # the loop variable is not named m: test_r78 reads every m-subscript as a measurement key
        for a in meth["assets"]:
            out[a] = mid
    return out


def _evidence_pointer_ok(ev) -> bool:
    """A declared evidence pointer is `unverified:<where>` or a repo-relative FILE (optionally `:line`) that exists. The resolved
    path must stay inside the repository: a symlink (or `..`) that leads out of it is not evidence."""
    if not (isinstance(ev, str) and ev.strip()):
        return False
    if ev.startswith("unverified:"):
        return bool(ev[len("unverified:"):].strip())
    rel = re.sub(r":[0-9]+$", "", ev)
    if rel.startswith("/") or ".." in rel.split("/"):
        return False
    try:
        root = ROOT.resolve()
        p = (ROOT / rel).resolve()
        return p.is_file() and (p == root or root in p.parents)
    except (OSError, ValueError):
        return False


def _carriage_pointer_strict(label: str, ev) -> None:
    """The S3 pointer rules for a carriage spec's evidence pointers (effect_clauses_evidence, condition_evidence, an escape hatch's, a repair's): no control / invisible character, a
    `:LINE` inside the file, an `unverified:` pointer states a real description. They are not N/A releases (the carriage's own `evidence` is), so `unverified:` stays allowed."""
    bad = _s3_evidence_problem(ev, allow_unverified=True)
    if bad:
        raise DeclarationsError(f"{label} {ev!r} {bad}")


def validate_carriage_declaration(where: str, car: dict, e: dict) -> None:
    """Raises DeclarationsError when the asset's declared carriage CHECK is malformed or contradicts N-73's nature rule."""
    nature = car.get("nature")
    allowed = list(CARRIAGE_NATURE_CHECK) + [RATIFIED_JUDGMENT]
    if nature not in allowed:
        raise DeclarationsError(f"{where}.carriage.nature must be one of {allowed}, got {nature!r}")
    _aid = (re.match(r"assets\['([^']+)'\]", where) or [None, None])[1]
    _served = _carriage_d3_served_assets()
    if _aid in _served and (nature == RATIFIED_JUDGMENT or CARRIAGE_NATURE_CHECK.get(nature) != "D3" or nature in CEILING_NATURES):
        raise DeclarationsError(f"{where}.carriage: nature {nature!r} is refused for {_aid!r}: the reviewed D3 method {_served[_aid]!r} serves it, so its D3 check is MEASURED (nature computation / derivation "
                                "with a spec), never released as an N/A by another nature (N-156 review MED-1)")
    for f in ("why", "evidence"):
        v = car.get(f)
        if not (isinstance(v, str) and v.strip() and "\n" not in v and len(v) <= 1200):
            raise DeclarationsError(f"{where}.carriage.{f} must be a non-blank single-line string (a reason / a pointer file:line or document)")
    if not _evidence_pointer_ok(car["evidence"]):
        raise DeclarationsError(f"{where}.carriage.evidence {car['evidence']!r} is not an existing repo-relative file (optionally with :line); a "
                                f"pointer that cannot be checked must say so: 'unverified:<where it is recorded>'")
    # E6.1 follow-up (S2 strictness, matching S3's `_s3_common`): the same text and pointer rules as vocab_alias / ldgr_source. `why` is a real one-line statement (no control or
    # invisible character, at least 15 characters and 3 words, no placeholder word anywhere, except that a D1 / D2 / D3 sentence may mention `null` / `none`, as the latta's does; a ratified_judgment, which releases N/A, may not); `evidence` has no control character, a `:LINE` inside the file, and an `unverified:` pointer states
    # a real description (10 characters, 2 words). A ratified_judgment carriage RELEASES Carr.D1-D3 to N/A, so (as an S3 N/A release) it may not rest on an `unverified:` pointer.
    bad = _s3_text_problem(car["why"], min_chars=15, min_words=3, placeholder="any" if nature == RATIFIED_JUDGMENT else "prose")
    if bad:
        raise DeclarationsError(f"{where}.carriage.why {bad}")
    bad = _s3_evidence_problem(car["evidence"], allow_unverified=nature != RATIFIED_JUDGMENT and nature not in NO_SPEC_NATURES)      # an N/A release rests on a real file:line
    if bad:
        raise DeclarationsError(f"{where}.carriage.evidence {car['evidence']!r} {bad}")
    if car.get("per_witness_values") is not None and car["per_witness_values"] is not False:
        raise DeclarationsError(f"{where}.carriage.per_witness_values may only be declared false (the asset stores no per-witness values: Carr.D2 reads N/A, N-156); an asset that stores them has no D2 detector yet")
    if isinstance(e.get("terminal_by_construction"), str) and e["terminal_by_construction"].strip():
        raise DeclarationsError(f"{where}: a declared carriage check and terminal_by_construction contradict each other (an asset that "
                                f"declares a carriage check carries something from a source; declare one or the other)")
    if nature == RATIFIED_JUDGMENT:
        if car.get("applies") is not None or car.get("spec") is not None:
            raise DeclarationsError(f"{where}.carriage: nature ratified_judgment declares no check (`applies`/`spec` must be absent)")
        if not (isinstance(car.get("ruling"), str) and _RULING_ID.fullmatch(car["ruling"])):
            raise DeclarationsError(f"{where}.carriage.ruling must be the ruling id (N-<number>) that ratified the judgment")
        if car.get("citation_state") is not None:
            raise DeclarationsError(f"{where}.carriage: citation_state is for a transcription, not a ratified judgment")
        return
    want = CARRIAGE_NATURE_CHECK[nature]
    if car.get("applies") != want:
        raise DeclarationsError(f"{where}.carriage: nature {nature!r} requires applies {want!r} (N-73 / N-101 (a): transcription -> D1 match to a "
                                f"cited source; computation -> D3 re-derivation; derivation from another asset's stored facts -> D3; D2 is witness "
                                f"carriage and no nature maps to it yet), got {car.get('applies')!r}")
    if car.get("ruling") is not None:
        raise DeclarationsError(f"{where}.carriage.ruling is only for nature ratified_judgment")
    cs = car.get("citation_state")
    if nature == "transcription":
        if cs not in CITATION_STATES:
            raise DeclarationsError(f"{where}.carriage.citation_state must be one of {list(CITATION_STATES)} for a transcription, got {cs!r}")
    elif nature in ("unverified_transcription", NOT_A_TRANSCRIPTION):
        if nature == NOT_A_TRANSCRIPTION and cs is not None:
            raise DeclarationsError(f"{where}.carriage.citation_state is not declared for not_a_transcription (the source is not a citation)")
        if cs is not None and cs not in CITATION_STATES:
            raise DeclarationsError(f"{where}.carriage.citation_state must be one of {list(CITATION_STATES)} (or absent) for an unverified transcription, got {cs!r}")
    elif cs is not None:
        raise DeclarationsError(f"{where}.carriage.citation_state is only declared for nature transcription / unverified_transcription")
    if nature == "unverified_transcription" and source_kinds(e.get("source")) and not (source_kinds(e.get("source")) - {"K2", "K3", "LEDGER"}):
        raise DeclarationsError(f"{where}.carriage: nature unverified_transcription is refused: the source declaration names only {sorted(source_kinds(e.get('source')))} (a ratification or "
                                "derivation, not a classical passage): declare not_a_transcription (N-156 C8)")
    if nature == "unverified_transcription" and "K1" not in source_kinds(e.get("source")):
        raise DeclarationsError(f"{where}.carriage: nature unverified_transcription needs a `source` declaration that names K1 (a classical citation): an asset with no declared source, or one whose source is "
                                "not_built / no_data, has nothing to be an unverified transcription OF (declare the source first; N-156 review LOW-6)")
    if nature == NOT_A_TRANSCRIPTION:
        bad = not_a_transcription_problem(e.get("source"))
        if bad:
            raise DeclarationsError(f"{where}.carriage: nature not_a_transcription: {bad}")
    if nature in NO_SPEC_NATURES:
        if car.get("spec") is not None:
            raise DeclarationsError(f"{where}.carriage: nature {nature} is a declared ceiling and carries no `spec` (a spec means the check is MEASURED: declare transcription / computation instead)" if nature in CEILING_NATURES else f"{where}.carriage: nature {nature} carries no `spec`")
        if nature == "single_derivation":
            aid = (re.match(r"assets\['([^']+)'\]", where) or [None, None])[1]
            served = _carriage_d3_served_assets()
            if aid in served:
                raise DeclarationsError(f"{where}.carriage: nature single_derivation is refused for {aid!r}: the reviewed D3 method {served[aid]!r} serves it, so its second route exists and the check is measured, not waived (N-156)")
        return
    spec = car.get("spec")
    if spec is not None and want == "D3":
        d3m = _carriage_d3()
        try:
            d3m.validate_spec(spec, f"{where}.carriage", asset_id=(re.match(r"assets\['([^']+)'\]", where) or [None, None])[1])
        except ValueError as exc:
            raise DeclarationsError(str(exc)) from exc
        ptrs = [(f"{where}.carriage.spec.conventions[{k}].evidence", v["evidence"]) for k, v in spec["conventions"].items()]
        ptrs += [(f"{where}.carriage.spec.uncovered[{u['column']}].evidence", u["evidence"]) for u in spec["uncovered"]]
        if "recorded" in spec:
            ptrs += [(f"{where}.carriage.spec.recorded.{k}", spec["recorded"][k]) for k in ("writer_digest_file", "binds")]
        for label, ev in ptrs:
            if not _evidence_pointer_ok(ev):
                raise DeclarationsError(f"{label} {ev!r} is not an existing repo-relative file (optionally :line) or 'unverified:<where>'")
            _carriage_pointer_strict(label, ev)
        return
    if spec is not None:
        if want != "D1":
            raise DeclarationsError(f"{where}.carriage.spec is only defined for applies D1 and D3")
        try:
            _carriage_d1().validate_spec(spec, f"{where}.carriage")
        except ValueError as exc:
            raise DeclarationsError(str(exc)) from exc
        d1m = _carriage_d1()
        for label, ev, suffix in d1m._kernel_of(spec)["evidence_pointers"](spec, f"{where}.carriage.spec"):      # the kernel names its own evidence pointers
            if not _evidence_pointer_ok(ev):
                raise DeclarationsError(f"{label} {ev!r} is not an existing repo-relative file (optionally :line) or 'unverified:<where>'{suffix}")
            _carriage_pointer_strict(label, ev)
        for x in spec.get("non_claim_columns", []):       # C1-1 column ledger: each declared non-claim needs a real one-line `why` (S3 rules), a real file:line pointer, and must NAME its column
            lab = f"{where}.carriage.spec.non_claim_columns[{x['column']}]"
            bad = _s3_text_problem(x["why"], min_chars=15, min_words=3)
            if bad:
                raise DeclarationsError(f"{lab}.why {bad}")
            bad = _s3_evidence_problem(x["evidence"], allow_unverified=False)
            if bad:
                raise DeclarationsError(f"{lab}.evidence {x['evidence']!r} {bad}")
            bad = _non_claim_names_column_problem(x)
            if bad:
                raise DeclarationsError(f"{lab}: {bad}")


def _non_claim_names_column_problem(x: dict):
    """None when a declared non-claim names its column as a whole token (case-insensitive) in its `why` OR in the evidence line it points at (so a generic reason with an unrelated
    pointer cannot declare a prophecy column a label), else why not. `evidence` is `path:line` (the line must exist: `_s3_evidence_problem` ran first) or a bare existing file."""
    tok = re.compile(r"(?<![A-Za-z0-9_])" + re.escape(x["column"]) + r"(?![A-Za-z0-9_])", re.IGNORECASE)
    if tok.search(x["why"]):
        return None
    m = re.fullmatch(r"(.+):([0-9]+)", x["evidence"])
    line = ""
    if m:
        try:
            line = (ROOT / m.group(1)).read_text(encoding="utf-8").splitlines()[int(m.group(2)) - 1]
        except (OSError, UnicodeDecodeError, IndexError):
            line = ""
    if tok.search(line):
        return None
    return (f"neither the `why` nor the evidence line {x['evidence']!r} names the column {x['column']!r} (whole token, case-insensitive): a non-claim must say which column it is "
            "about and point at where that column is written")


# E6 S3 (SS N-72 S3, N-73 (1)/(4), N-74 (b)): two more per-asset DECLARATIONS, each reviewed and carrying evidence and ONE line of reason. `vocab_alias`
# declares the asset's alias class (measured against bg_ontology) or that it has none (`no_alias_class`); `ldgr_source` names the column that carries
# the asset's classical source and the citation_state it stands on, or declares that the asset states no classical rule or cited fact
# (`no_classical_claim`). N/A is reached ONLY through these words, never from a column pattern (A5). N-73 (4): `no_alias_class` may not be declared
# where a documented alias exists. N-73 (1): a source-status disclosure is not a source.
# Earn.service_state (E5.7, criterion revision 2): a service asset DECLARES the probe it is read against, `service_probe: {probe_type, max_age_hours, why, evidence}`. The probe's own result is what the
# registry recorded when the engine ran it (`service_health`, `last_selftest_at`, `health_probe.probe_type`); the declaration only names WHICH probe and HOW FRESH, it never states a verdict.
SERVICE_PROBE_DECL_FIELDS = ("probe_type", "max_age_hours", "why", "evidence")
SERVICE_MAX_AGE_HOURS_CAP = 24 * 366
NO_ALIAS_CLASS = "no_alias_class"
NO_CLASSICAL_CLAIM = "no_classical_claim"
ALIAS_CLASSES = ("planet",)                       # the bg_ontology entity classes an alias is measured against (widening is a registry revision)
ONTOLOGY_TABLE = "brahma_ontology"                # bg_ontology's target table
VOCAB_ALIAS_DECL_FIELDS = ("na", "class", "vocab_column", "alias_column", "identity_only", "identity_only_why", "why", "evidence")
LDGR_SOURCE_DECL_FIELDS = ("na", "source_column", "citation_state", "why", "evidence")
# columns that carry (or look like they carry) an asset's own alias set: a measured `vocab_alias` that declares no alias_column beside one is contradicted
ALIAS_LIKE_TOKENS = ("synonym", "alias", "alt_name", "alternate_name", "other_name", "also_known", "nickname", "name_variant")
ALIAS_LIKE_EXACT = ("aka",)


def alias_like_columns(cols) -> list:
    """The columns of `cols` that carry (or look like they carry) an asset's own alias set: a case-insensitive match on any of ALIAS_LIKE_TOKENS or exactly `aka`.
    A measured `vocab_alias` that declares no alias_column beside one is contradicted, and `no_alias_class` may not be declared beside one (N-73 (4))."""
    return [c for c in (cols or ()) if isinstance(c, str) and (c.casefold() in ALIAS_LIKE_EXACT or any(t in c.casefold() for t in ALIAS_LIKE_TOKENS))]
# N-150 R3: columns that hold a vocabulary term the registry's OWN ontology (bg_ontology, ALIAS_CLASSES) aliases: a table that carries one may not read `no_alias_class` N/A (the alias class
# must be measured). A closed name list: widening it is a registry revision. Case-insensitive.
ALIAS_VOCAB_COLUMNS = ("graha", "grahas", "planet", "planet_name", "other_graha", "star_lord", "sub_lord", "lord")


def alias_vocab_columns(cols) -> list:
    """The columns of `cols` that hold a planet-vocabulary term bg_ontology aliases (ALIAS_VOCAB_COLUMNS, case-insensitive)."""
    return [c for c in (cols or ()) if isinstance(c, str) and c.casefold() in ALIAS_VOCAB_COLUMNS]


_DECL_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,127}")
# S3 declaration quality (adversarial review M5): a reason / evidence text that cannot be a real one is refused for the new keys only (S2's carriage validator is unchanged)
_S3_PLACEHOLDER_WORDS = frozenset({"tbd", "todo", "tba", "fixme", "xxx", "placeholder", "unknown", "none", "null", "na", "n/a", "n.a", "nil", "lorem", "ipsum", "etc", "pending"})
_S3_WORD = re.compile(r"[^\W_]+(?:[./'-][^\W_]+)*")


_PROSE_MAY_MENTION = frozenset({"null", "none"})      # the only placeholder words a carriage `why` sentence may mention (the committed latta why says "content_sa is NULL")


def _s3_text_problem(v, *, min_chars: int, min_words: int, placeholder: str = "any"):
    """None when `v` is a real one-line text: a str with no control / format / line-separator character (\\r, \\n, U+0085, U+2028/9, zero-width ...), at least
    `min_chars` characters and `min_words` words once trimmed, and no placeholder word (TBD, todo, N/A ...); else why it is not.
    `placeholder="any"` (S3's rule) refuses a placeholder word ANYWHERE. `placeholder="prose"` (the carriage `why` of a D1 / D2 / D3 check, E6.1 follow-up) is for a long explanatory
    sentence that may legitimately MENTION the words `null` and `none` ("content_sa is NULL", "none of the rows has an effect clause"): ONLY those two are exempt; every other placeholder
    word (tbd, todo, tba, fixme, xxx, placeholder, pending, n/a, unknown, nil, ...) is still refused anywhere, and the statement needs at least `min_words` REAL words (a word that is no
    placeholder word at all: 'see tbd tbd tbd' and 'none none none none' have fewer than three). A ratified_judgment `why` (it releases Carr.D1-D3 to N/A) uses "any"."""
    if not isinstance(v, str):
        return "is not a string"
    if v != v.strip():
        return "has leading or trailing whitespace"
    if any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in v):
        return "contains a control, line-separator or invisible character (it must be one visible line)"
    if len(v) > 1200:
        return "is longer than 1200 characters"
    words = _S3_WORD.findall(v)
    if len(v) < min_chars or len(words) < min_words:
        return f"is too short to be a real statement (need at least {min_chars} characters and {min_words} words)"
    if placeholder == "prose":
        bad = [w for w in words if w.casefold() in _S3_PLACEHOLDER_WORDS and w.casefold() not in _PROSE_MAY_MENTION]
        if bad:
            return f"contains a placeholder word ({bad[0]!r}: TBD / todo / pending / unknown / n/a ... are refused anywhere; only null / none may be mentioned in a sentence)"
        if sum(1 for w in words if w.casefold() not in _S3_PLACEHOLDER_WORDS) < min_words:
            return f"is mostly placeholder words (need at least {min_words} words that are none of: null, none, tbd, todo, ...)"
        return None
    if any(w.casefold() in _S3_PLACEHOLDER_WORDS for w in words):
        return "contains a placeholder word (TBD / todo / placeholder / n/a ...)"
    return None


def _s3_evidence_problem(ev, *, allow_unverified: bool, needle=None):
    """None when `ev` is acceptable evidence for an S3 declaration: an existing repo-relative file whose optional `:LINE` is within the file's real
    line count, or `unverified:<a real description, >= 10 characters and 2 words>` when `allow_unverified` (never for an N/A release)."""
    if not isinstance(ev, str) or not ev.strip():
        return "is not a non-blank string"
    if ev.startswith("unverified:"):
        if not allow_unverified:
            return "may not be `unverified:` for an N/A release: a declaration that releases a check must point at a real file the reviewer read"
        bad = _s3_text_problem(ev[len("unverified:"):], min_chars=10, min_words=2)
        return None if bad is None else f"`unverified:` text {bad}"
    if any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in ev):
        return "contains a control or invisible character"
    if not _evidence_pointer_ok(ev):
        return "is not an existing repo-relative file (optionally with :line)"
    m = re.search(r":([0-9]+)$", ev)
    if m:
        try:
            n = len((ROOT / ev[:m.start()]).read_bytes().splitlines())
        except OSError:
            return "is not readable"
        if not 1 <= int(m.group(1)) <= n:
            return f"names line {m.group(1)} but the file has {n} line(s)"
    if needle is not None:
        # DENS-TIER-GUARD (F3): an optional extra, default None = S3's behaviour unchanged. The cited FILE must mention `needle` (case-insensitive), so the pointer is about it.
        try:
            body = (ROOT / re.sub(r":[0-9]+$", "", ev)).read_text(encoding="utf-8", errors="replace")
        except OSError:
            return "is not readable"
        if str(needle).casefold() not in body.casefold():
            return f"is a real file but does not mention {needle!r}: the evidence must be about the column it supports"
    return None


def _s3_common(where: str, key: str, d: dict, allowed, *, na: bool) -> None:
    extra = sorted(set(d) - set(allowed))
    if extra:
        raise DeclarationsError(f"{where}.{key}: unknown field(s) {extra}")
    bad = _s3_text_problem(d.get("why"), min_chars=15, min_words=3)
    if bad:
        raise DeclarationsError(f"{where}.{key}.why {bad}")
    bad = _s3_evidence_problem(d.get("evidence"), allow_unverified=not na)
    if bad:
        raise DeclarationsError(f"{where}.{key}.evidence {d.get('evidence')!r} {bad}")


def _s3_ident(where: str, key: str, field: str, v) -> None:
    if not (isinstance(v, str) and _DECL_IDENT.fullmatch(v)):
        raise DeclarationsError(f"{where}.{key}.{field} must be a column name (an identifier), got {v!r}")


def validate_vocab_alias_declaration(where: str, va, e: dict) -> None:
    """Raises DeclarationsError when an asset's `vocab_alias` declaration is malformed. Exactly one of: `na: no_alias_class`, or a measured alias
    class (`class` in ALIAS_CLASSES, `vocab_column`, optional `alias_column`, optional `identity_only: true` + `identity_only_why`); both forms need
    `why` (a real one-line reason) and `evidence` (a checkable pointer; `unverified:` is refused for the N/A form). A measured declaration without
    `alias_column` reads at most PARTIAL (identity only) unless it states `identity_only` with its reason."""
    if not isinstance(va, dict):
        raise DeclarationsError(f"{where}.vocab_alias must be an object or null")
    _s3_common(where, "vocab_alias", va, VOCAB_ALIAS_DECL_FIELDS, na=va.get("na") is not None)
    na, cls = va.get("na"), va.get("class")
    measured = [f for f in ("class", "vocab_column", "alias_column", "identity_only", "identity_only_why") if va.get(f) is not None]
    if na is not None:
        if na != NO_ALIAS_CLASS:
            raise DeclarationsError(f"{where}.vocab_alias.na must be null or {NO_ALIAS_CLASS!r}, got {na!r}")
        if measured:
            raise DeclarationsError(f"{where}.vocab_alias: na {NO_ALIAS_CLASS!r} declares no alias class, so {measured} must be absent")
        return
    if cls not in ALIAS_CLASSES:
        raise DeclarationsError(f"{where}.vocab_alias must declare na {NO_ALIAS_CLASS!r} or a measured alias class (class one of "
                                f"{list(ALIAS_CLASSES)}), got class {cls!r}")
    _s3_ident(where, "vocab_alias", "vocab_column", va.get("vocab_column"))
    if va.get("alias_column") is not None:
        _s3_ident(where, "vocab_alias", "alias_column", va["alias_column"])
        if va["alias_column"] == va["vocab_column"]:
            raise DeclarationsError(f"{where}.vocab_alias.alias_column must differ from vocab_column")
    if va.get("identity_only") is not None:
        if va["identity_only"] is not True:
            raise DeclarationsError(f"{where}.vocab_alias.identity_only must be true or absent")
        if va.get("alias_column") is not None:
            raise DeclarationsError(f"{where}.vocab_alias: identity_only (no alias set carried) contradicts a declared alias_column")
        bad = _s3_text_problem(va.get("identity_only_why"), min_chars=15, min_words=3)
        if bad:
            raise DeclarationsError(f"{where}.vocab_alias.identity_only_why {bad} (identity_only must say why no alias set is carried)")
    elif va.get("identity_only_why") is not None:
        raise DeclarationsError(f"{where}.vocab_alias.identity_only_why is only for identity_only true")


def validate_ldgr_source_declaration(where: str, ls, e: dict) -> None:
    """Raises DeclarationsError when an asset's `ldgr_source` declaration is malformed. Exactly one of: `na: no_classical_claim` (the asset states no
    classical rule or cited fact; refused beside a transcription, derivation or ratified-judgment carriage declaration), or `source_column` +
    `citation_state` (one of CITATION_STATES); both forms need `why` (a real one-line reason) and `evidence` (a checkable pointer; `unverified:` is
    refused for the N/A form)."""
    if not isinstance(ls, dict):
        raise DeclarationsError(f"{where}.ldgr_source must be an object or null")
    _s3_common(where, "ldgr_source", ls, LDGR_SOURCE_DECL_FIELDS, na=ls.get("na") is not None)
    na = ls.get("na")
    if na is not None:
        if na != NO_CLASSICAL_CLAIM:
            raise DeclarationsError(f"{where}.ldgr_source.na must be null or {NO_CLASSICAL_CLAIM!r}, got {na!r}")
        if ls.get("source_column") is not None or ls.get("citation_state") is not None:
            raise DeclarationsError(f"{where}.ldgr_source: na {NO_CLASSICAL_CLAIM!r} declares no source, so source_column / citation_state must be absent")
        car = e.get("carriage")
        if isinstance(car, dict) and car.get("nature") in ("transcription", "derivation", "unverified_transcription", RATIFIED_JUDGMENT):
            raise DeclarationsError(f"{where}.ldgr_source: na {NO_CLASSICAL_CLAIM!r} contradicts a declared {car['nature']} carriage (the asset "
                                    f"transcribes, derives from, or ratifies classical content: only a computation can state no classical claim)")
        return
    _s3_ident(where, "ldgr_source", "source_column", ls.get("source_column"))
    if ls.get("citation_state") not in CITATION_STATES:
        raise DeclarationsError(f"{where}.ldgr_source.citation_state must be one of {list(CITATION_STATES)} with a source_column, got "
                                f"{ls.get('citation_state')!r}")


# NARR-GUARD (REGISTRY_REVISION 16, strategist ruling N-94). Narr measures GENERATED prose; an asset whose text columns are TRANSCRIPTION of a cited passage declares
# `prose_fields: []` (R03), and the claim a Narr check would measure (each stored string faithfully restates its passage clause) already has a real detector, Carr.D1.
# `prose_coupling` keeps the two honest: it names the text columns so classified, and the Narr N/A stands ONLY while the asset's own Carr.D1 reads PASS and its spec
# covers every one of them. The declaration CLASSIFIES; the guard VERIFIES the classified columns (the covered set is derived from the D1 spec, never from the declaration).
# Inert until an asset declares it: no declaration, no change in any cell.
PROSE_COUPLING_DECL_FIELDS = ("to", "columns", "why", "evidence")
PROSE_COUPLING_TO = "carriage_d1"
PROSE_COUPLING_MAX_COLUMNS = 16
_COUPLING_D1_WORD = re.compile(r"\bD1\b")


def prose_coupling_problem(entry, table_columns=None, column_types=None):
    """None when `entry` (an asset's declaration) has no `prose_coupling`, or has a sound one; else why it is refused. ONE definition: the validator
    (validate_prose_coupling_declaration) and the measure-time glue (prose_checks) both call it. Sound means: `to` is 'carriage_d1'; `columns` is a non-empty list of at most
    PROSE_COUPLING_MAX_COLUMNS distinct column identifiers; the entry declares prose_fields EXACTLY [] (a coupling only qualifies a []); the entry declares a transcription carriage
    that applies D1 with a spec; the `why` cites carriage transcription and D1; and EVERY listed column is covered by the D1 spec (carriage_d1.prose_coverage: derived from the spec).
    With `table_columns` / `column_types` (the measure-time catalog; None = not supplied) every listed column must also be a column of the table and of a text type."""
    if not isinstance(entry, dict) or entry.get("prose_coupling") is None:
        return None
    pc = entry["prose_coupling"]
    if not isinstance(pc, dict):
        return "prose_coupling must be an object"
    if pc.get("to") != PROSE_COUPLING_TO:
        return f"`to` must be {PROSE_COUPLING_TO!r} (the only detector a prose N/A can rest on), got {pc.get('to')!r}"
    cols = pc.get("columns")
    if not (isinstance(cols, list) and cols and len(cols) <= PROSE_COUPLING_MAX_COLUMNS
            and all(isinstance(c, str) and _DECL_IDENT.fullmatch(c) for c in cols) and len(set(cols)) == len(cols)):
        return (f"`columns` must be a non-empty list of at most {PROSE_COUPLING_MAX_COLUMNS} distinct column identifiers (the text columns classified as "
                f"transcription), got {cols!r}")
    pf = entry.get("prose_fields")
    if not (isinstance(pf, list) and pf == []):
        return f"a prose_coupling only qualifies a declared prose_fields [] (this asset declares prose_fields {pf!r})"
    why = pc.get("why")
    if not (isinstance(why, str) and "transcription" in why.casefold() and _COUPLING_D1_WORD.search(why)):
        return "`why` must cite carriage transcription and Carr.D1 (the words 'transcription' and 'D1'): the N/A rests on that detector, say so"
    car = entry.get("carriage")
    if not (isinstance(car, dict) and car.get("nature") == "transcription" and car.get("applies") == "D1"):
        return ("the asset must declare a carriage check of nature 'transcription' that applies 'D1': the coupling rests on Carr.D1, so there must "
                "be one (this asset's carriage declares "
                f"nature {car.get('nature') if isinstance(car, dict) else None!r}, applies {car.get('applies') if isinstance(car, dict) else None!r})")
    spec = car.get("spec")
    if not isinstance(spec, dict):
        return "the asset's D1 carriage declares no `spec`: nothing is matched against the passage, so no column is covered"
    try:
        cov = _carriage_d1().prose_coverage(spec)
        claim = set(spec["fields"].values())
        equals = {ef["column"] for ef in spec.get("extra_fields", []) if ef["kind"] == "equals"}
    except (KeyError, TypeError, AttributeError, ValueError) as exc:
        return f"the asset's D1 spec is malformed or ambiguous (the covered columns cannot be derived from it: {type(exc).__name__}: {exc})"
    for c in cols:
        if c in cov:
            continue
        if c in claim:
            return (f"column {c!r} is not covered by the D1 spec as prose: it is a claim field (claimant / count / direction), a structural value, not text matched "
                    "against a passage clause")
        if c in equals:
            return f"column {c!r} is not covered by the D1 spec as prose: it is checked only against a constant (kind equals), not against passage text"
        return (f"column {c!r} is not covered by the D1 spec: the spec checks the effect column and its passage_text extra fields {sorted(cov)}, never {c!r}; "
                "a text column D1 does not check cannot be released to N/A by D1")
    if table_columns is not None:
        absent = [c for c in cols if c not in table_columns]
        if absent:
            return f"column(s) {absent} are not columns of the asset's table"
    if column_types is not None:
        nontext = [c for c in cols if c in column_types and str(column_types[c]).strip().casefold() not in LDGR_TEXT_TYPES]
        if nontext:
            return f"column(s) {nontext} are not text columns (a prose coupling classifies TEXT columns: {[column_types[c] for c in nontext]})"
    return None


def prose_empty_d1_problem(entry):
    """None, or why the entry is refused: it declares prose_fields [] AND a transcription carriage that applies D1, but no `prose_coupling` (N-94: such a declaration is
    refused unless Carr.D1 covers its text columns, so the binding holds by VALIDATION, not by a test: deleting the coupling block must not turn the asset into a plain Narr N/A with
    no Carr.D1 behind it). An asset with no D1-transcription carriage (bg_yogas, bg_doshas, bg_ontology, bo_laksana_rerank) is never touched by this."""
    if not isinstance(entry, dict) or entry.get("prose_fields") != [] or entry.get("prose_coupling") is not None:
        return None
    car = entry.get("carriage")
    if isinstance(car, dict) and car.get("nature") == "transcription" and car.get("applies") == "D1":
        return ("prose_fields [] on an asset that declares a transcription carriage checked by D1 needs a `prose_coupling` to carriage_d1 naming the text columns Carr.D1 covers "
                "(N-94): without it the Narr N/A would stand with no Carr.D1 behind it; declare the coupling (or declare the prose_fields the writer composes)")
    return None


# NARR-GUARD required-coupling pin (E6.1 follow-up, L3). `prose_empty_d1_problem` binds a coupling to the D1 carriage it rests on by VALIDATION, but it keys on the
# carriage being PRESENT: delete the `prose_coupling` AND the `carriage` block of bg_phaladeepika_latta (a double deletion) and what is left is `prose_fields []` on an asset with
# no carriage, which is exactly what bg_doshas / bg_yogas / bg_ontology / bo_laksana_rerank declare, a plain R03 Narr N/A with no Carr.D1 behind it: a cheaper state reached by
# deleting two declarations. This table names the assets whose N/A is ONLY ever the coupled one (the strategist ruling that made their text columns transcription, N-94): for
# them the coupling is REQUIRED, so `prose_fields []` without a `prose_coupling` is refused by the validator, read NO_DETECTOR by the measure-time glue and flagged
# `declared_prose_coupling_missing` for the rollup / gap ledger / certificate writer / E6.3 reader, whatever else the entry holds or whether it exists. A registry-side table, not
# fingerprinted content (it adds no criterion, rule or cause and decides no cell where the coupling is present); adding an asset here is a ruling, not a convenience.
PROSE_COUPLING_REQUIRED = {
    "bg_phaladeepika_latta": "N-94: its effect / affliction strings are transcription of a cited passage whose fidelity only Carr.D1 measures",
}


def prose_coupling_required_problem(asset_id, entry):
    """None unless `asset_id` is in PROSE_COUPLING_REQUIRED and its declaration carries no `prose_coupling` object (an absent entry, a null one, a malformed one: all missing); else why
    its Narr N/A may not stand. Pure; ONE definition for the validator, the measure-time glue and `declared_facts`."""
    why = PROSE_COUPLING_REQUIRED.get(asset_id) if isinstance(asset_id, str) else None
    if why is None:
        return None
    if isinstance(entry, dict) and isinstance(entry.get("prose_coupling"), dict):
        return None
    return (f"{asset_id} requires a prose_coupling to carriage_d1 ({why}): without it a `prose_fields []` would be a plain no-prose N/A with no Carr.D1 behind it "
            "(deleting the coupling together with the carriage must not make the asset cheaper)")


def prose_coupling_unclassified(entry, table_columns, column_types) -> list:
    """The table's text-like columns that are neither listed in the entry's prose_coupling nor a column its D1 spec checks: the structural labels and provenance pointers the
    N/A does NOT claim to cover (R03 reads them as not narration). Named on the measured record so a reviewer sees them; never gated. [] when the entry has no coupling or the
    catalog is unavailable."""
    if not isinstance(entry, dict) or not isinstance(entry.get("prose_coupling"), dict) or not isinstance(table_columns, (list, tuple, set)) or not isinstance(column_types, dict):
        return []
    try:
        d1cols = set(_carriage_d1().spec_columns(entry["carriage"]["spec"]))
    except (KeyError, TypeError, AttributeError):
        d1cols = set()
    listed = set(entry["prose_coupling"].get("columns") or [])
    return sorted(c for c in table_columns if isinstance(c, str) and c not in listed and c not in d1cols
                  and str(column_types.get(c, "")).strip().casefold() in LDGR_TEXT_TYPES)


def validate_prose_coupling_declaration(where: str, pc, e: dict) -> None:
    """Raises DeclarationsError when an asset's `prose_coupling` is malformed or unsound: shape, a real `why` and a real `evidence` (S3's text rules; `unverified:` is refused, this releases
    an N/A), then `prose_coupling_problem` (prose_fields exactly [], a transcription D1 carriage with a spec, every listed column covered by it)."""
    if not isinstance(pc, dict):
        raise DeclarationsError(f"{where}.prose_coupling must be an object or null")
    _s3_common(where, "prose_coupling", pc, PROSE_COUPLING_DECL_FIELDS, na=True)
    bad = prose_coupling_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.prose_coupling: {bad}")


# DENS-TIER-GUARD (REGISTRY_REVISION 23, strategist ruling N-98 / Dens memo item 3). The Dens tier vocabulary is CLOSED (`dens_tier_counts`, above): an asset whose served select
# carries a verification / confidence tier column that is not literally `tier` / `verification_pass_status` DECLARES it: `density_tier_columns: [{column, why, evidence}]`.
# STRICTER-ONLY and inert until an asset declares one: no declaration, no change from the closed default. A deny-listed name (a price / plan / access bucket) is refused even when declared.
DENSITY_TIER_WHY_WORDS = ("verification", "confidence")


def density_tier_problem(entry, table_columns=None):
    """None when `entry` (an asset's declaration) has no `density_tier_columns`, or has a sound one; else why it is refused. ONE definition: the validator
    (validate_density_tier_declaration) and the measure-time glue both call it. Sound means: a non-empty list of at most DENS_TIER_MAX_DECLARED objects with exactly the fields
    column / why / evidence; `column` an identifier, no duplicate (case-insensitive), never a deny-listed name (`cost_tier`: a price bucket is not verification, declared or not);
    `why` a real one-line reason (S3's text rule) that says the column is a verification or confidence tier and names no deny-listed word; `evidence` a real repo-relative `file:LINE`
    (the line within the file; the file mentions the column; never `unverified:`). With `table_columns` (the measure-time catalog; None = not supplied) every declared column must also be a column of the asset's table."""
    if not isinstance(entry, dict) or entry.get("density_tier_columns") is None:
        return None
    dt = entry["density_tier_columns"]
    if not isinstance(dt, list) or not dt:
        return "density_tier_columns must be a non-empty list of {column, why, evidence} (omit the key to declare none)"
    if len(dt) > DENS_TIER_MAX_DECLARED:
        return f"density_tier_columns declares more than {DENS_TIER_MAX_DECLARED} columns: not a tier vocabulary"
    seen: list = []
    for i, d in enumerate(dt):
        w = f"density_tier_columns[{i}]"
        if not isinstance(d, dict):
            return f"{w} must be an object {{column, why, evidence}}"
        extra = sorted(set(d) - set(DENS_TIER_DECL_FIELDS))
        if extra:
            return f"{w}: unknown field(s) {extra}"
        missing = [f for f in DENS_TIER_DECL_FIELDS if f not in d]
        if missing:
            return f"{w}: missing field(s) {missing}"
        c = d["column"]
        if not (isinstance(c, str) and _DECL_IDENT.fullmatch(c)):
            return f"{w}.column must be a column name (an identifier), got {c!r}"
        if c.casefold() in {x.casefold() for x in seen}:
            return f"{w}.column {c!r} is declared twice (duplicate)"
        dw = dens_tier_denied_word(c)
        if dw:
            return (f"{w}.column {c!r} carries the deny-listed word {dw!r} ({', '.join(sorted(DENS_TIER_DENY_WORDS))}): a cost / price / plan / access bucket is not a "
                    "verification or confidence tier, and a deny-listed name never counts, declared or not")
        seen.append(c)
        bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
        if bad:
            return f"{w}.why {bad} (why this column is a verification / confidence tier)"
        if not any(x in d["why"].casefold() for x in DENSITY_TIER_WHY_WORDS):
            return f"{w}.why must say the column is a verification or confidence tier (the word 'verification' or 'confidence'): {d['why']!r}"
        wdeny = next((x for x in DENS_TIER_DENY_WORDS for tk in re.findall(r"[a-z]+", d["why"].casefold()) if x in _dens_deny_stems(tk)), None)
        if wdeny:
            return (f"{w}.why contains the deny-listed word {wdeny!r}: a reason that talks about a cost / price / plan / access bucket does not establish a verification or "
                    f"confidence tier, whatever else it says: {d['why']!r}")
        ev = d["evidence"]
        if isinstance(ev, str) and ev.startswith("unverified:"):
            return f"{w}.evidence may not be `unverified:`: a tier declaration lifts a Dens cell, so it must point at a real file:line the reviewer read"
        bad = _s3_evidence_problem(ev, allow_unverified=False, needle=c)
        if bad:
            return f"{w}.evidence {ev!r} {bad}"
        if not re.search(r":[0-9]+$", ev):
            return f"{w}.evidence {ev!r} must name a line (repo-relative file:LINE)"
    if table_columns is not None:
        have = {c.casefold() for c in table_columns if isinstance(c, str)}
        absent = [d["column"] for d in dt if d["column"].casefold() not in have]
        if absent:
            return f"declared tier column(s) {absent} are not columns of the asset's table"
    return None


def density_tier_measure_problem(entry, table, table_columns):
    """The measure-time form of `density_tier_problem` (ONE definition of the check, plus what only a measurement can say): None when the entry declares nothing; else why Dens.served
    cannot trust the declaration. A declaration on an asset with NO target table, or on a table whose columns the catalog does not list (a view / materialized view / no column rows:
    `table_columns` None), is UNVERIFIABLE and refused, never read as present."""
    if not isinstance(entry, dict) or entry.get("density_tier_columns") is None:
        return None
    if not table:
        return "the asset has no target table, so the declared tier columns cannot apply to any table (declaration unverifiable)"
    if table_columns is None:
        return f"table columns unknown for {table} (a view, or the catalog lists no columns for it), declaration unverifiable"
    return density_tier_problem(entry, table_columns)


def validate_service_probe_declaration(where: str, sp, e: dict) -> None:
    """Raises DeclarationsError when an asset's `service_probe` is malformed: only a declared `service` kind carries one; `probe_type` is an identifier (whether the registry names it is the measure-time
    question), `max_age_hours` a positive integer within a year, `why` a real one-line reason and `evidence` a checkable pointer (`unverified:` allowed: it names a probe, it releases nothing)."""
    if not isinstance(sp, dict):
        raise DeclarationsError(f"{where}.service_probe must be an object or null")
    if e.get("kind") != "service":
        raise DeclarationsError(f"{where}.service_probe is only for a declared kind 'service', got {e.get('kind')!r}")
    _s3_common(where, "service_probe", sp, SERVICE_PROBE_DECL_FIELDS, na=False)
    _s3_ident(where, "service_probe", "probe_type", sp.get("probe_type"))
    h = sp.get("max_age_hours")
    if not (isinstance(h, int) and not isinstance(h, bool) and 1 <= h <= SERVICE_MAX_AGE_HOURS_CAP):
        raise DeclarationsError(f"{where}.service_probe.max_age_hours must be an integer of 1..{SERVICE_MAX_AGE_HOURS_CAP}, got {h!r}")


def validate_density_tier_declaration(where: str, dt, e: dict) -> None:
    """Raises DeclarationsError when an asset's `density_tier_columns` is malformed or unsound (see `density_tier_problem`). The validator has no database: that a declared
    column IS a column of the table is the measure-time question (Dens.served reads NO_DETECTOR with the disagreement reported, never PASS)."""
    bad = density_tier_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.{bad}" if bad.startswith("density_tier_columns") else f"{where}.density_tier_columns: {bad}")


# ─────────────────── N-150 / N-151 (REGISTRY_REVISION 26): the engine build-out declarations ───────────────────
# Four declaration forms, validated here (SHAPE only: no database, no register). Each is inert until an asset declares it; the detectors that READ them are separate
# (Ldgr.source_presence for `source`; the Narr.* / Null.* N/A for `prose_none`; Build.completion's produced-table clause for `produced_tables`).
#
# `source` (N-151, R4 final): EVERY L0 asset that holds data carries a SOURCE of kind K1 (classical citation: text + locus), K2 (ratification: a decision id) or K3 (derivation:
# generator or dataset + method + version or seed); computed L1/L2 assets declare LEDGER (the fact ids a column carries resolve to chart_facts.fact_id, N.5). TABLE level: one declared
# source for the whole table (the constants are in the declaration). ROW level: `columns` names the column(s) that carry the source per row; the entries are ALTERNATIVES (a row is
# sourced when at least one entry resolves). N/A exists ONLY as `na: no_data` (the asset holds no data: no owned table) or `na: no_claims` (the asset makes no claims), each CHECKED by the detector.
SOURCE_KINDS = ("K1", "K2", "K3", "LEDGER")
SOURCE_LEVELS = ("table", "row")
SOURCE_NA_FORMS = ("no_data", "no_claims", "not_built")
SOURCE_DECL_FIELDS = ("na", "level", "kind", "citation", "locus", "decision_id", "generator", "dataset", "method", "version", "seed", "version_digest", "columns", "provenance_columns", "citation_state", "residual", "untraced_marker", "why", "evidence")
SOURCE_COLUMN_FIELDS = ("column", "kinds", "id_prefixes", "generator_column", "dataset_column", "method_column", "version_column", "seed_column", "path", "resolves_to", "except_when", "split_citation")
# `split_citation` (SS via Pravaha, form (b) of the six Rahu/Ketu house-vedha rows of bg_transit_rules): the ONE declared, CHECKED exception to "a citation that starts with UNSOURCED is a placeholder".
# A K1 text column may declare it for the rows a closed `applies_to` predicate selects. On those rows a citation of EXACTLY the shape
#   UNSOURCED (vedha partner: <text>) - transit result: <K1 locus words> [machine locus <text_id>:PG<n>:C<n>] "<excerpt of at most 25 words>"
# is judged on its K1 part (the locus words are not a placeholder, the excerpt is non-blank and short, and the machine locus RESOLVES to a chunk of classical_text_chunks); a string of any other shape
# that starts with UNSOURCED stays a placeholder, and so does the split shape on a row the predicate does not select. No general 'UNSOURCED is fine' rule. The vedha partner stays declared unsourced:
# the record names the rows judged this way and the declaration's `why` says what is pending.
SPLIT_CITATION_FIELDS = ("vedha_prefix", "applies_to", "why", "evidence")
SPLIT_VEDHA_PREFIX = "UNSOURCED (vedha partner:"
SPLIT_MAX_PREDICATES = 6
SPLIT_MAX_EXCERPT_WORDS = 25
SPLIT_SHAPE_RE = (r'^UNSOURCED \(vedha partner: ([^()]{1,200})\) — transit result: ([^\[\]"]{3,200}) \[machine locus ([a-z][a-z0-9_]*):PG([0-9]{1,4}):C([0-9]{1,2})\] "([^"]{1,255})"$')
SPLIT_WS = " \t\r\n\u00a0\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u200b\u202f\u205f\u3000\ufeff"     # every kind of blank: ASCII, NBSP, the unicode spaces, zero-width space, BOM
SPLIT_ALLOWED = {("bg_transit_rules", "classical_citation")}       # the ONE table / column the exception exists for (SS via Pravaha): any other asset or column that declares it is refused
SOURCE_RESOLVES_TO = ("chart_facts.fact_id", "bodha_msr_signals.signal_id")
SOURCE_EXCEPT_FIELDS = ("column", "equals")
_LEDGER_PATH_RE = re.compile(r"\$(?:\.[A-Za-z_][A-Za-z0-9_]*(?:\[\*\])?)+")
_SHA256_RE = re.compile(r"[0-9a-f]{64}")
SOURCE_MAX_COLUMNS = 8
SOURCE_DEFAULT_ID_PREFIXES = ("N", "D", "F")
_K2_SHORT_RE = re.compile(r"[A-Za-z][A-Za-z0-9]{0,5}-?[0-9]{1,6}[A-Za-z0-9._-]{0,24}")      # a decision id: N-150, D-4, F-2, N-72a
_K2_LONG_PREFIXES = ("ADJUDICATION", "RULING", "DVA")      # the closed set of long ruling / adjudication id prefixes (SS 2026-10-05)
_K2_LONG_RE = re.compile(r"(ADJUDICATION|RULING|DVA)-([0-9]{1,6})_([0-9]{4})-([0-9]{2})-([0-9]{2})")      # ADJUDICATION-9_2026-08-01: the id, then a REAL calendar date (checked in _k2_problem)
_K2_ID_RE = re.compile(_K2_SHORT_RE.pattern + "|" + _K2_LONG_RE.pattern)      # the combined shape (callers that only need "is it id-shaped")
_ID_PREFIX_RE = re.compile(r"[A-Z]{1,4}")


_SRC_BARE_PLACEHOLDERS = frozenset({"tbc", "unsourced", "tradition", "classical tradition"})      # bare labels that state no source ('classical_tradition' normalises to 'classical tradition')


def _src_text_problem(v):
    """None when `v` is a real one-line value for a source field, else why not: a non-blank string with no control character and at least one real word, that is no placeholder
    (the S3 placeholder words anywhere: tbd, todo, none, n/a, xxx, pending, unknown ...; tbc; a value with no letter or digit such as '?'; 'unsourced ...'; a bare tradition label such as
    classical_tradition). N-151: a placeholder is no source."""
    bad = _s3_text_problem(v, min_chars=1, min_words=1)
    if bad:
        return bad
    n = re.sub(r"[\W_]+", " ", v).strip().casefold()
    if not n or n in _SRC_BARE_PLACEHOLDERS or n.startswith("unsourced"):
        return "is a placeholder (a status word, 'unsourced', or a bare tradition label states no source)"
    return None


def source_version_digest_problem(vd):
    """None when `vd` is {file, sha256}: a repo-relative path (no `..`, not absolute) and a lower-case sha256 hex. SHAPE only; the detector reads the file."""
    if not (isinstance(vd, dict) and set(vd) == {"file", "sha256"} and isinstance(vd["file"], str) and isinstance(vd["sha256"], str)):
        return "must be exactly {file: <repo-relative path>, sha256: <64 lower-case hex>}"
    f = vd["file"]
    if not f or f.startswith("/") or ".." in f.split("/") or any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in f):
        return "file must be a repo-relative path with no `..`"
    if not _SHA256_RE.fullmatch(vd["sha256"]):
        return "sha256 must be 64 lower-case hex characters"
    return None


def source_declared_columns(entry) -> list:
    """The columns an asset DECLARES as source carriers (N-156 F4: citation / provenance / hash / ratification-id columns are source metadata, NOT prose): the row-level `source` entries'
    columns, its `provenance_columns`, and the older `ldgr_source.source_column`. [] for an asset that declares none. The R1 live-schema check (grade_prose_none) does not count these as open text."""
    out = []
    if isinstance(entry, dict):
        src = entry.get("source")
        if isinstance(src, dict) and src.get("na") is None:
            for e in src.get("columns") or []:
                if isinstance(e, dict):
                    out += [e[f] for f in ("column", "generator_column", "dataset_column", "method_column", "version_column", "seed_column") if isinstance(e.get(f), str)]
            out += [c for c in (src.get("provenance_columns") or []) if isinstance(c, str)]
        ls = entry.get("ldgr_source")
        if isinstance(ls, dict) and isinstance(ls.get("source_column"), str):
            out.append(ls["source_column"])
    return list(dict.fromkeys(out))


def _src_text(v) -> bool:
    return _src_text_problem(v) is None


def _k2_parts(v):
    """(prefix, number, long_date_parts | None) of a decision-id string, or None when it has no id shape. The NUMBER is the digit run right after the FINAL prefix dash: for `A1-0` the prefix is `A1`
    and the number 0 (never the 1 inside the prefix); for a dashless id (`N150`) it is the first digit run after the leading letters. The long form (`ADJUDICATION-9_2026-08-01`) is a prefix from the
    closed set, a number, `_`, and a date; nothing else is accepted after the number."""
    if not isinstance(v, str):
        return None
    m = _K2_LONG_RE.fullmatch(v)
    if m:
        return m.group(1), int(m.group(2)), (int(m.group(3)), int(m.group(4)), int(m.group(5)))
    if not _K2_SHORT_RE.fullmatch(v):
        return None
    d = re.match(r"([A-Za-z][A-Za-z0-9]{0,5})-([0-9]+)", v)
    if d:
        parts = (d.group(1), int(d.group(2)), None)
    else:
        n = re.match(r"([A-Za-z]+)([0-9]+)", v)
        parts = (n.group(1), int(n.group(2)), None) if n else None
    if parts is not None and re.match(r"(?:" + "|".join(_K2_LONG_PREFIXES) + r")(?![A-Za-z])", parts[0]):
        return None                                      # RULING / DVA also fit the short shape: they are accepted ONLY in the long, dated form
    return parts


def _k2_problem(v):
    """None when `v` is a decision-id string (N-154: a string, no register lookup), else why not: the K2 shape (short: N-150, D-4, F-2, N-72a; long: ADJUDICATION | RULING | DVA, a number, `_` and a REAL
    date YYYY-MM-DD), an alphabetic prefix that is no placeholder word (TBD-1, TODO1, none-1, XXX-7 are not decision ids), and a NON-ZERO number read after the final prefix dash (N-0, A1-0, XXX-000 are not)."""
    parts = _k2_parts(v)
    if parts is None:
        return f"{v!r} is not a decision id (shape like N-150, D-4, F-2, or ADJUDICATION-9_2026-08-01): a bare word is not a source"
    prefix, number, date = parts
    if date is not None:
        try:
            dt.date(*date)
        except ValueError:
            return f"{v!r} carries a date that is not a real calendar date"
    letters = re.match(r"[A-Za-z]+", prefix).group(0).casefold()
    if letters in _S3_PLACEHOLDER_WORDS or letters in _SRC_BARE_PLACEHOLDERS or letters == "tbc":
        return f"{v!r} has a placeholder prefix: it is not a decision id"
    if number == 0:
        return f"{v!r} has a zero number: it is not a decision id"
    return None


def split_citation_problem(sc, entry, aid=None):
    """None when `sc` (a column entry's `split_citation`) is sound, else why not (SHAPE only; the data is read by the detector). The entry carries K1 ALONE; `vedha_prefix` is exactly
    SPLIT_VEDHA_PREFIX; `applies_to` is 1..SPLIT_MAX_PREDICATES distinct-column conditions, each {column, equals: <non-blank string>} | {column, in: [1..8 non-blank strings]} | {column, not_null: true};
    `why` a real one-line reason that says the vedha partner stays unsourced; `evidence` a real repo-relative file:LINE (never `unverified:`)."""
    if entry.get("kinds") != ["K1"]:
        return "belongs to an entry that carries K1 alone (a citation column), not mixed with K2 / K3 / LEDGER"
    if (aid, entry.get("column")) not in SPLIT_ALLOWED:
        return (f"is not allowed for {aid!r}.{entry.get('column')!r}: the exception exists for exactly {sorted(SPLIT_ALLOWED)} (any other UNSOURCED text is a placeholder); a new use needs its own ruling and an entry in SPLIT_ALLOWED")
    if not isinstance(sc, dict):
        return "must be an object {vedha_prefix, applies_to, why, evidence}"
    extra = sorted(set(sc) - set(SPLIT_CITATION_FIELDS))
    missing = [f for f in SPLIT_CITATION_FIELDS if f not in sc]
    if extra or missing:
        return f"must be exactly {list(SPLIT_CITATION_FIELDS)} (unknown {extra}, missing {missing})"
    if sc["vedha_prefix"] != SPLIT_VEDHA_PREFIX:
        return f"vedha_prefix must be exactly {SPLIT_VEDHA_PREFIX!r}: the one shape the exception is for, never another UNSOURCED text"
    ap = sc["applies_to"]
    if not (isinstance(ap, list) and 1 <= len(ap) <= SPLIT_MAX_PREDICATES):
        return f"applies_to must be a list of 1 to {SPLIT_MAX_PREDICATES} conditions"
    seen = set()
    for i, cond in enumerate(ap):
        if not (isinstance(cond, dict) and isinstance(cond.get("column"), str) and _DECL_IDENT.fullmatch(cond["column"])):
            return f"applies_to[{i}] must name a column (an identifier)"
        ops = [k for k in cond if k != "column"]
        if len(ops) != 1 or ops[0] not in ("equals", "in", "not_null"):
            return f"applies_to[{i}] must carry exactly one of equals / in / not_null"
        op, v = ops[0], cond[ops[0]]
        def _s(x):
            return isinstance(x, str) and x.strip() and x == x.strip() and len(x) <= 200 and "\\" not in x and not any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in x)
        if op == "equals" and not _s(v):
            return f"applies_to[{i}].equals must be a non-blank string"
        if op == "in" and not (isinstance(v, list) and 1 <= len(v) <= 8 and len(set(v)) == len(v) and all(_s(x) for x in v)):
            return f"applies_to[{i}].in must be 1 to 8 distinct non-blank strings"
        if op == "not_null" and v is not True:
            return f"applies_to[{i}].not_null must be true"
        if cond["column"] in seen:
            return f"applies_to names column {cond['column']} twice"
        seen.add(cond["column"])
    bad = _s3_text_problem(sc["why"], min_chars=15, min_words=3)
    if bad:
        return f"why {bad}"
    if not any(w in sc["why"].casefold() for w in ("vedha", "unsourced")):
        return f"why must say what stays unsourced (the vedha partner): {sc['why']!r}"
    bad = _s3_evidence_problem(sc["evidence"], allow_unverified=False)
    if bad:
        return f"evidence {sc['evidence']!r} {bad}"
    if not re.search(r":[0-9]+$", sc["evidence"]):
        return f"evidence {sc['evidence']!r} must name a line (repo-relative file:LINE)"
    return None


def source_declaration_problem(src, entry=None, aid=None):
    """None when `src` (an asset's `source` declaration) is well formed, else why not (SHAPE only). Exactly one of: `na` ('no_data' | 'no_claims': no other field but why / evidence;
    evidence may not be `unverified:`), or `level` 'table' (`kind` K1: citation + locus + citation_state; K2: decision_id; K3: generator xor dataset, method, version and/or seed) or `level`
    'row' (`columns`: 1..SOURCE_MAX_COLUMNS entries; an entry with `kinds` ['K3'] names generator_column xor dataset_column, method_column and version_column and/or seed_column; an entry
    with ['LEDGER'] names `column` (alone: LEDGER is not mixed); any other entry names `column` and `kinds` a distinct non-empty subset of K1 / K2, optional `id_prefixes` only with K2).
    K2 is a decision-id STRING (N-154): a non-placeholder id shape, not a bare word. Every form needs `why` and `evidence` (S3 text and pointer rules). A row entry's column names are distinct
    across the declaration. `citation_state` (one of CITATION_STATES) is required when any K1 source is declared."""
    if not isinstance(src, dict):
        return "source must be an object or null"
    extra = sorted(set(src) - set(SOURCE_DECL_FIELDS))
    if extra:
        return f"unknown field(s) {extra}"
    na = src.get("na")
    bad = _s3_text_problem(src.get("why"), min_chars=15, min_words=3)
    if bad:
        return f"why {bad}"
    bad = _s3_evidence_problem(src.get("evidence"), allow_unverified=na is None)
    if bad:
        return f"evidence {src.get('evidence')!r} {bad}"
    if na is not None:
        if na not in SOURCE_NA_FORMS:
            return f"na must be null or one of {list(SOURCE_NA_FORMS)}, got {na!r}"
        other = sorted(k for k in src if k not in ("na", "why", "evidence") and src[k] is not None)
        if other:
            return f"na {na!r} declares no source, so {other} must be absent"
        return None
    level = src.get("level")
    if level not in SOURCE_LEVELS:
        return f"level must be one of {list(SOURCE_LEVELS)} (or na one of {list(SOURCE_NA_FORMS)}), got {level!r}"
    cs = src.get("citation_state")
    if cs is not None and cs not in CITATION_STATES:
        return f"citation_state must be null or one of {list(CITATION_STATES)}, got {cs!r}"
    rs, mk = src.get("residual"), src.get("untraced_marker")
    if rs is not None:
        if rs not in LDGR_RESIDUALS:
            return f"residual must be null or one of {list(LDGR_RESIDUALS)}, got {rs!r}"
        if level != "row":
            return f"residual {rs} is a row-level declaration (the detector checks the rows really lack a traceable source): a table-level source cannot carry it"
        if cs != "unsourced":
            return f"residual {rs} stands only on citation_state 'unsourced' (a source that is sourced is not an unsourced residual), got {cs!r}"
        cols_ = src.get("columns")
        if not (isinstance(cols_, list) and len(cols_) == 1 and isinstance(cols_[0], dict) and cols_[0].get("kinds") == ["K1"]):
            return f"residual {rs} reads ONE row-level K1 source column (the column the rows would name a source in): `columns` is exactly one entry with kinds ['K1']"
        if mk is not None:
            bad = _s3_text_problem(mk, min_chars=12, min_words=3, placeholder="prose")
            if bad:
                return f"untraced_marker {bad}"
            if len(mk) > 200 or "\\" in mk:
                return "untraced_marker must be at most 200 characters with no backslash"
    elif mk is not None:
        return "untraced_marker is a field of a residual declaration"
    pc = src.get("provenance_columns")
    if pc is not None and not (isinstance(pc, list) and 1 <= len(pc) <= SOURCE_MAX_COLUMNS and len(set(pc)) == len(pc)
                               and all(isinstance(c, str) and _DECL_IDENT.fullmatch(c) for c in pc)):
        return f"provenance_columns must be null or a list of 1 to {SOURCE_MAX_COLUMNS} distinct column names (citation / provenance / hash columns that are source metadata, not prose, N-156 F4)"
    if level == "table":
        kind = src.get("kind")
        if kind not in ("K1", "K2", "K3"):
            return f"a table-level source has kind K1, K2 or K3, got {kind!r}"
        if src.get("columns") is not None:
            return "a table-level source names no columns (the declared source is for the whole table)"
        need = {"K1": ("citation", "locus"), "K2": ("decision_id",), "K3": ("method",)}[kind]
        allowed = {"K1": ("citation", "locus"), "K2": ("decision_id",), "K3": ("generator", "dataset", "method", "version", "seed")}[kind]
        for f in ("citation", "locus", "decision_id", "generator", "dataset", "method", "version", "seed"):
            v = src.get(f)
            if f in allowed:
                bad = None if v is None else _src_text_problem(v)
                if bad:
                    return f"{f} {bad}"
            elif v is not None:
                return f"{f} is not a field of a {kind} source"
        vd = src.get("version_digest")
        if vd is not None:
            if kind != "K3":
                return "version_digest is a field of a K3 source (the code digest of the generator, standing as its version)"
            bad = source_version_digest_problem(vd)
            if bad:
                return f"version_digest {bad}"
        for f in need:
            if src.get(f) is None:
                return f"a {kind} source needs {f}"
        if kind == "K1" and cs is None:
            return "a K1 source states its citation_state (sourced / sourced_ocr_unverified / unsourced / refuted): a citation is never assumed verified"
        if kind == "K2":
            bad = _k2_problem(src["decision_id"])
            if bad:
                return f"decision_id {bad}"
        if kind == "K3":
            if (src.get("generator") is None) == (src.get("dataset") is None):
                return "a K3 source names exactly one of generator / dataset"
            if src.get("version") is None and src.get("seed") is None and src.get("version_digest") is None:
                return "a K3 source names a version, a seed or a version_digest (the code digest of its generator)"
        return None
    for f in ("kind", "citation", "locus", "decision_id", "generator", "dataset", "method", "version", "seed", "version_digest"):
        if src.get(f) is not None:
            return f"{f} is a table-level field; a row-level source names its sources in `columns`"
    cols = src.get("columns")
    if not (isinstance(cols, list) and 1 <= len(cols) <= SOURCE_MAX_COLUMNS):
        return f"a row-level source needs `columns`: a list of 1 to {SOURCE_MAX_COLUMNS} entries"
    seen, k1 = set(), False
    for i, c in enumerate(cols):
        lab = f"columns[{i}]"
        if not isinstance(c, dict):
            return f"{lab} must be an object"
        bad_f = sorted(set(c) - set(SOURCE_COLUMN_FIELDS))
        if bad_f:
            return f"{lab}: unknown field(s) {bad_f}"
        kinds = c.get("kinds")
        if not (isinstance(kinds, list) and kinds and len(set(kinds)) == len(kinds) and all(k in SOURCE_KINDS for k in kinds)):
            return f"{lab}.kinds must be a non-empty list of distinct kinds from {list(SOURCE_KINDS)}"
        names = []
        if kinds != ["LEDGER"] and (c.get("path") is not None or c.get("resolves_to") is not None):
            return f"{lab}: path / resolves_to belong to a LEDGER entry"
        if c.get("path") is not None and not (isinstance(c["path"], str) and _LEDGER_PATH_RE.fullmatch(c["path"])):
            return f"{lab}.path must be a JSON path into a json(b) column: $.key(.key)*, a key optionally followed by [*] (e.g. $.signal_ids, $.factor_ledger[*])"
        if c.get("resolves_to") is not None and c["resolves_to"] not in SOURCE_RESOLVES_TO:
            return f"{lab}.resolves_to must be one of {list(SOURCE_RESOLVES_TO)}"
        ew = c.get("except_when")
        if ew is not None:
            if not (isinstance(ew, dict) and set(ew) == set(SOURCE_EXCEPT_FIELDS) and isinstance(ew.get("column"), str) and _DECL_IDENT.fullmatch(ew["column"])
                    and isinstance(ew.get("equals"), str) and ew["equals"].strip() and ew["equals"] == ew["equals"].strip()
                    and not any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in ew["equals"]) and "\\" not in ew["equals"] and len(ew["equals"]) <= 200):
                return f"{lab}.except_when must be exactly {{column: <identifier>, equals: <non-blank string>}}: the rows with that value are excepted from this entry by declaration"
            if ew["column"] in (c.get("column"), c.get("generator_column"), c.get("dataset_column"), c.get("method_column"), c.get("version_column"), c.get("seed_column")):
                return f"{lab}.except_when names the entry's own source column"
        sc_ = c.get("split_citation")
        if sc_ is not None:
            bad = split_citation_problem(sc_, c, aid)
            if bad:
                return f"{lab}.split_citation {bad}"
        if kinds == ["K3"]:
            for f in ("generator_column", "dataset_column", "method_column", "version_column", "seed_column"):
                if c.get(f) is not None:
                    if not (isinstance(c[f], str) and _DECL_IDENT.fullmatch(c[f])):
                        return f"{lab}.{f} must be a column name (an identifier)"
                    names.append(c[f])
            if c.get("column") is not None or c.get("id_prefixes") is not None:
                return f"{lab}: a K3 entry names generator_column / dataset_column, method_column, version_column / seed_column, not `column` or `id_prefixes`"
            if (c.get("generator_column") is None) == (c.get("dataset_column") is None):
                return f"{lab}: a K3 entry names exactly one of generator_column / dataset_column"
            if c.get("method_column") is None:
                return f"{lab}: a K3 entry names method_column"
            if c.get("version_column") is None and c.get("seed_column") is None:
                return f"{lab}: a K3 entry names version_column or seed_column"
        else:
            if "K3" in kinds:
                return f"{lab}: K3 is declared alone (its sources are three columns), not mixed with {kinds}"
            if "LEDGER" in kinds and kinds != ["LEDGER"]:
                return f"{lab}: LEDGER (fact ids resolved against chart_facts) is declared alone, not mixed with {kinds}"
            if not (isinstance(c.get("column"), str) and _DECL_IDENT.fullmatch(c["column"])):
                return f"{lab}.column must be a column name (an identifier)"
            names.append(c["column"])
            if any(c.get(f) is not None for f in ("generator_column", "dataset_column", "method_column", "version_column", "seed_column")):
                return f"{lab}: generator_column / dataset_column / method_column / version_column / seed_column belong to a K3 entry"
            pre = c.get("id_prefixes")
            if pre is not None:
                if "K2" not in kinds:
                    return f"{lab}.id_prefixes is only for an entry that carries K2"
                if not (isinstance(pre, list) and 1 <= len(pre) <= 8 and len(set(pre)) == len(pre) and all(isinstance(p, str) and _ID_PREFIX_RE.fullmatch(p) for p in pre)):
                    return f"{lab}.id_prefixes must be 1 to 8 distinct upper-case letter prefixes (default {list(SOURCE_DEFAULT_ID_PREFIXES)})"
            k1 = k1 or "K1" in kinds
        if len(set(names)) != len(names) or seen & set(names):
            return f"{lab}: a column is named twice in the declaration"
        seen |= set(names)
    if k1 and cs is None:
        return "a source that carries K1 states its citation_state"
    return None


def validate_source_declaration(where: str, src, e: dict, aid=None) -> None:
    """Raises DeclarationsError when an asset's `source` declaration is malformed (see `source_declaration_problem`), or sits beside the older `ldgr_source` (one source declaration per asset)."""
    bad = source_declaration_problem(src, e, aid)
    if bad:
        raise DeclarationsError(f"{where}.source: {bad}")
    if isinstance(e, dict) and e.get("ldgr_source") is not None:
        raise DeclarationsError(f"{where}.source: an asset declares `source` (N-151) or the older `ldgr_source`, not both")


# `prose_none` (N-150 R1/R2): the EXPLICIT declared-none form of `prose_fields []`. `prose_fields: []` alone says "this writer composes no prose" and nothing checks it against the
# schema; with `prose_none` the detector CHECKS the claim against the live schema: every text-capable column of the asset's produced tables (text / varchar / citext / array / json(b) /
# user-defined types) must be listed in `closed_columns` with a CLOSED vocabulary (`values`: the data must stay inside it) or, for a json(b) column, `no_string_leaves: true`; an open
# text column contradicts the declaration (FAIL, not N/A). Narr.* and Null.* read N/A only through a passing check.
PROSE_NONE_DECL_FIELDS = ("why", "closed_columns", "transcription_columns", "identifier_columns", "column_scope")
PROSE_NONE_COLUMN_SCOPES = ("all", "written")
PROSE_NONE_MAX_IDENTIFIERS = 32
PROSE_NONE_TRANSCRIPTION_FIELDS = ("column", "table", "why", "evidence")
PROSE_NONE_MAX_TRANSCRIPTIONS = 80      # SS 2026-10-05: raised from 32 (bg_nakshatra declares 51 transcription columns, bg_reference 60)
PROSE_NONE_COLUMN_FIELDS = ("table", "column", "values", "no_string_leaves", "json_leaf_patterns", "why")
# A json(b) column that carries timestamp-valued leaves (bo_laksana_rerank: `computed_at` inside graph_node_strength_contribution_jsonb) is closed by `json_leaf_patterns`: [{path, kind}], a path of
# the form $.key(.key)* each key optionally [*] and a closed leaf KIND. CHECKED against the DATA, never trusted: every string leaf of the column must sit at a declared path AND be shaped like its kind;
# any other string-valued leaf (or a declared path holding a differently shaped string) is outside the closure and the check FAILs. A pattern may instead carry a closed `values` list (a graha title, a formula-version
# string): the leaf at that path must equal one of them.
PROSE_NONE_LEAF_KINDS = {
    "iso8601_timestamp": r"^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)?$",
    "iso8601_date": r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$",
    # SS residual (L2 pointer leaves: bo_drishti `$.signal_ids[*]`, `$.ranked_signals[*].signal_id` ...): a string leaf that is an identifier of the canonical uuid shape, lower-case 8-4-4-4-12 hex (what
    # Postgres and Python str(uuid) write). Any other string at the path (a name, a sentence, an upper-case or brace/undashed form) is outside the closure: the shape is checked against the DATA.
    "uuid": r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
}
PROSE_NONE_MAX_LEAF_PATTERNS = 8
# a segment is a key (optionally followed by [*], every element of the array there) or `*` (every member VALUE of the object there: data-derived keys under a constant structure, e.g. a
# `$.domain_verdict_map.*.verdict_note` where the domain names are the keys and `verdict_note` is the constant sub-key; the jsonpath wildcard member accessor)
_LEAF_PATH_RE = re.compile(r"\$(?:\.(?:[A-Za-z_][A-Za-z0-9_]*|\*)(?:\[\*\])?)+")


def _leaf_path_segments(path: str) -> list[str]:
    """`$.a.*.b[*]` -> ['a', '*', 'b'] (the key sequence; [*] only unwraps an array and is not a segment)."""
    return path.replace("[*]", "").split(".")[1:]


def _leaf_paths_overlap(p: str, q: str) -> bool:
    """True when ONE leaf could be matched by both paths (so its count would be added twice and could mask a leaf outside the closure): same key-sequence length and, segment by segment,
    equal keys or a `*` on either side. Paths that differ only in [*] are the same path."""
    a, b = _leaf_path_segments(p), _leaf_path_segments(q)
    return len(a) == len(b) and all(x == y or x == "*" or y == "*" for x, y in zip(a, b))
PROSE_NONE_MAX_COLUMNS = 64
PROSE_NONE_MAX_VALUES = 300


def _leaf_values_ok(vals) -> bool:
    return (isinstance(vals, list) and 1 <= len(vals) <= PROSE_NONE_MAX_VALUES and len(set(vals)) == len(vals)
            and all(isinstance(v, str) and v.strip() and len(v) <= 200 and "\\" not in v
                    and not any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in v) for v in vals))


def prose_none_problem(entry):
    """None when `entry` has no `prose_none` or a sound one, else why not (SHAPE only). Sound: an object with exactly the fields why / closed_columns; `why` a real one-line reason; the entry
    declares `prose_fields` EXACTLY [] (a declared-none form qualifies the empty list) and no `prose_coupling` (a coupled asset's N/A rests on Carr.D1, not on this); `closed_columns` is a
    list (possibly empty: the produced tables have no text-capable column) of at most PROSE_NONE_MAX_COLUMNS objects: `column` an identifier, optional `table` an identifier, `why` a real
    reason, and exactly one of `values` (1..PROSE_NONE_MAX_VALUES distinct non-blank strings) or `no_string_leaves: true`; no (table, column) listed twice."""
    if not isinstance(entry, dict) or entry.get("prose_none") is None:
        return None
    pn = entry["prose_none"]
    if not isinstance(pn, dict):
        return "prose_none must be an object or null"
    extra = sorted(set(pn) - set(PROSE_NONE_DECL_FIELDS))
    if extra:
        return f"unknown field(s) {extra}"
    if entry.get("prose_fields") != []:
        return f"prose_none qualifies a declared prose_fields [] (this asset declares prose_fields {entry.get('prose_fields')!r})"
    if entry.get("prose_coupling") is not None:
        return "an asset declares a prose_coupling (its N/A rests on Carr.D1) or the prose_none form (its N/A rests on the schema check), not both"
    bad = _s3_text_problem(pn.get("why"), min_chars=15, min_words=3)
    if bad:
        return f"why {bad}"
    scope = pn.get("column_scope")
    if scope is not None and scope not in PROSE_NONE_COLUMN_SCOPES:
        return f"column_scope must be null or one of {list(PROSE_NONE_COLUMN_SCOPES)}"
    tc, idc = pn.get("transcription_columns"), pn.get("identifier_columns")
    for key, lst, cap, why_what in (("transcription_columns", tc, PROSE_NONE_MAX_TRANSCRIPTIONS, "a pointer to the text it transcribes"),
                                    ("identifier_columns", idc, PROSE_NONE_MAX_IDENTIFIERS, "a pointer to where the column is written as an identifier")):
        if lst is None:
            continue
        if not (isinstance(lst, list) and 1 <= len(lst) <= cap):
            return f"{key} must be null or a list of 1 to {cap} objects"
        seen_t = set()
        for i, t in enumerate(lst):
            lab = f"{key}[{i}]"
            if not isinstance(t, dict):
                return f"{lab} must be an object"
            bad_f = sorted(set(t) - set(PROSE_NONE_TRANSCRIPTION_FIELDS))
            if bad_f:
                return f"{lab}: unknown field(s) {bad_f}"
            if not (isinstance(t.get("column"), str) and _DECL_IDENT.fullmatch(t["column"])):
                return f"{lab}.column must be a column name (an identifier)"
            if t.get("table") is not None and not (isinstance(t["table"], str) and _DECL_IDENT.fullmatch(t["table"])):
                return f"{lab}.table must be null or a table name (an identifier)"
            bad = _s3_text_problem(t.get("why"), min_chars=15, min_words=3)
            if bad:
                return f"{lab}.why {bad}"
            bad = _s3_evidence_problem(t.get("evidence"), allow_unverified=False)
            if bad:
                return f"{lab}.evidence {t.get('evidence')!r} {bad} (the exemption from the vocabulary requirement rests on {why_what})"
            key2 = (t.get("table"), t["column"])
            if key2 in seen_t:
                return f"{lab}: ({key2[0] or 'the target table'}, {key2[1]}) is listed twice"
            seen_t.add(key2)
        if entry.get("prose_fields") != [] or any(parse_prose_field(f)[0] == t["column"] for t in lst for f in (entry.get("prose_fields") or []) if isinstance(f, str)):
            return f"a {key[:-8]} column is never also a prose_fields entry"
    both_ti = {(t.get("table"), t["column"]) for t in (tc or [])} & {(t.get("table"), t["column"]) for t in (idc or [])}
    if both_ti:
        return f"{sorted(both_ti)[0][1]} is both a transcription column and an identifier column: declare it once"
    cc = pn.get("closed_columns")
    if not (isinstance(cc, list) and len(cc) <= PROSE_NONE_MAX_COLUMNS):
        return f"closed_columns must be a list of at most {PROSE_NONE_MAX_COLUMNS} objects ([] = the produced tables carry no text-capable column)"
    seen = set()
    for i, c in enumerate(cc):
        lab = f"closed_columns[{i}]"
        if not isinstance(c, dict):
            return f"{lab} must be an object"
        bad_f = sorted(set(c) - set(PROSE_NONE_COLUMN_FIELDS))
        if bad_f:
            return f"{lab}: unknown field(s) {bad_f}"
        if not (isinstance(c.get("column"), str) and _DECL_IDENT.fullmatch(c["column"])):
            return f"{lab}.column must be a column name (an identifier)"
        if c.get("table") is not None and not (isinstance(c["table"], str) and _DECL_IDENT.fullmatch(c["table"])):
            return f"{lab}.table must be null or a table name (an identifier)"
        bad = _s3_text_problem(c.get("why"), min_chars=15, min_words=3)
        if bad:
            return f"{lab}.why {bad}"
        vals, nsl, jlp = c.get("values"), c.get("no_string_leaves"), c.get("json_leaf_patterns")
        if sum(x is not None for x in (vals, nsl, jlp)) != 1:
            return f"{lab} declares exactly one of values (a closed vocabulary), no_string_leaves true or json_leaf_patterns (a json(b) column whose only string leaves are declared kinds at declared paths)"
        if jlp is not None:
            if not (isinstance(jlp, list) and 1 <= len(jlp) <= PROSE_NONE_MAX_LEAF_PATTERNS):
                return f"{lab}.json_leaf_patterns must be a list of 1 to {PROSE_NONE_MAX_LEAF_PATTERNS} objects"
            seen_p = set()
            for k, pat in enumerate(jlp):
                if not (isinstance(pat, dict) and isinstance(pat.get("path"), str) and _LEAF_PATH_RE.fullmatch(pat["path"])
                        and (set(pat) == {"path", "kind"} and pat.get("kind") in PROSE_NONE_LEAF_KINDS
                             or set(pat) == {"path", "values"} and _leaf_values_ok(pat.get("values")))):
                    return (f"{lab}.json_leaf_patterns[{k}] must be exactly {{path: '$.key(.key)*' (a key or `*` optionally followed by [*]), kind: one of {sorted(PROSE_NONE_LEAF_KINDS)}}} "
                            f"OR {{path, values: 1 to {PROSE_NONE_MAX_VALUES} distinct non-blank strings, at most 200 characters each}} (a closed vocabulary for that path's string leaves)")
                norm = pat["path"].replace("[*]", "")           # a leaf has ONE key path: paths that differ only in [*] could match the same leaf and be counted twice
                if norm in seen_p:
                    return f"{lab}.json_leaf_patterns[{k}]: path {pat['path']} duplicates another path (paths that differ only in [*] match the same leaves)"
                clash = next((q for q in seen_p if _leaf_paths_overlap(norm, q)), None)
                if clash is not None:
                    return (f"{lab}.json_leaf_patterns[{k}]: path {pat['path']} overlaps {clash} (a `*` segment and a key, or two `*`, could match the same leaf, which would be counted twice and could "
                            "hide a string leaf outside the closure): declare the wildcard path alone or the keyed paths alone")
                seen_p.add(norm)
        if nsl is not None and nsl is not True:
            return f"{lab}.no_string_leaves must be true or absent"
        if vals is not None and not (isinstance(vals, list) and 1 <= len(vals) <= PROSE_NONE_MAX_VALUES and len(set(vals)) == len(vals)
                                     and all(isinstance(v, str) and v.strip() and len(v) <= 200 and "\\" not in v
                                             and not any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in v) for v in vals)):
            return f"{lab}.values must be 1 to {PROSE_NONE_MAX_VALUES} distinct non-blank strings (at most 200 characters each)"
        key = (c.get("table"), c["column"])
        if key in seen:
            return f"{lab}: ({key[0] or 'the target table'}, {key[1]}) is listed twice"
        seen.add(key)
    both = [k for k in seen if k in {(t.get("table"), t["column"]) for t in (tc or []) + (idc or [])}]
    if both:
        return f"{both[0][1]} is both a closed column and an exempt (transcription / identifier) column: declare it once"
    return None


def validate_prose_none_declaration(where: str, pn, e: dict) -> None:
    """Raises DeclarationsError when an asset's `prose_none` is malformed (see `prose_none_problem`)."""
    bad = prose_none_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.prose_none: {bad}")


# `produced_tables` (N-150): the asset's DECLARED produced-table set, e.g. ga_dashas = chart_dashas + chart_facts[fact_category = dasha_scope_cap]. A table the writer writes that is not
# in the set is an undeclared extra (the Build.completion clause that reads it is Worker B's; this block is the schema and the validator only).
PRODUCED_TABLE_FIELDS = ("table", "filter", "why")
PRODUCED_FILTER_FIELDS = ("column", "equals")
PRODUCED_MAX_TABLES = 8


def produced_tables_problem(entry):
    """None when `entry` has no `produced_tables` or a sound one, else why not. Sound: a non-empty list of at most PRODUCED_MAX_TABLES objects {table, filter?, why?}: `table` an identifier,
    `filter` null or {column, equals} (identifier, non-blank string: the slice of a SHARED table the asset produces), `why` null or a real one-line reason; no (table, filter) listed twice."""
    if not isinstance(entry, dict) or entry.get("produced_tables") is None:
        return None
    pt = entry["produced_tables"]
    if not (isinstance(pt, list) and 1 <= len(pt) <= PRODUCED_MAX_TABLES):
        return f"produced_tables must be a list of 1 to {PRODUCED_MAX_TABLES} objects"
    seen = set()
    for i, t in enumerate(pt):
        lab = f"produced_tables[{i}]"
        if not isinstance(t, dict):
            return f"{lab} must be an object"
        extra = sorted(set(t) - set(PRODUCED_TABLE_FIELDS))
        if extra:
            return f"{lab}: unknown field(s) {extra}"
        if not (isinstance(t.get("table"), str) and _DECL_IDENT.fullmatch(t["table"])):
            return f"{lab}.table must be a table name (an identifier)"
        f = t.get("filter")
        if f is not None:
            if not (isinstance(f, dict) and set(f) == set(PRODUCED_FILTER_FIELDS) and isinstance(f.get("column"), str) and _DECL_IDENT.fullmatch(f["column"])
                    and _src_text(f.get("equals"))):
                return f"{lab}.filter must be null or exactly {{column: <identifier>, equals: <non-blank string>}}"
        if t.get("why") is not None:
            bad = _s3_text_problem(t["why"], min_chars=15, min_words=3)
            if bad:
                return f"{lab}.why {bad}"
        key = (t["table"], None if f is None else (f["column"], f["equals"]))
        if key in seen:
            return f"{lab}: {t['table']} with this filter is listed twice"
        seen.add(key)
    return None


def validate_produced_tables_declaration(where: str, pt, e: dict) -> None:
    """Raises DeclarationsError when an asset's `produced_tables` is malformed (see `produced_tables_problem`)."""
    bad = produced_tables_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.{bad}" if bad.startswith("produced_tables") else f"{where}.produced_tables: {bad}")


def declared_produced_tables(entry) -> list | None:
    """The asset's declared produced-table set as [{table, filter}] (filter None or {column, equals}), or None when undeclared (UNKNOWN, never 'none')."""
    if not isinstance(entry, dict) or produced_tables_problem(entry) or entry.get("produced_tables") is None:
        return None
    return [dict(table=t["table"], filter=(dict(t["filter"]) if t.get("filter") else None)) for t in entry["produced_tables"]]


def produced_tables_extra(entry, observed) -> list | None:
    """The tables of `observed` (an iterable of table names a writer writes) that the entry's declared produced-table set does not name, sorted; None when the entry declares no set (nothing to
    compare against). An extra table is a FAIL for the clause that reads this (Build.completion, Worker B), never a tolerance."""
    decl = declared_produced_tables(entry)
    if decl is None:
        return None
    names = {d["table"] for d in decl}
    # a non-string observed name is never silently dropped: it cannot be in the declared set, so it is an EXTRA (reported as its repr)
    return sorted({(t if isinstance(t, str) else repr(t)) for t in observed if not (isinstance(t, str) and t in names)})
# DENS-FACET (REGISTRY_REVISION 26, Worker D; TI-L2-04). An asset that lives in a table other assets share (chart_facts, bodha_msr_signals) is attributed to a served select by a
# FACET it DECLARES: `density_facet: {column, values, why, evidence}` -- the column that tells this asset's rows from the table's other rows (`fact_category`, `signal_type_class`,
# `producer_asset_id`) and the value(s) that are its own. The scan then credits a served `SELECT ... FROM <shared table>` only when the SAME top-level declaration carries a literal
# predicate on that column pinning at least one declared value (`col = 'v'`, `col IN ('v', ...)`, `col = ANY(ARRAY['v'])`); a bind-parameter filter (`col = ANY($2)`) is reported and credits
# nothing (the value is not readable from the SQL, never guessed). Inert until an asset declares one; the evidence file must mention the column and every declared value.
DENS_FACET_DECL_FIELDS = ("column", "values", "why", "evidence")
DENS_FACET_MAX_VALUES = 32


def density_facet_problem(entry, table_columns=None):
    """None when `entry` has no `density_facet`, or a sound one; else why it is refused (ONE definition: the validator and the measure-time glue both call it)."""
    if not isinstance(entry, dict) or entry.get("density_facet") is None:
        return None
    d = entry["density_facet"]
    if not isinstance(d, dict):
        return "density_facet must be an object {column, values, why, evidence}"
    extra = sorted(set(d) - set(DENS_FACET_DECL_FIELDS))
    if extra:
        return f"density_facet: unknown field(s) {extra}"
    missing = [f for f in DENS_FACET_DECL_FIELDS if f not in d]
    if missing:
        return f"density_facet: missing field(s) {missing}"
    c = d["column"]
    if not (isinstance(c, str) and _DECL_IDENT.fullmatch(c)):
        return f"density_facet.column must be a column name (an identifier), got {c!r}"
    vs = d["values"]
    if not (isinstance(vs, list) and vs and len(vs) <= DENS_FACET_MAX_VALUES
            and all(isinstance(v, str) and v.strip() and v == v.strip() and "'" not in v and "${" not in v for v in vs) and len(set(vs)) == len(vs)):
        return (f"density_facet.values must be a non-empty list of at most {DENS_FACET_MAX_VALUES} distinct plain strings (no quote, no interpolation), got {vs!r}")
    bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
    if bad:
        return f"density_facet.why {bad} (why these values are this asset's rows of the shared table)"
    ev = d["evidence"]
    if isinstance(ev, str) and ev.startswith("unverified:"):
        return "density_facet.evidence may not be `unverified:`: a facet lifts a Dens cell, so it must point at a real file:line the reviewer read"
    bad = _s3_evidence_problem(ev, allow_unverified=False, needle=c)
    if bad:
        return f"density_facet.evidence {ev!r} {bad}"
    if not re.search(r":[0-9]+$", ev):
        return f"density_facet.evidence {ev!r} must name a line (repo-relative file:LINE)"
    body = (ROOT / re.sub(r":[0-9]+$", "", ev)).read_text(encoding="utf-8", errors="replace")
    absent = [v for v in vs if v not in body]
    if absent:
        return f"density_facet.evidence {ev!r} is a real file but does not mention the declared value(s) {absent}: the evidence must be about the facet it supports"
    if table_columns is not None and c.casefold() not in {x.casefold() for x in table_columns if isinstance(x, str)}:
        return f"declared facet column {c!r} is not a column of the asset's table"
    return None


def density_facet_measure_problem(entry, table, table_columns):
    """Measure-time form (same shape as `density_tier_measure_problem`): a declaration on an asset with no target table or unknown table columns is UNVERIFIABLE, never read as present."""
    if not isinstance(entry, dict) or entry.get("density_facet") is None:
        return None
    if not table:
        return "the asset has no target table, so the declared facet cannot apply to any table (declaration unverifiable)"
    if table_columns is None:
        return f"table columns unknown for {table} (a view, or the catalog lists no columns for it), declaration unverifiable"
    return density_facet_problem(entry, table_columns)


UNIFORM_AUTHORITY_DECL_FIELDS = ("why", "evidence")


def uniform_authority_problem(entry, asset_id=None):
    """None when `entry` has no `uniform_authority`, or a sound one; else why it is refused. TI-L0-04 (SS Q2, folded from held PR #3105) as ruled N-154 Q1: the
    declaration is an object {why, evidence} (the key present = this asset's table is a reference vocabulary of UNIFORM authority, so a tier column has nothing to
    distinguish and Dens.served may PASS on density_contract facets). `why` a real one-line reason that says every row carries the same authority (the word 'uniform'
    or 'authority'); `evidence` a real repo-relative file:LINE (never `unverified:`) that the reviewer read, and (review fix MED-2, with `asset_id` supplied) a file that MENTIONS the
    asset (its id or its declared `read_table`), so the pointer is about it. Absent or null = not declared."""
    if not isinstance(entry, dict) or entry.get("uniform_authority") is None:
        return None
    d = entry["uniform_authority"]
    if not isinstance(d, dict):
        return "must be an object {why, evidence} (omit the key to declare none)"
    extra = sorted(set(d) - set(UNIFORM_AUTHORITY_DECL_FIELDS))
    if extra:
        return f"unknown field(s) {extra}"
    missing = [f for f in UNIFORM_AUTHORITY_DECL_FIELDS if f not in d]
    if missing:
        return f"missing field(s) {missing}"
    bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
    if bad:
        return f"why {bad} (why every row of the table carries the same authority)"
    if not any(w in d["why"].casefold() for w in ("uniform", "authority")):
        return f"why must say the table's rows are of uniform authority (the word 'uniform' or 'authority'): {d['why']!r}"
    ev = d["evidence"]
    if isinstance(ev, str) and ev.startswith("unverified:"):
        return "evidence may not be `unverified:`: a declaration that lifts a Dens cell must point at a real file:line the reviewer read"
    bad = _s3_evidence_problem(ev, allow_unverified=False)
    if bad:
        return f"evidence {ev!r} {bad}"
    if not re.search(r":[0-9]+$", ev):
        return f"evidence {ev!r} must name a line (repo-relative file:LINE)"
    needles = [n for n in (asset_id, entry.get("read_table")) if isinstance(n, str) and n]
    if needles:
        body = (ROOT / re.sub(r":[0-9]+$", "", ev)).read_text(encoding="utf-8", errors="replace").casefold()
        if not any(re.search(r"(?<![A-Za-z0-9_])" + re.escape(n.casefold()) + r"(?![A-Za-z0-9_])", body) for n in needles):     # a whole word: 'ga_yoga' is not 'ga_yogas'
            return f"evidence {ev!r} is a real file but mentions neither {' nor '.join(repr(n) for n in needles)}: the evidence must be about this asset's table"
    return None


def uniform_authority_measure_problem(entry, table, table_columns, asset_id=None):
    """(review fix MED-2) The measure-time form: None when the entry declares no `uniform_authority`; else why Dens.served cannot trust it. A uniform-authority PASS bypasses the tier
    requirement, so it is REFUSED where the table carries a column of the closed tier vocabulary (`tier`, `verification_pass_status`: per-row authority exists, select it instead),
    where the table or its columns are unknown (unverifiable), or where the declaration itself is unsound."""
    if not isinstance(entry, dict) or entry.get("uniform_authority") is None:
        return None
    bad = uniform_authority_problem(entry, asset_id)
    if bad:
        return bad
    if not table:
        return "the asset has no target table, so the declared uniform authority cannot be checked against its columns (declaration unverifiable)"
    if table_columns is None:
        return f"table columns unknown for {table} (a view, or the catalog lists no columns for it), declaration unverifiable"
    declared = [d.get("column") for d in (entry.get("density_tier_columns") or []) if isinstance(d, dict)]      # the asset's own declared tier columns count as tier columns too
    tiers = sorted(c for c in table_columns if isinstance(c, str) and dens_tier_counts(c, declared))
    if tiers:
        return (f"the table {table} carries the tier column(s) {tiers}: its rows have per-row authority, so a uniform-authority PASS would bypass the tier requirement; select the "
                "tier column in the serving capability instead")
    return None


def validate_density_facet_declaration(where: str, e: dict) -> None:
    bad = density_facet_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.{bad}" if bad.startswith("density_facet") else f"{where}.density_facet: {bad}")


# `has_writer` (N-150 R5, REGISTRY_REVISION 26): the declared fact that the asset has NO writer (a service, a static or dormant asset). The only value that means anything is `false`: with it AND the
# registry row agreeing (has_writer false, no @register found) the Build.registered / Build.contract / Build.exercised / Idem.pattern N/A reads released (causes no-writer-registry-agrees,
# never-run-no-writer, never-executed-no-writer); a declaration the registry or the code contradicts releases nothing, and a registry-only no-writer asset (no declaration) keeps reading NO_DETECTOR.
def has_writer_problem(entry):
    """None when `entry` has no `has_writer` or `false`; else why it is refused (only `false` is a declaration: `true` says nothing a release could rest on)."""
    if not isinstance(entry, dict) or entry.get("has_writer") is None:
        return None
    return None if entry["has_writer"] is False else f"has_writer must be false or absent (the declared fact that the asset has no writer), got {entry['has_writer']!r}"


# `lint_none` (N-150 R2, REGISTRY_REVISION 26): the declared form of "the narration lints do not apply to this asset's writer". An asset that declares prose columns but whose writer scope selects
# no chart_facts by fact_category and writes no column the raw-token lint's field pattern covers has nothing for either lint to read: Narr.lint then reads N/A (cause lint-not-applicable) ONLY
# when the asset DECLARES this AND the lint scan's own surface test agrees (applied == [], at least one writer file scanned, no violation). A declaration the scan contradicts (a surface exists)
# reads NO_DETECTOR naming the surface, never N/A and never a PASS; an undeclared asset keeps today's NO_DETECTOR 'not applicable'. Shape: {why, evidence}.
# SS 2026-10-05 (Idem update-only): `update_only` declares "this asset's writer rebuilds its own table(s) by UPDATE in place, by intent": {why, evidence}. Released to N/A ONLY when the writer scope
# the scan reads holds UPDATE statements on the asset's own tables and no INSERT, no upsert, no DELETE / TRUNCATE of them, no dynamic or cut statement, and no accumulating assignment; any other
# statement contradicts the declaration (NO_DETECTOR, the disagreement named), and a measured FAIL (an accumulating assignment, a hold) is never excused by it.
UPDATE_ONLY_DECL_FIELDS = ("why", "evidence")
LINT_NONE_DECL_FIELDS = ("why", "evidence")


def lint_none_problem(entry):
    """None when `entry` has no `lint_none` or a sound one (SHAPE only; the scan agreement is the detector's); else why it is refused. `why` a real one-line reason that names what the writer scope
    lacks (the word 'chart_facts', 'fact_category', 'lint' or 'narrative'); `evidence` a real repo-relative file:LINE (never `unverified:`)."""
    if not isinstance(entry, dict) or entry.get("lint_none") is None:
        return None
    d = entry["lint_none"]
    if not isinstance(d, dict):
        return "lint_none must be an object {why, evidence} (omit the key to declare none)"
    extra = sorted(set(d) - set(LINT_NONE_DECL_FIELDS))
    if extra:
        return f"lint_none: unknown field(s) {extra}"
    missing = [f for f in LINT_NONE_DECL_FIELDS if f not in d]
    if missing:
        return f"lint_none: missing field(s) {missing}"
    bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
    if bad:
        return f"lint_none.why {bad} (why neither narration lint has a surface in this writer)"
    if not any(w in d["why"].casefold() for w in ("chart_facts", "fact_category", "lint", "narrative")):
        return f"lint_none.why must say what the writer scope lacks (chart_facts / fact_category selection, a raw-token narrative column): {d['why']!r}"
    ev = d["evidence"]
    if isinstance(ev, str) and ev.startswith("unverified:"):
        return "lint_none.evidence may not be `unverified:`: a declaration that releases a check must point at a real file:line the reviewer read"
    bad = _s3_evidence_problem(ev, allow_unverified=False)
    if bad:
        return f"lint_none.evidence {ev!r} {bad}"
    if not re.search(r":[0-9]+$", ev):
        return f"lint_none.evidence {ev!r} must name a line (repo-relative file:LINE)"
    return None


# SS 2026-10-05 (no-table-no-prose): `no_table: {why, evidence}` declares "this asset is a service that owns no table, so it has no column that could carry prose and no declared key of a non-empty table".
# Released to N/A (cause no-table-no-prose) for the seven checks whose own applicability text needs a table (Narr x4, Null x2, Vocab.identity) ONLY when the declaration, the asset's declared `has_writer: false`,
# its declared kind `service`, the registry asset_kind `service`, an empty target_table and no count_sql table, no @register class and no `register(` call all agree; any disagreement reads NO_DETECTOR.
NO_TABLE_DECL_FIELDS = ("why", "evidence")
NO_TABLE_CRITERIA = ("Narr.agree", "Narr.checkable", "Narr.fidelity_test", "Narr.lint", "Null.schema_default", "Null.blank_rows", "Vocab.identity")
NO_TABLE_CAUSE = "no-table-no-prose"


def no_table_problem(entry):
    """None when `entry` has no `no_table` or a sound one (SHAPE only); else why it is refused. `why` a real one-line reason that says the asset owns no table; `evidence` a real repo-relative file:LINE."""
    if not isinstance(entry, dict) or entry.get("no_table") is None:
        return None
    d = entry["no_table"]
    if not isinstance(d, dict):
        return "no_table must be an object {why, evidence} (omit the key to declare none)"
    extra = sorted(set(d) - set(NO_TABLE_DECL_FIELDS))
    if extra:
        return f"no_table: unknown field(s) {extra}"
    missing = [f for f in NO_TABLE_DECL_FIELDS if f not in d]
    if missing:
        return f"no_table: missing field(s) {missing}"
    bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
    if bad:
        return f"no_table.why {bad} (why this asset owns no table)"
    if "table" not in d["why"].casefold():
        return f"no_table.why must say the asset owns no table: {d['why']!r}"
    ev = d["evidence"]
    if isinstance(ev, str) and ev.startswith("unverified:"):
        return "no_table.evidence may not be `unverified:`: a declaration that releases a check must point at a real file:line the reviewer read"
    bad = _s3_evidence_problem(ev, allow_unverified=False)
    if bad:
        return f"no_table.evidence {ev!r} {bad}"
    if not re.search(r":[0-9]+$", ev):
        return f"no_table.evidence {ev!r} must name a line (repo-relative file:LINE)"
    if entry.get("has_writer") is not False:
        return "no_table needs the asset to declare `has_writer: false` (a writer-backed asset owns a table)"
    if entry.get("kind") != "service":
        return f"no_table needs the asset's declared kind to be `service` (this one declares {entry.get('kind')!r})"
    if entry.get("prose_fields") or entry.get("prose_none") is not None or entry.get("prose_coupling") is not None:
        return "no_table is for an asset that declares no prose at all (no prose_fields entry, prose_none or prose_coupling)"
    return None


def validate_no_table_declaration(where: str, e: dict) -> None:
    bad = no_table_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.{bad}" if bad.startswith("no_table") else f"{where}.no_table: {bad}")


def no_table_block(entry, asset_kind, registry_has_writer, target_table, count_tables, register_files, register_mentions) -> dict:
    """The facts a no-table-no-prose release rests on, as measured (pure)."""
    return dict(declared=isinstance(entry, dict) and entry.get("no_table") is not None and no_table_problem(entry) is None,
                has_writer_declared_false=isinstance(entry, dict) and entry.get("has_writer") is False,
                declared_kind=(entry or {}).get("kind") if isinstance(entry, dict) else None, registry_asset_kind=asset_kind,
                registry_has_writer=bool(registry_has_writer), target_table=target_table or None, count_tables=sorted(t for t in (count_tables or []) if t),
                register_files=register_files, register_mentions=list(register_mentions or []))


def no_table_block_problem(b) -> str | None:
    """None when `b` shows every fact agreeing; else the first that does not (pure)."""
    if not isinstance(b, dict):
        return "no block"
    checks = (("declared", b.get("declared") is True), ("has_writer: false is declared", b.get("has_writer_declared_false") is True), ("the declared kind is service", b.get("declared_kind") == "service"),
              ("the registry asset_kind is service", b.get("registry_asset_kind") == "service"), ("the registry says has_writer false", b.get("registry_has_writer") is False),
              ("the registry target_table is empty", not b.get("target_table")), ("no count_sql table is named", b.get("count_tables") == []),
              ("no @register class exists", b.get("register_files") == 0), ("no register( call names the asset", b.get("register_mentions") == []))
    for what, ok in checks:
        if not ok:
            return what
    return None


def no_table_records(aid: str, entry, block: dict) -> dict:
    """The seven records of a service that declares `no_table` (pure): N/A with the checked block when every fact agrees, else NO_DETECTOR naming the disagreement. {} for an asset that does not declare it."""
    if not isinstance(entry, dict) or entry.get("no_table") is None:
        return {}
    bad = no_table_block_problem(block)
    nt = entry["no_table"]
    if bad:
        rec = lambda: dict(v=NO_DET, no_table=dict(block), declaration_disagreements=[bad],
                           measured=f"NO_DETECTOR — {aid} declares no_table but the check that {bad} does not hold: a declaration the registry or the code contradicts is not a release")
        return {c: rec() for c in NO_TABLE_CRITERIA}
    return {c: dict(_na(f"no table, no prose (declared, reviewed, evidence: {nt.get('evidence')}): {nt.get('why')}; the registry row, the declared kind and the @register scan agree: a service that owns no table has no column that could carry prose, "
                        "and no declared key of a non-empty table", "no-table-no-prose"), no_table=dict(block)) for c in NO_TABLE_CRITERIA}


def no_table_na_problem(crit: str, meas) -> str | None:
    """None unless a no-table-no-prose N/A is NOT backed by the agreeing block (pure; read by `_check_contribution` and `_na_released`)."""
    if crit not in NO_TABLE_CRITERIA or not isinstance(meas, dict) or meas.get("v") != NA or meas.get("cause") != NO_TABLE_CAUSE:
        return None
    if no_table_block_problem(meas.get("no_table")) is not None:
        return (f"{crit} N/A rests on a declared no_table that the registry and the code agree with (SS 2026-10-05): this record does not carry the agreeing block "
                "(has_writer false, service kind, no table, no @register), so the declaration alone is not a release")
    return None


def update_only_problem(entry):
    """None when `entry` has no `update_only` or a sound one (SHAPE only; the scan agreement is the detector's); else why it is refused. `why` a real one-line reason that says the writer UPDATEs its
    own table(s) in place; `evidence` a real repo-relative file:LINE (never `unverified:`)."""
    if not isinstance(entry, dict) or entry.get("update_only") is None:
        return None
    d = entry["update_only"]
    if not isinstance(d, dict):
        return "update_only must be an object {why, evidence} (omit the key to declare none)"
    extra = sorted(set(d) - set(UPDATE_ONLY_DECL_FIELDS))
    if extra:
        return f"update_only: unknown field(s) {extra}"
    missing = [f for f in UPDATE_ONLY_DECL_FIELDS if f not in d]
    if missing:
        return f"update_only: missing field(s) {missing}"
    bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
    if bad:
        return f"update_only.why {bad} (why this writer rebuilds its own table by UPDATE in place)"
    if "update" not in d["why"].casefold():
        return f"update_only.why must say the writer UPDATEs its own table(s) in place: {d['why']!r}"
    if entry.get("produced_tables") is not None:
        return ("update_only is judged on the asset's own table(s) (its target table and its count_sql tables) only; an asset that declares produced_tables writes tables the scan would not judge, "
                "so a declared update-only intent cannot stand beside a produced set (declare one or the other)")
    ev = d["evidence"]
    if isinstance(ev, str) and ev.startswith("unverified:"):
        return "update_only.evidence may not be `unverified:`: a declaration that releases a check must point at a real file:line the reviewer read"
    bad = _s3_evidence_problem(ev, allow_unverified=False)
    if bad:
        return f"update_only.evidence {ev!r} {bad}"
    if not re.search(r":[0-9]+$", ev):
        return f"update_only.evidence {ev!r} must name a line (repo-relative file:LINE)"
    return None


def validate_update_only_declaration(where: str, e: dict) -> None:
    bad = update_only_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.{bad}" if bad.startswith("update_only") else f"{where}.update_only: {bad}")


def validate_lint_none_declaration(where: str, e: dict) -> None:
    bad = lint_none_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.{bad}" if bad.startswith("lint_none") else f"{where}.lint_none: {bad}")


_DECL_ENTRY_KEYS = ("kind", "carriage", "prose_fields", "terminal_by_construction", "cross_asset_writes",
                    "read_evidence", "read_table", "read_kind", "evidence", "evidence_kind", "vocab_alias", "ldgr_source", "null_convention",
                    "prose_coupling", "density_tier_columns", "source", "prose_none", "produced_tables", "density_facet", "uniform_authority", "service_probe", "zero_row_convention", "lint_none", "has_writer", "update_only", "no_table", "static_data", "probe_attempts")
_DECL_EVIDENCE_KEYS = ("kind", "carriage", "prose_fields", "cross_asset_writes")
# E5.7 (Worker E, SS N-150 R7): `fidelity_tests` declares the golden-value test(s) of the asset's narration builder: [{test: "platform/python-sidecar/<...>/test_x.py::[Class::]test_name",
# covers: [<declared prose entries>]}]. The census VERIFIES each from the test's source (golden_test_scan.py); the declaration names, it never decides.
DECL_FIDELITY_KEYS = ("fidelity_tests",)
FIDELITY_TEST_FIELDS = ("test", "covers")
MAX_FIDELITY_TESTS = 16
_FIDELITY_REF_RE = re.compile(r"platform/python-sidecar/[A-Za-z0-9_./-]+\.py::[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)?")


# ───────────────────────── E5.7 W2 (SS rulings 2026-10-06): the declared prose EXCLUSION and the closed-values LABEL forms ─────────────────────────
DECL_E57_KEYS = ("prose_excluded", "label_columns")
DECISIONS_REGISTER_PATH = ROOT / "00_ARCHITECTURE" / "control" / "suvarna" / "state" / "DECISIONS.jsonl"
PROSE_EXCLUSION_DECISIONS_PATH = Path(__file__).resolve().parent / "prose_exclusion_decisions.json"
PROSE_EXCLUDED_FIELDS = ("column", "decision_id", "why")
PROSE_EXCLUDED_OPTIONAL = ("table",)       # the owned table the column is excluded on; absent = the asset's TARGET table (an exclusion is never by bare column name)
MAX_PROSE_EXCLUDED = 8
LABEL_COLUMN_FIELDS = ("column", "values", "why", "evidence")
MAX_LABEL_COLUMNS = 16
MAX_LABEL_VALUES = 64


def load_decisions_register(path=None) -> dict:
    """{decision id: the latest committed record} of the append-only decisions register (DECISIONS.jsonl, one JSON object per line, the first line the schema). A record is USABLE only when its
    state is `decided` and no other decided record `supersedes` it (the register's own correction rule). Raises DeclarationsError when the file cannot be read."""
    p = Path(path) if path is not None else DECISIONS_REGISTER_PATH
    try:
        lines = p.read_text(encoding="utf-8").splitlines()
    except (OSError, ValueError) as exc:
        raise DeclarationsError(f"cannot read the decisions register {p}: {exc}") from exc
    recs: dict = {}
    for ln in lines[1:]:
        if not ln.strip():
            continue
        try:
            r = json.loads(ln)
        except json.JSONDecodeError as exc:
            raise DeclarationsError(f"the decisions register {p} holds a line that is not JSON: {exc}") from exc
        if isinstance(r, dict) and isinstance(r.get("id"), str):
            recs[r["id"]] = r
    sup = {r.get("supersedes") for r in recs.values() if r.get("state") == "decided" and isinstance(r.get("supersedes"), str)}
    return {i: r for i, r in recs.items() if r.get("state") == "decided" and i not in sup}


def load_prose_exclusion_decisions(path=None) -> dict:
    """{decision id: {(asset, column)}}: the DECLINES the committed table prose_exclusion_decisions.json records per decision id (the citation_human sweep of N-49, one row per declined asset and
    column). Raises DeclarationsError on a missing or malformed file."""
    p = Path(path) if path is not None else PROSE_EXCLUSION_DECISIONS_PATH
    try:
        doc = json.loads(p.read_text(encoding="utf-8"))
        return {did: {(d["asset"], d["column"]) for d in rec["declines"]} for did, rec in doc["decisions"].items()}
    except (OSError, ValueError, KeyError, TypeError) as exc:
        raise DeclarationsError(f"cannot read the prose-exclusion decisions {p}: {exc}") from exc


def prose_excluded_problem(aid, entry, register=None, decisions=None):
    """None when `entry` has no `prose_excluded` or a sound, CHECKED one; else why it is refused. Sound: a list of 1..MAX_PROSE_EXCLUDED objects with exactly the fields column / decision_id / why;
    `column` an identifier, listed once, and NOT a declared prose entry of the asset (an exclusion on a column that IS declared prose is a contradiction); `why` a real reason; `decision_id` an id of
    the committed decisions register (usable: decided, not superseded) that DECLINES this asset's column (prose_exclusion_decisions.json). The detector re-checks all of it at measure time and also
    that the column exists on the asset's table."""
    if not isinstance(entry, dict) or entry.get("prose_excluded") is None:
        return None
    pe = entry["prose_excluded"]
    if not (isinstance(pe, list) and 1 <= len(pe) <= MAX_PROSE_EXCLUDED):
        return f"prose_excluded must be a list of 1 to {MAX_PROSE_EXCLUDED} objects"
    reg = load_decisions_register() if register is None else register
    dec = load_prose_exclusion_decisions() if decisions is None else decisions
    declared = {parse_prose_field(f)[0] for f in (entry.get("prose_fields") or []) if isinstance(f, str)}
    seen = set()
    for i, d in enumerate(pe):
        lab = f"prose_excluded[{i}]"
        if not isinstance(d, dict) or not set(PROSE_EXCLUDED_FIELDS) <= set(d) <= set(PROSE_EXCLUDED_FIELDS) | set(PROSE_EXCLUDED_OPTIONAL):
            return f"{lab} must be an object with the fields {list(PROSE_EXCLUDED_FIELDS)} (and optionally {list(PROSE_EXCLUDED_OPTIONAL)})"
        if d.get("table") is not None and not (isinstance(d["table"], str) and _DECL_IDENT.fullmatch(d["table"])):
            return f"{lab}.table must be a table name (an identifier)"
        if not (isinstance(d["column"], str) and _DECL_IDENT.fullmatch(d["column"])):
            return f"{lab}.column must be a column name (an identifier)"
        if d["column"] in seen:
            return f"{lab}: {d['column']} is excluded twice"
        seen.add(d["column"])
        if d["column"] in declared:
            return f"{lab}: {d['column']} is declared prose (prose_fields) and cannot also be excluded from it"
        bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
        if bad:
            return f"{lab}.why {bad}"
        did = d["decision_id"]
        if not (isinstance(did, str) and did in reg):
            return f"{lab}.decision_id {did!r} is not a usable decision of the committed decisions register (decided, not superseded)"
        if (aid, d["column"]) not in dec.get(did, set()):
            return f"{lab}: decision {did} is not a recorded decline of {aid}.{d['column']} (prose_exclusion_decisions.json)"
    return None


def validate_prose_excluded_declaration(where: str, aid: str, e: dict) -> None:
    bad = prose_excluded_problem(aid, e)
    if bad:
        raise DeclarationsError(f"{where}.prose_excluded: {bad}")


def label_columns_problem(entry):
    """None when `entry` has no `label_columns` or a sound one; else why it is refused. Sound: a list of 1..MAX_LABEL_COLUMNS objects {column, values, why, evidence}: `column` a prose-field style entry
    (a column, or `col.$.key` JSON path) of a GRADED LABEL the writer stores (one word of a closed vocabulary, not a sentence); `values` a NON-EMPTY list of 1..MAX_LABEL_VALUES distinct plain
    strings; `why` a real reason; `evidence` a repo-relative `path:LINE` naming the writer line the vocabulary comes from. The entry's column is never also a prose_fields entry."""
    if not isinstance(entry, dict) or entry.get("label_columns") is None:
        return None
    lc = entry["label_columns"]
    if not (isinstance(lc, list) and 1 <= len(lc) <= MAX_LABEL_COLUMNS):
        return f"label_columns must be a non-empty list of at most {MAX_LABEL_COLUMNS} objects"
    declared = set(entry.get("prose_fields") or [])
    seen = set()
    for i, d in enumerate(lc):
        lab = f"label_columns[{i}]"
        if not isinstance(d, dict) or set(d) != set(LABEL_COLUMN_FIELDS):
            return f"{lab} must be an object with exactly the fields {list(LABEL_COLUMN_FIELDS)}"
        try:
            parse_prose_field(d["column"])
        except DeclarationsError as exc:
            return f"{lab}.column: {exc}"
        if d["column"] in seen:
            return f"{lab}: {d['column']} is listed twice"
        seen.add(d["column"])
        if d["column"] in declared:
            return f"{lab}: {d['column']} is a prose_fields entry (a label column is a different declaration)"
        vs = d["values"]
        if not (isinstance(vs, list) and 1 <= len(vs) <= MAX_LABEL_VALUES and len(set(vs)) == len(vs)
                and all(isinstance(v, str) and v.strip() and v == v.strip() and len(v) <= 80 and "'" not in v and "\\" not in v for v in vs)):
            return f"{lab}.values must be a NON-EMPTY list of 1 to {MAX_LABEL_VALUES} distinct plain strings (at most 80 characters, no quote or backslash); an empty vocabulary closes nothing"
        bad = _s3_text_problem(d["why"], min_chars=15, min_words=3)
        if bad:
            return f"{lab}.why {bad}"
        bad = _s3_evidence_problem(d["evidence"], allow_unverified=False)
        if bad:
            return f"{lab}.evidence {d['evidence']!r} {bad}"
        if not re.search(r":[0-9]+$", str(d["evidence"])):
            return f"{lab}.evidence {d['evidence']!r} must name a line (repo-relative file:LINE)"
    return None


def validate_label_columns_declaration(where: str, e: dict) -> None:
    bad = label_columns_problem(e)
    if bad:
        raise DeclarationsError(f"{where}.label_columns: {bad}")


def checked_prose_exclusions(aid: str, decl, own: dict, target=None, register=None, decisions=None):
    """The measure-time CHECK of a declared `prose_excluded` (pure): (applied, block, fail text | None, unread text | None). `applied` is a set of lower-case `table.column` PAIRS (never a bare column
    name: an exclusion on one table must not hide a same-named write into another). The entry's table is its `table` (an owned table) or, absent, the asset's TARGET table `target`. Re-validates the
    declaration (decision usable and a decline of this asset column, column not prose), then requires the column to exist among the KNOWN columns of that table. A column the table does not carry
    (its columns known) is a contradiction (`fail`); a table whose columns are unknown leaves the exclusion unapplied (`unread`)."""
    pe = decl.get("prose_excluded") if isinstance(decl, dict) else None
    if pe is None:
        return set(), None, None, None
    bad = prose_excluded_problem(aid, decl, register, decisions)
    if bad:
        return set(), None, f"declared prose_excluded refused: {bad}", None
    applied, rows, missing, unread = set(), [], [], []
    for d in pe:
        t = d.get("table") or target
        low = {k.lower(): k for k in own}
        if not t or t.lower() not in low:
            missing.append(f"{d['column']} (table {t!r} is not an owned table)")
            continue
        cols = own[low[t.lower()]][0]
        if not (isinstance(cols, (list, tuple, set)) and cols):
            unread.append(d["column"])
        elif d["column"] in cols:
            applied.add(f"{t.lower()}.{d['column']}")
            rows.append(dict(table=t, column=d["column"], decision_id=d["decision_id"], na=True))
        else:
            missing.append(f"{d['column']} (not a column of {t})")
    if missing:
        return set(), None, f"declared prose_excluded names column(s) the asset's table does not carry: {', '.join(missing)}", None
    block = dict(checked=True, excluded=rows)
    return applied, block, None, (f"the columns of the table were not read, so the exclusion of {', '.join(unread)} is not applied" if unread else None)


# ───────────── the MEASURED-CHART scope of every live data read (SS, interim census 42e96d491, bo_chart_gestalt) ─────────────
# A check that reads DATA must judge the rows of the measured chart. bo_chart_gestalt's Narr.agree read `SELECT DISTINCT ... FROM <whole table>`: other charts' OLDER rows (built by earlier code) held a label
# the measured chart's rebuilt rows do not, and the cell judged data that is not the measured chart's. The reads below consult `_READ_SCOPE` ({table: {where, label}}), set by `measure()` for the asset it is
# measuring from `read_scopes` (chart_id = the census chart on a table that carries a chart_id column and whose registry count_sql is chart-bound or unreadable; on a table shared with other assets, also the
# asset's own rows). A table with no chart column, or one the asset's count_sql declares global, is read WHOLE and says so. Empty scope (the default; every unit test of a builder) = the SQL is byte for byte what
# it was. The scope predicate is a boolean SQL expression over the table's own columns.
_READ_SCOPE: dict = {}


def set_read_scope(scopes) -> None:
    """Install ({table: {where, label}}) the read scope the data-reading builders apply; None / {} clears it."""
    global _READ_SCOPE
    _READ_SCOPE = {str(t).strip('"').lower(): v for t, v in (scopes or {}).items() if isinstance(v, dict)}


def _scope_pred(table) -> str | None:
    v = _READ_SCOPE.get(str(table).strip('"').lower())
    return v.get("where") if v else None


def _sw(table, cond: str) -> str:
    """`cond` with the read scope of `table` ANDed on (parenthesised, so a top-level OR in `cond` cannot escape it); `cond` unchanged without a scope."""
    p = _scope_pred(table)
    return cond if not p else f"({cond}) AND ({p})"


def _scope_block(table):
    """Why a read of `table` must NOT be made (None = it may): the table's scope could not be established (columns not read) or the table holds NO rows in the measured chart's scope, so a closure /
    vocabulary / source judgment over it is vacuous (a closure over zero rows is not 'holds')."""
    v = _READ_SCOPE.get(str(table).strip('"').lower())
    return v.get("block") if v else None


def mark_empty_scopes(scopes: dict, convention_holds: bool = False) -> dict:
    """Mark (in place, and return) every SCOPED table of `scopes` that holds no row in its scope: `block` says so, and the label carries it. One EXISTS probe per scoped table (`LIMIT 1` inside; a failed or
    cancelled probe marks nothing: the reads then run and answer for themselves). `convention_holds` (a declared zero_row_convention VERIFIED for the measured chart) lifts the guard: zero rows is then the
    by-design reading for this chart."""
    if convention_holds:
        return scopes
    for t, v in scopes.items():
        if not v.get("where") or v.get("block"):
            continue
        try:
            got = scalar(f'SELECT EXISTS(SELECT 1 FROM "{t}" WHERE {v["where"]})::text')
        except Unknown:
            continue
        if got is not None and str(got).strip().lower() in ("f", "false"):
            v["empty"] = True
            v["block"] = f"the table holds NO rows in the read scope ({v['label']}): there is nothing to judge, and a closure / vocabulary / source over zero rows is vacuous, never a pass"
            v["label"] = v["label"] + "; NO ROWS in this scope"
    return scopes


def _where_scope(table) -> str:
    """` WHERE (<scope>)` for a read that has no WHERE of its own, or ''."""
    p = _scope_pred(table)
    return f" WHERE ({p})" if p else ""


def label_distinct_sql(table: str, entry: str) -> str:
    """ONE read-only query: the DISTINCT string values a declared label entry (a column, or a `col.$.key` / `[*]` JSON path) holds in `table`, at most MAX_LABEL_VALUES + 1 of them (more is not a closed
    vocabulary). A non-string leaf is not a label value and is not selected. Identifiers come from parse_prose_field (regex-validated): ValueError otherwise."""
    if not _IDENT.fullmatch(table or ""):
        raise ValueError("label_distinct_sql needs a table identifier")
    col, path = parse_prose_field(entry)
    lim = MAX_LABEL_VALUES + 1
    if path is None:
        cond = f'"{col}" IS NOT NULL'
        return f'SELECT DISTINCT "{col}"::text FROM {table} WHERE {_sw(table, cond)} LIMIT {lim}'
    if PROSE_WILDCARD in path:
        jp = "$"
        for seg in path:
            jp += "[*]" if seg == PROSE_WILDCARD else f'."{seg}"'
        cond = f"\"{col}\" IS NOT NULL AND jsonb_typeof(x) = 'string'"
        return f"SELECT DISTINCT (x #>> '{{}}') FROM {table}, jsonb_path_query(\"{col}\"::jsonb, '{jp}') AS e(x) WHERE {_sw(table, cond)} LIMIT {lim}"
    keys = ",".join(path)
    cond = f"\"{col}\" IS NOT NULL AND jsonb_typeof(\"{col}\"::jsonb #> '{{{keys}}}') = 'string'"
    return f"SELECT DISTINCT (\"{col}\"::jsonb #>> '{{{keys}}}') FROM {table} WHERE {_sw(table, cond)} LIMIT {lim}"


def grade_label_columns(entries, fetched) -> dict:
    """The Narr.agree contribution of a declared `label_columns` (pure). `fetched`: {column entry: [distinct values] | None (not read)}. FAIL: a stored value the declaration does not list (the vocabulary is
    not closed). PARTIAL: a read that did not happen, or more distinct values than the declared vocabulary can be (>= MAX_LABEL_VALUES + 1). PASS: every stored value is declared (a declared value
    never seen is ALLOWED and reported)."""
    stray, unread, unseen, ok, blocked = [], [], [], [], []
    for d in entries:
        got = fetched.get(d["column"])
        if isinstance(got, dict) and got.get("blocked"):
            blocked.append(f"{d['column']} ({got['blocked']})")
            continue
        if isinstance(got, dict):
            # the bounded existence read (the DISTINCT read was cancelled by a statement timeout): a stray value is a fact; none after a scan that reached the end of the table is a closed vocabulary
            # (which declared values were seen is unknown: no `declared_never_seen`, no total)
            if got.get("stray"):
                stray.append(f"{d['column']} holds undeclared value(s), at least {sorted(got['stray'])} (existence read: values were not aggregated, no total is stated)")
            else:
                ok.append(d["column"])
            continue
        if got is None:
            unread.append(d["column"])
            continue
        if len(got) > MAX_LABEL_VALUES:
            unread.append(f"{d['column']} (more than {MAX_LABEL_VALUES} distinct values)")
            continue
        out_of = sorted(v for v in got if v not in set(d["values"]))
        if out_of:
            stray.append(f"{d['column']} holds undeclared value(s) {out_of}")
        else:
            ok.append(d["column"])
        never = sorted(set(d["values"]) - set(got))
        if never:
            unseen.append(f"{d['column']}: {never}")
    block = dict(checked=True, closed=ok, undeclared=stray, unread=unread, declared_never_seen=unseen)
    if blocked:
        block["blocked"] = blocked
    if stray:
        return dict(v=FAIL, label_columns=block, measured="declared label column(s) hold values outside the declared closed vocabulary: " + "; ".join(stray))
    if blocked:
        return dict(v=NO_DET, label_columns=block, measured="NO_DETECTOR — the declared label column(s) were not read: " + "; ".join(blocked))
    if unread:
        return dict(v=PARTIAL, label_columns=block, measured="the declared label vocabulary was not read for " + ", ".join(unread))
    note = f"declared label column(s) {', '.join(ok)} hold only declared values"
    return dict(v=PASS, label_columns=block, measured=note + (f" (declared but never seen, allowed: {'; '.join(unseen)})" if unseen else ""))


def label_fetch_distinct(table: str, entry: str) -> list:
    """The distinct values of a label entry, read-only. Raises Unknown on a failed read."""
    rows = psql(label_distinct_sql(table, entry)) or []
    return [r[0] for r in rows if r and r[0] is not None]


def label_read(table: str, entry: str, values):
    """One label entry's reading for `grade_label_columns`: the DISTINCT values (a list) while the table is small; when that read is cancelled by a statement timeout, the bounded stray read (a dict); None when the
    read did not happen (a timeout again, or any other failure: the entry reads PARTIAL 'not read', as before). Never raises."""
    blk = _scope_block(table)
    if blk:
        return dict(blocked=blk)
    try:
        return label_fetch_distinct(table, entry)
    except (Unknown, ValueError, OSError) as exc:
        if not _is_statement_timeout(exc):
            return None
    try:
        return label_fetch_stray(table, entry, values)
    except (Unknown, ValueError, OSError):
        return None


def label_stray_sql(table: str, entry: str, values) -> str:
    """The bounded twin of `label_distinct_sql` (pure): up to PROSE_NONE_SAMPLE_LIMIT stored string values of the label entry that are NOT in `values`, each cut to PROSE_NONE_SAMPLE_CHARS characters. A scan
    that stops at the first such rows (LIMIT, no DISTINCT, no ORDER BY) instead of aggregating every distinct value of the table. Identifiers come from parse_prose_field (ValueError otherwise)."""
    if not _IDENT.fullmatch(table or ""):
        raise ValueError("label_stray_sql needs a table identifier")
    col, path = parse_prose_field(entry)
    arr = "ARRAY[" + ",".join(_sql_lit(v) for v in values) + "]::text[]"
    lim, cut = PROSE_NONE_SAMPLE_LIMIT, PROSE_NONE_SAMPLE_CHARS
    if path is None:
        cond = f'"{col}" IS NOT NULL AND "{col}"::text <> ALL({arr})'
        return f'SELECT left("{col}"::text, {cut}) FROM {table} WHERE {_sw(table, cond)} LIMIT {lim}'
    if PROSE_WILDCARD in path:
        jp = "$"
        for seg in path:
            jp += "[*]" if seg == PROSE_WILDCARD else f'."{seg}"'
        cond = f"\"{col}\" IS NOT NULL AND jsonb_typeof(x) = 'string' AND (x #>> '{{}}') <> ALL({arr})"
        return f"SELECT left(x #>> '{{}}', {cut}) FROM {table}, jsonb_path_query(\"{col}\"::jsonb, '{jp}') AS e(x) WHERE {_sw(table, cond)} LIMIT {lim}"
    keys = ",".join(path)
    cond = f"\"{col}\" IS NOT NULL AND jsonb_typeof(\"{col}\"::jsonb #> '{{{keys}}}') = 'string' AND (\"{col}\"::jsonb #>> '{{{keys}}}') <> ALL({arr})"
    return f"SELECT left(\"{col}\"::jsonb #>> '{{{keys}}}', {cut}) FROM {table} WHERE {_sw(table, cond)} LIMIT {lim}"


def label_fetch_stray(table: str, entry: str, values) -> dict:
    """{stray: [up to PROSE_NONE_SAMPLE_LIMIT undeclared stored values], bounded: True}: the existence read of a label entry, used when the exact DISTINCT read was cancelled by a statement
    timeout. A stray value is a fact (FAIL); an empty answer after a scan that reached the end of the table is a closed vocabulary. Raises Unknown on a failed (or timed-out) read."""
    rows = psql(label_stray_sql(table, entry, values)) or []
    return dict(stray=[r[0] for r in rows if r and r[0] is not None], bounded=True)


def validate_fidelity_tests_declaration(where: str, ft, e: dict) -> None:
    """Raises DeclarationsError when `fidelity_tests` is not a list of {test, covers}: a sidecar test file `::` test (optionally `::Class::test`), and the distinct declared prose entries it covers.
    Needs a non-empty `prose_fields` (the golden test is a claim about the declared narration)."""
    pf = e.get("prose_fields")
    if not (isinstance(pf, list) and pf):
        raise DeclarationsError(f"{where}.fidelity_tests needs a non-empty prose_fields (the golden test is a claim about the declared narration)")
    if not (isinstance(ft, list) and ft and len(ft) <= MAX_FIDELITY_TESTS):
        raise DeclarationsError(f"{where}.fidelity_tests must be a non-empty list of at most {MAX_FIDELITY_TESTS} {{test, covers}} entries")
    seen = set()
    for i, d in enumerate(ft):
        w = f"{where}.fidelity_tests[{i}]"
        if not isinstance(d, dict) or set(d) != set(FIDELITY_TEST_FIELDS):
            raise DeclarationsError(f"{w} must be an object with exactly the fields {list(FIDELITY_TEST_FIELDS)}")
        t = d["test"]
        if not (isinstance(t, str) and _FIDELITY_REF_RE.fullmatch(t)) or ".." in t.split("::")[0].split("/"):
            raise DeclarationsError(f"{w}.test must be 'platform/python-sidecar/<path>.py::[Class::]test_name'")
        if not _EVIDENCE_TEST_PATH_RE.search(t.split("::")[0]):
            raise DeclarationsError(f"{w}.test: {t.split('::')[0]} is not a test file path")
        if t in seen:
            raise DeclarationsError(f"{w}.test {t!r} is declared twice")
        seen.add(t)
        cv = d["covers"]
        if not (isinstance(cv, list) and cv and len(set(cv)) == len(cv) and all(isinstance(c, str) and c in pf for c in cv)):
            raise DeclarationsError(f"{w}.covers must be a non-empty list of distinct entries of this asset's prose_fields")
# prose_fields entries (SS ruling 2026-10-01; CLAUDE.md N.7 concerns GENERATED prose): a column name, or a JSON path into
# a JSONB column, `column.$.seg(.seg)*` where a seg is an identifier key, optionally followed by ONE `[*]` (every element
# of the array at that key; grammar 1.6.0). No index numbers, no `[*][*]`, no `[*]` on the column itself, no quoting.
# Used with fullmatch.
PROSE_IDENT_MAX = 128          # a column name / JSON key longer than this is not an identifier anyone declared on purpose
_PROSE_COLUMN_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_PROSE_PATH_RE = re.compile(r"([A-Za-z_][A-Za-z0-9_]*)\.\$((?:\.[A-Za-z_][A-Za-z0-9_]*(?:\[\*\])?)+)")
PROSE_WILDCARD = "[*]"         # the path-tuple token for an array-element segment (not a valid identifier: no key collides)
# evidence.prose_fields must cite writer code as `path.ext:LINE` (py/ts/tsx; never .sql, never a test path) and carries
# `evidence_kind: "writer"`; a declaration that cites the column's DDL migration instead is marked `evidence_kind: "ddl"` (it then
# needs a `NNN_name.sql` token, no line). An unmarked (null) kind gets the same cite checks as "writer".
EVIDENCE_PATH_LINE_RE = re.compile(r"[A-Za-z0-9_][A-Za-z0-9_./\[\]@-]*\.(?:py|ts|tsx):[1-9][0-9]*")
_EVIDENCE_SQL_LINE_RE = re.compile(r"[A-Za-z0-9_][A-Za-z0-9_./\[\]@-]*\.sql:[1-9][0-9]*")
_EVIDENCE_ANY_CITE_RE = re.compile(r"([A-Za-z0-9_][A-Za-z0-9_./\[\]@-]*\.(?:py|ts|tsx)):[1-9][0-9]*")
_EVIDENCE_TEST_PATH_RE = re.compile(r"(^|/)(__tests__|tests?|fixtures)/|(^|/)test_[^/]*$|_test\.py$|\.(test|spec)\.tsx?$")
EVIDENCE_KINDS = ("ddl", "writer")
_DDL_EVIDENCE_RE = re.compile(r"[0-9]+_[A-Za-z0-9_]+\.sql")


def _blank_text(s) -> bool:
    """True for a string with no visible character: empty, whitespace, control, or invisible format/separator code points
    (zero-width space/joiner, BOM, word joiner, no-break and other Unicode spaces), which str.strip() alone does not remove."""
    return all(unicodedata.category(ch)[0] in ("Z", "C") for ch in s)


_CROSS_WRITE_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*")   # table.column; used with fullmatch
# `served_surface: true` needs a real read: `read_evidence` is a repo-relative `path:line` (1-based) and `read_table` the
# identifier that line reads FROM/JOINs (a test opens the file and checks the line); neither may exist otherwise.
# Served TypeScript only (platform/src or platform-mcp/src, .ts/.tsx; no Python, no scripts); components are never
# '.'/'..' (checked in validate_declarations) and never match _READ_EVIDENCE_EXCLUDED_RE.
_READ_EVIDENCE_RE = re.compile(r"(?:platform|platform-mcp)/src/[A-Za-z0-9_.\[\]@-]+(?:/[A-Za-z0-9_.\[\]@-]+)*\.tsx?:[1-9][0-9]*")
# paths that can never be a served read: tests/specs/mocks/e2e/fixtures/generated, the availability probe, the
# api/mcp/db/query table allow-list (a component match anywhere, with or without a leading directory)
_READ_EVIDENCE_EXCLUDED_RE = re.compile(
    r"(?:(?:^|/)(?:__tests__|__mocks__|tests?|e2e|fixtures|generated)/|\.(?:test|spec)\.[A-Za-z]+:?|"
    r"source_query_availability|(?:^|/)mcp/db/query/)")
READ_KINDS = ("coverage", "projection", "table_map")   # None = a row-level SQL read (the default); see declared_facts
_READ_TABLE_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


class DeclarationsError(ValueError):
    """The declarations file (or a document handed to validate_declarations) is malformed."""


def parse_prose_field(entry):
    """One `prose_fields` entry -> (column, path): `"narrative"` -> ("narrative", None);
    `"narrative.$.headline"` -> ("narrative", ("headline",)) (the JSON path of a composed string inside a JSONB column,
    which is what a Narr detector reads); `"d.$.a[*].b"` -> ("d", ("a", "[*]", "b")) (`[*]` = every element of the array
    at `a`, carried as the token "[*]"). Raises DeclarationsError on anything else (a blank, a non-string, a table
    prefix, `col.$` with no key, an index number, `[*][*]`, `[*]` on the column itself, a column that does not look like
    a column name)."""
    if isinstance(entry, str):
        if _PROSE_COLUMN_RE.fullmatch(entry):
            if len(entry) <= PROSE_IDENT_MAX:
                return entry, None
        else:
            m = _PROSE_PATH_RE.fullmatch(entry)
            if m:
                path = []
                for seg in m.group(2).split(".")[1:]:
                    wild = seg.endswith(PROSE_WILDCARD)
                    path.append(seg[:-len(PROSE_WILDCARD)] if wild else seg)
                    if wild:
                        path.append(PROSE_WILDCARD)
                path = tuple(path)
                if len(m.group(1)) <= PROSE_IDENT_MAX and all(len(k) <= PROSE_IDENT_MAX for k in path):
                    return m.group(1), path
    raise DeclarationsError(f"prose_fields entry {entry!r} must be a column name or 'column.$.key(.key)*' "
                            f"(a JSON path into a JSONB column; keys are plain identifiers, each optionally followed by one [*])")


def _registry_id_set(registry_ids):
    if registry_ids is None:
        return None
    if not isinstance(registry_ids, (list, tuple, set, frozenset)) or not all(isinstance(i, str) for i in registry_ids):
        raise DeclarationsError("registry_ids must be a list/tuple/set of asset-id strings (a bare string or other "
                                "iterable would silently change what `in` means)")
    return set(registry_ids)


def _decl_pairs(pairs):
    seen = {}
    for k, v in pairs:
        if k in seen:
            raise DeclarationsError(f"duplicate key {k!r} in the declarations file")
        seen[k] = v
    return seen


def validate_declarations(doc, registry_ids=None) -> dict:
    """Validate a declarations document and return its `assets` mapping (asset_id -> entry). Raises
    DeclarationsError naming the offending asset/field. `registry_ids` (an iterable of asset ids), when given, is the
    census registry set: a declared asset id outside it is an error (a typo must not become a silent UNKNOWN); it
    must be a list/tuple/set of strings, anything else is a DeclarationsError."""
    if not isinstance(doc, dict):
        raise DeclarationsError("declarations document must be a JSON object")
    if not isinstance(doc.get("version"), str) or not doc["version"].strip():
        raise DeclarationsError("`version` must be a non-empty string")
    if doc.get("kind_enum") != list(DECLARED_KINDS):
        raise DeclarationsError(f"`kind_enum` must be exactly {list(DECLARED_KINDS)}, got {doc.get('kind_enum')!r}")
    assets = doc.get("assets")
    if not isinstance(assets, dict):
        raise DeclarationsError("`assets` must be an object mapping asset_id to a declaration")
    if "carriage_declaration_fields" in doc and doc["carriage_declaration_fields"] != list(CARRIAGE_DECL_FIELDS):
        raise DeclarationsError(f"`carriage_declaration_fields` must be exactly {list(CARRIAGE_DECL_FIELDS)}")
    for _fk, _fv in (("vocab_alias_declaration_fields", VOCAB_ALIAS_DECL_FIELDS), ("ldgr_source_declaration_fields", LDGR_SOURCE_DECL_FIELDS),
                     ("null_convention_declaration_fields", NULL_CONVENTION_DECL_FIELDS),
                     ("prose_coupling_declaration_fields", PROSE_COUPLING_DECL_FIELDS),
                     ("density_tier_declaration_fields", DENS_TIER_DECL_FIELDS), ("source_declaration_fields", SOURCE_DECL_FIELDS),
                     ("source_column_declaration_fields", SOURCE_COLUMN_FIELDS), ("prose_none_declaration_fields", PROSE_NONE_DECL_FIELDS),
                     ("prose_none_column_declaration_fields", PROSE_NONE_COLUMN_FIELDS), ("produced_table_declaration_fields", PRODUCED_TABLE_FIELDS),
                     ("service_probe_declaration_fields", SERVICE_PROBE_DECL_FIELDS),
                     ("zero_row_convention_declaration_fields", ZERO_ROW_DECL_FIELDS),
                     ("static_data_declaration_fields", STATIC_DATA_DECL_FIELDS),
                     ("probe_attempts_declaration_fields", PROBE_ATTEMPTS_DECL_FIELDS)):
        if _fk in doc and doc[_fk] != list(_fv):
            raise DeclarationsError(f"`{_fk}` must be exactly {list(_fv)}")
    known = _registry_id_set(registry_ids)
    for aid, e in assets.items():
        where = f"assets[{aid!r}]"
        if not isinstance(aid, str) or not aid.strip():
            raise DeclarationsError(f"{where}: asset id must be a non-empty string")
        if known is not None and aid not in known:
            raise DeclarationsError(f"{where}: asset id is not in the census registry set")
        if not isinstance(e, dict):
            raise DeclarationsError(f"{where}: must be an object")
        extra = sorted(set(e) - set(_DECL_ENTRY_KEYS) - set(DECL_FIDELITY_KEYS) - set(DECL_E57_KEYS) - set(DECL_N189_KEYS))
        if extra:
            raise DeclarationsError(f"{where}: unknown field(s) {extra}")
        k = e.get("kind")
        if k is not None and (not isinstance(k, str) or k not in DECLARED_KINDS):
            raise DeclarationsError(f"{where}.kind {k!r} is not one of {list(DECLARED_KINDS)} (or null = unknown)")
        car = e.get("carriage")
        if car is not None:
            if not isinstance(car, dict):
                raise DeclarationsError(f"{where}.carriage must be an object or null")
            bad = sorted(set(car) - set(CARRIAGE_FIELDS) - set(CARRIAGE_DECL_FIELDS))
            if bad:
                raise DeclarationsError(f"{where}.carriage: unknown field(s) {bad}")
            for f, v in car.items():
                if f in CARRIAGE_FIELDS and v is not None and not isinstance(v, bool):
                    raise DeclarationsError(f"{where}.carriage.{f} must be true, false or null, got {v!r}")
            if any(car.get(f) is not None for f in CARRIAGE_DECL_FIELDS):
                validate_carriage_declaration(where, car, e)
        if e.get("vocab_alias") is not None:
            validate_vocab_alias_declaration(where, e["vocab_alias"], e)
        if e.get("ldgr_source") is not None:
            validate_ldgr_source_declaration(where, e["ldgr_source"], e)
        if e.get("null_convention") is not None:
            validate_null_convention_declaration(where, e["null_convention"], e)
        if e.get("zero_row_convention") is not None:
            validate_zero_row_convention_declaration(where, e["zero_row_convention"], e)
        if e.get("static_data") is not None:
            validate_static_data_declaration(where, e["static_data"], e)
        if e.get("probe_attempts") is not None:
            validate_probe_attempts_declaration(where, e["probe_attempts"], e)
        if e.get("prose_coupling") is not None:
            validate_prose_coupling_declaration(where, e["prose_coupling"], e)
        if e.get("fidelity_tests") is not None:
            validate_fidelity_tests_declaration(where, e["fidelity_tests"], e)
        if e.get("density_tier_columns") is not None:
            validate_density_tier_declaration(where, e["density_tier_columns"], e)
        if e.get("source") is not None:
            validate_source_declaration(where, e["source"], e, aid)
        if e.get("prose_none") is not None:
            validate_prose_none_declaration(where, e["prose_none"], e)
        if e.get("prose_excluded") is not None:
            validate_prose_excluded_declaration(where, aid, e)
        if e.get("label_columns") is not None:
            validate_label_columns_declaration(where, e)
        if e.get("forwarded_leaves") is not None:
            validate_forwarded_leaves_declaration(where, e)
        if e.get("lint_none") is not None:
            validate_lint_none_declaration(where, e)
        if e.get("update_only") is not None:
            validate_update_only_declaration(where, e)
        if e.get("no_table") is not None:
            validate_no_table_declaration(where, e)
        bad = has_writer_problem(e)
        if bad:
            raise DeclarationsError(f"{where}.{bad}")
        if e.get("produced_tables") is not None:
            validate_produced_tables_declaration(where, e["produced_tables"], e)
        if e.get("density_facet") is not None:
            validate_density_facet_declaration(where, e)
        if e.get("uniform_authority") is not None:
            bad = uniform_authority_problem(e, aid)
            if bad:
                raise DeclarationsError(f"{where}.uniform_authority: {bad}")
        if e.get("service_probe") is not None:
            validate_service_probe_declaration(where, e["service_probe"], e)
        bad = prose_empty_d1_problem(e)
        if bad:
            raise DeclarationsError(f"{where}.prose_coupling is missing: {bad}")
        if e.get("prose_fields") == []:
            bad = prose_coupling_required_problem(aid, e)
            if bad:
                raise DeclarationsError(f"{where}.prose_coupling is missing: {bad}")
        pf = e.get("prose_fields")
        if pf is not None:
            # null = undeclared; [] = declared "this writer composes no prose" (a positive claim); both need evidence
            if not isinstance(pf, list):
                raise DeclarationsError(f"{where}.prose_fields must be null or a list of column names / "
                                        f"'column.$.key' JSON paths ([] = declared: composes no prose)")
            parsed = []
            for c in pf:
                try:
                    parsed.append(parse_prose_field(c))
                except DeclarationsError as exc:
                    raise DeclarationsError(f"{where}.prose_fields: {exc}") from exc
            # distinct, and no entry covers another: a duplicate, a column and a path of it, or a path and its sub-path
            # (case-insensitively; one column's sibling paths, or equal keys under two columns, are fine)
            for i, (col, path) in enumerate(parsed):
                for j in range(i + 1, len(parsed)):
                    col2, path2 = parsed[j]
                    if col.lower() != col2.lower():
                        continue
                    short, long_ = sorted((path or (), path2 or ()), key=len)
                    if tuple(x.lower() for x in long_[:len(short)]) == tuple(x.lower() for x in short):
                        raise DeclarationsError(f"{where}.prose_fields: {pf[i]!r} and {pf[j]!r} overlap (equal, or one "
                                                f"column/path already covers the other)")
            evp = (e.get("evidence") or {}).get("prose_fields") if isinstance(e.get("evidence"), dict) else None
            if not (isinstance(evp, str) and not _blank_text(evp)):
                raise DeclarationsError(f"{where}.prose_fields is declared (even []), so evidence.prose_fields must "
                                        f"carry a non-blank pointer (the writer code read, file:line)")
            ek = e.get("evidence_kind")
            if ek is not None and ek not in EVIDENCE_KINDS:
                raise DeclarationsError(f"{where}.evidence_kind must be null or one of {list(EVIDENCE_KINDS)}")
            if ek in (None, "writer"):
                cites = _EVIDENCE_ANY_CITE_RE.findall(evp)
                if not cites:
                    raise DeclarationsError(f"{where}.evidence.prose_fields must cite writer code as 'path.py:LINE' "
                                            f"(py/ts/tsx); DDL-only evidence needs evidence_kind 'ddl'")
                if _EVIDENCE_SQL_LINE_RE.search(evp):
                    raise DeclarationsError(f"{where}.evidence.prose_fields: a .sql:LINE cite is not writer code")
                if any(_EVIDENCE_TEST_PATH_RE.search(c) for c in cites):
                    raise DeclarationsError(f"{where}.evidence.prose_fields: a test/fixture path is not writer code")
            else:
                if not pf:
                    raise DeclarationsError(f"{where}: an empty prose_fields ([]) is a claim about writer code, not DDL evidence")
                if not _DDL_EVIDENCE_RE.search(evp):
                    raise DeclarationsError(f"{where}: evidence_kind 'ddl' needs the migration file (NNN_name.sql) in evidence.prose_fields")
        else:
            ev_orphan = e.get("evidence")
            if isinstance(ev_orphan, dict) and ev_orphan.get("prose_fields") is not None:
                raise DeclarationsError(f"{where}.evidence.prose_fields is set but prose_fields is null (undeclared): "
                                        f"an orphan pointer would read as evidence for a claim nobody made")
            if e.get("evidence_kind") is not None:
                raise DeclarationsError(f"{where}.evidence_kind is set but prose_fields is null (undeclared)")
        tbc = e.get("terminal_by_construction")
        if tbc is not None:
            if not isinstance(tbc, str) or _blank_text(tbc) or tbc != tbc.strip():
                raise DeclarationsError(f"{where}.terminal_by_construction must be null or a non-blank pointer string "
                                        f"(why the asset has no downstream consumer BY CONSTRUCTION)")
            if isinstance(car, dict) and car.get("served_surface") is True:
                raise DeclarationsError(f"{where}: terminal_by_construction contradicts carriage.served_surface true")
        re_ = e.get("read_evidence")
        rt = e.get("read_table")
        served_true = isinstance(car, dict) and car.get("served_surface") is True
        if re_ is not None and not (isinstance(re_, str) and _READ_EVIDENCE_RE.fullmatch(re_)
                                    and not {".", ".."} & set(re_.rsplit(":", 1)[0].split("/"))):
            raise DeclarationsError(f"{where}.read_evidence must be null or 'platform/src/...ts:LINE' / "
                                    f"'platform-mcp/src/...ts:LINE' (served TypeScript, no test/mock/generated/allow-list path)")
        if isinstance(re_, str) and _READ_EVIDENCE_EXCLUDED_RE.search(re_):
            raise DeclarationsError(f"{where}.read_evidence {re_!r} is a test/mock/generated/allow-list path, not a served read")
        rk = e.get("read_kind")
        if rk is not None and (not isinstance(rk, str) or rk not in READ_KINDS):
            raise DeclarationsError(f"{where}.read_kind must be null (row-level read) or one of {list(READ_KINDS)}")
        if rt is not None and not (isinstance(rt, str) and _READ_TABLE_RE.fullmatch(rt)):
            raise DeclarationsError(f"{where}.read_table must be null or a table identifier")
        if served_true and (re_ is None or rt is None):
            raise DeclarationsError(f"{where}: carriage.served_surface true requires read_evidence ('path:line' of a real "
                                    f"non-test read of the asset's table) and read_table; without a real read it is null")
        if not served_true and (re_ is not None or rt is not None or rk is not None):
            raise DeclarationsError(f"{where}: read_evidence/read_table/read_kind are only for carriage.served_surface true")
        cw = e.get("cross_asset_writes")
        if cw is not None:
            if (not isinstance(cw, list) or not all(isinstance(c, str) and _CROSS_WRITE_RE.fullmatch(c) for c in cw)
                    or len({c.lower() for c in cw}) != len(cw)):
                raise DeclarationsError(f"{where}.cross_asset_writes must be null or a list of distinct (case-insensitively) "
                                        f"'table.column' strings ([] = declared: writes nothing outside its own table)")
            ev0 = e.get("evidence")
            if not (isinstance(ev0, dict) and isinstance(ev0.get("cross_asset_writes"), str) and ev0["cross_asset_writes"].strip()):
                raise DeclarationsError(f"{where}.cross_asset_writes is declared (even []), so evidence.cross_asset_writes "
                                        f"must carry a non-blank pointer")
        ev = e.get("evidence")
        if ev is not None:
            if (not isinstance(ev, dict) or set(ev) - set(_DECL_EVIDENCE_KEYS)
                    or not all(v is None or isinstance(v, str) for v in ev.values())):
                raise DeclarationsError(f"{where}.evidence must be null or an object of pointer strings keyed "
                                        f"by {list(_DECL_EVIDENCE_KEYS)}")
    return assets


def load_asset_declarations(path=None, registry_ids=None) -> dict:
    """Pure reader: asset_id -> entry (`kind`, `carriage`, `prose_fields`, `evidence`). Reads only `path`
    (default DECLARATIONS_PATH). Raises DeclarationsError on a missing, unreadable, undecodable, non-JSON,
    pathologically nested, duplicate-keyed or malformed file. An asset absent from the result is UNKNOWN; so is any null field of an entry."""
    p = Path(path) if path is not None else DECLARATIONS_PATH
    try:
        text = p.read_text(encoding="utf-8")
    except (OSError, ValueError) as exc:     # ValueError: UnicodeDecodeError, an embedded NUL in the path
        raise DeclarationsError(f"cannot read the declarations file {p}: {exc}") from exc
    try:
        doc = json.loads(text, object_pairs_hook=_decl_pairs)
    except json.JSONDecodeError as exc:
        raise DeclarationsError(f"declarations file {p} is not valid JSON: {exc}") from exc
    except RecursionError as exc:
        raise DeclarationsError(f"declarations file {p} is nested too deeply to parse (recursion limit)") from exc
    except ValueError as exc:                # e.g. an integer literal over the int-parsing digit limit
        raise DeclarationsError(f"declarations file {p} cannot be parsed: {exc}") from exc
    return validate_declarations(doc, registry_ids)


def declared_facts(declarations, asset_id, registry_kind=None, measured_dependents=None, measured_served=None) -> dict:
    """The DECLARED facts for one asset, as separate keys that never replace a measured one:
    `declared_kind`; `declared_carriage` (only the known `served_surface` boolean); `declared_carries_downstream`;
    `declared_prose_fields` (a list; `[]` = declared "composes no prose", a positive claim, present as an empty list; null = undeclared, key left out; entries are a column or a `column.$.key` JSON path, see parse_prose_field); `declared_read_evidence` / `declared_read_table` (the `path:line` of the real read that
    backs a declared served_surface true) and `declared_read_kind` (only when that read is not row-level:
    `coverage` = a facet/DISTINCT coverage lookup, `projection` = a column served on request, `table_map` = a
    dynamic `FROM ${table}` fed by a map); `declared_terminal_by_construction` (the pointer string); `declared_cross_asset_writes`
    (a list of 'table.column'; [] = declared writes-nothing-outside-its-own-table, null = unknown, key omitted); and
    `declaration_disagreements`: every place a declaration contradicts a measured or registry fact, reported and
    never resolved. Absent asset / null field -> key left out (UNKNOWN).

    `declared_carries_downstream` is NEVER derived from negatives (a negative scan or a zero measured count is not
    proof, CLAUDE.md N.8 / N.7.6): True only from a positive `served_surface: true`; False ONLY when the file carries
    the separate positive `terminal_by_construction` pointer; otherwise omitted (unknown). A future `write-nothing`
    cause must key on `declared_cross_asset_writes == []`, never on kind `service` alone (mi_abhilekha is a service
    that UPDATEs mimamsa_predictions.lifecycle_status).

    Measured inputs (each optional; a disagreement is reported only where the measurement is available):
    `registry_kind` (only 'service' and 'data' are compared: `artifact` maps to the declaration file per asset),
    `measured_dependents` (the census blocking_radius.direct; the only word on DAG dependents), `measured_served`
    (the Dens.served verdict: a declared served_surface False against PASS/FAIL/PARTIAL, or True against N/A, is reported)."""
    facts: dict = {}
    e = (declarations or {}).get(asset_id)
    if prose_coupling_required_problem(asset_id, e):
        facts["declared_prose_coupling_missing"] = True      # a required coupling that is not declared (even an absent entry): no Narr N/A of this asset may stand
    if not isinstance(e, dict):
        return facts
    disagree = []
    kind = e.get("kind")
    if isinstance(kind, str) and kind in DECLARED_KINDS:
        facts["declared_kind"] = kind
        if registry_kind in ("service", "data") and kind != registry_kind:
            disagree.append(dict(field="kind", declared=kind, registry=registry_kind))
    car = e.get("carriage")
    served = None
    if isinstance(car, dict):
        known = {f: car[f] for f in CARRIAGE_FIELDS if isinstance(car.get(f), bool)}
        if known:
            facts["declared_carriage"] = known
            served = known.get("served_surface")
    if served is True:
        facts["declared_carries_downstream"] = True
    if isinstance(measured_served, str):
        if served is False and measured_served in (PASS, FAIL, PARTIAL):
            disagree.append(dict(field="carriage.served_surface", declared=False, measured=measured_served))
        elif served is True and measured_served == NA:
            disagree.append(dict(field="carriage.served_surface", declared=True, measured=measured_served))
    tbc = e.get("terminal_by_construction")
    if isinstance(tbc, str) and not _blank_text(tbc):
        facts["declared_terminal_by_construction"] = tbc
        if served is not True:
            facts["declared_carries_downstream"] = False
        if isinstance(measured_dependents, int) and not isinstance(measured_dependents, bool) and measured_dependents > 0:
            disagree.append(dict(field="terminal_by_construction", declared=tbc, measured_dependents=measured_dependents))
    pf = e.get("prose_fields")
    if isinstance(pf, list):
        facts["declared_prose_fields"] = list(pf)
    pcp = e.get("prose_coupling")
    if isinstance(pcp, dict):
        # NARR-GUARD (pin 16): the declared coupling of a prose N/A to Carr.D1; the rollup reads it so a record that dropped its own coupling block cannot slip an N/A through
        cols = list(pcp["columns"]) if isinstance(pcp.get("columns"), list) else None
        covered = None                       # the D1 spec's own coverage of the listed columns, DERIVED here: a record's `covered` map is compared with it (never trusted)
        try:
            cov = _carriage_d1().prose_coverage(e["carriage"]["spec"])
            covered = {c: cov[c] for c in cols} if cols is not None else None
        except (KeyError, TypeError, AttributeError, ValueError):
            covered = None
        facts["declared_prose_coupling"] = dict(to=pcp.get("to"), columns=cols, covered=covered)
    elif prose_empty_d1_problem(e) or prose_coupling_required_problem(asset_id, e):
        facts["declared_prose_coupling_missing"] = True      # [] + a D1 transcription carriage and NO coupling: no Narr N/A may stand (the rollup, the ledger and the reader read this)
    cw = e.get("cross_asset_writes")
    if isinstance(cw, list):
        facts["declared_cross_asset_writes"] = list(cw)
    dpt = declared_produced_tables(e)
    if dpt is not None:
        facts["declared_produced_tables"] = dpt          # N-150: the DECLARED produced-table set (read by the Build.completion clause; undeclared = key left out)
    rev, rtab = e.get("read_evidence"), e.get("read_table")
    if isinstance(rev, str) and rev.strip() and isinstance(rtab, str) and rtab.strip():
        facts["declared_read_evidence"] = rev
        facts["declared_read_table"] = rtab
        if isinstance(e.get("read_kind"), str) and e["read_kind"] in READ_KINDS:
            facts["declared_read_kind"] = e["read_kind"]
    if disagree:
        facts["declaration_disagreements"] = disagree
    return facts


def facts_for_asset(asset_record, declarations=None) -> dict:
    """The `facts` mapping `rollup_asset` expects (`columns`, `asset_kind`; plus `count_sql_declared` for the
    conditions that will read it), from one measured asset record. A fact that is absent (a record from before
    packet 2a), None (unknown), empty, or of the wrong type is LEFT OUT, so its applicability stays
    UNKNOWN. `columns_known` is never set: an emitted list cannot assert 'the table is known and has zero columns'.

    `declarations` (the mapping load_asset_declarations returns; default None = none supplied, the mapping is then
    exactly what it was before the declarations packet) MERGES the declared facts under their own `declared_*`
    keys (see declared_facts). The measured `asset_kind` is never overwritten: a declared kind that disagrees with
    the registry's 'service'/'data' is listed under `declaration_disagreements`, not silently preferred. No
    criterion reads a declared_* key, so no cell changes."""
    facts: dict = {}
    if not isinstance(asset_record, dict):
        return facts
    cols = asset_record.get("target_columns")
    if isinstance(cols, list) and cols and all(isinstance(c, str) and c.strip() for c in cols):
        facts["columns"] = [c.strip() for c in cols]   # stripped like measure() strips: a blank name is unknown
    kind = asset_record.get("asset_kind")
    if isinstance(kind, str) and kind.strip():
        facts["asset_kind"] = kind.strip()
    declared = asset_record.get("count_sql_declared")
    if isinstance(declared, bool):
        facts["count_sql_declared"] = declared
    if declarations:
        br = asset_record.get("blocking_radius")
        direct = br.get("direct") if isinstance(br, dict) else None
        ms = asset_record.get("measurements")
        ds = ms.get("Dens.served") if isinstance(ms, dict) else None
        served = ds.get("v") if isinstance(ds, dict) else None
        aid = asset_record.get("asset_id")
        if isinstance(aid, str):
            facts.update(declared_facts(declarations, aid, facts.get("asset_kind"), direct, served))
    return facts


def build_rollup_output(census_by_layer: dict, declarations: dict | None = None) -> dict:
    """The `--rollup` payload for {layer: measure() output}: the nine gate cells per asset (computed from each
    asset's emitted facts) and, as information, the measured criteria of the non-nine gates. Read-only; the
    census dicts are not modified (emit_gaps never sees this)."""
    layers, excluded = {}, {}
    scopes = {k: census_scope(c) for k, c in census_by_layer.items()}
    scoped = [k for k, v in scopes.items() if v is not None]
    if scoped and len(scoped) != len(census_by_layer):
        raise ScopeError(f"layer(s) {', '.join(scoped)} are scoped and the rest are full: one rollup cannot be both")
    if declarations is None:
        # the id check needs the whole registry set, never a partial run — and a scoped run is a partial run even
        # when it reaches every layer (E1.9)
        full = set(census_by_layer) == set(ALL_LAYERS) and not scoped
        ids = [a["asset_id"] for c in census_by_layer.values() for a in c["assets"]] if full else None
        declarations = load_asset_declarations(registry_ids=ids)
    for k, c in census_by_layer.items():
        layers[k] = rollup_census(c, {a["asset_id"]: facts_for_asset(a, declarations) for a in c["assets"]})
        excluded[k] = {a["asset_id"]: rollup_excluded(c["layer"], a["measurements"]) for a in c["assets"]}
    head = dict(registry_revision=REGISTRY_REVISION, registry_fingerprint=registry_fingerprint())
    if scoped:   # E1.9: the rollup header says it is partial, next to the registry revision it was computed under
        head["scope"] = dict(assets=sorted(x for v in scopes.values() for x in v["assets"]), partial=True,
                             layers=list(scoped), registry_revision=REGISTRY_REVISION)
    return dict(rollup=dict(**head, layers=layers),
                rollup_excluded=excluded)


# ─────────────────────────── E6 item (f): Carr `no-carriage` on D1, D2, D3 ───────────────────────────
# N-22 ruling principle 7 (provisional until the J1 review): "where no D-check fits because the asset carries nothing
# downstream by construction (a declared fact), that is check-level N/A by cause `no-carriage`. Where a check should
# fit but none exists, it is NO_DETECTOR (T4:329)." SS strict definition (2026-09-30): the asset has NO DAG dependents
# AND does not reach a served surface; being served IS downstream carriage. The cause is a CANDIDATE only: it releases
# nothing until NA_RULE_DECISIONS declares `Carr.D<n>#measured:no-carriage` (empty today, and no asset declares
# `terminal_by_construction` today, so no census cell changes). An absence is never the evidence (CLAUDE.md N.8): zero
# measured dependents and a null served_surface are NOT proof of anything; only the positive declared pointer is.
CARR_D_CHECKS = ("Carr.D1", "Carr.D2", "Carr.D3")
_CARR_NEVER = "never read as no-carriage"


def _count(v):
    """A measured non-negative integer count, else None (a bool, float, str or negative is not a measurement)."""
    return v if isinstance(v, int) and not isinstance(v, bool) and v >= 0 else None


def grade_carr_no_carriage(record_facts) -> dict:
    """The Carr.D1/D2/D3 `no-carriage` reading of one asset, from `record_facts` (pure; no I/O):
      declared_terminal_by_construction  the positive declared pointer (a str with at least one visible character), else undeclared
      declared_carriage                  {'served_surface': bool | None}  (absent/None = unknown; any other form is malformed)
      blocking_radius                    the census radius {'direct': int, 'transitive': int} (absent/None/malformed = unmeasured)
      measured_served                    the Dens.served verdict of this census run
    N/A (cause `no-carriage`, a CANDIDATE) ONLY when ALL hold: the pointer is declared; measured direct AND transitive
    dependents are both 0; `served_surface` is None or False (true contradicts; a non-bool is malformed); and the
    measured Dens.served verdict is EXACTLY 'N/A' (the only verdict meaning "scanned, no served select": since REGISTRY_REVISION 14 a serving
    module may still NAME the asset as a label, a provenance string or a type name, which is not a select; the cause stays `no-served-surface`). Every other
    Dens.served value (NO_DETECTOR, ERRORED, absent, a case variant) means "possibly served" (the scan did not run, a module
    names the table but no served select was found, comment-only, outside the scanned roots, unparsed, shared-only), which
    is not evidence of no carriage: NO_DETECTOR. A declaration that a measured fact contradicts is NO_DETECTOR with a
    `declaration_disagreements` entry (reported, never resolved); an unmeasured radius or no declaration is NO_DETECTOR.
    `served_surface` None does not block: the declared pointer is then the evidence, and the verdict text says so.

    LIMIT (N-22 principle 3): no detector exists that still catches a mis-declared terminal asset. D1-D3 are detector NONE,
    and the contradiction checks here are blind to undeclared edges: the blocking radius counts only DECLARED depends_on
    edges, so it under-reports an undeclared reader (bg_gochara_arcs is read by ka_gochara.py:412 with no depends_on edge;
    an L0 reader never adds an edge because Build.dag exempts bedrock reads; 14 of the 40 zero-dependent assets are L0),
    and to Dens scanner gaps. The `no-carriage` N/A RULE must stay UNDECLARED (NA_RULE_DECISIONS empty) until an
    inverse-readers detector exists: one that scans the registered writers' reads, bedrock included, for readers of the
    asset's tables, and gates the candidate on none found."""
    f = record_facts if isinstance(record_facts, dict) else {}
    tbc = f.get("declared_terminal_by_construction")
    if not (isinstance(tbc, str) and not _blank_text(tbc)):
        return dict(v=NO_DET, measured=f"NO_DETECTOR — no terminal_by_construction declared: carriage is unknown, {_CARR_NEVER}")
    car = f.get("declared_carriage")
    if car is not None and not isinstance(car, dict):
        return dict(v=NO_DET, measured=f"NO_DETECTOR — the declared carriage is malformed ({car!r}: not an object); the "
                                       f"declared pointer ({tbc!r}) cannot be relied on, {_CARR_NEVER}")
    served = car.get("served_surface") if isinstance(car, dict) else None
    if served is not None and not isinstance(served, bool):
        return dict(v=NO_DET, measured=f"NO_DETECTOR — carriage.served_surface is malformed ({served!r}: only null, true or "
                                       f"false are forms); the declared pointer ({tbc!r}) cannot be relied on, {_CARR_NEVER}")
    br = f.get("blocking_radius")
    direct = _count(br.get("direct")) if isinstance(br, dict) else None
    trans = _count(br.get("transitive")) if isinstance(br, dict) else None
    ms = f.get("measured_served")
    bad = []
    if served is True:
        bad.append(dict(field="carriage.served_surface", declared=True, terminal_by_construction=tbc))
    if direct is not None and trans is not None and (direct > 0 or trans > 0):
        bad.append(dict(field="terminal_by_construction", declared=tbc,
                        measured_dependents=dict(direct=direct, transitive=trans)))
    if ms in (PASS, FAIL, PARTIAL):
        bad.append(dict(field="terminal_by_construction", declared=tbc, measured_served=ms))
    if bad:
        what = []
        if served is True:
            what.append("carriage.served_surface is declared true (reaches a served surface)")
        if direct is not None and trans is not None and (direct > 0 or trans > 0):
            what.append(f"measured dependents are direct {direct}, transitive {trans}")
        if ms in (PASS, FAIL, PARTIAL):
            what.append(f"Dens.served measured {ms} (a served read was found)")
        return dict(v=NO_DET, declaration_disagreements=bad,
                    measured=f"NO_DETECTOR — the declared terminal_by_construction pointer ({tbc!r}) is contradicted: "
                             f"{'; '.join(what)}; {_CARR_NEVER}")
    if direct is None or trans is None:
        return dict(v=NO_DET, measured=f"NO_DETECTOR — dependents unmeasured (the blocking radius is absent or not a count); "
                                       f"the declared pointer ({tbc!r}) cannot be checked against the DAG, {_CARR_NEVER}")
    if not (isinstance(ms, str) and ms == NA):
        return dict(v=NO_DET, measured=f"NO_DETECTOR — Dens.served is {ms!r}, not 'N/A' (scanned, no reference): the asset is "
                                       f"possibly served (scan not run, a served select not found or not attributable), so the "
                                       f"declared pointer ({tbc!r}) is not corroborated; {_CARR_NEVER}")
    sv = ("served_surface declared false" if served is False else
          "served_surface not declared (null: the declared pointer is the evidence)")
    return _na(f"declared terminal_by_construction ({tbc!r}); measured dependents direct {direct}, transitive {trans}; "
               f"Dens.served N/A (scanned, no reference); {sv}; the declared pointer is the evidence (a candidate, not a "
               "rule: released only by a declared rule, which must stay undeclared until an inverse-readers detector exists)",
               "no-carriage")


_D1_SQL_ID = re.compile(r"[a-z0-9][a-z0-9_]*")
_D1_SQL_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def d1_fetch_chunks(chunk_ids) -> dict:
    """{chunk_id: {chunk_id, text_id, content_en, content_sa, content_sha256}} for the declared passages: ONE read-only SELECT of
    classical_text_chunks by chunk id (the ids are the validated declaration's, matched against a strict pattern before they reach
    SQL). A chunk that does not exist is simply absent from the result (the D1 engine reports it as missing). Raises Unknown on a
    failed read."""
    ids = list(chunk_ids)
    if not ids or not all(isinstance(i, str) and _D1_SQL_ID.fullmatch(i) for i in ids):
        raise Unknown(f"d1_fetch_chunks: malformed chunk id list {ids!r}")
    lst = ",".join(f"'{i}'" for i in ids)
    blob = scalar("SELECT coalesce(json_agg(json_build_object('chunk_id',chunk_id,'text_id',text_id,'content_en',content_en,"
                  "'content_sa',content_sa,'content_sha256',content_sha256) ORDER BY chunk_id)::text,'[]') "
                  f"FROM classical_text_chunks WHERE chunk_id IN ({lst})")
    try:
        got = json.loads(blob or "[]")
    except json.JSONDecodeError as exc:
        raise Unknown(f"d1_fetch_chunks: unparseable chunk read: {exc}") from exc
    return {c["chunk_id"]: c for c in got if isinstance(c, dict) and c.get("chunk_id")}


_UUID = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")


def d1_fetch_rows(table: str, columns, chart_id: str | None = None) -> list:
    """The asset's own table rows restricted to the DECLARED columns, in a total order (ORDER BY every column): the SECOND
    read-only SELECT D1 makes (listed in the detector's stated reads), needed to compare EVERY row with the passage. When the
    table carries `chart_id` the caller passes the census chart and the read is chart-scoped (`WHERE chart_id = '<uuid>'`).
    Identifiers and the chart id are matched against strict patterns before they reach SQL. The rows come back as ONE line
    (`jsonb_agg(...)::text`; `json_agg` over record rows puts ', <newline> ' between elements and `scalar()` returns only the
    first output line: a 2+ row table read ERRORED live). Raises Unknown on a failed read."""
    cols = list(dict.fromkeys(columns))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and cols and all(_D1_SQL_IDENT.fullmatch(c) for c in cols)):
        raise Unknown(f"d1_fetch_rows: malformed identifier(s) {table!r} / {cols!r}")
    if chart_id is not None and not (isinstance(chart_id, str) and _UUID.fullmatch(chart_id)):
        raise Unknown(f"d1_fetch_rows: malformed chart id {chart_id!r}")
    sel = ",".join(f'"{c}"' for c in cols)
    order = ",".join(f't."{c}"' for c in cols)
    where = f" WHERE \"chart_id\" = '{chart_id}'" if chart_id else ""
    blob = scalar(f"SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY {order})::text,'[]') FROM (SELECT {sel} FROM \"{table}\"{where}) t")
    try:
        return json.loads(blob or "[]")
    except json.JSONDecodeError as exc:
        raise Unknown(f"d1_fetch_rows: unparseable read of {table}: {exc}") from exc


# C1-1 (SS N-101 (c)): the COLUMN LEDGER (every text-like column of the table is matched, a declared constant, a declared non-claim or a Narr prose field, else D1 cannot read
# PASS) always runs for a declared D1 carriage: there is no switch. The one asset that declares a carriage check, bg_phaladeepika_latta, has two text columns its D1 spec never checks
# (`table_version`, `source_citation`); it declares both as `non_claim_columns` (declarations 1.13.0), so it reads PASS, and removing either declaration reads PARTIAL naming the
# column. A clean ledger adds no key to the record. The column facts come from pg_catalog (`pg_column_type_facts`, the Null detector's one catalog read), not information_schema.


def carriage_fetch_column_types(table: str) -> dict:
    """{column: {t, c, ec, et}} for every column of `table`: the Carr column ledger's input (`pg_column_type_facts`). Raises Unknown on a failed read."""
    return pg_column_type_facts(table)


D3_READ_TIMEOUT_SECONDS = int(os.environ.get("NIKASHA_CENSUS_D3_READ_TIMEOUT_SECONDS", "900"))      # stated in every D3 record (N-156: a long read is bounded and says so, never silently truncated)
D3_READ_ROW_CAP = 200_000       # a declared D3 read over more rows than this is refused (chunked reads are a later method's job): never one jsonb_agg of a huge table (the documented trap)


def _d3_where_sql(where) -> str:
    """The SQL for a closed D3 `where` list (validated by carriage_d3.validate_spec: identifiers and plain-string values only, re-checked here)."""
    out = []
    for c in where or []:
        col = c["column"]
        vals = [c["equals"]] if "equals" in c else list(c["in"])
        if not (_D1_SQL_IDENT.fullmatch(col) and vals and all(isinstance(v, str) and re.fullmatch(r"[A-Za-z0-9_.:+\- ]{1,80}", v) for v in vals)):
            raise Unknown(f"d3 read: malformed condition on {col!r}")
        out.append(f'"{col}" IN (' + ",".join(f"'{v}'" for v in vals) + ")")
    return " AND ".join(out)


def d3_fetch_rows(table: str, read: dict, chart_id: str | None = None):
    """The asset's own table rows for a D3 spec's stated `read` (columns, closed where, chart scope): ONE read-only SELECT, one line of jsonb (the d1_fetch_rows shape),
    in a total order. A read over more than D3_READ_ROW_CAP rows is refused (Unknown). Raises Unknown on a failed read."""
    cols = list(dict.fromkeys(read["columns"]))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and cols and all(_D1_SQL_IDENT.fullmatch(c) for c in cols)):
        raise Unknown(f"d3_fetch_rows: malformed identifier(s) {table!r} / {cols!r}")
    conds = []
    if read.get("chart_scoped"):
        if not (isinstance(chart_id, str) and _UUID.fullmatch(chart_id)):
            raise Unknown(f"d3_fetch_rows: malformed chart id {chart_id!r}")
        conds.append(f"\"chart_id\" = '{chart_id}'")
    w = _d3_where_sql(read.get("where"))
    if w:
        conds.append(w)
    where = (" WHERE " + " AND ".join(conds)) if conds else ""
    n = scalar(f'SELECT count(*) FROM "{table}"{where}')
    try:
        n = int(n)
    except (TypeError, ValueError) as exc:
        raise Unknown(f"d3_fetch_rows: unreadable row count of {table}") from exc
    if n > D3_READ_ROW_CAP:
        raise Unknown(f"d3_fetch_rows: the declared read of {table} holds {n} rows (cap {D3_READ_ROW_CAP}): a chunked read is not built")
    sel = ",".join(f'"{c}"' for c in cols)
    order = ",".join(f't."{c}"' for c in cols)
    rows = psql(f"SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY {order})::text,'[]') FROM (SELECT {sel} FROM \"{table}\"{where}) t", timeout=D3_READ_TIMEOUT_SECONDS)       # ONE read-only pass, one line
    blob = rows[0][0] if rows and rows[0] else None
    try:
        return json.loads(blob or "[]")
    except json.JSONDecodeError as exc:
        raise Unknown(f"d3_fetch_rows: unparseable read of {table}: {exc}") from exc


# SS ruling 2026-10-06 (interim census, e718a9b15): the census role (suvarna_reader) has NO SELECT on `charts` and is NOT granted one. A D3 method whose `inputs_table` is one of these tables
# is therefore not measurable under the census role: the census issues NO statement against it (no read, no privilege probe) and the Carr.D3 cell reads NO_DETECTOR naming what it needs,
# never ERRORED (the interim run read `ERROR: permission denied for table charts` as ERRORED on ga_positions). A different role that can read the table (a test, an owner-path run) empties
# this set (monkeypatch) and the declared read proceeds as before.
CENSUS_ROLE_UNREADABLE_TABLES = frozenset({"charts"})


D3_NEEDS_READABLE_CAUSE = "needs-a-table-the-census-role-cannot-read"


def d3_unreadable_inputs_record(spec: dict, inputs: dict) -> dict:
    """The Carr.D3 record for a declared D3 whose re-derivation inputs live in a table the census role cannot read: NO_DETECTOR (never ERRORED, never PASS), the specific cause and exactly what
    it needs. Pure: no read."""
    cols, tbl, idc = list(inputs.get("columns") or ()), inputs.get("table"), inputs.get("id_column")
    needs = dict(table=tbl, columns=cols, id_column=idc, where=f"{idc} = <the census chart id>", census_role_privilege="SELECT")
    text = (f"NO_DETECTOR — needs a table the census role cannot read: the D3 method {spec.get('method')!r} re-derives from the chart's own birth parameters ({', '.join(cols)}), which live in "
            f"`{tbl}` (one row, {idc} = the census chart), and the census role has no SELECT on `{tbl}` (SS ruling 2026-10-06: it is not granted one). No statement was issued against `{tbl}`; "
            f"nothing was re-derived, so this is neither a PASS nor a FAIL. To make it measurable without a grant on `{tbl}`, the same {len(cols)} columns for the census chart must be readable by the "
            "census role from another source (a view or a table it can SELECT, or L1 facts carrying the birth instant, latitude, longitude and time zone); the census never infers them from the stored outputs")
    return dict(v=NO_DET, measured=text, d3=dict(method=spec.get("method"), cause=D3_NEEDS_READABLE_CAUSE, needs=needs))


def d3_denied_record(spec: dict, msg: str) -> dict:
    """The Carr.D3 record for a read the SERVER refused for privilege (a message `permission denied for <object>`): NO_DETECTOR naming the object, never ERRORED. Pure."""
    obj = denied_object(msg)
    return dict(v=NO_DET, measured=(f"NO_DETECTOR — needs a table the census role cannot read: the server refused a D3 read ({msg[:200]}); denied object: {obj or 'not named by the server message'}. "
                                    "Nothing was re-derived, so this is neither a PASS nor a FAIL; the census role is not widened"),
                d3=dict(method=spec.get("method"), cause=D3_NEEDS_READABLE_CAUSE, denied_object=obj))


def d3_fetch_inputs(inputs: dict, chart_id: str):
    """The chart's own birth parameters for a D3 spec's `read.inputs` {table, columns, id_column}: ONE row, WHERE id_column = <census chart>. Raises Unknown on a failed read; raises
    CensusRoleCannotRead, before any SQL, for a table in CENSUS_ROLE_UNREADABLE_TABLES."""
    t, cols, idc = inputs["table"], list(dict.fromkeys(inputs["columns"])), inputs["id_column"]
    if t in CENSUS_ROLE_UNREADABLE_TABLES:
        raise CensusRoleCannotRead(f"the census role cannot read {t}")
    if not (_D1_SQL_IDENT.fullmatch(t) and _D1_SQL_IDENT.fullmatch(idc) and cols and all(_D1_SQL_IDENT.fullmatch(c) for c in cols) and isinstance(chart_id, str) and _UUID.fullmatch(chart_id)):
        raise Unknown("d3_fetch_inputs: malformed identifier or chart id")
    sel = ",".join(f'"{c}"' for c in cols)
    blob = scalar(f"SELECT coalesce(jsonb_agg(to_jsonb(t))::text,'[]') FROM (SELECT {sel} FROM \"{t}\" WHERE \"{idc}\"::text = '{chart_id}' LIMIT 2) t")
    try:
        return json.loads(blob or "[]")
    except json.JSONDecodeError as exc:
        raise Unknown(f"d3_fetch_inputs: unparseable read of {t}: {exc}") from exc


D3_RECORDED_ATTEMPT_LIMIT = 25


def d3_recorded_attempts(asset_id: str, chart_id: str, limit: int = D3_RECORDED_ATTEMPT_LIMIT) -> list[dict]:
    """N-169: this asset's STARTED build_run_assets attempts for ONE chart, NEWEST FIRST (the order of `latest_attempts`: (run created_at, run_id) descending), each
    {run_id, state, disposition, when, error, notes}. Read-only, census-written (build_run_assets and build_runs are bookkeeping tables the census role already reads for Build.history).
    `error` is the attempt's own error text, newlines folded, the first 1500 characters (the writer's refusal text starts with its counts). `notes` is ALWAYS None today: the orchestrator does not persist `WriterResult.notes` for a completed attempt (`asset_runner._drive_substeps` sums the rows and drops the result; build_run_assets has no column for it), so the live PASS rests on the provenance receipt (`d3_recorded_receipts`), not on a note; this is the seam a future notes channel would fill, and `d3_recorded_measure` cross-checks a supplied note, never requires one. Raises Unknown on a failed or ragged read; the asset id must be a plain registry id and the chart id a uuid."""
    if not (_ASSET_ID.fullmatch(asset_id) and isinstance(chart_id, str) and _UUID.fullmatch(chart_id) and isinstance(limit, int) and 1 <= limit <= 100):
        raise Unknown("d3_recorded_attempts: malformed asset id, chart id or limit")
    raw = psql("SELECT a.run_id::text, coalesce(a.state,''), coalesce(a.disposition,''), coalesce(r.created_at::date::text,''), "
               "coalesce(left(translate(a.error, E'\\n\\r' || chr(31), '   '),1500),'') "
               "FROM build_run_assets a JOIN build_runs r ON r.id = a.run_id "
               f"WHERE a.asset_id = '{asset_id}' AND r.chart_id::text = '{chart_id}' AND a.started_at IS NOT NULL "
               f"ORDER BY r.created_at DESC, a.run_id DESC LIMIT {limit}")
    bad = [x for x in raw if len(x) != 5]
    if bad:
        raise Unknown(f"d3_recorded_attempts: {len(bad)} line(s) did not parse into the 5 selected fields: the attempts are not read")
    return [dict(run_id=r[0], state=r[1], disposition=r[2], when=r[3], error=r[4], notes=None) for r in raw]


def d3_recorded_receipts(asset_id: str, chart_id: str) -> list[dict]:
    """N-169 / N-180 Option C: this asset's provenance receipt row(s) for ONE chart, [{receipt_state, code_digest, build_id, partition_key, observed_at}]. Read-only, census-written. The census already
    issues SELECTs on asset_provenance_receipts (`latest_attempts`, `probe_attempt_rows`), so the table is one it reads; whether the census ROLE holds SELECT on it in production is not verifiable
    offline (a refusal reads as the check's NO_DETECTOR `receipt-read-failed`, never a PASS). Raises Unknown on a failed or ragged read."""
    if not (_ASSET_ID.fullmatch(asset_id) and isinstance(chart_id, str) and _UUID.fullmatch(chart_id)):
        raise Unknown("d3_recorded_receipts: malformed asset id or chart id")
    raw = psql("SELECT coalesce(p.receipt_state,''), coalesce(p.code_digest,''), coalesce(p.build_id::text,''), coalesce(p.partition_key,''), coalesce(p.observed_at::text,'') "
               f"FROM asset_provenance_receipts p WHERE p.asset_id = '{asset_id}' AND p.chart_id::text = '{chart_id}' ORDER BY p.partition_key LIMIT 10")
    bad = [x for x in raw if len(x) != 5]
    if bad:
        raise Unknown(f"d3_recorded_receipts: {len(bad)} line(s) did not parse into the 5 selected fields: the receipt is not read")
    return [dict(receipt_state=r[0], code_digest=r[1] or None, build_id=r[2] or None, partition_key=r[3], observed_at=r[4]) for r in raw]


def d3_expected_writer_digest(asset_id: str, rel_path: str) -> dict:
    """N-169 / N-180 Option C: the expected code digest of `asset_id` from the generated writer-digest inventory (`rel_path`, repo-relative) at the measured commit (this tree). Returns {value, source,
    why}; `value` None with the cause in `why` when the file or the entry is absent or not a 64-hex digest. Reads no database."""
    src = f"{rel_path} writers.{asset_id}"
    try:
        p = (ROOT / rel_path)
        doc = json.loads(p.read_text(encoding="utf-8"))
        v = doc["writers"][asset_id]
    except (OSError, ValueError, KeyError, TypeError) as exc:
        return dict(value=None, source=src, why=f"{type(exc).__name__} reading the inventory")
    if not (isinstance(v, str) and re.fullmatch(r"[0-9a-f]{64}", v)):
        return dict(value=None, source=src, why="the inventory entry is not a 64-hex digest")
    return dict(value=v, source=src, why="")


def carriage_declared_checks(aid: str, car, target_table, chart_scoped: bool = False, *, column_types, prose_columns, asset_rows=None, source=None) -> dict:
    """measure()'s Carr.D1/D2/D3 records for an asset that DECLARES its carriage check (SS N-72 S2): {} unless `car.nature` is
    declared (an undeclared asset emits nothing here, so its cell reads exactly as before).

    ratified_judgment: all three N/A, cause `ratified_judgment`. Otherwise the declared check (`applies`) is MEASURED (D1 by the
    generic engine in carriage_d1.py with a spec; D2/D3 have no detector yet: NO_DETECTOR, named) and the other two read N/A,
    cause `not-the-declared-carriage`, released only by the declared rule (never by a caller's choice).

    `column_types` (REQUIRED, no default: a caller cannot leave the column ledger off by forgetting it) is the table's pg_catalog column facts (`carriage_fetch_column_types`), or
    None when they could not be read (the ledger then reads NO_DETECTOR, never PASS); `prose_columns` the columns the asset declares as Narr prose."""
    if not isinstance(car, dict) or car.get("nature") is None:
        return {}
    why = car.get("why") or ""
    if car["nature"] == RATIFIED_JUDGMENT:
        return {c: _na(f"ratified judgment seed (ruling {car.get('ruling')}): {why}", "ratified_judgment") for c in CARR_D_CHECKS}
    applies = car["applies"]
    own = f"Carr.{applies}"
    _served_now = _carriage_d3_served_assets()
    if aid in _served_now and (applies != "D3" or car["nature"] in CEILING_NATURES):      # N-156 review MED-1: a D3-served asset's D3 is measured, never released by another nature
        why_bad = f"{aid} declares nature {car['nature']} (applies {applies}) but the reviewed D3 method {_served_now[aid]!r} serves it: its D3 check is measured, not released as an N/A"
        rec = lambda: dict(v=NO_DET, measured="NO_DETECTOR — " + why_bad, declaration_disagreements=[why_bad])
        return {"Carr.D1": rec(), "Carr.D2": rec(), "Carr.D3": rec()}
    out = {c: _na(f"the asset's declared carriage check is {applies} (nature {car['nature']}; reviewed, evidence: {car.get('evidence')}); "
                  f"{c.split('.')[1]} is not it", "not-the-declared-carriage") for c in CARR_D_CHECKS if c != own}
    if car.get("per_witness_values") is False:
        out["Carr.D2"] = _na(f"the asset declares per_witness_values false (reviewed, evidence: {car.get('evidence')}): it stores no per-witness values, so there is no second witness "
                             "of the same fact to carry (N-156)", "no-per-witness-values")
    if car["nature"] == "single_derivation":
        served = _carriage_d3_served_assets()
        if aid in served:                    # a declaration the measured facts contradict: reported, never resolved
            out[own] = dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares single_derivation but the reviewed D3 method {served[aid]!r} serves it: where a second route exists the check "
                                               "is measured, not waived", declaration_disagreements=[f"single_derivation vs method {served[aid]}"])
        else:
            out[own] = _na(f"single derivation (N-156): no independent second route; verified by integrity checks and internal consistency (reviewed, evidence: {car.get('evidence')}): {why}",
                           "single-derivation")
        return out
    if car["nature"] == NOT_A_TRANSCRIPTION:
        bad = not_a_transcription_problem(source)
        if bad:                              # a declaration the asset's own source declaration contradicts: reported, never resolved
            out[own] = dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares not_a_transcription but {bad}", declaration_disagreements=[bad])
        else:
            out[own] = _na(f"not a transcription (N-156 C8): the asset's source is {'/'.join(sorted(source_kinds(source)))} (a ratification or derivation, not a classical passage; reviewed, evidence: "
                           f"{car.get('evidence')}): {why}", "not-a-transcription")
        return out
    if car["nature"] == "unverified_transcription":
        if "K1" not in source_kinds(source):          # N-156 review LOW-6: declared alone it releases nothing: the source declaration must name K1
            out[own] = dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares unverified_transcription but its source declaration names no K1 classical citation (kinds {sorted(source_kinds(source))}): "
                                               "there is nothing to be an unverified transcription of", declaration_disagreements=["unverified_transcription without a K1 source"])
            return out
        out[own] = _na(f"transcription not verified against a passage (N-156): no passage-level spec (reviewed, evidence: {car.get('evidence')}): {why}", "transcription-not-verified")
        return out
    if applies == "D3":
        spec = car.get("spec")
        if not isinstance(spec, dict):
            out[own] = dict(v=NO_DET, measured=f"NO_DETECTOR — D3 is declared (nature {car['nature']}) but without a `spec` (the method, the stated read, the declared comparators "
                                               "and tolerances): there is nothing to re-derive", declared_carriage=dict(applies=applies, nature=car["nature"]))
            return out
        d3m = _carriage_d3()
        if aid not in _carriage_d3_served_assets() or _carriage_d3_served_assets()[aid] != spec.get("method"):
            out[own] = dict(v=NO_DET, measured=f"NO_DETECTOR — method {spec.get('method')!r} is not a reviewed D3 method serving asset {aid!r}: a computation declaration cannot borrow "
                                               "a method built for another asset", declared_carriage=dict(applies=applies, nature=car["nature"]))
            return out
        if spec.get("table") != target_table:
            out[own] = d3m.d3_measure(spec, None, target_table, asset_rows=asset_rows)
            return out
        if spec.get("form") == d3m.FORM_BUILD_RECORDED:
            # N-169: the method form that READS THE BUILD RECORD instead of re-deriving from birth data: the census role has no access to `charts`, so no statement is issued against it
            # (rd["inputs"] is the reference route's read and is not used here); the chart's own rows and this asset's attempts are the stated reads
            try:
                rd = d3m.spec_read(spec)
                rows = d3_fetch_rows(spec["table"], rd, CHART_ID if rd.get("chart_scoped") else None)
                try:
                    attempts = d3_recorded_attempts(aid, CHART_ID)
                except Unknown:
                    attempts = None                                      # the cell reads NO_DETECTOR (attempt-read-failed); a failed attempt read is not an ERRORED asset read
                try:
                    receipts = d3_recorded_receipts(aid, CHART_ID)
                except Unknown:
                    receipts = None                                      # NO_DETECTOR receipt-read-failed
                out[own] = dict(d3m.d3_recorded_measure(spec, attempts, rows, target_table, asset_rows=asset_rows, read_timeout_s=D3_READ_TIMEOUT_SECONDS, receipts=receipts,
                                                        expected_digest=d3_expected_writer_digest(aid, spec["recorded"]["writer_digest_file"])),
                                declared_carriage=dict(applies=applies, nature=car["nature"]))
            except Unknown as exc:                                     # R41: this check's failure degrades only this check
                out[own] = dict(v=ERRORED, measured=f"check errored: {' '.join(str(exc).split())} (the D3 read runs in ONE read-only pass under a {D3_READ_TIMEOUT_SECONDS} second client timeout; nothing is truncated, a timeout is an error)")
            return out
        try:
            rd = d3m.spec_read(spec)
            if isinstance(rd.get("inputs"), dict) and rd["inputs"].get("table") in CENSUS_ROLE_UNREADABLE_TABLES:
                out[own] = dict(d3_unreadable_inputs_record(spec, rd["inputs"]), declared_carriage=dict(applies=applies, nature=car["nature"]))      # nothing is read: not the asset rows, not `charts`
                return out
            rows = d3_fetch_rows(spec["table"], rd, CHART_ID if rd.get("chart_scoped") else None)
            inputs = d3_fetch_inputs(rd["inputs"], CHART_ID) if rd.get("inputs") else None
            out[own] = d3m.d3_measure(spec, rows, target_table, inputs=inputs, asset_rows=asset_rows, read_timeout_s=D3_READ_TIMEOUT_SECONDS)
        except Unknown as exc:                                  # R41: this check's failure degrades only this check
            msg = " ".join(str(exc).split())
            if isinstance(exc, CensusRoleCannotRead):          # a privilege the census role lacks is not a defect of the check: NO_DETECTOR with the cause, never ERRORED
                out[own] = dict(d3_unreadable_inputs_record(spec, (spec.get("read") or {}).get("inputs") or {}), declared_carriage=dict(applies=applies, nature=car["nature"]))
            elif "permission denied for" in msg.lower():
                out[own] = dict(d3_denied_record(spec, msg), declared_carriage=dict(applies=applies, nature=car["nature"]))
            else:
                out[own] = dict(v=ERRORED, measured=f"check errored: {exc} (the D3 read runs in ONE read-only pass under a {D3_READ_TIMEOUT_SECONDS} second client timeout; nothing is truncated, a timeout is an error)")
        return out
    if applies != "D1":
        out[own] = dict(v=NO_DET, measured=f"NO_DETECTOR — the declared carriage check is {applies} (nature {car['nature']}), and no {applies} "
                                           "detector is built yet: nothing measures it", declared_carriage=dict(applies=applies, nature=car["nature"]))
        return out
    spec = car.get("spec")
    if not isinstance(spec, dict):
        out[own] = dict(v=NO_DET, measured="NO_DETECTOR — D1 is declared but without a `spec` (the declared passage, rows and matching "
                                           "fields): there is nothing to match against")
        return out
    d1 = _carriage_d1()
    if spec.get("table") != target_table:     # the table guard runs BEFORE any SELECT (nothing is read for an asset the spec is not about)
        out[own] = d1.d1_measure(spec, car.get("citation_state"), {}, None, target_table)
        return out
    try:
        chunks = d1_fetch_chunks(spec["chunk_ids"])
        rows = d1_fetch_rows(spec["table"], d1.spec_columns(spec), CHART_ID if chart_scoped else None)
        out[own] = d1.d1_measure(spec, car.get("citation_state"), chunks, rows, target_table,
                                 ledger=dict(columns=column_types, prose_columns=list(prose_columns or ())))
    except Unknown as exc:                                  # R41: this check's failure degrades only this check
        out[own] = dict(v=ERRORED, measured=f"check errored: {exc}", citation_state=car.get("citation_state"))
    return out


def _carriage_ledger_inputs(entry, tbl):
    """(column_types, prose_columns) for measure()'s carriage_declared_checks: the table's pg_catalog column facts (read ONLY for an asset that declares a D1 carriage with a spec
    on this table; None when the read failed: unreadable, never "no columns") and the asset's declared Narr prose columns."""
    entry = entry if isinstance(entry, dict) else {}
    car = entry.get("carriage")
    types = None
    if isinstance(car, dict) and car.get("applies") == "D1" and isinstance(car.get("spec"), dict) and car["spec"].get("table") == tbl and tbl:
        try:
            types = carriage_fetch_column_types(tbl)
        except Unknown:
            types = None
    return types, _carriage_prose_columns(entry.get("prose_fields"))


def _carriage_prose_columns(prose_fields) -> list:
    """The columns an asset DECLARES as Narr prose (the first segment of each prose_fields entry: a column name, or `column.$.path`), for the column ledger's fourth class.
    [] when none are declared (null or empty)."""
    out = []
    for e in prose_fields if isinstance(prose_fields, list) else []:
        try:
            out.append(parse_prose_field(e)[0])
        except (DeclarationsError, ValueError, TypeError, IndexError):
            continue
    return list(dict.fromkeys(out))


def carr_checks(record_facts) -> dict:
    """measure()'s Carr.D1/D2/D3 records for one asset: {} unless the asset DECLARES a terminal_by_construction pointer
    (an undeclared asset emits nothing, so its cell reads the rollup's own `not measured` NO_DETECTOR exactly as before;
    an explicit NO_DETECTOR record per check would change every cell's check text for no new information). A declared
    asset gets one independent record per check (the same grading: the declared fact covers D1, D2 and D3 alike)."""
    f = record_facts if isinstance(record_facts, dict) else {}
    tbc = f.get("declared_terminal_by_construction")
    if not (isinstance(tbc, str) and not _blank_text(tbc)):
        return {}
    r = grade_carr_no_carriage(f)
    return {c: dict(r, **({"declaration_disagreements": list(r["declaration_disagreements"])}
                          if "declaration_disagreements" in r else {})) for c in CARR_D_CHECKS}


# ─────────────────────────── E6 S3: declared Vocab.alias and Ldgr.source_presence ───────────────────────────
# Design: scratchpad s3/DESIGN.md. An asset that DECLARES `vocab_alias` / `ldgr_source` (validated above) gets the declared form of the check; an
# undeclared asset reads EXACTLY as before (the legacy pattern measurements in measure() are skipped only for a declaring asset). The records
# carry `declared: True` so the certificate writer does not apply the column-pattern applicability to a declared column.
_ALIAS_WS = re.compile(r"\s+")


def _norm_form(x) -> str:
    """A vocabulary form compared as the ontology compares it: NFKC, casefolded, whitespace collapsed and trimmed."""
    return _ALIAS_WS.sub(" ", unicodedata.normalize("NFKC", str(x))).strip().casefold()


def alias_fetch_forms(cls: str) -> list:
    """[{canonical_id, canonical_name_en, synonyms[]}] of bg_ontology's entities of class `cls`, in canonical_id order: ONE read-only SELECT, the
    answer ONE line of jsonb (the d1_fetch_rows shape). `cls` must be one of ALIAS_CLASSES (a literal in the SQL). Raises Unknown on a failed read."""
    if cls not in ALIAS_CLASSES:
        raise Unknown(f"alias_fetch_forms: {cls!r} is not an alias class ({list(ALIAS_CLASSES)})")
    blob = scalar("SELECT coalesce(jsonb_agg(jsonb_build_object('canonical_id',canonical_id,'canonical_name_en',canonical_name_en,"
                  "'synonyms',to_jsonb(coalesce(synonyms,ARRAY[]::text[]))) ORDER BY canonical_id)::text,'[]') "
                  f"FROM {ONTOLOGY_TABLE} WHERE entity_class = '{cls}'")
    try:
        got = json.loads(blob or "[]")
    except json.JSONDecodeError as exc:
        raise Unknown(f"alias_fetch_forms: unparseable ontology read: {exc}") from exc
    return [g for g in got if isinstance(g, dict)]


def alias_fetch_values(table: str, vocab_col: str, alias_col: str | None = None) -> list:
    """The asset's distinct `[{v, a?, n}]` (the vocabulary value as text, its alias set when `alias_col` is declared, and the rows holding that pair),
    in a total order: ONE read-only GROUP BY SELECT answered as ONE line of jsonb. Identifiers are matched against a strict pattern before they
    reach SQL. Raises Unknown on a failed read."""
    cols = [vocab_col] + ([alias_col] if alias_col else [])
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and all(isinstance(c, str) and _D1_SQL_IDENT.fullmatch(c) for c in cols)):
        raise Unknown(f"alias_fetch_values: malformed identifier(s) {table!r} / {cols!r}")
    sel = f'"{vocab_col}"::text AS v' + (f', to_jsonb("{alias_col}") AS a' if alias_col else "")
    grp = "1, 2" if alias_col else "1"
    order = "g.v, g.a::text" if alias_col else "g.v"
    blob = scalar(f"SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY {order}),'[]')::text FROM "
                  f"(SELECT {sel}, count(*) AS n FROM \"{table}\"{_where_scope(table)} GROUP BY {grp}) g")
    try:
        return json.loads(blob or "[]")
    except json.JSONDecodeError as exc:
        raise Unknown(f"alias_fetch_values: unparseable read of {table}: {exc}") from exc


def _alias_set(a) -> set:
    """The normalised alias set a row carries: a list of strings, or one string; anything else (NULL, a number, a mapping) is no alias set."""
    if isinstance(a, str):
        a = [a]
    return {_norm_form(x) for x in a if isinstance(x, str) and x.strip()} if isinstance(a, list) else set()


def grade_vocab_alias(spec: dict, forms: list, pairs: list) -> dict:
    """The declared Vocab.alias reading (pure): the asset's vocabulary column against bg_ontology's `spec['class']` entities (N-74 (b)).
    Leg 1: every stored value must resolve, normalised, to exactly ONE entity by its canonical id or its display name (`canonical_name_en`); an
    unresolved value is named (a value that is only an ontology synonym says so). Leg 2, only when `alias_column` is declared: every row's alias set
    must carry every ontology synonym of the entity it resolves to (the asset's own id/display name count as present; extra aliases are not a defect);
    a synonym present in the ontology and missing from the asset is named with the entity and the rows affected. PASS needs both legs clean on a
    non-empty table and a non-empty class; FAIL on any unresolved value or missing synonym; NO_DETECTOR (vacuous) on an empty class or no rows.
    WITHOUT an `alias_column` the completeness leg did not run: identity alone is Vocab.identity under another name, so a clean leg 1 reads PARTIAL,
    and PASS only when the declaration states `spec['identity_only']` (true, with its reason): the asset carries no alias set by design."""
    cls, vcol, acol = spec["class"], spec["vocab_column"], spec.get("alias_column")
    rows = sum(int(p.get("n") or 0) for p in pairs if isinstance(p, dict))
    if not forms:
        return dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — bg_ontology holds no entity of class {cls}: nothing to resolve {vcol} against")
    if not pairs or rows == 0:
        return dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the table has no rows: {vcol} resolves nothing on 0 rows (vacuous)")
    ids, names, syns = {}, {}, {}
    for f in forms:
        eid = f.get("canonical_id")
        ids.setdefault(_norm_form(eid), []).append(f)
        if f.get("canonical_name_en"):
            names.setdefault(_norm_form(f["canonical_name_en"]), []).append(f)
        for sy in f.get("synonyms") or []:
            syns.setdefault(_norm_form(sy), []).append(f)
    resolved_by, unresolved, missing, affected, per_entity = {}, {}, {}, 0, set()
    for p in pairs:
        n = int(p.get("n") or 0)
        raw = p.get("v")
        key = _norm_form(raw) if isinstance(raw, str) else None
        hits = {}                                           # canonical_id -> (entity, how it matched); a canonical id outranks the display name
        for idx, by in ((names, "canonical_name_en"), (ids, "canonical_id")):
            for e in (idx.get(key, []) if key is not None else []):
                hits[e["canonical_id"]] = (e, by)
        if len(hits) != 1:
            if raw is None:
                why = "NULL"
            elif hits:
                why = "ambiguous: matches " + ", ".join(sorted(hits))
            elif key in syns:
                why = "only an ontology synonym of " + ", ".join(sorted({e["canonical_id"] for e in syns[key]}))
            else:
                why = "no match"
            slot = unresolved.setdefault("NULL" if raw is None else str(raw), dict(rows=0, why=why))
            slot["rows"] += n
            continue
        ent, by = next(iter(hits.values()))
        resolved_by.setdefault(by, set()).add(str(raw))
        per_entity.add(ent["canonical_id"])
        if acol:
            have = _alias_set(p.get("a")) | {_norm_form(ent["canonical_id"]), _norm_form(ent.get("canonical_name_en") or "")}
            lack = sorted({str(sy) for sy in (ent.get("synonyms") or []) if _norm_form(sy) not in have})
            if lack:
                affected += n
                missing.setdefault(ent["canonical_id"], set()).update(lack)
    bad_rows = affected + sum(u["rows"] for u in unresolved.values())
    block = {"class": cls, "vocab_column": vcol, "alias_column": acol, "rows": rows, "distinct_values": len(pairs),
             "resolved_by": {k: sorted(v) for k, v in sorted(resolved_by.items())},
             "unresolved": {k: dict(u) for k, u in sorted(unresolved.items())},
             "missing_synonyms": {k: sorted(v) for k, v in sorted(missing.items())}, "rows_affected": bad_rows}
    if not unresolved and not missing:
        head = f"{rows} row(s), {len(pairs)} distinct value(s) of {vcol}: all resolve to bg_ontology class {cls} by canonical id or display name"
        if acol:
            return dict(v=PASS, declared=True, severity=0.0, alias=block,
                        measured=f"{head}; every ontology synonym of the {len(per_entity)} resolved entit{'y' if len(per_entity) == 1 else 'ies'} is in {acol}")
        if spec.get("identity_only") is True:
            return dict(v=PASS, declared=True, severity=0.0, alias=block,
                        measured=f"{head}; identity_only declared (the asset carries no alias set by design: {spec.get('identity_only_why')}): ontology synonyms not compared")
        return dict(v=PARTIAL, declared=True, severity=0.0, alias=block,
                    measured=f"{head}; PARTIAL: identity only, the completeness leg (ontology synonyms against an alias set) was not run because no alias_column is "
                             "declared; declare the alias column, or `identity_only: true` with its reason if the asset carries no alias set by design")
    parts = []
    if unresolved:
        parts.append("unresolved " + ", ".join(f"{k!r} ({u['why']}; {u['rows']} row(s))" for k, u in sorted(unresolved.items())))
    if missing:
        parts.append(f"ontology synonym(s) missing from {acol}: " + ", ".join(f"{k}: {', '.join(v)}" for k, v in sorted(missing.items())) +
                     f" ({affected} row(s))")
    return dict(v=FAIL, declared=True, severity=round(bad_rows / rows, 4), alias=block,
                measured=f"{bad_rows}/{rows} row(s) of {vcol} do not resolve cleanly against bg_ontology class {cls}: " + "; ".join(parts))


def vocab_alias_declared_check(aid: str, va, table, cols, keys=None) -> dict:
    """measure()'s Vocab.alias record for an asset that DECLARES `vocab_alias`: {} for an undeclared asset (it reads as before). `table` is the asset's
    DECLARED target table (None = the asset has none: a service); `cols` its catalog column names when the table exists in production and its columns are
    known, else None. `no_alias_class` reads N/A, cause `no-alias-class`, released only by the declared rule. It is NEVER emitted while the table
    carries an alias-like column (the documented `synonyms`, N-73 (4)), and an asset WITH a target table whose columns are unknown (a view, a table absent from
    production) is NO_DETECTOR: the contradiction cannot be checked. A column pattern only ever WITHHOLDS the N/A. A measured declaration is read on the
    target table; with no `alias_column` it is refused beside an alias-like column and otherwise reads at most PARTIAL unless `identity_only` is declared.
    A malformed declaration that reaches here (a hand-built census, an unvalidated dict) reads NO_DETECTOR, never an exception."""
    if not isinstance(va, dict) or (va.get("na") is None and va.get("class") is None):
        return {}
    known = isinstance(cols, (list, tuple, set)) and bool(cols)
    try:
        if va.get("na") is not None:
            if va["na"] != NO_ALIAS_CLASS:
                raise KeyError("na")
            ev = va["evidence"]
            like = alias_like_columns(cols) if known else []
            if like:
                return {"Vocab.alias": dict(v=NO_DET, declared=True,
                                            declaration_disagreements=[dict(field="vocab_alias.na", declared=NO_ALIAS_CLASS, measured=f"the table carries alias-like column(s) {like}")],
                                            measured=f"NO_DETECTOR — no_alias_class is declared but {table} carries the documented alias column(s) {', '.join(like)} "
                                                     "(N-73 (4): it may not be declared where a documented alias exists); the declaration is contradicted")}
            voc = alias_vocab_columns(cols) if known else []
            if voc:
                return {"Vocab.alias": dict(v=NO_DET, declared=True,
                                            declaration_disagreements=[dict(field="vocab_alias.na", declared=NO_ALIAS_CLASS, measured=f"the table carries ontology-aliased vocabulary column(s) {voc}")],
                                            measured=f"NO_DETECTOR — no_alias_class is declared but {table} carries vocabulary column(s) {', '.join(voc)} that the registry's own ontology aliases "
                                                     "(N-150 R3): declare a measured alias class for it; the declaration is contradicted")}
            if table and not known:
                return {"Vocab.alias": dict(v=NO_DET, declared=True,
                                            measured=f"NO_DETECTOR — no_alias_class is declared but the columns of {table} are unknown (a view, or the table is absent from "
                                                     "production): the declaration cannot be checked against a documented alias, so it is not released")}
            return {"Vocab.alias": dict(_na(f"declared no_alias_class (reviewed; evidence: {ev}): {va['why']}", "no-alias-class"), declared=True)}
        if va["class"] not in ALIAS_CLASSES:
            raise KeyError("class")
        spec = {"class": va["class"], "vocab_column": va["vocab_column"], "alias_column": va.get("alias_column"), "table": table,
                "identity_only": va.get("identity_only") is True, "identity_only_why": va.get("identity_only_why")}
        if not (isinstance(spec["vocab_column"], str) and _D1_SQL_IDENT.fullmatch(spec["vocab_column"])):
            raise KeyError("vocab_column")
    except (KeyError, TypeError) as exc:
        return {"Vocab.alias": dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the vocab_alias declaration is malformed ({type(exc).__name__}: {exc}); it was not validated")}
    if not table or not known:
        return {"Vocab.alias": dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the declared alias class ({va['class']}) is measured on the target table, "
                                                                        "which does not exist in production or whose columns are unknown")}
    absent = [c for c in (spec["vocab_column"], spec["alias_column"]) if c and c not in cols]
    if absent:
        return {"Vocab.alias": dict(v=FAIL, declared=True, measured=f"declared column(s) {', '.join(absent)} are not columns of {table}: the declaration names a "
                                                                    "vocabulary the table does not carry")}
    like = alias_like_columns(cols)
    if not spec["alias_column"] and like:
        return {"Vocab.alias": dict(v=NO_DET, declared=True,
                                    declaration_disagreements=[dict(field="vocab_alias.alias_column", declared=None, measured=f"the table carries alias-like column(s) {like}")],
                                    measured=f"NO_DETECTOR — {table} carries the alias column(s) {', '.join(like)} but the declaration names no alias_column: declare it so the "
                                             "ontology synonyms are compared with it (an alias-less identity PASS would bypass the empty-synonyms check)")}
    try:
        forms = alias_fetch_forms(va["class"])
        pairs = alias_fetch_values(table, spec["vocab_column"], spec["alias_column"])
        return {"Vocab.alias": grade_vocab_alias(spec, forms, pairs)}
    except Unknown as exc:                                  # R41: this check's failure degrades only this check
        return {"Vocab.alias": dict(v=ERRORED, declared=True, measured=f"check errored: {exc}")}


# ─────────────────── N-176 (REGISTRY_REVISION 26): the VALUE-BASED Vocab.alias detector ───────────────────
# Vocab.alias used to be decided by COLUMN NAMES (ALIAS_VOCAB_COLUMNS: graha, planet, star_lord ...) and by hand declarations (`vocab_alias: no_alias_class`): 67 assets read NO_DETECTOR because the audits
# removed the false declarations and nothing could decide the rule for the rest, and a column that carries planet names under an innocent name (`label`) was invisible. SS ruling N-176: the check applies to an
# asset if ANY column's VALUES fall in the canonical graha / rashi / nakshatra / bhava vocabulary. So the detector READS THE DATA: for every text-capable or json(b) column of the asset's owned tables it takes a
# BOUNDED, read-only sample (the first VOCAB_SAMPLE_ROWS non-NULL rows: a LIMIT scan that stops there, never a scan of a huge table; json(b): the first VOCAB_JSON_SAMPLE_ROWS rows of at most VOCAB_JSON_MAX_BYTES,
# string leaves to a depth of VOCAB_JSON_DEPTH, at most VOCAB_JSON_MAX_LEAVES leaves) and matches whole values against the canonical vocabularies the repo already holds (brahmagyan/l0_ontology.py ENTITIES,
# classes planet / sign / nakshatra / house, and the L0 semantic release for the graha identities; nothing is invented here).
# A column NAME is a HINT that orders the reads (a `*_lord` column is read first) and decides NOTHING: no name, no suffix, no declaration is a verdict. A declaration `vocab_alias: no_alias_class` is ADVISORY: the
# detector's value finding overrides it (values present: the cell is not N/A; none present in any column read: N/A with an evidence block naming the columns read and the rows sampled; a column that could not be
# sampled: NO_DETECTOR, never N/A).
# GRADING (what a PASS means, chosen here): the existing alias/identity grading is KEPT for an asset that declares a measured alias class (`grade_vocab_alias`, unchanged) and for an undeclared asset with a
# `synonyms` column (the per-class empty-alias census, unchanged). For every other asset that carries vocabulary values: CANONICAL = the exact spelling of a canonical form (ontology canonical_id or
# canonical_name_en; the released canonical subject code or label for a graha): PASS when every value found is canonical (and the whole table was read, or the existence read found no other spelling),
# FAIL when a NON-canonical spelling of a known term is found (an ontology synonym, a case variant, a padded value, a Sanskrit or short alias: what `norm_graha` would accept and rewrite), PARTIAL when the values
# found are canonical in the sample but part of the table or a column was not read.
VOCAB_CLASSES = ("graha", "rashi", "nakshatra", "bhava")
VOCAB_ONTOLOGY_CLASS = {"planet": "graha", "sign": "rashi", "nakshatra": "nakshatra", "house": "bhava"}
VOCAB_SAMPLE_ROWS = 2000            # text / array / enum column: rows sampled (the first N non-NULL rows: a LIMIT scan that stops there)
VOCAB_JSON_SAMPLE_ROWS = 200        # json(b) column: rows sampled
VOCAB_JSON_MAX_BYTES = 262_144      # a json(b) value larger than this (pg_column_size) is NOT traversed: the column then cannot be called free of vocabulary values
VOCAB_JSON_DEPTH = 8                # string leaves down to this depth are read; a document that goes deeper makes the column incomplete
VOCAB_JSON_MAX_LEAVES = 5000
VOCAB_MAX_VALUES = 300              # distinct values kept per column (more = the column is incomplete)
VOCAB_VALUE_CHARS = 120             # a value is cut to this many characters (a vocabulary term is short)
VOCAB_MAX_COLUMNS = 96              # candidate columns read per asset (past it: not read, so never N/A)
VOCAB_BATCH_COLUMNS = 12            # columns per statement (one psql round trip per batch; a failed batch is retried per column)
VOCAB_DETECT_MIN_LEN = 3            # a NON-canonical spelling shorter than this (`SA`, `MA`, `ME`) never makes a column "carry vocabulary values" by itself (too many words are two letters)
VOCAB_SPELLING_SAMPLE = 3
VOCAB_HINT_TOKENS = ("graha", "grahas", "planet", "planets", "lord", "lords", "sign", "signs", "rashi", "nakshatra", "bhava", "house", "star", "dasha", "lagna", "subject")      # ORDER of the reads only: a whole name token (`dasha_lord`, `planet_id`), never a substring (`assignment`)
VOCAB_NA_CAUSE = "no-vocabulary-values"
_VOCAB_LEX: dict | None = None


def _load_sidecar_module(rel: str, name: str):
    """A sidecar module loaded by FILE PATH (the way `_carriage_d1` loads its module): the census is a governance script and never puts the sidecar on sys.path."""
    import importlib.util
    path = SIDECAR / rel
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None or not path.is_file():
        raise Unknown(f"vocabulary source {rel} is not readable in this checkout")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


VOCAB_FAMILY_SOURCE = {"canonical_id": "id", "canonical_name_en": "name", "canonical_subject_code": "code", "canonical_label": "name"}     # the spelling FAMILY of a canonical form: the ontology id (`sun`), the display name (`Sun`), the released code (`SUN`)
VOCAB_EMBED_MIN_LEN = 4             # a canonical form of at least this many characters is searched INSIDE longer text (token boundaries: any non-letter); a 3-letter form only in its exact, not-all-lower-case spelling (Sun, SUN, MAR ...)
VOCAB_EMBED_BOUND = "[^A-Za-z]"
VOCAB_KEY_WORDS = ("graha", "grahas", "planet", "planets", "sign", "signs", "rashi", "rashis", "nakshatra", "nakshatras", "bhava", "bhavas", "house", "houses", "lagna")      # a json KEY with one of these names (or naming a term): embedded vocabulary, never N/A
_VOCAB_EMB_RE: tuple | None = None


def _vocab_emb_pattern(terms, bound=VOCAB_EMBED_BOUND) -> str:
    """One regular expression, the SAME text for PostgreSQL (ARE) and Python `re`: a term between token boundaries (the start, the end, or any non-letter, so `sun_in_aries`, `graha=Sun,sign=Aries` and `Sun <-> Moon` match, `Moonstone` does not). Longest term first."""
    body = "|".join(re.escape(t) for t in sorted(terms, key=lambda t: (-len(t), t)))
    return f"(^|{bound})({body})({bound}|$)"


def vocab_lexicon() -> dict:
    """The canonical graha / rashi / nakshatra / bhava vocabularies the repo already holds, as {canonical: {class: {exact spelling}}, keys: {normalised form: {class}}, family: {canonical form: {'id'|'name'|'code'}},
    emb_ci / emb_cs: the term lists searched INSIDE longer text and their regular expressions}. `canonical` = ontology canonical_id and canonical_name_en (planet, sign, nakshatra, house) plus the released canonical
    subject code and label of every graha identity; `keys` = EVERY spelling the repo knows (those, the ontology synonyms and Sanskrit names, the released aliases and script labels), normalised as the ontology
    normalises (`_norm_form`: NFKC, whitespace collapsed, trimmed, casefolded), so a case variant or a padded value is recognised as a non-canonical spelling of its term; `family` says WHICH canonical spelling a form
    is (one column holding two families, `Moon` and `MOON`, is the cross-layer drift graha_vocabulary.py exists to stop). Loaded once; raises Unknown when the repo's vocabulary modules cannot be read (the check
    then reads NO_DETECTOR, never a verdict)."""
    global _VOCAB_LEX
    if _VOCAB_LEX is not None:
        return _VOCAB_LEX
    ont = _load_sidecar_module("brahmagyan/l0_ontology.py", "_census_l0_ontology")
    rel = _load_sidecar_module("brahmagyan/l0_semantic_release.py", "_census_l0_semantic_release")
    canon: dict = {c: set() for c in VOCAB_CLASSES}
    forms: dict = {c: set() for c in VOCAB_CLASSES}
    fam: dict = {}
    for e in getattr(ont, "ENTITIES", ()):
        cls = VOCAB_ONTOLOGY_CLASS.get(e.get("entity_class"))
        if cls is None:
            continue
        for k in ("canonical_id", "canonical_name_en"):
            if isinstance(e.get(k), str) and e[k].strip():
                canon[cls].add(e[k])
                fam.setdefault(e[k], set()).add(VOCAB_FAMILY_SOURCE[k])
        for k in ("canonical_id", "canonical_name_en", "canonical_name_sa"):
            if isinstance(e.get(k), str) and e[k].strip():
                forms[cls].add(e[k])
        forms[cls] |= {s for s in (e.get("synonyms") or []) if isinstance(s, str) and s.strip()}
    for ent in (getattr(rel, "SEMANTIC_RELEASE", None) or {}).get("entities", ()):
        for k in ("canonical_subject_code", "canonical_label"):
            if isinstance(ent.get(k), str) and ent[k].strip():
                canon["graha"].add(ent[k])
                forms["graha"].add(ent[k])
                fam.setdefault(ent[k], set()).add(VOCAB_FAMILY_SOURCE[k])
        forms["graha"] |= {s for s in (ent.get("aliases") or []) if isinstance(s, str) and s.strip()}
        forms["graha"] |= {s for s in (ent.get("script_labels") or {}).values() if isinstance(s, str) and s.strip()}
    keys: dict = {}
    for cls in VOCAB_CLASSES:
        for f in forms[cls] | canon[cls]:
            if re.fullmatch(r"[0-9]+", f.strip()):
                continue                                         # a bare number is never a vocabulary term (a house number is an integer, not a spelling)
            keys.setdefault(_norm_form(f), set()).add(cls)
    if not any(canon.values()) or not keys:
        raise Unknown("the repo's canonical vocabularies (brahmagyan/l0_ontology.py, l0_semantic_release) hold no graha / rashi / nakshatra / bhava terms")
    allc = {f for c in VOCAB_CLASSES for f in canon[c]}
    # LOCALE-INDEPENDENT FOLDING (review round 2): the SQL must not lean on lower() / \s / ~*, whose reach under a C LC_CTYPE differs from Python's. The whitespace class is the EXPLICIT set of every code point
    # with str.isspace() (what Python's `\s` and strip() use), and the case fold is an explicit translate() over every character whose NFKC-stable case fold lies in the alphabet of the lexicon keys (ASCII capitals,
    # the non-ASCII capitals of the Sanskrit forms: Ś Ū Ā Ṛ Ṅ ...) plus a replace() for the few that fold to two letters (ß): both sides apply the SAME table.
    ws = [c for c in range(0x110000) if chr(c).isspace()]
    ranges, i = [], 0
    while i < len(ws):
        j = i
        while j + 1 < len(ws) and ws[j + 1] == ws[j] + 1:
            j += 1
        ranges.append((ws[i], ws[j]))
        i = j + 1
    ws_class = "[" + "".join(f"\\u{a:04x}" + (f"-\\u{b:04x}" if b != a else "") for a, b in ranges) + "]+"
    alphabet = set("".join(keys)) | set("".join(allc).casefold()) | set(string.ascii_lowercase)
    singles, multis = {}, []
    for cp in range(0x110000):
        if 0xD800 <= cp <= 0xDFFF:
            continue
        ch = chr(cp)
        cf = ch.casefold()
        if cf == ch or not set(cf) <= alphabet or unicodedata.normalize("NFKC", ch) != ch:
            continue
        (singles.__setitem__(ch, cf) if len(cf) == 1 else multis.append((ch, cf)))
    fold_table = {ord(a): b for a, b in singles.items()}
    ci_terms = sorted({_vocab_fold_with(f, fold_table, multis) for f in allc if len(f) >= VOCAB_EMBED_MIN_LEN and not re.fullmatch(r"[0-9]+", f)})
    cs_terms = sorted({f for f in allc if len(f) == VOCAB_EMBED_MIN_LEN - 1 and f != f.lower()})
    _VOCAB_LEX = dict(canonical={c: frozenset(v) for c, v in canon.items()}, keys={k: frozenset(v) for k, v in keys.items()}, family={f: frozenset(v) for f, v in fam.items()},
                      emb_ci=ci_terms, emb_cs=cs_terms, emb_ci_re=_vocab_emb_pattern(ci_terms, "[^a-z]"), emb_cs_re=_vocab_emb_pattern(cs_terms),
                      ws_class=ws_class, ws_points=tuple(ws), fold_from="".join(singles), fold_to="".join(singles.values()), fold_table=fold_table, fold_multi=tuple(multis))
    return _VOCAB_LEX


def _vocab_fold_with(s: str, table: dict, multis) -> str:
    s = re.sub(r"\s+", " ", unicodedata.normalize("NFKC", s)).strip().translate(table)
    for ch, rep in multis:
        s = s.replace(ch, rep)
    return s


def vocab_fold(value: str) -> str:
    """The locale-independent form a value is compared in: NFKC, whitespace runs (every str.isspace() code point) collapsed to one space, trimmed, case-folded by the lexicon's explicit table. For every value this
    equals `_norm_form` wherever the result could be a known form (a test runs the whole code-point range); the SQL twin is `_vocab_norm`. Pure."""
    lex = vocab_lexicon()
    return _vocab_fold_with(value, lex["fold_table"], lex["fold_multi"])


def vocab_classify(value) -> dict | None:
    """None for a value that is no vocabulary term; else {kind: 'canonical'|'alias', classes, detect, short}: `canonical` = the exact spelling of a canonical form; `alias` = a known term in another spelling
    (case variant, padding, whitespace, NFKC form, ontology synonym, Sanskrit or short alias). `detect` says whether the value alone makes its column count as carrying vocabulary values (a canonical form always
    does; an alias shorter than VOCAB_DETECT_MIN_LEN does not); `short` marks that short alias (`Su`, `Ma`, `Sa`: too many words are two letters, so one of them is a WEAK signal: the column then reads PARTIAL, never
    N/A, and two distinct ones, or one beside a canonical value, make it carry vocabulary). Whole-value only: `vocab_embedded` is the token-boundary reading. Pure."""
    if not isinstance(value, str) or not value.strip():
        return None
    lex = vocab_lexicon()
    classes = [c for c in VOCAB_CLASSES if value in lex["canonical"][c]]
    if classes:
        return dict(kind="canonical", classes=classes, detect=True, short=False)
    key = _norm_form(value)
    got = sorted(lex["keys"].get(key, ()))
    if got:
        d = len(key) >= VOCAB_DETECT_MIN_LEN
        return dict(kind="alias", classes=got, detect=d, short=not d)
    return None


def vocab_embedded(value) -> bool:
    """True when `value` holds a canonical term INSIDE longer text between token boundaries (`Sun in 7th house`, `graha=Sun,sign=Aries`, `Mutual Reception: Sun <-> Moon`, `sun_in_aries`): a canonical form of at
    least VOCAB_EMBED_MIN_LEN characters in any case (compared in the folded form, `vocab_fold`), a 3-letter form only in its exact not-all-lower-case spelling (compared in the NFKC form). The twin of the SQL predicate
    `_vocab_p_emb`: the same regular expressions, applied to the same two normalised texts, case-sensitively (no re.I, no ~*: their Unicode reach depends on the locale). Pure."""
    global _VOCAB_EMB_RE
    if not isinstance(value, str):
        return False
    lex = vocab_lexicon()
    if _VOCAB_EMB_RE is None or _VOCAB_EMB_RE[0] is not lex:
        _VOCAB_EMB_RE = (lex, re.compile(lex["emb_ci_re"]), re.compile(lex["emb_cs_re"]) if lex["emb_cs"] else None)
    return bool(_VOCAB_EMB_RE[1].search(vocab_fold(value)) or (_VOCAB_EMB_RE[2] is not None and _VOCAB_EMB_RE[2].search(unicodedata.normalize("NFKC", value))))


def vocab_hint_rank(col: str) -> int:
    """0 when the column NAME carries a vocabulary hint (`*_lord`, `planet`, `sign` ...), else 1. Orders the reads; never a verdict."""
    return 0 if any(t in VOCAB_HINT_TOKENS for t in re.split(r"[^a-z0-9]+", str(col).casefold())) else 1


# ── the SQL twin of the Python classifier: ONE normalisation (NFKC, whitespace runs collapsed to one space, trimmed, lower-cased: `_norm_form`), the same canonical / key / short / embedded sets ──
def _vocab_lit(x) -> str:
    """A SQL string literal for the vocabulary statements (quote-doubled; backslashes pass through under standard_conforming_strings, which the regular expressions need). Refuses NUL."""
    x = str(x)
    if "\x00" in x:
        raise Unknown("vocabulary literal holds a NUL character")
    return "'" + x.replace("'", "''") + "'"


def _vocab_arr(xs) -> str:
    return "ARRAY[" + ",".join(_vocab_lit(x) for x in xs) + "]::text[]"


def vocab_lex_sql() -> str:
    """The `lex` CTE body every vocabulary statement opens with (pure): the canonical spellings, every known normalised form (`keys`), those of at least VOCAB_DETECT_MIN_LEN characters (`detect`), the shorter ones
    (`short`), the json key class words and the two embedded-term regular expressions. One CTE per statement: no per-column copy of these lists."""
    lex = vocab_lexicon()
    canon = sorted({f for c in VOCAB_CLASSES for f in lex["canonical"][c]})
    keys = sorted(lex["keys"])
    detect = [k for k in keys if len(k) >= VOCAB_DETECT_MIN_LEN]
    short = [k for k in keys if len(k) < VOCAB_DETECT_MIN_LEN]
    return (f"SELECT {_vocab_arr(canon)} AS canon, {_vocab_arr(keys)} AS keys, {_vocab_arr(detect)} AS detect, {_vocab_arr(short)} AS short, {_vocab_arr(VOCAB_KEY_WORDS)} AS kwords, "
            f"{_vocab_lit(lex['emb_ci_re'])}::text AS emb_ci, {_vocab_lit(lex['emb_cs_re'])}::text AS emb_cs, {_vocab_lit(lex['ws_class'])}::text AS ws, "
            f"{_vocab_lit(lex['fold_from'])}::text AS tf, {_vocab_lit(lex['fold_to'])}::text AS tt")


def _vocab_norm(v: str) -> str:
    """SQL: the folded form of `v` (the twin of `vocab_fold`), LOCALE-INDEPENDENT by construction: normalize(NFKC) (PostgreSQL 13+, a UTF8 database), translate() over the lexicon's explicit case-fold table,
    replace() for the two-letter folds, every str.isspace() code point (an explicit class, not `\\s`) collapsed to one space, trimmed. No lower(), no locale-dependent character class."""
    lex = vocab_lexicon()
    x = f"translate(normalize({v}, NFKC), (SELECT tf FROM lex), (SELECT tt FROM lex))"
    for ch, rep in lex["fold_multi"]:
        x = f"replace({x}, {_vocab_lit(ch)}, {_vocab_lit(rep)})"
    return f"btrim(regexp_replace({x}, (SELECT ws FROM lex), ' ', 'g'), ' ')"


def _vocab_p_whole(v: str) -> str:
    """SQL: `v` is a whole-value vocabulary hit: the exact canonical spelling, or a known form of at least VOCAB_DETECT_MIN_LEN characters after the shared normalisation."""
    return f"({v} = ANY(((SELECT canon FROM lex)::text[])) OR {_vocab_norm(v)} = ANY(((SELECT detect FROM lex)::text[])))"


def _vocab_p_short(v: str) -> str:
    return f"{_vocab_norm(v)} = ANY(((SELECT short FROM lex)::text[]))"


def _vocab_p_emb(v: str) -> str:
    """SQL: `v` holds a canonical term between token boundaries (the regular expressions `vocab_embedded` uses)."""
    return f"({_vocab_norm(v)} ~ (SELECT emb_ci FROM lex) OR normalize({v}, NFKC) ~ (SELECT emb_cs FROM lex))"


def _vocab_p_key(v: str) -> str:
    """SQL: a json KEY `v` names a known term, or is one of the class words (`planet`, `house` ...)."""
    return f"({_vocab_norm(v)} = ANY(((SELECT detect FROM lex)::text[])) OR {_vocab_norm(v)} = ANY(((SELECT kwords FROM lex)::text[])))"


def _vocab_sample_parts(table: str, col: str, kind: str, where: str | None = None):
    """(ctes, select) of the ONE bounded, read-only sample of a column (pure; the statement wraps them with the `lex` CTE): ONE line of jsonb {rows, values, emb[, oversized, deep, leaves, keys, key_hits]}.
    text / enum: the first VOCAB_SAMPLE_ROWS non-NULL values (`LIMIT` stops the scan); array: the elements of the first VOCAB_SAMPLE_ROWS non-NULL rows; json(b): string leaves (depth <= VOCAB_JSON_DEPTH, at most
    VOCAB_JSON_MAX_LEAVES) and object KEYS of the first VOCAB_JSON_SAMPLE_ROWS rows, a row bigger than VOCAB_JSON_MAX_BYTES counted `oversized` and NOT traversed, a document with a leaf deeper than the depth counted
    `deep`. `values` are distinct (cut to VOCAB_VALUE_CHARS, at most VOCAB_MAX_VALUES: more is flagged by its length); `emb` = up to 5 UNCUT values holding a canonical term inside longer text (a value that IS a
    term is not one of them). No count(*) over the table, no ORDER BY, no GROUP BY: every read of `table` is bounded by a LIMIT. `where` (a boolean SQL expression: the asset's own rows of a SHARED table) restricts
    every read to them."""
    c, t = f'"{col}"', f'"{table}"'
    w = f" AND ({where})" if where else ""
    dist = (f"(SELECT coalesce(jsonb_agg(d.x), '[]'::jsonb) FROM (SELECT DISTINCT left(v, {VOCAB_VALUE_CHARS}) AS x FROM s WHERE v IS NOT NULL LIMIT {VOCAB_MAX_VALUES + 1}) d)")
    emb = (f"(SELECT coalesce(jsonb_agg(e.x), '[]'::jsonb) FROM (SELECT left(v, {VOCAB_VALUE_CHARS}) AS x FROM s WHERE v IS NOT NULL AND {_vocab_p_emb('v')} "
           f"AND NOT {_vocab_p_whole('v')} AND NOT {_vocab_p_short('v')} LIMIT 5) e)")
    if kind == "json":
        ctes = (f"r0 AS (SELECT {c}::jsonb AS a, pg_column_size({c}) AS sz FROM {t} WHERE {c} IS NOT NULL{w} LIMIT {VOCAB_JSON_SAMPLE_ROWS}), "
                f"r AS (SELECT a FROM r0 WHERE sz <= {VOCAB_JSON_MAX_BYTES}), "
                f"s AS (SELECT (e.x #>> '{{}}') AS v FROM r, jsonb_path_query(r.a, 'strict $.**{{0 to {VOCAB_JSON_DEPTH}}}') AS e(x) WHERE jsonb_typeof(e.x) = 'string' LIMIT {VOCAB_JSON_MAX_LEAVES}), "
                f"ks AS (SELECT (kv.x ->> 'key') AS v FROM r, jsonb_path_query(r.a, 'lax $.**{{0 to {VOCAB_JSON_DEPTH}}} ? (@.type() == \"object\").keyvalue()') AS kv(x) LIMIT {VOCAB_JSON_MAX_LEAVES})")
        sel = (f"SELECT jsonb_build_object('rows', (SELECT count(*) FROM r0), 'oversized', (SELECT count(*) FROM r0 WHERE sz > {VOCAB_JSON_MAX_BYTES}), "
               f"'deep', (SELECT count(*) FROM r WHERE jsonb_path_exists(r.a, 'strict $.**{{{VOCAB_JSON_DEPTH + 1} to last}}')), "
               f"'leaves', (SELECT count(*) FROM s), 'keys', (SELECT count(*) FROM ks), 'values', {dist}, 'emb', {emb}, "
               f"'key_hits', (SELECT coalesce(jsonb_agg(k.x), '[]'::jsonb) FROM (SELECT DISTINCT left(v, {VOCAB_VALUE_CHARS}) AS x FROM ks WHERE v IS NOT NULL AND {_vocab_p_key('v')} LIMIT 5) k))")
        return ctes, sel
    if kind == "array":
        ctes = (f"r AS (SELECT {c} AS a FROM {t} WHERE {c} IS NOT NULL{w} LIMIT {VOCAB_SAMPLE_ROWS}), s AS (SELECT u.x::text AS v FROM r, LATERAL unnest(r.a) AS u(x))")
        return ctes, f"SELECT jsonb_build_object('rows', (SELECT count(*) FROM r), 'values', {dist}, 'emb', {emb})"
    ctes = f"s AS (SELECT {c}::text AS v FROM {t} WHERE {c} IS NOT NULL{w} LIMIT {VOCAB_SAMPLE_ROWS})"
    return ctes, f"SELECT jsonb_build_object('rows', (SELECT count(*) FROM s), 'values', {dist}, 'emb', {emb})"


def vocab_sample_sql(table: str, col: str, kind: str, where: str | None = None) -> str:
    """The single-column sample statement (`_vocab_sample_parts` under the `lex` CTE), one line of jsonb text."""
    ctes, sel = _vocab_sample_parts(table, col, kind, where)
    return f"WITH lex AS ({vocab_lex_sql()}), {ctes} {sel}::text"


def vocab_batch_sql(table: str, cols_kinds, where: str | None = None) -> str:
    """ONE statement that samples several columns of `table` (pure): a jsonb object {column: the column's sample answer}. One `lex` CTE, each column a scalar sub-select with its own bounded scan."""
    parts = ", ".join(f"{_vocab_lit(c)}, (WITH {_vocab_sample_parts(table, c, k, where)[0]} {_vocab_sample_parts(table, c, k, where)[1]})" for c, k in cols_kinds)
    return f"WITH lex AS ({vocab_lex_sql()}) SELECT jsonb_build_object({parts})::text"


def _vocab_values_src(table: str, col: str, kind: str, where: str | None = None) -> str:
    c, t = f'"{col}"', f'"{table}"'
    w = f" AND ({where})" if where else ""
    return (f"SELECT u.x::text AS v FROM {t}, LATERAL unnest({c}) AS u(x) WHERE {c} IS NOT NULL{w}" if kind == "array" else f"SELECT {c}::text AS v FROM {t} WHERE {c} IS NOT NULL{w}")


def _vocab_pred_on(v: str) -> str:
    """SQL: `v` is a whole-value hit, a short alias, or holds a canonical term inside longer text (what the existence probe looks for)."""
    return f"({_vocab_p_whole(v)} OR {_vocab_p_short(v)} OR {_vocab_p_emb(v)})"


def vocab_probe_sql(table: str, col: str, kind: str, where: str | None = None) -> str:
    """The bounded EXISTENCE probe of a column whose sample is not the whole column and found nothing (pure): up to 3 values anywhere in the column that are a whole-value hit, a short alias or hold a canonical term
    inside longer text (the SAME predicates the sample uses), as one line of jsonb {hits[, key_hits, oversized, deep]}. The scan stops at the first rows found (LIMIT, no count, no ORDER BY); an empty answer means
    the scan REACHED THE END of the column with none, which is the only thing that lets an incomplete column read as free of vocabulary. json(b): leaves and keys of every row of at most VOCAB_JSON_MAX_BYTES; a
    bigger row, or a document deeper than VOCAB_JSON_DEPTH, is reported (`oversized`, `deep`) because it was not looked into."""
    c, t = f'"{col}"', f'"{table}"'
    pred = _vocab_pred_on("v")
    w = f" AND ({where})" if where else ""
    if kind == "json":
        return (f"WITH lex AS ({vocab_lex_sql()}), r AS (SELECT {c}::jsonb AS a FROM {t} WHERE {c} IS NOT NULL{w} AND pg_column_size({c}) <= {VOCAB_JSON_MAX_BYTES}), "
                f"lv AS (SELECT (e.x #>> '{{}}') AS v FROM r, jsonb_path_query(r.a, 'strict $.**{{0 to {VOCAB_JSON_DEPTH}}}') AS e(x) WHERE jsonb_typeof(e.x) = 'string'), "
                f"ks AS (SELECT (kv.x ->> 'key') AS v FROM r, jsonb_path_query(r.a, 'lax $.**{{0 to {VOCAB_JSON_DEPTH}}} ? (@.type() == \"object\").keyvalue()') AS kv(x)) "
                f"SELECT jsonb_build_object('hits', (SELECT coalesce(jsonb_agg(h.x), '[]'::jsonb) FROM (SELECT left(v, {VOCAB_VALUE_CHARS}) AS x FROM lv WHERE v IS NOT NULL AND {pred} LIMIT 3) h), "
                f"'key_hits', (SELECT coalesce(jsonb_agg(k.x), '[]'::jsonb) FROM (SELECT left(v, {VOCAB_VALUE_CHARS}) AS x FROM ks WHERE v IS NOT NULL AND {_vocab_p_key('v')} LIMIT 3) k), "
                f"'oversized', EXISTS (SELECT 1 FROM {t} WHERE {c} IS NOT NULL{w} AND pg_column_size({c}) > {VOCAB_JSON_MAX_BYTES} LIMIT 1), "
                f"'deep', EXISTS (SELECT 1 FROM r WHERE jsonb_path_exists(r.a, 'strict $.**{{{VOCAB_JSON_DEPTH + 1} to last}}') LIMIT 1))::text")
    return (f"WITH lex AS ({vocab_lex_sql()}) SELECT jsonb_build_object('hits', (SELECT coalesce(jsonb_agg(h.x), '[]'::jsonb) FROM "
            f"(SELECT left(w.v, {VOCAB_VALUE_CHARS}) AS x FROM ({_vocab_values_src(table, col, kind, where)}) w WHERE {_vocab_pred_on('w.v')} LIMIT 3) h))::text")


def vocab_spelling_sql(table: str, col: str, kind: str, offfam=(), where: str | None = None) -> str:
    """The bounded existence read of everything the whole-value sample would have graded in a column already found to carry vocabulary values, over the REST of the column (pure). ONE scan first (`EXISTS ... LIMIT 1`
    over the union of the four categories: a clean column costs one scan); when something exists, up to VOCAB_SPELLING_SAMPLE values PER CATEGORY (cut to VOCAB_VALUE_CHARS characters, each its own `LIMIT`, no count,
    no ORDER BY), as one line of jsonb {spell, off, emb, short}: `spell` a non-canonical spelling (not an exact canonical form, whose form under the SAME normalisation as the Python classifier is a known form),
    `off` a canonical spelling OUTSIDE the column's own spelling family (`offfam`: a second family is the drift the sample would have flagged), `emb` a canonical term inside longer text (a value that is no term
    itself), `short` a short alias (Su, Mo ...). Every category is read separately so one kind cannot crowd another out of the sample (a spelling is a FAIL, the others PARTIAL). text / enum / array only (json(b) is read
    by its sample and probe alone). `where` restricts the read to the asset's own rows of a shared table."""
    src = _vocab_values_src(table, col, kind, where)
    spell = f"(w.v <> ALL(((SELECT canon FROM lex)::text[])) AND {_vocab_norm('w.v')} = ANY(((SELECT keys FROM lex)::text[])) AND NOT {_vocab_p_short('w.v')})"
    off = f"w.v = ANY({_vocab_arr(sorted(offfam))})" if offfam else "false"
    emb = f"({_vocab_p_emb('w.v')} AND NOT {_vocab_p_whole('w.v')} AND NOT {_vocab_p_short('w.v')})"
    short = _vocab_p_short("w.v")
    def cat(p):
        return f"(SELECT coalesce(jsonb_agg(c.x), '[]'::jsonb) FROM (SELECT left(w.v, {VOCAB_VALUE_CHARS}) AS x FROM ({src}) w WHERE {p} LIMIT {VOCAB_SPELLING_SAMPLE}) c)"
    return (f"WITH lex AS ({vocab_lex_sql()}) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM ({src}) w WHERE ({spell} OR {off} OR {emb} OR {short}) LIMIT 1) THEN '{{}}'::jsonb "
            f"ELSE jsonb_build_object('spell', {cat(spell)}, 'off', {cat(off)}, 'emb', {cat(emb)}, 'short', {cat(short)}) END::text")


def vocab_candidate_columns(tables: dict, udts=None):
    """([(table, column, kind)] ordered by name HINT then table / column order, [problems]): the text-capable and json(b) columns of the owned `tables` ({table: (columns, types)}), up to VOCAB_MAX_COLUMNS.
    A table whose columns or types were not read is a problem (nothing can be said about it), never 'no candidate'. A column of a type that cannot carry text (numbers, timestamps, uuid, vectors) is
    not a candidate. Pure."""
    cands, problems = [], []
    for t, (cols, types) in tables.items():
        if not (isinstance(cols, (list, tuple, set)) and cols and isinstance(types, dict)):
            problems.append(f"{t}: columns or column types not read")
            continue
        lacking = [c for c in cols if c not in types]
        if lacking:
            problems.append(f"{t}: no type read for {sorted(lacking)}")
            continue
        for c in cols:
            kind = prose_none_kind(types.get(c), ((udts or {}).get(t) or {}).get(c))
            if kind is not None and _D1_SQL_IDENT.fullmatch(t) and _D1_SQL_IDENT.fullmatch(c):
                cands.append((t, c, kind))
    order = {t: i for i, t in enumerate(tables)}
    cands.sort(key=lambda x: (vocab_hint_rank(x[1]), order[x[0]], x[1]))
    if len(cands) > VOCAB_MAX_COLUMNS:
        problems += [f"{t}.{c}: beyond the {VOCAB_MAX_COLUMNS}-column read cap" for t, c, _k in cands[VOCAB_MAX_COLUMNS:]]
        cands = cands[:VOCAB_MAX_COLUMNS]
    return cands, problems


def _vocab_json_loads(blob, what: str):
    try:
        return json.loads(blob or "null")
    except json.JSONDecodeError as exc:
        raise Unknown(f"vocab {what}: unparseable answer: {exc}") from exc


def vocab_parse_sample(blob, kind: str):
    """The answer of `vocab_sample_sql` as {rows, values, emb, key_hits, complete, ...} (pure). `complete` says the sample IS the whole column: fewer rows than the limit, no truncated value list, and for json(b)
    no oversized row, no too-deep document and no leaf / key cap hit. Raises Unknown on an answer that does not parse."""
    got = _vocab_json_loads(blob, "sample")
    if not (isinstance(got, dict) and isinstance(got.get("rows"), int) and isinstance(got.get("values"), list)):
        raise Unknown(f"vocab sample: malformed answer {str(blob)[:80]!r}")
    vals = [v for v in got["values"] if isinstance(v, str)]
    limit = VOCAB_JSON_SAMPLE_ROWS if kind == "json" else VOCAB_SAMPLE_ROWS
    truncated = len(vals) > VOCAB_MAX_VALUES
    vals = vals[:VOCAB_MAX_VALUES]
    out = dict(rows=got["rows"], values=vals, truncated=truncated, emb=[v for v in (got.get("emb") or []) if isinstance(v, str)])
    complete = got["rows"] < limit and not truncated
    if kind == "json":
        out.update(oversized=int(got.get("oversized") or 0), deep=int(got.get("deep") or 0), leaves=int(got.get("leaves") or 0), keys=int(got.get("keys") or 0),
                   key_hits=[v for v in (got.get("key_hits") or []) if isinstance(v, str)])
        complete = complete and not out["oversized"] and not out["deep"] and out["leaves"] < VOCAB_JSON_MAX_LEAVES and out["keys"] < VOCAB_JSON_MAX_LEAVES
    out["complete"] = complete
    return out


def vocab_parse_probe(blob, kind: str) -> dict:
    """The answer of `vocab_probe_sql` as {hits, key_hits, oversized, deep} (pure). Raises Unknown on an answer that does not parse."""
    got = _vocab_json_loads(blob, "probe")
    if not (isinstance(got, dict) and isinstance(got.get("hits"), list)):
        raise Unknown(f"vocab probe: malformed answer {str(blob)[:80]!r}")
    return dict(hits=[v for v in got["hits"] if isinstance(v, str)], key_hits=[v for v in (got.get("key_hits") or []) if isinstance(v, str)],
                oversized=bool(got.get("oversized")), deep=bool(got.get("deep")))


def vocab_fetch_samples(table: str, cols_kinds, where: str | None = None) -> dict:
    """{column: sample dict | {unread: reason}} for the columns of `table`, in batches of VOCAB_BATCH_COLUMNS (one psql round trip each). A batch that fails is retried column by column, so one hostile
    column cannot hide the others; a column whose read fails (a statement timeout, a type the sample cannot cast) is `unread` with the cause: NEVER read as 'no vocabulary values'."""
    out: dict = {}
    cols_kinds = list(cols_kinds)
    for i in range(0, len(cols_kinds), VOCAB_BATCH_COLUMNS):
        batch = cols_kinds[i:i + VOCAB_BATCH_COLUMNS]
        try:
            blob = scalar(vocab_batch_sql(table, batch, where))
            got = json.loads(blob or "null")
            if not (isinstance(got, dict) and set(got) == {c for c, _k in batch}):
                raise Unknown("batch answer does not carry every column")
            for c, k in batch:
                out[c] = vocab_parse_sample(json.dumps(got[c]), k)
            continue
        except (Unknown, ValueError, OSError):
            pass
        for c, k in batch:
            try:
                out[c] = vocab_parse_sample(scalar(vocab_sample_sql(table, c, k, where)), k)
            except (Unknown, ValueError, OSError) as exc:
                why = " ".join(str(exc).split())[:200]
                out[c] = dict(unread=("the bounded sample exceeded the statement timeout: " if _is_statement_timeout(exc) else "the bounded sample failed: ") + why)
    return out


def vocab_fetch_probe(table: str, col: str, kind: str, where: str | None = None) -> dict:
    """The existence probe of `vocab_probe_sql` ({hits, key_hits, oversized, deep}), or {unread: cause} when it is cancelled or fails: the column then stays UNSAMPLED (never read as free of vocabulary)."""
    try:
        return vocab_parse_probe(scalar(vocab_probe_sql(table, col, kind, where)), kind)
    except (Unknown, ValueError, OSError) as exc:
        return dict(unread=("the existence probe exceeded the statement timeout: " if _is_statement_timeout(exc) else "the existence probe failed: ") + " ".join(str(exc).split())[:160])


def vocab_fetch_spelling(table: str, col: str, kind: str, offfam=(), where: str | None = None) -> dict:
    """{found: bool, sample: [values of every category], emb: [...], short: [...], off: [...], spell: [...]} from `vocab_spelling_sql`, or {unread: cause} when the read is cancelled or fails (the column is then
    graded from its sample alone). The values go back through the same grader as the sample's, so a spelling, a second family, an embedded term and a short alias read exactly as they do inside the sample."""
    try:
        got = json.loads(scalar(vocab_spelling_sql(table, col, kind, offfam, where)) or "null")
        if not isinstance(got, dict):
            raise Unknown("malformed spelling answer")
        cats = {k: [str(x) for x in (got.get(k) or [])] for k in ("spell", "off", "emb", "short")}
        allv = list(dict.fromkeys(x for k in ("spell", "off", "emb", "short") for x in cats[k]))
        return dict(found=bool(allv), sample=allv, **cats)
    except (Unknown, ValueError, OSError) as exc:
        return dict(unread=("exceeded the statement timeout" if _is_statement_timeout(exc) else "failed") + ": " + " ".join(str(exc).split())[:160])


def vocab_families(canonical) -> frozenset:
    """The spelling families (`id`, `name`, `code`) EVERY canonical value of a column belongs to: empty when the column mixes two (`Moon` and `MOON`). Pure."""
    fam = vocab_lexicon()["family"]
    sets = [fam.get(v, frozenset()) for v in canonical]
    return frozenset.intersection(*sets) if sets else frozenset()


def vocab_off_family(canonical) -> list:
    """The canonical spellings that would be a SECOND family beside the column's own (empty when the column already mixes families or holds no canonical value). Pure."""
    fams = vocab_families(canonical)
    if not canonical or not fams:
        return []
    lex = vocab_lexicon()
    allc = {f for c in VOCAB_CLASSES for f in lex["canonical"][c]}
    return sorted(f for f in allc if not (lex["family"].get(f, frozenset()) & fams))


def vocab_grade_column(table: str, col: str, kind: str, sample: dict, spelling=None, probe=None) -> dict:
    """The reading of ONE column (pure): {table, column, kind, rows_sampled, complete, read, carries, weak, embedded, key_hits[, classes, canonical, spellings, families, mixed]} for a column read, or {unread} for
    one that could not be read to its end. The values come from the sample, then from `probe` (the existence probe of an incomplete column that showed nothing) and `spelling` (the existence read of spellings
    / a second family in a column that carries values). `carries` = a whole-value hit (a canonical form, or a known spelling of at least VOCAB_DETECT_MIN_LEN characters, or two distinct short aliases, or a short
    alias beside a canonical value). `weak` = ONE short alias and nothing else (`Sa`, `Ma`: PARTIAL, never N/A). `embedded` = a canonical term INSIDE longer text (`Sun in 7th house`, `sun_in_aries`), `key_hits` =
    a json key naming a term or a class (`{"planet": 5}`): the column holds vocabulary whose spelling is not checked. `complete` = the whole column was examined: read whole, or an incomplete sample whose existence
    probe came back EMPTY. A column that is neither complete nor showing a hit is `unread`: it can hide a value."""
    base = dict(table=table, column=col, kind=kind)
    if sample.get("unread"):
        return dict(base, unread=sample["unread"])
    values = list(dict.fromkeys(list(sample["values"]) + ([v for v in spelling.get("sample", [])] if isinstance(spelling, dict) and not spelling.get("unread") else [])
                                + ([v for v in probe.get("hits", [])] if isinstance(probe, dict) and not probe.get("unread") else [])))
    emb = {v for v in sample.get("emb") or [] if vocab_classify(v) is None}
    key_hits = set(sample.get("key_hits") or []) | (set(probe.get("key_hits") or []) if isinstance(probe, dict) and not probe.get("unread") else set())
    canon, spell, short, classes = set(), set(), set(), set()
    for v in values:
        r = vocab_classify(v)
        if r is None:
            if vocab_embedded(v):
                emb.add(v)
            continue
        classes |= set(r["classes"])
        (canon if r["kind"] == "canonical" else short if r["short"] else spell).add(v)
    carries = bool(canon or spell) or len(short) >= 2
    if carries:
        spell |= short                                            # a short alias beside a canonical value (or a second one) is a non-canonical spelling of a term
        short = set()
    probe_clean = (isinstance(probe, dict) and not probe.get("unread") and not probe.get("hits") and not probe.get("key_hits") and not probe.get("oversized") and not probe.get("deep"))
    unmatched = isinstance(probe, dict) and not probe.get("unread") and bool(probe.get("hits")) and not (canon or spell or short or emb)
    weak = bool(short)
    shows = carries or weak or bool(emb) or bool(key_hits) or unmatched
    complete = bool(sample["complete"]) or probe_clean
    if not shows and not complete:
        if probe is None:
            why = "the sample is not the whole column and no existence probe was made"
        elif probe.get("unread"):
            why = f"the rest of the column was not read ({probe['unread']})"
        else:
            why = "part of the column could not be sampled (" + "; ".join(x for x in (["rows larger than the json size cap were not traversed"] if probe.get("oversized") else []) + (["a document deeper than the depth cap"] if probe.get("deep") else []) or ["the existence probe did not reach the end"]) + ")"
        return dict(base, unread=why, rows_sampled=sample["rows"])
    rec = dict(base, rows_sampled=sample["rows"], complete=complete, carries=carries, weak=weak, embedded=sorted(emb)[:5], key_hits=sorted(key_hits)[:5],
               read="whole column" if sample["complete"] else "existence probe (whole column, none found)" if probe_clean else "sample")
    if unmatched:
        rec["probe_unclassified"] = True
    if probe is not None and not probe.get("unread"):
        rec["probe"] = dict(clean=probe_clean, hits=probe.get("hits", [])[:3])
    if sample.get("oversized"):
        rec["oversized_rows_skipped"] = sample["oversized"]
    if sample.get("deep"):
        rec["deeper_than_read"] = sample["deep"]
    if int(sample.get("leaves") or 0) >= VOCAB_JSON_MAX_LEAVES or int(sample.get("keys") or 0) >= VOCAB_JSON_MAX_LEAVES:
        rec["leaf_cap_hit"] = True
    if weak:
        rec["short_aliases"] = sorted(short)
    if carries:
        fams = vocab_families(canon)
        rec.update(classes=sorted(classes), canonical=sorted(canon), spellings=sorted(spell), families=sorted(fams), mixed=bool(canon) and not fams)
        if spelling is not None:
            if spelling.get("unread"):
                rec["spelling_read"] = dict(unread=spelling["unread"])
            else:
                rec["spelling_read"] = dict(found=spelling["found"], sample=spelling["sample"])
    return rec


def vocab_values_record(cols: list, problems: list, tables, aid: str = "", declared: dict | None = None, scopes: dict | None = None) -> dict:
    """The Vocab.alias record from the readings of every candidate column (pure). FAIL: a non-canonical spelling of a known term was found. PARTIAL: values were found and every one is canonical but part of the asset was
    not read, or a column MIXES canonical spelling families (`Moon` and `MOON`: the cross-layer drift), or a column holds vocabulary the whole-value reading cannot grade (a term inside longer text, a json key naming a
    term or a class, one short alias): never N/A, never PASS. PASS: values found, every one canonical in ONE spelling family per column, every column examined whole (or by a clean existence read), nothing embedded,
    nothing unread. N/A (cause no-vocabulary-values): every candidate column examined to its END (read whole, or an incomplete sample followed by an existence probe that found nothing), no hit of any kind, at
    least one row seen. NO_DETECTOR: nothing could be read, the table has no rows, or a column could not be examined to its end and nothing was found. `declared` carries a `vocab_alias` declaration that this value
    reading OVERRIDES (advisory)."""
    unread = [f"{c['table']}.{c['column']}: {c['unread']}" for c in cols if c.get("unread")] + list(problems)
    read = [c for c in cols if not c.get("unread")]
    for c in read:                  # a part of a json(b) column the bounded read could not look into is UNSAMPLED: it can hide a value, so it is never read as 'none found'
        gaps = ([f"{c['oversized_rows_skipped']} row(s) larger than {VOCAB_JSON_MAX_BYTES} bytes not traversed"] if c.get("oversized_rows_skipped") else []) \
            + ([f"{c['deeper_than_read']} document(s) deeper than {VOCAB_JSON_DEPTH} levels"] if c.get("deeper_than_read") else []) \
            + ([f"leaf cap {VOCAB_JSON_MAX_LEAVES} reached"] if c.get("leaf_cap_hit") else [])
        if gaps and not c.get("complete"):
            unread.append(f"{c['table']}.{c['column']}: part of the column could not be sampled ({'; '.join(gaps)})")
    found = [c for c in read if c.get("carries")]
    weak = [c for c in read if c.get("weak")]
    embedded = [c for c in read if c.get("embedded") or c.get("key_hits") or c.get("probe_unclassified")]
    mixed = [c for c in found if c.get("mixed")]
    rows_seen = sum(int(c.get("rows_sampled") or 0) for c in read)
    keep = ("table", "column", "kind", "classes", "canonical", "spellings", "families", "mixed", "rows_sampled", "complete", "read", "spelling_read", "oversized_rows_skipped", "deeper_than_read", "leaf_cap_hit")
    block = dict(checked=True, read="bounded sample, then an existence probe of every incomplete column that showed nothing (first rows of each column, read-only)", tables=sorted(tables), columns_read=len(read),
                 rows_sampled={f"{c['table']}.{c['column']}": c["rows_sampled"] for c in read}, complete_columns=sorted(f"{c['table']}.{c['column']}" for c in read if c["complete"]),
                 probed_columns=sorted(f"{c['table']}.{c['column']}" for c in read if (c.get("probe") or {}).get("clean")),
                 found=[{k: v for k, v in c.items() if k in keep} for c in found],
                 embedded=[dict(table=c["table"], column=c["column"], examples=c.get("embedded", []), key_hits=c.get("key_hits", [])) for c in embedded],
                 weak=[dict(table=c["table"], column=c["column"], short_aliases=c.get("short_aliases", [])) for c in weak],
                 unread=unread, hint_tokens=list(VOCAB_HINT_TOKENS), scopes=dict(scopes or {}))
    adv = {}
    if isinstance(declared, dict) and declared.get("na") is not None:
        adv = dict(declared_advisory=dict(declared=declared.get("na"), overridden_by="the value reading (N-176): a declaration is advisory, the data decides"))
    spells = [c for c in found if c.get("spellings")]
    if spells:
        what = "; ".join(f"{c['table']}.{c['column']} ({'/'.join(c['classes'])}): " + ", ".join(repr(s) for s in c["spellings"][:6]) for c in spells)
        return dict(v=FAIL, vocab_values=block, **adv,
                    measured=f"non-canonical spelling(s) of a graha / rashi / nakshatra / bhava term found by value in {len(spells)} column(s): {what} (canonical = the ontology canonical id or display name, or the "
                             f"released graha code or label; read by a bounded sample of {len(read)} column(s)" + ("; unread: " + "; ".join(unread[:3]) if unread else "") + ")")
    emb_txt = "; ".join(f"{c['table']}.{c['column']} ({', '.join(repr(x) for x in (c.get('embedded') or c.get('key_hits') or ['a matched value'])[:3])})" for c in embedded)
    weak_txt = "; ".join(f"{c['table']}.{c['column']} ({', '.join(c.get('short_aliases', []))})" for c in weak)
    mixed_txt = "; ".join(f"{c['table']}.{c['column']} ({', '.join(c['canonical'][:6])}: no single spelling family)" for c in mixed)
    if found:
        lab = ", ".join(f"{c['table']}.{c['column']} ({'/'.join(c['classes'])}: {', '.join(c['canonical'][:6]) or 'short aliases only'})" for c in found)
        partial = [c for c in found if not c["complete"] and not (c.get("spelling_read") and not c["spelling_read"].get("unread") and not c["spelling_read"]["found"])]
        why = ([f"{c['table']}.{c['column']} was read by a bounded sample only" for c in partial] + ([f"unread: {'; '.join(unread[:3])}"] if unread else [])
               + ([f"MIXED canonical spelling families in one column: {mixed_txt} (the cross-layer drift graha_vocabulary.py exists to stop; PARTIAL, not PASS)"] if mixed else [])
               + ([f"embedded vocabulary, spelling unchecked: {emb_txt}"] if embedded else []) + ([f"one short alias only, unverified: {weak_txt}"] if weak else []))
        if why:
            return dict(v=PARTIAL, vocab_values=block, **adv, measured=f"vocabulary values found by value in {len(found)} column(s): {lab}; every whole value found is canonical, but: {'; '.join(why)}")
        return dict(v=PASS, vocab_values=block, **adv,
                    measured=f"vocabulary values found by value in {len(found)} column(s): {lab}; every value found is canonical, in one spelling family per column (whole column read, or an existence read found no other spelling)")
    if embedded or weak:
        return dict(v=PARTIAL, vocab_values=block, **adv,
                    measured=("embedded vocabulary, spelling unchecked: " + emb_txt if embedded else "") + ("; " if embedded and weak else "") + (("one short alias only (two letters), unverified: " + weak_txt) if weak else "")
                             + "; no whole value is a term, so the spelling cannot be graded: PARTIAL, never N/A" + (f"; unread: {'; '.join(unread[:3])}" if unread else ""))
    if unread:
        return dict(v=NO_DET, vocab_values=block, **adv,
                    measured=f"NO_DETECTOR — no vocabulary value was found in the {len(read)} column(s) read, but column(s) could not be examined to their end: {'; '.join(unread[:4])}: not N/A, never PASS")
    if rows_seen == 0:
        return dict(v=NO_DET, vocab_values=block, **adv,
                    measured=f"NO_DETECTOR — the owned table(s) {', '.join(sorted(tables))} hold no rows in any candidate column ({len(read)} column(s) read): vacuous, not N/A")
    sampled = ", ".join(f"{k} {n}" for k, n in sorted(block["rows_sampled"].items())[:8])
    return dict(_na(f"no graha / rashi / nakshatra / bhava value in any of the {len(read)} text-capable or json column(s) of {', '.join(sorted(tables))}: every column examined to its END ({len(block['complete_columns']) - len(block['probed_columns'])} "
                    f"read whole, {len(block['probed_columns'])} by an existence probe that reached the end of the column and found nothing; rows sampled: {sampled}{' ...' if len(block['rows_sampled']) > 8 else ''}). WHAT WAS SEARCHED: whole values "
                    f"(the canonical spellings and every known alias, under one NFKC / whitespace / case normalisation), canonical terms of at least {VOCAB_EMBED_MIN_LEN} characters between token boundaries inside longer text "
                    "(and the exact-case 3-letter forms), json keys naming a term or a class word. NOT searched: an alias embedded in longer text, a lower-case 3-letter word; column names are a hint only (N-176)", "no-vocabulary-values"),
                vocab_values=block, **adv)


def vocab_value_detect(own: dict, udts=None, declared: dict | None = None, cache: dict | None = None, scopes: dict | None = None) -> dict:
    """The value-based Vocab.alias record for an asset (N-176). `own` = {table: (columns, types)} of its owned tables that exist in production. Reads only: bounded samples (one batch statement per table), then,
    per column, an existence PROBE of the whole column when the sample is incomplete and showed nothing or only a weak / embedded signal (the only way an incomplete column can read as free of vocabulary), and, for an
    incomplete column that showed anything, ONE existence read of the REST of the column for every category the sample grades: a non-canonical spelling, a second spelling family, a term inside longer text, a short
    alias (so a shape beyond the sample reads exactly as the same shape inside it). `scopes` ({table: {where, label}}) restricts the reads of a table SHARED with other assets to this asset's own rows (the
    registry's count_sql predicate or the declared produced_tables filter): without it a shared table's reading would be one verdict for every asset that writes into it. Never raises for a column's failure
    (that column is `unread`); a vocabulary the repo cannot load, or no owned table, is a NO_DETECTOR record naming why. `cache` ({key: answer}, owned by the caller for ONE layer run; its keys carry the scope)
    keeps a table's samples and probes from being read again for every asset that reads the same rows; without it nothing is remembered."""
    cache = cache if cache is not None else {}
    scopes = scopes or {}
    try:
        vocab_lexicon()
    except Unknown as exc:
        return dict(v=NO_DET, measured=f"NO_DETECTOR — the value reading needs the repo's canonical vocabularies: {exc}")
    cands, problems = vocab_candidate_columns(own, udts)
    if not own:
        return dict(v=NO_DET, measured="NO_DETECTOR — the asset owns no table that exists in production: nothing to read the vocabulary from")
    blocked = {t: v["block"] for t, v in scopes.items() if v.get("block") and t in own}
    if blocked:                                              # a table with no rows in the scope (or whose scope is unknown) is not read: nothing to judge
        problems += [f"{t}: {why}" for t, why in sorted(blocked.items())]
        cands = [x for x in cands if x[0] not in blocked]
    by_table: dict = {}
    for t, c, k in cands:
        by_table.setdefault(t, []).append((c, k))
    readings = []

    def memo(key, fn):
        if key not in cache:
            cache[key] = fn()
        return cache[key]
    for t, cks in by_table.items():
        w = (scopes.get(t) or {}).get("where")
        missing = [(c, k) for c, k in cks if ("sample", t, c, k, w) not in cache]
        if missing:
            got = vocab_fetch_samples(t, missing, w)
            for c, k in missing:
                cache[("sample", t, c, k, w)] = got.get(c) or dict(unread="no sample came back")
        for c, k in cks:
            s = cache[("sample", t, c, k, w)]
            rec, probe = vocab_grade_column(t, c, k, s), None
            if rec.get("unread") and not s.get("unread"):                  # incomplete and showing nothing: the existence probe of the whole column decides
                probe = memo(("probe", t, c, k, w), lambda: vocab_fetch_probe(t, c, k, w))
                rec = vocab_grade_column(t, c, k, s, probe=probe)
            if not rec.get("unread") and not rec["complete"] and not rec.get("spellings") and k in ("text", "enum", "array"):
                off = vocab_off_family(rec.get("canonical", []))
                rec = vocab_grade_column(t, c, k, s, spelling=memo(("spelling", t, c, k, tuple(off), w), lambda: vocab_fetch_spelling(t, c, k, off, w)), probe=probe)
            readings.append(rec)
    order = {(t, c): i for i, (t, c, _k) in enumerate(cands)}
    readings.sort(key=lambda r: order.get((r["table"], r["column"]), 0))
    return vocab_values_record(readings, problems, list(own), declared=declared, scopes={t: v.get("label") for t, v in scopes.items() if t in own})


def vocab_scopes(tables, r: dict, own: dict, shared, decl, chart_id: str) -> dict:
    """{table: {where, label}} for the owned tables the value reading must restrict to THIS asset's rows (review round 2, MED-3): a table SHARED with another asset of the layer (chart_facts is written by eight)
    holds rows that are not this asset's, and an unscoped reading would give all of them one verdict (a non-canonical spelling written by one asset FAILs the other seven). The asset's rows are named, in order of
    preference, by (1) its DECLARED `produced_tables` filter for that table ({column, equals}: the writer's own row set), (2) the predicate of its registry `count_sql` on that table (`_count_scope_tail`, bound to
    the census chart like the count itself). A shared table whose rows neither names (a count_sql with no predicate, one the scan cannot read, a failed bind) is read WHOLE and the label says so: the reading then
    rests on every asset's rows in it. A table that is not shared is read whole and needs no entry. Pure but for `_bind_chart` (which only validates and substitutes)."""
    out = {}
    produced = declared_produced_tables(decl) or []
    for t in tables:
        if t not in shared:
            continue
        mine = [d for d in produced if d["table"] == t]
        flts = [d["filter"] for d in mine if d.get("filter") and _D1_SQL_IDENT.fullmatch(d["filter"]["column"])]
        if flts and len(flts) == len(mine):                  # EVERY declared entry for the table names a filter: the asset's rows are the UNION of them (an unfiltered entry = the whole table, no restriction)
            out[t] = dict(where=" OR ".join(f'("{f["column"]}"::text = {_vocab_lit(f["equals"])})' for f in flts),
                          label=f"the asset's declared produced rows ({len(flts)} filter{'s' if len(flts) != 1 else ''}, ORed): " + "; ".join(f'{f["column"]} = {f["equals"]!r}' for f in flts))
            continue
        tail = _count_scope_tail((r or {}).get("count_sql") or "", t)
        if tail is None:
            out[t] = dict(where=None, label="shared table, the asset's rows are not named by its count_sql: read whole (every asset's rows in it)")
            continue
        try:
            bound = _bind_chart(tail, chart_id).strip()
        except Unknown:
            out[t] = dict(where=None, label="shared table, the count_sql predicate could not be bound: read whole (every asset's rows in it)")
            continue
        bound = re.sub(r"^\s*where\s+", "", bound, flags=re.I).strip()
        if not bound:
            out[t] = dict(where=None, label="shared table, its count_sql names no row predicate: read whole (every asset's rows in it)")
        else:
            out[t] = dict(where=bound, label="the asset's own rows by its registry count_sql predicate: " + " ".join(bound.split())[:200])
    return out


READ_SCOPE_CRITERIA = ("Narr.agree", "Narr.checkable", "Narr.fidelity_test", "Narr.lint", "Null.schema_default", "Null.blank_rows", "Ldgr.source_presence", "Vocab.alias", "Vocab.identity", "Complete.depth")


def _tail_mentions_chart(tail: str) -> bool:
    """True when a count_sql tail refers to the chart AT ALL: a `$1` parameter or any `chart_id` reference, case- and quote-insensitive (`chart_id = $1::uuid`, `chart_id::text = $1`, `"chart_id" = $1`,
    `c.chart_id = $1`). A table is GLOBAL only when its count_sql tail has neither: any other tail keeps the chart scope (the matcher of `_chart_pinned` is deliberately narrower: it decides whether a COUNT is
    exact, not whether a READ is chart-scoped)."""
    return bool(re.search(r"\$1(?!\d)|chart_id", tail or "", re.I))


def read_scopes(tables, r: dict, cols_of: dict, shared, decl, chart_id: str) -> dict:
    """{table: {where, label}} the live data reads of the asset must be scoped to (SS, interim census: bo_chart_gestalt's label check judged OTHER charts' older rows). For every owned table:
    - a table that carries a `chart_id` column is read through `"chart_id" = '<census chart>'`, unless the asset's registry count_sql on it is readable and NOT chart-bound (the asset is declared global: whole table,
      said so); an unreadable count_sql keeps the chart scope (the registry's count_sql is chart-bound for a chart-scoped asset);
    - a table with no chart_id column is global: read whole, said so;
    - a table SHARED with another asset of the layer is further restricted to the asset's own rows (`vocab_scopes`: its declared produced_tables filter, else its count_sql predicate), or read whole with the label
      saying every asset's rows are in it.
    The chart id is validated like every chart binding (a uuid, never the dead phantom): a chart that cannot be bound raises Unknown, so no chart-scoped table is ever judged on other charts' rows. Pure but for that check."""
    if chart_id.startswith(_PHANTOM_CHART_PREFIX):
        raise Unknown(f"refusing chart scope {chart_id}: the 362f9f17-… chart id is a dead phantom")
    if not re.fullmatch(r"[0-9a-fA-F-]{36}", chart_id):
        raise Unknown(f"chart scope {chart_id!r} is not a uuid")
    rows = vocab_scopes(tables, r, {}, shared, decl, chart_id)
    out = {}
    for t in tables:
        cols = cols_of.get(t)
        parts, labels = [], []
        if not (isinstance(cols, (list, tuple, set)) and cols):
            # the columns could not be READ: whether the table carries a chart_id column is unknown, so the read cannot be scoped and must not be made (NO_DETECTOR with this cause), never "no chart column: whole table"
            out[t] = dict(where=None, label="columns not read: whether the table is chart-scoped is unknown", block="the table's columns could not be read, so it is unknown whether it carries a chart_id column and the read cannot be scoped to the measured chart: not read (NO_DETECTOR), never judged on every chart's rows")
            continue
        if "chart_id" in cols:
            tail = _count_scope_tail((r or {}).get("count_sql") or "", t)
            if tail is not None and not _tail_mentions_chart(tail):
                labels.append("whole table (global: the registry count_sql carries no $1 and no chart_id reference)")
            else:
                parts.append(f'"chart_id" = {_vocab_lit(chart_id)}')       # ANY chart reference (`chart_id = $1::uuid`, `chart_id::text = $1`, "chart_id", c.chart_id ...) or an unreadable count_sql keeps the chart scope
                labels.append(f"chart {chart_id[:8]}")
        else:
            labels.append("whole table (global: no chart_id column)")
        rs = rows.get(t)
        if rs:
            if rs.get("where"):
                parts.append(rs["where"])
            labels.append(rs["label"])
        out[t] = dict(where=" AND ".join(f"({x})" for x in parts) or None, label="; ".join(labels))
    return out


def stamp_read_scope(m: dict, scopes: dict) -> None:
    """Name, on every record that rests on a live data read, which scope was read ('chart <id>' or 'whole table (global)' ...): `read_scope` {table: label} of the asset's owned tables."""
    if not scopes:
        return
    for c in READ_SCOPE_CRITERIA:
        if isinstance(m.get(c), dict):
            m[c] = dict(m[c], read_scope={t: v["label"] for t, v in sorted(scopes.items())})


def vocab_values_na_problem(crit: str, meas) -> str | None:
    """None unless a Vocab.alias N/A of cause no-vocabulary-values is NOT backed by its checked `vocab_values` block (N-176): the block must be `checked`, name the owned tables, show at least one row sampled,
    no unread column, no vocabulary value found, nothing embedded and no short alias, and EVERY column that was read must be in `complete_columns` (read whole, or examined by an existence probe that reached the
    end of the column: a sample is never enough). A record without it is not a release. Pure; read by `_check_contribution` and `_na_released`."""
    if crit != "Vocab.alias" or not isinstance(meas, dict) or meas.get("v") != NA or meas.get("cause") != VOCAB_NA_CAUSE:
        return None
    b = meas.get("vocab_values")
    ok = (isinstance(b, dict) and b.get("checked") is True and isinstance(b.get("tables"), list) and b["tables"] and b.get("found") == [] and b.get("unread") == []
          and b.get("embedded") == [] and b.get("weak") == [] and isinstance(b.get("rows_sampled"), dict) and isinstance(b.get("complete_columns"), list)
          and sum(n for n in b["rows_sampled"].values() if isinstance(n, int) and not isinstance(n, bool)) > 0 and set(b["rows_sampled"]) <= set(b["complete_columns"]))
    if not ok:
        return ("Vocab.alias N/A (no-vocabulary-values) rests on the value reading (N-176): every text-capable / json column examined to its END (read whole, or an existence probe that reached the end), no graha / "
                "rashi / nakshatra / bhava value, term inside longer text or short alias found, none unread, at least one row sampled; this record does not carry that evidence block, so it is not a release")
    return None


def vocab_value_merge(existing, declared, found: dict | None, columns_known: bool) -> dict | None:
    """Which Vocab.alias record measure() keeps once the value reading exists (pure). `existing` = the record the older readings produced for this asset (None for an undeclared asset without a
    `synonyms` census); `declared` its `vocab_alias` declaration; `found` the value reading (None when it was not run). The value reading REPLACES: an undeclared asset's absent record; a declared
    `no_alias_class` (an N/A, or the name-based disagreement the old rule raised: a name decides nothing). It does NOT replace a record of a declared MEASURED alias class (the existing alias / identity
    grading), the per-class `synonyms` census, or a `no_alias_class` contradicted by an alias-like column the table documents (N-73 (4): a documented alias set stays a hard disagreement)."""
    if found is None:
        return existing
    declared_na = isinstance(declared, dict) and declared.get("na") is not None
    declared_class = isinstance(declared, dict) and declared.get("class") is not None
    if declared_class:
        return existing
    if existing is None:
        return found
    if declared_na:
        dis = [d for d in (existing.get("declaration_disagreements") or []) if isinstance(d, dict)]
        alias_like = any("alias-like" in str(d.get("measured", "")) for d in dis)
        if alias_like:
            return existing
        if existing.get("cause") == "no-alias-class" and not columns_known:
            return existing                      # no readable table: the declared N/A (an asset with no table) stands
        return found
    return existing


# What counts as NO source (N-73 (1): a source-status disclosure is not a source; adversarial review M3). A value is compared AFTER normalisation: leading and trailing
# whitespace, punctuation, dashes, quotes and invisible/format characters (_LDGR_JUNK, an explicit Unicode-aware set, so a Devanagari citation is never mistaken for
# punctuation under a C locale) are stripped, internal whitespace collapsed, case folded. A value that normalises to '' (pure junk: '-', '.', U+2014, tab, NBSP,
# U+200B, '{}', '""') or to one of these forms lacks a source. Quote-free: they are SQL literals.
LDGR_PLACEHOLDERS = ("", "not traced", "not traced yet", "untraced", "unsourced", "not sourced", "no source", "no sources", "no citation", "no reference",
                     "source unidentified", "source not identified", "unidentified", "unknown", "n/a", "n.a", "na", "nil", "none", "null", "nan", "not available",
                     "not applicable", "not found", "not given", "pending", "tbd", "tba", "todo", "to do", "to be added", "to be determined", "missing", "false", "0")
# C2(ii) (REGISTRY_REVISION 24, SS N-98): the CITATION-only extension of the closed list, applied by `_ldgr_lacking` (every Ldgr caller, the legacy undeclared reading AND the declared
# ldgr_source check: N-98 named the legacy reading; the declared check shares the one predicate on purpose, so declaring ldgr_source cannot escape the rule) and NEVER by the Null
# convention detector (which calls `_ldgr_lacking_text` with its default, so a text column that legitimately holds the word elsewhere is not a Null fallback). Each entry is a spelling
# the L0 writers are read to write INTO a citation column, stored here in its NORMALISED form (junk stripped at the ends, lower case):
#   'classical_tradition'          the bare tradition label: brahma_dosha_catalog.classical_citations holds [{"text_id": "classical_tradition"}] on the tradition-rooted doshas
#                                  (brahmagyan/l0_doshas.py:111 and 40-odd siblings, written by json.dumps at :1976), and the repo already treats that value as a non-citation
#                                  (pipeline/orchestrator/writers/bg_parihara_rules.py:28 / :106 / :135: "real (non-placeholder) citation", `text_id <> 'classical_tradition'`);
#                                  reference tables carry it as source_citation (brahmagyan/l0_reference.py:829-838, :926-961: reference_constants / reference_glossary, not measured targets).
#   'classical tradition (jyotish'  the label "classical tradition (Jyotish)" as it normalises (the trailing ')' is junk and is stripped): brahma_ontology.source_citation on the dosha
#                                  rows (l0_doshas.py:39, :1999) and brahma_remedy_corpus.source_citation (l0_remedy_corpus.py:46 SOURCE_CLASSICAL, used from :334).
#   'vastu shastra tradition (nairitya corner'  VASTU_TRADITION = "Vastu Shastra tradition (Nairitya corner)" (brahmagyan/l0_vastu_directions.py:32), written to
#                                  bg_vastu_directions.classical_citation on the Southwest row (:108, 1 of 8 rows): a tradition label, not a citation (a measured target).
# DECIDED NOT TO ADD (each traced to the table it lands in): VASTU_TRAD_GENERAL "Vastu Shastra tradition" (l0_vastu_directions.py:33, written at :126-246) lands in
# bg_vastu_direction_remedials, which is not any asset's target_table (bg_vastu_directions' target is bg_vastu_directions), so no measured Ldgr cell reads it; 'Tajaka tradition'
# (l0_reference.py:954-958) is a reference_glossary citation (written at :1555), not a measured target either (bg_reference measures reference_planets). Add either only if a
# measured Ldgr target ever holds it. '(unextracted)' (brahmagyan/l0_text_chunker.py:224, "<source_prefix> (unextracted)") STAYS a source: the source prefix is kept. A bare
# 'classical tradition' (no underscore, no parenthesis) has no writer spelling here and stays a citation.
# PREFIXES: a status word that LEADS a sentence disclosing there is no source: the six Rahu/Ketu house-vedha rows of bg_transit_rules carry "UNSOURCED - no house-transit vedha
# doctrine ..." (brahmagyan/l0_transit.py:80-86, written at :764 and five siblings; migration 1079 counts them with LIKE 'UNSOURCED%'). The exact 'unsourced' is already in the list; the
# prefix is the same word followed by a separator (so never inside a longer word; the bare word needs no prefix rule, the list has it).
LDGR_CITATION_PLACEHOLDERS = ("classical_tradition", "classical tradition (jyotish", "vastu shastra tradition (nairitya corner")
LDGR_CITATION_PLACEHOLDER_PREFIXES = ("unsourced",)
# INVISIBLE characters are removed everywhere in the value (soft hyphen, combining grapheme joiner, Arabic letter mark, Hangul/Braille/Hangul-filler blanks, Mongolian
# and zero-width/format/bidi controls, variation selectors, BOM, interlinear/tag characters): they print as nothing, so 'n<SHY>/a' is 'n/a'. JUNK is stripped from the
# ends (whitespace, punctuation, dashes, quotes, dandas). Both are explicit sets (the database may be UTF8 with a C collation, where [[:alnum:]] / [[:punct:]] know ASCII only).
_LDGR_INVISIBLE = (r"[\u00ad\u034f\u061c\u115f\u1160\u17b4\u17b5\u180b-\u180f\u200b-\u200f\u202a-\u202e\u2060-\u206f\u2800\u3164\ufe00-\ufe0f\ufeff\uffa0\ufff9-\ufffd"
                   r"\U000e0000-\U000e007f\U000e0100-\U000e01ef]")
_LDGR_JUNK = (r"[[:space:][:punct:]\u00a0\u00a1\u00ab\u00b7\u00bb\u00bf\u0964\u0965\u1680\u2000-\u206f\u2212\u2e00-\u2e7f\u3000-\u303f\ufe00-\ufe6f\ufeff\uff01-\uff0f\uff1a-\uff20]")
_LDGR_SPACE = r"[[:space:]\u00a0\u1680\u2000-\u200b\u2028\u2029\u202f\u205f\u3000\ufeff]"
LDGR_TEXT_TYPES = ("text", "character varying", "character", "bpchar", "citext")


def _ldgr_lacking_text(x: str, citation: bool = False) -> str:
    """The SQL predicate 'the text expression `x` states no source': NULL, or after NFKC normalisation (fullwidth 'ＮＯＮＥ' -> 'NONE'; needs a UTF8 database, a
    non-UTF8 one raises and the check reads ERRORED), removal of INVISIBLE characters, stripping of JUNK at the ends, whitespace collapse and case folding, an empty
    value or one of LDGR_PLACEHOLDERS; or the fallback: no alphanumeric character at all in an all-ASCII value (control characters, stray symbols). A value with a
    non-ASCII character outside the explicit sets (a Devanagari citation) is a source whatever the database locale classifies as alnum.
    `citation=True` (C2(ii), pin 24: `_ldgr_lacking`, i.e. every Ldgr.source_presence reading, declared or not) ALSO applies LDGR_CITATION_PLACEHOLDERS (a bare tradition label is
    a label, not a citation) and LDGR_CITATION_PLACEHOLDER_PREFIXES ('UNSOURCED - ...' discloses there is no source). The default (False) is the Null convention's fallback test:
    it grades every value exactly as before pin 24.
    COST: the normalised value is computed once per call in a derived table (OFFSET 0 stops the planner pulling the subquery up and re-evaluating the normalisation at each
    comparison); measured on 400k-1.5M rows the effect on its own is between none and 2x, so the legacy Ldgr read does not rely on it: it evaluates this predicate once per DISTINCT
    value (ldgr_legacy_count_sql). The grading is unchanged (the differential tests hold the old expression's results)."""
    words = LDGR_PLACEHOLDERS + (LDGR_CITATION_PLACEHOLDERS if citation else ())
    lst = ",".join("'" + w + "'" for w in words)
    # S1 (review F2): the SAME list is also compared with the spaces removed, so 'N / A', 'n o n e' and 'not  found' are the placeholders they spell; ONE definition for Ldgr and Null
    lst_nospace = ",".join("'" + w + "'" for w in dict.fromkeys(w.replace(" ", "") for w in words))
    pre = (f" OR v.norm ~ '^({'|'.join(LDGR_CITATION_PLACEHOLDER_PREFIXES)}){_LDGR_JUNK}'" if citation else "")
    inner = f"SELECT regexp_replace(normalize({x}, NFKC), '{_LDGR_INVISIBLE}+', '', 'g') AS n0 OFFSET 0"
    mid = (f"SELECT a.n0, lower(regexp_replace(regexp_replace(a.n0, '^{_LDGR_JUNK}+|{_LDGR_JUNK}+$', '', 'g'), '{_LDGR_SPACE}+', ' ', 'g')) AS norm "
           f"FROM ({inner}) a OFFSET 0")
    return (f"({x} IS NULL OR (SELECT v.norm IN ({lst}) OR replace(v.norm, ' ', '') IN ({lst_nospace}){pre} "
            f"OR (v.n0 !~ '[[:alnum:]]' AND v.n0 !~ '[^\\x01-\\x7f]') FROM ({mid}) v))")


def _py_junk(ch: str) -> bool:
    """Python reading of `_LDGR_JUNK` (the SQL class is POSIX [[:space:][:punct:]] plus explicit ranges, which `re` cannot express): whitespace, ASCII punctuation, any Unicode
    punctuation category, and the same explicit extras."""
    o = ord(ch)
    return (ch.isspace() or ch in string.punctuation or unicodedata.category(ch).startswith("P") or ch in "\u00a0\u00a1\u00ab\u00b7\u00bb\u00bf\u0964\u0965\u1680\u2212"
            or 0x2000 <= o <= 0x206f or 0x2e00 <= o <= 0x2e7f or 0x3000 <= o <= 0x303f or 0xfe00 <= o <= 0xfe6f or o == 0xfeff or 0xff01 <= o <= 0xff0f or 0xff1a <= o <= 0xff20)


def ldgr_placeholder_py(x) -> bool:
    """E5.7 (Worker E): the PYTHON form of `_ldgr_lacking_text` with its default (the Null convention's fallback test, not the citation extension): True when the text value `x` states
    nothing: empty, or after NFKC, removal of invisible characters, stripping of junk at the ends, whitespace collapse and case folding one of LDGR_PLACEHOLDERS (also with the spaces
    removed), or an all-ASCII value with no alphanumeric character. ONE vocabulary for the SQL predicate and the writer-source scan (writer_literal_scan.py takes this as `is_placeholder`)."""
    if not isinstance(x, str):
        return False
    n0 = re.sub(_LDGR_INVISIBLE + "+", "", unicodedata.normalize("NFKC", x))
    lo, hi = 0, len(n0)
    while lo < hi and _py_junk(n0[lo]):
        lo += 1
    while hi > lo and _py_junk(n0[hi - 1]):
        hi -= 1
    norm = re.sub(r"[\s\u00a0\u1680\u2000-\u200b\u2028\u2029\u202f\u205f\u3000\ufeff]+", " ", n0[lo:hi]).lower()
    words = set(LDGR_PLACEHOLDERS)
    if norm in words or norm.replace(" ", "") in {w.replace(" ", "") for w in words}:
        return True
    return (not any(ch.isalnum() for ch in n0) and all(ord(ch) < 0x80 for ch in n0)) if n0 else True


def _ldgr_lacking(col: str, kind: str, any_element: bool = True) -> str:
    """The SQL predicate 'this row's source column states no source' for a text / text[] / json(b) column. An array, or a JSON array, is lacking when empty or when ANY
    element is (`any_element=True`, the declared ldgr_source reading: every cited element must be a source); with `any_element=False` (the legacy undeclared presence count,
    C2(ii)) it is lacking when empty or when EVERY element is, so a row that cites one real source beside a tradition label still names a source. A JSON string is tested as
    text; a JSON object or array (also nested inside one) is lacking unless at least one STRING LEAF (any depth) passes the same text
    test, so {"source":"not traced"}, {"a":null}, {"a":{}} and [{"src":"n/a"}] lack a source; numbers, booleans and nulls are never sources.
    The text test is `_ldgr_lacking_text(..., citation=True)`: the shared list plus the citation-only placeholders and prefixes (pin 24)."""
    c = f'"{col}"'
    if kind == "text":
        return _ldgr_lacking_text(c, True)
    if kind == "array":
        el = f"EXISTS (SELECT 1 FROM unnest({c}) AS e(x) WHERE {_ldgr_lacking_text('e.x', True)})" if any_element else \
             f"NOT EXISTS (SELECT 1 FROM unnest({c}) AS e(x) WHERE NOT {_ldgr_lacking_text('e.x', True)})"
        return f"({c} IS NULL OR cardinality({c}) = 0 OR {el})"

    def elem(e):
        leaf = (f"NOT EXISTS (SELECT 1 FROM jsonb_path_query({e}, 'strict $.**') AS l(x) WHERE jsonb_typeof(l.x) = 'string' "
                f"AND NOT {_ldgr_lacking_text('(l.x #>> ' + chr(39) + '{}' + chr(39) + ')', True)})")
        return (f"(CASE jsonb_typeof({e}) WHEN 'string' THEN {_ldgr_lacking_text('(' + e + ' #>> ' + chr(39) + '{}' + chr(39) + ')', True)} "
                f"WHEN 'object' THEN {leaf} WHEN 'array' THEN {leaf} ELSE true END)")
    arr = (f"EXISTS (SELECT 1 FROM jsonb_array_elements({c}::jsonb) AS je(x) WHERE {elem('je.x')})" if any_element else
           f"NOT EXISTS (SELECT 1 FROM jsonb_array_elements({c}::jsonb) AS je(x) WHERE NOT {elem('je.x')})")
    return (f"({c} IS NULL OR (CASE jsonb_typeof({c}::jsonb) WHEN 'array' THEN (jsonb_array_length({c}::jsonb) = 0 OR {arr}) "
            f"ELSE {elem(c + '::jsonb')} END))")


LDGR_KIND_CAST = {"text": "::text", "array": "::text[]", "json": "::jsonb"}


def ldgr_legacy_count_sql(table: str, col: str, kind: str) -> str:
    """The ONE read of the legacy Ldgr reading for a text-like column (`kind` is ldgr_column_kind): rows / NULL rows / placeholder rows as one line of jsonb, over the WHOLE table.
    Identifiers must already match the strict pattern. DISTINCT VALUES, NOT ROWS: the table is grouped by the column's value first (a hash aggregate, one pass) and the shared
    placeholder predicate runs ONCE PER DISTINCT VALUE, weighted by that value's row count: a 1.46M-row citation column with a handful of distinct citations costs a scan and a
    hash aggregate, not 1.46M normalisations (the per-row form exceeded the production statement timeout on chart_dashas). Same predicate, same counts as the per-row form
    (differential test). The column is cast to its comparison type first (text / text[] / jsonb: citext would otherwise group case-insensitively and a `json` column has no equality)."""
    pred = _ldgr_lacking("v", kind, any_element=False)
    return (f'WITH d AS (SELECT "{col}"{LDGR_KIND_CAST[kind]} AS v, count(*) AS n FROM "{table}"{_where_scope(table)} GROUP BY 1) '
            f"SELECT jsonb_build_object('rows',coalesce(sum(n),0),'null',coalesce(sum(n) FILTER (WHERE v IS NULL),0),"
            f"'placeholder',coalesce(sum(n) FILTER (WHERE v IS NOT NULL AND {pred}),0))::text FROM d")


def ldgr_legacy_presence(table: str, col: str, rows: int) -> dict:
    """The UNDECLARED asset's Ldgr.source_presence record (C2(ii), pin 24): {v, measured[, ldgr_legacy]} for its first recognised citation column `col` over `rows` rows
    (the depth census count). A row names a source when the column is not NULL AND not a placeholder: `_ldgr_lacking(col, kind, any_element=False)`, the SAME shared predicate
    as the declared ldgr_source check (NULL, junk, the closed LDGR_PLACEHOLDERS list, a bare tradition label, an 'UNSOURCED ...' disclosure; an array / JSON array lacks only when
    empty or when EVERY element lacks). ONE verdict rule for every column type: PASS = every row names a source, FAIL = none does (this includes an all-NULL column, which read PARTIAL
    before pin 24; it is the declared grader's rule), PARTIAL otherwise. A column whose type cannot carry text (integer, uuid, ...), or a table / column name outside the strict
    identifier pattern, can hold no placeholder: it keeps the `col IS NOT NULL` count (and the same verdict rule). When no row is a placeholder the record text is the pre-pin-24
    `<col> populated on N/R rows`; when some row is a placeholder the text states the exact counts and the record carries `ldgr_legacy` {source_column, rows, null, placeholder,
    present}; a read that times out is PARTIAL with `ldgr_legacy.incomplete` and the text says it was not measured (a key distinct from the declared record's `ldgr`, which has a different shape). Raises Unknown on a failed read."""
    ident = _D1_SQL_IDENT
    kind = ldgr_column_kind(ldgr_fetch_column_type(table, col)) if (ident.fullmatch(table or "") and ident.fullmatch(col or "")) else None
    if kind is None:
        n = int(scalar(f"SELECT count(*)::text FROM {table} WHERE {_sw(table, f'{col} IS NOT NULL')}"))
        return dict(v=(PASS if n == rows else (FAIL if n == 0 else PARTIAL)), measured=f"{col} populated on {n}/{rows} rows")
    try:
        blob = scalar(ldgr_legacy_count_sql(table, col, kind))
    except Unknown as exc:
        if not (isinstance(exc, CheckTimeout) or "statement timeout" in str(exc)):
            raise                                              # any other failure is ERRORED, as for every check
        # the table is too large for the read to finish inside the timeout: nothing was measured, so the cell says exactly that: never PASS, never FAIL, never a silent ERRORED
        return dict(v=PARTIAL, measured=(f"{col}: the placeholder-aware count could not complete within the timeout on {rows} rows ({'client' if isinstance(exc, CheckTimeout) else 'statement'} timeout): "
                                         "NOT measured, so neither PASS nor FAIL"),
                    ldgr_legacy=dict(source_column=col, rows=rows, incomplete="timeout"))
    try:
        got = json.loads(blob or "{}")
    except json.JSONDecodeError as exc:
        raise Unknown(f"ldgr_legacy_presence: unparseable read of {table}: {exc}") from exc
    if not (isinstance(got, dict) and all(isinstance(got.get(k), int) for k in ("rows", "null", "placeholder"))):
        raise Unknown(f"ldgr_legacy_presence: malformed answer for {table}.{col}")
    nonnull, ph = got["rows"] - got["null"], got["placeholder"]
    present = nonnull - ph
    v = PASS if present == rows else (FAIL if present == 0 else PARTIAL)
    if ph == 0:
        return dict(v=v, measured=f"{col} populated on {nonnull}/{rows} rows")
    return dict(v=v, measured=(f"{col} names a source on {present}/{rows} rows ({ph} placeholder row(s), which are not a citation: a status word, 'UNSOURCED ...' or a bare "
                               f"tradition label such as 'classical_tradition'; {got['null']} NULL)"),
                ldgr_legacy=dict(source_column=col, rows=rows, null=got["null"], placeholder=ph, present=present))


def ldgr_column_kind(type_text) -> str | None:
    """'text' | 'array' | 'json' for a source column's Postgres type (format_type text), None for any other type (a boolean, an integer, a date is not a
    citation: the check reads NO_DETECTOR with the type named, never a PASS)."""
    t = re.sub(r"\(.*?\)", "", str(type_text or "")).strip().lower()
    if t in LDGR_TEXT_TYPES:
        return "text"
    if t.endswith("[]") and t[:-2].strip() in LDGR_TEXT_TYPES:
        return "array"
    if t in ("jsonb", "json"):
        return "json"
    return None


def ldgr_fetch_column_type(table: str, col: str) -> str:
    """The declared source column's Postgres type (`format_type`, e.g. 'text', 'character varying(40)', 'text[]', 'jsonb', 'boolean') or '' when the column is not
    found: ONE read-only catalog SELECT. Identifiers are matched against a strict pattern before they reach SQL. Raises Unknown on a failed read."""
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and isinstance(col, str) and _D1_SQL_IDENT.fullmatch(col)):
        raise Unknown(f"ldgr_fetch_column_type: malformed identifier(s) {table!r} / {col!r}")
    out = scalar("SELECT coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = to_regclass('\"" + table + "\"') "
                 f"AND a.attname = '{col}' AND a.attnum > 0 AND NOT a.attisdropped), '')")
    return (out or "").strip()


def ldgr_fetch_source_stats(table: str, col: str, keycols=(), kind: str = "text") -> dict:
    """{rows, lacking, sample[{key col: value}]}: the table's row count, how many rows carry NO source in `col` (see LDGR_PLACEHOLDERS / _ldgr_lacking: NULL,
    pure junk, a placeholder, or for an array / JSON array any lacking element), and up to 5 identities (the first key columns, total ORDER BY) of rows that
    lack one: ONE read-only SELECT over the WHOLE table (no chart slice: for a chart-scoped asset it reads every chart, for a shared table it counts rows other
    assets wrote), answered as ONE line of jsonb. `kind` is ldgr_column_kind of the column. Identifiers are matched against a strict pattern before they reach SQL."""
    keys = list(dict.fromkeys(keycols or ()))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and isinstance(col, str) and _D1_SQL_IDENT.fullmatch(col)
            and all(isinstance(k, str) and _D1_SQL_IDENT.fullmatch(k) for k in keys) and kind in ("text", "array", "json")):
        raise Unknown(f"ldgr_fetch_source_stats: malformed identifier(s) / kind {table!r} / {col!r} / {keys!r} / {kind!r}")
    pred = _ldgr_lacking(col, kind)
    q = ",".join(chr(34) + k + chr(34) for k in keys)
    sample = ("'[]'::jsonb" if not keys else
              f"(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT {q} FROM \"{table}\" WHERE {_sw(table, pred)} ORDER BY {q} LIMIT 5) s)")
    blob = scalar(f"SELECT jsonb_build_object('rows',count(*),'lacking',count(*) FILTER (WHERE {pred}),'sample',{sample})::text FROM \"{table}\"{_where_scope(table)}")
    try:
        got = json.loads(blob or "{}")
    except json.JSONDecodeError as exc:
        raise Unknown(f"ldgr_fetch_source_stats: unparseable read of {table}: {exc}") from exc
    if not (isinstance(got, dict) and isinstance(got.get("rows"), int) and isinstance(got.get("lacking"), int)):
        raise Unknown(f"ldgr_fetch_source_stats: malformed answer for {table}.{col}")
    return got


def grade_ldgr_source(ls: dict, stats: dict, table: str) -> dict:
    """The declared Ldgr.source_presence reading (pure): the declared source column names a source on every row. PASS: every row names one; PARTIAL: some
    rows lack one (the sample names which); FAIL: no row names one; NO_DETECTOR: no rows (vacuous), and ALSO any would-be PASS or PARTIAL whose declared
    citation_state is `unsourced` or `refuted` (the column is populated but the claim is not sourced; the same cap Carr.D1 applies in its detector, so the raw
    record, the gap ledger and the rollup all agree: it never reads PASS). The record carries the DECLARED citation_state.
    The read is over the WHOLE table: for a chart-scoped asset every chart, and for a shared table the verdict rests on rows other assets wrote."""
    col, cs = ls["source_column"], ls["citation_state"]
    rows, lacking = stats["rows"], stats["lacking"]
    if rows == 0:
        return dict(v=NO_DET, declared=True, citation_state=cs,
                    measured=f"NO_DETECTOR — {table} has no rows: {col} names a source on 0 rows (vacuous)")
    sample = stats.get("sample") or []
    where = ("; rows lacking one: " + json.dumps(sample, sort_keys=True, default=str) + (" (first 5)" if lacking > len(sample) else "")) if lacking and sample else \
            ("; row identity unavailable (no declared key)" if lacking else "")
    v = PASS if lacking == 0 else (FAIL if lacking == rows else PARTIAL)
    text = (f"declared source column {col} names a source on {rows - lacking}/{rows} rows (NULL, blank, punctuation-only, 'not traced'-style placeholders, a bare tradition label "
            f"such as 'classical_tradition' and an 'UNSOURCED ...' disclosure do not count); citation_state {cs}{where}")
    if v in (PASS, PARTIAL) and cs in CITATION_CAPPED_STATES:
        return dict(v=NO_DET, declared=True, citation_state=cs, ldgr=dict(source_column=col, rows=rows, lacking=lacking, sample=sample),
                    measured=f"NO_DETECTOR — the column is populated as {text}, but the declared citation_state is {cs!r}: a source that is {cs} is never a PASS")
    return dict(v=v, declared=True, citation_state=cs, ldgr=dict(source_column=col, rows=rows, lacking=lacking, sample=sample), measured=text)


def ldgr_source_declared_check(aid: str, ls, table, cols, keys=None) -> dict:
    """measure()'s Ldgr.source_presence record for an asset that DECLARES `ldgr_source`: {} for an undeclared asset. `table` is the asset's DECLARED target table
    (None = it has none), `cols` its catalog column names when the table exists in production and its columns are known, else None. `no_classical_claim` reads
    N/A, cause `no-classical-claim`, released only by the declared rule; it is NEVER emitted while the table carries a recognised citation column
    (CITATION_COLUMNS), and an asset WITH a target table whose columns are unknown is NO_DETECTOR (the contradiction cannot be checked). A measured declaration
    names the column that carries the source (L0 CF-08); its type must be text / varchar / text[] / json(b), else NO_DETECTOR with the type named. The read is
    over the WHOLE table (see grade_ldgr_source). A malformed declaration that reaches here reads NO_DETECTOR, never an exception."""
    if not isinstance(ls, dict) or (ls.get("na") is None and ls.get("source_column") is None):
        return {}
    known = isinstance(cols, (list, tuple, set)) and bool(cols)
    try:
        if ls.get("na") is not None:
            if ls["na"] != NO_CLASSICAL_CLAIM:
                raise KeyError("na")
            ev = ls["evidence"]
            cit = [c for c in CITATION_COLUMNS if known and c in cols]
            if cit:
                return {"Ldgr.source_presence": dict(v=NO_DET, declared=True,
                                                     declaration_disagreements=[dict(field="ldgr_source.na", declared=NO_CLASSICAL_CLAIM, measured=f"the table carries citation column(s) {cit}")],
                                                     measured=f"NO_DETECTOR — no_classical_claim is declared but {table} carries citation column(s) "
                                                              f"{', '.join(cit)}; the declaration is contradicted")}
            if table and not known:
                return {"Ldgr.source_presence": dict(v=NO_DET, declared=True,
                                                     measured=f"NO_DETECTOR — no_classical_claim is declared but the columns of {table} are unknown (a view, or the table is absent "
                                                              "from production): the declaration cannot be checked against a citation column, so it is not released")}
            return {"Ldgr.source_presence": dict(_na(f"declared no_classical_claim (reviewed; evidence: {ev}): {ls['why']}", "no-classical-claim"), declared=True)}
        col, cs = ls["source_column"], ls["citation_state"]
        if not (isinstance(col, str) and _D1_SQL_IDENT.fullmatch(col) and cs in CITATION_STATES):
            raise KeyError("source_column / citation_state")
    except (KeyError, TypeError) as exc:
        return {"Ldgr.source_presence": dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the ldgr_source declaration is malformed ({type(exc).__name__}: {exc}); it was not validated")}
    if not table or not known:
        return {"Ldgr.source_presence": dict(v=NO_DET, declared=True, citation_state=cs,
                                             measured="NO_DETECTOR — the declared source column is read on the target table, which does not exist in production "
                                                      "or whose columns are unknown")}
    if col not in cols:
        return {"Ldgr.source_presence": dict(v=FAIL, declared=True, citation_state=cs,
                                             measured=f"the declared source column {col} is not a column of {table}: the declaration names a source the table does not carry")}
    kc = []
    if keys:                                                # the same key choice as Vocab.identity: not the bare surrogate `id` when another key exists
        k0 = keys[0] if len(keys[0]) > 1 or keys[0][0] != "id" else (keys[1] if len(keys) > 1 else keys[0])
        kc = list(k0)
    try:
        typ = ldgr_fetch_column_type(table, col)
        kind = ldgr_column_kind(typ)
        if kind is None:
            return {"Ldgr.source_presence": dict(v=NO_DET, declared=True, citation_state=cs,
                                                 measured=f"NO_DETECTOR — the declared source column {table}.{col} has type {typ or 'unknown'}: only text, varchar, text[] and "
                                                          "json(b) can carry a citation, so presence on it is not a source")}
        return {"Ldgr.source_presence": grade_ldgr_source(ls, ldgr_fetch_source_stats(table, col, kc[:3], kind), table)}
    except Unknown as exc:                                  # R41: this check's failure degrades only this check
        return {"Ldgr.source_presence": dict(v=ERRORED, declared=True, citation_state=cs, measured=f"check errored: {exc}")}


# ─────────────────── N-151 (REGISTRY_REVISION 26): the declared `source` reading of Ldgr.source_presence ───────────────────
# An asset that declares `source` (validated above) gets THIS reading instead of the legacy column-pattern one. K1 / K3 resolve by shape (non-placeholder citation + a locus with a number;
# generator-or-dataset + method + version-or-seed); K2 is a decision-id STRING of the right shape, no register lookup (N-154); LEDGER resolves each carried fact id against chart_facts.fact_id (N.5).
# PASS needs the detector to have measured the claim: a table-level source is PASS only on a table that holds rows; a row-level source only where EVERY row resolves through at least one entry.
# N/A is ONLY `na: no_data` (the asset owns no table: checked) or `na: no_claims` (the asset's own prose_none check passed and no citation / ledger column exists: checked).
LEDGER_TABLE = "chart_facts"
LEDGER_LIKE_TOKENS = ("fact_id", "constituent_fact", "derivation_ledger", "ledger")
_PY_JUNK = "।॥−"


def _py_norm(v: str) -> str:
    """Python mirror of the SQL normalisation `_ldgr_lacking_text` applies: NFKC, invisible/format characters removed, junk (whitespace / punctuation / symbols) stripped at the ends,
    whitespace collapsed, case folded."""
    s = unicodedata.normalize("NFKC", v)
    s = "".join(ch for ch in s if unicodedata.category(ch) not in ("Cf",) and not (unicodedata.category(ch) == "Cc" and not ch.isspace()) and not 0xFE00 <= ord(ch) <= 0xFE0F)

    def junk(ch):
        return ch.isspace() or unicodedata.category(ch)[0] in "PZS" or ch in _PY_JUNK
    i, j = 0, len(s)
    while i < j and junk(s[i]):
        i += 1
    while j > i and junk(s[j - 1]):
        j -= 1
    return re.sub(r"\s+", " ", s[i:j]).casefold()


def ldgr_placeholder_text(v) -> bool:
    """True when `v` states no source: not a string, empty after normalisation, one of LDGR_PLACEHOLDERS (also with the spaces removed), one of the citation placeholders (a bare tradition
    label such as 'classical_tradition'), led by a placeholder prefix ('UNSOURCED - ...'), or all-ASCII with no alphanumeric character. The same predicate the SQL readings apply."""
    if not isinstance(v, str):
        return True
    n = _py_norm(v)
    words = LDGR_PLACEHOLDERS + LDGR_CITATION_PLACEHOLDERS
    if n in words or n.replace(" ", "") in {w.replace(" ", "") for w in words}:
        return True
    if any(re.match(re.escape(p) + r"(?:[^0-9A-Za-z\u0080-\U0010ffff]|$)", n) for p in LDGR_CITATION_PLACEHOLDER_PREFIXES):
        return True
    return not any(ch.isalnum() for ch in n) and all(ord(ch) < 128 for ch in n)


def source_table_problem(src) -> str | None:
    """None when a TABLE-level `source` resolves, else why not: K1 needs a citation and a locus that are no placeholder, the locus carrying a number (chapter / verse / page); K2 needs a
    decision-id string; K3 needs generator-or-dataset, method and version-or-seed, none a placeholder. A placeholder is FAIL, never a source."""
    kind = src.get("kind")
    if kind == "K1":
        if ldgr_placeholder_text(src.get("citation")):
            return f"the K1 citation {src.get('citation')!r} is a placeholder, not a citation"
        loc = src.get("locus")
        if ldgr_placeholder_text(loc) or not re.search(r"[0-9]", loc):
            return f"the K1 locus {loc!r} is a placeholder or names no chapter / verse / page number"
        return None
    if kind == "K2":
        d = src.get("decision_id")
        if ldgr_placeholder_text(d) or _k2_problem(d):
            return f"the K2 decision id {d!r} is a placeholder, not a decision id"
        return None
    if kind == "K3":
        for f in ("generator", "dataset", "method", "version", "seed"):
            if src.get(f) is not None and ldgr_placeholder_text(src[f]):
                return f"the K3 {f} {src[f]!r} is a placeholder"
        vd = src.get("version_digest")
        if vd is not None:
            import hashlib
            try:
                fp = (ROOT / vd["file"]).resolve()
                if ROOT.resolve() not in fp.parents:
                    return f"the K3 version_digest file {vd['file']} is outside the repository"
                have = hashlib.sha256(fp.read_bytes()).hexdigest()
            except OSError:
                return f"the K3 version_digest file {vd['file']} cannot be read in this checkout"
            if have != vd["sha256"]:
                return (f"the K3 version_digest does not match: {vd['file']} hashes to {have[:12]}..., the declaration records {vd['sha256'][:12]}...: the generator changed since it was declared "
                        "(re-read it, then re-record the digest)")
        return None
    return f"kind {kind!r} is not a table-level kind"


def ldgr_undeclared_l0_record(layer, *, declared, measured, table, exists, rows):
    """N-151: the Ldgr.source_presence record of an L0 asset that DECLARES no source (`ldgr_source` / `source`), is not already read by the legacy citation-column reading (`measured`), owns a
    target table that exists in production and HOLDS DATA (rows > 0): FAIL, "no source declared" (absence of K1 / K2 / K3 is FAIL). None for every other case (another layer, a declared source, an
    already-measured legacy reading, no table, an absent table, an empty table: those read as before, NO_DETECTOR / the legacy cell). Pure; measure() and the replay of a saved census read it."""
    if (layer == "L0" and not declared and not measured and table and exists and isinstance(rows, int) and not isinstance(rows, bool) and rows > 0):
        return dict(v=FAIL, measured=f"no source declared: {table} holds {rows} row(s) and the asset declares no K1 citation, K2 ratification or K3 derivation "
                                     "(N-151: every L0 asset that holds data carries one; absence of all three is FAIL)")
    return None


def source_column_kind(type_text):
    """`ldgr_column_kind` plus 'uuid_array' (a uuid[] column: only a LEDGER entry may read it, each id cast to text for its resolution)."""
    if re.sub(r"\(.*?\)", "", str(type_text or "")).strip().lower() == "uuid[]":
        return "uuid_array"
    return ldgr_column_kind(type_text)


def source_fetch_column_types(table: str, cols) -> dict:
    """{column: format_type} for the declared source columns of `table` ('' when absent): ONE read-only catalog SELECT answered as one line of jsonb. Raises Unknown on a failed read."""
    cols = list(dict.fromkeys(cols))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and all(isinstance(c, str) and _D1_SQL_IDENT.fullmatch(c) for c in cols)):
        raise Unknown(f"source_fetch_column_types: malformed identifier(s) {table!r} / {cols!r}")
    lit = ",".join("'" + c + "'" for c in cols)
    blob = scalar("SELECT coalesce(jsonb_object_agg(a.attname, format_type(a.atttypid, a.atttypmod)),'{}'::jsonb)::text FROM pg_attribute a "
                  f"WHERE a.attrelid = to_regclass('\"{table}\"') AND a.attname IN ({lit}) AND a.attnum > 0 AND NOT a.attisdropped")
    try:
        got = json.loads(blob or "{}")
    except json.JSONDecodeError as exc:
        raise Unknown(f"source_fetch_column_types: unparseable read of {table}: {exc}") from exc
    return {c: str(got.get(c) or "") for c in cols}


def _k2_regex(prefixes=None) -> str:
    """The SQL regex of a decision-id string. Default: any letters-then-number shape; with `prefixes` (an entry that mixes K1 and K2) only those prefixes, so a K1 citation is not read as an id.
    The declared-prefix form is matched case-INSENSITIVELY (`~*`) so `n-0` is judged as the id it spells (and refused for its zero number), not re-read as a K1 citation."""
    if prefixes:
        return "^(?:" + "|".join(prefixes) + ")-?[0-9]{1,6}[A-Za-z0-9._-]{0,24}$"
    leap = "(?:[0-9]{2}(?:0[48]|[2468][048]|[13579][26])|(?:0[048]|[2468][048]|[13579][26])00)"      # a leap year: divisible by 4, a century only when divisible by 400
    date = ("(?:[0-9]{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12][0-9]|3[01])|(?:0[469]|11)-(?:0[1-9]|[12][0-9]|30)|02-(?:0[1-9]|1[0-9]|2[0-8]))"
            f"|{leap}-02-29)")      # real calendar dates only, 02-29 in leap years
    long_prefixes = "|".join(_K2_LONG_PREFIXES)
    return (f"^(?:(?!(?:{long_prefixes})(?![A-Za-z]))[A-Za-z][A-Za-z0-9]{{0,5}}-?[0-9]{{1,6}}[A-Za-z0-9._-]{{0,24}}"      # the short shape, except the long-form prefixes (RULING, DVA)
            f"|(?:{long_prefixes})-[0-9]{{1,6}}_{date})$")


_K2_PAD = "[[:space:]\u00a0\u2000-\u200b\u202f\u205f\u3000\ufeff]"


def _k2_trimmed(col: str) -> str:
    """The SQL expression of the column `col` with leading and trailing whitespace removed: ANY whitespace (tab, newline, carriage return) and the no-break and other unicode spaces,
    not only the ASCII space `btrim` strips. A padded real id ('N-150\\t') is still the id; a padded placeholder ('TBD-1\\t') is still the placeholder. Used by both K2 branches."""
    return f"regexp_replace({col}, '^{_K2_PAD}+|{_K2_PAD}+$', '', 'g')"


def _k2_sql_prefix_ok(raw: str) -> str:
    """The prefix half of `_k2_sql_ok`: the alphabetic prefix is no placeholder word. In a mixed K1 / K2 column a value in the GENERAL id shape (letters then a number) whose prefix is a placeholder
    (TBD-1, TODO1) is no source either, even though its prefix is not one of the declared id prefixes (it would otherwise read as a K1 citation text)."""
    words = sorted(set(_S3_PLACEHOLDER_WORDS) | set(_SRC_BARE_PLACEHOLDERS) | {"tbc"})
    lst = ",".join("'" + w.replace("'", "''") + "'" for w in words)
    return f"(lower(substring({raw} from '^[A-Za-z]+')) NOT IN ({lst}))"


def _k2_sql_ok(raw: str) -> str:
    """The SQL mirror of `_k2_problem`'s two refusals beyond the shape regex, for a value that already matches the id shape: the alphabetic prefix is no placeholder word (TBD-1, TODO1, none-1,
    XXX-7, NA-1, null-9, tbc-4), and the number is NON-ZERO (N-0, XXX-000). `raw` is a SQL text expression. ONE list: `_S3_PLACEHOLDER_WORDS` + `_SRC_BARE_PLACEHOLDERS` + 'tbc'."""
    words = sorted(set(_S3_PLACEHOLDER_WORDS) | set(_SRC_BARE_PLACEHOLDERS) | {"tbc"})
    lst = ",".join("'" + w.replace("'", "''") + "'" for w in words)
    return (f"(lower(substring({raw} from '^[A-Za-z]+')) NOT IN ({lst}) "
            f"AND COALESCE(CASE WHEN {raw} ~ '^(?:{'|'.join(_K2_LONG_PREFIXES)})-[0-9]' THEN substring({raw} from '^[A-Za-z]+-([0-9]+)') "
            f"WHEN {raw} ~ '^[A-Za-z][A-Za-z0-9]{{0,5}}-[0-9]' THEN substring({raw} from '^[A-Za-z][A-Za-z0-9]{{0,5}}-([0-9]+)') "
            f"ELSE substring({raw} from '^[A-Za-z]+([0-9]+)') END::numeric, 0) > 0)")


def _ledger_resolves(idexpr: str, resolves_to: str) -> str:
    """The SQL predicate 'the id `idexpr` RESOLVES': to chart_facts.fact_id, or to a bodha_msr_signals.signal_id whose OWN constituent_facts_array is non-empty and resolves, every element, to
    chart_facts.fact_id (the id chains down to L1, N.5). An id that is NULL, absent from the target, or whose chain does not reach L1 does not resolve."""
    if resolves_to == "bodha_msr_signals.signal_id":
        return (f"EXISTS (SELECT 1 FROM bodha_msr_signals ms WHERE ms.signal_id::text = ({idexpr}) AND cardinality(ms.constituent_facts_array) > 0 AND NOT EXISTS "
                f"(SELECT 1 FROM unnest(ms.constituent_facts_array) AS cf(x) WHERE NOT EXISTS (SELECT 1 FROM {LEDGER_TABLE} f WHERE f.fact_id = cf.x)))")
    return f"EXISTS (SELECT 1 FROM {LEDGER_TABLE} f WHERE f.fact_id = ({idexpr}))"


def source_entry_exception(entry: dict):
    """The SQL predicate 'this row is EXCEPTED from the entry by declaration' (`except_when {column, equals}`), or None."""
    ew = entry.get("except_when")
    if not isinstance(ew, dict):
        return None
    return f'COALESCE(("{ew["column"]}")::text = {_sql_lit(ew["equals"])}, false)'


def source_entry_lacking(entry: dict, ktypes: dict):
    """See `_source_entry_lacking_core`; an entry with `except_when` does not lack a source on the rows it excepts (they are counted separately, never judged)."""
    p, why = _source_entry_lacking_core(entry, ktypes)
    exc = source_entry_exception(entry)
    if p is None or exc is None:
        return p, why
    return f"(NOT {exc} AND {p})", None


def _source_entry_lacking_core(entry: dict, ktypes: dict):
    """(SQL predicate, problem) for ONE row-level entry: the predicate is true on a row this entry does NOT source. `ktypes` is {column: ldgr_column_kind or None}. A column of a type that
    cannot carry the entry's kind returns (None, why): the cell then reads NO_DETECTOR with the type named, never a PASS."""
    kinds = entry["kinds"]
    if kinds == ["K3"]:
        parts = {}
        for f in ("generator_column", "dataset_column", "method_column", "version_column", "seed_column"):
            c = entry.get(f)
            if c is None:
                continue
            if ktypes.get(c) in (None, "uuid_array"):
                return None, f"{c} is not a text, text[] or json column"
            parts[f] = _ldgr_lacking(c, ktypes[c])
        who = parts.get("generator_column") or parts["dataset_column"]
        ver = " AND ".join(parts[f] for f in ("version_column", "seed_column") if f in parts)
        return f"({who} OR {parts['method_column']} OR ({ver}))", None
    c, kd = entry["column"], ktypes.get(entry["column"])
    if kinds == ["LEDGER"]:
        rt = entry.get("resolves_to") or SOURCE_RESOLVES_TO[0]
        idkey = "fact_id" if rt.endswith(".fact_id") else "signal_id"
        path = entry.get("path")
        if path is not None:
            if kd != "json":
                return None, f"{c} is not a json(b) column (a path reads inside one)"
            jp = path if path.endswith("[*]") else path + "[*]"      # lax mode: [*] on a scalar is that scalar, on an array its elements
            elem = f"CASE jsonb_typeof(pe.x) WHEN 'string' THEN pe.x #>> '{{}}' WHEN 'object' THEN pe.x->>'{idkey}' END"
            return (f'("{c}" IS NULL OR NOT EXISTS (SELECT 1 FROM jsonb_path_query("{c}"::jsonb, \'{jp}\') AS pe(x)) OR EXISTS (SELECT 1 FROM jsonb_path_query("{c}"::jsonb, \'{jp}\') AS pe(x) '
                    f"WHERE NOT {_ledger_resolves(elem, rt)}))"), None
        if kd in ("array", "uuid_array"):
            return (f'("{c}" IS NULL OR cardinality("{c}") = 0 OR EXISTS (SELECT 1 FROM unnest("{c}") AS u(x) WHERE NOT {_ledger_resolves("u.x::text", rt)}))'), None
        if kd == "json":
            elem = f"CASE jsonb_typeof(je.x) WHEN 'string' THEN je.x #>> '{{}}' WHEN 'object' THEN je.x->>'{idkey}' END"
            return (f'("{c}" IS NULL OR jsonb_typeof("{c}"::jsonb) <> \'array\' OR jsonb_array_length("{c}"::jsonb) = 0 OR EXISTS (SELECT 1 FROM jsonb_array_elements("{c}"::jsonb) AS je(x) '
                    f"WHERE NOT {_ledger_resolves(elem, rt)}))"), None
        return None, f"{c} is not a text[] or json(b) column of ids"
    if kd == "uuid_array":
        return None, f"{c} is a uuid[] column: only a LEDGER entry (ids resolved against their target) may read it"
    if "K2" in kinds:
        if kd != "text":
            return None, f"{c} is not a text column (a decision id is a string)"
        raw = _k2_trimmed(f'"{c}"')
        if kinds == ["K2"]:
            return f"(\"{c}\" IS NULL OR NOT ({raw} ~ '{_k2_regex()}' AND {_k2_sql_ok(raw)}))", None
        # mixed K1 / K2: a value in the id shape is judged AS AN ID (a placeholder prefix or a zero number is no source, never re-read as a citation); any other value is a K1 citation
        return (f"(\"{c}\" IS NULL OR NOT (CASE WHEN {raw} ~* '{_k2_regex(entry.get('id_prefixes') or SOURCE_DEFAULT_ID_PREFIXES)}' THEN {_k2_sql_ok(raw)} "
                f"ELSE (NOT {_ldgr_lacking(c, 'text')} AND NOT ({raw} ~ '{_k2_regex()}' AND NOT {_k2_sql_prefix_ok(raw)})) END))"), None
    if kd is None:
        return None, f"{c} is not a text, text[] or json column"
    sp = entry.get("split_citation")
    if sp is not None:
        if kd != "text":
            return None, f"{c} is not a text column (a split citation is a string)"
        return f"(CASE WHEN {_split_selected(entry)} THEN NOT {_split_ok(c)} ELSE {_ldgr_lacking(c, kd)} END)", None
    return _ldgr_lacking(c, kd), None


def _split_shape_sql() -> str:
    """The shape regex as a SQL expression that carries no quote or backslash (hex-decoded UTF-8): the second lock before any pattern text reaches SQL."""
    return "convert_from(decode('" + SPLIT_SHAPE_RE.encode("utf-8").hex() + "', 'hex'), 'UTF8')"


def _split_applies(sc: dict) -> str:
    parts = []
    for cond in sc["applies_to"]:
        col = '"' + cond["column"] + '"'
        if "equals" in cond:
            parts.append(f"COALESCE({col}::text = {_sql_lit(cond['equals'])}, false)")
        elif "in" in cond:
            parts.append(f"COALESCE({col}::text = ANY(ARRAY[" + ",".join(_sql_lit(v) for v in cond["in"]) + "]::text[]), false)")
        else:
            parts.append(f"({col} IS NOT NULL)")
    return "(" + " AND ".join(parts) + ")"


def _split_selected(entry: dict) -> str:
    """The SQL predicate 'this row is judged under the declared split_citation': the declared rows AND a citation of exactly the split shape."""
    c = '"' + entry["column"] + '"'
    return f"({_split_applies(entry['split_citation'])} AND {c} ~ {_split_shape_sql()})"


def _split_ok(col: str) -> str:
    """The SQL predicate 'the K1 part of a split-shaped citation holds' (Python mirror: `split_citation_k1_problem`): the vedha text and the locus words hold an alphanumeric and are no placeholder,
    the excerpt holds an alphanumeric and has at most SPLIT_MAX_EXCERPT_WORDS words (split on ANY blank: ASCII, NBSP, unicode spaces), and the machine locus (text_id:PGnnn:Cn) RESOLVES to a
    chunk of classical_text_chunks (chunk_id <text_id>_pg<4 digits>_c<2 digits>). Only evaluated on rows the shape already matched."""
    c = '"' + col + '"'
    m = lambda i: f"(regexp_match({c}, {_split_shape_sql()}))[{i}]"       # noqa: E731
    ws = "E'" + "".join(("\\u%04x" % ord(ch)) for ch in SPLIT_WS) + "'"
    blank = f"'[[:space:]{chr(92)}u00a0{chr(92)}u2000-{chr(92)}u200b{chr(92)}u202f{chr(92)}u205f{chr(92)}u3000{chr(92)}ufeff]+'"
    ex = f"btrim({m(6)}, {ws})"
    return (f"(btrim({m(1)}, {ws}) ~ '[[:alnum:]]' AND NOT {_ldgr_lacking_text(m(2), True)} AND {ex} ~ '[[:alnum:]]' "
            f"AND array_length(regexp_split_to_array({ex}, {blank}), 1) <= {SPLIT_MAX_EXCERPT_WORDS} "
            f"AND EXISTS (SELECT 1 FROM classical_text_chunks ch WHERE ch.chunk_id = {m(3)} || '_pg' || lpad({m(4)}, 4, '0') || '_c' || lpad({m(5)}, 2, '0')))")


def split_citation_k1_problem(text, chunk_ids=()):
    """The pure Python mirror of the SQL judgement (`_split_selected` shape + `_split_ok`), used by the differential test: None when `text` is a split citation whose K1 part holds, else why
    not. `chunk_ids` is the set of classical_text_chunks.chunk_id values that exist. Never reads a database."""
    m = re.match(SPLIT_SHAPE_RE, text or "")
    if not m:
        return "not of the exact split shape"
    vedha, words, tid, page, chunk, excerpt = m.groups()
    blank = re.compile("[" + re.escape(SPLIT_WS) + r"\s]+")
    if not re.search(r"[^\W_]", vedha.strip(SPLIT_WS), re.U):
        return "the vedha partner text is blank"
    if _ldgr_placeholder_text_py(words):
        return "the locus words are a placeholder"
    ex = excerpt.strip(SPLIT_WS)
    if not re.search(r"[^\W_]", ex, re.U):
        return "the excerpt is blank"
    if len(blank.split(ex)) > SPLIT_MAX_EXCERPT_WORDS:
        return f"the excerpt is longer than {SPLIT_MAX_EXCERPT_WORDS} words"
    if f"{tid}_pg{int(page):04d}_c{int(chunk):02d}" not in set(chunk_ids):
        return "the machine locus does not resolve to a corpus chunk"
    return None


def _ldgr_placeholder_text_py(x: str) -> bool:
    """A minimal Python reading of the Ldgr placeholder test for the locus words (empty, no alphanumeric, or one of LDGR_PLACEHOLDERS / LDGR_CITATION_PLACEHOLDERS after case-fold and whitespace collapse)."""
    n = " ".join(unicodedata.normalize("NFKC", x or "").casefold().split()).strip(" .,;:-_/\\")
    return (not re.search(r"[^\W_]", n, re.U)) or n in LDGR_PLACEHOLDERS or n in LDGR_CITATION_PLACEHOLDERS


def source_fetch_stats(table: str, pred: str, keycols=(), exc=None, split=None) -> dict:
    """{rows, lacking, sample}: the table's rows, the rows `pred` (a predicate built by `source_entry_lacking`, never user text) marks as sourced by NO entry, and up to 5 identities (the key
    columns, total ORDER BY) of them: ONE read-only SELECT over the WHOLE table, answered as one line of jsonb. Raises Unknown on a failed read."""
    keys = list(dict.fromkeys(keycols or ()))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and all(isinstance(k, str) and _D1_SQL_IDENT.fullmatch(k) for k in keys)):
        raise Unknown(f"source_fetch_stats: malformed identifier(s) {table!r} / {keys!r}")
    q = ",".join('"' + k + '"' for k in keys)
    sample = ("'[]'::jsonb" if not keys else
              f"(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT {q} FROM \"{table}\" WHERE {_sw(table, pred)} ORDER BY {q} LIMIT 5) s)")
    exc_sql = f",'excepted',count(*) FILTER (WHERE {exc})" if exc else ""
    exc_sql += (f",'split',count(*) FILTER (WHERE {split[0]}),'split_ok',count(*) FILTER (WHERE {split[1]})" if split else "")
    blob = scalar(f"SELECT jsonb_build_object('rows',count(*),'lacking',count(*) FILTER (WHERE {pred}),'sample',{sample}{exc_sql})::text FROM \"{table}\"{_where_scope(table)}")
    try:
        got = json.loads(blob or "{}")
    except json.JSONDecodeError as err:
        raise Unknown(f"source_fetch_stats: unparseable read of {table}: {err}") from err
    if not (isinstance(got, dict) and isinstance(got.get("rows"), int) and isinstance(got.get("lacking"), int)):
        raise Unknown(f"source_fetch_stats: malformed answer for {table}")
    return got


# ───────────── the cheap EXISTENCE read of a declared row-level source (interim census, 2026-10-06) ─────────────
# The exact read above (`source_fetch_stats`) counts every row and re-scans the table for a sample: five checks (bg_muhurta_lattice, ga_dashas, ga_sensitive_degree, bo_anveshana, bo_pratijna) were
# cancelled by the census role's statement timeout and read ERRORED. For a table that is large (the catalog estimate reaches LDGR_CHEAP_MIN_ROWS), or whose exact read timed out, the verdict is
# read by EXISTENCE instead: does any row lack a source (EXISTS ... LIMIT 1: it stops at the first violating row), does any row name one (EXISTS ... LIMIT 1), up to LDGR_SAMPLE_LIMIT
# offending identities (LIMIT, no ORDER BY: an ORDER BY would force the full scan this read exists to avoid). The verdict is EXACT: PASS only when no violating row exists (the one read
# that must visit every row: a PASS cannot be proven by fewer), FAIL when no row names a source, PARTIAL when both exist. What it does NOT produce is a total: the text says "at least 1",
# never an invented count. If even this read times out the cell reads NO_DETECTOR with that cause (never ERRORED, never PASS).
LDGR_CHEAP_MIN_ROWS = 250_000      # catalog estimate (pg_class.reltuples) at or above which the existence read is used straight away; below it the exact read runs first
LDGR_SAMPLE_LIMIT = 3              # offending identities named by the existence read


def _is_statement_timeout(exc) -> bool:
    """True for the server's `canceling statement due to statement timeout` (it arrives as an Unknown carrying psql's first stderr line) and for the client-side CheckTimeout."""
    return isinstance(exc, CheckTimeout) or "statement timeout" in str(exc)


def source_estimate_rows(table: str):
    """The catalog's row estimate for `table` (pg_class.reltuples: ONE catalog lookup, never a scan of the table), or None when it is unknown (never analysed: -1; absent; the read failed)."""
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table)):
        return None
    try:
        out = scalar(f"SELECT coalesce((SELECT c.reltuples::bigint FROM pg_class c WHERE c.oid = to_regclass('\"{table}\"')), -1)")
        n = int(str(out).strip())
    except (Unknown, TypeError, ValueError):
        return None
    return n if n >= 0 else None


def source_presence_sql(table: str, pred: str, keycols=(), exc=None) -> str:
    """The ONE existence statement (pure): any row, any judged row, any excepted row, up to LDGR_SAMPLE_LIMIT rows that lack a source, and whether any judged row names one. Every sub-select is an
    EXISTS ... LIMIT 1 or a LIMIT: there is no count(*) and no ORDER BY over `table`. `pred` is a predicate built by `source_entry_lacking` (never user text); identifiers are matched before this runs."""
    keys = list(dict.fromkeys(keycols or ()))
    q = ",".join('"' + k + '"' for k in keys)
    t = f'"{table}"'
    lack_sample = (f"(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT {q} FROM {t} WHERE {_sw(table, pred)} LIMIT {LDGR_SAMPLE_LIMIT}) s)" if keys else
                   f"(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT true AS lacking FROM {t} WHERE {_sw(table, pred)} LIMIT {LDGR_SAMPLE_LIMIT}) s)")
    judged = f"EXISTS (SELECT 1 FROM {t} WHERE {_sw(table, 'NOT ' + exc)} LIMIT 1)" if exc else f"EXISTS (SELECT 1 FROM {t}{_where_scope(table)} LIMIT 1)"
    sourced = f"EXISTS (SELECT 1 FROM {t} WHERE {_sw(table, ('NOT ' + exc + ' AND ' if exc else '') + '(' + pred + ') IS NOT TRUE')} LIMIT 1)"
    excepted = f",'excepted',EXISTS (SELECT 1 FROM {t} WHERE {_sw(table, exc)} LIMIT 1)" if exc else ""
    return (f"SELECT jsonb_build_object('any_row',EXISTS (SELECT 1 FROM {t}{_where_scope(table)} LIMIT 1),'judged',{judged},'lacking',{lack_sample},'sourced',{sourced}{excepted},"
            f"'has_keys',{'true' if keys else 'false'})::text")


def source_fetch_presence(table: str, pred: str, keycols=(), exc=None) -> dict:
    """{any_row, judged, lacking_at_least, sample, sourced, excepted?}: the existence read of `source_presence_sql`, answered as one line of jsonb. Raises Unknown on a failed (or timed-out) read."""
    keys = list(dict.fromkeys(keycols or ()))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and all(isinstance(k, str) and _D1_SQL_IDENT.fullmatch(k) for k in keys)):
        raise Unknown(f"source_fetch_presence: malformed identifier(s) {table!r} / {keys!r}")
    blob = scalar(source_presence_sql(table, pred, keys, exc))
    try:
        got = json.loads(blob or "{}")
    except json.JSONDecodeError as err:
        raise Unknown(f"source_fetch_presence: unparseable read of {table}: {err}") from err
    if not (isinstance(got, dict) and all(isinstance(got.get(k), bool) for k in ("any_row", "judged", "sourced")) and isinstance(got.get("lacking"), list)):
        raise Unknown(f"source_fetch_presence: malformed answer for {table}")
    lack = got["lacking"]
    out = dict(any_row=got["any_row"], judged=got["judged"], sourced=got["sourced"], lacking_at_least=1 if lack else 0, sample=lack if got.get("has_keys") else [], exact=False)
    if exc:
        if not isinstance(got.get("excepted"), bool):
            raise Unknown(f"source_fetch_presence: malformed answer for {table}")
        out["excepted"] = got["excepted"]
    return out


def source_read_stats(table: str, pred: str, keycols=(), exc=None, split=None) -> dict:
    """The stats `source_declared_check` grades: the EXACT read (`source_fetch_stats`: totals, the first 5 offenders) while the table is small, the EXISTENCE read (`source_fetch_presence`,
    `exact` False) when the catalog estimate reaches LDGR_CHEAP_MIN_ROWS or the exact read was cancelled by a statement timeout. Any other failure of the exact read propagates (ERRORED, as before)."""
    if split is not None:        # a declared split_citation exception is judged ONLY by the exact read (the existence read does not apply it): never route around it; a statement timeout propagates and reads NO_DETECTOR
        return source_fetch_stats(table, pred, keycols, exc=exc, split=split)
    est = source_estimate_rows(table)
    if est is not None and est >= LDGR_CHEAP_MIN_ROWS:
        return dict(source_fetch_presence(table, pred, keycols, exc), why_cheap=f"the catalog estimates {est} rows (>= {LDGR_CHEAP_MIN_ROWS})")
    try:
        return source_fetch_stats(table, pred, keycols, exc=exc)
    except Unknown as err:
        if not _is_statement_timeout(err):
            raise
    return dict(source_fetch_presence(table, pred, keycols, exc), why_cheap="the exact row count exceeded the statement timeout")


def grade_ldgr_source_presence(ls: dict, pr: dict, table: str) -> dict:
    """The declared Ldgr.source_presence reading from the EXISTENCE read (pure; the twin of `grade_ldgr_source`, same verdict rule, same citation_state cap): PASS = no judged row lacks a source,
    FAIL = a row lacks one and none names one, PARTIAL = both exist, NO_DETECTOR = no judged row (vacuous). Counts are never stated as totals: 'at least 1' is all this read knows."""
    col, cs = ls["source_column"], ls["citation_state"]
    if not pr["any_row"] or not pr["judged"]:
        return dict(v=NO_DET, declared=True, citation_state=cs, measured=f"NO_DETECTOR — {table} has no judged rows: {col} names a source on 0 rows (vacuous)")
    lack, sample = pr["lacking_at_least"] > 0, pr.get("sample") or []
    v = PASS if not lack else (PARTIAL if pr["sourced"] else FAIL)
    shown = ("; rows lacking one (first up to " + str(LDGR_SAMPLE_LIMIT) + " found, unordered): " + json.dumps(sample, sort_keys=True, default=str)) if lack and sample else ("; row identity unavailable (no declared key)" if lack else "")
    what = ("no row lacks one" if not lack else "at least 1 row lacks one and at least 1 row names one" if pr["sourced"] else "at least 1 row lacks one and no row names one")
    text = (f"declared source column {col} names a source: {what} (existence read of {table}: rows were not counted, so no total is stated; NULL, blank, punctuation-only, 'not traced'-style "
            f"placeholders, a bare tradition label such as 'classical_tradition' and an 'UNSOURCED ...' disclosure do not count); citation_state {cs}{shown}")
    ev = dict(source_column=col, rows=None, lacking=None, lacking_at_least=1 if lack else 0, sample=sample, exact=False)
    if v in (PASS, PARTIAL) and cs in CITATION_CAPPED_STATES:
        return dict(v=NO_DET, declared=True, citation_state=cs, ldgr=ev, measured=f"NO_DETECTOR — the column is populated: {text}, but the declared citation_state is {cs!r}: a source that is {cs} is never a PASS")
    return dict(v=v, declared=True, citation_state=cs, ldgr=ev, measured=text)


def _source_existence_record(stats: dict, blk: dict, kinds, cs: str, table: str) -> dict:
    """source_declared_check's record for the existence read: same verdict rule as the exact read, the source block carries `rows` None (not counted), `lacking_at_least`, the bounded sample."""
    pr = dict(stats, any_row=stats["any_row"], judged=stats["judged"])
    blk = dict(blk, read="existence", why_cheap=stats.get("why_cheap"))
    if stats.get("excepted"):
        blk["excepted_at_least"] = 1
    if stats["any_row"] and not stats["judged"]:
        return dict(v=NO_DET, declared=True, citation_state=cs, source=dict(blk, rows=None),
                    measured=f"NO_DETECTOR — every row of {table} is excepted by declaration (except_when): no row was judged")
    rec = grade_ldgr_source_presence(dict(source_column=", ".join(blk["columns"]), citation_state=cs), pr, table)
    rec["source"] = dict(blk, rows=None, lacking=None, lacking_at_least=pr["lacking_at_least"], exact=False)
    rec["measured"] = f"row-level {'/'.join(kinds)} source ({stats.get('why_cheap')}): " + rec["measured"]
    if stats.get("excepted"):
        rec["measured"] += "; at least 1 row excepted by declaration (except_when) is not judged"
    return rec


def _source_cols(src) -> list:
    out = []
    for e in src.get("columns") or []:
        out += [e[f] for f in ("column", "generator_column", "dataset_column", "method_column", "version_column", "seed_column") if e.get(f)]
    return out


# ───────────── N-177: the UNSOURCED_DECLARED residual of a declared row-level source ─────────────
# The asset DECLARES `residual: UNSOURCED_DECLARED` (on citation_state `unsourced`, one K1 source column, optionally the `untraced_marker` phrase its rows use to say they are not traced to a source). The detector
# CHECKS it, read-only and bounded (ONE existence statement: first judged rows, up to LDGR_SAMPLE_LIMIT rows that CARRY a source): every judged row (a row the entry's `except_when` does not except) must either
# lack a source by the shared Ldgr predicate (NULL, blank, a placeholder, 'UNSOURCED ...') or contain the declared marker phrase (the row itself says it is not traced). One judged row that does neither names
# a source: the label is NOT earned, the declaration is contradicted, and the cell reads as measured (the capped NO_DETECTOR the citation_state `unsourced` always gave, with the disagreement named). No judged
# row at all is vacuous: NO_DETECTOR. A scan the statement timeout cancels is NO_DETECTOR with the cause, never ERRORED, never the label.
def unsourced_declared_sql(table: str, lack_pred: str, col: str, marker, keycols=(), exc=None) -> str:
    """The ONE existence statement of the residual check (pure): whether any judged row exists, up to LDGR_SAMPLE_LIMIT judged rows that carry a traceable source (neither lacking one nor carrying the marker),
    and, as information, whether any judged row lacks a source / carries the marker. Every sub-select is EXISTS ... LIMIT 1 or a LIMIT: no count(*), no ORDER BY over `table`."""
    keys = list(dict.fromkeys(keycols or ()))
    t, q = f'"{table}"', ",".join('"' + k + '"' for k in keys)
    judged = f"NOT {exc} AND " if exc else ""
    mk = f"(position(lower({_sql_lit(marker)}) in lower(\"{col}\"::text)) > 0)" if marker else "false"
    untraced = f"(({lack_pred}) OR {mk})"
    sel = q if keys else "true AS carries"
    return (f"SELECT jsonb_build_object('judged', EXISTS (SELECT 1 FROM {t}{(' WHERE ' + _sw(table, 'NOT ' + exc)) if exc else _where_scope(table)} LIMIT 1), "
            f"'carrying', (SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT {sel} FROM {t} WHERE {_sw(table, f'{judged}{untraced} IS NOT TRUE')} LIMIT {LDGR_SAMPLE_LIMIT}) s), "
            f"'lacking', EXISTS (SELECT 1 FROM {t} WHERE {_sw(table, f'{judged}({lack_pred}) IS TRUE')} LIMIT 1), "
            f"'marked', EXISTS (SELECT 1 FROM {t} WHERE {_sw(table, f'{judged}{mk} AND ({lack_pred}) IS NOT TRUE')} LIMIT 1), "
            f"'has_keys', {'true' if keys else 'false'})::text")


def unsourced_declared_fetch(table: str, lack_pred: str, col: str, marker, keycols=(), exc=None) -> dict:
    """{judged, carrying (the sample), lacking, marked, has_keys}: the answer of `unsourced_declared_sql`. Raises Unknown on a failed (or timed-out) read."""
    keys = list(dict.fromkeys(keycols or ()))
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table) and isinstance(col, str) and _D1_SQL_IDENT.fullmatch(col) and all(isinstance(k, str) and _D1_SQL_IDENT.fullmatch(k) for k in keys)):
        raise Unknown(f"unsourced_declared_fetch: malformed identifier(s) {table!r} / {col!r} / {keys!r}")
    blob = scalar(unsourced_declared_sql(table, lack_pred, col, marker, keys, exc))
    try:
        got = json.loads(blob or "{}")
    except json.JSONDecodeError as err:
        raise Unknown(f"unsourced_declared_fetch: unparseable read of {table}: {err}") from err
    if not (isinstance(got, dict) and all(isinstance(got.get(k), bool) for k in ("judged", "lacking", "marked", "has_keys")) and isinstance(got.get("carrying"), list)):
        raise Unknown(f"unsourced_declared_fetch: malformed answer for {table}")
    return got


def grade_unsourced_declared(src: dict, rd: dict, table: str, blk: dict) -> dict | None:
    """The residual record from the existence read (pure): N/A (cause unsourced-declared, the CHECKED block) when a judged row exists and NONE carries a traceable source; NO_DETECTOR when no row was judged;
    None when a row carries a source (the label is not earned: the caller reads the asset as measured and names the contradiction). The block `unsourced_declared` is what the rollup requires."""
    col = src["columns"][0]["column"]
    marker = src.get("untraced_marker")
    if not rd["judged"]:
        return dict(v=NO_DET, declared=True, citation_state="unsourced", source=dict(blk, read="existence"),
                    measured=f"NO_DETECTOR — the declared residual {UNSOURCED_DECLARED} has no judged row to check: {table} holds no row (or every row is excepted by declaration): vacuous, not a residual")
    if rd["carrying"]:
        return None
    how = ("every judged row lacks a source in " + col if not rd["marked"] else
           f"every judged row either lacks a source in {col} or states it is not traced (contains {marker!r})" if rd["lacking"] else f"every judged row states in {col} that it is not traced (contains {marker!r})")
    block = dict(checked=True, verified=True, residual=UNSOURCED_DECLARED, source_column=col, untraced_marker=marker, read="existence (first rows that carry a source, bounded, no counting)",
                 judged_rows_exist=True, carrying_a_source=False, some_lacking=rd["lacking"], some_marked=rd["marked"], citation_state="unsourced")
    return dict(_na(f"declared residual {UNSOURCED_DECLARED} (reviewed; evidence: {src['evidence']}): {src['why']}; CHECKED on the live table {table}: {how}; no judged row carries a traceable source "
                    "(existence read: rows were not counted). Never a PASS: a source that is unsourced is a known limitation printed on the certified list", "unsourced-declared"),
                declared=True, citation_state="unsourced", source=dict(blk, read="existence"), unsourced_declared=block)


def _residual_contradiction(rec: dict, rd) -> dict:
    """The record of an asset whose declared residual the rows contradict: the ordinary reading (the capped citation_state `unsourced` never reads PASS), annotated with the disagreement and the rows that
    carry a source. Unchanged when no residual was declared (`rd` None)."""
    if rd is None:
        return rec
    sample = rd.get("carrying") if rd.get("has_keys") else []
    dis = dict(field="source.residual", declared=UNSOURCED_DECLARED,
               measured=f"at least 1 judged row carries a traceable source in the declared column (neither lacking one nor stating it is not traced){'; first found: ' + json.dumps(sample, sort_keys=True, default=str) if sample else ''}")
    return dict(rec, declaration_disagreements=[dis], measured=f"the declared residual {UNSOURCED_DECLARED} is CONTRADICTED by the rows ({dis['measured']}); read as measured: {rec['measured']}")


def unsourced_declared_na_problem(crit: str, meas) -> str | None:
    """None unless an Ldgr.source_presence N/A of cause unsourced-declared is NOT backed by its CHECKED `unsourced_declared` block (N-177): checked and verified true, the residual in the closed list, a judged
    row seen, no row carrying a source, citation_state 'unsourced'. A record without it (a hand-built census, a declaration alone) is not a release. Pure; read by `_check_contribution` and `_na_released`."""
    if crit != "Ldgr.source_presence" or not isinstance(meas, dict) or meas.get("v") != NA or meas.get("cause") != LDGR_RESIDUAL_CAUSE[UNSOURCED_DECLARED]:
        return None
    b = meas.get("unsourced_declared")
    if not (isinstance(b, dict) and b.get("checked") is True and b.get("verified") is True and b.get("residual") in LDGR_RESIDUALS and b.get("judged_rows_exist") is True
            and b.get("carrying_a_source") is False and b.get("citation_state") == "unsourced" and meas.get("citation_state") == "unsourced"):
        return ("Ldgr.source_presence N/A (unsourced-declared) is the closed-list residual UNSOURCED_DECLARED (N-177): it rests on a CHECKED declaration (the rows were read and none carries a traceable source); "
                "this record does not carry that verified block, so it is not a release")
    return None


def source_declared_check(aid: str, src, table, cols, *, rows=None, owned=(), keys=None, prose_record=None, asset_kind=None, owned_columns=None) -> dict:
    """measure()'s Ldgr.source_presence record for an asset that DECLARES `source` (N-151): {} for an undeclared asset. `table` is the asset's DECLARED target table (None = it has none),
    `cols` its catalog columns when the table exists in production and its columns are known, else None; `rows` the table's row count (the depth census; None = not read); `owned` the owned
    tables that exist in production (the target and every count_sql table); `prose_record` the asset's own Narr.agree record (the prose_none check that `no_claims` rests on).
    na `no_data` reads N/A (cause `no-data`) ONLY when the asset owns no existing table; an owned table that exists contradicts it (FAIL). na `no_claims` reads N/A (cause `no-claims`) ONLY
    when the asset's own prose_none check read N/A and the table carries no citation or ledger column; an open text column or such a column contradicts it (FAIL).
    A table-level source: FAIL on a placeholder, NO_DETECTOR where the table is absent / empty / unread, PASS when it resolves on a table that holds rows. A row-level source: every row
    must resolve through at least one entry (PASS), none (FAIL), some (PARTIAL); citation_state caps as for the legacy reading. A malformed declaration reads NO_DETECTOR, never an exception."""
    if not isinstance(src, dict) or (src.get("na") is None and src.get("level") is None):
        return {}
    out = "Ldgr.source_presence"
    bad = source_declaration_problem(src, None, aid)
    if bad:
        return {out: dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the source declaration is malformed ({bad}); it was not validated")}
    known = isinstance(cols, (list, tuple, set)) and bool(cols)
    na = src.get("na")
    if na == "no_data":
        if owned:
            return {out: dict(v=FAIL, declared=True, declaration_disagreements=[dict(field="source.na", declared="no_data", measured=f"the asset owns existing table(s) {sorted(owned)}")],
                              measured=f"declared no_data but the asset owns existing table(s) {', '.join(sorted(owned))}: N/A is only for an asset that holds no data")}
        if table:
            return {out: dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — no_data is declared but the target table {table} is not in production: its absence is not shown to be 'holds no data'")}
        return {out: dict(_na(f"declared no_data (reviewed; evidence: {src['evidence']}): {src['why']}; the asset has no target table and owns no existing table", "no-data"), declared=True)}
    if na == "not_built":
        # the asset is registered but not built (an EXISTING EMPTY table with no writer, or no table in production): there is no data to source, and that is a FAIL, never an N/A
        if known and isinstance(rows, int) and not isinstance(rows, bool) and rows > 0:
            return {out: dict(v=FAIL, declared=True, declaration_disagreements=[dict(field="source.na", declared="not_built", measured=f"{table} holds {rows} row(s)")],
                              measured=f"declared not_built but {table} holds {rows} row(s): the asset is built, so declare its K1 / K2 / K3 / LEDGER source")}
        what = (f"{table} exists and holds no rows" if known and rows == 0 else f"{table} is not in production" if table else "the asset has no target table")
        return {out: dict(v=FAIL, declared=True, source=dict(level="not_built"),
                          measured=f"not built: {what} (declared not_built; evidence: {src['evidence']}): {src['why']}; there is no data to carry a source, which is a failure of the build, not an N/A")}
    if na == "no_claims":
        if not table or not known:
            return {out: dict(v=NO_DET, declared=True, measured="NO_DETECTOR — no_claims is declared but the target table is absent or its columns are unknown: it cannot be checked")}
        pn = (prose_record or {}).get("prose_none") if isinstance(prose_record, dict) else None
        # EVERY owned / produced table is read, not only the target: prose_none covers all of them (the target's columns are always among them)
        per_table = {table: list(cols)}
        for t, tc_ in (owned_columns or {}).items():
            if isinstance(tc_, (list, tuple, set)) and tc_:
                per_table.setdefault(t, list(tc_))
        unread_t = sorted(t for t in ((pn or {}).get("tables") or []) if t not in per_table)
        if unread_t:
            return {out: dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — no_claims is declared but the columns of produced table(s) {unread_t} were not read: a citation or ledger column there cannot be ruled out")}
        hits = {t: [c for c in tcols if c in CITATION_COLUMNS or any(tok in c.casefold() for tok in LEDGER_LIKE_TOKENS)] for t, tcols in sorted(per_table.items())}
        hits = {t: v for t, v in hits.items() if v}
        if hits:
            desc = "; ".join(f"{t}: {', '.join(v)}" for t, v in hits.items())
            return {out: dict(v=FAIL, declared=True, declaration_disagreements=[dict(field="source.na", declared="no_claims", measured=f"an owned table carries citation / ledger column(s): {desc}")],
                              measured=f"declared no_claims but an owned table carries citation / ledger column(s) ({desc}): the declaration is contradicted")}
        if isinstance(pn, dict) and pn.get("checked") is True and prose_record.get("v") == NA:
            return {out: dict(_na(f"declared no_claims (reviewed; evidence: {src['evidence']}): {src['why']}; checked: the table carries no citation or ledger column and the declared-none prose check "
                                  "(no open text column) passed", "no-claims"), declared=True)}
        if isinstance(pn, dict) and prose_record.get("v") == FAIL:
            return {out: dict(v=FAIL, declared=True, declaration_disagreements=[dict(field="source.na", declared="no_claims", measured="the declared-none prose check found an open text column")],
                              measured="declared no_claims but the asset's prose_none check found an open text column: the asset states text the declaration does not account for")}
        return {out: dict(v=NO_DET, declared=True, measured="NO_DETECTOR — no_claims rests on the asset's own checked declared-none prose form (prose_none, N-150 R1), which did not read N/A")}
    # a measured source
    level, cs = src["level"], src.get("citation_state")
    if level == "table":
        kind = src["kind"]
        cs = cs or "sourced"
        blk = dict(level="table", kind=kind)
        if not table or not known:
            return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=blk, measured="NO_DETECTOR — the declared table-level source is for the target table, which is not in production or whose columns are unknown")}
        bad = source_table_problem(src)
        if bad:
            return {out: dict(v=FAIL, declared=True, citation_state=cs, source=dict(blk, resolved=False), measured=f"the declared {kind} source does not resolve: {bad}")}
        if not (isinstance(rows, int) and not isinstance(rows, bool) and rows > 0):
            return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=dict(blk, resolved=True),
                              measured=f"NO_DETECTOR — the declared {kind} source resolves but {table} has no rows (or its row count was not read): a source for no data is vacuous")}
        text = f"table-level {kind} source resolves (one declared source for all {rows} rows of {table}); citation_state {cs}"
        if cs in CITATION_CAPPED_STATES:
            return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=dict(blk, resolved=True), measured=f"NO_DETECTOR — {text}, but a source that is {cs} is never a PASS")}
        return {out: dict(v=PASS, declared=True, citation_state=cs, source=dict(blk, resolved=True, rows=rows), measured=text)}
    # row level
    kinds = sorted({k for e in src["columns"] for k in e["kinds"]})
    cs = cs or "sourced"
    blk = dict(level="row", kinds=kinds, columns=_source_cols(src))
    if not table or not known:
        return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=blk, measured="NO_DETECTOR — the declared row-level source is read on the target table, which is not in production or whose columns are unknown")}
    exc_cols = [e["except_when"]["column"] for e in src["columns"] if isinstance(e.get("except_when"), dict)]
    exc_cols += [cnd["column"] for e in src["columns"] if isinstance(e.get("split_citation"), dict) for cnd in e["split_citation"]["applies_to"]]
    absent = [c for c in _source_cols(src) + exc_cols if c not in cols]
    if absent:
        return {out: dict(v=FAIL, declared=True, citation_state=cs, source=blk, measured=f"the declared source column(s) {', '.join(absent)} are not columns of {table}: the declaration names a source the table does not carry")}
    kc = []
    if keys:
        k0 = keys[0] if len(keys[0]) > 1 or keys[0][0] != "id" else (keys[1] if len(keys) > 1 else keys[0])
        kc = list(k0)
    try:
        types = source_fetch_column_types(table, _source_cols(src))
        ktypes = {c: source_column_kind(t) for c, t in types.items()}
        preds = []
        for e in src["columns"]:
            p, why = source_entry_lacking(e, ktypes)
            if p is None:
                return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=blk, measured=f"NO_DETECTOR — {table}: {why}, so presence on it is not a source")}
            preds.append(p)
        pred = "(" + " AND ".join(preds) + ")"                      # the entries are alternatives: a row lacks a source only when EVERY entry lacks it
        excs = [x for x in (source_entry_exception(e) for e in src["columns"]) if x]
        contradicted = None
        if src.get("residual") == UNSOURCED_DECLARED:               # N-177: the declared honest label is CHECKED against the rows before it is allowed to stand
            e0 = src["columns"][0]
            p0, why0 = _source_entry_lacking_core(e0, ktypes)
            if p0 is None:
                return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=blk, measured=f"NO_DETECTOR — {table}: {why0}, so the declared residual {UNSOURCED_DECLARED} cannot be checked")}
            if src.get("untraced_marker") and ktypes.get(e0["column"]) != "text":
                return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=blk,
                                  measured=f"NO_DETECTOR — the declared untraced_marker is read in a text column and {table}.{e0['column']} is not one: the residual {UNSOURCED_DECLARED} cannot be checked")}
            rd = unsourced_declared_fetch(table, p0, e0["column"], src.get("untraced_marker"), kc[:3], source_entry_exception(e0))
            got = grade_unsourced_declared(src, rd, table, blk)
            if got is not None:
                return {out: got}
            contradicted = rd
        splits = [e for e in src["columns"] if isinstance(e.get("split_citation"), dict)]
        split_sql = (("(" + " OR ".join(_split_selected(e) for e in splits) + ")", "(" + " OR ".join(f"({_split_selected(e)} AND {_split_ok(e['column'])})" for e in splits) + ")") if splits else None)
        stats = source_read_stats(table, pred, kc[:3], exc=("(" + " OR ".join(excs) + ")") if excs else None, split=split_sql)
    except Unknown as exc:                                          # R41: this check's failure degrades only this check
        if _is_statement_timeout(exc):                              # even the existence read (first violating row, bounded sample, no counting) was cancelled: nothing was measured, which is NO_DETECTOR with the cause, never ERRORED
            return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=dict(blk, read="existence", timed_out=True),
                              measured=(f"NO_DETECTOR — the existence read of {table} (first violating row, bounded sample, no counting) also exceeded the statement timeout ({' '.join(str(exc).split())[:160]}): "
                                        "no source verdict was reached, so this is neither a PASS nor a FAIL; the check needs a longer per-check timeout or a narrower read"))}
        return {out: dict(v=ERRORED, declared=True, citation_state=cs, source=blk, measured=f"check errored: {exc}")}
    if stats.get("exact") is False:                                 # the existence read: no totals, only "at least 1"
        return {out: _residual_contradiction(_source_existence_record(stats, blk, kinds, cs, table), contradicted)}
    excepted = stats.get("excepted") if isinstance(stats.get("excepted"), int) else 0
    if excepted:
        blk = dict(blk, excepted=excepted)
        if stats["rows"] - excepted <= 0:
            return {out: dict(v=NO_DET, declared=True, citation_state=cs, source=dict(blk, rows=stats["rows"]),
                              measured=f"NO_DETECTOR — every one of the {stats['rows']} row(s) of {table} is excepted by declaration (except_when): no row was judged")}
        stats = dict(stats, rows=stats["rows"] - excepted)                  # the excepted rows are not judged: the grade is over the rest
    rec = grade_ldgr_source(dict(source_column=", ".join(_source_cols(src)), citation_state=cs), stats, table)
    rec["source"] = dict(blk, rows=stats["rows"], lacking=stats["lacking"])
    if excepted:
        rec["measured"] += f"; {excepted} row(s) excepted by declaration (except_when) are not judged"
    if isinstance(stats.get("split"), int):
        why_ = "; ".join(e["split_citation"]["why"] for e in src["columns"] if isinstance(e.get("split_citation"), dict))
        rec["source"]["split_citation_rows"] = stats["split"]
        rec["source"]["split_citation_ok"] = stats.get("split_ok")
        rec["measured"] += (f"; {stats['split']} row(s) carry a split-shaped citation (UNSOURCED vedha partner + a K1 transit result) on the declared rows; {stats.get('split_ok')} of them pass on the K1 part "
                            f"(machine locus resolves to a corpus chunk, locus words and excerpt hold, excerpt at most {SPLIT_MAX_EXCERPT_WORDS} words) and the rest count as lacking a source "
                            f"(declared split_citation: {why_})")
    rec["measured"] = f"row-level {'/'.join(kinds)} source: " + rec["measured"]
    return {out: _residual_contradiction(rec, contradicted)}


# ─────────────────── N-150 R1 / R2 (REGISTRY_REVISION 26): a declared-none prose N/A is CHECKED against the live schema ───────────────────
# `prose_fields []` alone is no longer a release: the Narr.* and Null.* N/A reads only through `prose_none` (validated above) and a passing check of it against the asset's produced tables:
# every text-capable column (text / varchar / citext / array / json(b) / user-defined) must be declared closed (the DATA must stay inside the declared vocabulary) or, for json(b), declared
# free of string leaves. An open text column is a contradiction of the declaration: FAIL, not N/A. R2 (Narr.lint not applicable) is keyed identically: it is one of the four Narr checks.
PROSE_NONE_TEXTLIKE = LDGR_TEXT_TYPES + ("array", "json", "jsonb", "user-defined")


PROSE_NONE_TEXT_ARRAY_UDTS = ("_text", "_varchar", "_bpchar", "_citext", "_name")     # the pg_type names of the TEXT array types (information_schema `udt_name` of an ARRAY column)
PROSE_NONE_NONTEXT_UDTS = ("vector", "halfvec", "sparsevec")      # USER-DEFINED types that hold numbers, never text (pgvector embeddings: classical_text_chunks.embedding, bodha_signal_embeddings.embedding_vec)


def prose_none_kind(data_type, udt=None) -> str | None:
    """'text' | 'array' | 'json' | 'enum' for an information_schema data_type that can carry text, None for one that cannot (integer, numeric, boolean, timestamp, uuid, bytea ...).
    An ARRAY is text-capable only when its element type is text (`udt` = information_schema udt_name: _text / _varchar / _bpchar / _citext / _name); an array of uuid / bigint / integer /
    numeric ... is NOT (SS / Worker F finding: bg_doshas' uuid[] and bigint[] id columns). An ARRAY whose element type was not read (`udt` None) stays text-capable: unknown is never "not prose"."""
    t = str(data_type or "").strip().casefold()
    if t not in PROSE_NONE_TEXTLIKE:
        return None
    if t == "array" and udt is not None and str(udt).strip().casefold() not in PROSE_NONE_TEXT_ARRAY_UDTS:
        return None
    if t == "user-defined" and udt is not None and str(udt).strip().casefold() in PROSE_NONE_NONTEXT_UDTS:
        return None                                  # an embedding vector is not an enum of text labels: it can carry no prose
    return "array" if t == "array" else "json" if t in ("json", "jsonb") else "enum" if t == "user-defined" else "text"


def _prose_none_cond(c: str, kind: str, entry: dict):
    """The SQL predicate 'this row's column `c` (already quoted) holds text OUTSIDE the declared closure' for one `closed_columns` entry (pure; shared by the exact count and the existence read,
    so the two cannot disagree on what a violation is), or None when the entry cannot be read on a column of this `kind` (json-only forms on a non-json column)."""
    if entry.get("values") is not None:
        arr = "ARRAY[" + ",".join(_sql_lit(v) for v in entry["values"]) + "]::text[]"
        if kind == "array":
            return f"EXISTS (SELECT 1 FROM unnest({c}) AS u(x) WHERE u.x IS NOT NULL AND u.x::text <> ALL({arr}))"
        if kind == "json":
            return f"EXISTS (SELECT 1 FROM jsonb_path_query({c}::jsonb, 'strict $.**') AS l(x) WHERE jsonb_typeof(l.x) = 'string' AND (l.x #>> '{{}}') <> ALL({arr}))"
        return f"{c}::text <> ALL({arr})"
    if entry.get("json_leaf_patterns") is not None:
        if kind != "json":
            return None                                     # json_leaf_patterns is only meaningful on json(b): the grader refuses it before this runs
        # a row is outside the closure when it has MORE string leaves than the string leaves that sit at a declared path AND match that path's kind (a path's leaves are counted once per path;
        # the validator refuses two paths that differ only in [*]: paths with different key sequences cannot match the same leaf)
        def _leaf_ok(pat):
            if "values" in pat:                             # a closed vocabulary at this path (a graha title, a formula-version string)
                return "(p.x #>> '{}') = ANY(ARRAY[" + ",".join(_sql_lit(v) for v in pat["values"]) + "]::text[])"
            return f"(p.x #>> '{{}}') ~ '{PROSE_NONE_LEAF_KINDS[pat['kind']]}'"
        ok = " + ".join(f"(SELECT count(*) FROM jsonb_path_query({c}::jsonb, '{pat['path']}') AS p(x) WHERE jsonb_typeof(p.x) = 'string' AND {_leaf_ok(pat)})"
                        for pat in entry["json_leaf_patterns"])
        return f"(SELECT count(*) FROM jsonb_path_query({c}::jsonb, 'strict $.**') AS l(x) WHERE jsonb_typeof(l.x) = 'string') <> ({ok})"
    if kind != "json":
        return None                                         # no_string_leaves is only meaningful on json(b): the grader refuses it before this runs
    return f"EXISTS (SELECT 1 FROM jsonb_path_query({c}::jsonb, 'strict $.**') AS l(x) WHERE jsonb_typeof(l.x) = 'string')"


def prose_none_outside_sql(table: str, col: str, kind: str, entry: dict, filt=None) -> str:
    """ONE read-only count: the rows of `table` (optionally sliced by the produced-table `filt` {column, equals}) whose `col` holds text OUTSIDE the declared closed vocabulary
    (`entry['values']`), or, for a `no_string_leaves` entry, holds any string leaf. Identifiers must already match the strict pattern; the values are SQL string literals (quote-doubled).
    This is the EXACT read (every row visited and counted); `prose_none_existence_sql` is its bounded twin for a table the exact read cannot finish."""
    c = f'"{col}"'
    where = f' WHERE "{filt["column"]}"::text = {_sql_lit(filt["equals"])}' if filt else ""
    glue = " AND " if where else " WHERE "
    cond = _prose_none_cond(c, kind, entry)
    if cond is None:
        return "SELECT NULL::text"
    sp = _scope_pred(table)
    return f'SELECT count(*)::text FROM "{table}"{where}{glue}{c} IS NOT NULL AND {cond}{f" AND ({sp})" if sp else ""}'


# ───────────── the bounded EXISTENCE read of a declared closure (SS N-176 / interim census: bo_drishti, 2026-10-07) ─────────────
# The exact read above counts every row of the table. On bodha_question_lenses (three jsonb documents per row, each traversed once per declared leaf path) it was cancelled by the census role's
# statement timeout, and because the read sat OUTSIDE the per-check guard all six Narr/Null cells of bo_drishti read ERRORED. For a table that is large (the catalog estimate reaches
# LDGR_CHEAP_MIN_ROWS) or whose exact read timed out, the verdict is now read by EXISTENCE, the same discipline as the Ldgr existence read: ONE statement per column that stops at the first
# violating row (`LIMIT PROSE_NONE_SAMPLE_LIMIT` rows, unordered: no count(*), no ORDER BY, no GROUP BY) and answers a bounded sample of the offending values. The verdict is EXACT: a closure is shown
# CLOSED only when the scan reached the end of the table without a violating row (a PASS cannot be proven by fewer rows), a closure is shown BROKEN by the first violating row. What it does NOT
# produce is a total: the text says "at least 1", never an invented count. If even this read times out the closure is NOT READ (the cells read NO_DETECTOR with the cause; never ERRORED, never PASS).
PROSE_NONE_SAMPLE_LIMIT = 3        # offending values named by the existence read
PROSE_NONE_SAMPLE_CHARS = 80       # each sampled value is cut to this many characters (a lens document is large)


def prose_none_existence_sql(table: str, col: str, kind: str, entry: dict, filt=None) -> str:
    """The ONE bounded statement (pure): up to PROSE_NONE_SAMPLE_LIMIT offending values (each cut to PROSE_NONE_SAMPLE_CHARS characters) of the rows of `table` whose `col` leaves the declared closure, as one
    line of jsonb text. The rows are tested by `_prose_none_cond`, the SAME predicate the exact count uses. A non-empty answer is a violation; an empty one means the scan finished with none."""
    c = f'"{col}"'
    where = f' WHERE "{filt["column"]}"::text = {_sql_lit(filt["equals"])}' if filt else ""
    glue = " AND " if where else " WHERE "
    cond = _prose_none_cond(c, kind, entry)
    if cond is None:
        return "SELECT NULL::text"
    return (f"SELECT coalesce(jsonb_agg(s.x), '[]'::jsonb)::text FROM (SELECT left({c}::text, {PROSE_NONE_SAMPLE_CHARS}) AS x FROM \"{table}\"{where}{glue}{c} IS NOT NULL AND {cond}{f' AND ({_scope_pred(table)})' if _scope_pred(table) else ''} "
            f"LIMIT {PROSE_NONE_SAMPLE_LIMIT}) s")


def prose_none_fetch_existence(table: str, col: str, kind: str, entry: dict, filt=None) -> dict:
    """{violating, sample, exact: False}: the existence read of `prose_none_existence_sql`. Raises Unknown on a failed (or timed-out) read."""
    blob = scalar(prose_none_existence_sql(table, col, kind, entry, filt))
    try:
        got = json.loads(blob or "null")
    except json.JSONDecodeError as exc:
        raise Unknown(f"prose_none_fetch_existence: unparseable read of {table}.{col}: {exc}") from exc
    if not isinstance(got, list):
        raise Unknown(f"prose_none_fetch_existence: malformed answer for {table}.{col}: {blob!r}")
    return dict(violating=bool(got), sample=[str(x) for x in got], exact=False)


def prose_none_read_outside(table: str, col: str, kind: str, entry: dict, filt=None, *, est="read", exact_timed_out: bool = False):
    """One closed column's closure reading: an int (the EXACT count of violating rows, while the table is small) or a dict (the bounded EXISTENCE read: `violating`, `sample`, `exact` False, `why_cheap`)
    when the catalog estimate reaches LDGR_CHEAP_MIN_ROWS or the exact read was cancelled by a statement timeout; `dict(unread=...)` when even the existence read timed out (the closure was not
    read: never PASS, never a violation, never ERRORED). Any other failure propagates (ERRORED, as before). `est` is the table's catalog estimate when the caller already read it (default: read it here);
    `exact_timed_out` says an exact count of THIS table was already cancelled, so its other columns go straight to the existence read (one timeout per table, not one per column)."""
    blk = _scope_block(table)
    if blk:
        return dict(unread=blk, why_cheap=None, exact_timed_out=False)
    if est == "read":
        est = source_estimate_rows(table)
    why, timed_out = None, False
    if exact_timed_out:
        why, timed_out = "the exact row count of this table already exceeded the statement timeout", True
    elif est is not None and est >= LDGR_CHEAP_MIN_ROWS:
        why = f"the catalog estimates {est} rows (>= {LDGR_CHEAP_MIN_ROWS})"
    else:
        try:
            n = scalar(prose_none_outside_sql(table, col, kind, entry, filt))
        except Unknown as err:
            if not _is_statement_timeout(err):
                raise
            why, timed_out = "the exact row count exceeded the statement timeout", True
        else:
            try:
                return int(n)
            except (TypeError, ValueError) as exc:
                raise Unknown(f"prose_none_fetch_outside: unparseable count for {table}.{col}: {n!r}") from exc
    try:
        return dict(prose_none_fetch_existence(table, col, kind, entry, filt), why_cheap=why, exact_timed_out=timed_out)
    except Unknown as err:
        if not _is_statement_timeout(err):
            raise
        return dict(unread=f"the existence read (first violating row, bounded sample, no counting) also exceeded the statement timeout ({' '.join(str(err).split())[:160]}): "
                           "no closure verdict was reached, so this is neither a PASS nor a FAIL", why_cheap=why, exact_timed_out=timed_out)


def prose_none_fetch_outside(tables: dict, target: str, pn: dict, udts=None) -> dict:
    """{(table, column): rows outside the declared closure} for every `closed_columns` entry whose column exists and is text-capable in `tables` ({table: (columns, types, filter)});
    an entry that cannot be read is left out (the grader reads a missing count as unread). A value is an int (the exact count: small tables, as before) or a dict from `prose_none_read_outside`
    (the bounded existence read of a large table, or `unread` when even that timed out). Raises Unknown on any other failed read."""
    out, est_of, slow = {}, {}, set()               # the catalog estimate is read once per table; a table whose exact count timed out is read by existence for its other columns
    for e in pn.get("closed_columns") or []:
        t = e.get("table") or target
        cols, types, filt = tables.get(t, (None, None, None))
        if not (isinstance(cols, (list, tuple, set)) and isinstance(types, dict) and e["column"] in cols):
            continue
        kind = prose_none_kind(types.get(e["column"]), ((udts or {}).get(t) or {}).get(e["column"]))
        if kind is None or not (_D1_SQL_IDENT.fullmatch(t) and _D1_SQL_IDENT.fullmatch(e["column"])):
            continue
        if (e.get("no_string_leaves") is True or e.get("json_leaf_patterns") is not None) and kind != "json":
            continue
        if t not in est_of:
            est_of[t] = source_estimate_rows(t)
        got = prose_none_read_outside(t, e["column"], kind, e, filt, est=est_of[t], exact_timed_out=t in slow)
        if isinstance(got, dict) and got.get("exact_timed_out"):
            slow.add(t)
        out[(t, e["column"])] = got
    return out


def grade_prose_none(aid: str, decl: dict, tables: dict, target, outside: dict, *, udts=None, keys=None, written=None) -> dict:
    """The six Narr/Null records for an asset that declares `prose_none` (pure). `tables` is {table: (columns, types, filter)} for the asset's produced tables; `outside` the closure counts
    ({(table, column): n}; a missing key = not read). N/A (Narr cause no-prose, Null cause no-prose-declared, each carrying the checked `prose_none` block) ONLY when every produced
    table's columns and types were read, every text-capable column is declared closed, every declared column exists and is text-capable (a json-only `no_string_leaves` on a json column) and the
    data stays inside every declared vocabulary. An open column or a violated closure is a contradiction: Narr.agree FAIL (the others NO_DETECTOR); a read that did not happen is NO_DETECTOR.
    `udts` {table: {column: udt_name}} types the ARRAY columns (an array of uuid / bigint / int is no text); `keys` {table: [[unique / primary key columns]]} backs `identifier_columns` (a TEXT
    column that holds identifiers is exempt from the vocabulary only when it is a member of a unique / primary key of its table, or a declared source column); `written` {table: {columns}} is
    what the writer scan found the asset's writer WRITES: with `column_scope: "written"` only those columns are judged (a shared table's other columns belong to other assets), and a scan that
    saw no write at all is NO_DETECTOR."""
    pn = decl["prose_none"]
    scope = pn.get("column_scope") or "all"
    ident = {((t.get("table") or target), t["column"]) for t in (pn.get("identifier_columns") or [])}
    def kind_of(t, c, types):
        return prose_none_kind(types.get(c), ((udts or {}).get(t) or {}).get(c))
    judged_written = None
    if scope == "written":
        if not (isinstance(written, dict) and any(written.values())):
            judged_written = False
        else:
            judged_written = {t: {str(c).casefold() for c in cs} for t, cs in written.items()}
    declared = {((e.get("table") or target), e["column"]): e for e in pn["closed_columns"]}
    exempt = {(target, c) for c in source_declared_columns(decl)}
    transcribed = {((t.get("table") or target), t["column"]) for t in (pn.get("transcription_columns") or [])}      # N-156 F4: hand-authored seed text that transcribes a source is not prose
    exempt |= transcribed
    exempt |= ident
    # N-156 F4: the asset's declared source columns are source metadata, not prose: never "open", never needing a vocabulary
    unread, wrong, open_cols, closed, unread_tables, existence = [], [], [], [], set(), []
    for t, (cols, types, _f) in tables.items():
        if not (isinstance(cols, (list, tuple, set)) and cols and isinstance(types, dict)):
            unread.append(f"{t}: columns or column types not read")
            unread_tables.add(t)
            continue
        lacking_t = [c for c in cols if c not in types]
        if lacking_t:
            unread.append(f"{t}: no type read for {lacking_t}")
            unread_tables.add(t)
            continue
        for c in cols:
            if judged_written is False or (judged_written is not None and c.casefold() not in judged_written.get(t, set())):
                continue                                         # column_scope written: a column this asset's writer does not write is another asset's (all unjudged when the writes are unknown: NO_DETECTOR below)
            if kind_of(t, c, types) is not None and (t, c) not in declared and (t, c) not in exempt:
                open_cols.append(f"{t}.{c} ({types[c]})")
        for (et, ec) in sorted(exempt):
            if et == t and ec not in cols:
                wrong.append(f"{t}.{ec}: a declared source column that is not a column of {t}")
    if judged_written is False:
        unread.append("column_scope is `written` but the writer's writes could not be read (or the scan saw no write at all): the columns it writes are unknown")
    for (t, c) in sorted(transcribed):
        if t not in tables:
            wrong.append(f"{t}.{c}: a declared transcription column of {t}, which is not one of the asset's produced tables")
    src_cols = {(target, c) for c in source_declared_columns(decl)}
    for (t, c) in sorted(ident):
        if t not in tables:
            wrong.append(f"{t}.{c}: a declared identifier column of {t}, which is not one of the asset's produced tables")
            continue
        if t in unread_tables:
            continue
        cols, types, _f = tables[t]
        if c not in cols:
            wrong.append(f"{t}.{c}: a declared identifier column that is not a column of {t}")
        elif kind_of(t, c, types) is None:
            wrong.append(f"{t}.{c}: a declared identifier column that is not text-capable ({types.get(c)}): there is nothing to exempt")
        elif (t, c) in src_cols:
            pass                                                  # a declared source (provenance) column is an identifier by declaration
        elif not isinstance(keys, dict) or t not in keys:
            unread.append(f"{t}.{c}: the table's unique / primary keys were not read, so the identifier column cannot be checked")
        elif not any(c in k for k in keys[t] if isinstance(k, (list, tuple))):
            wrong.append(f"{t}.{c}: a declared identifier column that is not a member of any unique / primary key of {t} (keys: {[list(k) for k in keys[t]]}): it is not shown to hold identifiers")
    for (t, c), e in sorted(declared.items()):
        if t not in tables:
            wrong.append(f"{t}.{c}: {t} is not one of the asset's produced tables")
            continue
        if t in unread_tables:
            continue                                      # its schema was not read: the declared column cannot be judged (the table is already listed as unread)
        cols, types, _f = tables[t]
        if c not in cols:
            wrong.append(f"{t}.{c}: not a column of {t}")
            continue
        kind = kind_of(t, c, types)
        if kind is None:
            wrong.append(f"{t}.{c}: not a text-capable column ({types.get(c)}), so it is not declared closed")
            continue
        if (e.get("no_string_leaves") is True or e.get("json_leaf_patterns") is not None) and kind != "json":
            wrong.append(f"{t}.{c}: no_string_leaves / json_leaf_patterns is for a json(b) column, this is {types.get(c)}")
            continue
        n = outside.get((t, c)) if isinstance(outside, dict) else None
        what = ("a string leaf" if e.get("no_string_leaves") is True else
                "a string leaf outside the declared paths (or a declared path holding a string that is not its kind, or outside its closed values)" if e.get("json_leaf_patterns") is not None
                else "text outside the declared closed vocabulary")
        if isinstance(n, dict):
            # the bounded EXISTENCE read (a large table, or an exact read that timed out): the same verdict rule (a violating row = broken, none after a complete scan = closed), no total
            if n.get("unread"):
                unread.append(f"{t}.{c}: the closure was not read ({n['unread']})")
            elif not isinstance(n.get("violating"), bool):
                unread.append(f"{t}.{c}: the closure was not read")
            elif n["violating"]:
                shown = (f"; first up to {PROSE_NONE_SAMPLE_LIMIT} offending value(s) found, unordered, each cut to {PROSE_NONE_SAMPLE_CHARS} characters: "
                         + json.dumps(list(n.get("sample") or []), ensure_ascii=False)) if n.get("sample") else ""
                wrong.append(f"{t}.{c}: at least 1 row holds {what} (existence read: rows were not counted, so no total is stated{shown})")
                existence.append(f"{t}.{c}")
            else:
                closed.append(dict(table=t, column=c, kind=kind, read="existence"))
                existence.append(f"{t}.{c}")
        elif not (isinstance(n, int) and not isinstance(n, bool)):
            unread.append(f"{t}.{c}: the closure was not read")
        elif n > 0:
            wrong.append(f"{t}.{c}: {n} row(s) hold {what}")
        else:
            closed.append(dict(table=t, column=c, kind=kind))
    block = dict(checked=True, tables=sorted(tables), closed=closed, open=open_cols, contradicted=wrong, unread=unread, source_columns=sorted(c for (_t, c) in exempt if (_t, c) not in transcribed and (_t, c) not in ident), transcription_columns=sorted(f"{_t}.{c}" for (_t, c) in transcribed),
                 identifier_columns=sorted(f"{_t}.{c}" for (_t, c) in ident), column_scope=scope)
    if existence:                  # the bounded existence read answered for these columns (no total; key absent for an asset every closure of which was counted exactly)
        block["existence_reads"] = sorted(existence)
    allc = NARR_CHECKS + NULL_CHECKS
    if open_cols or wrong:
        what = "; ".join(([f"open text column(s) the declaration does not close: {', '.join(open_cols)}"] if open_cols else []) + wrong)
        rec = {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares no prose but its schema contradicts it ({what})", prose_none=dict(block)) for c in allc}
        rec["Narr.agree"] = dict(v=FAIL, measured=f"{aid} declares no prose (prose_none) but its schema contradicts it: {what}", prose_none=dict(block))
        return rec
    if unread:
        return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares no prose (prose_none) but the declaration could not be checked: {'; '.join(unread)}", prose_none=dict(block)) for c in allc}
    note = (f"prose_none declared and CHECKED against the live schema (N-150 R1): {len(tables)} produced table(s), every text-capable column closed ({len(closed)} declared closed, data "
            f"inside the vocabulary), no open text column")
    if existence:
        note += f"; the closure of {', '.join(sorted(existence))} was read by the bounded existence read (no violating row found by a scan that reached the end of the table; rows were not counted)"
    return {c: dict(_na(f"{note}: {pn['why']}", "no-prose" if c.startswith("Narr.") else "no-prose-declared"), prose_none=dict(block)) for c in allc}


NO_WRITER_CAUSES = {"Build.completion": ("service-no-writer-no-count-sql",), "Build.count_integrity": ("service-no-writer-no-count-sql",), "Build.dep_liveness": ("static-data-existence-only",),
                    "Build.registered": ("no-writer-registry-agrees",), "Build.contract": ("no-writer-registry-agrees",), "Idem.pattern": ("no-writer-registry-agrees",),
                    "Build.exercised": ("never-run-no-writer", "never-executed-no-writer", "legacy-attempts-no-writer"), "Earn.build_record": ("no-writer-registry-agrees", "declared-probe-runs-verified")}


def no_writer_na_problem(crit: str, meas) -> str | None:
    """None unless a no-writer N/A of Build.registered / Build.contract / Build.exercised / Idem.pattern is NOT backed by the three agreeing facts (N-150 R5): the asset DECLARES `has_writer: false`,
    the registry row says has_writer false, and no @register was found. The record carries them as `no_writer` {declared, registry_has_writer, register_files}; a record without the block, or with
    any fact other than (true, false, 0), is not a release. Pure; read by `_check_contribution` and `_na_released`."""
    if crit not in NO_WRITER_CAUSES or not isinstance(meas, dict) or meas.get("v") != NA or meas.get("cause") not in NO_WRITER_CAUSES[crit]:
        return None
    b = meas.get("no_writer")
    if not (isinstance(b, dict) and b.get("declared") is True and b.get("registry_has_writer") is False and b.get("register_files") == 0 and b.get("register_mentions") == []):
        return (f"{crit} N/A rests on the declared fact `has_writer: false` that the registry row and the code scan agree with (N-150 R5): this record does not carry all four "
                "(declared, registry has_writer false, no @register in any layer, no `register(` call naming or possibly naming the asset), so a registry-only no-writer asset is not released")
    if meas.get("cause") == "declared-probe-runs-verified" and not (b.get("probe_attempts") is True and b.get("verified") is True and b.get("service") is True and isinstance(b.get("runs"), list) and b["runs"]):
        return f"{crit} N/A (SS 2026-10-05 probe_attempts) rests on declared probe runs VERIFIED against the live rows of a writer-less service: this record carries no such verification"
    if meas.get("cause") == "service-no-writer-no-count-sql" and not (b.get("service") is True and b.get("registry_kind") == "service" and b.get("declared_kind") == "service"):
        return f"{crit} N/A (SS 2026-10-05 R-d) rests on a writer-less SERVICE: this record does not carry the declared kind service agreeing with the registry asset_kind service"
    if meas.get("cause") == "static-data-existence-only" and not (b.get("static_data") is True and b.get("declared_kind") == "static" and b.get("migrations_checked") is True
                                                                   and isinstance(b.get("migrations"), list) and b["migrations"] and isinstance(b.get("table"), str)):
        return f"{crit} N/A (SS 2026-10-05 R-d) rests on migration-seeded STATIC data whose declaration names its owning migrations and whose migration files were CHECKED on main: this record carries no such check"
    return None


def lint_na_problem(crit: str, meas) -> str | None:
    """None unless a Narr.lint N/A of cause lint-not-applicable is NOT backed by the scan's own agreement (N-150 R2): the record must carry the `lint_none` block with at least one scanned writer file and
    applied == [] (never the declaration alone). Pure; read by `_check_contribution` and `_na_released`."""
    if crit != "Narr.lint" or not isinstance(meas, dict) or meas.get("v") != NA or meas.get("cause") != "lint-not-applicable":
        return None
    b = meas.get("lint_none")
    if not (isinstance(b, dict) and b.get("applied") == [] and b.get("beyond") == [] and isinstance(b.get("scope_files"), int) and b["scope_files"] > 0 and meas.get("applied") == []
            and isinstance(b.get("why"), str) and isinstance(b.get("evidence"), str)):
        return ("Narr.lint N/A rests on a declared lint_none that the lint scan AGREES with (N-150 R2): this record carries no scan agreement (a scanned writer file and no lint surface), "
                "so the declaration alone is not a release")
    return None


def prose_none_na_problem(crit: str, meas, facts=None) -> str | None:
    """None unless a Narr.* / Null.* N/A of cause no-prose / no-prose-declared is NOT backed by a checked `prose_none` block (N-150 R1: bare `prose_fields []` is no release). A coupled Narr N/A
    (prose_coupling, N-94) is judged by `narr_coupling_problem`, not here. Pure; read by `_check_contribution` and `_na_released`."""
    if not (isinstance(crit, str) and crit in NARR_CHECKS + NULL_CHECKS) or not isinstance(meas, dict) or meas.get("v") != NA:
        return None
    if meas.get("cause") not in ("no-prose", "no-prose-declared"):
        return None
    if crit.startswith("Narr.") and meas.get("prose_coupling") is not None:
        return None
    b = meas.get("prose_none")
    if not (isinstance(b, dict) and b.get("checked") is True and isinstance(b.get("tables"), list) and b["tables"] and b.get("open") == [] and b.get("contradicted") == []
            and b.get("unread") == []):
        return (f"{crit} N/A rests on a CHECKED declared-none prose form (prose_none, N-150 R1): this record carries no passing schema check, so a bare `prose_fields []` / an unchecked "
                "claim is not a release")
    return None


# ─────────────────────────── E6 packet (c): the Null and Narr checks ───────────────────────────
# Design: /Users/Dev/suvarna-evidence/E6.1/packet_c_design.md. Each check is a pure grader over inputs the census
# reads (declarations, catalog, writer code, tests on disk); measure() calls `prose_checks`, so the saved-census
# harness and the unit tests run exactly what measure() runs. INCONCLUSIVE is a measured STATE (`inconclusive: true`
# on a NO_DETECTOR record), never a verdict and never a PASS. Null can never read PASS ("never PASS alone", Track E E6.1).
PROSE_JSON_TYPES = ("json", "jsonb")
_EMPTY_JSON_DEFAULT = re.compile(r"\s*'\s*(?:\{\s*\}|\[\s*\])\s*'\s*(?:::\s*jsonb?)?\s*", re.I)



def _json_entry(entry: str) -> bool:
    return parse_prose_field(entry)[1] is not None


def grade_narr_agree_tables(entries, own) -> dict:
    """Narr.agree over every table the asset owns (`own`: table -> (columns | None, types | None)): a declared prose
    entry must resolve to a column of at least one owned table (a multi-table asset keeps its narration column in a
    table other than the registry's target_table). FAIL: a column found in no owned table while every owned table's
    columns are known, or a JSON-path entry whose column is typed non-JSON everywhere it is found. PASS: all resolve
    (JSON types verified). PARTIAL: names resolve but a JSON-path column's type was not read. NO_DETECTOR: no owned
    table, or a missing column could sit in a table whose columns are unknown (never 'zero columns')."""
    if not own:
        return dict(v=NO_DET, measured="NO_DETECTOR — no target table to read the declared prose columns against")
    known = {t: set(c) for t, (c, _ty) in own.items() if isinstance(c, (list, tuple, set)) and c}
    unknown = sorted(t for t in own if t not in known)
    names = ", ".join(own)
    parsed = [(e, *parse_prose_field(e)) for e in entries]
    missing = [e for e, col, _ in parsed if not any(col in cs for cs in known.values())]
    if missing:
        if unknown:
            return dict(v=NO_DET, measured=f"NO_DETECTOR — {', '.join(missing)} not found in the known columns of {names}, and "
                                           f"the columns of {', '.join(unknown)} are unknown (never 'zero columns')")
        return dict(v=FAIL, measured=f"declared prose column(s) not among the columns of {names}: {', '.join(missing)}")
    wrong, unread = [], []
    for e, col, path in parsed:
        if path is None:
            continue
        kinds = [(own[t][1] or {}).get(col) for t in known if col in known[t]]
        if any(k and k.lower() in PROSE_JSON_TYPES for k in kinds):
            continue
        if any(k is None for k in kinds):
            unread.append(col)
        else:
            wrong.append(f"{col} ({', '.join(sorted(set(kinds)))})")
    if wrong:
        return dict(v=FAIL, measured=f"JSON-path entries on non-JSON column(s) of {names}: {', '.join(wrong)}")
    if unread:
        # SS 2026-10-05 R-e (bo_pratijna): the typed JSON-leaf reader (the data-level type of the declared leaf, not only the column's type) is DEFERRED: with the column type unread nothing
        # establishes that the declared path entries resolve, so the cell reads NO_DETECTOR and says why (it was PARTIAL)
        return dict(v=NO_DET, measured=f"NO_DETECTOR — typed JSON-leaf reader deferred (SS 2026-10-05 R-e): every declared column exists in {names}, but the type of JSON-path column(s) "
                                       f"{', '.join(sorted(set(unread)))} was not read, so the declared path entries are not established")
    return dict(v=PASS, measured=f"all {len(parsed)} declared prose entr{'y' if len(parsed) == 1 else 'ies'} resolve to "
                                 f"column(s) of {names} (names, and JSON types for path entries; the writer binding is "
                                 "the declaration tests' claim, not read here)")


def grade_narr_agree(entries, table, columns, types) -> dict:
    """Single-table form of grade_narr_agree_tables (table, its columns, its column types)."""
    return grade_narr_agree_tables(entries, {table: (columns, types)} if table else {})


def _holders(col, own):
    """The owned tables whose KNOWN columns include `col`."""
    return [t for t, v in own.items() if isinstance(v[0], (list, tuple, set)) and v[0] and col in v[0]]


def grade_null_schema_default_tables(entries, own) -> dict:
    """Null.schema_default over the asset's owned tables (`own`: table -> (columns, types, defaults)): each declared
    entry is read against the default of the owned table(s) that HOLD its column (a same-named column elsewhere is not
    read). FAIL names a non-NULL default (an empty JSON container on a path-only column is structure, not a stand-in).
    PARTIAL (never PASS) when none; NO_DETECTOR when an entry's column is held by no owned table or its table's
    defaults were not read."""
    parsed = [parse_prose_field(e) for e in entries]
    hit, unread = [], []
    for col in sorted({c for c, _ in parsed}):
        held = _holders(col, own)
        if not held:
            unread.append(f"{col} (no owned table holds it)")
            continue
        for t in held:
            dflts = own[t][2] if len(own[t]) > 2 else None
            if not isinstance(dflts, dict):
                unread.append(f"{col} (defaults of {t} not read)")
                continue
            d = dflts.get(col)
            if d in (None, ""):
                continue
            if all(path is not None for c2, path in parsed if c2 == col) and _EMPTY_JSON_DEFAULT.fullmatch(d):
                continue
            hit.append(f"{t}.{col} DEFAULT {d}")
    if hit:
        return dict(v=FAIL, measured="declared prose column(s) carry a non-NULL schema default: " + "; ".join(hit))
    if unread:
        return dict(v=NO_DET, measured="NO_DETECTOR — the column default could not be read for: " + "; ".join(unread))
    cols = sorted({c for c, _ in parsed})
    # `clean` (S1): this PARTIAL is a genuinely clean reading (no default found, none unread); only that reading can be earned up to PASS by a verified null_convention
    return dict(v=PARTIAL, clean=True, measured=f"no schema default on the declared prose column(s) {', '.join(cols)}; writer "
                                                "literal fallbacks and constant columns are not measured here, so this is never PASS")


def grade_null_schema_default(entries, columns, defaults) -> dict:
    """Single-table form of grade_null_schema_default_tables (the target table's columns and defaults)."""
    if not isinstance(columns, (list, tuple, set)) or not columns or not isinstance(defaults, dict):
        return dict(v=NO_DET, measured="NO_DETECTOR — the target table's columns or column defaults were not read")
    return grade_null_schema_default_tables(entries, {"(table)": (list(columns), None, defaults)})


# Placeholder literals that stand in for NULL in prose (closed, lowercase; compared trimmed and lowercased).
PROSE_PLACEHOLDERS = ("", "n/a", "na", "none", "null", "unknown", "tbd", "-", "--", "undefined", "nan")
_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_SCOPE_COUNT = re.compile(r"\s*select\s+count\(\s*(?:\*|1)\s*\)(?:\s+as\s+\w+)?\s+from\s+(?:public\.)?(\w+)"
                          r"(\s+where\s+.+?)?\s*;?\s*", re.I | re.S)
_SCOPE_BANNED = re.compile(r"\b(?:select|join|group|having|union|limit|order|intersect|except)\b|;", re.I)


def _split_depth0(s: str, sep: str):
    """Split `s` at depth-0 occurrences of the single character `sep` (parentheses and single-quoted literals respected)."""
    out, depth, q, start, j = [], 0, False, 0, 0
    while j < len(s):
        ch = s[j]
        if q:
            if ch == "'":
                if j + 1 < len(s) and s[j + 1] == "'":
                    j += 1
                else:
                    q = False
        elif ch == "'":
            q = True
        elif ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif ch == sep and depth == 0:
            out.append(s[start:j])
            start = j + 1
        j += 1
    out.append(s[start:])
    return out


def _count_scope_tail(count_sql: str, table: str):
    """The ` WHERE ...` tail (or "") of a registry count_sql that is a plain `SELECT count(*) FROM <table> [WHERE ...]`
    over `table`, OR (E5.7) a SUM of such counts `SELECT (SELECT count(*) FROM a WHERE ..) + (SELECT count(*) FROM b WHERE ..) [AS n]` in which `table`
    is counted by EXACTLY ONE term (that term's tail); None for any other shape (join, group, union, nested subselect, constant, another table,
    the table counted twice): the asset's own rows cannot then be scoped from it."""
    q = re.sub(r"--[^\n]*", "", count_sql or "")
    m = _SCOPE_COUNT.fullmatch(q)
    if m:
        if m.group(1).lower() != (table or "").lower():
            return None
        tail = (m.group(2) or "").strip()
        if tail and _SCOPE_BANNED.search(tail):
            return None
        return " " + tail if tail else ""
    body = re.fullmatch(r"\s*select\s+(.*?)(?:\s+as\s+\w+)?\s*;?\s*", q, re.I | re.S)
    if not body:
        return None
    inner = body.group(1).strip()
    while inner.startswith("(") and len(_split_depth0(inner, "\x00")) == 1:
        # one pair of parentheses wrapping the WHOLE sum (`SELECT ( (SELECT count(*) ..) + (SELECT count(*) ..) ) AS count`): unwrap it when its match is the last character
        depth, close = 0, -1
        for j, ch in enumerate(inner):
            depth += ch == "("
            depth -= ch == ")"
            if depth == 0:
                close = j
                break
        if close != len(inner) - 1:
            break
        inner = inner[1:-1].strip()
    terms = _split_depth0(inner, "+")
    if len(terms) < 2:
        return None
    tails = []
    for t in terms:
        t = t.strip()
        if not (t.startswith("(") and t.endswith(")")):
            return None
        mt = _SCOPE_COUNT.fullmatch(t[1:-1])
        if not mt:
            return None                                  # a term the scan cannot read: the whole sum is unreadable
        tl = (mt.group(2) or "").strip()
        if tl and _SCOPE_BANNED.search(tl):
            return None
        if mt.group(1).lower() == (table or "").lower():
            tails.append(" " + tl if tl else "")
    return tails[0] if len(tails) == 1 else None


def _chart_pinned(tail: str) -> bool:
    """True when a ` WHERE ...` tail PINS the chart: no depth-0 OR anywhere (a depth-0 OR could let rows of other charts in) and a depth-0 AND-conjunct that is exactly `chart_id = $1`
    (an OR inside parentheses, as in `chart_id = $1 AND (a OR b)`, is fine). The depth-0 OR / AND are found by a CHARACTER scan (quotes and parentheses respected, a keyword is a whole word
    even when glued to a parenthesis: `x = 1 OR(y = 2)`, `(x)OR(y)`)."""
    t = re.sub(r"^\s*where\s+", "", tail or "", flags=re.I)
    conj, cur, depth, q, i, n = [], 0, 0, False, 0, len(t)
    word = lambda k: k < 0 or k >= n or not (t[k].isalnum() or t[k] == "_")      # noqa: E731
    while i < n:
        ch = t[i]
        if q:
            if ch == "'":
                if i + 1 < n and t[i + 1] == "'":
                    i += 1
                else:
                    q = False
        elif ch == "'":
            q = True
        elif ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif depth == 0:
            if t[i:i + 2].upper() == "OR" and word(i - 1) and word(i + 2):
                return False
            if t[i:i + 3].upper() == "AND" and word(i - 1) and word(i + 3):
                conj.append(t[cur:i])
                cur = i + 3
                i += 2
        i += 1
    conj.append(t[cur:])
    return depth == 0 and not q and any(re.fullmatch(r"\(?\s*(?:\w+\.)?\"?chart_id\"?(?:::\w+)?\s*=\s*\$1(?:::\w+)?(?!\d)\s*\)?", c.strip()) for c in conj)


def _in_list() -> str:
    return ", ".join("'" + p + "'" for p in PROSE_PLACEHOLDERS)


# whitespace class for "blank": the POSIX space class (space, tab, LF, VT, FF, CR) plus NBSP, zero-width space,
# U+2000-200A (en/em/thin... spaces) and the BOM; the same class text is valid in a PostgreSQL ARE and in Python re
_WS = r"[\s\u00A0\u200B\u2000-\u200A\uFEFF]"
_WS_TRIM_PY = f"^{_WS}+|{_WS}+$"
_WS_TRIM = f"'{_WS_TRIM_PY}', '', 'g'"


def prose_row_counts_sql(table: str, entries, where_tail: str, types=None) -> str:
    """One read-only count query: per declared entry, `count(*) FILTER` rows whose text is checkable (non-NULL, a TEXT
    value, not blank, not a placeholder) and rows holding a blank/placeholder string instead of NULL. A plain column
    reads `"c"::text` (a json/jsonb column must hold a JSON string, an array column is never text: `types` = column ->
    data_type); a JSON path `("c"::jsonb #>> '{k,k}')` only where the leaf is a JSON string; an array path (`[*]`) an
    EXISTS over jsonb_path_query. Trimming covers space, tab, CR and LF. Identifiers come from parse_prose_field
    (regex-validated): ValueError otherwise."""
    if not _IDENT.fullmatch(table or "") or not entries:
        raise ValueError("prose_row_counts_sql needs a table identifier and at least one declared entry")
    items = []
    for e in entries:
        col, path = parse_prose_field(e)
        if path and PROSE_WILDCARD in path:
            jp = "$"
            for seg in path:
                jp += "[*]" if seg == PROSE_WILDCARD else f'."{seg}"'
            src = (f"EXISTS (SELECT 1 FROM jsonb_path_query(\"{col}\"::jsonb, '{jp}') AS e(x) WHERE jsonb_typeof(x) = 'string' "
                   f"AND lower(regexp_replace(x #>> '{{}}', {_WS_TRIM})) ")
            checkable, blank = src + f"NOT IN ({_in_list()}))", src + f"IN ({_in_list()}))"
        else:
            ty = ((types or {}).get(col) or "").lower()
            if path is not None:
                keys = ",".join(path)
                v = f"(\"{col}\"::jsonb #>> '{{{keys}}}')"
                guard = f"jsonb_typeof(\"{col}\"::jsonb #> '{{{keys}}}') = 'string' AND "
            elif ty in ("json", "jsonb"):
                v, guard = f'("{col}"::jsonb #>> \'{{}}\')', f'jsonb_typeof("{col}"::jsonb) = \'string\' AND '
            elif ty == "array" or ty.endswith("[]") or ty.startswith("_"):
                v, guard = f'"{col}"::text', "FALSE AND "
            else:
                v, guard = f'"{col}"::text', ""
            tr = f"lower(regexp_replace({v}, {_WS_TRIM}))"
            checkable = ("(FALSE)" if guard == "FALSE AND " else f"{guard}{v} IS NOT NULL AND {tr} NOT IN ({_in_list()})")
            blank = ("(FALSE)" if guard == "FALSE AND " else f"{guard}{v} IS NOT NULL AND {tr} IN ({_in_list()})")
        items += [f"count(*) FILTER (WHERE {checkable})::text", f"count(*) FILTER (WHERE {blank})::text"]
    return f"SELECT {', '.join(items)} FROM {table}{where_tail}"


def prose_row_counts(table: str, entries, where_tail: str, types=None) -> dict:
    """entry -> dict(checkable=int, blank=int), from one read-only query. A malformed answer raises Unknown."""
    row = (psql(prose_row_counts_sql(table, entries, where_tail, types)) or [[]])[0]
    if len(row) != 2 * len(entries):
        raise Unknown(f"prose row-count query answered {len(row)} value(s) for {len(entries)} declared entr(ies)")
    try:
        return {e: dict(checkable=int(row[2 * i]), blank=int(row[2 * i + 1])) for i, e in enumerate(entries)}
    except ValueError as exc:
        raise Unknown(f"prose row-count query returned a non-integer: {exc}") from exc


UPPER_BOUND = "whole-table upper bound"


def grade_narr_checkable(entries, counts) -> dict:
    """Narr.checkable (SS 2026-10-01): rows actually CHECKABLE per declared entry (`counts[entry]` = dict(checkable,
    blank, scope), or None = unknown for that entry). PASS: every entry has >= 1 checkable row in a chart-scoped (or
    chart-free) count; PARTIAL: some have none / are unknown, or the count is a whole-table upper bound (the scope is
    named). Zero everywhere, unknown everywhere, or no row data: INCONCLUSIVE (NO_DETECTOR + inconclusive), never PASS."""
    if not isinstance(counts, dict):
        return dict(v=NO_DET, inconclusive=True, measured="INCONCLUSIVE: no row data was read for the declared prose "
                                                          "entries (scope unsupported or not measured); no PASS is possible")
    n = {e: (None if counts.get(e) is None else int(counts[e].get("checkable", 0))) for e in entries}
    scopes = sorted({counts[e]["scope"] for e in entries if counts.get(e) and counts[e].get("scope")})
    extra = dict(scope="; ".join(scopes)) if scopes else {}
    text = ", ".join(f"{e}={'unknown' if k is None else k}" for e, k in n.items())
    if not any(n.values()):
        return dict(v=NO_DET, inconclusive=True, checkable=n, **extra,
                    measured=f"INCONCLUSIVE: 0 checkable rows on every declared entry ({text})")
    bad = [e for e, k in n.items() if not k]
    if bad:
        return dict(v=PARTIAL, checkable=n, **extra,
                    measured=f"checkable rows per declared entry: {text}; none or unknown on {', '.join(bad)}")
    if UPPER_BOUND in scopes:
        return dict(v=PARTIAL, checkable=n, **extra, measured=f"checkable rows per declared entry: {text}; the count is a "
                    f"{UPPER_BOUND} (count_sql unparseable, unshared table that carries chart_id): rows of other charts may count")
    return dict(v=PASS, checkable=n, **extra, measured=f"checkable rows per declared entry: {text} ({'; '.join(scopes) or 'scope n/a'})")


def grade_null_blank_rows(entries, counts) -> dict:
    """Null.blank_rows: declared prose rows holding a blank string or a placeholder literal instead of NULL. FAIL on
    any. PARTIAL (never PASS) when none in >= 1 checkable row; INCONCLUSIVE without row data or checkable rows."""
    if isinstance(counts, dict):
        bad = {e: (None if counts.get(e) is None else int(counts[e].get("blank", 0))) for e in entries}
        ub = {e for e in entries if (counts.get(e) or {}).get("scope") == UPPER_BOUND}
        hit = [f"{e}={k}" for e, k in bad.items() if k and e not in ub]
        hit_ub = [f"{e}={k}" for e, k in bad.items() if k and e in ub]
        if hit:
            return dict(v=FAIL, blank=bad, measured="blank or placeholder rows standing in for NULL in declared prose "
                                                    "column(s): " + ", ".join(hit)
                        + (f" (not counted: {', '.join(hit_ub)} in a {UPPER_BOUND})" if hit_ub else ""))
        if hit_ub:
            return dict(v=PARTIAL, blank=bad, measured=f"blank or placeholder rows ({', '.join(hit_ub)}) in a {UPPER_BOUND}: "
                        "they may belong to other charts, so this chart is not failed on them; chart-scope the count to decide")
        if any((counts.get(e) or {}).get("checkable", 0) for e in entries):
            unk = [e for e, k in bad.items() if k is None]
            # `clean` (S1): every declared entry has >= 1 checkable row, none is unknown, none counted as a whole-table upper bound
            clean = (not unk and not ub and all((counts.get(e) or {}).get("checkable", 0) >= 1 for e in entries))
            return dict(v=PARTIAL, blank=bad, **({"clean": True} if clean else {}), measured="no blank or placeholder row among the checkable prose rows"
                        + (f" (unknown for {', '.join(unk)})" if unk else "") + "; schema defaults are read by "
                        "Null.schema_default and writer literal fallbacks and constant columns are not measured, so "
                        "this is never PASS")
    return dict(v=NO_DET, inconclusive=True,
                measured="INCONCLUSIVE: no checkable prose rows were read for the declared entries")


# ─────────────────────────── E6 S1: the declared null convention (REGISTRY_REVISION 13) ───────────────────────────
# SS N-72 S1 (verbatim): "The cap stays as the default; it LIFTS per asset only by earning it: Null reads PASS for an asset when schema_default and blank_rows
# both pass AND that asset's declared null convention (pin 13: which columns may be NULL and what NULL means; no literal fallbacks, no constant columns) is
# verified by the detector. No Null N/A rule (N-22 row 33 stands)." Design: scratchpad s1/DESIGN.md.
# An asset DECLARES `null_convention` (validated here, asset_declarations.json 1.9.0): the table, its nullable columns (each with what NULL means and an
# optional key scope), its declared constant columns, optional `allowed_literals` (a value that looks like a placeholder but is a real value of a NON-nullable
# column, with a reason), a real one-line why and a checkable evidence pointer. The detector verifies it read-only. The cap is never lifted by a column pattern, a
# NOT NULL constraint, a clean populated table or a record's own say-so: `null_lift_earned` re-checks the evidence on BOTH Null records. An undeclared asset reads
# exactly as before.
# "No literal fallbacks" has ONE definition, S3's: the same normaliser and closed list (`_ldgr_lacking_text` / LDGR_PLACEHOLDERS: NFKC, invisible characters removed,
# junk punctuation stripped at the ends, case folded: 'N/A.', 'Ｎ/Ａ', 'n<ZWSP>/a', '—', '0', 'pending', 'missing', 'not found' ...) is applied to EVERY text-like
# column of the declared table (text / varchar / char / citext, element-wise on arrays, a JSON string or an empty JSON container), not only to the declared-nullable
# ones: a non-nullable column holding '' or 'N/A' is a fallback dodging the undeclared-NULL check. A value that collides with the list legitimately must be declared
# in `allowed_literals` (never guessed by the detector). A declared-nullable NUMERIC column also treats a 0 as a sentinel.
# COST NOTE: `count(DISTINCT col)` over a very large or vector-heavy table can hit the client timeout (PSQL_TIMEOUT_SECONDS): that reads ERRORED, never PASS. Columns of
# KIND json, blob (bytea / tsvector / tsquery / xml / vector ...) or array_num (numeric / float arrays, e.g. embeddings) are therefore NOT distinct-counted unless declared constant;
# the verdict names them as not examined. An array whose ELEMENT contents are not inspected (kind array_other: jsonb[], composite[], inet[], bytea[], uuid[], date[] ...) gets only the
# empty-array fallback test, so it is NOT counted in the "no literal fallback in the N column(s) checked" claim: it is listed under "NOT examined (element contents not inspected)".
NULL_CONVENTION_DECL_FIELDS = ("table", "nullable", "constants", "stamp_columns", "allowed_literals", "why", "evidence")
NULL_STAMP_FIELDS = ("column", "why")
NULL_MAX_STAMPS = 16
NULL_STAMP_TYPES = ("timestamp", "timestamptz")     # pg_type names (domains resolved): `date`, `time`, text and everything else is NOT a write-time stamp
NULL_NULLABLE_FIELDS = ("column", "means", "scope")
NULL_SCOPE_FIELDS = ("key_column", "null_for", "mode")
NULL_CONSTANT_FIELDS = ("column", "why", "value")
NULL_ALLOWED_FIELDS = ("column", "values", "why")
NULL_SCOPE_MODES = ("only", "exactly")        # only: a NULL is allowed just on the declared keys; exactly: NULL iff the key is declared
NULL_MAX_NULLABLE, NULL_MAX_CONSTANTS, NULL_MAX_ALLOWED, NULL_MAX_VALUES, NULL_MAX_KEY_LEN = 64, 256, 64, 20, 128   # a declaration larger than this is not a convention
NULL_NUMERIC_TYPES = ("smallint", "integer", "bigint", "numeric", "decimal", "real", "double precision")   # a 0 in a declared-nullable numeric column is a sentinel
NULL_ALLOWED_EFFECT_KINDS = ("text", "array_text", "json")   # the kinds `_null_fallback_sql` applies allowed_literals to; on any other kind an entry has no effect
NULL_DISTINCT_SKIP_KINDS = ("json", "blob", "array_num")   # kinds not distinct-counted (cost: json, bytea / tsvector / vector, numeric / float arrays such as embeddings) unless declared constant


def _s3_key_problem(v, limit: int = NULL_MAX_KEY_LEN):
    """None when `v` is a safe literal for a declared key value / allowed literal: a non-empty str of at most `limit` characters, no leading/trailing whitespace, no
    control / format / line-separator character (U+2028 ...), no backslash."""
    if not (isinstance(v, str) and v):
        return "is not a non-empty string"
    if v != v.strip() or len(v) > limit:
        return f"has leading or trailing whitespace or is longer than {limit} characters"
    if any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") or ch == "\\" for ch in v):
        return "contains a control, format, line-separator character or a backslash"
    return None


def _null_placeholder_text(v: str) -> bool:
    """True when `v` (a declared meaning) is itself a placeholder of S3's list, with or without surrounding punctuation: '', '-', 'N/A', 'none.', 'Unknown'."""
    flat = re.sub(r"\s+", " ", v.strip()).casefold()
    core = re.sub(r"^[\W_]+|[\W_]+$", "", flat)
    return flat in LDGR_PLACEHOLDERS or core in LDGR_PLACEHOLDERS


def _validate_stamp_columns(where: str, nc: dict, e: dict) -> list:
    """The declared `stamp_columns` of a null_convention, validated (the declaration shape only: the validator has no database, so whether a column IS a NOT NULL timestamp is the
    detector's question, refused at measure time). Optional; a list of at most NULL_MAX_STAMPS {column, why} entries: `column` an identifier, `why` a real one-line reason (S1's text
    rule), no duplicate, and never a column the asset declares as a prose field (a stamp is not narration). Returns the column names in declared order."""
    st = nc.get("stamp_columns")
    if st is None and "stamp_columns" not in nc:
        return []
    if not isinstance(st, list):
        raise DeclarationsError(f"{where}.null_convention.stamp_columns must be a list (omit the key when the table declares none)")
    if len(st) > NULL_MAX_STAMPS:
        raise DeclarationsError(f"{where}.null_convention.stamp_columns declares more than {NULL_MAX_STAMPS} columns: not a convention")
    prose = set()
    for p in (e.get("prose_fields") if isinstance(e, dict) else None) or []:
        try:
            prose.add(parse_prose_field(p)[0])
        except DeclarationsError:
            continue
    cols = []
    for i, c in enumerate(st):
        w = f"{where}.null_convention.stamp_columns[{i}]"
        if not isinstance(c, dict):
            raise DeclarationsError(f"{where}.null_convention stamp_columns entry {i} must be an object")
        extra = sorted(set(c) - set(NULL_STAMP_FIELDS))
        if extra:
            raise DeclarationsError(f"{w}: unknown field(s) {extra}")
        _s3_ident(where, "null_convention", f"stamp_columns[{i}].column", c.get("column"))
        bad = _s3_text_problem(c.get("why"), min_chars=15, min_words=3)
        if bad:
            raise DeclarationsError(f"{w}.why {bad} (why this column is a write-time stamp)")
        if c["column"] in cols:
            raise DeclarationsError(f"{w}.column {c['column']!r} is declared twice (duplicate)")
        if c["column"] in prose:
            raise DeclarationsError(f"{w}.column {c['column']!r} is also a declared prose field: a write-time stamp is not narration")
        cols.append(c["column"])
    return cols


# ZERO-ROW CONVENTION (SS N-149; the same declared-convention shape as null_convention): a writer-backed asset whose table is LEGITIMATELY empty for
# some charts declares WHEN: `scope_table.scope_column` holds the charts the asset produces rows for, and a chart absent from it has no rows by design
# (ga_prashna: a natal chart is not in prashna_charts, and the writer returns 0 rows for it, ga_prashna_writer.py:134). The census VERIFIES the
# declared condition against the live scope table for the chart it measures; it never takes the declaration as the answer.
ZERO_ROW_DECL_FIELDS = ("scope_table", "scope_column", "applies_when", "why", "evidence")
ZERO_ROW_APPLIES = ("chart_absent",)


def validate_zero_row_convention_declaration(where: str, zr, e: dict) -> None:
    """Raises DeclarationsError when an asset's `zero_row_convention` is malformed: `scope_table` and `scope_column` (identifiers), `applies_when` (one of
    ZERO_ROW_APPLIES: `chart_absent` = the measured chart has no row in scope_table.scope_column), `why` (a real reason) and `evidence` (a real repo file
    pointer: `unverified:` is refused, the convention releases a verdict)."""
    if not isinstance(zr, dict):
        raise DeclarationsError(f"{where}.zero_row_convention must be an object or null")
    _s3_common(where, "zero_row_convention", zr, ZERO_ROW_DECL_FIELDS, na=True)
    _s3_ident(where, "zero_row_convention", "scope_table", zr.get("scope_table"))
    _s3_ident(where, "zero_row_convention", "scope_column", zr.get("scope_column"))
    if zr.get("applies_when") not in ZERO_ROW_APPLIES:
        raise DeclarationsError(f"{where}.zero_row_convention.applies_when must be one of {list(ZERO_ROW_APPLIES)}, got {zr.get('applies_when')!r}")


# STATIC DATA (SS 2026-10-05 R-d, second ruling): a migration-seeded static asset (declared kind static, has_writer false) names the OWNING MIGRATIONS in its declaration; the census checks that those
# migration files exist on main and reference the asset's table. A registry SEED row alone is not ownership. Only then does Build.dag check the declared edge for existence and acyclicity only, and
# Build.dep_liveness read N/A (static-data-existence-only).
STATIC_DATA_DECL_FIELDS = ("migrations", "table", "why", "evidence")
STATIC_MIGRATION_DIR = "platform/supabase/migrations"
STATIC_MAX_MIGRATIONS = 8
_STATIC_MIGRATION_NAME = re.compile(r"[0-9]{1,5}_[A-Za-z0-9_]+\.sql")


def validate_static_data_declaration(where: str, sd, e: dict) -> None:
    """Raises DeclarationsError when an asset's `static_data` is malformed: `migrations` (1 to STATIC_MAX_MIGRATIONS distinct file names `NNN_name.sql`, relative to STATIC_MIGRATION_DIR), `table` (an
    identifier: the table the migrations seed), `why` (a real reason) and `evidence` (a real repo file pointer; `unverified:` is refused). It is only for an asset that declares kind `static` and
    `has_writer: false`: a writer-built asset (or a service, or an undeclared kind) cannot claim it."""
    if not isinstance(sd, dict):
        raise DeclarationsError(f"{where}.static_data must be an object or null")
    _s3_common(where, "static_data", sd, STATIC_DATA_DECL_FIELDS, na=True)
    _s3_ident(where, "static_data", "table", sd.get("table"))
    mig = sd.get("migrations")
    if not (isinstance(mig, list) and 1 <= len(mig) <= STATIC_MAX_MIGRATIONS and len(set(mig)) == len(mig) and all(isinstance(m, str) and _STATIC_MIGRATION_NAME.fullmatch(m) for m in mig)):
        raise DeclarationsError(f"{where}.static_data.migrations must name 1 to {STATIC_MAX_MIGRATIONS} distinct migration files `NNN_name.sql` (it names no migration, or a malformed one): {mig!r}")
    if e.get("kind") != "static" or e.get("has_writer") is not False:
        raise DeclarationsError(f"{where}.static_data is for migration-seeded static data only: the asset must declare kind 'static' and has_writer false (a writer-built asset or a service cannot claim it)")


def static_data_check(sd, read_file, own_tables=None) -> dict:
    """The CHECKED half of a `static_data` declaration (pure over `read_file(path) -> text | None`, which reads a file at main): the declared table must be one of the asset's own tables
    (`own_tables`: its registry target_table and the tables its count_sql reads; None = not checked, for the pure unit tests only), and every named migration must exist under
    STATIC_MIGRATION_DIR and, after the SQL comments are blanked, hold a `CREATE TABLE [IF NOT EXISTS] [public.]<table>`, `INSERT INTO [public.]<table>` or `UPDATE [public.]<table>` statement
    (a comment (nested ones included), a string literal or dollar-quoted body (`DO $$ ... $$`), a `DROP TABLE`, a SELECT, a table of another schema or a name that merely contains it does not count); AT LEAST ONE of them must create or seed it (CREATE TABLE / INSERT INTO):
    the others may repair its rows (migrations 630 / 631 UPDATE bg_gochara_citation_resolution). `ok` only when all pass; `problems` names each failure; `files` lists what was read.
    Never raises."""
    problems, files = [], []
    if not (isinstance(sd, dict) and isinstance(sd.get("migrations"), list) and sd["migrations"] and isinstance(sd.get("table"), str)):
        return dict(ok=False, problems=["the declaration names no migration or no table"], files=[])
    if own_tables is not None and sd["table"] not in set(own_tables):
        return dict(ok=False, problems=[f"the declared table {sd['table']} is not the asset's own table (registry target_table / count_sql tables: {sorted(own_tables) or 'none'})"], files=[])
    tbl = re.escape(sd["table"])
    tail = r"(?:public\.)?\"?" + tbl + r"\"?(?![A-Za-z0-9_$.])"
    creates = re.compile(r"\bCREATE\s+(?:UNLOGGED\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?" + tail + r"|\bINSERT\s+INTO\s+" + tail, re.I)     # creates or seeds it
    repairs = re.compile(r"\bUPDATE\s+(?:ONLY\s+)?" + tail, re.I)                                                                           # corrects its rows
    seeded = False
    wls = _lint_module("writer_literal_scan")

    def blank(txt: str) -> str:                         # comments first (they nest), then string literals and dollar-quoted bodies: a keyword that only appears inside TEXT is not a statement
        return wls.blank_sql_literals(wls.blank_sql_comments(txt))
    for name in sd["migrations"]:
        path = f"{STATIC_MIGRATION_DIR}/{name}"
        try:
            txt = read_file(path)
        except Exception as exc:                       # noqa: BLE001 -- an unreadable ref is a failed check, never an exception out of measure()
            problems.append(f"{path}: could not be read on main ({type(exc).__name__}: {' '.join(str(exc).split())[:100]})")
            continue
        if txt is None:
            problems.append(f"{path}: does not exist on main")
        else:
            body = blank(txt)
            if creates.search(body):
                seeded = True
                files.append(path)
            elif repairs.search(body):
                files.append(path)
            else:
                problems.append(f"{path}: exists but has no CREATE TABLE / INSERT INTO / UPDATE statement for {sd['table']} (a comment, a DROP, a SELECT, another schema's table or a longer name does not count)")
    if not problems and not seeded:
        problems.append(f"no named migration creates or seeds {sd['table']} (CREATE TABLE / INSERT INTO): UPDATE statements alone do not own a table")
    return dict(ok=not problems, problems=problems, files=files)


# PROBE ATTEMPTS (SS 2026-10-05): a writer-less SERVICE whose health probe was run by the orchestrator names those (asset, run) pairs. The engine's probe-green row is state `complete` with NO
# disposition and a provenance receipt (build_id = the run, output_digest_spec_sha256 NULL, receipt_state unknown); the census checks each named run still has exactly that shape in the live
# build_run_assets / asset_provenance_receipts rows, and that the asset has NO other build_run_assets row. Then Earn.build_record reads N/A by a checked declaration.
PROBE_ATTEMPTS_DECL_FIELDS = ("attempts", "why", "evidence")
PROBE_MAX_ATTEMPTS = 1          # receipts are upserted per (asset, scope, partition): only the LATEST survives, so a second named run's receipt cannot be verified
_UUID_LOWER = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")


def validate_probe_attempts_declaration(where: str, pa, e: dict) -> None:
    """Raises DeclarationsError when an asset's `probe_attempts` is malformed: `attempts` 1 to PROBE_MAX_ATTEMPTS distinct objects `{run_id}` (a lower-case uuid), `why` (a real reason) and
    `evidence` (a real repo file pointer; `unverified:` refused). Only an asset that declares kind `service` AND `has_writer: false` may declare it: a writer-backed asset (or any other kind)
    has builds, not probes, and is refused."""
    if not isinstance(pa, dict):
        raise DeclarationsError(f"{where}.probe_attempts must be an object or null")
    _s3_common(where, "probe_attempts", pa, PROBE_ATTEMPTS_DECL_FIELDS, na=True)
    at = pa.get("attempts")
    ok = (isinstance(at, list) and 1 <= len(at) <= PROBE_MAX_ATTEMPTS and all(isinstance(x, dict) and set(x) == {"run_id"} and isinstance(x["run_id"], str) and _UUID_LOWER.fullmatch(x["run_id"]) for x in at)
          and len({x["run_id"] for x in at}) == len(at))
    if not ok:
        raise DeclarationsError(f"{where}.probe_attempts.attempts must be 1 to {PROBE_MAX_ATTEMPTS} distinct objects {{run_id: <lower-case uuid>}}, got {at!r}")
    if e.get("kind") != "service" or e.get("has_writer") is not False:
        raise DeclarationsError(f"{where}.probe_attempts is for a writer-less service only: the asset must declare kind 'service' and has_writer false (a writer-backed asset has builds, not probes)")


def probe_attempt_rows(asset_id: str) -> tuple[list[dict], list[dict]]:
    """(rows, receipts) of one asset, read-only and census-written: EVERY build_run_assets row (run_id, state, disposition, started, the run's created_at epoch) and EVERY
    asset_provenance_receipts row (build_id, output_digest_spec_sha256 IS NULL, receipt_state). Receipts are upserted on (asset_id, scope_key, partition_key), so only the LATEST receipt
    of a scope survives. Raises Unknown on a failed or ragged read; the asset id must be a plain registry id."""
    if not _ASSET_ID.fullmatch(asset_id):
        raise Unknown(f"probe_attempt_rows: {asset_id!r} is not a plain asset id")
    raw_rows = psql("SELECT a.run_id::text, coalesce(a.state,''), coalesce(a.disposition,''), (a.started_at IS NOT NULL)::text, coalesce(extract(epoch FROM r.created_at)::text,'') "
                    f"FROM build_run_assets a JOIN build_runs r ON r.id = a.run_id WHERE a.asset_id = '{asset_id}' ORDER BY r.created_at, a.run_id")
    raw_rc = psql(f"SELECT coalesce(p.build_id::text,''), (p.output_digest_spec_sha256 IS NULL)::text, coalesce(p.receipt_state,'') FROM asset_provenance_receipts p WHERE p.asset_id = '{asset_id}'")
    if any(len(r) != 5 for r in raw_rows) or any(len(r) != 3 for r in raw_rc):
        raise Unknown("probe_attempt_rows: a row did not parse into the selected fields (5 for build_run_assets, 3 for receipts): the rows are not read")
    rows = [dict(run_id=r[0], state=r[1], disposition=r[2], started=(r[3] in ("t", "true")), created_epoch=_epoch(r[4])) for r in raw_rows]
    rc = [dict(build_id=r[0], spec_null=(r[1] in ("t", "true")), receipt_state=r[2]) for r in raw_rc]
    return rows, rc


def _probe_receipt_ok(x: dict) -> bool:
    return bool(x.get("spec_null")) and x.get("receipt_state") == "unknown"


def grade_probe_attempts(pa: dict, rows, receipts, block: dict, registry_kind) -> dict | None:
    """The checked reading of a `probe_attempts` declaration against the live rows (pure). None = the declaration does not apply (no agreeing no-writer block). Otherwise a record.

    A build_run_assets row is NON-PROBE when its disposition is not empty, its state is not `complete`, or a receipt that names it is not the probe shape (output_digest_spec_sha256 NULL and
    receipt_state unknown). A LATER orchestrated probe is not a contradiction (SS: any other NON-PROBE row fails, not any other row): an extra row that is complete with an empty disposition is
    tolerated when its own receipt is probe-shaped, or when it has none because a probe-shaped receipt of an equal-or-newer run overwrote it (receipts are upserted: only the latest survives).
      NO_DETECTOR  the registry asset_kind is not `service`; the rows could not be read; or a named run's own receipt is gone, overwritten by a NEWER probe-shaped receipt: the evidence was
                   destroyed, not contradicted, and nothing else can verify the run (a pre-disposition completion could be a build), so it is not released;
      FAIL         a named run is absent; a named run that is non-probe; a named run with no receipt and no newer probe receipt to explain it; ANY non-probe extra row; an extra complete row
                   with no receipt that no newer probe-shaped receipt could have overwritten;
      N/A          every named run has ALL its receipts probe-shaped (at least one) and every other row is a tolerated probe: `declared probe runs verified against live rows`."""
    agree = bool(block.get("declared")) and block.get("registry_has_writer") is False and block.get("register_files") == 0 and block.get("register_mentions") == []
    if not agree:
        return None
    base = dict(block, probe_attempts=True)
    if registry_kind != "service":
        return dict(v=NO_DET, no_writer=dict(base, verified=False), measured=f"NO_DETECTOR — probe_attempts is declared but the registry asset_kind is {registry_kind or 'unset'}, not `service`: a probe declaration needs a "
                                                                                 "writer-less service, so it establishes nothing")
    if rows is None:
        return dict(v=NO_DET, no_writer=dict(base, verified=False), measured="NO_DETECTOR — probe_attempts is declared but the asset's build_run_assets / receipt rows could not be read: the named runs are not verified")
    named = [x["run_id"] for x in pa["attempts"]]
    by = {r["run_id"]: r for r in rows}
    rc: dict[str, list] = {}
    for x in receipts or []:
        rc.setdefault(x["build_id"], []).append(x)

    def epoch_of(run):
        e = (by.get(run) or {}).get("created_epoch")
        return e if isinstance(e, (int, float)) and e != float("-inf") else None

    def newer_probe_receipt(row) -> bool:
        """a probe-shaped receipt names a run created at or after `row`'s creation, other than the row itself (it could have overwritten the row's receipt)"""
        e = epoch_of(row["run_id"])
        for build, xs in rc.items():
            if build != row["run_id"] and build in by and all(_probe_receipt_ok(x) for x in xs) and e is not None and (epoch_of(build) or float("-inf")) >= e:
                return True
        return False

    def nonprobe(row) -> list[str]:
        bad = []
        if row["state"] != "complete":
            bad.append(f"state is '{row['state']}', not complete")
        if row["disposition"] != "":
            bad.append(f"disposition is '{row['disposition']}', not empty")
        if any(not _probe_receipt_ok(x) for x in rc.get(row["run_id"], [])):
            bad.append("its receipt is not the probe shape (output_digest_spec_sha256 NULL and receipt_state unknown)")
        return bad

    fails, destroyed, tolerated = [], [], []
    for run in named:
        row = by.get(run)
        if row is None:
            fails.append(f"named run {run[:8]} is ABSENT from the asset's build_run_assets rows (the declared probe is not on record)")
            continue
        bad = nonprobe(row)
        if bad:
            fails.append(f"named run {run[:8]} is not a probe: " + "; ".join(bad))
        elif not rc.get(run):
            if newer_probe_receipt(row):
                destroyed.append(f"named run {run[:8]}'s own receipt is gone: a NEWER probe-shaped receipt overwrote it (receipts are upserted, only the latest survives), so the declared probe cannot be verified")
            else:
                fails.append(f"named run {run[:8]} has no provenance receipt (and no newer probe-shaped receipt could have overwritten it)")
    for row in rows:
        if row["run_id"] in named:
            continue
        bad = nonprobe(row)
        if bad:
            fails.append(f"non-probe build_run_assets row {row['run_id'][:8]} is not named: " + "; ".join(bad))
        elif rc.get(row["run_id"]) or newer_probe_receipt(row):
            tolerated.append(row["run_id"])
        else:
            fails.append(f"build_run_assets row {row['run_id'][:8]} (complete, no disposition) is not named and has no receipt that proves it a probe (no newer probe-shaped receipt could have overwritten it)")
    if fails:
        return dict(v=FAIL, no_writer=dict(base, verified=False, runs=named), measured="declared has_writer: false service, but its declared probe runs are contradicted by the live rows: " + " | ".join(fails + destroyed))
    if destroyed:
        return dict(v=NO_DET, no_writer=dict(base, verified=False, runs=named), measured="NO_DETECTOR — " + " | ".join(destroyed) + ": the evidence was destroyed by design, not contradicted")
    later = (f"; {len(tolerated)} later probe-shaped run(s) tolerated (a later orchestrated probe is not a contradiction)" if tolerated else "")
    return dict(_na("no build record applies: declared probe runs verified against live rows (" + ", ".join(f"{r[:8]} complete, no disposition, every receipt of the run has no output-digest spec and state unknown" for r in named)
                    + f"); every other build_run_assets row is a probe{later} ({len(rows)} row(s) in all)", "declared-probe-runs-verified"), no_writer=dict(base, verified=True, runs=named, service=True, tolerated_probe_runs=len(tolerated)))


def zero_row_convention_outcome(zr: dict, chart_id: str) -> dict:
    """Verify a declared zero-row convention for `chart_id` against the live scope table (two census-written read-only SELECTs over validated
    identifiers; nothing here is registry-stored text). `state`: `holds` (the chart is absent from scope_table.scope_column: zero rows is the declared
    by-design reading), `does_not_hold` (the chart IS in it: the asset should have produced rows, so zero is a defect), `unverified` (table/column
    missing or a read failed: never read as holding). Never raises."""
    t, c = zr["scope_table"], zr["scope_column"]
    where = f"{t}.{c}"
    try:
        have = psql("SELECT count(*)::text FROM information_schema.columns WHERE table_schema='public' "
                    f"AND table_name='{t}' AND column_name='{c}'")
        if not have or have[0][0] != "1":
            return dict(state="unverified", detail=f"{where} does not exist in this database, so the declared condition cannot be read")
        rows = psql(f'SELECT (NOT EXISTS (SELECT 1 FROM "{t}" WHERE "{c}"::text = \'{chart_id}\'))::text')
    except Unknown as exc:
        return dict(state="unverified", detail=f"the read of {where} failed: {' '.join(str(exc).split())[:160]}")
    v = rows[0][0] if rows and rows[0] else ""
    if v in ("t", "true"):
        return dict(state="holds", detail=f"chart {chart_id[:8]} has no row in {where}")
    if v in ("f", "false"):
        return dict(state="does_not_hold", detail=f"chart {chart_id[:8]} IS in {where}")
    return dict(state="unverified", detail=f"the read of {where} returned {v!r}")


def validate_null_convention_declaration(where: str, nc, e: dict) -> None:
    """Raises DeclarationsError when an asset's `null_convention` declaration is malformed: `table` (an identifier), `nullable` and `constants` (lists, empty
    when none), optional `allowed_literals`, `why` (a real one-line reason) and `evidence` (a checkable pointer). A nullable entry names its column, what NULL means
    (a real statement, not itself a fallback literal) and optionally a key `scope` (key_column, null_for, mode); a constant entry names its column, a real reason and
    optionally its `value`; an allowed-literals entry names a NON-nullable column, the literals that are real values of it and a real reason. List lengths are capped."""
    if not isinstance(nc, dict):
        raise DeclarationsError(f"{where}.null_convention must be an object or null")
    _s3_common(where, "null_convention", nc, NULL_CONVENTION_DECL_FIELDS, na=False)   # no N/A form exists for Null: an `unverified:` evidence pointer is allowed here as for the non-N/A S3 keys
    _s3_ident(where, "null_convention", "table", nc.get("table"))
    for key in ("nullable", "constants"):
        if not isinstance(nc.get(key), list):
            raise DeclarationsError(f"{where}.null_convention.{key} must be a list (empty when the table declares none)")
    if len(nc["nullable"]) > NULL_MAX_NULLABLE or len(nc["constants"]) > NULL_MAX_CONSTANTS:
        raise DeclarationsError(f"{where}.null_convention declares more than {NULL_MAX_NULLABLE} nullable or {NULL_MAX_CONSTANTS} constant columns: not a convention")
    n_cols, k_cols = [], []
    for i, n in enumerate(nc["nullable"]):
        w = f"{where}.null_convention.nullable[{i}]"
        if not isinstance(n, dict):
            raise DeclarationsError(f"{where}.null_convention nullable entry {i} must be an object")
        extra = sorted(set(n) - set(NULL_NULLABLE_FIELDS))
        if extra:
            raise DeclarationsError(f"{w}: unknown field(s) {extra}")
        _s3_ident(where, "null_convention", f"nullable[{i}].column", n.get("column"))
        if isinstance(n.get("means"), str) and _null_placeholder_text(n["means"]):
            raise DeclarationsError(f"{w}.means {n['means']!r} is a fallback literal, not a meaning: say what a NULL in this column states")
        bad = _s3_text_problem(n.get("means"), min_chars=15, min_words=3)
        if bad:
            raise DeclarationsError(f"{w}.means {bad} (what NULL means in this column)")
        if n["column"] in n_cols:
            raise DeclarationsError(f"{w}.column {n['column']!r} is declared twice (duplicate)")
        n_cols.append(n["column"])
        sc = n.get("scope")
        if sc is None:
            continue
        if not isinstance(sc, dict):
            raise DeclarationsError(f"{w}.scope must be an object or null")
        extra = sorted(set(sc) - set(NULL_SCOPE_FIELDS))
        if extra:
            raise DeclarationsError(f"{w}.scope: unknown field(s) {extra}")
        _s3_ident(where, "null_convention", f"nullable[{i}].scope.key_column", sc.get("key_column"))
        if sc["key_column"] == n["column"]:
            raise DeclarationsError(f"{w}.scope.key_column must differ from the nullable column itself")
        if sc.get("mode") not in NULL_SCOPE_MODES:
            raise DeclarationsError(f"{w}.scope.mode must be one of {list(NULL_SCOPE_MODES)}, got {sc.get('mode')!r}")
        nf = sc.get("null_for")
        if not (isinstance(nf, list) and nf):
            raise DeclarationsError(f"{w}.scope.null_for must be a non-empty list of key values")
        if len(nf) > NULL_MAX_VALUES * 5:
            raise DeclarationsError(f"{w}.scope.null_for lists more than {NULL_MAX_VALUES * 5} keys: not a convention")
        for v in nf:
            bad = _s3_key_problem(v)
            if bad:
                raise DeclarationsError(f"{w}.scope.null_for entry {v!r} {bad}")
        if len(set(nf)) != len(nf):
            raise DeclarationsError(f"{w}.scope.null_for lists a key twice (duplicate)")
        k_cols.append(sc["key_column"])
    c_cols = []
    for i, c in enumerate(nc["constants"]):
        w = f"{where}.null_convention.constants[{i}]"
        if not isinstance(c, dict):
            raise DeclarationsError(f"{where}.null_convention constants entry {i} must be an object")
        extra = sorted(set(c) - set(NULL_CONSTANT_FIELDS))
        if extra:
            raise DeclarationsError(f"{w}: unknown field(s) {extra}")
        _s3_ident(where, "null_convention", f"constants[{i}].column", c.get("column"))
        bad = _s3_text_problem(c.get("why"), min_chars=15, min_words=3)
        if bad:
            raise DeclarationsError(f"{w}.why {bad} (why this column is constant)")
        if c.get("value") is not None and not (isinstance(c["value"], str) and c["value"] != "" and len(c["value"]) <= 4000 and "\x00" not in c["value"]):
            raise DeclarationsError(f"{w}.value must be a non-empty string (the constant's text form) when present")
        if c["column"] in c_cols:
            raise DeclarationsError(f"{w}.column {c['column']!r} is declared twice (duplicate)")
        c_cols.append(c["column"])
    s_cols = _validate_stamp_columns(where, nc, e)
    both = sorted(set(n_cols) & set(c_cols))
    if both:
        raise DeclarationsError(f"{where}.null_convention: {both} are both nullable and constant (a column that is NULL on every row is a dead column, not a convention)")
    both = sorted(set(s_cols) & (set(n_cols) | set(c_cols)))
    if both:
        raise DeclarationsError(f"{where}.null_convention: {both} are declared as a stamp column AND as nullable or constant: a stamp column is NOT NULL and exempt from the constant test only; "
                                "it cannot also be one of the other two words")
    bad = sorted((set(k_cols) & set(c_cols)) | (set(k_cols) & set(n_cols)) | (set(k_cols) & set(s_cols)))
    if bad:
        raise DeclarationsError(f"{where}.null_convention: {bad} are used as a scope key_column, which must be a non-NULL identity (neither nullable, constant nor a stamp column)")
    al = nc.get("allowed_literals")
    if al is None:
        al = []
    if not isinstance(al, list) or len(al) > NULL_MAX_ALLOWED:
        raise DeclarationsError(f"{where}.null_convention.allowed_literals must be a list of at most {NULL_MAX_ALLOWED} entries")
    a_cols = []
    for i, a in enumerate(al):
        w = f"{where}.null_convention.allowed_literals[{i}]"
        if not isinstance(a, dict):
            raise DeclarationsError(f"{where}.null_convention allowed_literals entry {i} must be an object")
        extra = sorted(set(a) - set(NULL_ALLOWED_FIELDS))
        if extra:
            raise DeclarationsError(f"{w}: unknown field(s) {extra}")
        _s3_ident(where, "null_convention", f"allowed_literals[{i}].column", a.get("column"))
        vals = a.get("values")
        if not (isinstance(vals, list) and vals) or len(vals) > NULL_MAX_VALUES:
            raise DeclarationsError(f"{w}.values must be a non-empty list of at most {NULL_MAX_VALUES} literals")
        for v in vals:
            bad = _s3_key_problem(v)
            if bad:
                raise DeclarationsError(f"{w}.values entry {v!r} {bad}")
        if len(set(vals)) != len(vals):
            raise DeclarationsError(f"{w}.values lists a literal twice (duplicate)")
        bad = _s3_text_problem(a.get("why"), min_chars=15, min_words=3)
        if bad:
            raise DeclarationsError(f"{w}.why {bad} (why this literal is a real value of the column)")
        if a["column"] in a_cols:
            raise DeclarationsError(f"{w}.column {a['column']!r} is declared twice (duplicate)")
        a_cols.append(a["column"])
    if set(a_cols) & set(s_cols):
        raise DeclarationsError(f"{where}.null_convention: {sorted(set(a_cols) & set(s_cols))} are stamp columns (a timestamp, checked for infinity, -infinity or a value at or before epoch + 1 day instead): an allowed literal there has no meaning")
    if set(a_cols) & set(n_cols):
        raise DeclarationsError(f"{where}.null_convention: {sorted(set(a_cols) & set(n_cols))} are nullable, where NULL is the only way to say 'absent': an allowed literal there is the fallback itself")


def _sql_lit(s) -> str:
    """A SQL string literal for a declared key value: quotes doubled; a non-string, a control character or a backslash is refused (the declaration validator
    refuses them too; this is the second lock before any text reaches SQL)."""
    if not isinstance(s, str) or any(unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") or ch == "\\" for ch in s):
        raise Unknown(f"null_convention: {s!r} is not a safe key literal")
    return "'" + s.replace("'", "''") + "'"


def _null_type_kind(t) -> str:
    """The kind of a column from its information_schema data_type STRING (the catalog read `_null_kind_from_catalog` resolves what this cannot: citext, enums, domains, array
    element types, vector): 'text' | 'num' | 'bool' | 'json' | 'array_text' | 'array_num' | 'array_bool' | 'array_other' | 'blob' | 'other'. An `ARRAY` of unknown element
    reads as array_text (conservative); USER-DEFINED / bytea / tsvector / xml read as 'blob' (heavy, no text to test)."""
    t = re.sub(r"\(.*?\)", "", str(t or "")).strip().lower()
    if t in LDGR_TEXT_TYPES:
        return "text"
    if t == "array" or t.endswith("[]"):
        base = t[:-2].strip() if t.endswith("[]") else ""
        return "array_num" if base in NULL_NUMERIC_TYPES else "array_bool" if base == "boolean" else "array_text"
    if t in ("json", "jsonb"):
        return "json"
    if t in NULL_NUMERIC_TYPES:
        return "num"
    if t == "boolean":
        return "bool"
    if t in ("bytea", "tsvector", "user-defined", "xml", "tsquery"):
        return "blob"
    return "other"


NULL_BLOB_TYPENAMES = ("bytea", "tsvector", "tsquery", "xml", "vector", "halfvec", "sparsevec")


def _null_kind_from_catalog(typname, cat, elem_cat) -> str:
    """The kind of a column from pg_type facts (typname and typcategory of its base type, domains resolved; for an array the element's typcategory): text = category S
    (text, varchar, bpchar, name, citext) or E (an enum: its label text is tested); num = N; bool = B; json = json / jsonb; blob = bytea / tsvector / vector ...; an array
    is array_text / array_num / array_bool / array_other by its element."""
    if cat == "A":
        return {"S": "array_text", "E": "array_text", "N": "array_num", "B": "array_bool"}.get(elem_cat, "array_other")
    if typname in ("json", "jsonb"):
        return "json"
    if typname in NULL_BLOB_TYPENAMES:
        return "blob"
    return {"S": "text", "E": "text", "N": "num", "B": "bool"}.get(cat, "other")


def pg_column_type_facts(table: str, columns=None) -> dict:
    """{column: {t, c, ec, et}} for the table from ONE read-only pg_catalog SELECT (answered as one line of jsonb): `t` / `c` are the pg_type name and typcategory of the column's BASE
    type (a domain resolved to its base type), `ec` / `et` the typcategory and type name of an array's ELEMENT. The ONE catalog read behind the Null detector's column kinds
    (`null_fetch_column_kinds`) and the Carr column ledger (`carriage_fetch_column_types`): information_schema.data_type is not used, it reports USER-DEFINED for an enum, citext
    and a domain over citext. `columns` None = every column of the table; a list = those columns, and the catalog must answer for each of them. Identifiers are matched against
    a strict pattern. Raises Unknown on a malformed identifier, a failed read, or a requested column the catalog does not answer for."""
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table)):
        raise Unknown(f"pg_column_type_facts: malformed table {table!r}")
    blob = scalar("SELECT coalesce(jsonb_object_agg(a.attname, jsonb_build_object('t', bt.typname, 'c', bt.typcategory, 'ec', et.typcategory, 'et', et.typname)), '{}'::jsonb)::text "
                  "FROM pg_attribute a JOIN pg_type t ON t.oid = a.atttypid "
                  "JOIN pg_type bt ON bt.oid = CASE WHEN t.typtype = 'd' THEN t.typbasetype ELSE t.oid END "
                  "LEFT JOIN pg_type et ON et.oid = CASE WHEN bt.typcategory = 'A' THEN bt.typelem END "
                  f"WHERE a.attrelid = to_regclass('\"{table}\"') AND a.attnum > 0 AND NOT a.attisdropped")
    try:
        got = json.loads(blob or "")
    except (json.JSONDecodeError, TypeError) as exc:
        raise Unknown(f"pg_column_type_facts: unparseable read of {table}: {exc}") from exc
    if not isinstance(got, dict) or not got:
        raise Unknown(f"pg_column_type_facts: the catalog returned no column of {table}")
    if columns is not None and not all(isinstance(got.get(c), dict) for c in columns):
        raise Unknown(f"pg_column_type_facts: the catalog does not answer for every column of {table}")
    return {c: got[c] for c in (got if columns is None else columns)}


def null_fetch_column_kinds(table: str, columns) -> dict:
    """{column: kind} for the declared table: `pg_column_type_facts` (ONE read-only pg_catalog SELECT; a domain is resolved to its base type, an array to its element's category)
    turned into the Null detector's kinds. Raises Unknown on a malformed identifier, a failed read, or a column the catalog does not answer for."""
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table)):
        raise Unknown(f"null_fetch_column_kinds: malformed table {table!r}")
    try:
        got = pg_column_type_facts(table, list(columns))
    except Unknown as exc:
        raise Unknown(str(exc).replace("pg_column_type_facts", "null_fetch_column_kinds")) from exc
    return {c: _null_kind_from_catalog(got[c].get("t"), got[c].get("c"), got[c].get("ec")) for c in columns}


def null_fetch_stamp_facts(table: str, columns) -> dict:
    """{column: {type, notnull}} for the declared STAMP columns of `table` from ONE read-only pg_catalog SELECT (answered as one line of jsonb): `type` is the pg_type name of the
    column's base type (a domain resolved to its base: timestamp / timestamptz are the only stamp types), `notnull` is true when the catalog itself guarantees the column non-NULL
    (attnotnull, or a domain declared NOT NULL). Issued only for an asset that declares stamp_columns. Raises Unknown on a malformed identifier, a failed read, or a column the
    catalog does not answer for (never a guess)."""
    cols = list(columns or ())
    if not (isinstance(table, str) and _D1_SQL_IDENT.fullmatch(table)) or not all(isinstance(c, str) and _D1_SQL_IDENT.fullmatch(c) for c in cols):
        raise Unknown(f"null_fetch_stamp_facts: malformed identifier(s) {[table] + cols!r}")
    blob = scalar("SELECT coalesce(jsonb_object_agg(a.attname, jsonb_build_object('t', bt.typname, 'nn', (a.attnotnull OR t.typnotnull))), '{}'::jsonb)::text "
                  "FROM pg_attribute a JOIN pg_type t ON t.oid = a.atttypid "
                  "JOIN pg_type bt ON bt.oid = CASE WHEN t.typtype = 'd' THEN t.typbasetype ELSE t.oid END "
                  f"WHERE a.attrelid = to_regclass('\"{table}\"') AND a.attnum > 0 AND NOT a.attisdropped")
    try:
        got = json.loads(blob or "")
    except (json.JSONDecodeError, TypeError) as exc:
        raise Unknown(f"null_fetch_stamp_facts: unparseable read of {table}: {exc}") from exc
    if not (isinstance(got, dict) and all(isinstance(got.get(c), dict) and isinstance(got[c].get("t"), str) and isinstance(got[c].get("nn"), bool) for c in cols)):
        raise Unknown(f"null_fetch_stamp_facts: the catalog does not answer for every stamp column of {table}")
    return {c: dict(type=got[c]["t"], notnull=got[c]["nn"]) for c in cols}


def _null_stamp_sentinel_sql(col: str, typname: str) -> str:
    """The SQL predicate 'this row's stamp column holds a SENTINEL timestamp': 'infinity', '-infinity', or anything at or before one day after the epoch (so 'epoch',
    1970-01-01 00:00 UTC, year 0001 and every default-ish 1970 placeholder), compared in the column's OWN type (timestamptz against the epoch as timestamptz; timestamp without time zone
    against the epoch as timestamp, never through a session-time-zone cast). A real write time is neither: this is the literal fallback of a timestamp column (a disguise a constant test
    used to catch when the stamp was undeclared). `typname` is the catalog's base type name (timestamp / timestamptz); anything else has no such predicate."""
    if typname not in NULL_STAMP_TYPES:
        raise Unknown(f"null_convention: {typname!r} is not a stamp type")
    q = f'"{col}"'
    return f"{q} = 'infinity' OR {q} = '-infinity' OR {q} <= 'epoch'::{typname} + interval '1 day'"


def _null_stamp_type_ok(data_type) -> bool:
    """True when an information_schema data_type STRING names a timestamp (with or without time zone): the early, no-SELECT screen; the catalog's pg_type name decides."""
    t = re.sub(r"\(.*?\)", "", str(data_type or "")).strip().lower()
    return t in ("timestamp without time zone", "timestamp with time zone", "timestamp", "timestamptz")


def _null_fb_possible(kind: str, nullable: bool) -> bool:
    """Can a column of this kind hold a literal fallback the detector tests? text / arrays / json always; a numeric scalar only when declared nullable (the 0 sentinel);
    boolean, dates, timestamps, uuid, enums-as-other, blobs never."""
    return kind in ("text", "json", "array_text", "array_num", "array_bool", "array_other") or (kind == "num" and nullable)


def _null_declared_columns(spec: dict) -> list:
    """Every column name the declaration refers to (nullable, constants, scope keys, allowed literals), in a stable order."""
    out = [n["column"] for n in spec.get("nullable") or []] + [c["column"] for c in spec.get("constants") or []]
    out += [n["scope"]["key_column"] for n in spec.get("nullable") or [] if n.get("scope")] + [a["column"] for a in spec.get("allowed_literals") or []]
    out += [x["column"] for x in spec.get("stamp_columns") or []]
    return list(dict.fromkeys(out))


def _null_fallback_sql(col: str, kind: str, nullable: bool, allowed=()):
    """The SQL predicate 'this row's `col` holds a literal that stands in for NULL', or None when the column kind cannot hold one (`_null_fb_possible`). text: S3's
    `_ldgr_lacking_text` (the ONE definition) on a non-NULL value. array_text: empty, or ANY element lacking (compared per element; a NULL element lacks). array_num /
    array_bool / array_other: empty; a numeric array element of 0 only when the column is declared nullable (as the scalar sentinel). json: a JSON null, an empty object or
    array, or NESTED to any depth any JSON null or string leaf that lacks ({"src":"N/A"}, ["none"], {"a":null}, [null]): the right question for a null convention is 'does any
    leaf hold a placeholder or a null'. numeric scalar: a 0 in a declared-nullable column only. A literal listed in `allowed` (declared, with a reason) is never a fallback:
    compared on the column's text for a scalar, per element for an array, per string leaf for json."""
    q = f'"{col}"'
    lits = ", ".join(_sql_lit(v) for v in allowed)
    if kind == "text":
        core = _ldgr_lacking_text(f"{q}::text")                    # ::text: an enum's label, a domain's / citext's value is tested as text (normalize() needs text)
        ok = f" AND {q}::text NOT IN ({lits})" if allowed else ""
    elif kind == "array_text":
        el = _ldgr_lacking_text("e.x") + (f" AND (e.x IS NULL OR e.x NOT IN ({lits}))" if allowed else "")
        core, ok = f"(cardinality({q}) = 0 OR EXISTS (SELECT 1 FROM unnest({q}::text[]) AS e(x) WHERE {el}))", ""
    elif kind == "array_num":
        core, ok = f"(cardinality({q}) = 0" + (f" OR EXISTS (SELECT 1 FROM unnest({q}) AS e(x) WHERE e.x = 0)" if nullable else "") + ")", ""
    elif kind in ("array_bool", "array_other"):
        core, ok = f"(cardinality({q}) = 0)", ""
    elif kind == "json":
        leaf = _ldgr_lacking_text("(l.x #>> " + chr(39) + "{}" + chr(39) + ")") + (f" AND (l.x #>> '{{}}') NOT IN ({lits})" if allowed else "")
        core = (f"({q}::jsonb IN ('{{}}'::jsonb, '[]'::jsonb) OR EXISTS (SELECT 1 FROM jsonb_path_query({q}::jsonb, 'strict $.**') AS l(x) "
                f"WHERE jsonb_typeof(l.x) = 'null' OR (jsonb_typeof(l.x) = 'string' AND {leaf})))")
        ok = ""
    elif kind == "num" and nullable:
        core, ok = f"{q} = 0", ""
    else:
        return None
    return f"{q} IS NOT NULL AND ({core}){ok}"


def null_convention_fetch(table: str, columns, types, spec: dict, tail: str = "") -> dict:
    """{rows, kinds, cols: {column: {nulls, distinct | None, [sole], [fallback], [null_outside, null_outside_keys, nonnull_inside, nonnull_inside_keys]}}} for the declared
    table: one read-only pg_catalog SELECT (`null_fetch_column_kinds`: domains, enums, citext, array element types resolved) and ONE read-only SELECT over the table (`tail` = the
    chart-scope ` WHERE ...` the caller has BOUND), answered as ONE line of jsonb. Per column: its NULL count and its distinct count (`count(DISTINCT col)` for a numeric column, so
    1 / 1.0 / 1.00 are one value; `col::text` otherwise; NOT counted for a json, bytea / tsvector / vector or numeric-array column unless declared constant: `distinct` is then
    None); for a declared constant its sole value (min); wherever the column kind can hold one (`_null_fb_possible`) the rows holding a literal fallback by S3's definition
    (see `_null_fallback_sql`); and for a scoped nullable column the NULL rows outside the declared keys and (mode exactly) the non-NULL rows on them, as counts and up to 5
    sample keys. Identifiers are matched against a strict pattern and double-quoted; key values are doubled-quote literals. Raises Unknown on a malformed identifier or a failed
    read, and on a missing column type or a malformed answer."""
    cols = list(columns or ())
    nullable = {n["column"]: n for n in (spec.get("nullable") or [])}
    consts = {c["column"]: c for c in (spec.get("constants") or [])}
    allowed = {a["column"]: list(a["values"]) for a in (spec.get("allowed_literals") or [])}
    ids = [table] + cols + [n["scope"]["key_column"] for n in nullable.values() if n.get("scope")]
    if not cols or not all(isinstance(x, str) and _D1_SQL_IDENT.fullmatch(x) for x in ids):
        raise Unknown(f"null_convention_fetch: malformed identifier(s) {ids!r}")
    types = types or {}
    if any(c not in types for c in cols):
        raise Unknown("null_convention_fetch: the data type of a column is unknown")
    kinds = null_fetch_column_kinds(table, cols)
    stamp_cols = [x["column"] for x in spec.get("stamp_columns") or []]
    stamp_facts = null_fetch_stamp_facts(table, stamp_cols) if stamp_cols else {}      # read FIRST: the sentinel counter is built only for a column the catalog says is a timestamp
    parts = []
    for c in cols:
        qc = f'"{c}"'
        kind = kinds[c]
        numeric = kind == "num"
        f = [f"'nulls', count(*) FILTER (WHERE {qc} IS NULL)"]
        if kind not in NULL_DISTINCT_SKIP_KINDS or c in consts:
            f.append(f"'distinct', count(DISTINCT {qc}{'' if numeric else '::text'})")
        else:
            f.append("'distinct', NULL")
        if c in consts:
            f.append(f"'sole', min({qc}{'' if numeric else '::text'})::text")
        if c in stamp_facts and stamp_facts[c]["type"] in NULL_STAMP_TYPES:
            f.append(f"'sentinel', count(*) FILTER (WHERE {_null_stamp_sentinel_sql(c, stamp_facts[c]['type'])})")
        n = nullable.get(c)
        pred = _null_fallback_sql(c, kind, bool(n), allowed.get(c, ()))
        if pred:
            f.append(f"'fallback', count(*) FILTER (WHERE {pred})")
        if n and n.get("scope"):
            sc = n["scope"]
            k = f'"{sc["key_column"]}"'
            ink = f"coalesce({k}::text IN ({', '.join(_sql_lit(v) for v in sc['null_for'])}), false)"
            out_w, in_w = f"{qc} IS NULL AND NOT {ink}", f"{qc} IS NOT NULL AND {ink}"
            f += [f"'null_outside', count(*) FILTER (WHERE {out_w})",
                  f"'null_outside_keys', to_jsonb(coalesce((array_agg({k}::text ORDER BY {k}::text) FILTER (WHERE {out_w}))[1:5], ARRAY[]::text[]))"]
            if sc["mode"] == "exactly":
                f += [f"'nonnull_inside', count(*) FILTER (WHERE {in_w})",
                      f"'nonnull_inside_keys', to_jsonb(coalesce((array_agg({k}::text ORDER BY {k}::text) FILTER (WHERE {in_w}))[1:5], ARRAY[]::text[]))"]
        parts.append(f"jsonb_build_object('{c}', jsonb_build_object({', '.join(f)}))")
    blob = scalar(f"SELECT jsonb_build_object('rows', count(*), 'cols', ({' || '.join(parts)}))::text FROM \"{table}\"{tail}")
    try:
        got = json.loads(blob or "")
    except (json.JSONDecodeError, TypeError) as exc:
        raise Unknown(f"null_convention_fetch: unparseable read of {table}: {exc}") from exc
    if isinstance(got, dict):
        got["kinds"] = kinds
        if stamp_cols:
            got["stamp_facts"] = stamp_facts
    return _checked_null_stats(got, table, cols, nullable, consts, types, stamp_cols)


def _isint(x) -> bool:
    return isinstance(x, int) and not isinstance(x, bool)


def _null_kinds(got, cols, types) -> dict:
    """The kind of each column for grading: the fetch's resolved `kinds` where present, else derived from the data_type strings (stats supplied without a catalog read)."""
    k = got.get("kinds") if isinstance(got, dict) else None
    return {c: (k[c] if isinstance(k, dict) and isinstance(k.get(c), str) else _null_type_kind((types or {}).get(c))) for c in cols}


def _checked_null_stats(got, table: str, cols, nullable: dict, consts: dict, types=None, stamps=()) -> dict:
    """The fetched / supplied stats, shape-checked: a malformed answer is Unknown, never a PASS on missing numbers. `distinct` is None exactly for a column whose kind is
    skipped (json / blob / numeric array) and is not declared constant; `fallback` is an int exactly where the column kind can hold a literal fallback (`_null_fb_possible`) and is
    not required for a boolean, a date, a timestamp, an enum-as-other, a blob or a non-nullable number."""
    ok = isinstance(got, dict) and _isint(got.get("rows")) and isinstance(got.get("cols"), dict)
    if ok:
        kinds = _null_kinds(got, cols, types)
        for c in cols:
            d = got["cols"].get(c)
            ok = ok and isinstance(d, dict) and _isint(d.get("nulls"))
            skipped = kinds[c] in NULL_DISTINCT_SKIP_KINDS and c not in consts
            ok = ok and ("distinct" in d) and ((d["distinct"] is None) if skipped else _isint(d["distinct"]))
            if ok and c in consts:
                ok = "sole" in d and (d["sole"] is None or isinstance(d["sole"], str))
            if ok and _null_fb_possible(kinds[c], c in nullable):
                ok = _isint(d.get("fallback"))
            if ok and c in nullable:
                sc = nullable[c].get("scope")
                if sc:
                    ok = _isint(d.get("null_outside")) and isinstance(d.get("null_outside_keys"), list)
                    if ok and sc["mode"] == "exactly":
                        ok = _isint(d.get("nonnull_inside")) and isinstance(d.get("nonnull_inside_keys"), list)
    if ok and stamps:                  # a declared stamp column needs the catalog's own answer (its type and NOT NULL): never a PASS on a fact nobody read
        sf = got.get("stamp_facts")
        ok = isinstance(sf, dict) and all(isinstance(sf.get(c), dict) and isinstance(sf[c].get("type"), str) and isinstance(sf[c].get("notnull"), bool) for c in stamps)
        # a stamp the catalog says is a timestamp needs its sentinel count (a refused one is never graded, so it has none)
        ok = ok and all(_isint(got["cols"][c].get("sentinel")) for c in stamps if sf[c]["type"] in NULL_STAMP_TYPES)
    if not ok:
        raise Unknown(f"null_convention: malformed or incomplete statistics for {table}")
    return got


def _same_constant(a, b, kind: str) -> bool:
    """A declared constant's text compared with the stored one: numerics by value (1 = 1.0 = 1.00), everything else as text."""
    if kind == "num":
        try:
            import decimal
            return decimal.Decimal(str(a)) == decimal.Decimal(str(b))
        except (decimal.InvalidOperation, ValueError):
            return str(a) == str(b)
    return a == b


def grade_null_convention(spec: dict, columns, types, stats) -> dict:
    """The declared null convention verified (pure). Order: (1) a declared column the table does not carry (nullable, constant, scope key, allowed-literals) is a FAIL
    before any statistic is read; (2) under 2 rows is NO_DETECTOR (variation and constants cannot be shown); then every defect is collected: an undeclared NULL (a NULL in
    a column that is not declared nullable), a literal fallback (S3's definition, `_null_fallback_sql`) in ANY text-like column or a 0 in a declared-nullable numeric
    one, a scoped NULL outside the declared keys (both modes) or a value on a reserved-NULL key (mode exactly), a column that holds ONE value on every row (NULL counted as a
    value; numerics by value) and is not declared constant, a declared constant that varies or differs from its declared `value`. Any defect is a FAIL naming the columns
    and counts. A declared-nullable column that HAS NULL rows but no key scope has a meaning that is declared, not machine-checked: PARTIAL. Otherwise PASS, naming the
    columns actually checked. A malformed `stats` raises Unknown."""
    table = spec["table"]
    nullable = {n["column"]: n for n in spec["nullable"]}
    consts = {c["column"]: c for c in spec["constants"]}
    stamps = [x["column"] for x in spec.get("stamp_columns") or []]
    cols = list(columns)
    types = types or {}
    absent = sorted({c for c in _null_declared_columns(spec) if c not in cols})
    if absent:
        return dict(v=FAIL, declared=True, convention=dict(table=table, absent=absent),
                    measured=f"declared column(s) {', '.join(absent)} are not columns of {table}: the declaration names columns the table does not carry")
    got = _checked_null_stats(stats, table, cols, nullable, consts, types, stamps)
    rows, per = got["rows"], got["cols"]
    kinds = _null_kinds(got, cols, types)
    # a stamp column must be a timestamp / timestamptz AND NOT NULL by the CATALOG: a declaration the table contradicts is refused (NO_DETECTOR, never PASS), before any row is graded
    refused = [dict(field=f"null_convention.stamp_columns.{c}", declared="a NOT NULL timestamp / timestamptz write-time stamp",
                    measured=f"type {got['stamp_facts'][c]['type']}, {'NOT NULL' if got['stamp_facts'][c]['notnull'] else 'nullable'}")
               for c in stamps if got["stamp_facts"][c]["type"] not in NULL_STAMP_TYPES or not got["stamp_facts"][c]["notnull"]]
    if refused:
        return dict(v=NO_DET, declared=True, convention=dict(table=table, rows=rows, stamp_refused=[r["field"].rsplit(".", 1)[1] for r in refused]), declaration_disagreements=refused,
                    measured=f"NO_DETECTOR — the declared stamp column(s) are refused, the table contradicts the declaration (a stamp column must be a NOT NULL timestamp / timestamptz): "
                             + "; ".join(f"{r['field'].rsplit('.', 1)[1]} is {r['measured']}" for r in refused))
    if rows < 2:
        return dict(v=NO_DET, declared=True, convention=dict(table=table, rows=rows),
                    measured=f"NO_DETECTOR — {table} has {rows} row(s): constants and variation cannot be shown on fewer than 2 rows (vacuous)")
    undecl_nulls = {c: per[c]["nulls"] for c in cols if c not in nullable and c not in stamps and per[c]["nulls"]}
    stamp_nulls = {c: per[c]["nulls"] for c in stamps if per[c]["nulls"]}                   # a stamp column is checked instead of exempted: it must hold no NULL
    stamp_sentinels = {c: per[c]["sentinel"] for c in stamps if per[c]["sentinel"]}         # ... and no sentinel timestamp (infinity, -infinity, epoch, 1970-01-01, year 0001): its literal fallback
    fallbacks = {c: per[c]["fallback"] for c in cols if _null_fb_possible(kinds[c], c in nullable) and per[c].get("fallback")}
    scope_viol: dict = {}
    for c, n in nullable.items():
        sc = n.get("scope")
        if not sc:
            continue
        d = per[c]
        if d["null_outside"]:
            scope_viol.setdefault(c, {})["null_outside"] = dict(rows=d["null_outside"], keys=list(d["null_outside_keys"]))
        if sc["mode"] == "exactly" and d["nonnull_inside"]:
            scope_viol.setdefault(c, {})["valued_reserved"] = dict(rows=d["nonnull_inside"], keys=list(d["nonnull_inside_keys"]))
    not_examined = [c for c in cols if per[c]["distinct"] is None]
    one_value = {c: per[c]["distinct"] + (1 if per[c]["nulls"] else 0) <= 1 for c in cols if per[c]["distinct"] is not None}   # NULL counts as a value: {NULL, 'x'} varies
    undecl_consts = [c for c in cols if c not in consts and c not in stamps and one_value.get(c)]       # the ONE exemption a stamp column gets: a write-time stamp may be one value
    const_viol = []
    for c, d in consts.items():
        if not one_value[c]:
            const_viol.append(c)
        elif d.get("value") is not None and per[c]["nulls"] == 0 and not _same_constant(per[c].get("sole"), d["value"], kinds[c]):
            const_viol.append(c)
    unscoped = [c for c, n in nullable.items() if not n.get("scope") and per[c]["nulls"] > 0]
    # PARTITION NOTE (E6.1 follow-up, STAMP LOW): fallback_checked / elements_not_inspected / fallback_not_applicable / stamp_columns partition `cols` (each column in exactly one group,
    # pinned by test_e6_stamp_columns._partition) only while the catalog reads that feed them agree. `kinds` (null_fetch_column_kinds) and `stamp_facts` (null_fetch_stamp_facts) are two
    # separate pg_catalog SELECTs and the table SELECT is a third, not one snapshot: a concurrent ALTER COLUMN .. TYPE between them can list one column in TWO groups (a stamp the kinds
    # read still saw as text sits in fb_checked AND stamps) or in none. That is an accounting race only: the verdict is decided from the one table SELECT's numbers (`per`) plus the
    # refusal of a non-timestamp stamp above, never from the group lists, and a rebuild re-reads. It is recorded rather than guarded (guarding needs one catalog snapshot).
    fb_possible = [c for c in cols if _null_fb_possible(kinds[c], c in nullable)]
    elem_not_inspected = [c for c in fb_possible if kinds[c] == "array_other"]            # only the EMPTY-array test runs: the element contents are not looked at
    fb_checked = [c for c in fb_possible if c not in elem_not_inspected]                  # what the PASS claim "no literal fallback" actually covers
    fb_na = [c for c in cols if c not in fb_possible and c not in stamps]                 # a stamp column is examined (NOT NULL, no sentinel): it is in neither not-examined group
    allowed_all = [dict(column=a["column"], values=list(a["values"]), why=a["why"]) for a in spec.get("allowed_literals") or []]
    allowed_in_force = [a for a in allowed_all if kinds[a["column"]] in NULL_ALLOWED_EFFECT_KINDS]          # an exemption on a boolean / number / numeric array changes nothing
    allowed_no_effect = [a["column"] for a in allowed_all if kinds[a["column"]] not in NULL_ALLOWED_EFFECT_KINDS]
    block = dict(table=table, rows=rows, undeclared_nulls=undecl_nulls, stamp_columns=list(stamps), stamp_nulls=stamp_nulls, stamp_sentinels=stamp_sentinels, fallbacks=fallbacks, scope_violations=scope_viol,
                 undeclared_constants=undecl_consts, constant_violations=const_viol, unscoped_null_columns=unscoped,
                 fallback_checked_columns=fb_checked, fallback_not_applicable=fb_na, elements_not_inspected=elem_not_inspected, constants_not_examined=not_examined,
                 allowed_literals_in_force=allowed_in_force, allowed_literals_no_effect=allowed_no_effect)
    problems = []
    if undecl_nulls:
        problems.append("undeclared NULL in column(s) " + ", ".join(f"{c} ({n} row(s))" for c, n in sorted(undecl_nulls.items()))
                        + " (a NULL is permitted only in a declared nullable column)")
    if stamp_nulls:
        problems.append("NULL in declared stamp column(s) " + ", ".join(f"{c} ({n} row(s))" for c, n in sorted(stamp_nulls.items())) + " (a write-time stamp column must hold no NULL)")
    if stamp_sentinels:
        problems.append("sentinel timestamp: infinity, -infinity or any value at or before epoch + 1 day (epoch, 1970-01-01, year 0001 and earlier; a placeholder, not a write time) in declared stamp column(s) "
                        + ", ".join(f"{c} ({n} row(s))" for c, n in sorted(stamp_sentinels.items())))
    if fallbacks:
        problems.append("literal fallback (S3's placeholder definition: blank, N/A, none, 0 ... after normalisation) standing in for a value or for NULL in column(s) "
                        + ", ".join(f"{c} ({n} row(s){'' if c in nullable else '; not declared nullable'})" for c, n in sorted(fallbacks.items())))
    for c, v in sorted(scope_viol.items()):
        if "null_outside" in v:
            problems.append(f"{c}: NULL outside the declared keys on {v['null_outside']['rows']} row(s) (keys: {', '.join(map(str, v['null_outside']['keys']))})")
        if "valued_reserved" in v:
            problems.append(f"{c}: a value on reserved-NULL key(s) {', '.join(map(str, v['valued_reserved']['keys']))} ({v['valued_reserved']['rows']} row(s); mode exactly)")
    if undecl_consts:
        problems.append("column(s) " + ", ".join(undecl_consts) + " hold one value on every row (NULL counted as a value) and are not declared constant")
    for c in const_viol:
        d = consts[c]
        if one_value[c]:
            problems.append(f"declared constant column {c} holds {per[c].get('sole')!r} but {d['value']!r} was declared")
        else:
            problems.append(f"declared constant column {c} varies ({per[c]['distinct']} distinct value(s), {per[c]['nulls']} NULL)")
    if problems:
        return dict(v=FAIL, declared=True, convention=block, severity=1.0, measured=f"{table} ({rows} row(s)) breaks its declared null convention: " + "; ".join(problems))
    if unscoped:
        return dict(v=PARTIAL, declared=True, convention=block,
                    measured=f"{table} ({rows} row(s)): no undeclared NULL, no literal fallback, no undeclared constant; but declared-nullable column(s) "
                             f"{', '.join(unscoped)} hold NULL rows with no declared key scope, so what NULL means there is declared, not machine-checked")
    scoped = [f"{c} (NULL {'exactly' if n['scope']['mode'] == 'exactly' else 'only'} on {', '.join(n['scope']['null_for'])})" for c, n in nullable.items() if n.get("scope")]
    return dict(v=PASS, declared=True, convention=block,
                measured=f"{table} ({rows} row(s)): NULL only in the declared nullable column(s) {', '.join(nullable) or 'none'}"
                         + (f", verified on keys: {'; '.join(scoped)}" if scoped else "")
                         + f"; no literal fallback in the {len(fb_checked)} text-like / declared-nullable column(s) checked ({', '.join(fb_checked) or 'none'})"
                         + f"; {len(consts)} declared constant column(s) constant, no other column constant" + (" except the stamp column(s) named next" if stamps else "")
                         + (f"; stamp columns (write-time, constant test exempted; checked instead: NOT NULL timestamp, no NULL row, no infinity, -infinity or value at or before epoch + 1 day): " + ", ".join(f"{c} ({got['stamp_facts'][c]['type']}, NOT NULL, {per[c]['distinct']} distinct value(s) over {rows} row(s))" for c in stamps) if stamps else "")
                         + (f"; allowed literals in force (declared exemptions): " + "; ".join(f"{a['column']} {a['values']} ({a['why']})" for a in allowed_in_force) if allowed_in_force else "")
                         + (f"; NOT examined for a literal fallback (the type cannot hold one): " + ", ".join(f"{c} ({types.get(c) or kinds[c]})" for c in fb_na) if fb_na else "")
                         + (f"; NOT examined (element contents not inspected; only an empty array is a fallback): " + ", ".join(f"{c} ({types.get(c) or kinds[c]})" for c in elem_not_inspected) if elem_not_inspected else "")
                         + (f"; allowed_literals with no effect on the column type (not in force): {', '.join(allowed_no_effect)}" if allowed_no_effect else "")
                         + (f"; constants NOT examined (kind not distinct-counted, cost): " + ", ".join(f"{c} ({kinds[c]})" for c in not_examined) if not_examined else ""))


def null_convention_check(nc: dict, own: dict, exists, scope) -> dict:
    """measure()'s record for an asset that DECLARES `null_convention`. `own`: the asset's owned tables {table: (columns, types, defaults)}; `exists`: the tables
    production carries; `scope`: (tail, label) the declared table is read under, the tail already BOUND to the chart (`_bind_chart`), None when its rows cannot be scoped.
    A declared table the asset does not own is refused (NO_DETECTOR with the disagreement reported, nothing read); so is one production lacks, one with unknown columns or
    types, or one whose scope is unknown. A declared column (nullable, constant, scope key, allowed literal) the table does not carry is a FAIL before any SELECT. A table read
    as a whole-table UPPER BOUND (rows of other charts count) never reads PASS or FAIL: PARTIAL, naming what the whole table showed (as Null.blank_rows does). A failed read
    (including a client timeout, an OS or value error) degrades only this check (ERRORED)."""
    table = nc["table"]
    if table not in own:
        return dict(v=NO_DET, declared=True,
                    declaration_disagreements=[dict(field="null_convention.table", declared=table, measured=f"owned tables: {sorted(own)}")],
                    measured=f"NO_DETECTOR — the declared table {table} is not a table the asset owns (its target table or a table its count_sql reads: "
                             f"{', '.join(sorted(own)) or 'none'}); the declaration is refused")
    if table not in (exists or ()):
        return dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the declared table {table} does not exist in production")
    cols, types = own[table][0], own[table][1]
    if not isinstance(cols, (list, tuple, set)) or not cols:
        return dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the columns of {table} are unknown (never 'zero columns')")
    cols = sorted(cols) if not isinstance(cols, list) else list(cols)
    missing = sorted({c for c in _null_declared_columns(nc) if c not in cols})
    if missing:
        return grade_null_convention(nc, cols, types, None)           # a declaration naming what the table does not carry: FAIL before any SELECT
    if not isinstance(types, dict) or any(c not in types for c in cols):
        return dict(v=NO_DET, declared=True, measured=f"NO_DETECTOR — the data types of the columns of {table} were not read: a literal fallback cannot be tested without them")
    not_ts = [x["column"] for x in nc.get("stamp_columns") or [] if not _null_stamp_type_ok(types[x["column"]])]
    if not_ts:                                                    # the early screen: a declared stamp the table's own data types say is not a timestamp is refused before any SELECT
        return dict(v=NO_DET, declared=True,
                    declaration_disagreements=[dict(field=f"null_convention.stamp_columns.{c}", declared="a NOT NULL timestamp / timestamptz write-time stamp", measured=f"type {types[c]}") for c in not_ts],
                    measured=f"NO_DETECTOR — the declared stamp column(s) {', '.join(not_ts)} are not timestamp columns of {table} ({', '.join(f'{c} is {types[c]}' for c in not_ts)}): "
                             "the declaration is refused, nothing read")
    if scope is None:
        return dict(v=NO_DET, declared=True,
                    measured=f"NO_DETECTOR — the rows of {table} cannot be scoped to this asset (shared table, count_sql not a plain count): the scope is unknown")
    try:
        rec = grade_null_convention(nc, cols, types, null_convention_fetch(table, cols, types, nc, scope[0]))
    except (Unknown, OSError, ValueError) as exc:                 # R41: this check's failure (a client timeout included) degrades only this check
        return dict(v=ERRORED, declared=True, measured=f"check errored: {exc}")
    if scope[1] == UPPER_BOUND and rec["v"] in (PASS, FAIL, PARTIAL):
        return dict(rec, v=PARTIAL, measured=f"the table was read as a {UPPER_BOUND} (count_sql is not chart-scoped and the table carries chart_id): rows of other charts "
                                             f"count, so this chart is neither passed nor failed on them (the whole table reads {rec['v']}: {rec['measured']}); chart-scope the count to decide")
    return dict(rec, measured=f"{rec['measured']} [{scope[1]}]")


def _null_annotation(conv: dict, verified: bool = False) -> dict:
    """The `null_convention` block a Null record carries: what the detector said and whether the cap was lifted."""
    a = dict(declared=True, verified=verified, v=conv.get("v"), measured=conv.get("measured"))
    for k in ("convention", "declaration_disagreements"):
        if conv.get(k) is not None:
            a[k] = conv[k]
    return a


def earn_null_lift(entries, sd: dict, br: dict, conv: dict, decl: dict) -> dict:
    """The whole Null decision for an asset that declares a null_convention (pure). `sd` / `br`: the Null.schema_default / Null.blank_rows records computed over
    `entries` (the declared prose fields plus the convention's nullable columns), `conv`: the detector's record, `decl`: the declaration (evidence, why).
    {} = no change (the cap stays, the records are exactly what prose_checks produced). A FAIL (the convention's, or a grader's over the convention columns) is written
    to the records, so the cell flips. Both graders clean (the PARTIAL they can reach, marked `clean`) AND the convention PASS = both records PASS, each carrying the
    verified block `null_lift_earned` re-checks in the rollup."""
    out = {}
    cv = conv.get("v")
    if sd.get("v") == FAIL:
        out["Null.schema_default"] = dict(sd, null_convention=_null_annotation(conv))
    if br.get("v") == FAIL or cv == FAIL:
        note = f"declared null convention violated: {conv.get('measured')}"
        rec = dict(br, measured=f"{br['measured']}; {note}") if br.get("v") == FAIL else dict(v=FAIL, declared=True, measured=note)
        out["Null.blank_rows"] = dict(rec, null_convention=_null_annotation(conv))
    if out:
        return out
    if (cv == PASS and entries and sd.get("v") == PARTIAL and sd.get("clean") is True and br.get("v") == PARTIAL and br.get("clean") is True):
        table = (conv.get("convention") or {}).get("table")
        block = dict(declared=True, verified=True, v=PASS, table=table, columns=list(entries), stamp_columns=[x["column"] for x in decl.get("stamp_columns") or []],
                     evidence=decl.get("evidence"), why=decl.get("why"),
                     schema_default_clean=True, blank_rows_clean=True, convention=conv.get("measured"))
        return {"Null.schema_default": dict(sd, v=PASS, null_convention=dict(block),
                                            measured=f"PASS earned by the declared null convention: {sd['measured']}; {conv['measured']}"),
                "Null.blank_rows": dict(br, v=PASS, null_convention=dict(block),
                                        measured=f"PASS earned by the declared null convention: {br['measured']}; {conv['measured']}")}
    return {}


def null_lift_problem(meas) -> str | None:
    """None when this ONE Null record carries a complete verified lift block, else the reason it does not: the declared, verified, PASS block with the table, the
    covered columns, the echoed evidence and reason and both clean flags; no INCONCLUSIVE, no basis, the record itself PASS."""
    if not isinstance(meas, dict):
        return "no record"
    nc = meas.get("null_convention")
    if not isinstance(nc, dict):
        return "no null_convention block"
    if nc.get("declared") is not True or nc.get("verified") is not True or nc.get("v") != PASS:
        return "the convention is not declared, verified and PASS"
    for k in ("table", "evidence", "why"):
        if not (isinstance(nc.get(k), str) and nc[k].strip()):
            return f"the block carries no {k}"
    cols = nc.get("columns")
    if not (isinstance(cols, list) and cols and all(isinstance(c, str) and c for c in cols)):
        return "the block names no covered column"
    st = nc.get("stamp_columns", [])
    if not (isinstance(st, list) and all(isinstance(c, str) and c for c in st) and len(set(st)) == len(st) and not set(st) & set(cols)):
        return "the block's stamp_columns is not a list of distinct column names outside the covered columns"
    if nc.get("schema_default_clean") is not True or nc.get("blank_rows_clean") is not True:
        return "schema_default and blank_rows are not both clean"
    if meas.get("inconclusive") or meas.get("basis") is not None or meas.get("v") != PASS:
        return "the record is inconclusive, carries a basis, or is not PASS"
    return None


def writer_scan_problem(meas, facts=None) -> str | None:
    """E5.7 (Worker E, SS N-150 R7): None when this ONE Null record carries a complete verified `writer_scan` block (the static writer scan found every write path to every declared prose
    column, no literal fallback, no constant write, nothing unresolved; schema_default and blank_rows both clean), else the reason it does not. When `facts` carries the declared prose fields
    the block's entries must equal them (a record cannot narrow the claim)."""
    if not isinstance(meas, dict):
        return "no record"
    ws = meas.get("writer_scan")
    if not isinstance(ws, dict):
        return "no writer_scan block"
    if ws.get("verified") is not True or ws.get("v") != PASS:
        return "the writer scan is not verified and PASS"
    ents = ws.get("entries")
    if not (isinstance(ents, list) and ents and all(isinstance(x, str) and x for x in ents) and len(set(ents)) == len(ents)):
        return "the block names no covered prose entry"
    pe = ws.get("paths_per_entry")
    if not (isinstance(pe, dict) and set(pe) == set(ents) and all(isinstance(v, int) and not isinstance(v, bool) and v >= 1 for v in pe.values())):
        return "a covered entry has no found write path"
    fl = ws.get("files")
    if not (isinstance(fl, list) and fl and all(isinstance(x, str) and x for x in fl)):
        return "the block names no scanned source file"
    if ws.get("schema_default_clean") is not True or ws.get("blank_rows_clean") is not True:
        return "schema_default and blank_rows are not both clean"
    if isinstance(facts, dict) and isinstance(facts.get("declared_prose_fields"), list) and sorted(facts["declared_prose_fields"]) != sorted(ents):
        return "the block's entries are not the asset's declared prose_fields"
    if meas.get("inconclusive") or meas.get("basis") is not None or meas.get("v") != PASS:
        return "the record is inconclusive, carries a basis, or is not PASS"
    return None


def writer_scan_earned(crit: str, meas, all_meas, facts=None) -> bool:
    """True when the cap lifts for `crit` by the writer scan: this record AND its sibling Null record both carry a complete verified writer_scan block over the same entries and files."""
    if writer_scan_problem(meas, facts) is not None or not isinstance(all_meas, dict):
        return False
    sib = all_meas.get("Null.blank_rows" if crit == "Null.schema_default" else "Null.schema_default")
    if writer_scan_problem(sib, facts) is not None:
        return False
    a, b = meas["writer_scan"], sib["writer_scan"]
    return sorted(a["entries"]) == sorted(b["entries"]) and sorted(a["files"]) == sorted(b["files"])


def null_lift_earned(crit: str, meas, all_meas, facts=None) -> bool:
    """True when the Null cap lifts for `crit`: by the declared null convention (`_convention_lift_earned`, S1 pin 13) OR by the static writer scan (`writer_scan_earned`, E5.7)."""
    return _convention_lift_earned(crit, meas, all_meas) or writer_scan_earned(crit, meas, all_meas, facts)


def fidelity_pass_problem(meas, facts=None) -> str | None:
    """E5.7 (Worker E, SS N-150 R7): None when the Narr.fidelity_test record carries a complete verified `golden` block (each declared test verified by golden_test_scan: the built output asserted
    equal to an independent literal sentence), else the reason it does not. With `facts` carrying the declared prose fields, the covered entries must equal them."""
    if not isinstance(meas, dict):
        return "no record"
    g = meas.get("golden")
    if not isinstance(g, dict) or g.get("verified") is not True:
        return "no verified golden block"
    ents, tests = g.get("entries"), g.get("tests")
    if not (isinstance(ents, list) and ents and all(isinstance(x, str) and x for x in ents)):
        return "the block names no covered prose entry"
    if not (isinstance(tests, list) and tests):
        return "the block names no verified test"
    covered = set()
    for t in tests:
        if not (isinstance(t, dict) and isinstance(t.get("test"), str) and "::" in t["test"] and isinstance(t.get("line"), int) and t["line"] >= 1
                and all(isinstance(t.get(k), str) and re.fullmatch(r"[0-9a-f]{64}", t[k]) for k in ("expected_sha256", "file_sha256"))
                and isinstance(t.get("covers"), list) and t["covers"] and all(isinstance(c, str) for c in t["covers"])):
            return "a verified test entry is incomplete (test, line, expected_sha256, file_sha256, covers)"
        covered |= set(t["covers"])
    if not set(ents) <= covered:
        return "a covered prose entry is named by no verified test"
    if isinstance(facts, dict) and isinstance(facts.get("declared_prose_fields"), list) and sorted(facts["declared_prose_fields"]) != sorted(ents):
        return "the block's entries are not the asset's declared prose_fields"
    if meas.get("inconclusive") or meas.get("basis") is not None or meas.get("v") != PASS:
        return "the record is inconclusive, carries a basis, or is not PASS"
    return None


def fidelity_pass_earned(meas, facts=None) -> bool:
    return fidelity_pass_problem(meas, facts) is None


def _convention_lift_earned(crit: str, meas, all_meas) -> bool:
    """True when the cap lifts for `crit` by the declared null convention: this record AND its sibling Null record both carry a complete verified block, naming the same table and columns."""
    if null_lift_problem(meas) is not None or not isinstance(all_meas, dict):
        return False
    sib = all_meas.get("Null.blank_rows" if crit == "Null.schema_default" else "Null.schema_default")
    if null_lift_problem(sib) is not None:
        return False
    a, b = meas["null_convention"], sib["null_convention"]
    return a["table"] == b["table"] and a["columns"] == b["columns"] and a.get("stamp_columns", []) == b.get("stamp_columns", [])


_SIDECAR_PREFIX = "platform/python-sidecar/"
_TEST_FACTS: dict = {}


def python_tests(sidecar=None) -> list:
    """Every `test_*.py` under a `tests/` or `__tests__/` directory of the python sidecar, as (Path, text)."""
    root = Path(sidecar) if sidecar is not None else SIDECAR
    out = []
    for f in sorted(root.rglob("test_*.py")):
        if {"tests", "__tests__"} & set(f.relative_to(root).parts[:-1]):
            try:
                out.append((f, f.read_text(encoding="utf-8", errors="replace")))
            except OSError:
                continue
    return out


def _cited_modules(evidence) -> list:
    """The dotted sidecar modules the declaration's evidence cites (`platform/python-sidecar/x/y.py:LINE`)."""
    out = []
    for c in _EVIDENCE_ANY_CITE_RE.findall(evidence or ""):
        if c.startswith(_SIDECAR_PREFIX) and c.endswith(".py"):
            d = c[len(_SIDECAR_PREFIX):-3].replace("/", ".")
            d = d[:-len(".__init__")] if d.endswith(".__init__") else d
            if d not in out:
                out.append(d)
    return out


def _dotted(node, bound):
    parts = []
    while isinstance(node, ast.Attribute):
        parts.append(node.attr)
        node = node.value
    if isinstance(node, ast.Call):
        return None
    if not isinstance(node, ast.Name) or node.id not in bound:
        return None
    return ".".join([bound[node.id]] + parts[::-1])


_GENERIC_LEAVES = ("statement", "reason", "text", "summary", "description", "note")


_SKIP_WORD = re.compile(r"\b(?:skip\w*|xfail|expected_?failure)\b", re.I)


def _skips(node, aliases=()) -> bool:
    """A skip/xfail decorator (`pytest.mark.skip[if]`, `unittest.skip*`, `xfail`), directly or through an alias name
    (`sk = pytest.mark.skip` ... `@sk`)."""
    for d in getattr(node, "decorator_list", []):
        u = ast.unparse(d)
        if _SKIP_WORD.search(u) or any(re.search(rf"\b{re.escape(a)}\b", u) for a in aliases):
            return True
    return False


def _path_loaded(node, loaders):
    """`loader('x.py')` where `loader` is a module-level helper that loads a module from a file path
    (spec_from_file_location): the token `<file>:x`, which a cited module of the same stem matches."""
    if (isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in loaders and node.args
            and isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, str)
            and node.args[0].value.endswith(".py")):
        return "<file>:" + node.args[0].value[:-3].replace("/", ".").split(".")[-1]
    return None


def _import_module_arg(node, bound):
    """`importlib.import_module('x')` / `import_module('x')` / an alias of it (`from importlib import import_module as im`):
    the dotted module string, else None."""
    if not (isinstance(node, ast.Call) and node.args and isinstance(node.args[0], ast.Constant)
            and isinstance(node.args[0].value, str)):
        return None
    f = node.func
    name = _dotted(f, bound) if isinstance(f, (ast.Name, ast.Attribute)) else None
    if ast.unparse(f).endswith("import_module") or (name or "").endswith("import_module"):
        return node.args[0].value
    return None


def _test_facts(path: Path, text: str):
    """(functions, module_skipped) for a test file — cached; None if unparseable. One record per `test*` function:
    the dotted names it CALLS, whether it has a real assert, the leaf names it references (`leaves`; `assert_leaves`
    = those inside asserts / assert-call arguments) and whether it is skipped (decorator, class decorator, a
    `pytest.skip(` call, or a module `pytestmark` skip)."""
    key = (str(path), text)
    if key in _TEST_FACTS:
        return _TEST_FACTS[key]
    try:
        tree = ast.parse(text)
    except (SyntaxError, ValueError):
        _TEST_FACTS[key] = None
        return None
    try:
        pkg = list(path.relative_to(SIDECAR).parts[:-1])
    except ValueError:
        pkg = []
    bound: dict = {}
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.asname:
                    bound[a.asname] = a.name
                else:
                    bound[a.name.split(".")[0]] = a.name.split(".")[0]
        elif isinstance(n, ast.ImportFrom):
            if n.level:
                base = pkg[:len(pkg) - (n.level - 1)] if n.level - 1 <= len(pkg) else []
                mod = ".".join(base + ([n.module] if n.module else []))
            else:
                mod = n.module or ""
            for a in n.names:
                bound[a.asname or a.name] = f"{mod}.{a.name}" if mod else a.name
    # a helper that RETURNS an imported module/name (`def _mod(): from x import m; return m`) binds `w = _mod()`;
    # `w = importlib.import_module('x')` binds w to x
    rets = {}
    loaders = {f.name for f in tree.body if isinstance(f, (ast.FunctionDef, ast.AsyncFunctionDef))
               and any(isinstance(c, ast.Call) and ast.unparse(c.func).endswith("spec_from_file_location") for c in ast.walk(f))}
    for fn in ast.walk(tree):
        if isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
            for r in ast.walk(fn):
                if isinstance(r, (ast.Return, ast.Yield)) and r.value is not None:
                    d = (_dotted(r.value, bound) if isinstance(r.value, (ast.Name, ast.Attribute))
                         else _import_module_arg(r.value, bound) or _path_loaded(r.value, loaders))
                    if d:
                        rets[fn.name] = d
                        if any("fixture" in ast.unparse(dd) for dd in fn.decorator_list):
                            bound[fn.name] = d          # a test parameter named like the fixture is that module
    for n in ast.walk(tree):
        if isinstance(n, ast.Assign) and isinstance(n.value, ast.Call):
            f = n.value.func
            tgt = [t.id for t in n.targets if isinstance(t, ast.Name)]
            if isinstance(f, ast.Name) and f.id in rets:
                for t in tgt:
                    bound[t] = rets[f.id]
            elif _import_module_arg(n.value, bound) or _path_loaded(n.value, loaders):
                for t in tgt:
                    bound[t] = _import_module_arg(n.value, bound) or _path_loaded(n.value, loaders)
    aliases = {t.id for n in ast.walk(tree) if isinstance(n, ast.Assign) and _SKIP_WORD.search(ast.unparse(n.value))
               for t in n.targets if isinstance(t, ast.Name) and t.id != "pytestmark"}
    mod_skip = any(isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "pytestmark" for t in n.targets)
                   and _SKIP_WORD.search(ast.unparse(n.value)) for n in tree.body)
    cls_of = {id(c): k.name for k in ast.walk(tree) if isinstance(k, ast.ClassDef) for c in k.body if isinstance(c, (ast.FunctionDef, ast.AsyncFunctionDef))}
    cls_skip = {id(c): _skips(k, aliases) for k in ast.walk(tree) if isinstance(k, ast.ClassDef)
                for c in k.body if isinstance(c, (ast.FunctionDef, ast.AsyncFunctionDef))}

    def leaves_of(root, acc):
        for n in ast.walk(root):
            if isinstance(n, ast.Constant) and isinstance(n.value, str):
                acc.add(n.value)
            elif isinstance(n, ast.Attribute):
                acc.add(n.attr)
            elif isinstance(n, ast.Name):
                acc.add(n.id)
            elif isinstance(n, ast.keyword) and n.arg:
                acc.add(n.arg)
    def facts_of(fn):
        calls, leaves, aleaves, asserts, called = set(), set(), set(), False, set()
        skipped = _skips(fn, aliases) or cls_skip.get(id(fn), False)
        leaves_of(fn, leaves)
        for n in ast.walk(fn):
            if isinstance(n, ast.Call):
                d = _dotted(n.func, bound)
                if d:
                    calls.add(d)
                if isinstance(n.func, ast.Name):
                    called.add(n.func.id)
                nm = ast.unparse(n.func)
                if nm in ("pytest.skip", "skip", "pytest.xfail", "xfail"):
                    skipped = True
                if isinstance(n.func, ast.Attribute) and (n.func.attr.startswith("assert") or n.func.attr == "raises"):
                    asserts = True
                    for x in list(n.args) + [k.value for k in n.keywords]:
                        leaves_of(x, aleaves)
            elif isinstance(n, ast.Assert):
                if not (isinstance(n.test, ast.Constant) and n.test.value):      # `assert True` / `assert 1` prove nothing
                    asserts = True
                    leaves_of(n.test, aleaves)
        return dict(name=fn.name, calls=calls, asserts=asserts, leaves=leaves, assert_leaves=aleaves, skipped=skipped,
                    called=called, node=fn, bound=bound, cls=cls_of.get(id(fn)))
    helpers = {n.name: facts_of(n) for n in tree.body
               if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and not n.name.startswith("test")}
    funcs = []
    for fn in ast.walk(tree):
        if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)) or not fn.name.startswith("test"):
            continue
        f = facts_of(fn)
        for h in f["called"]:                       # ONE level of module-level helper: its calls, asserts and leaves
            if h in helpers:
                f["calls"] |= helpers[h]["calls"]
                f["leaves"] |= helpers[h]["leaves"]
                f["asserts"] = f["asserts"] or helpers[h]["asserts"]
        funcs.append(f)
    _TEST_FACTS[key] = (funcs, mod_skip)
    return _TEST_FACTS[key]


def _calls_module(call: str, mod: str) -> bool:
    """A dotted call lies in `mod`, or in a module loaded from a file path whose stem is mod's last component."""
    if call == mod or call.startswith(mod + "."):
        return True
    return call.startswith("<file>:") and call[len("<file>:"):].split(".")[0] == mod.rsplit(".", 1)[-1]


def _leaf_in(leaf: str, names) -> bool:
    """A declared leaf is referenced when a name contains it (`citation_human` in `_citation_human_position`) or is one of
    its underscore tokens of length >= 5 (`reason` for `verdict_reason`)."""
    toks = {t for t in leaf.split("_") if len(t) >= 5}
    return any(leaf in n or n in toks for n in names)


def narr_fidelity_scan(entries, evidence, tests, declared=None, root=None) -> dict:
    """The structural reading (`_narr_fidelity_structural`) PLUS, when the asset DECLARES `fidelity_tests` (E5.7, SS N-150 R7), the verification of each declared golden-value test
    (golden_test_scan.py: the named test exists, calls the builder and asserts the built output EQUAL to an independent literal sentence, covering the declared entries). PASS only when every
    declared prose entry is covered by a verified golden test and every declared test verifies; the record then carries the `golden` block the rollup re-checks. A structural FAIL / NO_DETECTOR
    is never raised by a declaration; without a declaration the reading is exactly the structural one (never PASS)."""
    base = _narr_fidelity_structural(entries, evidence, tests)
    if not declared:
        return base
    mods = _cited_modules(evidence)
    if not mods or base["v"] in (NO_DET, FAIL):
        return dict(base, golden_declared=True, measured=base["measured"] + "; the declared fidelity_tests were not verified (no builder module cited, or no test calls the builder)")
    try:
        gold = _lint_module("golden_test_scan")
    except (OSError, ImportError, SyntaxError) as exc:         # a tree without the sibling module (a plant fixture): the declared tests are not verified, the cap stands
        return dict(base, golden_declared=True, measured=f"{base['measured']}; the declared fidelity_tests were not verified (golden_test_scan.py could not be loaded: {type(exc).__name__})")
    rt = Path(root) if root is not None else ROOT

    def rel(p):
        try:
            return Path(p).resolve().relative_to(rt.resolve()).as_posix()
        except ValueError:
            return Path(p).as_posix()
    try:
        got = gold.scan(list(entries), declared, mods, tests, _test_facts, _dotted, _calls_module,
                        lambda e: (lambda c, pth: [k for k in (pth or ()) if k != PROSE_WILDCARD][-1] if pth else c)(*parse_prose_field(e)), rel)
    except (SyntaxError, ValueError, RecursionError, KeyError, AttributeError, TypeError) as exc:     # R41: a failed verification degrades only this check to its structural reading
        return dict(base, golden_declared=True, measured=f"{base['measured']}; the declared fidelity_tests could not be verified ({type(exc).__name__}: {str(exc)[:100]})")
    if got["v"] == PASS:
        return dict(got, tests=base.get("tests", []), measured="PASS: " + got["measured"])
    return dict(base, golden_tests=got["golden_tests"], covered_golden=got["covered"],
                measured=base["measured"] + "; declared golden-value tests NOT yet PASS: " + got["measured"])


def _narr_fidelity_structural(entries, evidence, tests) -> dict:
    """Narr.fidelity_test (CLAUDE.md N.7 item 5): a test exists that exercises the narration builder. Builder modules
    = the .py files the declaration's evidence cites. A test QUALIFIES when it calls a name imported from a builder
    module and contains an assert; it COVERS an entry when it also references the entry's leaf (column or last key).
    FAIL: no qualifying test. PARTIAL: >= 1 qualifying test. PASS is NOT reachable (SS decision: structural coverage
    does not prove a test grades the sentence). NO_DETECTOR: no readable builder module cited."""
    mods = _cited_modules(evidence)
    if not mods:
        return dict(v=NO_DET, measured="NO_DETECTOR — the declaration's evidence cites no readable sidecar writer module "
                                       "to look for tests of")
    leaves = {e: (lambda c, p: [k for k in (p or ()) if k != PROSE_WILDCARD][-1] if p else c)(*parse_prose_field(e))
              for e in entries}
    spec = [e for e, lf in leaves.items() if lf not in _GENERIC_LEAVES]
    spec_leaves = {leaves[e] for e in spec}
    qual, covered = [], set()
    for path, text in tests:
        f = _test_facts(Path(path), text)
        if not f or f[1]:                                  # unparseable, or the module is skipped
            continue
        for fn in f[0]:
            if fn["skipped"] or not fn["asserts"] or not any(_calls_module(c, m) for c in fn["calls"] for m in mods):
                continue
            qual.append(Path(path).name)
            beside = any(_leaf_in(lf, fn["leaves"]) for lf in spec_leaves)
            covered |= {e for e, lf in leaves.items()
                        if (_leaf_in(lf, fn["leaves"]) if lf not in _GENERIC_LEAVES
                            else (lf in fn["assert_leaves"] or (lf in fn["leaves"] and beside)))}
    if not qual:
        return dict(v=FAIL, covered=[], tests=[], measured=f"no (unskipped) test function calls the builder module(s) "
                    f"{', '.join(mods)} and asserts in the same function — N.7 item 5 (a fidelity test for the narration) "
                    "has no evidence in the repo")
    cov = [e for e in entries if e in covered]
    unc = [e for e in entries if e not in covered]
    names = sorted(set(qual))
    if not cov:
        return dict(v=PARTIAL, covered=[], tests=names, measured=f"{len(names)} test file(s) call the builder and assert "
                    f"({', '.join(names[:4])}): tests call the builder but none names a declared field (direct or indirect); "
                    f"declared: {', '.join(entries)}; structural only, never PASS")
    return dict(v=PARTIAL, covered=cov, tests=names, measured=(
        f"structural only: {len(names)} test file(s) call the builder and assert in the same test function "
        f"({', '.join(names[:4])}{'…' if len(names) > 4 else ''}); declared field(s) referenced: {', '.join(cov)}"
        + (f"; no qualifying test names: {', '.join(unc)}" if unc else "")
        + "; whether the assertion grades the sentence is not read, so this never reads PASS"))


_LINTS: dict = {}


def _lint_module(name: str):
    """A sibling governance lint, loaded by path once (registered in sys.modules: its dataclasses need it)."""
    if name not in _LINTS:
        import importlib.util
        spec = importlib.util.spec_from_file_location(f"_census_{name}", Path(__file__).resolve().parent / f"{name}.py")
        mod = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = mod
        spec.loader.exec_module(mod)
        _LINTS[name] = mod
    return _LINTS[name]


def _flat_str(node):
    """The text of a string expression made of constants, f-string constant parts and `+` concatenation; None otherwise."""
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.JoinedStr):
        return "".join(v.value if isinstance(v, ast.Constant) and isinstance(v.value, str) else " " for v in node.values)
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        a, b = _flat_str(node.left), _flat_str(node.right)
        return None if a is None or b is None else a + b
    return None


def _fact_category_surface(text: str) -> bool:
    """Real code that SELECTs chart_facts by fact_category: a non-docstring string expression (constant, f-string,
    `+` concatenation) holding SELECT, chart_facts and fact_category. A comment, a docstring or two unrelated strings
    each mentioning one word are not a surface. Raises SyntaxError for unparseable source."""
    tree = ast.parse(text)
    docs = _docstring_ids(tree)
    for n in ast.walk(tree):
        if id(n) in docs or not isinstance(n, (ast.Constant, ast.JoinedStr, ast.BinOp)):
            continue
        t = _flat_str(n)
        if t and re.search(r"\bSELECT\b", t, re.I) and "chart_facts" in t and "fact_category" in t:
            return True
    return False


def _raw_token_surface(col: str) -> bool:
    """A column the raw-token lint's narrative-field pattern covers: signal_headline_text, signal_text, *_thesis, *_narrative."""
    return col in ("signal_headline_text", "signal_text") or col.endswith(("_thesis", "_narrative"))


def narr_lint_scan(paths, columns=(), lint_none=None, beyond=()) -> dict:
    """Narr.lint: the existing narration lints (check_fact_category_pinning: the D1 class, N.7 item 2;
    check_no_raw_token_in_narrative) over the writer's resolved scope files, with their own allowlists. FAIL: a
    non-allowlisted violation (file:line). PARTIAL: only allowlisted ones (named; CI accepts them, the census does not
    call them clean). PASS needs a lint SURFACE that applied: fact_category selection of chart_facts in the scope
    (fact-category-pin) and/or a declared column the raw-token lint's field pattern covers (raw-token); with neither,
    the lints say nothing about this asset: NO_DETECTOR 'not applicable' (a clean scan of code a lint cannot see is
    not a pass). `applied` names the surfaces. NO_DETECTOR: no file in scope. ERRORED: unreadable file/lint.
    `beyond` (review fix LOW-1): the delegation chains the hop limit cut (`_delegation_scope`); a lint-not-applicable N/A needs it EMPTY (a cut chain could hold a lint surface), else NO_DETECTOR naming it.
    Single-expression limit, disclosed: `_fact_category_surface` finds a surface only when SELECT, chart_facts and fact_category sit in ONE flattened string expression; a query assembled across
    several statements is not seen, which is why the N/A also rests on a declaration the reviewer read.
    `lint_none` (N-150 R2): the asset's declared {why, evidence}. With it AND `applied == []` over at least one scanned file the record reads N/A (cause lint-not-applicable) carrying the
    `lint_none` block the rollup requires; with it and a surface that DID apply the record is NO_DETECTOR naming the surface (the declaration is contradicted); without it the old NO_DETECTOR."""
    paths = [Path(p) for p in paths]
    if not paths:
        return dict(v=NO_DET, applied=[], measured="NO_DETECTOR — no writer file in scope to run the narration lints over")
    try:
        fcp, rt = _lint_module("check_fact_category_pinning"), _lint_module("check_no_raw_token_in_narrative")
        allow_f, allow_r = fcp.load_allowlist(fcp.ALLOWLIST_PATH), rt.load_allowlist(rt.ALLOWLIST_PATH)
        new, old = [], []
        fact_surface = False
        for p in paths:
            text = p.read_text(encoding="utf-8")
            fact_surface = fact_surface or _fact_category_surface(text)
            try:
                rel = p.resolve().relative_to(ROOT).as_posix()
            except ValueError:
                rel = str(p)
            vf = [fcp.Violation(rel, ln, "python", "sql_select", sn, "") for ln, sn in fcp.scan_python_text(text)]
            vr = [rt.Violation(rel, ln, kind, sn, "") for ln, kind, sn in rt.scan_py_file(text)]
            for tag, vs, allow, mod in (("fact-category-pin", vf, allow_f, fcp), ("raw-token", vr, allow_r, rt)):
                a, n = mod.partition_allowlisted(vs, allow)
                old += [f"{tag} {v.file}:{v.line}" for v in a]
                new += [f"{tag} {v.file}:{v.line}" for v in n]
    except (OSError, ValueError, AttributeError, SyntaxError, ImportError) as exc:
        return dict(v=ERRORED, measured=f"check errored: narration lint could not run ({type(exc).__name__}: {exc})")
    applied = (["fact-category-pin"] if fact_surface else []) + (["raw-token"] if any(_raw_token_surface(c) for c in columns) else [])
    if new:
        return dict(v=FAIL, applied=applied, measured="narration lint violation(s) in the writer scope: " + "; ".join(new))
    if old:
        return dict(v=PARTIAL, applied=applied, measured="only allowlisted narration lint violation(s) in scope: " + "; ".join(old))
    if lint_none is not None and applied:
        return dict(v=NO_DET, applied=applied, measured=f"NO_DETECTOR — the asset declares lint_none (N-150 R2) but the scan found a lint surface ({' and '.join(applied)}): the declaration is "
                    "contradicted, never N/A; declare prose and fix the lint result, or correct the declaration")
    if not applied and lint_none is not None and beyond:
        return dict(v=NO_DET, applied=[], measured="NO_DETECTOR — the asset declares lint_none (N-150 R2) but its delegation chain was cut by the hop limit (" + "; ".join(map(str, list(beyond)[:3])) +
                    "): a cut chain could hold a lint surface, so the scan does not agree, never N/A")
    if not applied and lint_none is not None:
        return dict(_na(f"the narration lints are not applicable: no chart_facts fact_category selection in the {len(paths)}-file writer scope and no declared column the raw-token lint covers "
                        f"(declared lint_none, agreed by the scan, N-150 R2): {lint_none['why']}", "lint-not-applicable"),
                    applied=[], lint_none=dict(why=lint_none["why"], evidence=lint_none["evidence"], scope_files=len(paths), applied=[], beyond=[]))
    if not applied:
        return dict(v=NO_DET, applied=[], measured=f"NO_DETECTOR — the narration lints are not applicable to this asset: no "
                    f"chart_facts fact_category selection in its {len(paths)}-file writer scope and no declared column the "
                    "raw-token lint covers; a clean scan of code they cannot see is not a pass")
    return dict(v=PASS, applied=applied, measured=f"{len(paths)} writer scope file(s) clean under the {' and '.join(applied)} "
                                                  "narration lint(s) that applied (their own allowlists applied)")


_QQ = r"(?:ONLY\s+)?(?:public\.)?\"?"
_INSERT_COLS = re.compile(r"INSERT\s+INTO\s+" + _QQ + r"([A-Za-z_][A-Za-z_0-9]*)\"?\s*(\([^)]*\))?", re.I)
_UPDATE_SET = re.compile(r"\bUPDATE\s+" + _QQ + r"([A-Za-z_][A-Za-z_0-9]*)\"?\s+SET\s+(.*?)(?=\bWHERE\b|\bFROM\b|\bRETURNING\b|\Z)",
                         re.I | re.S)


def written_columns(units, tables):
    """table -> the columns the writer's resolved scope INSERTs (column list) or UPDATEs (SET targets) on `tables`.
    None when a write to one of them cannot be read (no column list, an unresolved `{?}` name): never a guess."""
    tset = {t.lower() for t in tables if t}
    out: dict = {}
    for u in units:
        for node in u["nodes"]:
            for text, _ln in _sql_texts(dict(u, nodes=[node])):
                for m in _INSERT_COLS.finditer(text):
                    if m.group(1).lower() not in tset:
                        continue
                    if not m.group(2) or "{?}" in m.group(2):
                        return None
                    out.setdefault(m.group(1).lower(), set()).update(
                        c.strip().strip('"') for c in m.group(2)[1:-1].split(",") if c.strip())
                for m in _UPDATE_SET.finditer(text):
                    if m.group(1).lower() not in tset:
                        continue
                    if "{?}" in m.group(2):
                        return None
                    for a in _split_top(m.group(2)):
                        if "=" in a:
                            out.setdefault(m.group(1).lower(), set()).add(a.split("=", 1)[0].strip().strip('"'))
    return out


def prose_vocabulary(declarations, asset_tables=None):
    """The columns some asset's declaration lists as prose (the file's own narration-column vocabulary).

    `asset_tables` None: the legacy GLOBAL form, a set of column names (a column name declared as prose by any asset). `asset_tables` {asset id: {tables the asset owns}}: the PER-ASSET form
    (E5.7, SS 2026-10-06), a dict {column: {tables}}: a column is narration in the tables of the assets that declare it, so a writer is judged only against declarations of assets that
    share a table with it (bo_pramana_mapa's `notes` no longer flips the unrelated L0 writers that also write a column named `notes`). A declaring asset whose tables are unknown
    contributes the wildcard None (the legacy global reading for that one declaration: never weaker than before)."""
    if asset_tables is None:
        return {parse_prose_field(e)[0] for d in (declarations or {}).values() if isinstance(d, dict)
                for e in (d.get("prose_fields") or [])}
    out: dict = {}
    for aid, d in (declarations or {}).items():
        if not isinstance(d, dict):
            continue
        tabs = {t.lower() for t in (asset_tables.get(aid) or ())}
        for e in (d.get("prose_fields") or []):
            out.setdefault(parse_prose_field(e)[0], set()).update(tabs or {None})
    return out


def prose_reverse_leg(written, vocabulary) -> list:
    """`[]`-declared asset: the `table.column` writes that hit a column the declarations treat as narration elsewhere
    (principle 8: such a column present while prose_fields is empty reads FAIL). Write-column names only: it does not
    prove 'composes no string' (the AST proofs in test_e6_1_declarations.py do, per asset). A per-asset vocabulary (dict column -> tables, see prose_vocabulary) hits only a write into a
    table that the declaring assets own (or a wildcard declaration); a set is the legacy global match."""
    if isinstance(vocabulary, dict):
        return sorted(f"{t}.{c}" for t, cols in (written or {}).items() for c in cols
                      if c in vocabulary and (None in vocabulary[c] or str(t).lower() in vocabulary[c]))
    return sorted(f"{t}.{c}" for t, cols in (written or {}).items() for c in cols if c in vocabulary)


def declared_asset_tables(reg_all, other_layers=()) -> dict:
    """{asset id: {tables}} the asset owns: registry target_table plus the tables its count_sql reads, for this layer's registry rows `reg_all` and any further registry dicts in
    `other_layers` (each read defensively by the caller). Used to scope the Narr.agree reverse leg per asset."""
    out: dict = {}
    for reg in (reg_all, *other_layers):
        for aid, r in (reg or {}).items():
            if not isinstance(r, dict):
                continue
            ts = ([r["target_table"]] if r.get("target_table") else []) + _count_tables(r.get("count_sql") or "")
            out.setdefault(aid, set()).update(t.lower() for t in ts if t)
    return out


NARR_CHECKS = ("Narr.agree", "Narr.checkable", "Narr.fidelity_test", "Narr.lint")
NULL_CHECKS = ("Null.schema_default", "Null.blank_rows")


def _own3(ctx: dict) -> dict:
    """ctx -> {table: (columns, types, defaults)}: the owned tables when supplied (a 2-tuple has unread defaults),
    else the single target table with ctx's columns/types/defaults."""
    if ctx.get("own") is not None:
        return {t: (v[0], v[1], v[2] if len(v) > 2 else None) for t, v in ctx["own"].items()}
    return {ctx["table"]: (ctx.get("columns"), ctx.get("types"), ctx.get("defaults"))} if ctx.get("table") else {}


def writer_scan_scope(aid: str, files: list[str]) -> tuple[list[dict], list[str]]:
    """The writer scope the Null writer scan (writer_literal_scan.py) reads: the delegation scope at PRODUCED_SET_HOPS depth, the same depth Build.completion's produced-set scan uses.
    The default scope (the Narr.agree reverse leg's) cuts the chain two hops out, so an asset whose narration row is assembled in a helper three or four hops from the writer could
    never be read clean (the scan names the cut as an unresolved path and the cell stays PARTIAL). A deeper scope only ADDS statements to read: it cannot clear a finding the shallower scope
    made, and a write the deeper scope reveals is judged exactly like any other. Raises Unknown like `_delegation_scope`."""
    return _delegation_scope(aid, files, hops=PRODUCED_SET_HOPS)


def _apply_writer_scan(out: dict, pf, ctx: dict) -> None:
    """E5.7 (Worker E, SS N-150 R7): run the static writer scan (writer_literal_scan.py) over `ctx['units']` (the writer's resolved scope) for the declared prose entries and fold it into the two
    Null records. Both records clean (the PARTIAL `clean` reading of the data-level graders) AND the scan clean = both read PASS, each carrying the `writer_scan` block the rollup re-checks.
    Otherwise the records keep their verdict and say what the scan found / could not resolve. No units = no scan (the records are exactly what the graders produced). Fault-isolated (R41)."""
    scan_units = ctx.get("scan_units")                         # the deeper scope (writer_scan_scope) when the caller read it; else the default scope
    units = scan_units or ctx.get("units")
    if not units or not pf:
        return
    beyond = (ctx.get("scan_beyond") if scan_units else ctx.get("beyond")) or ()
    own = _own3(ctx)
    holders = {parse_prose_field(e)[0]: _holders(parse_prose_field(e)[0], own) for e in pf}
    try:
        ws = _lint_module("writer_literal_scan").scan(units, list(pf), holders, is_placeholder=ldgr_placeholder_py, sql_texts=_sql_texts,
                                                      parse_entry=parse_prose_field, beyond=beyond)
    except Exception as exc:                                  # a failed scan degrades only the writer-scan evidence: the data-level records stay as they are
        for crit in NULL_CHECKS:
            if out.get(crit, {}).get("v") == PARTIAL:
                out[crit] = dict(out[crit], measured=out[crit]["measured"] + f"; writer scan errored ({type(exc).__name__}: {str(exc)[:120]}), so this stays PARTIAL")
        return
    summary = dict(v=ws["v"], problems=ws["problems"][:10], unresolved=ws["unresolved"][:10], files=ws["files"])
    ctx["scan_result"] = ws                                     # N-189: the whole scan (every finding), for the forwarded-leaf detector's cover check
    sd, br = out.get("Null.schema_default", {}), out.get("Null.blank_rows", {})
    clean = all(r.get("v") == PARTIAL and r.get("clean") is True for r in (sd, br))
    if clean and ws["v"] == PASS:
        block = dict(verified=True, v=PASS, entries=list(pf), columns=sorted({parse_prose_field(e)[0] for e in pf}), files=list(ws["files"]),
                     paths_per_entry={e: ws["entries"][e]["writes"] for e in pf}, schema_default_clean=True, blank_rows_clean=True, scan=ws["measured"])
        for crit in NULL_CHECKS:
            out[crit] = dict(out[crit], v=PASS, writer_scan=dict(block),
                             measured=f"PASS earned by the writer scan: {out[crit]['measured'].split('; schema defaults')[0].split('; writer literal')[0]}; {ws['measured']}")
        return
    for crit in NULL_CHECKS:
        rec = out.get(crit)
        if isinstance(rec, dict) and rec.get("v") == PARTIAL:
            txt = rec["measured"].replace("so this is never PASS", "so the writer source is scanned for them (E5.7) and the scan is not clean")
            out[crit] = dict(rec, writer_scan_summary=summary, measured=f"{txt}; {ws['measured']}")


def prose_checks(aid: str, decl, ctx: dict) -> dict:
    """The six Narr/Null records for one asset, from its declaration entry (`prose_fields`, `evidence`) and `ctx`:
    table, columns, types, defaults, counts (None = not read), paths (writer scope files), tests, vocabulary, written
    (None = the writer's writes could not be read). null prose_fields = undeclared: every check NO_DETECTOR, never
    'no prose'. [] = positive declaration: measured N/A candidates (causes no-prose / no-prose-declared). The rollup
    releases the four Narr ones only because the Narr.*#measured:no-prose rules are declared (SS N-65, REGISTRY_REVISION 9);
    the two Null ones have no rule (N-22 row 33) and read NO_DETECTOR. Unless a write hits a column the file treats as
    narration (agree FAIL, the rest NO_DETECTOR) or the writes are unreadable or EMPTY (NO_DETECTOR: a scan that saw no
    write at all is not evidence of "no narration write")."""
    allc = NARR_CHECKS + NULL_CHECKS
    pf = decl.get("prose_fields") if isinstance(decl, dict) else None
    if pf is None:
        return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — prose_fields is undeclared for {aid}: never read as 'no prose'")
                for c in allc}
    if not pf:
        bad = prose_empty_d1_problem(decl) or prose_coupling_required_problem(aid, decl)
        if bad:                           # NARR-GUARD (N-94): [] + a D1 transcription carriage with no coupling is never N/A, whatever the validator saw; nor is [] on an asset whose coupling is required
            return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid}: {bad}") for c in allc}
        if not ctx.get("written"):       # None (unreadable) OR {} (the scan saw no write at all): neither proves "no narration write"
            return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares prose_fields [] but its writes could not be "
                                               "read (or the scan saw no write to its tables), so the declaration cannot be checked")
                    for c in allc}
        hits = prose_reverse_leg(ctx["written"], ctx.get("vocabulary") or set())
        _ex_cols, _ex_block, _ex_fail, _ex_unread = checked_prose_exclusions(aid, decl, _own3(ctx), ctx.get("table"))
        if _ex_fail:
            out = {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares prose_fields [] but Narr.agree failed") for c in allc}
            out["Narr.agree"] = dict(v=FAIL, measured=_ex_fail)
            return out
        hits = [h for h in hits if h.lower() not in _ex_cols]
        if hits:
            out = {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares prose_fields [] but Narr.agree failed") for c in allc}
            out["Narr.agree"] = dict(v=FAIL, measured=f"prose_fields is [] but the writer writes column(s) the declarations "
                                                      f"treat as narration: {', '.join(hits)}")
            return out
        why = ("prose_fields [] declared and no write to a column the declarations treat as narration (write-column "
               "names only; the composed-string proof is the declaration tests')")
        if isinstance(decl, dict) and decl.get("prose_coupling") is not None:
            # NARR-GUARD (pin 16, N-94): the N/A is coupled to Carr.D1. The SAME check the validator runs, here with the table's columns and types: a refusal is NO_DETECTOR with the
            # disagreement reported, never N/A. The coupling to the D1 READING itself is the rollup's (narr_coupling_problem): it sees both cells.
            own = _own3(ctx).get(ctx.get("table")) or (next(iter(_own3(ctx).values()), None))
            tcols = own[0] if own and isinstance(own[0], (list, tuple, set)) else None
            ttypes = own[1] if own and isinstance(own[1], dict) else None
            bad = prose_coupling_problem(decl, tcols, ttypes)
            if bad:
                return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares prose_fields [] with a prose_coupling to Carr.D1, but the coupling is refused: {bad}")
                        for c in allc}
            cov = _carriage_d1().prose_coverage(decl["carriage"]["spec"])
            pcols = list(decl["prose_coupling"]["columns"])
            block = dict(to=decl["prose_coupling"]["to"], columns=pcols, covered={c: cov[c] for c in pcols},
                         unclassified_text_columns=prose_coupling_unclassified(decl, tcols, ttypes))
            note = (f"{why}; the text column(s) {', '.join(pcols)} are declared transcription (prose_coupling to Carr.D1, N-94): this N/A rests on Carr.D1 PASS (coupled), "
                    f"which the rollup re-reads on every cell; not claimed by the coupling (text-like, neither listed nor checked by the D1 spec): "
                    f"{', '.join(block['unclassified_text_columns']) or 'none'}")
            return {c: (dict(_na(note, "no-prose"), prose_coupling=dict(block)) if c.startswith("Narr.") else _na(why, "no-prose-declared")) for c in allc}
        # N-150 R1: a bare `prose_fields []` is NOT a release (nothing checks it against the schema); the explicit `prose_none` form is checked against the produced tables
        if decl.get("prose_none") is None:
            return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid} declares prose_fields [] without the explicit declared-none form (prose_none): the claim is not checked against the live "
                                               "schema, so it is not a release (N-150 R1)") for c in allc}
        bad = prose_none_problem(decl)
        if bad:
            return {c: dict(v=NO_DET, measured=f"NO_DETECTOR — {aid}: the prose_none declaration is refused: {bad}") for c in allc}
        tables = ctx.get("prose_tables")
        if tables is None:
            tables = {t: (v[0], v[1], None) for t, v in _own3(ctx).items()}
        return grade_prose_none(aid, decl, tables, ctx.get("table"), ctx.get("closed_outside") or {}, udts=ctx.get("udts"), keys=ctx.get("keys"), written=ctx.get("written"))
    ev = (decl.get("evidence") or {}).get("prose_fields") if isinstance(decl.get("evidence"), dict) else None
    out = {}
    for crit, fn in (
            ("Narr.agree", lambda: grade_narr_agree_tables(pf, {t: (v[0], v[1]) for t, v in _own3(ctx).items()})),
            ("Narr.checkable", lambda: grade_narr_checkable(pf, ctx.get("counts"))),
            ("Narr.fidelity_test", lambda: narr_fidelity_scan(pf, ev, ctx.get("tests") or (), decl.get("fidelity_tests"), ctx.get("root"))),
            ("Narr.lint", lambda: narr_lint_scan(ctx.get("lint_paths") or ctx.get("paths") or (), [parse_prose_field(e)[0] for e in pf],
                                                (decl.get("lint_none") if not lint_none_problem(decl) else None), ctx.get("lint_beyond") or ())),
            ("Null.schema_default", lambda: grade_null_schema_default_tables(pf, _own3(ctx))),
            ("Null.blank_rows", lambda: grade_null_blank_rows(pf, ctx.get("counts")))):
        try:
            out[crit] = fn()
        except (Unknown, DeclarationsError) as exc:      # R41: one check's failure degrades only that check
            out[crit] = dict(v=ERRORED, measured=f"check errored: {exc}")
    _apply_writer_scan(out, pf, ctx)
    _apply_forwarded_leaves(out, pf, ctx)                       # N-189: the forwarded-leaf detector (no declaration = no change)
    _ex_cols, _ex_block, _ex_fail, _ex_unread = checked_prose_exclusions(aid, decl, _own3(ctx), ctx.get("table"))
    if _ex_fail:
        out["Narr.agree"] = dict(v=FAIL, measured=_ex_fail)
    if out.get("Narr.agree", {}).get("v") == PASS and ctx.get("written") is None:
        out["Narr.agree"] = dict(v=PARTIAL, measured=out["Narr.agree"]["measured"] + "; reverse leg unavailable: the writer's "
                                 "writes could not be read, so a prose-vocabulary column it writes without declaring is unchecked")
    if out.get("Narr.agree", {}).get("v") == PASS and ctx.get("written") is not None:
        # two-way: a column the declarations treat as narration that this writer writes but does not declare
        declared_cols = {parse_prose_field(e)[0] for e in pf}
        und = [h for h in prose_reverse_leg(ctx["written"], ctx.get("vocabulary") or set()) if h.split(".", 1)[1] not in declared_cols]
        ex_hit = [h for h in und if h.lower() in _ex_cols]
        und = [h for h in und if h.lower() not in _ex_cols]
        if und:
            out["Narr.agree"] = dict(v=PARTIAL, measured=out["Narr.agree"]["measured"] + "; but the writer also writes "
                                     f"prose-vocabulary column(s) it does not declare (undeclared): {', '.join(und)}")
        if ex_hit and not und:
            out["Narr.agree"] = dict(out["Narr.agree"], measured=out["Narr.agree"]["measured"] + "; the writer also writes prose-vocabulary column(s) "
                                     f"{', '.join(ex_hit)}, EXCLUDED by declaration under the cited SS decision (checked: the column exists on the table and the decision declines it)",
                                     prose_excluded=_ex_block)
    if _ex_unread and out.get("Narr.agree", {}).get("v") == PASS:
        out["Narr.agree"] = dict(v=PARTIAL, measured=out["Narr.agree"]["measured"] + f"; {_ex_unread}")
    return out


# R40: the psql subprocess timeout was hardcoded at 180s, which is shorter than a full-table
# duplicate scan on the estate's largest table (kala_field, 10.3M rows) can take — making the L3
# and `--layer all` census unrunnable on production. Configurable via env so an operator pointed
# at a much larger table than the ones this script was calibrated against can raise it without a
# code change.
PSQL_TIMEOUT_SECONDS = int(os.environ.get("NIKASHA_CENSUS_TIMEOUT_SECONDS", "180"))
# N-99: the cap on one registry-stored `integrity_check_sql` run (client kill; the server `statement_timeout` is 90% of it).
INTEGRITY_TIMEOUT_SECONDS = PSQL_TIMEOUT_SECONDS

# R231 (A_REVIEW2 G4): 78 of 86 L1–L5 `count_sql` are chart-scoped (`WHERE chart_id = $1`). Run
# standalone they cannot bind `$1`, so F2 correctly graded them ERRORED — and `Build.completion` was
# unmeasured above L0. The census now binds ONE chart scope, exactly as the engine does
# (`asset_runner._data_rows_present`: `count_sql.replace("$1", %s)` with the chart id as a quoted
# literal), and reads that chart's own build record. The canonical chart (CLAUDE.md §B) is the
# default; `362f9f17-…` is a dead phantom and is refused.
CANONICAL_CHART_ID = "482012f1-710e-4a25-994a-93821f5871aa"
CHART_ID = os.environ.get("NIKASHA_CENSUS_CHART_ID", CANONICAL_CHART_ID).strip()
_PHANTOM_CHART_PREFIX = "362f9f17"
_PARAM_1 = re.compile(r"\$1(?!\d)")
_ANY_PARAM = re.compile(r"\$\d+")


def _view_count_sql(view: str, cols: list[str]) -> str:
    """R46: the census's count of a view target — its rows for the bound chart when the view carries
    `chart_id` (bound like any `$1` count), else the whole view."""
    return f"SELECT count(*) FROM {view}" + (" WHERE chart_id = $1" if "chart_id" in cols else "")


def _chart_scoped(count_sql: str) -> bool:
    return bool(_PARAM_1.search(count_sql or ""))


def _count_tables(count_sql: str) -> list[str]:
    """R42: the relations a count_sql reads (FROM / JOIN targets, in order, de-duplicated). One
    table is a plain count; several is a multi-table count (a sum or a join) whose total must be
    compared like-for-like and never presented as the target table's own rows; NONE is a constant
    (`SELECT 0 AS count`, bo_samvada) — a figure that cannot vary is not a measurement."""
    q = re.sub(r"--[^\n]*", "", count_sql or "")
    out: list[str] = []
    for t in re.findall(r"\b(?:FROM|JOIN)\s+([A-Za-z_][A-Za-z0-9_.]*)", q, re.I):
        t = t.split(".")[-1].lower()
        if t not in out:
            out.append(t)
    return out


# R42: the build-record states that mean "a build completed and wrote these rows". `stale` is a
# completed build whose upstream has since moved (R45 grades staleness, W2-2); `error`,
# `incomplete`, `dormant` and `building` are not completions, so their rows_written — whatever it
# equals — is not a completed build agreeing with the live data.
COMPLETED_STATES = ("lit", "stale")


def _bind_chart(q: str, chart_id: str) -> str:
    """Bind `$1` to the chart scope as a quoted literal (the engine's own binding). Raises `Unknown`
    for a phantom chart id, a malformed one, or a `count_sql` with any OTHER unbound parameter —
    a query that cannot be bound is not measured, and never silently run half-bound."""
    if _PARAM_1.search(q):
        if chart_id.startswith(_PHANTOM_CHART_PREFIX):
            raise Unknown(f"refusing chart scope {chart_id}: the 362f9f17-… chart id is a dead phantom")
        if not re.fullmatch(r"[0-9a-fA-F-]{36}", chart_id):
            raise Unknown(f"chart scope {chart_id!r} is not a uuid")
    bound = _PARAM_1.sub(f"'{chart_id}'", q)
    left = sorted(set(_ANY_PARAM.findall(bound)))
    if left:
        raise Unknown(f"count_sql has unbound parameter(s) {', '.join(left)} — only $1 (chart scope) is bindable")
    return bound


class Unknown(Exception):
    """The instrument could not run. Never reported as clean."""


class CheckTimeout(Unknown):
    """R223 (A_REVIEW2 G3): the client-side psql timeout fired. Production's `statement_timeout`
    (30 min) is far above the census's client timeout (180 s), so a real timeout arrives as
    `subprocess.TimeoutExpired` — which is not an `Unknown`, escaped every per-check guard, and
    ended the whole run with exit 5. It is converted here, at the one place every query passes
    through, so a timed-out check degrades to ERRORED exactly like any other failed query (and a
    timed-out layer-wide read still aborts the layer, fail-closed, naming the read)."""


class ReadError(Unknown):
    """E1.8: psql answered, but its text does not parse into the rectangular rows a `-tA` result always is
    (a ragged row, an unterminated output, undecodable bytes). A read that cannot be parsed exactly is not
    measured: it degrades like every other failed query (an `Unknown`), and is never padded, trimmed or guessed."""


class CensusRoleCannotRead(Unknown):
    """A read that needs a table the census role cannot SELECT from. Raised BEFORE any SQL is issued (d3_fetch_inputs); the D3 check degrades to NO_DETECTOR, never ERRORED."""


def parse_psql_output(out: str, sep: str = "\x1f", width: int | None = None) -> list[list[str]]:
    """The rows of `psql -tA -F <sep>` output, exactly. `-tA` prints each row as its fields joined by `sep` and
    terminated by ONE newline, so exactly that one terminator is removed and nothing else: `str.strip()` also
    removes U+001C..U+001F (the field separator is whitespace to Python) and so ate the trailing separator of a
    last row whose last field was empty — one field fewer, `ValueError` in a fixed-width unpack, or a silently
    shortened row — and the leading separator of a first row whose first field was empty, shifting every field.
    A row of only empty fields is a row (a single-column result's empty value is `[""]`), not a blank line.
    Every row must have the same field count (`width` when given): a row that does not is a `ReadError` —
    typically a value carrying a newline, which this line-oriented transport cannot represent."""
    if out == "":
        return []
    if not out.endswith("\n"):
        raise ReadError("psql output is not newline-terminated (truncated?) — not parsed")
    rows = [ln.split(sep) for ln in out[:-1].split("\n")]
    want = width if width is not None else len(rows[0])
    for i, r in enumerate(rows):
        if len(r) != want:
            seen = f"{r[:3]!r}"[:200]
            raise ReadError(f"psql row {i + 1} of {len(rows)} has {len(r)} field(s), expected {want} "
                            f"({'declared' if width is not None else 'the first row'}): {seen} — a value "
                            "containing a newline cannot be read line by line")
    return rows


class _Capped:
    """A finished psql run whose stdout / stderr were read through a byte cap (what was beyond the cap was read and DISCARDED, never kept)."""
    def __init__(self, returncode: int, stdout: bytes, stderr: bytes, over: bool):
        self.returncode, self.stdout, self.stderr, self.over = returncode, stdout, stderr, over


def _run_capped(argv: list[str], env: dict, limit: int, cap: int, stdin: bytes | None = None) -> _Capped:
    """`subprocess.run` for SQL the census did not write: stdout and stderr are each kept up to `cap` bytes and the rest is drained and dropped, so a
    value of hundreds of megabytes (`SELECT repeat('x', 400000000)`) cannot grow the census' memory. The wall-clock kill is the same (`limit`):
    raises `subprocess.TimeoutExpired` after killing psql."""
    p = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, **({} if stdin is None else dict(stdin=subprocess.PIPE)))
    kept: dict[str, bytearray] = {"out": bytearray(), "err": bytearray()}
    over = {"out": False, "err": False}

    def drain(stream, key):
        while True:
            chunk = stream.read(65536)
            if not chunk:
                return
            room = cap - len(kept[key])
            if room > 0:
                kept[key] += chunk[:room]
            if len(chunk) > room:
                over[key] = True
    threads = [threading.Thread(target=drain, args=(p.stdout, "out"), daemon=True), threading.Thread(target=drain, args=(p.stderr, "err"), daemon=True)]
    if stdin is not None:
        def feed():                              # a script too large for one -c argument is fed on stdin; a psql that exits early closes the pipe
            try:
                p.stdin.write(stdin)
            except (BrokenPipeError, OSError):
                pass
            finally:
                try:
                    p.stdin.close()
                except OSError:
                    pass
        threads.append(threading.Thread(target=feed, daemon=True))
    for t in threads:
        t.start()
    try:
        p.wait(timeout=limit)
    except subprocess.TimeoutExpired:
        p.kill()
        p.wait()
        for t in threads:
            t.join(5)
        raise
    for t in threads:
        t.join(30)
    return _Capped(p.returncode, bytes(kept["out"]), bytes(kept["err"]), over["out"])


def _psql_run(cmds: list[str], sep: str, limit: int, width: int | None, quiet: bool = False, label: int = 0, verbose: bool = False,
              cap: int | None = None, via_stdin: bool = False) -> list[list[str]]:
    """The ONE psql subprocess runner: `cmds` are sent as separate `-c` commands in one session (a single command for every ordinary
    read). Timeout, error and parse handling are shared by `psql` and `psql_read_only`. `label` is the index of the command named in a timeout
    message; `verbose` asks for error text carrying the SQLSTATE (`ERROR:  42501: ...`). `via_stdin` (needs `cap`) sends the same commands as ONE
    script on psql's stdin (each command ends `;` + newline) instead of separate `-c` arguments, for a command past the OS limit of one argument;
    the caller guarantees the large text sits inside a dollar-quoted body, which psql's scanner passes through untouched (no backslash command, no
    variable interpolation)."""
    env = dict(os.environ)
    env.setdefault("PGCONNECT_TIMEOUT", "10")
    argv = ["psql", "-qtAX" if quiet else "-tAX", "-F", sep, "-v", "ON_ERROR_STOP=1"] + (["-v", "VERBOSITY=verbose"] if verbose else [])
    script = None
    if via_stdin:
        if cap is None:
            raise Unknown("psql stdin script requires the capped runner")
        script = ("".join(c + ";\n" for c in cmds)).encode("utf-8")
    else:
        for c in cmds:
            argv += ["-c", c]
    try:
        # bytes, decoded here: `text=True` would translate a lone CR (or CRLF) inside a value into a newline
        p = subprocess.run(argv, capture_output=True, env=env, timeout=limit) if cap is None else _run_capped(argv, env, limit, cap, script)
    except subprocess.TimeoutExpired as exc:
        raise CheckTimeout(f"client-side timeout after {limit}s (psql killed): "
                           f"{' '.join(cmds[label].split())[:120]}") from exc
    if p.returncode != 0:
        err = p.stderr.decode("utf-8", errors="replace")
        raise Unknown((err.strip().splitlines() or ["psql failed"])[0][:400])
    if cap is not None and p.over:
        raise ReadError(f"psql output exceeds the {cap}-byte cap; not read")
    try:
        out = p.stdout.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ReadError(f"psql output is not valid UTF-8: {exc}") from exc
    return parse_psql_output(out, sep, width)


def psql(sql: str, sep: str = "\x1f", timeout: int | None = None, width: int | None = None) -> list[list[str]]:
    limit = timeout if timeout is not None else PSQL_TIMEOUT_SECONDS
    return _psql_run([sql], sep, limit, width)


def _unique_dollar_tag(prefix: str, *texts: str) -> str:
    """A dollar-quote tag such that, scanning `texts` followed by the closing delimiter `$tag$`, the FIRST occurrence of `$tag$` is the closing one (the
    text neither contains the delimiter nor ends in a prefix of it that the closing `$` would complete). Needs no SQL lexer: the text is data and
    cannot terminate its own quotation."""
    body = "".join(texts)
    for k in range(10_000):
        tag = f"{prefix}{k}"
        d = f"${tag}$"
        if (body + d).find(d) == len(body):           # the FIRST `$tag$` after the opening delimiter is ours (so neither the text nor its edge can close early)
            return tag
    raise Unknown("no free dollar-quote tag")      # unreachable in practice


INTEGRITY_VALUE_CHARS = 200        # the first value travels back truncated to this many characters (its full length too): never the whole value
INTEGRITY_OUTPUT_CAP = 65_536      # psql stdout / stderr kept per run (bytes); the rest is drained and dropped


def _integrity_first_value(rows: list[list[str]]) -> list[list[str]]:
    """The result of `psql_read_only` as `_integrity_holds` reads it: [] for no row, else [[the FIRST column of the first row as text]]. The DO block
    returns `row <length of the value's JSON text> <its first INTEGRITY_VALUE_CHARS characters>` (the value was read from `json_each(row_to_json(r))`,
    which keeps column order), so a 400 MB value costs the census ~250 bytes. A value longer than the prefix comes back as its prefix with a `...`
    marker and its length: it is never a boolean or a number."""
    if not rows or not rows[0] or rows[0][0] == "none":
        return []
    head = rows[0][0]
    m = re.fullmatch(r"row (\d+) (.*)", head, re.S)
    if not m:
        raise ReadError(f"unrecognised integrity read-back {head[:40]!r}")
    n, text = int(m.group(1)), m.group(2)
    if n == 0:
        return [[]]
    if n > INTEGRITY_VALUE_CHARS:
        return [[text + f"... ({n} characters)"]]
    try:
        v = json.loads(text, parse_int=str, parse_float=str)
    except ValueError as exc:
        raise ReadError(f"integrity value is not JSON: {exc}") from exc
    return [["t" if v is True else "f" if v is False else "" if v is None else v if isinstance(v, str) else json.dumps(v)]]


def psql_read_only(sql: str, sep: str = "\x1f", timeout: int | None = None, width: int | None = None) -> list[list[str]]:
    """N-99: the read-only path for SQL the census did NOT write itself (a registry-stored `integrity_check_sql`). Server-side guards, each enough on
    its own against a different escape, none relying on a client-side lexer:
      1. the text is wrapped `SELECT * FROM (<sql>\n) AS _integrity LIMIT 1` (the newline keeps a trailing `--` comment from swallowing the `)`):
         inside parentheses a `;`, COMMIT / BEGIN / SET, DML or a second statement is a syntax error at the server;
      2. the wrapped text is the DATA of `FOR r IN EXECUTE $unique-tag$...$unique-tag$` inside a DO block: a dynamic cursor query must be exactly ONE
         statement (a multi-statement plan, or a non-SELECT, is refused by the server), the tags are chosen so the text cannot end its own quotation,
         and a DO block is atomic, so no COMMIT / ROLLBACK / BEGIN in the text can end the surrounding transaction (this closes the one hole of 1: an
         unbalanced `)` that closes the wrapper early and continues with its own statements);
      3. `BEGIN READ ONLY` + `SET LOCAL statement_timeout` (writes, DDL, sequence advances, COPY FROM are refused by the server; a function that
         resets the server timeout leaves only the client-side wall-clock kill, which `_run_capped` enforces);
      4. `SET default_transaction_read_only = on` first, so even a transaction boundary that somehow got through opens the NEXT transaction read-only.
    The first value of the first row comes back through a transaction-local setting whose NAME is a per-run random nonce (the stored text cannot
    predict it), set to the sentinel `none` BEFORE the stored query runs and written AFTER it (so anything the stored query put there is overwritten
    whatever the name), carrying only `row <length> <first 200 characters>`; psql's own output is read through a 64 KiB cap. Separate `-c`
    commands in one session, never PGOPTIONS (a pooled connection refuses startup options), never `-f -` (psql would parse backslash commands).
    OPERATIONAL NOTE: `SET default_transaction_read_only` is SESSION-level: safe on a direct connection (the census reader runs through a local
    127.0.0.1 proxy, not a transaction-mode pooler); behind a transaction-mode pooler it would have to move inside the transaction (guards 1-3 do not
    depend on it). TEXT BEYOND ONE `-c` ARGUMENT (INTEGRITY_ARG_MAX_BYTES, under Linux's 128 KiB per-argument limit) goes on psql's STDIN as the SAME
    commands in the same order, same wrapper, same guards: the stored text is the body of the dollar-quoted DO block (tags chosen so it cannot close its own
    quotation), and psql's scanner does not interpret a backslash or a `:name` inside a dollar-quoted body. Raises `Unknown` past INTEGRITY_MAX_BYTES
    (an explicit cap, fixed, not host-dependent; the cell then reads PARTIAL naming it, never PASS)."""
    if not isinstance(sql, str) or len(sql.encode("utf-8", errors="replace")) > INTEGRITY_MAX_BYTES:
        raise Unknown(f"integrity SQL too large to run via psql (> {INTEGRITY_MAX_BYTES} bytes)")
    stmt = sql.rstrip()
    while stmt.endswith(";"):
        stmt = stmt[:-1].rstrip()
    limit = timeout if timeout is not None else INTEGRITY_TIMEOUT_SECONDS
    ms = max(1, int(limit * 900))
    wrapped = f"SELECT * FROM ({stmt}\n) AS _integrity LIMIT 1"
    guc = "n99.i_" + secrets.token_hex(12)
    tag = _unique_dollar_tag("n99q", wrapped)
    body = ("DECLARE r record; v text := 'none'; BEGIN PERFORM set_config('" + guc + "', 'none', true); FOR r IN EXECUTE $" + tag + "$" + wrapped + "$" + tag + "$ LOOP "
            "v := 'row ' || coalesce((SELECT length(e.value::text)::text || ' ' || left(e.value::text, " + str(INTEGRITY_VALUE_CHARS) + ") "
            "FROM json_each(row_to_json(r)) e LIMIT 1), '0 '); EXIT; END LOOP; PERFORM set_config('" + guc + "', v, true); END")
    outer = _unique_dollar_tag("n99d", body)
    run_sql = "DO $" + outer + "$ " + body + " $" + outer + "$"
    read_back = f"SELECT coalesce(current_setting('{guc}', true), 'none')"
    rows = _psql_run(["SET default_transaction_read_only = on", "BEGIN READ ONLY", f"SET LOCAL statement_timeout = {ms}", run_sql, read_back, "ROLLBACK"],
                     sep, limit, width, quiet=True, label=3, verbose=True, cap=INTEGRITY_OUTPUT_CAP,
                     via_stdin=len(run_sql.encode("utf-8", errors="replace")) > INTEGRITY_ARG_MAX_BYTES)
    return _integrity_first_value(rows)


def scalar(sql: str) -> str | None:
    r = psql(sql)
    return r[0][0] if r and r[0] else None


# ─────────────────────── N-99: a declared integrity_check_sql must HOLD for Build.completion to PASS ───────────────────────
# Convention (asset_runner.py `_probe_asset`, the engine's own definition; this is its one census-side restatement): the SQL is ONE statement
# run with NO bind parameters; healthy = the FIRST column of the FIRST row is truthy; no row, a NULL, an error = unhealthy. The SQL is
# registry-stored text the census did not write, so it is guarded THREE independent ways, none of which trusts the others:
#   1. `integrity_sql_problem` (a conservative lexer + closed allow-list; refuses what it cannot read exactly);
#   2. `psql_read_only` runs it ONLY wrapped as a subquery, `SELECT * FROM (<sql>\n) AS _integrity LIMIT 1`: the SERVER's parser then rejects
#      a `;`, a COMMIT / BEGIN / SET, DML or a second statement as a syntax error whatever the lexer in (1) missed;
#   3. the session is `SET default_transaction_read_only = on` + `BEGIN READ ONLY`: even a transaction boundary that somehow got through the
#      parser opens the next transaction read-only, and a write / sequence advance / DDL is refused by the server.
INTEGRITY_ARG_MAX_BYTES = 120_000  # < Linux MAX_ARG_STRLEN (128 KiB) for ONE psql -c argument: past this the SAME wrapped commands go on psql's stdin (host-independent)
INTEGRITY_MAX_BYTES = 1_000_000    # the explicit cap on a stored integrity SQL (ga_structural's is ~208 KB): past it the run is refused, never attempted
_INTEGRITY_WRITE_WORDS = frozenset({"insert", "update", "delete", "merge", "into", "share"})   # data-modifying CTE, SELECT INTO, row locks
_INTEGRITY_WRITE_FUNCS = frozenset({"nextval", "setval", "currval", "lastval", "set_config", "dblink", "query_to_xml", "query_to_xml_and_xmlschema",
                                    "cursor_to_xml", "table_to_xml", "schema_to_xml", "database_to_xml", "lowrite", "lo_import", "lo_export",
                                    "lo_create", "lo_creat", "lo_unlink", "lo_put", "lo_from_bytea", "lo_truncate", "lo_open", "lo_close",
                                    "ts_stat", "ts_rewrite", "setseed", "txid_current", "current_query", "gin_clean_pending_list"})
# prefixes of functions that change physical state or run SQL from a string even inside a READ ONLY transaction: index maintenance (brin_summarize_*,
# brin_desummarize_range, gin_clean_pending_list), the contrib index / page inspectors, advisory locks, notifications, large objects, dblink
_INTEGRITY_REFUSED_PREFIXES = ("lo_", "dblink", "pg_advisory", "pg_notify", "brin_", "gin_", "gist_", "bt_", "hash_", "heap_", "pgstat", "pgrowlocks")
_INTEGRITY_PG_FUNCS_OK = frozenset({"pg_typeof", "pg_column_size", "pg_relation_size", "pg_table_size", "pg_total_relation_size",
                                    "pg_size_pretty", "pg_input_is_valid"})   # every other pg_* call is refused (pg_sleep too); pg_get_* (catalog readers) is allowed


def _ident_char(ch: str) -> bool:
    """Postgres' identifier-continuation set: ASCII letters / digits / `_` / `$`, and EVERY non-ASCII character (a byte >= 0x80)."""
    return (ch.isascii() and (ch.isalnum() or ch in "_$")) or ord(ch) >= 128


def _integrity_mask(sql: str) -> str:
    """LENGTH-PRESERVING masked copy of `sql` (index i of the result is index i of the text): a comment becomes spaces; a string literal or a
    dollar-quoted string (delimiters included) becomes `'` + spaces + `'`; a quoted identifier becomes `"` + `Q`s + `"`. So a keyword or `;` inside
    text is never read as SQL, and a position found in the mask is a position in the text. Fidelity to Postgres' lexer is conservative: a `--`
    comment ends at `\\n` OR `\\r`; a `$` after any identifier character (including a digit, `$` and ANY non-ASCII character) is NOT a dollar-quote
    opener and is refused as ambiguous; outside literals, comments and dollar bodies a carriage return, a non-ASCII character, a backslash, a NUL
    and an unquoted `U&"` are refused. Raises `Unknown` (the reason) on any of these and on an unterminated literal / comment / quote."""
    out: list[str] = []
    i, n = 0, len(sql)
    if "\x00" in sql:
        raise Unknown("contains a NUL character")
    while i < n:
        c = sql[i]
        if c == "-" and sql[i:i + 2] == "--":
            j = i
            while j < n and sql[j] not in "\n\r":
                j += 1
            out.append(" " * (j - i))
            i = j
        elif c == "/" and sql[i:i + 2] == "/*":
            depth, j = 1, i + 2
            while j < n and depth:
                if sql[j:j + 2] == "/*":
                    depth, j = depth + 1, j + 2
                elif sql[j:j + 2] == "*/":
                    depth, j = depth - 1, j + 2
                else:
                    j += 1
            if depth:
                raise Unknown("unterminated /* comment")
            out.append(" " * (j - i))
            i = j
        elif c == "'":
            esc = i > 0 and sql[i - 1] in "Ee" and (i < 2 or not _ident_char(sql[i - 2]))
            j = i + 1
            while True:
                if j >= n:
                    raise Unknown("unterminated string literal")
                if esc and sql[j] == "\\":
                    j += 2
                    continue
                if sql[j] == "'":
                    if sql[j + 1:j + 2] == "'":
                        j += 2
                        continue
                    break
                j += 1
            out.append("'" + " " * (j - i - 1) + "'")
            i = j + 1
        elif c == '"':
            if sql[max(0, i - 2):i].lower() == "u&":
                raise Unknown('contains a Unicode-escaped identifier (U&"...")')
            j = i + 1
            while True:
                if j >= n:
                    raise Unknown("unterminated quoted identifier")
                if sql[j] == '"':
                    if sql[j + 1:j + 2] == '"':
                        j += 2
                        continue
                    break
                j += 1
            out.append('"' + "Q" * (j - i - 1) + '"')
            i = j + 1
        elif c == "$":
            if i > 0 and _ident_char(sql[i - 1]):
                raise Unknown("a '$' follows an identifier character (ambiguous dollar-quote / identifier); refused")
            m = re.match(r"\$([A-Za-z_][A-Za-z0-9_]*)?\$", sql[i:i + 400])
            if m:
                tag = m.group(0)
                j = sql.find(tag, i + len(tag))
                if j < 0:
                    raise Unknown(f"unterminated dollar-quoted string {tag}")
                out.append("'" + " " * (j + len(tag) - i - 2) + "'")
                i = j + len(tag)
            else:
                out.append(c)
                i += 1
        elif c == "\r":
            raise Unknown("contains a carriage return outside a string literal")
        elif c == "\\":
            raise Unknown("contains a backslash outside a string literal")
        elif ord(c) >= 128:
            raise Unknown("contains a non-ASCII character outside a string literal or comment")
        else:
            out.append(c)
            i += 1
    return "".join(out)


def _integrity_statement(sql) -> tuple[str | None, str]:
    """(reason | None, the statement text to run). The text is `sql` cut at its single trailing `;` (anything after it is whitespace or comment,
    dropped). The reason is None only for a single, parenthesis-balanced SELECT / WITH statement that passes the allow-list; the text is then
    safe to hand to `psql_read_only`, which wraps it as a subquery (the server's own parser is the second reader of every rule here)."""
    if not isinstance(sql, str) or not sql.strip():
        return "integrity_check_sql is blank", ""
    if len(sql.encode("utf-8", errors="replace")) > INTEGRITY_MAX_BYTES:
        return f"integrity SQL too large to run via psql ({len(sql.encode('utf-8', errors='replace'))} bytes > {INTEGRITY_MAX_BYTES})", ""
    try:
        m = _integrity_mask(sql)
    except Unknown as exc:
        return f"not parseable ({exc}); refused", ""
    semis = [k for k, ch in enumerate(m) if ch == ";"]
    cut = sql
    if semis:
        if m[semis[0]:].replace(";", "").strip():
            return "more than one statement (a ';' outside a string/comment with SQL after it); only a single SELECT/WITH is run", ""
        cut, m = sql[:semis[0]], m[:semis[0]]
    body = m.strip()
    if not body:
        return "integrity_check_sql holds no statement", ""
    depth = 0
    for ch in body:
        depth += (ch == "(") - (ch == ")")
        if depth < 0:
            return "unbalanced parentheses (a ')' closes more than was opened); refused", ""
    if depth:
        return "unbalanced parentheses (a '(' is never closed); refused", ""
    first = re.match(r"[\s(]*([A-Za-z_]+)", body)
    if not first or first.group(1).lower() not in ("select", "with"):
        return f"not a SELECT/WITH statement (starts with {body[:20]!r})", ""
    if re.search(r'"Q*"\s*\(', body) or re.search(r'\.\s*"Q*"', body):
        return "calls or qualifies a QUOTED identifier (a quoted function name hides what is called); refused", ""
    words = re.findall(r"[A-Za-z_][A-Za-z0-9_]*", body)
    bad = sorted({w.lower() for w in words if w.lower() in _INTEGRITY_WRITE_WORDS})
    if bad:
        return f"contains {', '.join(w.upper() for w in bad)} (data-modifying CTE, SELECT INTO or a row lock); read-only SELECT/WITH only", ""
    for fn in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\(", body):
        f = fn.lower()
        if f in _INTEGRITY_WRITE_FUNCS or f.startswith(_INTEGRITY_REFUSED_PREFIXES) or (
                f.startswith("pg_") and f not in _INTEGRITY_PG_FUNCS_OK and not f.startswith("pg_get_")):
            return f"calls {f}(), a function that writes, locks or leaves the read-only transaction; refused", ""
    return None, cut


def integrity_sql_problem(sql) -> str | None:
    """None when `sql` is a single read-only SELECT/WITH statement by the conservative lexer and closed allow-list of `_integrity_statement`
    (exactly one statement; first token SELECT / WITH; balanced parentheses; no INSERT/UPDATE/DELETE/MERGE/INTO/SHARE word; no call to a
    function known to write or lock, no quoted function name; no oversize text); else the reason it is refused (never run). A user-defined
    volatile function cannot be enumerated here: the wrapped-subquery form and the read-only session of `psql_read_only` are the server-side guards."""
    return _integrity_statement(sql)[0]


def _integrity_holds(rows: list[list[str]]) -> tuple[bool, str]:
    """(holds, what it returned) for one result: the engine's convention (first column of the first row, truthy), with the census's stricter
    readings — a value that is neither a Postgres boolean nor a FINITE number is NOT healthy (the engine's `bool("x")` and `bool(nan)` would call
    it so), and a value spanning several lines is not a scalar. The wrapped statement returns at most ONE row, so more than one line of output
    can only be a value containing a newline."""
    if not rows or not rows[0]:
        return False, "returned no rows"
    if len(rows) > 1:
        return False, "the first value spans several lines (not a boolean or a number)"
    if "\n" in rows[0][0] or "\r" in rows[0][0]:
        return False, "the first value spans several lines (not a boolean or a number)"
    v = rows[0][0].strip()
    low = v.lower()
    shown = repr(v if len(v) <= 120 else v[:120] + "...")          # never a whole value in the census text (a 10 MB string must not become a 10 MB cell)
    if low in ("t", "true"):
        return True, f"first column of the first row = {shown}"
    if low in ("f", "false"):
        return False, f"first column of the first row = {shown}"
    if v == "":
        return False, "first column of the first row is empty (NULL or an empty string)"
    try:
        num = float(v)
    except ValueError:
        return False, f"first column of the first row = {shown}, which is neither a boolean nor a number"
    if not math.isfinite(num):
        return False, f"first column of the first row = {shown}, which is not a finite number"
    return num != 0.0, f"first column of the first row = {shown}"


_PERMISSION_DENIED = re.compile(r"^ERROR:\s+42501:\s+permission denied\b", re.I)


_DENIED_OBJECT = re.compile(r"permission denied for (materialized view|function|table|view|schema|sequence|relation)\s+(\"?[\w.$]+\"?)", re.I)


def denied_object(detail: str) -> str | None:
    """The object a SQLSTATE 42501 message names (`permission denied for function chart_identity` -> `function chart_identity`); None when the
    message does not name one. Pure; used only to say WHICH object the census role may not read."""
    m = _DENIED_OBJECT.search(detail or "")
    return f"{m.group(1).lower()} {m.group(2)}" if m else None


def _integrity_outcome(sql: str) -> dict:
    """The ONE place a registry-stored integrity_check_sql is run and graded. Returns dict(state, detail, sha, secs) with state one of
    `holds` | `fails` | `refused` (never run) | `unrunnable` (oversize / error / timeout / unreadable) | `not_measurable` (the census role lacks
    a privilege the SQL needs: SQLSTATE 42501). `sha` is the first 12 hex of sha256(sql) and `secs` the elapsed seconds, both for the audit trail.
    Never raises: a SQL that cannot be run is an outcome, never an exception out of the census."""
    t0 = time.monotonic()
    sha = hashlib.sha256(sql.encode("utf-8", errors="replace")).hexdigest()[:12] if isinstance(sql, str) else "none"

    def done(state, detail):
        return dict(state=state, detail=detail, sha=sha, secs=round(time.monotonic() - t0, 2))
    try:
        why, _stmt = _integrity_statement(sql)
        if why is not None:
            return done("unrunnable" if why.startswith("integrity SQL too large") else "refused", why)
        rows = psql_read_only(_stmt)
    except Exception as exc:                    # Unknown / CheckTimeout / ReadError, and any runner surprise: degrade THIS check only
        msg = " ".join(str(exc).split())[:240]
        if isinstance(exc, Unknown) and _PERMISSION_DENIED.match(msg):
            return done("not_measurable", msg)
        return done("unrunnable", f"{type(exc).__name__}: {msg}")
    ok, got = _integrity_holds(rows)
    return done("holds" if ok else "fails", got)


def _completion_integrity(rec: dict, r: dict) -> dict:
    """N-99 (Build.completion rev 3): `rec` is a Build.completion record the count/record comparison has just graded PASS. When the asset
    DECLARES an integrity_check_sql (`r['integrity_sql']` is not None) that SQL must also hold, else the cell reads PARTIAL naming which
    failed; one the census role is not permitted to read (SQLSTATE 42501) reads NO_DETECTOR (not measurable, not a verdict on the data). An asset
    with no declared integrity_check_sql returns `rec` untouched (zero move). The text carries sha256(sql)[:12] and the elapsed seconds, so a
    swapped or deleted SQL is visible in the census output."""
    sql = r.get("integrity_sql")
    if rec.get("v") != PASS or sql is None:
        return rec
    o = _integrity_outcome(sql)
    audit = f"[integrity_check_sql sha256:{o['sha']}, {o['secs']}s]"
    if o["state"] == "holds":
        return dict(rec, measured=rec["measured"] + f"; the declared integrity_check_sql holds ({o['detail']}) {audit}")
    if o["state"] == "not_measurable":
        obj = denied_object(o["detail"])
        return dict(v=NO_DET, measured=f"NO_DETECTOR — integrity not measurable under the census role: {o['detail']}; "
                                       f"denied object: {obj or 'not named by the server message'}; the asset's integrity SQL needs "
                                       "objects the census role may not read. Declared way to measure it: the engine runs this same integrity_check_sql at "
                                       "build time under the runner role (asset_runner._probe_asset), which is where it is measured; to make it "
                                       "census-measurable, Track I: rewrite the check to need neither charts nor the identity function; do NOT widen the "
                                       f"census role (it is NOT widened, and this is not a verdict on the data) {audit}; counts: {rec['measured']}")
    what = {"fails": "does NOT hold", "refused": "was REFUSED (never run)", "unrunnable": "could NOT be run"}[o["state"]]
    return dict(v=PARTIAL, measured=f"{rec['measured']}; but the declared integrity_check_sql {what}: {o['detail']} {audit} — count equality alone "
                                    "is not a completion when the asset declares an integrity check (N-99)")



# ─────────────────────── N-150: the declared produced-table set for Build.completion (rev 4) ───────────────────────
# The orchestrator's own bookkeeping tables are written by the build machinery around a writer, never produced by it: never an "undeclared extra".
PRODUCED_SET_HOPS = 6      # deeper than Idem.pattern's IDEM_DELEGATION_HOPS: a cut chain would make every declared set unprovable (ga_dashas reaches a pure verifier three hops down)
BOOKKEEPING_TABLES = frozenset({"asset_throughput", "build_runs", "build_run_assets", "build_substep_progress", "asset_provenance_receipts"})


def produced_set_written(aid: str, files: list[str]) -> dict:
    """What the writer scan finds the asset's code WRITING: `written` (tables it INSERTs / upserts / DELETEs / TRUNCATEs, bookkeeping tables excluded), `update_only` (tables it only UPDATEs), `delete_only` (tables it only DELETEs from: touched, never produced) and
    `complete` (False when a delegation chain was cut or a statement's table could not be named: the set is then not proven). The same scan Idem.pattern runs (`_delegation_scope`, `_write_facts`)."""
    units, beyond = _delegation_scope(aid, files, hops=PRODUCED_SET_HOPS)
    facts = _write_facts(units)
    wrote = {x[0] for k in ("replace", "upsert", "insert") for x in facts[k]} - BOOKKEEPING_TABLES
    upd = {x[0] for x in facts["update"]} - wrote - BOOKKEEPING_TABLES
    adds = {x[0] for k in ("upsert", "insert") for x in facts[k]}
    dele = {x[0] for x in facts["replace"]} - adds - {x[0] for x in facts["update"]} - BOOKKEEPING_TABLES      # only DELETEd / TRUNCATEd: touched, never produced
    return dict(written=sorted(wrote), update_only=sorted(upd), delete_only=sorted(dele), complete=not (beyond or facts["dynamic"]))


def produced_set_counts(decl: list, chart_id: str) -> list:
    """Each declared table's row count, read-only through the census's own runner (`psql`, as `live_counts`): [(table, filter, n)] in declaration order. A table carrying `chart_id` is counted for
    the census chart, a global one whole (the count_sql convention); a declared filter is `AND "column" = 'value'`. Raises `Unknown` when a table cannot be counted (absent, malformed)."""
    names = [d["table"] for d in decl]
    if not all(isinstance(t, str) and _D1_SQL_IDENT.fullmatch(t) for t in names):
        raise Unknown(f"produced_set_counts: malformed table name(s) {names!r}")
    lit = ",".join("'" + t + "'" for t in dict.fromkeys(names))
    scoped = {r[0] for r in psql("SELECT DISTINCT table_name FROM information_schema.columns WHERE table_schema = 'public' AND column_name = 'chart_id' "
                                 f"AND table_name IN ({lit})")}
    if not re.fullmatch(r"[0-9a-fA-F-]{36}", chart_id) or chart_id.startswith(_PHANTOM_CHART_PREFIX):
        raise Unknown(f"chart scope {chart_id!r} is not a usable chart uuid")
    out = []
    for d in decl:
        t, f = d["table"], d.get("filter")
        conds = ([f"chart_id = '{chart_id}'"] if t in scoped else []) + ([f"\"{f['column']}\" = '{f['equals'].replace(chr(39), chr(39) * 2)}'"] if f else [])
        if f and not _D1_SQL_IDENT.fullmatch(f["column"]):
            raise Unknown(f"produced_set_counts: malformed filter column {f['column']!r}")
        v = scalar(f"SELECT count(*)::text FROM \"{t}\"" + (" WHERE " + " AND ".join(conds) if conds else ""))
        if v is None or not v.strip().isdigit():
            raise Unknown(f"produced_set_counts: {t} returned {v!r}, not a count")
        out.append((t, f, int(v)))
    return out


def produced_set_reading(aid: str, decl: list, files: list[str], chart_id: str, raw=None) -> dict:
    """The Build.completion comparison figure for an asset that declares `produced_tables`: `total` = the SUM over the declared tables the writer does not merely UPDATE, `parts` (every declared
    table, counted), `excluded` (declared UPDATE-only tables), `extra` (tables the writer writes that the set does not name), `complete` (the scan read the whole scope). `error` is set, and the
    rest absent, when the counts cannot be read. `raw` (the declaration's own `produced_tables` entries) supplies the `why` notes a mismatch is explained by."""
    try:
        counts = produced_set_counts(decl, chart_id)
        w = produced_set_written(aid, files) if files else dict(written=[], update_only=[], delete_only=[], complete=False)      # no recognised writer file: nothing was scanned, so no extra table is ruled out
    except Unknown as exc:
        return dict(error=str(exc))
    upd = (set(w["update_only"]) | set(w.get("delete_only") or ())) if w["complete"] else set()      # a declared table the writer only UPDATEs or DELETEs from is touched, not produced: read, not summed
    parts = [dict(table=t, filter=f, rows=n, counted=t not in upd) for t, f, n in counts]
    names = {d["table"] for d in decl}
    notes = [f"{d['table']}{'[' + d['filter']['column'] + '=' + d['filter']['equals'] + ']' if d.get('filter') else ''}: {d['why']}" for d in (raw or []) if isinstance(d, dict) and d.get("why")]
    return dict(notes=notes, total=sum(p["rows"] for p in parts if p["counted"]), parts=parts, excluded=sorted(p["table"] for p in parts if not p["counted"]),
                extra=sorted(t for t in set(w["written"]) | set(w["update_only"]) if t not in names), complete=w["complete"], error=None,
                unproven=([] if w["complete"] else sorted(n for n in names if n not in set(w["written"]) | set(w["update_only"]))),
                )


def produced_set_text(pr: dict) -> str:
    body = " + ".join(f"{p['table']}{'[' + p['filter']['column'] + '=' + p['filter']['equals'] + ']' if p['filter'] else ''}={p['rows']}" for p in pr["parts"] if p["counted"])
    return (f"declared produced-table set: {body or 'no counted table'} = {pr['total']}"
            + (f"; declared but only UPDATEd or DELETEd from by the writer (touched, not produced), not counted: {', '.join(pr['excluded'])}" if pr["excluded"] else ""))


def produced_set_verdict(rec: dict, pr: dict) -> dict:
    """The writer-scan clause of the declared produced-table set, applied to a Build.completion record BEFORE the integrity step (so an undeclared table is never hidden by it): a table the writer
    writes that the declaration does not name FAILs a PASS / PARTIAL / FAIL record (never a tolerance; a record that is not a verdict, NO_DETECTOR / ERRORED / N/A, only carries the text); a PASS
    from a writer scope the scan could not read fully is capped at PARTIAL; and a sum MISMATCH read from an unreadable scope, where a declared table is not proven written (so the sum may overcount
    a table the writer only updates), is capped at PARTIAL, never a false FAIL."""
    v = rec.get("v")
    if v not in (PASS, PARTIAL, FAIL):
        if pr["extra"] and v in (NO_DET, ERRORED):
            return dict(rec, measured=f"{rec['measured']}; the writer also writes {', '.join(pr['extra'])}, which the declared produced-table set does not name (an undeclared extra table)")
        return rec
    if pr["extra"]:
        return dict(v=FAIL, measured=f"{rec['measured']}; the writer also writes {', '.join(pr['extra'])}, which the declared produced-table set does not name (an undeclared extra table)")
    if v == FAIL and "disagrees with" in rec.get("measured", "") and not pr.get("unproven") and pr.get("notes"):
        return dict(rec, measured=f"{rec['measured']}; declared-set notes (the declaration's own reasons for its tables): {' | '.join(pr['notes'])}")      # a mismatch is explained by what the declaration says about each table
    if v == FAIL and pr.get("unproven") and "disagrees with" in rec.get("measured", ""):
        return dict(v=PARTIAL, measured=f"{rec['measured']}; but the writer scan could not read the whole writer scope and {', '.join(pr['unproven'])} is not proven written (it may only be updated), so the declared sum may "
                                        "overcount: the mismatch is not shown to be a defect")
    if v == PASS and not pr["complete"]:
        return dict(v=PARTIAL, measured=f"{rec['measured']}; but the writer scan could not read the whole writer scope (a cut delegation chain or an unnamed table), so that no undeclared "
                                        "table is written is not proven")
    return rec


# ─────────────────────────── code-side scans ───────────────────────────

def _writer_files() -> list[Path]:
    """Writer modules only. `__init__.py` is the FRAMEWORK — it defines @register and documents what a
    writer must not do, so scanning it as a writer reports the framework's own docstring as a violation.
    The first run did exactly that."""
    if not WRITERS.is_dir():
        raise Unknown(f"writers directory not found: {WRITERS}")
    return [f for f in sorted(WRITERS.glob("*.py")) if f.name != "__init__.py"]


_PARSED: dict[tuple[str, str], ast.AST] = {}


def _parse(f: Path):
    """R20: cached per (path, content) — delegation-following reads the same seeder/helper modules for
    many assets; a changed file re-parses (the key is its text, not its mtime)."""
    text = f.read_text(encoding="utf-8", errors="replace")
    key = (str(f), text)
    if key not in _PARSED:
        try:
            _PARSED[key] = ast.parse(text, filename=str(f))
        except SyntaxError as exc:
            raise Unknown(f"{f.name}: unparseable ({exc})") from exc
    return _PARSED[key]


def _register_id(dec: ast.expr, consts: dict[str, str] | None = None) -> str | None:
    """@register('<asset_id>') as a real decorator — via the AST, so a docstring that MENTIONS
    `@register('bg_x')` is not mistaken for one. The regex version made that mistake twice.

    R43 (handverify L4/L5): `@register(ASSET_ID)` — a module-level string constant — is resolved
    through `consts` (the module's own top-level `NAME = '<str>'` assignments). An unresolvable name
    is not guessed: it returns None, exactly like any other decorator."""
    if isinstance(dec, ast.Call) and isinstance(dec.func, ast.Name) and dec.func.id == "register" and dec.args:
        a = dec.args[0]
        if isinstance(a, ast.Constant) and isinstance(a.value, str):
            return a.value
        if isinstance(a, ast.Name) and consts and a.id in consts:
            return consts[a.id]
    return None


def _module_constants(tree: ast.AST) -> dict[str, str]:
    """R43: a module's top-level string constants (`ASSET_ID = "mi_bhara"`, annotated or not). A name
    assigned more than once, or to anything but one string literal, is dropped — never guessed."""
    seen: dict[str, list] = {}
    for node in getattr(tree, "body", []):
        if isinstance(node, ast.Assign):
            for tg in node.targets:
                if isinstance(tg, ast.Name):
                    seen.setdefault(tg.id, []).append(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.value is not None:
            seen.setdefault(node.target.id, []).append(node.value)
    return {k: v[0].value for k, v in seen.items()
            if len(v) == 1 and isinstance(v[0], ast.Constant) and isinstance(v[0].value, str)}


def _writer_path(name: str) -> Path:
    """R43: a writer-scan name is relative to writers/ (a module, or `<pkg>/<module>.py`) or, for a
    module reached through a writers/ shim's import, relative to the python sidecar root."""
    p = WRITERS / name
    return p if p.exists() else SIDECAR / name


def _first_party_imports(tree: ast.AST, here: Path) -> list[Path]:
    """R43: the first-party modules a writers/ module imports (`from services.ka_tulana.writer import
    KaTulanaWriter`, relative imports inside a package). The engine discovers writers by importing
    each writers/ module, and that import runs the imported modules' `@register` decorators — the ten
    L3 shims register this way. Only modules that exist under the sidecar are returned."""
    out: list[Path] = []
    for n in ast.walk(tree):
        mods = []
        if isinstance(n, ast.ImportFrom):
            base = SIDECAR if not n.level else here.parents[n.level - 1]
            mods.append((base, n.module or ""))
        elif isinstance(n, ast.Import):
            mods += [(SIDECAR, a.name) for a in n.names]
        for base, mod in mods:
            parts = [x for x in mod.split(".") if x]
            if not parts:
                continue
            for cand in (base.joinpath(*parts).with_suffix(".py"), base.joinpath(*parts, "__init__.py")):
                if cand.is_file() and cand not in out:
                    out.append(cand)
                    break
    return out


def _code_strings(node: ast.AST) -> list[str]:
    """String constants that are NOT docstrings — SQL, not prose."""
    docs = set()
    for n in ast.walk(node):
        if isinstance(n, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            body = getattr(n, "body", [])
            if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \
                    and isinstance(body[0].value.value, str):
                docs.add(id(body[0].value))
    return [n.value for n in ast.walk(node)
            if isinstance(n, ast.Constant) and isinstance(n.value, str) and id(n) not in docs]


_MEMO: dict | None = None      # one measure() run's memo of tree-wide scans that cannot change while it runs (None outside a run: nothing is cached)


def _memoized_run(fn):
    """Decorator for measure(): open a fresh memo for the duration of ONE run (and restore the previous one after), so the writer-tree scans that every asset's R5 block repeats
    (`_writer_modules`, `register_call_mentions`: a full AST walk of every writer module, once per asset and per criterion) are done once per run. Nothing is cached outside a run, so a
    caller that changes the tree between runs, or calls a scan directly, always sees the tree as it is. `functools.wraps` keeps the source and signature of the wrapped function."""
    @functools.wraps(fn)
    def run(*a, **k):
        global _MEMO
        prev, _MEMO = _MEMO, {}
        try:
            return fn(*a, **k)
        finally:
            _MEMO = prev
    return run


def _run_declarations() -> dict:
    """The committed declarations as `load_asset_declarations()` reads them, loaded and validated ONCE per measure() run (three sites of one run asked for the same file: ~0.3 s of a 0.45 s
    run) and handed out as a deep copy, so no site sees another's edit. A DeclarationsError propagates every time (a failed load is not cached)."""
    return copy.deepcopy(_memo(("declarations",), lambda: load_asset_declarations()))


def _memo(key, compute):
    if _MEMO is None:
        return compute()
    if key not in _MEMO:
        _MEMO[key] = compute()
    return _MEMO[key]


def _writer_modules() -> list[tuple[str, Path]]:
    """R43 (memoised per measure() run, see `_memoized_run`): the modules the engine's writer discovery executes; the list is a fresh copy, callers may keep it."""
    return list(_memo(("writer_modules",), _writer_modules_scan))


def _writer_modules_scan() -> list[tuple[str, Path]]:
    """R43: every module the engine's writer discovery executes, as (scan name, path):
    writers/*.py (the framework `__init__.py` excluded), each package directory's modules
    (`ph_rectification/__init__.py`; test directories and caches skipped), and — one level deep —
    the first-party modules those import (`services/ka_tulana/writer.py`). De-duplicated by path:
    a module imported by two shims runs its decorators once."""
    mods: list[tuple[str, Path]] = []
    seen: set[Path] = set()

    def add(name: str, path: Path) -> None:
        rp = path.resolve()
        if rp not in seen:
            seen.add(rp)
            mods.append((name, path))
    for f in _writer_files():
        add(f.name, f)
    for d in sorted(x for x in WRITERS.iterdir() if x.is_dir() and (x / "__init__.py").is_file()
                    and x.name not in ("tests", "__tests__", "__pycache__")):
        for f in sorted(d.glob("*.py")):
            add(f"{d.name}/{f.name}", f)
    for _name, f in list(mods):
        for g in _first_party_imports(_parse(f), f.parent):
            if WRITERS in g.parents and g.parent == WRITERS:
                continue                                    # a writers/ module: already listed
            if g.name == "__init__.py" and g.parent == WRITERS:
                continue                                    # the framework itself
            try:
                add(str(g.relative_to(SIDECAR)), g)
            except ValueError:
                continue
    return mods


def registered_ids(prefix: str) -> dict[str, list[str]]:
    """asset_id -> writer file(s), from real decorators on real classes (R43: literal ids, resolved
    module constants, package writers and shim-imported modules)."""
    out: dict[str, list[str]] = {}
    for name, f in _writer_modules():
        tree = _parse(f)
        consts = _module_constants(tree)
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                for dec in node.decorator_list:
                    rid = _register_id(dec, consts)
                    if rid and rid.startswith(prefix) and name not in out.setdefault(rid, []):
                        out[rid].append(name)
    return out


def register_call_mentions(asset_id: str) -> list[str]:
    """(review fix LOW-2, N-150 R5) The writers/ and sidecar modules (the ones the engine's writer discovery executes, `_writer_modules`) that mention `asset_id` inside ANY `register(` call
    (`register(x)(Cls)`, `@mod.register('id')`, an imported or computed id), or hold a `register(` call whose id argument is not a readable string (a literal or one of the module's own string
    constants): such a call could register the asset though `_register_id` (a class decorator `@register('lit')` / `@register(MODULE_CONST)`) cannot see it, so it is named, never ignored.
    Sorted module names; [] = no such call. Zero today: every `register(` in the discovery set is a class decorator over a literal or a resolved module constant."""
    out: set[str] = set()
    for name, f in _writer_modules():
        for strs, names, consts in _memo(("register_calls", str(f)), lambda f=f: _register_call_facts(f)):
            hit = False
            for a_strs, a_names in zip(strs, names):
                if asset_id in a_strs or any(consts.get(nm) == asset_id for nm in a_names):
                    hit = True
                elif any(nm not in consts for nm in a_names):
                    hit = True                                  # an id the scan cannot read: it may be this one
            if hit:
                out.add(name)
    return sorted(out)


def _register_call_facts(f: Path) -> list:
    """Per `register(` call of one module (`register(x)`, `mod.register(x)`) with at least one argument: ([string constants of each argument], [names of each argument], the module's string
    constants). The asset-independent half of `register_call_mentions` (the full AST walk), computed once per module per run."""
    if not re.search(r"register\s*\(", f.read_text(encoding="utf-8", errors="replace")):
        return []                                         # no `register(...)` call can exist in a module whose text has no `register` followed by `(`: skip the AST walk
    tree = _parse(f)
    consts = _module_constants(tree)
    out = []
    for n in ast.walk(tree):
        if not isinstance(n, ast.Call):
            continue
        fn = n.func
        if not ((isinstance(fn, ast.Name) and fn.id == "register") or (isinstance(fn, ast.Attribute) and fn.attr == "register")):
            continue
        args = list(n.args) + [k.value for k in n.keywords]
        if not args:
            continue
        out.append(([[x.value for x in ast.walk(a) if isinstance(x, ast.Constant) and isinstance(x.value, str)] for a in args],
                    [[x.id for x in ast.walk(a) if isinstance(x, ast.Name)] for a in args], consts))
    return out


def _writer_class(f: Path, asset_id: str) -> ast.ClassDef | None:
    tree = _parse(f)
    consts = _module_constants(tree)
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and any(_register_id(d, consts) == asset_id for d in node.decorator_list):
            return node
    return None


def contract_scan(asset_id: str, files: list[str]) -> tuple[str, list[str]]:
    """Frozen-contract conformance, per registered CLASS rather than per file.

    Calibrated after the first run's false positives: the ONLY hard failures are (a) no WriterBase
    subclass, (b) neither entry point, (c) a real `ctx.db_conn.commit()/close()` CALL, (d) a real SQL
    string that writes `asset_throughput`. Declaring both entry points is a note, not a failure —
    `WriterBase` may define `run()` as the template method that dispatches substeps, and calling that a
    violation would fail a conformant heavy writer."""
    notes: list[str] = []
    if not files:
        # R222 / N2: nothing was scanned — never N/A here. `_measure_contract` decides whether the
        # registry makes this genuinely not-applicable (has_writer=false) or an unmeasured writer.
        return NO_DET, ["no writer file recognised — nothing scanned"]
    found = False
    for name in files:
        f = _writer_path(name)
        cls = _writer_class(f, asset_id)
        if cls is None:
            continue
        found = True
        bases = {b.id for b in cls.bases if isinstance(b, ast.Name)} | \
                {b.attr for b in cls.bases if isinstance(b, ast.Attribute)}
        if "WriterBase" not in bases:
            notes.append(f"{name}: {cls.name} does not subclass WriterBase (bases: {sorted(bases) or 'none'})")
        methods = {m.name for m in cls.body if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef))}
        heavy = {"plan_substeps", "run_substep"} <= methods
        if not heavy and "run" not in methods:
            notes.append(f"{name}: {cls.name} has neither run(ctx) nor plan_substeps+run_substep")
        if heavy and "run" in methods:
            notes.append(f"{name}: {cls.name} declares both entry points (note, not a violation)")
        for n in ast.walk(cls):
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) \
                    and n.func.attr in ("commit", "close") and isinstance(n.func.value, ast.Attribute) \
                    and n.func.value.attr == "db_conn":
                notes.append(f"{name}: {cls.name} calls ctx.db_conn.{n.func.attr}() — the orchestrator owns the transaction")
        for sql in _code_strings(cls):
            if "asset_throughput" in sql and re.search(r"\b(INSERT|UPDATE|DELETE)\b", sql, re.I):
                notes.append(f"{name}: {cls.name} writes asset_throughput — the orchestrator is the sole build-state writer")
    if not found:
        return FAIL, [f"no class decorated @register('{asset_id}') found in {', '.join(files)}"]
    hard = [n for n in notes if "note, not a violation" not in n]
    return (PASS if not hard else FAIL), (notes or ["conformant"])


def _docstring_ids(tree: ast.AST) -> set[int]:
    docs = set()
    for n in ast.walk(tree):
        if isinstance(n, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            body = getattr(n, "body", [])
            if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \
                    and isinstance(body[0].value.value, str):
                docs.add(id(body[0].value))
    return docs


def _module_sequences(tree: ast.AST) -> dict[str, list[str]]:
    """C-KSHETRA: a module's top-level list/tuple literals of table names (`_OWNED_TABLES = (('kala_field',
    None), …)`, annotated or not) -> the first string of each element. Assigned twice -> dropped."""
    seen: dict[str, list] = {}
    for node in getattr(tree, "body", []):
        if isinstance(node, ast.Assign):
            for tg in node.targets:
                if isinstance(tg, ast.Name):
                    seen.setdefault(tg.id, []).append(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.value is not None:
            seen.setdefault(node.target.id, []).append(node.value)
    return {k: out for k, v in seen.items() if len(v) == 1 and (out := _literal_names(v[0]))}


def _literal_names(node: ast.AST) -> list[str]:
    """The table names a literal list/tuple enumerates: each string element, or each tuple element's first
    string. Anything else yields nothing (never guessed)."""
    if not isinstance(node, (ast.List, ast.Tuple)):
        return []
    out = []
    for e in node.elts:
        if isinstance(e, ast.Constant) and isinstance(e.value, str):
            out.append(e.value)
        elif isinstance(e, ast.Tuple) and e.elts and isinstance(e.elts[0], ast.Constant) \
                and isinstance(e.elts[0].value, str):
            out.append(e.elts[0].value)
    return out


def _call_name(c: ast.AST) -> str | None:
    if isinstance(c, ast.Call):
        f = c.func
        return f.id if isinstance(f, ast.Name) else f.attr if isinstance(f, ast.Attribute) else None
    return None


# ─────────── R20 (W2-3): follow writer delegation into the seeder ───────────

# R20: how many cross-module hops `idem_scan` follows from the registered writer class. Hop 1 is the
# module the writer calls into (a seeder `brahmagyan/l0_*.seed_*`, a shared helper
# `bodha_writers/_idempotency.replace_prior_*`, or the adapter target `ga_writers/ga_*_writer.build_*`);
# hop 2 is what THAT calls (the L1 adapters' own `ga_writers/_idempotency.replace_prior_*`). Beyond the
# limit nothing is guessed: a replacement found only deeper reads PARTIAL naming the chain.
IDEM_DELEGATION_HOPS = 2
# The orchestrator framework (@register, WriterBase, WriterResult, SubStep) is never a delegation target.
_FRAMEWORK_MODULES = ("pipeline/orchestrator/__init__.py", "pipeline/orchestrator/writers/__init__.py")
_WRITE_TEXT = re.compile(r"DELETE\s+FROM|TRUNCATE|INSERT\s+INTO|ON\s+CONFLICT|CREATE\s+OR\s+REPLACE", re.I)
_Q = r"(?:ONLY\s+)?(?:public\.)?\"?"
_SQL_DELETE = re.compile(r"DELETE\s+FROM\s+" + _Q + r"([A-Za-z_][A-Za-z_0-9]*|\{\?\})?", re.I)
_SQL_TRUNCATE = re.compile(r"\bTRUNCATE\s+(?:TABLE\s+)?" + _Q + r"([A-Za-z_][A-Za-z_0-9]*|\{\?\})?", re.I)
_SQL_INSERT = re.compile(r"INSERT\s+INTO\s+" + _Q + r"([A-Za-z_][A-Za-z_0-9]*|\{\?\})?", re.I)
_SQL_UPDATE = re.compile(r"\bUPDATE\s+" + _Q + r"([A-Za-z_][A-Za-z_0-9]*)\s+SET\b", re.I)
_SQL_VIEW = re.compile(r"CREATE\s+OR\s+REPLACE\s+(?:MATERIALIZED\s+)?VIEW\s+" + _Q + r"([A-Za-z_][A-Za-z_0-9]*)", re.I)
_ON_CONFLICT = re.compile(r"ON\s+CONFLICT", re.I)
# C-KSHETRA's output-existence probe, widened by R241 to the count form, now CAPTURING the probed table:
# a probe is an OUTPUT probe only when it reads one of the asset's own tables (or a table the scan cannot
# name) — mi_jivanaghatana's `count_chart_lel_events` counts its UPSTREAM life events and is no hold.
_PROBE_SQL = re.compile(r"SELECT\s+(?:EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+" + _Q + r"([A-Za-z_][A-Za-z_0-9]*|\{\?\})"
                        r"|(?:1|count\(\s*\*\s*\))\s+FROM\s+" + _Q + r"([A-Za-z_][A-Za-z_0-9]*|\{\?\})\s+WHERE\s+chart_id)", re.I)



def _rel(p: Path) -> str:
    try:
        return str(p.relative_to(WRITERS))
    except ValueError:
        try:
            return str(p.relative_to(SIDECAR))
        except ValueError:
            return p.name


def _import_map(tree: ast.AST, here: Path) -> dict[str, tuple[Path, str | None]]:
    """R20: every first-party name a module imports — module-level or inside a function (the L1 adapters
    import their builder inside run()) — as local name -> (module file, imported attribute), or
    (module file, None) when the name IS a module (`from services.mi_bhara import db`). Only files that
    exist under the python sidecar; third-party imports resolve to nothing.

    `here` is the DIRECTORY of the importing module; a relative import resolves against the importing module's own package
    (`here` for level 1, its parent for level 2, ...). ONE resolver serves Idem.pattern and the Build.dag reads scan: the
    earlier base (`here.parents[level - 1]`) sat one directory too high, so package re-exports were silently skipped."""
    out: dict[str, tuple[Path, str | None]] = {}

    def mod_file(base: Path, parts: list[str]) -> Path | None:
        for cand in (base.joinpath(*parts).with_suffix(".py") if parts else None,
                     base.joinpath(*parts, "__init__.py")):
            if cand is not None and cand.is_file():
                return cand
        return None

    for n in ast.walk(tree):
        if isinstance(n, ast.ImportFrom):
            if not n.level:
                base = SIDECAR
            else:
                base = here if n.level == 1 else here.parents[n.level - 2]
            parts = [x for x in (n.module or "").split(".") if x]
            for a in n.names:
                sub = mod_file(base, parts + [a.name])
                if sub is not None:
                    out.setdefault(a.asname or a.name, (sub, None))
                    continue
                f = mod_file(base, parts)
                if f is not None:
                    out.setdefault(a.asname or a.name, (f, a.name))
        elif isinstance(n, ast.Import):
            for a in n.names:
                if a.asname:
                    f = mod_file(SIDECAR, a.name.split("."))
                    if f is not None:
                        out.setdefault(a.asname, (f, None))
    return {k: v for k, v in out.items() if not _is_framework(v[0])}


def _is_framework(p: Path) -> bool:
    """The orchestrator itself (asset_runner, runner, …) and the writer framework are never a writer's
    delegate: a `@l2_producer` wrapper importing the runner must not pull the engine into the scope."""
    r = _rel(p)
    return any(r.endswith(m) for m in _FRAMEWORK_MODULES) or r == "__init__.py" or \
        (r.startswith("pipeline/orchestrator/") and not r.startswith("pipeline/orchestrator/writers/"))


def _top_defs(tree: ast.AST) -> dict[str, ast.AST]:
    """A module's top-level functions, classes and assigned names (the SQL constants live there:
    `_INSERT_SQL = \"\"\"INSERT INTO …\"\"\"`), by name — looking through top-level if/try blocks."""
    out: dict[str, ast.AST] = {}

    def walk(body):
        for s in body:
            if isinstance(s, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                out.setdefault(s.name, s)
            elif isinstance(s, ast.Assign):
                for t in s.targets:
                    if isinstance(t, ast.Name):
                        out.setdefault(t.id, s)
            elif isinstance(s, ast.AnnAssign) and isinstance(s.target, ast.Name) and s.value is not None:
                out.setdefault(s.target.id, s)
            elif isinstance(s, (ast.If, ast.Try)):
                walk(s.body)
                walk(getattr(s, "orelse", []))
                for h in getattr(s, "handlers", []):
                    walk(h.body)
    walk(getattr(tree, "body", []))
    return out


def _closure(roots: list[ast.AST], defs: dict[str, ast.AST]) -> list[ast.AST]:
    """R20: the roots plus every top-level definition of the SAME module they reference by name,
    transitively — a module-level helper or SQL constant the writer class uses is part of the writer."""
    out, seen, todo = [], set(), list(roots)
    while todo:
        n = todo.pop()
        if id(n) in seen:
            continue
        seen.add(id(n))
        out.append(n)
        for x in ast.walk(n):
            if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in defs:
                todo.append(defs[x.id])
    return out


def _external_refs(nodes: list[ast.AST], imports: dict) -> list[tuple[Path, str]]:
    """The first-party definitions these nodes reference in OTHER modules: an imported name used
    (`seed_rules(...)`, a decorator `@l2_producer(...)`) or a module attribute (`db.insert_skill_row`)."""
    out: list[tuple[Path, str]] = []
    for n in nodes:
        for x in ast.walk(n):
            ref = None
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id in imports \
                    and imports[x.value.id][1] is None:
                ref = (imports[x.value.id][0], x.attr)
            elif isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in imports \
                    and imports[x.id][1] is not None:
                ref = imports[x.id]
            if ref and ref not in out:
                out.append(ref)
    return out


def _resolve_def(path: Path, name: str) -> tuple[Path, ast.AST, ast.AST] | None:
    """`name` defined in `path`, following package re-exports (`from .x import name`, at most 3)."""
    for _ in range(4):
        tree = _parse(path)
        d = _top_defs(tree).get(name)
        if d is not None and not isinstance(d, (ast.Assign, ast.AnnAssign)):
            return path, tree, d
        nxt = _import_map(tree, path.parent).get(name)
        if not nxt or nxt[1] is None:
            return None
        path, name = nxt
    return None


def _delegation_scope(asset_id: str, files: list[str], hops: int | None = None) -> tuple[list[dict], list[str]]:
    """R20: the code a rebuild of `asset_id` runs, as far as it can be read statically — the registered
    writer CLASS (not its whole module: bo_laksana.py registers two assets, and bo_laksana_rerank must
    not inherit bo_laksana's replacement) plus the same-module definitions it references, then each
    first-party definition that code references in another module, up to `hops` modules away.
    Returns (units, beyond): a unit is dict(rel, tree, nodes, hop, via); `beyond` names each chain the
    hop limit cut whose target module holds write SQL (a module with no DELETE/INSERT/ON CONFLICT text
    cannot hold the replacement, so cutting it loses nothing and is not reported)."""
    hops = IDEM_DELEGATION_HOPS if hops is None else hops
    units: list[dict] = []
    beyond: list[str] = []
    seen: set[tuple[str, str]] = set()
    queue: list[tuple[Path, ast.AST, list[ast.AST], int, str]] = []
    for name in files:
        p = _writer_path(name)
        tree = _parse(p)
        cls = _writer_class(p, asset_id)
        queue.append((p, tree, [cls] if cls is not None else [tree], 0, _rel(p)))
    while queue:
        p, tree, roots, hop, via = queue.pop(0)
        nodes = _closure(roots, _top_defs(tree))
        units.append(dict(rel=_rel(p), path=p, tree=tree, nodes=nodes, hop=hop, via=via))
        for tp, attr in _external_refs(nodes, _import_map(tree, p.parent)):
            r = _resolve_def(tp, attr)
            if r is None:
                continue
            dp, dtree, dnode = r
            key = (str(dp.resolve()), attr)
            if key in seen:
                continue
            seen.add(key)
            chain = f"{via} → {_rel(dp)}:{attr}"
            if hop + 1 > hops:
                if _WRITE_TEXT.search(dp.read_text(encoding="utf-8", errors="replace")):
                    beyond.append(chain)
                continue
            queue.append((dp, dtree, [dnode], hop + 1, chain))
    return units, beyond


_TREE_INFO: dict[int, tuple] = {}


def _sql_texts(unit: dict):
    """(text, line, is_dynamic) for every SQL-bearing string in a unit's nodes — docstrings excluded;
    an f-string's `{X}` resolved to a module constant or the enclosing `for` sequence (one text per
    resolved name), else kept as the marker `{?}`; string concatenation (`a + b`) read as one text."""
    tree = unit["tree"]
    if id(tree) not in _TREE_INFO:                     # once per parsed module, not once per node
        _TREE_INFO[id(tree)] = (tree, _docstring_ids(tree), _module_constants(tree), _module_sequences(tree))
    _, docs, consts, seqs = _TREE_INFO[id(tree)]
    out: list[tuple[str, int]] = []
    done: set[int] = set()

    fn_stack: list = []

    def _str_list(a, depth=0):
        """The string constants of a literal list/tuple, or of a Name bound exactly once (in the enclosing function, else at module level) to one and never mutated; None otherwise."""
        if isinstance(a, (ast.List, ast.Tuple)) and a.elts and all(isinstance(x, ast.Constant) and isinstance(x.value, str) for x in a.elts):
            return [x.value for x in a.elts]
        if isinstance(a, ast.Name) and depth < 3:
            for sc in (([fn_stack[-1]] if fn_stack else []) + [tree]):
                pool = list(tree.body) if sc is tree else list(ast.walk(sc))
                vals = [x.value for x in pool if isinstance(x, ast.Assign) and any(isinstance(t, ast.Name) and t.id == a.id for t in x.targets)]
                if vals:
                    mutated = any((isinstance(x, ast.AugAssign) and isinstance(x.target, ast.Name) and x.target.id == a.id)
                                  or (isinstance(x, ast.Call) and isinstance(x.func, ast.Attribute) and isinstance(x.func.value, ast.Name) and x.func.value.id == a.id
                                      and x.func.attr in ("append", "extend", "insert", "remove", "pop", "clear", "sort", "reverse", "__iadd__"))
                                  for x in ast.walk(sc))
                    return None if len(vals) != 1 or mutated else _str_list(vals[0], depth + 1)
        return None

    def _joined(e, depth=0):
        """`', '.join(<literal list | name bound to one>)`, or a name bound once to such a join: the joined text (a column list built from a literal list), else None."""
        if isinstance(e, ast.Name) and fn_stack and depth < 3:
            vals = [x.value for x in ast.walk(fn_stack[-1]) if isinstance(x, ast.Assign) and any(isinstance(t, ast.Name) and t.id == e.id for t in x.targets)]
            return _joined(vals[0], depth + 1) if len(vals) == 1 else None
        if (isinstance(e, ast.Call) and isinstance(e.func, ast.Attribute) and e.func.attr == "join" and isinstance(e.func.value, ast.Constant)
                and isinstance(e.func.value.value, str) and len(e.args) == 1 and not e.keywords):
            items = _str_list(e.args[0])
            if items is None:                          # SS residual: `", ".join(["%s"] * len(COLS))`: one placeholder per column of a literal list (the VALUES group of a column-loop INSERT)
                a0 = e.args[0]
                if (isinstance(a0, ast.BinOp) and isinstance(a0.op, ast.Mult) and isinstance(a0.left, ast.List) and len(a0.left.elts) == 1
                        and isinstance(a0.left.elts[0], ast.Constant) and isinstance(a0.left.elts[0].value, str)
                        and isinstance(a0.right, ast.Call) and isinstance(a0.right.func, ast.Name) and a0.right.func.id == "len"
                        and len(a0.right.args) == 1 and not a0.right.keywords):
                    names = _str_list(a0.right.args[0])
                    if names:
                        items = [a0.left.elts[0].value] * len(names)
            return None if items is None else [e.func.value.value.join(items)]
        return None

    def parts_of(n, loops) -> list[str] | None:
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            return [n.value]
        if isinstance(n, ast.JoinedStr):
            texts = [""]
            for v in n.values:
                if isinstance(v, ast.Constant) and isinstance(v.value, str):
                    texts = [t + v.value for t in texts]
                elif isinstance(v, ast.FormattedValue):
                    e = v.value
                    names = (loops.get(e.id) or ([consts[e.id]] if e.id in consts else None)) \
                        if isinstance(e, ast.Name) else None
                    if names is None:
                        names = _joined(e)           # E5.7: a column list `", ".join(COLUMNS)` the writer builds from a literal list
                    texts = [t + x for t in texts for x in (names or ["{?}"])]
            return texts
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Add):
            a, b = parts_of(n.left, loops), parts_of(n.right, loops)
            if a is not None and b is not None:
                return [x + y for x in a for y in b]
        return None

    def visit(n, loops):
        pushed = isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        if pushed:
            fn_stack.append(n)
        try:
            _visit(n, loops)
        finally:
            if pushed:
                fn_stack.pop()

    def _visit(n, loops):
        if isinstance(n, (ast.For, ast.AsyncFor)):
            it = n.iter
            names = _literal_names(it) or (seqs.get(it.id, []) if isinstance(it, ast.Name) else [])
            tg = n.target.elts[0] if isinstance(n.target, ast.Tuple) and n.target.elts else n.target
            if names and isinstance(tg, ast.Name):
                loops = dict(loops, **{tg.id: names})
        if id(n) not in done and id(n) not in docs and isinstance(n, (ast.Constant, ast.JoinedStr, ast.BinOp)):
            texts = parts_of(n, loops)
            if texts is not None:
                for x in ast.walk(n):
                    done.add(id(x))
                out.extend((t, getattr(n, "lineno", 0)) for t in texts)
                return
        for c in ast.iter_child_nodes(n):
            visit(c, loops)
    for node in unit["nodes"]:
        visit(node, {})
    return out


def _write_facts(units: list[dict]) -> dict[str, list[tuple[str, str, int, str]]]:
    """R20: what the resolved scope WRITES, by statement kind: `replace` (DELETE / TRUNCATE / CREATE OR
    REPLACE VIEW), `upsert` (INSERT … ON CONFLICT), `insert` (plain INSERT), `update`, each as
    (table, file, line, delegation chain — '' in the writer itself); and `dynamic` — a DELETE/TRUNCATE/INSERT whose table the scan cannot name. An
    INSERT and an ON CONFLICT split across two strings of ONE function count as an upsert, never as a
    plain insert (the split must not manufacture an "accretes" FAIL)."""
    facts = {k: [] for k in ("replace", "upsert", "insert", "update", "dynamic")}
    for u in units:
        for node in u["nodes"]:
            texts = _sql_texts(dict(u, nodes=[node]))
            fns = sorted(((f.lineno, f.end_lineno) for f in ast.walk(node)
                          if isinstance(f, (ast.FunctionDef, ast.AsyncFunctionDef))), key=lambda r: r[1] - r[0])

            def owner(ln):
                return next((r for r in fns if r[0] <= ln <= r[1]), None)
            orphan = {owner(ln) for t, ln in texts if _ON_CONFLICT.search(t) and not _SQL_INSERT.search(t)}
            for t, ln in texts:
                where = (u["rel"], ln, u["via"] if u["hop"] else "")
                for rx in (_SQL_DELETE, _SQL_TRUNCATE, _SQL_VIEW):
                    for m in rx.finditer(t):
                        tb = m.group(1)
                        facts["dynamic" if not tb or tb == "{?}" else "replace"].append(
                            ("?" if not tb or tb == "{?}" else tb.lower(), *where))
                for m in _SQL_INSERT.finditer(t):
                    tb = m.group(1)
                    if not tb or tb == "{?}":
                        facts["dynamic"].append(("?", *where))
                    else:
                        k = "upsert" if (_ON_CONFLICT.search(t) or owner(ln) in orphan) else "insert"
                        facts[k].append((tb.lower(), *where))
                for m in _SQL_UPDATE.finditer(t):
                    facts["update"].append((m.group(1).lower(), *where))
    return {k: sorted(set(v), key=lambda x: (x[1], x[2], x[0])) for k, v in facts.items()}


_FETCH_CALLS = ("fetchone", "fetchall", "fetchval", "scalar")
# R241: a probe whose predicate pins the CURRENT build (`… AND build_id_uuid = %s`) asks whether this build
# already wrote the rows — a substep-resume check (ga_vargas `_check_already_written`); a rebuild carries a
# new build id and is never held by it. Only a probe of the chart's output as such is a hold.
_BUILD_SCOPED = re.compile(r"\bbuild_id\w*\s*=", re.I)


def _probe_polarity(t: ast.AST, probes: set[str], probed: dict[str, str]) -> tuple[str, str] | None:
    """R20/R241: is an `if` test the POPULATED or the EMPTY reading of an output-existence probe?
    Returns ('populated'|'empty', probe name) or None. Recognised: the probe call itself (also inside a
    walrus or `bool(...)`), a name bound to its result, `x is not None` / `x is None`, `x > 0`,
    `x >= 1`, `x != 0` / `x == 0`, `0 < x`, and `not <any of these>` (polarity inverted)."""
    if isinstance(t, ast.UnaryOp) and isinstance(t.op, ast.Not):
        r = _probe_polarity(t.operand, probes, probed)
        return (("empty" if r[0] == "populated" else "populated"), r[1]) if r else None
    if isinstance(t, (ast.NamedExpr, ast.Subscript, ast.Await)):         # `(n := probe())`, `row[0]`, `await p()`
        return _probe_polarity(t.value, probes, probed)
    if isinstance(t, ast.Call) and _call_name(t) == "bool" and t.args:
        return _probe_polarity(t.args[0], probes, probed)
    if isinstance(t, ast.Call) and _call_name(t) in probes:
        return "populated", _call_name(t)
    if isinstance(t, ast.Name) and t.id in probed:
        return "populated", probed[t.id]
    if isinstance(t, ast.Compare) and len(t.ops) == 1:
        left, op, right = t.left, t.ops[0], t.comparators[0]
        if isinstance(left, ast.Constant) and isinstance(right, ast.Name):          # 0 < x  ->  x > 0
            left, right = right, left
            op = {ast.Lt: ast.Gt(), ast.LtE: ast.GtE(), ast.Gt: ast.Lt(), ast.GtE: ast.LtE()}.get(type(op), op)
        base = _probe_polarity(left, probes, probed)
        if base is None or not isinstance(right, ast.Constant):
            return None
        v, name = right.value, base[1]
        if v is None and isinstance(op, ast.IsNot):
            return "populated", name
        if v is None and isinstance(op, ast.Is):
            return "empty", name
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            if (isinstance(op, ast.Gt) and v == 0) or (isinstance(op, ast.GtE) and v == 1) \
                    or (isinstance(op, ast.NotEq) and v == 0):
                return "populated", name
            if isinstance(op, ast.Eq) and v == 0:
                return "empty", name
    return None


def _refusal_guard(units: list[dict], tset=frozenset()) -> tuple[str, int, str, str] | None:
    """C-KSHETRA, generalised by R20/R241 to the whole resolved scope: a rebuild that is HELD when the
    chart's output already exists is not an idempotent replacement, whatever DELETE sits behind the hold.
    Across every function the writer's rebuild reaches (the writer class and its delegates — not merely
    one file), find an `if` on the POPULATED reading of an output-existence probe (a function or block
    whose SQL is `SELECT EXISTS (SELECT 1 FROM …`, `SELECT 1 FROM <t> WHERE chart_id …` or
    `SELECT count(*) FROM <t> WHERE chart_id …`) READING ONE OF THE ASSET'S OWN TABLES (`tset`, or a
    table the scan cannot name) whose populated branch RAISES, RETURNS, CONTINUEs or BREAKs with a delete
    reachable only past it (after the `if`, or in its empty branch) — or whose only delete sits in the
    empty branch (a skip with no raise). A probe of an UPSTREAM table is no hold (mi_jivanaghatana raises
    when its input life_events exist but it built nothing — the opposite of a refusal), nor is a probe
    pinned to the current build (`_BUILD_SCOPED`, a resume check). Returns (file,
    line, 'raise X' | 'return' | 'continue' | 'break' | 'the delete runs only in the output-empty branch',
    probe) or None."""
    funcs, seen = [], set()
    for u in units:
        for n in u["nodes"]:
            for f in ast.walk(n):
                if isinstance(f, (ast.FunctionDef, ast.AsyncFunctionDef)) and id(f) not in seen:
                    seen.add(id(f))
                    funcs.append((u, f))
    def probes_own(u, f) -> bool:
        for t, _ in _sql_texts(dict(u, nodes=[f])):
            for m in _PROBE_SQL.finditer(t):
                tb = (m.group(1) or m.group(2) or "").lower()
                if _BUILD_SCOPED.search(t[m.end():]):
                    continue            # "did THIS build already write it" — a resume check, not a hold
                if tb in tset or tb == "{?}":
                    return True
        return False
    own_probe = {id(f): probes_own(u, f) for u, f in funcs}
    probes = {f.name for _, f in funcs if own_probe[id(f)]}
    deleters = {f.name for _, f in funcs if any(_SQL_DELETE.search(s) or _SQL_TRUNCATE.search(s)
                                                 for s in _code_strings(f))}
    grew = True
    while grew:                                            # a function that calls a deleter deletes
        before = len(deleters)
        deleters |= {f.name for _, f in funcs if any(_call_name(c) in deleters for c in ast.walk(f))}
        grew = len(deleters) > before
    def deletes(nodes) -> bool:
        return any(_call_name(c) in deleters for c in nodes) or \
            any(isinstance(c, ast.Constant) and isinstance(c.value, str)
                and (_SQL_DELETE.search(c.value) or _SQL_TRUNCATE.search(c.value)) for c in nodes)

    def probed_names(f) -> dict[str, str]:
        inline, probed = own_probe[id(f)], {}
        for a in ast.walk(f):
            if isinstance(a, (ast.Assign, ast.AnnAssign, ast.NamedExpr)):
                val = a.value
                while isinstance(val, (ast.Subscript, ast.Await)) or (
                        isinstance(val, ast.Call) and _call_name(val) in ("bool", "int", "len") and val.args):
                    val = val.value if not isinstance(val, ast.Call) else val.args[0]   # `bool(probe())`
                tgts = a.targets if isinstance(a, ast.Assign) else [a.target]
                if _call_name(val) in probes or (inline and _call_name(val) in _FETCH_CALLS):
                    src = _call_name(val) if _call_name(val) in probes else f"{f.name} (inline)"
                    probed.update({t.id: src for t in tgts if isinstance(t, ast.Name)})
        return probed

    def populated_ifs(f):
        probed = probed_names(f)
        for node in ast.walk(f):
            if isinstance(node, ast.If):
                pol = _probe_polarity(node.test, probes, probed)
                if pol is not None:
                    held, path = (node.body, node.orelse) if pol[0] == "populated" else (node.orelse, node.body)
                    yield node, pol, held, path

    def raise_name(stop) -> str:
        exc = stop.exc
        return "raise " + (_call_name(exc) or (exc.id if isinstance(exc, ast.Name) else "an exception"))

    # R241 (follow-up): a GUARD HELPER — a function that raises on the populated reading and deletes nothing
    # itself (`_assert_empty`) — holds the rebuild for any caller that deletes after calling it (a call
    # inside a `try` is not counted: the caller may catch it). Resolved to a fixpoint over the scope.
    raisers: dict[str, tuple[str, str]] = {}
    for _u, f in funcs:
        for _node, pol, held, _path in populated_ifs(f):
            stop = next((x for x in held if isinstance(x, ast.Raise)), None)
            if stop is not None and f.name not in raisers:
                raisers[f.name] = (raise_name(stop), pol[1])

    def untried_calls(f):
        tried = {id(c) for t in ast.walk(f) if isinstance(t, ast.Try) and t.handlers
                 for s in t.body for c in ast.walk(s)}
        return [c for c in ast.walk(f) if isinstance(c, ast.Call) and id(c) not in tried]
    grew = True
    while grew:
        grew = False
        for _u, f in funcs:
            if f.name in raisers:
                continue
            hit = next((c for c in untried_calls(f) if _call_name(c) in raisers), None)
            if hit is not None:
                raisers[f.name] = raisers[_call_name(hit)]
                grew = True

    for u, f in funcs:
        for node, pol, held, path in populated_ifs(f):
            stop = next((s for s in held if isinstance(s, (ast.Raise, ast.Return, ast.Continue, ast.Break))), None)
            after = [c for c in ast.walk(f) if getattr(c, "lineno", 0) > node.end_lineno]
            on_path = [c for s in path for c in ast.walk(s)]
            if stop is not None and deletes(on_path + after):
                what = raise_name(stop) if isinstance(stop, ast.Raise) else type(stop).__name__.lower()
                return u["rel"], stop.lineno, what, pol[1]          # return / continue / break / raise X
            # R241: a hold that neither raises nor returns — the delete sits ONLY in the empty branch, and
            # nothing in the populated branch or after the `if` deletes: a populated chart is skipped.
            if stop is None and deletes(on_path) and not deletes([c for s in held for c in ast.walk(s)] + after):
                return u["rel"], node.lineno, "the delete runs only in the output-empty branch", pol[1]
        for c in untried_calls(f):
            name = _call_name(c)
            if name in raisers and name != f.name and \
                    deletes([x for x in ast.walk(f) if getattr(x, "lineno", 0) > getattr(c, "end_lineno", c.lineno)]):
                what, probe = raisers[name]
                return u["rel"], c.lineno, f"{what} in the guard helper {name}", probe
    return None


_UO_SCOPE_COLS = ("chart_id", "ayanamsha_id", "build_id", "asset_id", "run_id")
_UO_SET = re.compile(r"\bSET\b(.*?)(?=\bWHERE\b|\bFROM\b|\bRETURNING\b|\Z)", re.I | re.S)
_UO_WHERE = re.compile(r"\bWHERE\b(.*?)(?=\bRETURNING\b|\Z)", re.I | re.S)
_UO_ARRAY_ACC = re.compile(r"\b(?:array_(?:append|cat|prepend)|concat|jsonb_insert)\s*\(", re.I)
_UO_KEYED = re.compile(r"\b([A-Za-z_]\w*)\s*=\s*(?:%s|%\(\w+\)s|\$\d+|ANY\s*\()", re.I)


_UO_JSON_DELETE = r"(?:''|ARRAY\s*\[[^\]]*\]|(?:%s|%\(\w+\)s)\s*::\s*text(?:\[\])?)"


def _split_top_br(s: str) -> list:
    """_split_top that also keeps `[...]` (array constructors) whole."""
    parts, depth, cur = [], 0, []
    for ch in s:
        depth += ch in "(["
        depth -= ch in ")]"
        if ch == "," and depth == 0:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
    return parts + ["".join(cur)]


def _uo_assignments(set_text: str):
    """(column, expression) pairs of a SET clause; a tuple form `(a, b) = (x, y)` / `= ROW(x, y)` is paired by
    position (an unpairable right side is attributed whole to each column)."""
    for a in _split_top_br(set_text):
        if "=" not in a:
            continue
        lhs, rhs = (x.strip() for x in a.split("=", 1))
        if lhs.startswith("(") and lhs.endswith(")"):
            cols = [c.strip().strip('"') for c in lhs[1:-1].split(",")]
            r = rhs[3:].strip() if rhs.upper().startswith("ROW") else rhs
            exprs = _split_top(r[1:-1]) if r.startswith("(") and r.endswith(")") else None
            if exprs and len(exprs) == len(cols):
                yield from zip(cols, (x.strip() for x in exprs))
            else:
                yield from ((c, rhs) for c in cols)
        else:
            yield lhs.strip('"'), rhs


def _uo_shapes(w) -> list:
    """The row-set predicate shapes of an UPDATE's WHERE text (None = no WHERE)."""
    found = []
    if w is None:
        return ["no-predicate"]
    if re.search(r"\bIS\s+DISTINCT\s+FROM\b", w, re.I):
        found.append("guarded")
    if re.search(r"\bIS\s+(?:NOT\s+)?NULL\b", w, re.I):
        found.append("state-conditional")
    lhs = [c.lower() for c in _UO_KEYED.findall(w)]
    if any(c not in _UO_SCOPE_COLS for c in lhs):
        found.append("keyed")
    if any(c in _UO_SCOPE_COLS for c in lhs) or re.search(r"\b(?:" + "|".join(_UO_SCOPE_COLS) + r")\b", w, re.I):
        found.append("scope")
    return found or ["other-predicate"]


def _update_only_reading(units, tset) -> dict:
    """Idem.pattern's update-only sub-reading (N-22 ruling 6; SS: Idem stays ONE gate, update-only is not N/A): each
    own-table UPDATE is read for (a) an ACCUMULATING assignment (`SET c = c + x`, `c * x`, array_append/cat/prepend
    of c: a second rebuild changes the row again; named update-only:accumulating-assignment) and (b) its row-set
    predicate shape: keyed, scope (chart/ayanamsha/build/asset), state-conditional (IS [NOT] NULL), guarded (IS DISTINCT
    FROM), none, other. Whether a rebuild re-derives EVERY row is not provable statically (PASS needs the E5.5
    semantic-fingerprint comparison on the E5.6 rehearsal database), so the reading never PASSes."""
    acc, concat, shapes, recs = [], [], {}, []
    for u in units:
        for node in u["nodes"]:
            for text, ln in _sql_texts(dict(u, nodes=[node])):
                m = _SQL_UPDATE.search(text)
                if not m or m.group(1).lower() not in tset:
                    continue
                flat = re.sub(r"'(?:[^']|'')*'", "''", re.sub(r"--[^\n]*", "", text))
                where = _UO_WHERE.search(flat)
                cite_ = f"{m.group(1).lower()} ({u['rel']}:{ln}{' via ' + u['via'] if u['hop'] else ''})"
                st = _UO_SET.search(flat)
                fns = sorted(((f.lineno, f.end_lineno) for f in ast.walk(node)
                              if isinstance(f, (ast.FunctionDef, ast.AsyncFunctionDef))), key=lambda r: r[1] - r[0])
                fn = next((r for r in fns if r[0] <= ln <= r[1]), None)
                shapes_here = _uo_shapes(where.group(1) if where else None)
                ifs = [(i.lineno, i.end_lineno) for i in ast.walk(node) if isinstance(i, ast.If)]
                # a reset excuses an accumulation only when UNCONDITIONAL (not inside an `if`) and chart-wide (no keyed,
                # state-conditional, guarded or other predicate)
                excuses = (not any(a0 <= ln <= b0 for a0, b0 in ifs)
                           and not set(shapes_here) & {"keyed", "state-conditional", "guarded", "other-predicate"})
                for col, expr in (_uo_assignments(st.group(1)) if st else []):
                    if not re.fullmatch(r"[A-Za-z_]\w*", col):
                        continue
                    if not re.search(rf"\b{re.escape(col)}\b", expr):
                        recs.append(dict(kind="reset", table=m.group(1).lower(), col=col, line=ln, fn=fn, u=u["rel"], ok=excuses))
                    elif re.fullmatch(rf"\s*{re.escape(col)}\s*-\s*{_UO_JSON_DELETE}\s*", expr, re.I):
                        continue                                # jsonb key delete: idempotent
                    elif re.search(r"[+\-*/]", re.sub(r"%\(\w+\)s|::\w+", "", expr)) or _UO_ARRAY_ACC.search(expr):
                        recs.append(dict(kind="acc", table=m.group(1).lower(), col=col, line=ln, fn=fn, u=u["rel"],
                                         text=f"{col} = {expr[:60]} in {cite_}"))
                    elif "||" in expr:
                        concat.append(f"{col} in {cite_}")
                found = shapes_here
                for f in found:
                    shapes.setdefault(f, []).append(cite_)
    # an accumulation is excused only by a reset of the SAME column of the SAME table earlier in the SAME function
    for r in recs:
        if r["kind"] == "acc" and not any(x["kind"] == "reset" and x["ok"] and x["table"] == r["table"] and x["col"] == r["col"]
                                          and x["u"] == r["u"] and r["fn"] is not None and x["fn"] == r["fn"]
                                          and x["line"] < r["line"] for x in recs):
            acc.append(r["text"])
    return dict(accumulating=acc, concat=concat, shapes=shapes)


def _update_only_text(rd: dict) -> str:
    slugs = [f"update-only:{k}-row-set-unproven" for k in ("keyed", "scope", "state-conditional", "guarded", "no-predicate",
                                                          "other-predicate") if k in rd["shapes"]]
    if rd["concat"]:
        slugs.append("update-only:self-referencing-concat-type-unread (" + "; ".join(rd["concat"]) + ")")
    return (" ".join(slugs) + "; no row is added, but whether a rebuild re-derives every row is not proven statically: "
            "PASS needs the E5.5 semantic-fingerprint comparison across a rebuild on the E5.6 rehearsal database, "
            "which this scan does not run")


def idem_scan(asset_id: str, files: list[str], convention: str, targets=()) -> tuple[str, list[str]]:
    """§N.3, over real SQL strings (docstrings excluded), measured on the code a rebuild RUNS.

    C-KSHETRA (W2-2 gate review §4.1): the PASS is a claim that a REBUILD REPLACES the asset's own rows —
    (a) a counted DELETE must NAME one of the asset's own tables (`targets`: target_table ∪ count_sql
    tables), and (b) a rebuild held when the output is populated reads FAIL with the hold's location.

    R20 (W2-3): the scan now follows the writer's DELEGATION (`_delegation_scope`): from the registered
    class — not its whole module — through the same-module helpers and SQL constants it uses, into the
    seeder / shared helper / adapter target it calls, up to IDEM_DELEGATION_HOPS modules away. The same
    two rules apply to everything reached. Upsert layers (L0) PASS on an `INSERT … ON CONFLICT` into the
    asset's OWN table (no longer on `ON CONFLICT` text anywhere), or on a delete-then-insert of it — a
    full replacement, no accretion. A FAIL needs a measured defect on a fully-read scope: a hold, an
    own-table INSERT with no replacement (accretes), or an own-table upsert where §N.3 requires
    delete-then-insert. Everything else is PARTIAL with the reason named — a chain the hop limit cut, a
    table the scan cannot name, a registry/writer table mismatch (R240), in-place UPDATEs only, or no
    own-table write at all — never "likely delegates"."""
    if not files:
        return NO_DET, ["no writer file recognised — nothing scanned"]   # R222 / N2, as contract_scan
    units, beyond = _delegation_scope(asset_id, files)
    facts = _write_facts(units)
    tset = {t.lower() for t in targets if t}

    def cite(rows) -> str:
        return ", ".join(dict.fromkeys(f"{t} ({rel}:{ln}{f' via {via}' if via else ''})" for t, rel, ln, via in rows))

    guard = _refusal_guard(units, tset)          # R241: across the whole resolved scope, not one file
    if guard:
        rel, ln, what, probe = guard
        u = next((x for x in units if x["rel"] == rel), None)
        hop = f", reached via {u['via']}" if u and u["hop"] else ""
        return FAIL, [f"rebuild refused when target is populated: {rel}:{ln} ({what} after the output-existence "
                      f"probe {probe}{hop}) — the delete-then-insert path runs only on an output-empty chart, so a "
                      "rebuild of a populated chart does not replace (§N.3 'rebuild replaces' not met)"]
    own = {k: [x for x in facts[k] if x[0] in tset] for k in ("replace", "upsert", "insert", "update")}
    unresolved = bool(beyond or facts["dynamic"])
    # R20 (follow-up): the PASS is per TABLE, not per asset — a multi-table writer that replaces one of its
    # tables and plain-INSERTs into another it never replaces still accretes the second on every rebuild.
    covered = {x[0] for x in own["replace"] + own["upsert"]}
    unreplaced = [x for x in own["insert"] if x[0] not in covered]
    if unreplaced and covered:
        what = (f"the rebuild replaces {sorted(covered)} but plain-INSERTs into {sorted({x[0] for x in unreplaced})} "
                f"with no delete or upsert of it: {cite(unreplaced)}")
        if not unresolved:
            return FAIL, [f"{what} — that table accretes (or collides) on every rebuild"]
        return PARTIAL, [f"{what}; the scope is not fully read (a cut delegation chain or an unnamed table may "
                         f"hold its replacement) [resolved scope: {', '.join(dict.fromkeys(u['rel'] for u in units))}]"]
    if convention == "upsert":
        if own["upsert"]:
            return PASS, [f"INSERT … ON CONFLICT into the asset's own table(s) (upsert): {cite(own['upsert'])}"]
        if own["replace"]:
            return PASS, [f"the asset's own table(s) replaced by delete-then-insert: {cite(own['replace'])} — a full "
                          "replacement, not the L0 upsert convention, and no accretion"]
    elif own["replace"]:
        return PASS, [f"DELETE FROM the asset's own table(s) (delete-then-insert): {cite(own['replace'])}"]
    if not unresolved:
        if convention != "upsert" and own["upsert"]:
            return FAIL, [f"upsert into the asset's own table(s) with no delete of them anywhere in the resolved scope: "
                          f"{cite(own['upsert'])} — §N.3 requires delete-then-insert for this layer; rows a rebuild no "
                          "longer produces survive it"]
        if own["insert"] and not own["upsert"]:
            return FAIL, [f"plain INSERT into the asset's own table(s) with no delete or upsert of them anywhere in the "
                          f"resolved scope: {cite(own['insert'])} — a rebuild accretes (or collides) rather than replaces"]
    reasons = []
    other = sorted({x[0] for x in facts["replace"] + facts["upsert"]} - tset)
    mismatch = sorted({(o, t) for t in other for o in tset if t.startswith(o + "_") or o.startswith(t + "_")})
    if mismatch:
        reasons.append("registry/writer table mismatch (R240, a registry-data finding — not closable by the "
                       "detector): " + "; ".join(f"the registry declares {o}, the writer replaces {t}" for o, t in mismatch))
    if beyond:
        reasons.append(f"delegation deeper than {IDEM_DELEGATION_HOPS} hop(s), not followed: {'; '.join(beyond)}")
    if facts["dynamic"]:
        reasons.append("a DELETE/INSERT whose table the scan cannot name: "
                       + ", ".join(f"{x[1]}:{x[2]}" for x in facts["dynamic"]))
    if own["upsert"]:
        reasons.append(f"upsert into the asset's own table(s) and no delete of them found: {cite(own['upsert'])}")
    if own["insert"]:
        reasons.append(f"plain INSERT into the asset's own table(s) and no replacement found: {cite(own['insert'])}")
    if own["update"] and not (own["upsert"] or own["insert"]):
        rd = _update_only_reading(units, tset)
        if rd["accumulating"]:
            what = "update-only:accumulating-assignment: " + "; ".join(rd["accumulating"])
            if not unresolved:
                return FAIL, [f"the asset's own table(s) are only UPDATEd in place: {cite(own['update'])} — {what} — a second "
                              "rebuild changes the rows again (not idempotent)"]
            reasons.append(f"the asset's own table(s) are only UPDATEd in place: {cite(own['update'])} — {what} (the scope "
                           "is not fully read, so this is PARTIAL, not FAIL)")
        else:
            reasons.append(f"the asset's own table(s) are only UPDATEd in place: {cite(own['update'])} — "
                           f"{_update_only_text(rd)}")
    if other and not mismatch:
        reasons.append(f"it replaces only other tables: {', '.join(other)}")
    if not any(own.values()):
        reasons.append(f"no write to the asset's own table(s) {sorted(tset) or '(none declared)'} anywhere in the "
                       "resolved scope — nothing to replace; not graded N/A, since a static scan cannot prove a "
                       "write's absence")
    scope = ", ".join(dict.fromkeys(u["rel"] for u in units))
    return PARTIAL, ["; ".join(reasons) + f" [resolved scope: {scope}]"]


def _ts_code(src: str, blank_strings: bool = False) -> str:
    """R51: TypeScript source with its comments removed (`// …` and `/* … */`, JSDoc included), string
    and template literals respected — a `//` inside `'http://…'` or a backticked SQL string is code,
    not a comment. Newlines inside removed comments are kept so positions stay line-true. With
    `blank_strings`, literal CONTENTS are blanked too (the quotes stay). Limit, disclosed: a regex
    literal containing a quote or `//` is not recognised as a regex (no such literal is needed by the
    capability modules' table references or declarations)."""
    out: list[str] = []
    i, n = 0, len(src)
    while i < n:
        c, nx = src[i], src[i + 1] if i + 1 < n else ""
        if c == "/" and nx == "/":
            j = src.find("\n", i)
            i = n if j < 0 else j
        elif c == "/" and nx == "*":
            j = src.find("*/", i + 2)
            j = n if j < 0 else j + 2
            out.append("\n" * src.count("\n", i, j) or " ")
            i = j
        elif c in "'\"`":
            j = i + 1
            while j < n and src[j] != c:
                j += 2 if src[j] == "\\" else 1
            body = src[i + 1:min(j, n)]
            out.append(c + (re.sub(r"[^\n]", " ", body) if blank_strings else body) + (c if j < n else ""))
            i = j + 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


# `density_contract: <object or identifier>`: a key whose value is `undefined` / `null` / `false` / `true` declares
# nothing (R232 carried: a declaration needs a real value, not just the key).
_DENSITY_DECL = re.compile(r"\bdensity_contract\s*\??\s*:\s*(?!(?:undefined|null|false|true)\b)(?=[{A-Za-z_$(\[])")

# E6.1 (d) / N-22 ruling principle 4: the Dens scanner. A tier column is STRUCTURAL vocabulary -- a column NAME, never a value check -- and, from
# REGISTRY_REVISION 23 (SS ruling N-98, Dens memo item 3), a CLOSED one: the old open `\w+_tier` let `bg_remedies.cost_tier` (a price bucket) read as a
# verification/confidence tier. A column counts as a tier ONLY when (a) its name is exactly `tier` or `verification_pass_status`, or (b) the asset DECLARES
# it in `density_tier_columns` (a reviewed {column, why, evidence}); and (c) in NEITHER case does its name carry a deny-listed non-verification word (any
# spelling, case-insensitive; fail-closed, see `dens_tier_denied_word`): a denied name never counts, declared or not. Everything else (`severity_tier`, `signature_tier`, `access_tier`, ...)
# counts for nothing unless declared. `confidence*` columns are not in the vocabulary (open question to the lead, DESIGN_DENS.md Q1) except by declaration.
# ONE definition: `dens_tier_counts` is the only place a name is classified; the validator, the measure-time refusal and the scan all call it.
DENS_TIER_EXACT = frozenset({"tier", "verification_pass_status"})
DENS_TIER_DENY_WORDS = frozenset({"cost", "price", "pricing", "plan", "access", "subscription", "billing", "fee", "tariff"})
DENS_TIER_DECL_FIELDS = ("column", "why", "evidence")
DENS_TIER_MAX_DECLARED = 16


_DENS_CAMEL = re.compile(r"(?<=[a-z0-9])(?=[A-Z])")


def _dens_deny_stems(word: str) -> set:
    """`word` and its plural stems ('costs' -> 'cost', 'prices' -> 'price', 'accesses' -> 'access')."""
    return {word} | ({word[:-1]} if word.endswith("s") else set()) | ({word[:-2]} if word.endswith("es") else set())


def dens_tier_denied_word(name) -> str | None:
    """The deny-listed word `name` carries, or None (case-insensitive). Fail-CLOSED, so a deny-listed meaning cannot hide in a spelling: the name is split into words on
    underscores, digits and camelCase boundaries and each word (plural-stemmed: `costs`, `prices`, `plans`) is compared with the deny words; AND the name with every
    non-letter removed (`c_o_s_t_tier` -> `costtier`, `CostTier`, `costTier`, `cost1_tier`) is tested with and without a leading / trailing `tier`: when it STARTS or ENDS
    with a deny word (or its plural) it is denied (`pricetier`, `feetier`, `accesstier`, `costbucket_tier`). Deliberately over-blocking for a DECLARED name (`planet_tier`,
    `feedback_tier` are denied too: declare a name that does not begin or end with a deny word); the exact names `tier` / `verification_pass_status` carry none."""
    if not isinstance(name, str):
        return None
    toks = [t for t in re.split(r"[^a-z]+", _DENS_CAMEL.sub("_", name).casefold()) if t]
    for t in toks:
        hit = next((w for w in DENS_TIER_DENY_WORDS if w in _dens_deny_stems(t)), None)
        if hit:
            return hit
    letters = "".join(toks)
    cands = {letters}
    for c in list(cands):
        if c.startswith("tier"):
            cands.add(c[4:])
        if c.endswith("tier"):
            cands.add(c[:-4])
    if letters.startswith("tier") and letters.endswith("tier") and len(letters) > 8:
        cands.add(letters[4:-4])
    for c in sorted(cands):
        for w in sorted(DENS_TIER_DENY_WORDS):
            for suf in ("", "s", "es"):
                if c and (c.startswith(w + suf) or c.endswith(w + suf)):
                    return w
    return None


def dens_tier_counts(name, declared=()) -> bool:
    """True when the column `name` counts as a verification / confidence tier: not deny-listed, and either exactly `tier` / `verification_pass_status`
    or one of the asset's `declared` density tier columns (an iterable of names, matched case-insensitively). The ONE classifier."""
    if not isinstance(name, str) or dens_tier_denied_word(name):
        return False
    n = name.casefold()
    return n in DENS_TIER_EXACT or n in {d.casefold() for d in declared if isinstance(d, str)}


TIER_YES, TIER_NO, TIER_UNKNOWN = "tier", "no-tier", "unknown"


# ───────────── DENS-SCANNER (REGISTRY_REVISION 26, Worker D): ONE TypeScript lexer for the Dens scan ─────────────
# The old three scanners (`_ts_mask`, `_ts_literal_spans`, `_ts_desynced`) each hand-rolled the same quote loop and shared its three blind spots: a TEMPLATE
# LITERAL whose `${ ... }` holds another quote or backtick (a nested template closed at the first inner backtick, flipping the parity of every later literal),
# a REGEX LITERAL holding a quote / a bracket / `//`, and a `${` that is never closed. They are now views of ONE lexer, `_ts_lex`: top-level tokens are
# `comment` (line / block), `string` ('..' / ".."), `template` (the whole backticked literal, `${...}` included, nested templates / strings / comments / regexes
# inside an interpolation lexed recursively and NOT reported as tokens of their own: they are part of the template's text, as before) and `regex`.
# A `/` is a regex only where a regex may start (previous significant token is an operator / opening bracket / separator / start, or one of the keywords below)
# AND a closing `/` is found on the same line (a class `[...]` may hold a `/`); anywhere else (after an identifier, number, string, `)`, `]`, `}`) it is division.
# After `)` a regex is possible (`if (x) /re/.test(y)`) and after `}` too; both are read as DIVISION on purpose: the quote in such a regex then desyncs the file,
# and a desynced file is NO_DETECTOR naming it, never read as "no served select" (the safe direction). Desync = a `'`/`"` string across a raw newline, a string /
# template / interpolation / block comment never closed. A file whose tokens close cleanly is parsed; one that does not is never trusted.
_TS_REGEX_AFTER_WORDS = frozenset({"return", "typeof", "instanceof", "in", "of", "new", "delete", "void", "throw", "case", "do", "else", "yield", "await"})
_TS_IDENT = re.compile(r"[A-Za-z_$][\w$]*|\d[\w.]*")


def _ts_regex_end(src: str, i: int) -> int:
    """End offset (exclusive, flags included) of a regex literal opening at `i` (a `/`), or -1 when none closes on this line."""
    n, j, in_class = len(src), i + 1, False
    while j < n:
        ch = src[j]
        if ch == "\n":
            return -1
        if ch == "\\":
            j += 2
            continue
        if ch == "[":
            in_class = True
        elif ch == "]":
            in_class = False
        elif ch == "/" and not in_class:
            j += 1
            while j < n and (src[j].isalnum() or src[j] in "_$"):
                j += 1
            return j
        j += 1
    return -1


def _ts_lex_code(src: str, i: int, toks: list | None, nested: bool):
    """Lex code from `i`. `nested`: inside a `${ ... }` (stops at its closing `}`, returns its index; -1 desynced). Top level appends tokens to `toks`
    (`(kind, start, end)`) and returns `(index, ok)`."""
    n, depth, prev = len(src), 0, ("start", "")
    while i < n:
        c = src[i]
        nx = src[i + 1] if i + 1 < n else ""
        if c.isspace():
            i += 1
        elif c == "/" and nx == "/":
            j = src.find("\n", i)
            j = n if j < 0 else j
            if toks is not None:
                toks.append(("comment", i, j))
            i = j
        elif c == "/" and nx == "*":
            j = src.find("*/", i + 2)
            if j < 0:
                return (-1, False) if nested else (n, False)
            if toks is not None:
                toks.append(("comment", i, j + 2))
            i = j + 2
        elif c in "'\"":
            j = i + 1
            while j < n and src[j] != c:
                if src[j] == "\n":
                    return (-1, False) if nested else (j, False)
                j += 2 if src[j] == "\\" else 1
            if j >= n:
                return (-1, False) if nested else (n, False)
            if toks is not None:
                toks.append(("string", i, j + 1))
            i, prev = j + 1, ("value", "")
        elif c == "`":
            j, ok = _ts_template_end(src, i)
            if not ok:
                return (-1, False) if nested else (n, False)
            if toks is not None:
                toks.append(("template", i, j))
            i, prev = j, ("value", "")
        elif c == "/":
            allow = (prev[0] in ("start", "punct") and prev[1] not in (")", "]", "}")) or (prev[0] == "word" and prev[1] in _TS_REGEX_AFTER_WORDS)
            j = _ts_regex_end(src, i) if allow else -1
            if j > 0:
                if toks is not None:
                    toks.append(("regex", i, j))
                i, prev = j, ("value", "")
            else:
                i, prev = i + 1, ("punct", "/")
        elif c == "{":
            depth += 1
            i, prev = i + 1, ("punct", c)
        elif c == "}":
            if nested and depth == 0:
                return i, True
            depth = max(depth - 1, 0)
            i, prev = i + 1, ("punct", c)
        else:
            m = _TS_IDENT.match(src, i)
            if m:
                i, prev = m.end(), ("word", m.group(0))
            else:
                i, prev = i + 1, ("punct", c)
    return (-1, False) if nested else (n, True)


def _ts_template_end(src: str, i: int) -> tuple[int, bool]:
    """End offset (exclusive) of the template literal opening at `i` (a backtick), nested `${ ... }` lexed as code; `(n, False)` when it never closes."""
    n, j = len(src), i + 1
    while j < n:
        ch = src[j]
        if ch == "\\":
            j += 2
        elif ch == "`":
            return j + 1, True
        elif ch == "$" and src[j + 1:j + 2] == "{":
            k, ok = _ts_lex_code(src, j + 2, None, True)
            if not ok:
                return n, False
            j = k + 1
        else:
            j += 1
    return n, False


@functools.lru_cache(maxsize=16)
def _ts_lex(src: str) -> tuple[tuple, bool]:
    """`(tokens, ok)`: every top-level token (`(kind, start, end)`, kind comment / string / template / regex) and whether the file lexed cleanly."""
    toks: list = []
    _end, ok = _ts_lex_code(src, 0, toks, False)
    return tuple(toks), ok


def _ts_mask(src: str, blank_strings: bool = False) -> str:
    """Comments blanked with POSITIONS KEPT: same length as `src`; every comment character becomes a space (newlines stay); with `blank_strings`, string / template
    contents and regex literal bodies too (the delimiters stay). Offsets found in the mask are offsets in `src` (`_ts_code`, which deletes comment text, cannot give
    that): needed to say WHICH top-level declaration a token, a `density_contract:` and a SELECT literal sit in."""
    out = list(src)
    for kind, a, b in _ts_lex(src)[0]:
        if kind == "comment":
            out[a:b] = [ch if ch == "\n" else " " for ch in src[a:b]]
        elif blank_strings and kind in ("string", "template"):
            out[a + 1:b - 1] = [ch if ch == "\n" else " " for ch in src[a + 1:b - 1]]
        elif blank_strings and kind == "regex":
            e = src.rfind("/", a, b)                       # the closing slash: flags follow it
            out[a + 1:e] = [ch if ch == "\n" else " " for ch in src[a + 1:e]]
    return "".join(out)


def _ts_literal_spans(src: str) -> list[tuple[int, str]]:
    """`_ts_literals` with each literal's start offset in `src` (comments skipped, strings and templates respected, a regex literal is not a string)."""
    return [(a + 1, src[a + 1:b - 1]) for kind, a, b in _ts_lex(src)[0] if kind in ("string", "template")]


def _ts_desynced(src: str) -> bool:
    """Did the lexer lose sync with the file? True when a `'` / `"` string spans a raw newline, or a string, template literal, `${` interpolation or block comment is
    never closed (none is legal TypeScript; each is what a stray quote — an apostrophe in JSX text (`<p>don't</p>`), a quote in a regex the lexer did not
    recognise (after `)` or `}`) — does to every literal after it). Everything `_ts_mask`, `_ts_literal_spans` and `_ts_decl_starts` report for such a file is
    unreliable, so the outside probe never reads "no served select" from it. Limit, disclosed: two stray quotes re-sync by accident and are not detected (a `.tsx`
    file is never trusted for that reason — it is always read textually). Nested templates, regex literals holding quotes / brackets / `//`, and `${}` interpolations
    holding strings are lexed and do NOT desync (DENS-SCANNER, REGISTRY_REVISION 26)."""
    return not _ts_lex(src)[1]


_DYN_FROM = re.compile(r"\b(?:FROM|JOIN)\s+(?:ONLY\s+)?(?:\"?[A-Za-z_]\w*\"?\.)?\"?\$\{|\b(?:FROM|JOIN)\s+(?:ONLY\s+)?(?:[\w\"]+\.)?%(?:\d+\$)?[IsL]", re.I)
# a literal that ENDS in `FROM` / `JOIN` / `FROM <partial name>` and has its table name joined on in code
_DYN_FROM_TAIL = re.compile(r"\b(?:FROM|JOIN)\b(?:\s+(?:ONLY\s+)?[\w.\"]*)?\s*$", re.I)
_DYN_JOINED = re.compile(r"(?:\s|/\*.*?\*/|//[^\n]*\n)*(?:\+|,|\.concat\s*\()", re.S)


def _sqlish_dynamic(rx, c: str, prev: str = "") -> bool:
    """`rx` (a case-insensitive FROM/JOIN pattern) matches in literal `c` AS SQL: the keyword in UPPER case (this codebase's SQL), or any case when the literal
    carries a SELECT, or (review fix LOW-5) when the literal directly JOINED before it (`prev`: `'select a ' + 'from ' + t`, a lower-case concatenated select) carries a SELECT. A lower-case `from` in prose ("held-out, isolated from generation") is not a table read: DENS-SCANNER (REGISTRY_REVISION 26) -- the
    catalogue file `jyotish/asset_names.ts` held two such descriptions, each followed by the `,` of the next object property, and read as a run-time table name."""
    m = rx.search(c)
    if not m:
        return False
    return bool(re.search(r"\b(?:FROM|JOIN)\b", m.group(0))) or bool(re.search(r"\bSELECT\b", c, re.I)) or bool(re.search(r"\bSELECT\b", prev, re.I))


def _dynamic_from(txt: str, spans: list[tuple[int, str]]) -> bool:
    """Does any literal name its table at run time: `FROM ${T}` (also `"${T}"`, `"public"."${T}"`, `public.${T}`, JOIN,
    ONLY), a `format(… FROM %I …)` placeholder, or a literal ending in `FROM`/`JOIN`/`FROM t_` that has a name joined
    on with `+`, `.concat(` or an array `,` (a comment between is skipped)? SQL only (`_sqlish_dynamic`): prose that says "from" is not a read."""
    for i, (pos, c) in enumerate(spans):
        prev = ""
        if i:                                              # the literal directly joined before this one (`+`, `,`, `.concat(`), if any
            pp, pc = spans[i - 1]
            if _LIT_GAP.fullmatch(txt[pp + len(pc) + 1:pos - 1]):
                prev = pc
        if _sqlish_dynamic(_DYN_FROM, c, prev):
            return True
        if _sqlish_dynamic(_DYN_FROM_TAIL, c, prev) and _DYN_JOINED.match(txt[pos + len(c) + 1:pos + len(c) + 200]):
            return True
    return False


# ───────────── E6 / SS N-74(a): a SELECT is not a LABEL (REGISTRY_REVISION 14) — a CLOSED ALLOW-LIST ─────────────
# A serving module that merely NAMES the asset is not a module that selects rows from it. Every occurrence of a token in a module is classified,
# deterministically and read-only (regex + a bracket scan over the comment-masked text; no LLM, no file but the module itself). The design is a
# CLOSED ALLOW-LIST of label contexts (strategist, SS DENS second review): a name is a LABEL only in one of these, and EVERYTHING ELSE is a reach.
# There is no consumption tracking and no open-ended shape heuristic:
#   (1) PROVENANCE ENVELOPE: a bare name that is an element of the array under the key `tables` / `source_tables`, whose parent object is the value
#       of the key `provenance`, where the object literal holding `provenance` is a property value or a return value of an object literal that is
#       not a call argument and not a const holder (the real envelope: `return { content: { ..., provenance: { tables: [...] } } }`);
#   (2) STRICT PROSE: a string that is the whole value of the key `source` / `source_table` / `label` / `note` / `reason` / `description` / `message` /
#       `title`, is strict prose (`_strict_prose`) and sits in an object literal that is not a call argument;
#   (3) the `service_probe` envelope of a SERVICE-kind asset is a REACH (kind `probe`), at any depth below the marker object; for a DATA-kind asset the
#       envelope's own keys (`asset_id`, `endpoint_identity`, `source_ref`) are not in the list, so they are a reach too -- but a `provenance.tables`
#       element that happens to sit inside a probe envelope is still context (1), a LABEL, for a data-kind asset (the verdict is by the structural context);
#   (4) an import / require path, a type / interface / enum / class name; a COMMENT is not a label, it BLOCKS (R51; handled in capability_scan).
# KNOWN RESIDUALS of the allow-list (documented, deliberately not widened): (a) a regex literal holding a bracket or a quote can skew the bracket scan
# (`_ts_desynced` guards the quote case only); (b) strict prose is pure alphabetic words, so a statement made only of words (`table t_x union all table
# facts`) is refused by name (`table` / `union` are never prose here) but any other all-words SQL dialect form is not enumerated; (c) a function that
# RETURNS provenance.tables whose value then flows to a same-module generic reader is outside the allow-list's premise (the envelope is response metadata).
# SELECT = SQL in the literal (or its +/, neighbours); AMBIGUOUS = every other occurrence. A module is a reach unless EVERY occurrence is a LABEL (and
# it carries no strict served select): only an exact "scanned, no select, no unrecognised form" reads N/A.
LABEL, SELECT_REF, AMBIGUOUS_REF = "label", "select", "ambiguous"
PROBE_REF = "probe"        # a service-kind asset named inside a `service_probe` envelope: the module serves the service
PROV_ARRAY_KEYS = frozenset({"tables", "source_tables"})
PROSE_KEYS = frozenset({"source", "source_table", "label", "note", "reason", "description", "message", "title"})
# SQL signals in a literal: case-insensitive for the words prose does not use (SELECT, JOIN, INSERT INTO, ORDER BY, `$1`, `::cast`, `WHERE <col> =`),
# case-SENSITIVE for the words prose does use (FROM / INTO / UPDATE / TABLE / SET / WHERE / RETURNING / TRUNCATE / UNION: prose says "from <table>",
# "where present", "the union of"; SQL in this codebase is upper-case, and a lower-case SQL literal carries one of the case-insensitive signals)
_SQL_STRONG = re.compile(r"\bSELECT\b|\bJOIN\b|\bINSERT\s+INTO\b|\bDELETE\s+FROM\b|\bMERGE\s+INTO\b|\bON\s+CONFLICT\b"
                         r"|\bORDER\s+BY\b|\bGROUP\s+BY\b|\bLIMIT\s+[\d$]|\bOFFSET\s+[\d$]|\$\d|::\s*[A-Za-z_]"
                         r"|\bWHERE\s+[\w.\"()]+\s*(?:=|<|>|!|~|\b(?:IN|IS|LIKE|ILIKE|BETWEEN|ANY|NOT)\b)"
                         # DDL / COPY / `update t set` in any case (a long lower-case statement is still SQL, not prose)
                         r"|\bCREATE\s+(?:OR\s+REPLACE\s+)?(?:(?:GLOBAL\s+|LOCAL\s+)?TEMP(?:ORARY)?\s+|UNLOGGED\s+|MATERIALIZED\s+)?(?:TABLE|VIEW|INDEX)\b"
                         r"|\b(?:ALTER|DROP)\s+(?:TABLE|VIEW|INDEX)\b|\bUPDATE\s+(?:ONLY\s+)?[\w.\"]+(?:\s+(?:AS\s+)?\w+)?\s+SET\b"
                         r"|\bCOPY\s+[\w.\"]+(?:\s*\([^)]*\))?\s+(?:TO|FROM)\b", re.I)
_SQL_UPPER = re.compile(r"\b(?:FROM|INTO|UPDATE|TABLE|SET|WHERE|RETURNING|TRUNCATE|UNION|COPY)\b")
_LIT_GAP = re.compile(r"[\s+,]*(?:\.concat\s*\(\s*)?")
_KEY_AT_END = re.compile(r"(?:^|[{,]|\n)\s*(?:([A-Za-z_$][\w$]*)|'([A-Za-z_]\w*)'|\"([A-Za-z_]\w*)\")\s*\??:\s*$")
# an import / require path: `import x from '...'`, `export * from '...'`, side-effect `import '...'` (quote ' or ", never a tagged template), or a call
# `import(...)` / `require(...)` that is not a METHOD (`loader.import('t')`, `this.require('t')`)
_FROM_IMPORT_BEFORE = re.compile(r"(?:^|[\s;}])(?:from|import)\s*$")
_CALL_IMPORT_BEFORE = re.compile(r"(?<![.\w$])(?:import|require)\s*\(\s*$")
_TYPE_NAME_BEFORE = re.compile(r"\b(?:type|interface|enum|class)\s+$")
_PROSE_WORD = re.compile(r"[A-Za-z]+[.,;:!?]*")


def _literal_chain(mod: dict, i: int, radius: int = 2) -> str:
    """Literal `i` and the literals joined to it by `+` / `,` / `.concat(` (comments between are blanked, so they do not hide the join), up to
    `radius` each side: the text a table name or an SQL fragment of one concatenation is read from."""
    spans, cm = mod["spans"], mod["cmask"]

    def gap_ok(a: int, b: int) -> bool:
        end = spans[a][0] + len(spans[a][1]) + 1
        return _LIT_GAP.fullmatch(cm[end:spans[b][0] - 1]) is not None
    lo = i
    while lo > 0 and i - lo < radius and gap_ok(lo - 1, lo):
        lo -= 1
    hi = i
    while hi + 1 < len(spans) and hi - i < radius and gap_ok(hi, hi + 1):
        hi += 1
    return " ".join(spans[k][1] for k in range(lo, hi + 1))


def _strict_prose(c: str, tok: str) -> bool:
    """A literal is prose only if it has five or more whitespace-separated words besides the name, EVERY one purely alphabetic with at most
    trailing sentence punctuation (`. , ; : ! ?`) -- no `_`, digit, `( ) = * ' " ` , -`, no identifier-like run -- and the name stands as its own
    word (optionally in `( )` or with trailing punctuation). A snake_case run, a comma list, `a as b` or a JSON array string is never prose, and
    neither is a literal holding the word `table` or `union` (`table t_x union all table u` is valid SQL made only of alphabetic words)."""
    words = c.split()
    if any(w.strip(".,;:!?").lower() in ("table", "union") for w in words):
        return False                                               # `table t_x union all table u` is valid SQL made of alphabetic words
    name = re.compile(r"\(?" + re.escape(tok) + r"[.,;:!?)]*")
    others = [w for w in words if not name.fullmatch(w)]
    if len(others) == len(words) or len(others) < 5:
        return False
    return all(_PROSE_WORD.fullmatch(w) for w in others)


def _opener_before(blank: str, i: int):
    """Index of the innermost unmatched opener `([{` before offset `i` in the comment- and string-blanked text, or None."""
    depth, k = 0, i - 1
    while k >= 0:
        ch = blank[k]
        if ch in ")]}":
            depth += 1
        elif ch in "([{":
            if depth == 0:
                return k
            depth -= 1
        k -= 1
    return None


_NOT_A_CALL_WORDS = frozenset({"return", "await", "yield", "typeof", "void", "throw", "delete"})


def _prev_nonspace(blank: str, i: int) -> int:
    k = i - 1
    while k >= 0 and blank[k].isspace():
        k -= 1
    return k


def _paren_is_call(blank: str, k: int) -> bool:
    """Is the `(` at `k` a call / `new` argument list (as opposed to a grouping paren after `=>`, `return`, `=`, `:`, an operator or a bracket)?"""
    j = _prev_nonspace(blank, k)
    if j < 0:
        return False
    ch = blank[j]                                                  # `=> (` and `= (` end in a non-word char: a grouping paren
    if ch == ">":
        return not (j > 0 and blank[j - 1] == "=")                 # `query<Row>(` / `new Q<R>(` (a generic close) is a call; `=> (` is not
    if ch == "." and j > 0 and blank[j - 1] == "?":
        return True                                                # `query?.(`
    if ch == "!":
        return True                                                # `query!(`
    if ch.isalnum() or ch in "_$":
        w = re.search(r"[A-Za-z_$][\w$]*$", blank[max(0, j - 40):j + 1])
        return not (w and w.group(0) in _NOT_A_CALL_WORDS)
    return ch in ")]"                                              # `f(x)(...)`, `a[0](...)`


def _object_is_call_arg(blank: str, o: int) -> bool:
    """Is the object literal opening at `o` a call argument (first or later)? A spread (`...{`) counts as handed on."""
    k = _prev_nonspace(blank, o)
    p = blank[k] if k >= 0 else ""
    if p == ".":
        return True
    if p == "(":
        return _paren_is_call(blank, k)
    if p == ",":
        q = _opener_before(blank, k)
        return q is not None and blank[q] == "(" and _paren_is_call(blank, q)
    return False


def _key_before(cm: str, i: int):
    """The (lower-cased) property key whose `:` ends the text before offset `i`, or None."""
    m = _KEY_AT_END.search(cm[max(0, i - 200):i])
    return (m.group(1) or m.group(2) or m.group(3)).lower() if m else None


def _value_context_ok(mod: dict, o: int) -> bool:
    """The object literal opening at `o` is a PROPERTY VALUE (of an object literal whose own context is ok, recursively) or a RETURN VALUE (`return {`,
    `=> {`, `=> ({`): never a call argument, a const holder, an array element or anything else."""
    blank, cm = mod["blank"], mod["cmask"]
    k = _prev_nonspace(blank, o)
    if k < 0:
        return False
    p = blank[k]
    if p == ":":
        if _key_before(cm, k + 1) is None:
            return False                                           # a ternary colon, not a property
        parent = _opener_before(blank, o)
        return parent is not None and blank[parent] == "{" and _value_context_ok(mod, parent)
    if p == "(" and not _paren_is_call(blank, k):
        k = _prev_nonspace(blank, k)                               # a grouping paren: look before it
        if k < 0:
            return False
        p = blank[k]
    if p == ">" and k > 0 and blank[k - 1] == "=":
        return True                                                # `=> {` / `=> ({`
    w = re.search(r"[A-Za-z_$][\w$]*$", blank[max(0, k - 40):k + 1])
    return bool(w and w.group(0) == "return")


def _is_provenance_element(mod: dict, i: int) -> bool:
    """Allow-list (1): the literal span `i` is a bare element of `provenance: { tables | source_tables: [ ... ] }` in an envelope that is a property
    value or return value of an object literal."""
    start, c = mod["spans"][i]
    blank, cm = mod["blank"], mod["cmask"]
    q = start - 1
    k = _prev_nonspace(blank, q)
    if k < 0 or blank[k] not in "[,":
        return False
    arr = _opener_before(blank, q)
    if arr is None or blank[arr] != "[" or _key_before(cm, arr) not in PROV_ARRAY_KEYS:
        return False
    j = start + len(c) + 1                                          # after the closing quote
    while j < len(blank) and blank[j].isspace():
        j += 1
    if j >= len(blank) or blank[j] not in ",]":
        return False
    po = _opener_before(blank, arr)
    if po is None or blank[po] != "{" or _key_before(cm, po) != "provenance":
        return False
    holder = _opener_before(blank, po)
    return holder is not None and blank[holder] == "{" and _value_context_ok(mod, holder)


def _is_prose_label(mod: dict, i: int, tok: str) -> bool:
    """Allow-list (2): the literal span `i` is the whole value of a PROSE key, strict prose, in an object literal that is not a call argument."""
    start, c = mod["spans"][i]
    blank, cm = mod["blank"], mod["cmask"]
    if _key_before(cm, start - 1) not in PROSE_KEYS:
        return False
    o = _opener_before(blank, start - 1)
    if o is None or blank[o] != "{" or _object_is_call_arg(blank, o):
        return False
    return _strict_prose(c, tok)


def _in_interpolation(c: str, rel: int) -> bool:
    """Is offset `rel` of a template literal's content inside a `${ ... }` expression (code, not text)?"""
    depth, k = 0, 0
    while k < rel:
        if c.startswith("${", k):
            depth += 1
            k += 2
            continue
        if depth and c[k] == "{":
            depth += 1
        elif depth and c[k] == "}":
            depth -= 1
        k += 1
    return depth > 0


def _literal_ref_kind(mod: dict, i: int, off: int, tok: str) -> str:
    start, c = mod["spans"][i]
    cm, txt = mod["cmask"], mod["txt"]
    chain = _literal_chain(mod, i)
    if _SQL_STRONG.search(chain) or _SQL_UPPER.search(chain):
        return SELECT_REF
    before, after = c[:off - start], c[off - start + len(tok):]
    if txt[start - 1] == "`" and _in_interpolation(c, off - start):
        return AMBIGUOUS_REF                                      # code inside `${ ... }`: a call argument, a name built at run time
    if before.endswith("}") or after.startswith("${"):
        return AMBIGUOUS_REF                                      # glued to an interpolation: a name built at run time
    if not after.strip() and re.match(r"\s*(?:\+|\.concat\b)", txt[start + len(c) + 1:start + len(c) + 12]):
        return AMBIGUOUS_REF                                      # the tail of a concatenated name
    pre = cm[max(0, start - 1 - 120):start - 1]
    if _CALL_IMPORT_BEFORE.search(pre) or (txt[start - 1] in "'\"" and _FROM_IMPORT_BEFORE.search(pre)):
        return LABEL                                              # (4) an import / require path
    if c.strip() == tok and _is_provenance_element(mod, i):
        return LABEL                                              # (1) the provenance envelope
    if _is_prose_label(mod, i, tok):
        return LABEL                                              # (2) strict prose under a prose key
    return AMBIGUOUS_REF                                          # everything else is a reach


def _code_ref_kind(mod: dict, off: int, end: int) -> str:
    if _TYPE_NAME_BEFORE.search(mod["cmask"][max(0, off - 24):off]):
        return LABEL                                              # (4) a type / interface / enum / class name
    return AMBIGUOUS_REF


_PROBE_MARK = re.compile(r"""['"`]service_probe['"`]""")
_PROBE_OPEN_KIND = re.compile(r"""\bkind\s*:\s*[A-Za-z_$]""")        # `kind: PROBE_KIND`: a kind the scan cannot read
_PROBE_SPREAD = re.compile(r"\.\.\.\s*[A-Za-z_$(\[{]")                # `...base`: a probe assembled from another object


def _in_probe_envelope(mod: dict, off: int) -> bool:
    """Is `off` inside a `service_probe` envelope, at ANY depth below the marker object? Walks every enclosing object literal: one that holds the
    string 'service_probe', a `kind:` whose value is not a literal, or a spread (the kind is then unreadable: the safe direction)."""
    blank, cm = mod["blank"], mod["cmask"]
    pos, first = off, True
    while True:
        lo, hi = _enclosing_object(blank, pos)
        whole = (lo, hi) == (0, len(blank))
        if whole and not first:
            return False                                           # no further enclosing object: the whole file is not a parent envelope
        if _PROBE_MARK.search(cm[lo:hi]) or _PROBE_OPEN_KIND.search(blank[lo:hi]) or _PROBE_SPREAD.search(blank[lo:hi]):
            return True
        if whole or lo <= 0:
            return False
        pos, first = lo, False


def _ref_occurrences(mod: dict, tok: str, service: bool = False) -> list[tuple[int, str]]:
    """`(offset, kind)` per whole-word occurrence of `tok` (what `_ref_kinds_mod` classifies, with the position kept: review fix MED-3 reads the occurrences INSIDE one entry)."""
    starts = [p for p, _c in mod["spans"]]
    out = []
    for m in re.finditer(r"\b" + re.escape(tok) + r"\b", mod["cmask"]):
        i = bisect.bisect_right(starts, m.start()) - 1
        if i >= 0 and m.start() < starts[i] + len(mod["spans"][i][1]):
            k = _literal_ref_kind(mod, i, m.start(), tok)
        else:
            k = _code_ref_kind(mod, m.start(), m.end())
        if service and k != SELECT_REF and _in_probe_envelope(mod, m.start()):
            k = PROBE_REF
        out.append((m.start(), k))
    return out


def _ref_kinds_mod(mod: dict, tok: str, service: bool = False) -> list[str]:
    """One kind per whole-word occurrence of `tok` in the module's comment-masked text, in order (comments are not occurrences: R51 reads them).
    `service`: the asset's REGISTRY kind is `service` -- an occurrence inside a `service_probe` envelope is then a PROBE (a reach, named as such)."""
    return [k for _o, k in _ref_occurrences(mod, tok, service)]


def _ref_kinds(txt: str, tok: str, service: bool = False) -> list[str]:
    """`_ref_kinds_mod` over a source text (the unit-test and one-off entry; the scan itself reads each file once)."""
    return _ref_kinds_mod(_dens_facts(txt), tok, service)


def _module_reaches(kinds) -> bool:
    """A module reaches the asset unless every occurrence is a label: one SELECT or one unclassifiable form decides."""
    return any(k != LABEL for k in kinds)


_DECL_LINE = re.compile(r"^(?:import\b|export\b|(?:async\s+)?function\b|(?:const|let|var|class|interface|type|enum)\b)", re.M)


def _ts_decl_starts(mask: str) -> list[int]:
    """Offsets where a TOP-LEVEL declaration begins (the unit this scan calls a capability): the point at which a
    bracket nest returns to depth 0, a `;` at depth 0, and a line that starts a declaration keyword at depth 0.
    `mask` has comments and string contents blanked, so a brace in either never counts. Limit, disclosed: a regex
    literal holding a bracket is not recognised."""
    starts, depth = {0}, 0
    at_decl = {m.start() for m in _DECL_LINE.finditer(mask)}
    for i, ch in enumerate(mask):
        if depth == 0 and i in at_decl:
            starts.add(i)
        if ch in "{([":
            depth += 1
        elif ch in "})]":
            depth = max(depth - 1, 0)
            if depth == 0:
                starts.add(i + 1)
        elif ch == ";" and depth == 0:
            starts.add(i + 1)
    return sorted(starts)


_DENS_RAW: dict[tuple, frozenset] = {}
_DENS_FACTS: dict[tuple, dict] = {}


def _dens_words(f: Path) -> tuple[tuple, frozenset]:
    """Every `\\w+` word of the file's RAW text (comments included) — a cheap pre-filter: a token that is not a word
    here is in no comment and no code, so the expensive parse below never runs for the file."""
    st = f.stat()
    key = (str(f), st.st_mtime_ns, st.st_size)
    if key not in _DENS_RAW:
        _DENS_RAW[key] = frozenset(re.findall(r"\w+", f.read_text(encoding="utf-8", errors="replace")))
    return key, _DENS_RAW[key]


def _enclosing_object(blank: str, pos: int) -> tuple[int, int]:
    """`(start, end)` of the innermost `{ ... }` around `pos` in the comment- and string-blanked text — the object
    literal a `density_contract:` key sits directly in: the capability ENTRY it declares the contract for. No enclosing
    brace: the whole text."""
    depth, i = 0, pos - 1
    while i >= 0:
        ch = blank[i]
        if ch == "}":
            depth += 1
        elif ch == "{":
            if depth == 0:
                break
            depth -= 1
        i -= 1
    else:
        return 0, len(blank)
    depth = 0
    for j in range(i, len(blank)):
        if blank[j] == "{":
            depth += 1
        elif blank[j] == "}":
            depth -= 1
            if depth == 0:
                return i, j + 1
    return i, len(blank)


_DENSITY_KEY_VALUE = re.compile(r"\bdensity_contract\s*\??\s*:\s*")
_FACETS_LIST = re.compile(r"\bfacets\s*:\s*\[([^\]]*)\]")


def _contract_has_facets(blank: str, key_pos: int) -> bool:
    """TI-L0-04 (folded from held PR #3105): does the `density_contract:` declared at `key_pos` hold, as an INLINE object, a `facets` list with at least one entry?
    `blank` is the comment- and string-blanked text (brace structure; string delimiters kept, so a list of strings is non-empty). A contract that is an identifier
    or call, a `facets` that is not an inline list, an empty list, or a `facets:` key outside the contract object (a sibling property, a comment) is NOT
    established: False. Only the contract object's own top level is read (a nested object's `facets` is not the contract's)."""
    m = _DENSITY_KEY_VALUE.match(blank, key_pos)
    if m is None or m.end() >= len(blank) or blank[m.end()] != "{":
        return False
    depth, end = 0, None
    for j in range(m.end(), len(blank)):
        depth += (blank[j] == "{") - (blank[j] == "}")
        if depth == 0:
            end = j + 1
            break
    if end is None:
        return False
    depth_at, d = [], 0
    for ch in blank[m.end():end]:                       # bracket depth BEFORE each character; the contract's own keys sit at depth 1
        depth_at.append(d)
        d += (ch in "{[(") - (ch in "}])")
    for fm in _FACETS_LIST.finditer(blank, m.end(), end):
        at = fm.start() - m.end()
        if depth_at[at] == 1 and re.search(r"['\"`\w]", fm.group(1)):
            return True
    return False


def _dens_facts(txt: str) -> dict:
    """The module text parsed once (see `_dens_module`): comment-masked text, string-blanked text, declaration starts, `density_contract:`
    declarations, string-literal spans, desync, run-time table access."""
    blank = _ts_mask(txt, blank_strings=True)
    spans = _ts_literal_spans(txt)
    cmask = _ts_mask(txt)
    dyn_from = _dynamic_from(txt, spans)
    return dict(
        txt=txt,
        cmask=cmask,
        blank=blank,
        starts=_ts_decl_starts(blank),
        contracts=[m.start() for m in _DENSITY_DECL.finditer(blank)],
        contract_objs=[(m.start(), *_enclosing_object(blank, m.start())) for m in _DENSITY_DECL.finditer(blank)],
        spans=spans,
        desynced=_ts_desynced(txt),
        dynamic_from=dyn_from,
    )


def _dens_module(f: Path, key: tuple) -> dict:
    """The file parsed once: comment-masked text (strings kept: the SQL lives in them), the declaration starts, the
    offsets of `density_contract:` DECLARATIONS (R232: comments stripped, strings blanked), and the string literals
    with their offsets."""
    if key not in _DENS_FACTS:
        _DENS_FACTS[key] = _dens_facts(f.read_text(encoding="utf-8", errors="replace"))
    return _DENS_FACTS[key]


def _decl_of(mod: dict, pos: int) -> int:
    return bisect.bisect_right(mod["starts"], pos)


_WORD_SELECT = re.compile(r"\bSELECT\b", re.I)
_NOT_A_READ_PREFIX = re.compile(r"\b(?:INSERT|CREATE|MERGE|COPY|UNION|INTERSECT|EXCEPT)\b", re.I)


_SQL_TOKEN = re.compile(r"'(?:[^']|'')*'|/\*.*?\*/|--[^\n]*", re.S)


def _sql_flat(sql: str, strings: bool = True) -> str:
    """`sql` with its SQL comments (`/* … */`, `-- …`) — and, with `strings`, its `'…'` literals — blanked to spaces,
    positions kept: a paren or a keyword inside a comment or a string is not SQL structure."""
    def blank(m):
        t = m.group(0)
        return t if (t[0] == "'" and not strings) else re.sub(r"[^\n]", " ", t)
    return _SQL_TOKEN.sub(blank, sql)


# the read side of a write / a set operation, matched strictly (SQL syntax, not prose) when the evidence is only the
# PREVIOUS literal of a concatenation
_NOT_A_READ_STRICT = re.compile(
    r"\b(?:INSERT\s+INTO|MERGE\s+INTO|CREATE\s+(?:OR\s+REPLACE\s+)?(?:TEMP\w*\s+|MATERIALIZED\s+|UNLOGGED\s+)?(?:TABLE|VIEW)"
    r"|COPY\s+\S+|UNION(?:\s+ALL)?|INTERSECT|EXCEPT)\b", re.I)


def _owner_select(head: str):
    """The SELECT that owns a FROM sitting at the end of `head`: the last whole-word SELECT after which the
    parentheses balance (a SELECT inside an earlier `( … )` belongs to that sub-query, not to this FROM). Comments and
    string literals are blanked first: a `)` in either is not a paren."""
    flat = _sql_flat(head)
    for m in reversed(list(_WORD_SELECT.finditer(flat))):
        depth = 0
        for ch in flat[m.end():]:
            depth += (ch == "(") - (ch == ")")
            if depth < 0:
                break
        if depth == 0:
            return m
    return None


def _is_served_read(head: str, sel_start: int, before: str = "") -> bool:
    """Is the SELECT at `sel_start` of `head` a served READ — not a `( SELECT …` sub-query (WHERE .. IN, EXISTS, a CTE
    body) and not the read side of an INSERT / CREATE … AS / MERGE / COPY, nor a UNION / INTERSECT / EXCEPT branch
    (its column names come from the first branch)? SQL comments are blanked before the test. When the SELECT opens its
    literal (`'… IN (' + 'SELECT …'`), its context is the end of the PREVIOUS literal (`before`): a `(`, or a write /
    set-operation prefix, there makes it not-a-read. The context is judged on what is visible; a caller that cannot
    see it (a SELECT reached through a helper, a variable) is not seen at all — disclosed limit."""
    pre = _sql_flat(head[:sel_start], strings=False).rsplit(";", 1)[-1]
    if not pre.strip() and before:
        b = _sql_flat(before, strings=False).rsplit(";", 1)[-1]
        return not b.rstrip().endswith("(") and not _NOT_A_READ_STRICT.search(b)
    return not pre.rstrip().endswith("(") and not _NOT_A_READ_PREFIX.search(pre)


def _served_selects(table: str, lits: list[str], strict: bool = False):
    """`(i, match, alias, select_list)` for every `FROM|JOIN <table>` in literal `i` that sits under a SELECT list
    (R23's reader, factored so the Dens scan and `field_reach` read a served select identically). A FROM counts only
    with a SELECT in front of it — in the same literal or, for `'SELECT a, b ' + 'FROM t'`, the literal before (prose
    that says "from <table>" is not a query). `SELECT` is a whole word (`is_selected` is not one).
    `strict` (the Dens scan): the FROM's OWN select is found by paren balance, and when it is not a served read
    (`_is_served_read`) `select_list` is None — the select is counted as served but its list credits no tier column."""
    rx = re.compile(r"\b(?:FROM|JOIN)\s+(?:ONLY\s+)?(?:public\.)?\"?" + re.escape(table) +
                    r"\b\"?(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z_0-9]*))?", re.I)
    for i, lit in enumerate(lits):
        for m in rx.finditer(lit):
            alias = m.group(1) if m.group(1) and m.group(1).lower() not in _ALIAS_STOP else None
            head = lit[:m.start()]
            k = _owner_select(head) if strict else next(iter(reversed(list(_WORD_SELECT.finditer(head)))), None)
            if k is not None:
                sel = head[k.end():]
                ok = _is_served_read(head, k.start(), lits[i - 1] if i else "")
            elif strict and _WORD_SELECT.search(head):
                continue                                   # a SELECT exists but none owns this FROM (EXTRACT(.. FROM t))
            else:
                prev = lits[i - 1] if i else ""
                k2 = _owner_select(prev) if strict else next(iter(reversed(list(_WORD_SELECT.finditer(prev)))), None)
                if k2 is None or re.search(r"\bFROM\b", _sql_flat(prev[k2.start():]), re.I):
                    continue
                sel = prev[k2.end():]
                ok = _is_served_read(prev, k2.start(), lits[i - 2] if i > 1 else "")
            yield i, m, alias, (sel if (ok or not strict) else None)


_SEL_CAST = re.compile(r"::\s*[A-Za-z_][\w.]*(?:\s*\(\s*\d+(?:\s*,\s*\d+)?\s*\))?(?:\[\])*")
_SEL_ALIAS = re.compile(r"\s+AS\s+(?:\"[^\"]*\"|\w+)\s*$", re.I)
_SEL_PLAIN_ITEM = re.compile(r"(?:DISTINCT\s+)?(?:\"?([A-Za-z_]\w*)\"?\s*\.\s*)?\"?([A-Za-z_]\w*)\"?", re.I)


def _plain_item(item: str) -> tuple[str | None, str] | None:
    """`(qualifier, name)` when a select item IS a column reference — `col`, `q.col`, `"col"`, with an optional `::cast`
    and `AS alias` — else None (a function call, CASE, arithmetic, a sub-select, `*`: never a column by itself)."""
    it = _SEL_ALIAS.sub("", _SEL_CAST.sub("", item.strip())).strip()
    m = _SEL_PLAIN_ITEM.fullmatch(it)
    return (m.group(1), m.group(2)) if m else None


def _flatten_select(clean: str) -> str:
    """The select text as a list of top-level items: a top-level `FROM` (the scanner's text can carry one — a
    sub-select's truncated list, a driving table) and an unmatched `)` (the cut-off `(SELECT …` opener) become item
    separators, so each clause is read as its own item and an item is never glued to its FROM clause."""
    out, depth, i = [], 0, 0
    while i < len(clean):
        ch = clean[i]
        m = re.match(r"FROM\b", clean[i:], re.I) if (ch in "Ff" and (i == 0 or not re.match(r"\w", clean[i - 1]))) else None
        if m and depth == 0:
            out.append(" , ")
            i += 4
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            if depth == 0:
                out.append(" , ")
                i += 1
                continue
            depth -= 1
        out.append(ch)
        i += 1
    return "".join(out)


def _select_tier(sel: str, alias: str | None, table: str, cols: list[str] | None, declared=()) -> tuple[str, list[str]]:
    """Does this served select list carry a tier column? `(TIER_YES|TIER_NO|TIER_UNKNOWN, tier columns)`.
    What IS a tier column is the CLOSED vocabulary of `dens_tier_counts` (REGISTRY_REVISION 23): exactly `tier` / `verification_pass_status`, or a column the asset
    DECLARES in `density_tier_columns` (`declared`, this table's declared names), and never a deny-listed one (`cost_tier`, `access_tier`, ...).
    A tier column is carried only when a select ITEM is the column itself (`_plain_item`): `count(DISTINCT tier)`,
    `count(*) FILTER (WHERE tier = …)`, `lower(tier)`, `CASE … END AS tier` carry none. With the table's columns known
    (catalog) the item's name must also be one of them and `*` / `<alias>.*` expands to every column; with them
    unknown only a tier NAME counts (unqualified, or qualified by this table/alias) and `*` / a `${...}` run-time list
    stay UNKNOWN — never read as a tier column and never as proof of its absence.
    ATTRIBUTION LIMIT, disclosed: the scanner hands over the text after the LAST `SELECT` before the asset's `FROM` /
    `JOIN`. A `(SELECT …)` in the list, or any `FROM` in it (a sub-select's truncated list, or a driving table the
    asset is only JOINed to), means an UNQUALIFIED name cannot be attributed to the asset's table: UNKNOWN, never YES.
    A name qualified by the asset's own table/alias still counts.
    DELIBERATE OVER-BLOCKING, kept: a `(SELECT …)` scalar sub-select anywhere in the list makes the whole list UNKNOWN
    (PARTIAL at best, never PASS) even when a tier column is also qualified by the asset's alias — PASS is the closable
    direction (§N.8), so the ambiguity is resolved against it."""
    dynamic = "${" in sel
    clean = re.sub(r"'[^']*'", "''", sel)
    if re.search(r"\(\s*SELECT\b", clean, re.I):
        return TIER_UNKNOWN, []
    has_from = bool(re.search(r"\bFROM\b", clean, re.I))
    mine = {x.lower() for x in (alias, table) if x}
    lower = {c.lower() for c in cols} if cols else set()
    got: set[str] = set()
    star = unattributed = False
    for item in _split_top(_flatten_select(clean)):
        it = item.strip()
        if re.fullmatch(r"(?:DISTINCT\s+)?\*", it, re.I) or any(re.fullmatch(rf"{re.escape(m)}\.\*", it, re.I) for m in mine):
            star = True
            got.update(c for c in lower if dens_tier_counts(c, declared))
            continue
        pi = _plain_item(it)
        if not pi:
            continue
        q, name = pi
        if not dens_tier_counts(name, declared) or (cols and name.lower() not in lower):
            continue
        if q:
            if q.lower() in mine:
                got.add(name.lower())
        elif has_from:
            unattributed = True
        else:
            got.add(name.lower())
    if got:
        return TIER_YES, sorted(got)
    if unattributed:
        return TIER_UNKNOWN, []
    return (TIER_UNKNOWN if ((star and not cols) or dynamic) else TIER_NO), []


# ───────────── DENS-SCANNER (REGISTRY_REVISION 26): registry-driven table names and declared facets ─────────────
_DYN_FROM_EXPR = re.compile(r"\b((?:FROM|JOIN)\s+(?:ONLY\s+)?)\$\{\s*([^{}]+?)\s*\}", re.I)
_CONST_MAP_ENTRY = re.compile(r"\s*(?:[A-Za-z_$][\w$]*|'[^'\n]*'|\"[^\"\n]*\")\s*:\s*(?:'([^'\n]*)'|\"([^\"\n]*)\")\s*(?:,|$)")


def _const_map_values(mod: dict, name: str):
    """The string values of a module-level `const NAME[: type] = { k: 'v', ... }` whose EVERY entry is `key: 'string literal'` (else None: a computed or
    non-literal entry means the set of names is not readable)."""
    m = re.search(r"\bconst\s+" + re.escape(name) + r"\b[^=\n]*=\s*\{", mod["cmask"])
    if not m:
        return None
    lo, hi = _enclosing_object(mod["blank"], m.end())
    if lo != m.end() - 1:
        return None
    body, vals, pos = mod["txt"][lo + 1:hi - 1], [], 0
    while pos < len(body) and body[pos:].strip():
        e = _CONST_MAP_ENTRY.match(body, pos)
        if not e:
            return None
        vals.append(e.group(1) if e.group(1) is not None else e.group(2))
        pos = e.end()
    return set(vals) if vals else None


def _dyn_names(mod: dict, expr: str):
    """The table names a `FROM ${expr}` interpolation can take, when readable from the module: `expr` is a const string, an identifier const-assigned a const string or
    `MAP[...]` / `MAP.key` of a const map of string literals, or `MAP[...]` itself. None = not readable (a parameter, a call, a computed map)."""
    expr = expr.strip()
    mm = re.fullmatch(r"([A-Za-z_$][\w$]*)\s*(?:\[[^\]]*\]|\.[A-Za-z_$][\w$]*)", expr)
    if mm:
        return _const_map_values(mod, mm.group(1))
    if not re.fullmatch(r"[A-Za-z_$][\w$]*", expr):
        return None
    a = re.search(r"\bconst\s+" + re.escape(expr) + r"\b[^=\n]*=\s*([^\n;]+)", mod["cmask"])
    if not a:
        return None
    rhs = a.group(1).strip()
    lit = re.fullmatch(r"'([^'\n]*)'|\"([^\"\n]*)\"", rhs)
    if lit:
        return {lit.group(1) if lit.group(1) is not None else lit.group(2)}
    return _dyn_names(mod, rhs) if re.fullmatch(r"[A-Za-z_$][\w$]*\s*(?:\[[^\]]*\]|\.[A-Za-z_$][\w$]*)", rhs) else None


def _dyn_lits(mod: dict, table: str, lits: list[str]) -> tuple[list[str], list[int]]:
    """`lits` with every `FROM|JOIN ${expr}` whose readable name set (`_dyn_names`) contains `table` rewritten to name it, so the one served-select reader sees the
    registry-driven select the way it runs when that name is picked; the indexes of the literals rewritten are returned (empty = none does). The select list is
    unchanged, so a run-time list stays UNKNOWN."""
    changed, out = [], []
    for i, lit in enumerate(lits):
        def rep(m):
            names = _dyn_names(mod, m.group(2))
            if names and table in names:
                if i not in changed:
                    changed.append(i)
                return m.group(1) + table
            return m.group(0)
        out.append(_DYN_FROM_EXPR.sub(rep, lit))
    return out, changed


def _entry_object(blank: str, pos: int) -> tuple[int, int]:
    """(review fix MED-1) The capability ENTRY around `pos`: walking outward from the innermost `{ ... }`, the first object that holds, at its own top level, a
    `density_contract` / `handler` / `run` / `id` / `name` key; none found: the innermost object (a conservative fallback, never the whole declaration of a function that
    registers several tools). `blank` is the comment- and string-blanked text."""
    lo, hi = _enclosing_object(blank, pos)
    first, p = (lo, hi), pos
    while (lo, hi) != (0, len(blank)):
        d, hit = 0, False
        for m in re.finditer(r"[{}\[\]()]|\b(?:density_contract|handler|run|id|name)\b\s*[:(]", blank[lo:hi]):
            t = m.group(0)
            if t in "{[(":
                d += 1
            elif t in "}])":
                d -= 1
            elif d == 1:
                hit = True
                break
        if hit:
            return lo, hi
        p = lo
        lo, hi = _enclosing_object(blank, p)
        if lo >= p:
            break
    return first


def _facet_pins(lits, column: str) -> tuple[set, bool, bool]:
    """`(values pinned, bound, or_seen)` for `column` over the literals given (the caller passes the literals of ONE capability entry, `_entry_object`; review fix MED-1): the string values a literal predicate pins (`col = 'v'`, `col IN ('v', ..)`,
    `col = ANY(ARRAY['v', ..])`, `col = ANY('{v,..}')`; an interpolated value is not a pin) and whether the column is also filtered by a bind parameter (`col = $n`,
    `col = ANY($n)`, `col IN ($n)`), whose value the SQL does not carry. `or_seen`: a literal that pins a value also holds an `OR` (the predicate may be satisfied by another
    branch, so it pins nothing: the caller refuses the attribution)."""
    c = r"(?<![\w])(?:\w+\.)?\"?" + re.escape(column) + r"\"?\b"
    vals, bound, or_seen = set(), False, False
    for lit in lits:
        got = set()
        for m in re.finditer(c + r"\s*=\s*'((?:[^']|'')*)'", lit):
            got.add(m.group(1).replace("''", "'"))
        for m in re.finditer(c + r"\s+IN\s*\(([^)]*)\)", lit, re.I):
            got.update(v.replace("''", "'") for v in re.findall(r"'((?:[^']|'')*)'", m.group(1)))
        for m in re.finditer(c + r"\s*=\s*ANY\s*\(\s*(?:ARRAY\s*)?\[([^\]]*)\]", lit, re.I):
            got.update(v.replace("''", "'") for v in re.findall(r"'((?:[^']|'')*)'", m.group(1)))
        for m in re.finditer(c + r"\s*=\s*ANY\s*\(\s*'\{([^}]*)\}'", lit, re.I):
            got.update(v.strip().strip('"') for v in m.group(1).split(",") if v.strip())
        if got and re.search(r"\bOR\b", lit, re.I):
            or_seen = True
        vals |= got
        if re.search(c + r"\s*(?:=\s*(?:ANY\s*\(\s*)?|\s+IN\s*\(\s*)\$", lit, re.I):
            bound = True
    return {v for v in vals if "${" not in v}, bound, or_seen


def _name(rel: Path, root: str, first: bool) -> str:
    return rel.as_posix() if first else f"{root}/{rel.as_posix()}"


def capability_scan(caps_dirs, tables: list[str], shared=(), columns: dict | None = None, outside_roots=(), service: bool = False,
                    tier_declared: dict | None = None, facets: dict | None = None) -> dict:
    """E6.1 (d): the Dens scanner, repaired (N-22 ruling principle 4). Structural: it reads source, not behaviour.

    SCOPE. `caps_dirs` (one path or several; `measure()` passes `CAPS_ROOTS`, R23's serving roots) are read
    RECURSIVELY — every layer directory, the files at the layers root, both MCP roots — for every token in `tables`
    (target table, asset id, every `count_sql` table). A missing root is `scanned=False` (R222 / N3), never an N/A.
    `outside_roots` (the wider source trees) are probed ONLY so that an asset with a served select outside the serving
    roots is never read N/A: they grade nothing (no density contract lives there). The probe honours R51 (§N.8): a
    served select read in code is `outside`; otherwise the file is `outside_named` — and so also blocks N/A — when
    (a) only a COMMENT names a token, (b) the file is `.tsx` or the string scanner ends desynchronised on it (an
    apostrophe in JSX text, a quote in a regex literal: `_ts_desynced`) and ANY text names a token, or (c) it holds a
    token in code and selects `FROM ${...}` (a run-time table name). Limits, disclosed: a run-time table name built
    in a file that never names the asset or its table, and two stray quotes that re-sync the scanner by accident in a
    `.ts` file, are not seen; a names-map in a cleanly parsed `.ts` file (no select, no comment) does not block N/A.

    ATTRIBUTION. A token in `shared` (a table another asset also declares) never attributes a module to THIS asset:
    `chart_facts` would make every reader serve every asset. Attribution is per capability (a top-level declaration):
    a `density_contract:` counts for the asset only in a declaration that references it, and only a tier column in a
    served `SELECT ... FROM <the asset's table>` INSIDE THE SAME capability entry (the object literal holding the
    `density_contract:` key, whose value must be a real object/identifier) makes it dense; a sibling entry's select, a
    sub-select, an INSERT...SELECT or a UNION branch credits nothing. A serving-root file that names the asset but on
    which the string scanner loses sync (`_ts_desynced`) is returned in `unparsed` and grades NO_DETECTOR (never FAIL,
    never N/A; a PASS/PARTIAL earned in a clean file stands).

    TIER VOCABULARY (SS N-98, REGISTRY_REVISION 23) -- a CLOSED LIST (`dens_tier_counts`): a tier column is exactly `tier` / `verification_pass_status`, or a
    column the asset DECLARES in `density_tier_columns` (`tier_declared`: table (lower-case) -> declared names, only the asset's own target table), and never
    a deny-listed name (cost, price, pricing, plan, access, subscription, billing, fee, tariff, in any spelling, `dens_tier_denied_word`). `severity_tier`, `cost_tier` ... count for nothing undeclared.

    SELECT VS LABEL (SS N-74(a), REGISTRY_REVISION 14) -- a CLOSED ALLOW-LIST. A module that references a token in code is a reach (`modules`)
    unless EVERY occurrence is a label and it carries no strict served select (then it is `label_only`: it names the asset, it does not read it).
    A name is a label ONLY in: (1) an element of `provenance: { tables | source_tables: [...] }` in an envelope that is a property / return value of
    an object literal (not a call argument, not a const holder); (2) a strict-prose string (>= 5 purely alphabetic words besides the name) that is the
    whole value of `source`/`source_table`/`label`/`note`/`reason`/`description`/`message`/`title` in an object that is not a call argument; (3) --
    (a `service_probe` envelope is a REACH for a service-kind asset; for a data-kind asset its own keys are a reach, while a `provenance.tables` element
    inside it is still context (1)); (4) an import / require path, a type / interface / enum / class name. EVERYTHING ELSE (a bare name in a
    list or map, a label key's value, an identifier-looking word, a path, a URL, an alias, a name in a call, an interpolation or a concatenation) is a
    reach: there is no consumption tracking and no shape heuristic. The rest of the scan (attribution, contract and tier, `served`, `shared_only`,
    `comment_only`, the outside probe) is unchanged, so no PASS / PARTIAL / FAIL moves. COMMENTS: ONE rule (R51, strategist option ii): a comment
    that names the asset ANYWHERE in a module blocks the N/A, including a module whose code only labels it (`label_comment`).
    SERVICE ASSETS. `service` (measure() passes the asset's registry kind == 'service'): an occurrence inside a `service_probe` envelope, at any
    depth below the marker object, is a PROBE (a reach, named as such) so a service asset named only by its probe envelope stays NO_DETECTOR. The
    envelope's own keys are not in the allow-list for a data asset either (also a reach), so `service` changes the evidence NAME there, not the verdict;
    only a `provenance.tables` element inside an envelope differs (a LABEL for a data asset, a PROBE for a service asset). Whether
    Dens.served applies to services at all is a separate later declared rule.
    N/A MEANS "NOT SERVED DIRECTLY", NOT "UNUSED". `platform/python-sidecar/services/ka_vedha_gochara/writer.py` (a Python L3 writer) does read
    `FROM bg_phaladeepika_latta`; the rule says no SERVED module selects from it, which is true.
    SERVED SURFACE = TypeScript, BY DESIGN. Only `*.ts` under the serving roots (and `*.ts` / `*.tsx` in the outside probe) are read; a Python or
    sidecar reader of a table (`platform/python-sidecar/**`, e.g. the `ka_vedha_gochara` writer's `FROM bg_phaladeepika_latta`) is a build-time
    reader, not a served module, and never makes an asset served (R02's decision text, N-74(a)).

    Returns `modules` (by code, attributing tokens), `label_only` (modules that name it only as a label), `label_comment` (those of them a comment ALSO names: they block the N/A), `density` (capabilities that are dense), `dense`, `declared`
    (modules whose referencing capability declares the contract, with why the tier half is missing), `tier_only`,
    `served` (how many served selects of the asset's tables), `shared_only`, `comment_only` (R51: a comment names it,
    no code does), `outside`, `outside_named`."""
    dirs = [caps_dirs] if isinstance(caps_dirs, str) else list(caps_dirs)
    for d in dirs:
        if not (ROOT / d).is_dir():
            # R222 / N3: `scanned=False` — "no module references the table" was never established.
            return dict(modules=[], density=0, note=f"no capability directory at {d}", scanned=False)
    shared = set(shared or ())
    columns = columns or {}
    toks = [t for t in dict.fromkeys(tables) if t and t not in shared]
    sh = [t for t in dict.fromkeys(tables) if t and t in shared]
    hits, dense, declared, tier_only, shared_only, mentions, elsewhere = [], [], [], [], [], [], []
    facet_dense: list[str] = []         # TI-L0-04: modules whose contract-declaring entry has facets AND holds a real served read (read only for `uniform_authority`)
    label_only: list[str] = []
    label_comment: list[str] = []
    unparsed: list[str] = []
    facet_hits: list[str] = []
    facet_bound: list[str] = []
    dyn_resolved: list[str] = []
    served = 0
    seen: set[str] = set()
    for i, root in enumerate(dirs):
        base = ROOT / root
        for f in sorted(base.rglob("*.ts")):
            if f.name.endswith(".test.ts") or "__tests__" in f.parts:
                continue
            seen.add(str(f))
            name = _name(f.relative_to(base), root, i == 0)
            key, words = _dens_words(f)
            code_toks = [t for t in toks if t in words]
            code_sh = [t for t in sh if t in words]
            if not code_toks and not code_sh:
                continue
            mod = _dens_module(f, key)
            if mod["desynced"] and code_toks:
                # the string scanner lost sync on this file: what it reports (literals, comment blanking, declaration
                # boundaries, the contract) is unreliable, so it neither attributes the asset nor proves it unserved.
                # NO_DETECTOR for the asset (never FAIL, never N/A, never PASS from this file).
                unparsed.append(name)
                continue
            has = lambda t: re.search(r"\b" + re.escape(t) + r"\b", mod["cmask"])      # noqa: E731  (code, strings kept)
            ref_toks = [t for t in code_toks if has(t)]                                # R51: code, not a comment
            # DENS-FACET: a served select of a SHARED table is attributed to THIS asset when the capability ENTRY that holds it (`_entry_object`, never the whole top-level declaration of a
            # function that registers several tools: review fix MED-1) pins the facet column to declared values ONLY: at least one pin, every pinned value declared (an `IN ('x', 'declared')`
            # is not the asset's rows), and no pin-bearing literal carrying an `OR`. Attribution is per SELECT (`facet_pos`), not per declaration.
            facet_decls: set[int] = set()
            facet_pos: set[int] = set()
            if facets:
                lits0 = [c for _p, c in mod["spans"]]
                for t in (x for x in code_sh if has(x)):
                    fct = facets.get(t.lower())
                    if not fct:
                        continue
                    for li, _m, _a, _sel in _served_selects(t, lits0, strict=True):
                        pos0 = mod["spans"][li][0]
                        lo0, hi0 = _entry_object(mod["blank"], pos0)
                        if (lo0, hi0) == (0, len(mod["blank"])):
                            d0 = _decl_of(mod, pos0)
                            scope = [c for p, c in mod["spans"] if _decl_of(mod, p) == d0]
                        else:
                            scope = [c for p, c in mod["spans"] if lo0 <= p < hi0]
                        # review fix (re-check MED): the pin must sit in THIS select's own SQL (its literal and the literals directly joined to it). Only when the select's WHERE is a run-time
                        # `${...}` the pin may come from a STANDALONE filter literal of the same entry (one holding no SELECT: `const filters = ["fact_category = 'x'"]`), never from another select.
                        own = _literal_chain(mod, li)
                        pins, bound, or_seen = _facet_pins([own], fct["column"])
                        if not pins and re.search(r"\bWHERE\b[^;]*\$\{", own, re.I | re.S):
                            filt = [c for c in scope if not re.search(r"\bSELECT\b", c, re.I)]
                            pins, bound2, or_seen = _facet_pins(filt, fct["column"])
                            bound = bound or bound2
                        if pins and pins <= set(fct["values"]) and not or_seen:
                            facet_pos.add(pos0)
                            facet_decls.add(_decl_of(mod, pos0))
                        elif bound:
                            facet_bound.append(name)
            if not ref_toks and not facet_decls:
                if any(has(t) for t in code_sh):
                    shared_only.append(name)
                elif code_toks:
                    mentions.append(name)                                              # R51: named in a comment only
                continue
            kinds = [k for t in ref_toks for k in _ref_kinds_mod(mod, t, service)]                # SS N-74(a): SELECT or LABEL, per occurrence
            refs = {_decl_of(mod, m.start()) for t in ref_toks for m in re.finditer(r"\b" + re.escape(t) + r"\b", mod["cmask"])}
            lits = [c for _p, c in mod["spans"]]
            # DENS-SCANNER: a `FROM ${expr}` whose const map / const string names THIS asset's table is a select of it, and the declaration holding it references the asset
            dyn_lits: dict[str, list[str]] = {}
            if mod["dynamic_from"]:
                for t in ref_toks:
                    lt, changed = _dyn_lits(mod, t, lits)
                    if changed:
                        dyn_lits[t] = lt
                        refs |= {_decl_of(mod, mod["spans"][i][0]) for i in changed}
                        if name not in dyn_resolved:
                            dyn_resolved.append(name)
            refs_named = set(refs)                                                              # review fix MED-1: declarations that name the asset; the facet adds SELECTS, not declarations
            refs |= facet_decls
            # a capability ENTRY that declares the contract: the object literal holding the `density_contract:` key, in a
            # top-level declaration that references the asset
            cobjs = [o for o in mod["contract_objs"] if _decl_of(mod, o[0]) in refs]
            contract_decls = {_decl_of(mod, o[0]) for o in cobjs}
            sels: list[tuple[int, int, str, list[str]]] = []                           # (declaration, offset, tier state, columns)
            real_reads: set[int] = set()                                               # TI-L0-04: offsets of literals holding a real served read (sel is not None)
            # a select of a SHARED table counts only inside a capability that names THIS asset (by its id or by a table
            # only it declares): the asset id discriminates what the shared table cannot
            for t in ref_toks + [x for x in code_sh if has(x)]:
                for li, m, alias, sel in _served_selects(t, dyn_lits.get(t, lits), strict=True):
                    pos = mod["spans"][li][0]
                    d = _decl_of(mod, pos)
                    if d in refs_named or pos in facet_pos:
                        st = (_select_tier(sel, alias, t, columns.get(t.lower()) or columns.get(t), (tier_declared or {}).get(t.lower(), ()))
                              if sel is not None else (TIER_UNKNOWN, []))           # not the served read: credits nothing
                        sels.append((d, pos, st[0], st[1]))
                        if sel is not None and t in ref_toks:       # review fix MED-3: only a select of the asset's OWN (non-shared) table can carry a uniform_authority PASS
                            real_reads.add(pos)
                        served += 1
            if not sels and not _module_reaches(kinds):
                # every occurrence is a label (a provenance string, prose, a type name, an import path, a label-keyed value, a map key) and no
                # strict served select of the asset's table is in the module: it names the asset, it does not read it. Such a module never
                # carried a contract/tier credit (those need a select), so skipping the rest changes no PASS / PARTIAL / FAIL.
                label_only.append(name)
                # SS DENS L2 (strategist, option ii): ONE rule for comments -- a comment that names the asset ANYWHERE in a module blocks the N/A, even
                # when the module's code only labels it (a comment can assert served-ness the scan cannot read, R51)
                if any(len(re.findall(r"\b" + re.escape(t) + r"\b", mod["txt"])) > len(re.findall(r"\b" + re.escape(t) + r"\b", mod["cmask"]))
                       for t in code_toks):
                    label_comment.append(name)
                continue
            hits.append(name)
            if facet_decls:
                facet_hits.append(name)
            tier_decls = {d for d, _p, st, _c in sels if st == TIER_YES}
            inside = lambda o: [(st, cs) for _d, p, st, cs in sels if o[1] <= p < o[2]]    # noqa: E731
            dense_cols = sorted({c for o in cobjs for st, cs in inside(o) if st == TIER_YES for c in cs})
            # TI-L0-04 / review fix MED-3: the contract entry holds a real select of the asset's OWN table AND, inside that same entry, a non-label reference to the asset (its id or table)
            _own_refs = [off for t in ref_toks for off, k in _ref_occurrences(mod, t, service) if k != LABEL]
            if any(o[1] <= p < o[2] and _contract_has_facets(mod["blank"], o[0]) and any(o[1] <= off < o[2] for off in _own_refs) for o in cobjs for p in real_reads):
                facet_dense.append(name)
            if dense_cols:
                # PASS: the contract and the tier select belong to the SAME capability entry (the contract's own object)
                dense.append((name, dense_cols))
            else:
                # a contract counts for the asset only in a capability entry that also SERVES it (a served select of its
                # table inside the object that declares the contract) — a declaration that merely names the asset's id,
                # or a sibling entry's select, is not its serving capability
                why = set()
                for o in cobjs:
                    sts = {st for st, _c in inside(o)}
                    if sts:
                        why.add("tier carriage not established (a run-time select list, a sub-select / INSERT…SELECT / "
                                "UNION branch, or SELECT * with unknown columns)" if TIER_UNKNOWN in sts
                                else "no tier column in its served select")
                    elif any(sd == _decl_of(mod, o[0]) for sd, *_r in sels):
                        why.add("its served select of the table is in the same top-level declaration but a different "
                                "capability entry, not the object that declares the contract (attribution not established)")
                    elif sels:
                        why.add("its served select of the table is in a different top-level declaration of the module "
                                "(contract/select attribution not established)")
                if why:
                    declared.append((name, sorted(why)))
                else:
                    if tier_decls:
                        tier_only.append(name)
                    if sels and mod["contracts"]:
                        elsewhere.append(name)       # the module declares a contract, but not in a capability that serves it
    outside: list[str] = []
    outside_named: list[str] = []
    for root in outside_roots or ():
        base = ROOT / root
        if not base.is_dir():
            return dict(modules=[], density=0, note=f"no source directory at {root}", scanned=False)
        for ext in ("*.ts", "*.tsx"):
            for f in sorted(base.rglob(ext)):
                if str(f) in seen or DENS_OUTSIDE_EXCLUDE.search(str(f)):
                    continue
                seen.add(str(f))
                key, words = _dens_words(f)
                present = [t for t in toks if t in words]
                if not present:
                    continue
                mod = _dens_module(f, key)
                rel = f.relative_to(ROOT).as_posix() if f.is_relative_to(ROOT) else str(f)
                lits = [c for _p, c in mod["spans"]]
                if any(next(_served_selects(t, lits), None) for t in present):
                    outside.append(rel)
                    continue
                # No served select was read. That is a finding only for a file the scanner read RELIABLY (R51 / §N.8):
                if ext == "*.tsx" or mod["desynced"]:
                    # JSX text / a stray quote desynchronises the string scanner, so a select it missed is not evidence
                    # of none: ANY textual reference (code or comment) keeps the asset off the closable N/A
                    outside_named.append(f"{rel} (unparsed file — JSX, a nested template literal or a regex desynced the scanner: the asset is named in its text)")
                elif any(not re.search(r"\b" + re.escape(t) + r"\b", mod["cmask"]) for t in present):
                    outside_named.append(f"{rel} (a comment names it)")                          # R51: alone or beside code
                elif mod["dynamic_from"]:
                    outside_named.append(f"{rel} (holds the table and selects FROM a run-time table name)")
    return dict(modules=hits, label_only=label_only, label_comment=label_comment, density=len(dense), note="", scanned=True, comment_only=mentions, dense=dense,
                declared=declared, facet_dense=facet_dense, tier_only=tier_only, served=served, shared_only=shared_only, outside=outside, outside_named=outside_named, unparsed=unparsed, elsewhere=elsewhere,
                shared_tokens=sh, tokens=toks, roots=dirs, facet_attributed=facet_hits, facet_bound=sorted(set(facet_bound)), dynamic_resolved=dyn_resolved)


def _few(xs, n: int = 6) -> str:
    xs = list(xs)
    return ", ".join(xs[:n]) + (f" (+{len(xs) - n} more)" if len(xs) > n else "")


def _grade_dens(cap: dict, label: str, uniform_authority: bool = False) -> dict:
    """`Dens.served` from a `capability_scan` result. STRUCTURAL throughout: the contract is a declared property and the
    tier column a name in a served select — neither is a check that the served rows are in fact layered.
    PASS only when a capability that references the asset declares the contract AND a served select of its table in that
    same capability carries a tier column. See `capability_scan` for the attribution rule."""
    if cap.get("scanned") is not True:
        # R222 / N3 (A_REVIEW2 G2): a root was not scanned (missing), so "no module serves this table" was never
        # established. It read the closable N/A — one live ledger-copy run closed all 24 open L0 Dens.served gaps
        # with the dir pointed elsewhere.
        return dict(v=NO_DET, measured=f"NO_DETECTOR — {cap.get('note') or 'capability scan did not run'}; "
                                       "the served surface was never scanned")
    mods = cap.get("modules") or []
    outside = cap.get("outside") or []
    lab = cap.get("label_only") or []
    reach = (f"{len(mods)} module(s) reach it by code: {_few(mods)}"
             + (f" (+{len(lab)} name it only as a label)" if lab else "")
             + (f" ({len(cap['facet_attributed'])} attributed by the declared facet: {_few(cap['facet_attributed'], 3)})" if cap.get("facet_attributed") else "")
             + (f" (table name resolved from a module const map in: {_few(cap['dynamic_resolved'], 3)})" if cap.get("dynamic_resolved") else ""))
    tail = (f"; also a served select outside the scanned serving roots (not graded): {_few(outside, 3)}"
            if outside and mods else "")
    if mods and cap.get("density"):
        d = cap.get("dense") or []
        return dict(v=PASS, measured=(f"STRUCTURAL: {reach}; {cap['density']} capability(ies) declare density_contract AND "
                                      f"select a tier column from it ({_few(sorted({c for _n, cs in d for c in cs}))}) "
                                      f"in: {_few(n for n, _c in d)}" + tail))
    if uniform_authority and mods and cap.get("facet_dense"):
        # TI-L0-04 (SS Q2, folded from held PR #3105; PROVISIONAL until the J1 review): the asset DECLARES uniform authority (a reference vocabulary: every row the
        # same authority), so a tier column has nothing to distinguish; the contract's facets are what the served surface layers by. Reached only after the tier-column
        # PASS above, and only when the SAME capability entry that declares the contract (with a non-empty inline `facets` list) holds a real served SELECT of the table.
        return dict(v=PASS, measured=(f"STRUCTURAL: {reach}; uniform_authority declared (SS Q2, provisional until the J1 review): "
                                      f"{len(cap['facet_dense'])} capability(ies) declare density_contract with facets AND serve its table, "
                                      f"no tier column required: {_few(cap['facet_dense'])}" + tail))
    if mods and cap.get("declared"):
        det = "; ".join(f"{n}: {', '.join(w)}" for n, w in cap["declared"][:4])
        return dict(v=PARTIAL, measured=(f"STRUCTURAL: {reach}; a referencing capability declares density_contract but "
                                         f"{det}" + tail))
    if cap.get("unparsed"):
        # a serving-root file that names the asset could not be read reliably: what it serves, and whether it declares the
        # contract, is unknown — so neither FAIL (no contract anywhere) nor N/A (not served) was established
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — {len(cap['unparsed'])} serving-root file(s) naming {label} lose the "
                                        f"string scanner's sync (an unbalanced quote, a nested template literal, or a regex literal holding a "
                                        f"quote desynced it): {_few(cap['unparsed'], 4)}; its served "
                                        "select and density_contract cannot be read — never FAIL, never the closable N/A"))
    if mods and cap.get("served"):
        extra = ((f"; a tier column is selected without a contract in: {_few(cap['tier_only'])}" if cap.get("tier_only") else "")
                 + (f"; a density_contract is declared in {_few(cap['elsewhere'], 3)}, but not in a capability that serves it"
                    if cap.get("elsewhere") else ""))
        return dict(v=FAIL, measured=(f"STRUCTURAL: {reach}; {cap['served']} served select(s) of its table; no referencing "
                                      f"capability that serves it declares density_contract{extra}" + tail))
    if mods:
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — {reach}, but no served `SELECT ... FROM` its table was found "
                                        f"(no served select): whether it is served cannot be told by code"
                                        + tail))
    if outside:
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — no module in the serving roots references {label}, but a served "
                                        f"select of it sits outside the scanned serving roots: {_few(outside, 4)} — the "
                                        "served surface cannot be graded by this scan (never the closable N/A)"))
    if cap.get("outside_named"):
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — no module in the serving roots references {label}, but it is "
                                        f"named outside the scanned serving roots where a served select cannot be ruled "
                                        f"out (R51): {_few(cap['outside_named'], 4)} — never the closable N/A"))
    if cap.get("shared_only"):
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — only a table other assets share ({_few(cap.get('shared_tokens') or [])}) "
                                        f"is referenced, by {len(cap['shared_only'])} module(s): {_few(cap['shared_only'], 3)}; "
                                        f"the served surface cannot be attributed to {label} by code (never the closable N/A)"
                                        + (f"; a served select filters the declared facet column by a bind parameter in {_few(cap['facet_bound'], 3)}: its value is not "
                                           "readable from the SQL, never guessed" if cap.get("facet_bound") else "")))
    if cap.get("comment_only"):
        # R51 + §N.8: no module's CODE references the table, but comments do — the asset is named as served (e.g.
        # "already-served-elsewhere bg_dignity_reference", served by the generic MCP DB route). "Not served" was never
        # established, so never the closable N/A.
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — no capability module's code references {label}; named in comments "
                                        f"only in: {', '.join(cap['comment_only'])} — the served surface cannot be "
                                        "attributed by code (never the closable N/A)"))
    if cap.get("label_comment"):
        # SS DENS L2: a comment in a module that otherwise only labels the asset still blocks the N/A (one rule for comments, R51)
        return dict(v=NO_DET, measured=(f"NO_DETECTOR — no module's code selects from or otherwise reaches {label}; {len(lab)} module(s) name it only as a "
                                        f"label, and a comment in {_few(cap['label_comment'], 4)} also names it: a comment can assert that it is served, "
                                        "which the scan cannot read — never the closable N/A"))
    return _na(f"STRUCTURAL: 0 module(s) reference it by code in the {len(cap.get('roots') or [])} "
               "serving root(s) scanned, and no served select of it exists in the wider source "
               "scanned; declaring density_contract: 0"
               + (f"; {len(lab)} module(s) name it only as a label (a provenance string, prose, an id, a type name, an import path or a map "
                  f"key: not a select): {_few(lab)}" if lab else ""), "no-served-surface")


# ─────────── R23 (W2-3): field-level reachability over capability modules ───────────

# Every layer's capability modules: a field is dark only if NO retrieval capability, of any layer, reads it
# (an L4 capability reads chart_facts as readily as an L1 one). Tests and `__tests__` are not capabilities.
CAPS_ROOT = "platform/src/lib/retrieval/registry/layers"
# W2-3 C3 (gate review §5): the MCP server is a second serving plane. Its tools
# (`platform-mcp/src/tools/**`) run SQL directly, and so do the `platform-mcp/src/lib/**` modules those
# tools import (`lib/kala_envelope.ts`, imported by five `tools/kala_views/*` tools, reads
# kala_field_skill). The registry layers alone called ga_prashna_judgment "dark" while
# `tools/register_p1_synthesis.ts` serves it. Every root is scanned; a missing one leaves R23 unmeasured.
CAPS_ROOTS = (CAPS_ROOT, "platform-mcp/src/tools", "platform-mcp/src/lib")
DENS_OUTSIDE_ROOTS = ("platform/src", "platform-mcp/src")
# `retrieval/registry/knowledge/` holds read-only availability PROBES that mirror a handler's own source query (already read in
# CAPS_ROOTS) and the catalogue metadata naming every asset; it serves no rows, so it is not a served surface.
DENS_OUTSIDE_EXCLUDE = re.compile(r"\.test\.tsx?$|\.d\.ts$|__tests__|/generated/|node_modules|/retrieval/registry/knowledge/")
_SQL_STOP = re.compile(r"\b(?:ORDER\s+BY|GROUP\s+BY|LIMIT|OFFSET|UNION|RETURNING|FROM|WINDOW|HAVING)\b|;", re.I)
_ALIAS_STOP = {"where", "join", "left", "right", "inner", "outer", "full", "cross", "on", "order", "group", "limit",
               "offset", "union", "as", "using", "natural", "lateral", "window", "having", "returning", "for"}


def _ts_literals(src: str) -> list[str]:
    """R23: the CONTENTS of a TypeScript module's string and template literals, in order — comments skipped
    (the same scanner discipline as `_ts_code`, R51: `//` inside a string is not a comment)."""
    out, i, n = [], 0, len(src)
    while i < n:
        c, nx = src[i], src[i + 1] if i + 1 < n else ""
        if c == "/" and nx == "/":
            j = src.find("\n", i)
            i = n if j < 0 else j
        elif c == "/" and nx == "*":
            j = src.find("*/", i + 2)
            i = n if j < 0 else j + 2
        elif c in "'\"`":
            j = i + 1
            while j < n and src[j] != c:
                j += 2 if src[j] == "\\" else 1
            out.append(src[i + 1:min(j, n)])
            i = j + 1
        else:
            i += 1
    return out


_CAPS_LITERALS: dict[tuple, list[str]] = {}


def capability_sql(caps_root: str | None = None) -> dict[str, list[str]]:
    """R23: serving module -> its SQL-bearing literals (a FROM or JOIN in them). With no `caps_root`, every
    serving root in `CAPS_ROOTS` (C3): registry-layer modules keyed by their path under the registry root
    (unchanged), every other root's modules keyed `<root>/<path>`. With `caps_root`, that one root, keyed by
    the path under it. A missing directory raises `Unknown`: "no capability reads it" is never inferred from a
    scan that did not run (R222 / N3's rule, at field grain)."""
    if caps_root is None:
        out: dict[str, list[str]] = {}
        for i, root in enumerate(CAPS_ROOTS):
            out.update(capability_sql(root) if i == 0 else
                       {f"{root}/{k}": v for k, v in capability_sql(root).items()})
        return out
    d = ROOT / caps_root
    if not d.is_dir():
        raise Unknown(f"no capability directory at {caps_root}")
    out: dict[str, list[str]] = {}
    for f in sorted(d.rglob("*.ts")):
        if f.name.endswith(".test.ts") or "__tests__" in f.parts:
            continue
        st = f.stat()
        key = (str(f), st.st_mtime_ns, st.st_size)          # re-read only a module that changed
        if key not in _CAPS_LITERALS:
            # C3: SELECT-only literals are kept too — `\`SELECT a, b \` + \`FROM t \`` puts the select list in
            # the literal BEFORE the FROM, and `field_reach` reads it from there; dropping it here made the
            # concatenated form read as zero columns / no query at all.
            _CAPS_LITERALS[key] = [x for x in _ts_literals(f.read_text(encoding="utf-8", errors="replace"))
                                   if re.search(r"\b(?:FROM|JOIN|SELECT)\b", x, re.I)]
        lits = _CAPS_LITERALS[key]
        if lits:
            out[str(f.relative_to(d))] = lits
    return out


def _split_top(s: str) -> list[str]:
    parts, depth, cur = [], 0, []
    for ch in s:
        depth += ch == "("
        depth -= ch == ")"
        if ch == "," and depth == 0:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
    return parts + ["".join(cur)]


def _selected_columns(sel: str, cols: list[str], alias: str | None, table: str) -> set[str]:
    """The table's columns a SELECT list reads: `*` / `<alias>.*` -> every column; `<alias>.col` or a bare
    `col` (also inside an expression, `coalesce(col, …)`, `jsonb_build_object('k', col)`) -> that column;
    `<other_alias>.col` -> not this table's. String literal contents never count."""
    lower = {c.lower() for c in cols}
    mine = {x for x in (alias, table) if x}
    got: set[str] = set()
    sel = re.sub(r"'[^']*'", "''", sel)
    for item in _split_top(sel):
        it = item.strip()
        if it == "*" or re.fullmatch(r"(?:DISTINCT\s+)?\*", it, re.I) or \
                any(re.fullmatch(rf"{re.escape(m)}\.\*", it, re.I) for m in mine):
            return set(lower)
        for q, name in re.findall(r"(?:\b([A-Za-z_][A-Za-z_0-9]*)\s*\.\s*)?\b([A-Za-z_][A-Za-z_0-9]*)\b", it):
            if name.lower() in lower and (not q or q.lower() in {m.lower() for m in mine}):
                got.add(name.lower())
    return got


def _literal_pins(where: str, cols: list[str]) -> dict[str, set[str]] | None:
    """Row-level: the literal equality / IN pins a query's predicate puts on the table's own columns
    (`fact_category = 'dasha'`, `varga IN ('D9','D10')`). Parameters (`= $2`) pin nothing — the caller may
    ask for any value. An OR anywhere makes the predicate unanalysable here: None (read as unpinned, so
    depth stays an UPPER bound, never an invented narrowing)."""
    if re.search(r"\bOR\b", where, re.I):
        return None
    lower = {c.lower() for c in cols}
    pins: dict[str, set[str]] = {}
    for c, v in re.findall(r"(?:\b\w+\.)?\b(\w+)\s*=\s*'([^']*)'", where):
        if c.lower() in lower:
            pins.setdefault(c.lower(), set()).add(v)
    for c, vs in re.findall(r"(?:\b\w+\.)?\b(\w+)\s+IN\s*\(\s*('[^)]*')\s*\)", where, re.I):
        if c.lower() in lower:
            pins.setdefault(c.lower(), set()).update(re.findall(r"'([^']*)'", vs))
    return pins


def field_reach(table: str, cols: list[str], sql_by_module: dict[str, list[str]]) -> dict:
    """R23: which of `table`'s columns any capability module's SQL selects (width), and whether its
    queries pin rows by literal values (depth). Static and syntactic: see `_selected_columns` /
    `_literal_pins`; SQL a capability reaches through an imported helper is not followed. A FROM counts
    only with a SELECT in front of it (prose that says "from <table>" is not a query); a `${…}` select
    list is recorded in `dynamic_select` (its columns are unknown — width becomes a lower bound)."""
    exposed: set[str] = set()
    modules, pinned, unpinned, dynamic = [], [], False, []
    for mod, lits in sql_by_module.items():
        hit = False
        for i, m, alias, sel in _served_selects(table, lits):
            lit = lits[i]
            hit = True
            if "${" in sel:                               # `SELECT ${cols}`: the list is built at run time
                dynamic.append(mod)
            exposed |= _selected_columns(sel, cols, alias, table)
            # a keyword read as the alias (`FROM t WHERE …`) belongs to the tail, not the alias
            tail = lit[m.end() if alias or not m.group(1) else m.start(1):]
            w = re.search(r"\bWHERE\b", tail, re.I)
            where = ""
            if w:
                where = tail[w.end():]
                stop = _SQL_STOP.search(where)
                where = where[:stop.start()] if stop else where
            p = _literal_pins(where, cols)
            if p:
                pinned.append(p)
            else:
                unpinned = True
        if hit:
            modules.append(mod)
    return dict(modules=modules, exposed=exposed, pinned=pinned, unpinned=unpinned,
                dynamic_select=sorted(set(dynamic)))


def _pin_predicate(pins: list[dict[str, set[str]]]) -> str:
    def lit(v):
        return "'" + v.replace("'", "''") + "'"
    return " OR ".join("(" + " AND ".join(f"{c}::text IN ({', '.join(lit(v) for v in sorted(vs))})"
                                          for c, vs in sorted(p.items())) + ")" for p in pins)


def _grade_reach(tbl: str, cols: list[str], dc: dict, caps: dict | None, caps_note: str | None,
                 chart_id: str) -> tuple[dict, dict | None]:
    """R23: `Reach.fields` for an asset's target table — REPORTED, NOT GRADED (verdict stays NOT_GENERIC:
    a static SQL parse is a proxy for exposure, and a grading threshold is a decision above the census).
    Width = built columns some capability selects / built columns, where "built" is the depth census's
    populated columns (every column when depth did not measure rows — said so). Depth = the fraction of the
    table's rows (the bound chart's, when it has chart_id) some capability query can return: 1.0 when any
    query reads it with no literal row pin (an upper bound), else the rows matching the union of the pins,
    counted read-only; 0.0 when no capability reads the table at all."""
    if caps is None:
        return dict(v=NOT_GENERIC, measured=f"field reachability unmeasured: {caps_note}"), None
    fr = field_reach(tbl, cols, caps)
    never = set(c.lower() for c in dc.get("never", [])) if dc.get("rows") else set()
    built = [c.lower() for c in cols if c.lower() not in never]
    basis_b = "populated columns (depth census)" if dc.get("rows") else "all columns (depth census measured no rows)"
    exp = sorted(set(built) & fr["exposed"])
    dark = sorted(set(built) - fr["exposed"])
    width = (len(exp) / len(built)) if built else None
    if not fr["modules"]:
        depth, dbasis = 0.0, "no capability module reads this table"
    elif fr["unpinned"]:
        depth, dbasis = 1.0, "a capability query reads it with no literal row pin (upper bound)"
    else:
        scoped = " WHERE chart_id = '" + chart_id + "'" if "chart_id" in [c.lower() for c in cols] else ""
        try:
            hitn, total = psql(f"SELECT (count(*) FILTER (WHERE {_pin_predicate(fr['pinned'])}))::text, count(*)::text "
                               f"FROM {tbl}{scoped}")[0]
            depth = (int(hitn) / int(total)) if int(total) else None
            dbasis = (f"{hitn}/{total} rows{' of chart ' + chart_id[:8] if scoped else ''} match the capability "
                      f"queries' literal pins {_pin_predicate(fr['pinned'])[:160]}")
        except Unknown as exc:
            depth, dbasis = None, f"unmeasured: the pin count errored ({exc})"
    reach = dict(table=tbl, modules=fr["modules"], columns_built=len(built), built_basis=basis_b,
                 exposed=exp, dark=dark, width=(round(width, 4) if width is not None else None),
                 width_is_lower_bound=bool(fr["dynamic_select"]), dynamic_select=fr["dynamic_select"],
                 depth=(round(depth, 4) if depth is not None else None), depth_basis=dbasis)
    wtxt = (("≥ " if fr["dynamic_select"] else "") + f"{len(exp)}/{len(built)} built column(s) ({width:.1%})"
            + (f", a lower bound: {', '.join(fr['dynamic_select'])} select(s) a run-time column list"
               if fr["dynamic_select"] else "")) if width is not None else "no built column"
    dtxt = f"{depth:.1%}" if depth is not None else "unmeasured"
    return dict(v=NOT_GENERIC, measured=(f"reported, not graded — width {wtxt} selected by {len(fr['modules'])} "
                                         f"capability module(s); dark: {dark[:12]}{' …' if len(dark) > 12 else ''}; "
                                         f"depth {dtxt} ({dbasis})")), reach


def local_map_candidates(prefix: str) -> int:
    """Rule 6 candidates: literal graha-name sets in the layer's own python package."""
    pkg = ROOT / "platform" / "python-sidecar" / "brahmagyan"
    if not pkg.is_dir():
        return -1
    n = 0
    for f in pkg.rglob("*.py"):
        txt = f.read_text(encoding="utf-8", errors="replace")
        if re.search(r"['\"]Sun['\"]\s*[,:]", txt) and re.search(r"['\"]Venus['\"]", txt):
            n += 1
    return n


# ─────────────────────────── database reads ───────────────────────────

def registry(layer_key: str) -> tuple[dict[str, dict], dict]:
    """Read via json_agg, NOT line-oriented output.

    `count_sql` and `integrity_check_sql` contain newlines, so a row-per-line read splits one asset
    across several lines and invents assets whose ids are fragments of SQL. That bug produced 52 assets
    from 40 on this script's first run — the same defect class the layer template warns about, an
    instrument whose population was never stated. One JSON document has no such ambiguity.

    R220: `asset_registry` for this prefix has more rows than the ACTIVE population the census
    should measure — 129 total vs 127 active registry-wide (2 retired L3 rows, measured 2026-09-27).
    `is_active AND NOT dead_flag` is the register's own phrasing, but `dead_flag` is NULL (not
    false) on every row today, and `NOT NULL` is NULL in SQL — so that exact expression silently
    matches ZERO rows, not 127. The honest form is `is_active AND NOT coalesce(dead_flag, false)`.
    Excluded (inactive) rows are named here, not silently dropped — `measure()` states the
    population figure in its own output rather than letting 129 and 127 quietly disagree.

    R224 (A_REVIEW2 G5): the population is scoped by `asset_registry.layer`, NOT by the asset-id
    prefix. The prefix is a naming convention, not the registry's own statement of which layer an
    asset belongs to: `lel_events` (layer='mimamsa', no `mi_` prefix) was silently outside every
    layer's census — 126 measured where the tracker counts 127. `layer` is what the registry
    declares; the prefix still names the layer's writers and capability modules, nothing more."""
    cfg = LAYERS[layer_key]
    scope = f"layer = '{cfg['registry_layer']}'"
    total = int(scalar(f"SELECT count(*)::text FROM asset_registry WHERE {scope}") or 0)
    excluded = [dict(asset_id=r[0], is_active=(r[1] == "t"), catalog_status=r[2])
                for r in psql("SELECT asset_id, is_active::text, coalesce(catalog_status,'') "
                              f"FROM asset_registry WHERE {scope} "
                              "AND NOT (is_active AND NOT coalesce(dead_flag,false)) ORDER BY asset_id")]
    blob = scalar(
        "SELECT coalesce(json_agg(json_build_object("
        "'asset_id',asset_id,'has_writer',coalesce(has_writer,false),'target_table',target_table,"
        "'count_sql',coalesce(count_sql,''),'has_integrity',(integrity_check_sql IS NOT NULL),"
        "'integrity_sql',integrity_check_sql,"
        "'depends_on',coalesce(to_json(depends_on),'[]'::json),'target_floor',target_floor,"
        "'catalog_status',coalesce(catalog_status,''),'asset_kind',coalesce(asset_kind,''))"
        " ORDER BY asset_id)::text,'[]') "
        f"FROM asset_registry WHERE {scope} "
        "AND is_active AND NOT coalesce(dead_flag,false)")
    rows = json.loads(blob or "[]")
    out = {}
    for r in rows:
        out[r["asset_id"]] = dict(
            asset_id=r["asset_id"], has_writer=bool(r["has_writer"]),
            target_table=r["target_table"] or None, count_sql=r["count_sql"] or "",
            has_integrity=bool(r["has_integrity"]), depends_on=list(r["depends_on"] or []),
            # N-99: the declared SQL text itself (None = no integrity_check_sql declared; '' = declared but blank), read once with the rest of the row
            integrity_sql=(r["integrity_sql"] if r.get("integrity_sql") is not None and r["has_integrity"] else None),
            target_floor=(str(r["target_floor"]) if r["target_floor"] is not None else None),
            catalog_status=r["catalog_status"], asset_kind=r["asset_kind"])
    if not out:
        # F7 (A_REVIEW.md): before R220 this raised on zero rows; R220 narrowed it to zero REGISTRY
        # rows, so a population filter that matched nothing (the `NOT dead_flag` NULL trap, M9)
        # measured zero assets and exited 0 — a clean-looking census of nothing. An empty active
        # population is never a clean result: it is UNKNOWN (exit 4), with both figures stated.
        raise Unknown(f"zero active {cfg['prefix']}* rows (layer='{cfg['registry_layer']}') in asset_registry "
                      f"({total} registry row(s) for this layer) — an empty population is not a clean census; "
                      "check the population filter")
    population = dict(registry_total=total, active=len(out), excluded_inactive=excluded)
    return out, population


def live_counts(reg: dict, chart_id: str | None = None,
                view_counts: dict[str, str] | None = None) -> tuple[dict[str, int | None], dict[str, str]]:
    """Each asset's OWN count_sql — the cockpit instrument, not a table count.

    F2 (A_REVIEW.md, Lane A gate REJECT): a `count_sql` that RAISES (statement timeout, missing
    relation) must be distinguishable from an asset that simply HAS no `count_sql` at all — both
    used to collapse to `out[aid] = None`, and `measure()` then wrote `Build.completion = N/A "no
    count_sql"` for a query that in fact errored. N/A is CLOSABLE; a live demonstration
    (bg_ephemeris) closed the gap on a query that never returned a clean answer. Returns
    `(counts, errored)`: `errored[aid]` is set only when that asset's own `count_sql` was
    non-empty and its query raised `Unknown` — never for a genuinely absent `count_sql`.

    R231: a chart-scoped `count_sql` (`$1`) is bound to `chart_id` (default `CHART_ID`, the
    canonical chart) before it runs; one that cannot be bound is recorded in `errored` with the
    reason, never run and never read as absent."""
    chart_id = CHART_ID if chart_id is None else chart_id
    out: dict[str, int | None] = {}
    errored: dict[str, str] = {}
    parts, ids, bound = [], [], {}
    for aid, r in reg.items():
        q = " ".join(re.sub(r"--[^\n]*", "", r["count_sql"]).replace("\n", " ").rstrip(" ;").split())
        if view_counts and aid in view_counts:
            q = view_counts[aid]       # R46: the census's own count of the view (see _view_count_sql)
        if not q:
            out[aid] = None
            if r["count_sql"].strip():                     # R222: comments only is not "no count_sql"
                errored[aid] = "count_sql is empty once its comments are stripped — nothing to run"
            continue
        try:
            q = _bind_chart(q, chart_id)
        except Unknown as exc:
            out[aid] = None
            errored[aid] = str(exc)
            continue
        bound[aid] = q
        parts.append(f"SELECT '{aid}' a,({q})::text n")
        ids.append(aid)
    if not parts:
        return out, errored
    def _take(aid: str, v: str | None) -> None:
        # R222 / N1 (A_REVIEW2 G2): a count_sql that RAN but returned NULL or a non-integer used to
        # map to `None` with no error recorded — indistinguishable from an asset with no count_sql,
        # so measure() read the closable N/A "no count_sql" (false text; one live ledger-copy run
        # closed bg_ontology's gap on `SELECT NULL::bigint`). It is recorded as errored, with what
        # the query actually returned.
        if v is not None and v.strip().lstrip("-").isdigit():
            out[aid] = int(v)
        else:
            out[aid] = None
            errored[aid] = (f"count_sql returned {'NULL' if not (v or '').strip() else repr(v)}, "
                            "not an integer count")

    try:
        for a, n in psql(" UNION ALL ".join(parts)):
            _take(a, n)
    except Unknown:
        for aid in ids:                                    # one bad count_sql must not blind the rest
            q = bound[aid]
            try:
                _take(aid, scalar(f"SELECT ({q})::text"))
            except Unknown as exc:
                out[aid] = None
                errored[aid] = str(exc)
    return out, errored


def _asset_scope(prefix: str, ids=None, col: str = "asset_id") -> str:
    """R224: the per-layer reads select the MEASURED population (`ids`, from `registry()`, scoped by
    `asset_registry.layer`), not the id prefix — so an active asset outside the prefix convention
    (`lel_events`) gets its build record and history read like any other. `ids=None` keeps the
    prefix form for callers that have no population in hand."""
    if ids is None:
        return f"{col} LIKE '{prefix}%'"
    lit = ", ".join("'" + str(i).replace("'", "''") + "'" for i in ids)
    return f"{col} IN ({lit})" if lit else "FALSE"


def throughput(prefix: str, ids=None, with_duration: bool = False) -> dict[str, dict[str, dict]]:
    """asset_id -> {chart_id ('' for a global row) -> build record}.

    R231: `asset_throughput` holds one row per (chart_id, asset_id). The pre-R231 read keyed a dict
    by asset_id alone, so whichever chart's row came last silently became "the" build record — a
    count bound to one chart compared against another chart's rows_written. Rows are now kept per
    chart and `_build_record()` picks the one matching the count's own scope.

    R44 (handverify L1/L2/L4/L5): the record must be the LATEST row for its (asset, chart), chosen on
    a stated key — never "whichever row the unordered read returned last". The read had no ORDER BY
    and a second row for the same key silently overwrote the first. Uniqueness per (chart, asset) is
    today enforced only by two partial unique indexes (`asset_throughput_per_chart_idx`,
    `asset_throughput_global_idx`) that this script never checks, so the selection is made here,
    independent of row order: the greatest (last_built_at, last_measured_at), NULLs lowest. Two rows
    that tie on that key are not silently resolved — the record is marked `ambiguous` and
    Build.completion reads ERRORED (the latest cannot be determined; nothing opens or closes)."""
    rows = psql("SELECT asset_id, coalesce(state,''), coalesce(rows_written::text,''), "
                "coalesce(round(rows_per_second)::text,''), coalesce(last_built_at::date::text,''), "
                "coalesce(chart_id::text,''), "
                "coalesce(extract(epoch FROM last_built_at)::text,''), "
                "coalesce(extract(epoch FROM last_measured_at)::text,''), "
                # D6 item 2: the duration column is named ONLY when the instrument (migration 1094)
                # was feature-detected present — never a query that fails on its absence.
                + ("coalesce(duration_seconds::text,'') " if with_duration else "'' ")
                + f"FROM asset_throughput WHERE {_asset_scope(prefix, ids)} "
                "ORDER BY asset_id, chart_id, last_built_at DESC NULLS LAST, last_measured_at DESC NULLS LAST")
    out: dict[str, dict[str, dict]] = {}
    for r in ((x + [""] * 9)[:9] for x in rows):
        rec = dict(state=r[1], rows_written=r[2], rps=r[3], last_built=r[4], n_rows=1, ambiguous=False,
                   _key=(_epoch(r[6]), _epoch(r[7])), built_epoch=r[6],
                   duration=(float(r[8]) if r[8].strip() else None))
        cur = out.setdefault(r[0], {}).get(r[5])
        if cur is None:
            out[r[0]][r[5]] = rec
            continue
        n = cur["n_rows"] + 1
        if rec["_key"] > cur["_key"]:
            rec.update(n_rows=n, ambiguous=False)
            out[r[0]][r[5]] = rec
        else:
            cur["n_rows"] = n
            if rec["_key"] == cur["_key"]:
                cur["ambiguous"] = True
    return out


def _epoch(v: str) -> float:
    """An `extract(epoch …)` text as a sort key; NULL (empty) sorts lowest."""
    try:
        return float(v)
    except (TypeError, ValueError):
        return float("-inf")


def _build_record(rows_by_chart: dict, chart_scoped: bool, chart_id: str) -> tuple[dict, str]:
    """R231: the build record that matches the live count's scope, and a label naming it.
    Chart-scoped count -> that chart's row; global count -> the global (chart_id NULL) row, else the
    bound chart's row (a global table built per chart), said so in the label."""
    short = chart_id[:8]
    if chart_scoped:
        return rows_by_chart.get(chart_id, {}), f"chart {short}"
    if "" in rows_by_chart:
        return rows_by_chart[""], "global"
    return rows_by_chart.get(chart_id, {}), f"chart {short} (global count_sql; no global build row)"


def catalog(tables: list[str]) -> dict:
    """One round trip each for existence, columns and declared keys — not one per asset.

    The first run made roughly 240 psql invocations for 40 assets and took minutes; each pays process
    start plus connection. Three batched reads replace them."""
    t = [x for x in {x for x in tables if x}]
    if not t:
        return dict(exists=set(), cols={}, keys={})
    lit = ", ".join("'" + x.replace("'", "''") + "'" for x in t)
    exists = {r[0] for r in psql(f"SELECT table_name FROM information_schema.tables "
                                 f"WHERE table_schema='public' AND table_name IN ({lit})")}
    cols: dict[str, list[str]] = {}
    for tn, cn in psql("SELECT table_name, column_name FROM information_schema.columns "
                       f"WHERE table_schema='public' AND table_name IN ({lit}) "
                       "ORDER BY table_name, ordinal_position"):
        cols.setdefault(tn, []).append(cn)
    keys: dict[str, list[list[str]]] = {}
    for tn, defn in psql("SELECT c.relname, pg_get_constraintdef(x.oid) FROM pg_constraint x "
                         "JOIN pg_class c ON c.oid=x.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace "
                         f"WHERE n.nspname='public' AND x.contype IN ('u','p') AND c.relname IN ({lit})"):
        m = re.search(r"\((.*?)\)", defn)
        if m:
            keys.setdefault(tn, []).append([c.strip().strip('"') for c in m.group(1).split(",")])
    # R46: which targets are VIEWS (or materialized views) — a view is counted by the view itself.
    views = {r[0] for r in psql("SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace "
                                f"WHERE n.nspname='public' AND c.relkind IN ('v','m') AND c.relname IN ({lit})")}
    # E6 packet (c): column data types and non-NULL defaults (Narr.agree / Null.schema_default). `cols` is unchanged;
    # a failed read leaves them None (unknown), it never aborts the layer.
    types: dict | None = {}
    defaults: dict | None = {}
    types_error: str | None = None
    try:
        for row in psql("SELECT table_name, column_name, data_type, coalesce(replace(column_default, E'\\n', ' '), '') "
                        f"FROM information_schema.columns WHERE table_schema='public' AND table_name IN ({lit}) "
                        "ORDER BY table_name, ordinal_position"):
            if len(row) != 4:      # E1.8: a malformed row is a failed read with its reason, never a crashing unpack
                raise ReadError(f"columns/types/defaults read: a row has {len(row)} field(s), expected 4: {row[:3]!r}")
            tn, cn, dt_, dflt = row
            types.setdefault(tn, {})[cn] = dt_
            if dflt:
                defaults.setdefault(tn, {})[cn] = dflt
    except Unknown as exc:
        types = defaults = None
        types_error = str(exc)
    # N-150 R1: the element type of the ARRAY columns (udt_name: _text / _uuid / _int8 ...), so an array of ids is not read as text; and the type name of a USER-DEFINED column (an embedding `vector` is not an enum of labels). A failed read leaves it None (unknown: an array stays text-capable).
    udts: dict | None = {}
    try:
        for row in psql("SELECT table_name, column_name, udt_name FROM information_schema.columns "
                        f"WHERE table_schema='public' AND table_name IN ({lit}) AND data_type IN ('ARRAY', 'USER-DEFINED')"):
            if len(row) == 3:
                udts.setdefault(row[0], {})[row[1]] = row[2]
    except Unknown:
        udts = None
    return dict(exists=exists | views, cols=cols, keys=keys, views=views, types=types, defaults=defaults,
                types_error=types_error, udts=udts)


def _tally_attempt(per: dict, aid: str, scope: str, state: str, disp: str, when: str, err: str, started: str) -> None:
    """Fold ONE build_run_assets attempt into `per[aid]` (the build_history() per-asset tally). Extracted unchanged from
    build_history()'s loop so the Build.history WINDOW (`_grade_build_history_windowed`) tallies the attempts it keeps with
    EXACTLY the arithmetic the whole-history read uses; rows must arrive in ascending (created_at, run_id) order."""
    d = per.setdefault(aid, dict(runs=0, error=0, aborted=0, complete=0, queued=0, skipped=0,
                                 blocked=0, scopes=set(), last_state="", last_when="",
                                 last_disposition="", sample_error="", sample_blocked="",
                                 executed=0, executed_scopes=set(), last_executed_when="",
                                 states={}))
    d["runs"] += 1
    d[state] = d.get(state, 0) + 1
    d["states"][state] = d["states"].get(state, 0) + 1
    if started in ("t", "true"):
        d["executed"] += 1
        d["executed_scopes"].add(scope)
        d["last_executed_when"] = when
    if disp == "skip_no_delta":
        d["skipped"] += 1
    # Packet B1: 'blocked_dependency' (migration 1095) marks a row whose writer never
    # ran because an upstream dependency failed/was blocked in the SAME run — a
    # cascade CONSEQUENCE, not its own root cause. Tracked separately from the plain
    # `error` tally so grading below can count "one cause, N blocked" instead of
    # grading a chart FAIL/PARTIAL purely from downstream cascade noise
    # (B1_before_20260926T173931Z.json §4 — asset_census was the worst offender:
    # it already read `disposition` for skip_no_delta but never checked this value).
    if state == "error" and disp == "blocked_dependency":
        d["blocked"] += 1
        if err and not d["sample_blocked"]:
            d["sample_blocked"] = err
    d["scopes"].add(scope)
    d["last_state"], d["last_when"], d["last_disposition"] = state, when, disp
    if state == "error" and disp != "blocked_dependency" and err:
        # R49 (L3 handverify ka_avadhi, ka_kshetra): the quoted error is the LATEST one, dated —
        # the read is in ascending attempt order, so each later error replaces the earlier. It
        # used to keep the FIRST error ever recorded ("not d['sample_error']"), so a FAIL reading
        # "most recent run error" quoted a months-old error the asset had long since moved past.
        d["sample_error"], d["sample_error_when"] = err, when


def build_history(prefix: str, ids=None) -> dict:
    """What the orchestrator ACTUALLY did, from build_runs / build_run_assets.

    The static checks say an asset *should* be dispatchable. Only this says whether it ever was, and what
    happened. Native context (2026-09-26): a global build skips L0 and walks L1->L5, so an L0 asset is
    only ever exercised by a layer- or asset-scope run — measured here rather than assumed.

    C1 (W2-1_REVIEW §2 A8): a `build_run_assets` ROW is not an EXECUTION. The engine inserts every
    planned asset as `queued` and sets `started_at` only where an attempt is started in state
    'building': `asset_runner.py:1403` (the orchestrator's 'building' transition) and
    `run_heavy_writer_standalone.py:137` (the standalone heavy-writer runner, same meaning). "Executed"
    below therefore means STARTED — dispatched past the building flip — which includes skip_no_delta,
    probe-green and pre-writer-error attempts, not only writer runs. Rows that never reach it keep
    `started_at` NULL whatever their final state: `queued` leftovers in finished runs, `aborted` rows
    the runner's preflight/guardian terminalised straight from `queued` (runner.py
    `_terminalize_preflight_failure`), and `error` rows written by `_mark_asset_blocked` ("BLOCKED: …
    The asset is NOT executed"). Measured 2026-09-27: queued 1 465 (0 started), aborted 649 (8
    started), error 1 515 (319 started), complete 3 133 (3 133 started). So the executed set is
    `started_at IS NOT NULL`, not a list of states — a state list ({complete, error, aborted}) would
    count 1 837 never-started rows as runs. `executed` counts those rows; `runs` stays the raw row
    count and is reported beside it.

    R233 (F-C4, W2-1 C4): `error` is free text and Python tracebacks carry newlines. `psql()` splits
    its output on newlines, so a raw `left(a.error,200)` split ONE row into several: the row's
    started flag landed on a fragment line (executed undercounted — ph_sodhana 39 against 41 started)
    and traceback fragments became phantom per-asset keys. The error text is flattened in SQL before
    it reaches the line-oriented read: newline, carriage return and the field separator (chr(31))
    become spaces, THEN it is truncated — so one attempt is always exactly one line."""
    per: dict[str, dict] = {}
    rows = psql("SELECT a.asset_id, r.scope, a.state, coalesce(a.disposition,''), "
                "coalesce(r.created_at::date::text,''), "
                "coalesce(left(translate(a.error, E'\\n\\r' || chr(31), '   '),200),''), "
                "(a.started_at IS NOT NULL)::text "
                "FROM build_run_assets a JOIN build_runs r ON r.id=a.run_id "
                f"WHERE {_asset_scope(prefix, ids, 'a.asset_id')} "
                # R49: a TOTAL order — (asset_id, run_id) is build_run_assets' primary key, so rows of
                # runs created at the same instant (12 such pairs live, 2026-09-27) no longer come back
                # in an arbitrary order; "last" below is the latest attempt, deterministically.
                "ORDER BY a.asset_id, r.created_at, a.run_id")
    # R50 (L1 handverify: ga_dashas "108 run(s)" against 107 rows): every attempt must parse into
    # EXACTLY the seven selected fields. The read used to pad a short line (`(x + [""] * 7)[:7]`) and
    # count it as a run under whatever its first field held — so a split error fragment whose last
    # line was an asset id would add a phantom run to that REAL asset. R233 removed the known source
    # of split lines; a line of the wrong shape now fails the read (fail-closed), never counted.
    bad = [x for x in rows if len(x) != 7]
    if bad:
        raise Unknown(f"build_history: {len(bad)} line(s) did not parse into the 7 selected fields "
                      f"(first: {bad[0][:3]!r}) — the attempt tallies would be wrong; not counted")
    for aid, scope, state, disp, when, err, started in rows:
        _tally_attempt(per, aid, scope, state, disp, when, err, started)
    glob = int(scalar("SELECT count(*)::text FROM build_runs WHERE scope='global'") or 0)
    glob_l0 = int(scalar("SELECT count(*)::text FROM build_runs r JOIN build_run_assets a ON a.run_id=r.id "
                         f"WHERE r.scope='global' AND {_asset_scope(prefix, ids, 'a.asset_id')}") or 0)
    # R45: the chart-agnostic `lit` set (asset_ids lit on ANY chart) that Build.dep_liveness read is
    # gone — liveness is now read per dependency at the census's chart scope (`_grade_dep_liveness`).
    return dict(per=per, global_runs=glob, global_with_layer=glob_l0)


def _cascade_skip_note(rec_state: str, h: dict | None) -> str:
    """Suvarna Track I-3: when an asset's `asset_throughput` record reads 'error' only because the frozen
    runner's `_mark_asset_blocked` wrote a cascade skip there (it records `state='error'` for a consumer
    whose upstream did not complete), say so in Build.completion's measured text. The verdict is NOT
    changed here — a skipped consumer genuinely has no completed build record — only mis-attribution is
    removed: the test for "cascade" is the structural `disposition='blocked_dependency'` on the latest
    build_run_assets attempt (build_history's last_*), never the BLOCKED message text. Empty for a
    genuine error, a non-'error' record, or no history. Note: build_history is not chart-scoped, so this
    reads the latest attempt on any chart, said so in the note."""
    if rec_state != "error" or not h:
        return ""
    if h.get("last_state") == "error" and h.get("last_disposition") == "blocked_dependency":
        return ("; the throughput 'error' may be a cascade skip, not this asset's own failure: its latest recorded "
                f"build_run_assets attempt ({h.get('last_when') or 'undated'}, any chart) is blocked_dependency — an "
                "upstream did not complete, so the writer never ran on that attempt")
    return ""


# The disposition ERA floor (SS review, Earn.build_record R-c): before the engine wrote `disposition = 'build'`, completions carried NO disposition, so a no-disposition completion that has a provenance
# receipt may be a real writer build (receipts are persisted for writer builds too), never a probe. The era is therefore the LATER of (a) the first started 'build' attempt on record and
# (b) this commit: ef9ee729e (Nirmana O-wave WP-2, "pre-execution delta-skip gate (migration 641)", #1699), the FIRST commit in which asset_runner.py writes `SET state = 'complete',
# disposition = 'build'` (`git log --reverse -S"disposition = 'build'" -- asset_runner.py`, committed 2026-09-04T00:09:36Z). A commit date is a lower bound on the deploy, so the later of the two
# is used; if the commit cannot be dated in this checkout the era is UNKNOWN (None): no probe is derived, and a newer no-disposition row reads NO_DETECTOR, never a release.
DISPOSITION_ERA_COMMIT = "ef9ee729e749ada086c975aac501c78086f4f644"


def _disposition_era(era_data, reader) -> tuple[float | None, str]:
    """(era epoch | None, how it was anchored) = max(`era_data`, the date of DISPOSITION_ERA_COMMIT); None when either part is unavailable (fail closed). Never raises."""
    if era_data is None:
        return None, "no started 'build' attempt on record: the era is unknown"
    try:
        floor = reader.commit_epoch(DISPOSITION_ERA_COMMIT)
    except Exception as exc:                       # noqa: BLE001 -- a date is evidence, never a crash
        return None, f"the era floor commit {DISPOSITION_ERA_COMMIT[:9]} could not be dated ({type(exc).__name__}): the era is unknown"
    if floor is None:
        return None, f"the era floor commit {DISPOSITION_ERA_COMMIT[:9]} is not in this checkout: the era is unknown"
    return max(float(era_data), float(floor)), f"later of the first started 'build' attempt and commit {DISPOSITION_ERA_COMMIT[:9]} (the first to write disposition 'build')"


def latest_attempts(ids) -> tuple[dict[str, dict[str, dict]], float | None]:
    """D6 item 2 (R55, with R44/R45/R49): the latest STARTED build_run_assets attempt per
    (asset, run chart) — `{asset_id: {chart_id: attempt}}` — plus the start of the disposition era.

    Measurement identity is (asset, chart scope, latest attempt). "Attempt" means STARTED (C1: a
    `queued` leftover or an unstarted BLOCKED/aborted row never executed). Order is total and is the
    order the attempt STARTED: (a.started_at, r.created_at, run_id), each descending — a long-lived run
    created early whose asset attempt started after a newer run's attempt is the latest (N-178 review);
    run_id completes the primary key (R49). Each attempt carries `started_epoch` (the sort key's first
    term) and
    `ended_epoch` (the link to the build record, below), `created_epoch`, and `receipt`: whether an
    `asset_provenance_receipts` row names this run as its build_id — the probe-green evidence (the
    engine's `_mark_probe_green` writes `complete` with NO disposition and persists a receipt with
    build_id = run_id; it never writes a `probe_green` disposition, wave-1 F11).

    `era` is the epoch of the first attempt the engine marked `disposition='build'` (2026-09-04 live).
    From then on every writer completion records 'build'; BEFORE it, completions carried no
    disposition at all, so "complete + no disposition + a receipt" there may be a real writer build
    whose receipt survived (2 such latest attempts live, 2026-09-27) — never a probe-green."""
    if not ids:
        return {}, None
    lit = ", ".join("'" + str(i).replace("'", "''") + "'" for i in ids)
    rows = psql("SELECT DISTINCT ON (a.asset_id, r.chart_id) a.asset_id, r.chart_id::text, a.run_id::text, "
                "a.state, coalesce(a.disposition,''), coalesce(extract(epoch FROM a.ended_at)::text,''), "
                "extract(epoch FROM r.created_at)::text, r.created_at::date::text, "
                "(EXISTS (SELECT 1 FROM asset_provenance_receipts p WHERE p.build_id = a.run_id "
                "AND p.asset_id = a.asset_id))::text, "
                "coalesce(extract(epoch FROM a.started_at)::text,'') "
                "FROM build_run_assets a JOIN build_runs r ON r.id = a.run_id "
                f"WHERE a.started_at IS NOT NULL AND a.asset_id IN ({lit}) "
                # N-178 review LOW: the LATEST attempt is the one that STARTED last (a long-lived run created early whose asset attempt started after a newer run's must still win), then the run's
                # creation, then run_id: a TOTAL order, so a tie never leaves the winner to row order
                "ORDER BY a.asset_id, r.chart_id, a.started_at DESC, r.created_at DESC, a.run_id DESC")
    out: dict[str, dict[str, dict]] = {}
    for r in ((x + [""] * 10)[:10] for x in rows):
        out.setdefault(r[0], {})[r[1]] = dict(run_id=r[2], state=r[3], disposition=r[4], ended_epoch=r[5],
                                              created_epoch=_epoch(r[6]), when=r[7],
                                              receipt=(r[8] in ("t", "true")), started_epoch=_epoch(r[9]))
    # the first STARTED 'build' attempt (its own started_at, not its run's creation: a long-lived run created before the deploy would otherwise pull the era too early); measure() takes the
    # later of this and the engine-deploy floor `DISPOSITION_ERA_COMMIT` (see `_disposition_era`)
    era = scalar("SELECT extract(epoch FROM min(coalesce(a.started_at, r.created_at)))::text FROM build_run_assets a "
                 "JOIN build_runs r ON r.id = a.run_id WHERE a.disposition = 'build'")
    return out, (_epoch(era) if era else None)


def _grade_build_history(h: dict) -> dict:
    """Grade one asset's Build.history verdict from its build_history() per-asset dict `h`.

    Extracted as its own pure function (Packet B1) so this grading arithmetic is
    unit-testable directly against a hand-built `h`, without mocking psql/scalar for
    the whole measure() pipeline.

    Packet B1: a cascade-blocked row (disposition='blocked_dependency', migration 1095)
    is a CONSEQUENCE, never its own cause — it must not by itself grade a chart
    FAIL/PARTIAL. Before this fix, asset_census already read `disposition` (for
    skip_no_delta) but never checked this value at all — a chart whose every build
    blemish was downstream cascade from someone else's failure was graded exactly as
    if it had real defects of its own (B1_before_20260926T173931Z.json §4, the packet's
    most consequential surface: a governance signal, not just a UI cosmetic).

    `genuine_error` excludes blocked rows from the count this grading acts on;
    `last_run_was_blocked_only` excludes a purely-cascade most-recent-run from the
    "most recent run failed" FAIL trigger specifically. `h['blocked']` is still
    surfaced in every branch's `measured` text — never silently dropped (§N.6: count
    it, don't hide it; a chart with genuinely zero non-cascade defects grades PASS,
    not NA, so the blocked count doesn't vanish from the report).
    """
    genuine_error = h["error"] - h["blocked"]
    bad = genuine_error + h["aborted"]
    # R49: the quoted error is dated — it is the latest non-cascade error, not necessarily the last
    # run's (the last run may have completed, or ended with no error text).
    se = (f"latest error ({h['sample_error_when']}): {h['sample_error']}"
          if h.get("sample_error_when") and h.get("sample_error") else h.get("sample_error", ""))
    last_run_was_blocked_only = (
        h["last_state"] == "error" and h["last_disposition"] == "blocked_dependency"
    )
    if h["last_state"] in ("error", "aborted") and not last_run_was_blocked_only:
        return dict(v=FAIL, measured=f"most recent run {h['last_state']} ({h['last_when']}); {genuine_error} error(s), {h['aborted']} abort(s), {h['blocked']} blocked_dependency (cascade, not counted as failure). {se}")
    if bad:
        return dict(v=PARTIAL, measured=f"latest run complete, but {genuine_error} error(s) and {h['aborted']} abort(s) on record ({h['blocked']} additional blocked_dependency row(s) excluded as cascade-only). {se}")
    if h["blocked"]:
        # C-4 (review B1_review_20260926T182200Z.md, §N.8): PASS must require at
        # least one EARNED completion, not merely "zero genuine errors". Without
        # this guard, an asset that has NEVER once completed a build — every
        # attempt cascade-blocked, none of them its own fault — would grade PASS
        # from an all-cascade history alone: a green signal with no detector
        # behind the claim "this asset builds successfully" (the exact §N.8
        # defect class). Measured against live production at review time: 0 of
        # 124 assets currently hit this branch (6 FAIL->FAIL, 7 FAIL->PARTIAL, 89
        # PARTIAL->PARTIAL, 22 PASS->PASS, zero flips to PASS) — latent, not live,
        # but the path exists and would fire the moment a new asset is added
        # downstream of a chronically-failing root.
        if h["complete"] == 0:
            return dict(v=PARTIAL, measured=f"0 complete — this asset has NEVER once finished a build; {h['blocked']} blocked_dependency row(s) were all downstream cascade ({h['sample_blocked']}), not a defect of this asset, but a history with zero completions cannot grade PASS on the strength of 'no genuine error' alone; {h['skipped']} skip_no_delta")
        return dict(v=PASS, measured=f"{h['complete']} complete, no genuine error or abort; {h['blocked']} blocked_dependency row(s) were all downstream cascade from an upstream failure, not a defect of this asset ({h['sample_blocked']}); {h['skipped']} skip_no_delta (healthy)")
    if h["complete"] == 0:
        # C1 (W2-1_REVIEW §2 A3/A8): zero completions and zero errors/aborts means no attempt ever
        # reached an outcome (e.g. only `queued` rows left in finished runs). "No error" there is the
        # absence of a measurement, not a clean history — PASS would close a gap on nothing, and the
        # delegating N/A would too. NO_DETECTOR (non-closable, opens a gap) with the reason; the
        # missing execution itself is Build.exercised's FAIL.
        return dict(v=NO_DET, measured=f"NO_DETECTOR — 0 complete and no error or abort across {h['runs']} "
                                       f"build_run_assets row(s) (states: {h.get('states') or 'n/a'}): no "
                                       "attempt reached an outcome to grade")
    return dict(v=PASS, measured=f"{h['complete']} complete, no error or abort; {h['skipped']} skip_no_delta (healthy)")


# ───────────────────────── Build.history WINDOW (SS definition, binding; revision 2) ─────────────────────────
#
# Build.history judges the attempts SINCE the later of (i) the asset's last writer-digest change on main and (ii) its last registry-
# identity change, because an earlier error belongs to code or to a contract that no longer exists. What "last change" reads, and how it
# fails closed, is documented in build_window.py (git only, read-only). The count of older errors/aborts is REPORTED as "pre-window
# history", never hidden. An asset with NO attempt since that point reads NO_DETECTOR (nothing has exercised the current code), not PASS.
# A forced-unchanged rebuild is an attempt of the current code (the writer ran: disposition 'build'); a `skip_no_delta` row is not (the
# engine skipped the writer), and neither is a cascade-blocked row.

_PROBE_SOURCE_PATHS = ("platform/python-sidecar/pipeline/orchestrator/asset_runner.py",
                       "platform/python-sidecar/pipeline/orchestrator/service_probes.py")
_NON_EXERCISING_DISPOSITIONS = ("skip_no_delta", "blocked_dependency")


def build_attempt_log(prefix: str, ids=None) -> dict[str, list[dict]]:
    """Every build_run_assets attempt per asset, ascending (created_at, run_id), with the run's creation time as an epoch. The SAME rows
    and order as build_history() plus the epoch the window compares; a line that does not parse into the 8 selected fields, or a
    timestamp that is not a number, fails the read (fail-closed, as R50), never padded or guessed."""
    rows = psql("SELECT a.asset_id, r.scope, a.state, coalesce(a.disposition,''), "
                "coalesce(r.created_at::date::text,''), "
                "coalesce(left(translate(a.error, E'\\n\\r' || chr(31), '   '),200),''), "
                "(a.started_at IS NOT NULL)::text, coalesce(extract(epoch FROM r.created_at)::text,''), "
                # the probe-green evidence (the engine's `_mark_probe_green` writes `complete` with NO disposition and a receipt whose build_id is the run): see latest_attempts
                "(EXISTS (SELECT 1 FROM asset_provenance_receipts p WHERE p.build_id = a.run_id AND p.asset_id = a.asset_id))::text "
                "FROM build_run_assets a JOIN build_runs r ON r.id=a.run_id "
                f"WHERE {_asset_scope(prefix, ids, 'a.asset_id')} "
                "ORDER BY a.asset_id, r.created_at, a.run_id")
    bad = [x for x in rows if len(x) != 9]
    if bad:
        raise Unknown(f"build_attempt_log: {len(bad)} line(s) did not parse into the 9 selected fields (first: {bad[0][:3]!r}) — "
                      "the windowed attempt tallies would be wrong; not counted")
    out: dict[str, list[dict]] = {}
    for aid, scope, state, disp, when, err, started, ep, rcpt in rows:
        epoch = _epoch(ep)
        if epoch == float("-inf"):
            raise Unknown(f"build_attempt_log: {aid} has an attempt with no readable run creation time ({ep!r}) — it cannot be placed "
                          "against the window")
        out.setdefault(aid, []).append(dict(scope=scope, state=state, disposition=disp, when=when, error=err,
                                            started=(started in ("t", "true")), epoch=epoch, receipt=(rcpt in ("t", "true"))))
    return out


def _utc(epoch: float) -> str:
    return dt.datetime.fromtimestamp(epoch, dt.timezone.utc).strftime("%Y-%m-%d %H:%M:%SZ")


def _grade_build_history_windowed(aid: str, attempts: list[dict] | None, attempts_error: str | None, window: dict, h_all: dict) -> dict:
    """Build.history for one asset that HAS executed attempts, judged inside its window. Pure.

    `attempts`: that asset's build_attempt_log rows (None + `attempts_error` when the log could not be read); `window`:
    build_window.compute_window()'s answer; `h_all`: the whole-history tally (build_history()'s per-asset dict), used for the cross-check
    and to NAME the verdict the unwindowed reading would give, never to grade."""
    whole = _grade_build_history(h_all)["v"]
    if not window.get("ok"):
        return dict(v=NO_DET, measured=f"NO_DETECTOR — the Build.history window could not be determined: {window.get('reason', 'unknown')}; "
                                       f"the whole-history reading would be {whole} but it is not used (it judges attempts of code or a "
                                       "contract that may no longer exist, and a PASS cannot rest on it)")
    if attempts is None:
        return dict(v=NO_DET, measured=f"NO_DETECTOR — the attempt log could not be read ({attempts_error or 'unknown'}), so no attempt "
                                       f"can be placed against the window that opens {window['opens']}; whole-history reading would be {whole}")
    if len(attempts) != h_all["runs"]:
        return dict(v=NO_DET, measured=f"NO_DETECTOR — two reads of build_run_assets disagree ({len(attempts)} attempt row(s) in the timed log, "
                                       f"{h_all['runs']} in the history tally): the window cannot be applied to a history that moved between "
                                       "reads; run the census again")
    opens = window["epoch"]
    per: dict = {}
    pre = dict(n=0, error=0, aborted=0, complete=0, blocked=0)
    for a in attempts:
        if a["epoch"] > opens:
            _tally_attempt(per, aid, a["scope"], a["state"], a["disposition"], a["when"], a["error"], "t" if a["started"] else "f")
            continue
        pre["n"] += 1
        if a["state"] == "error" and a["disposition"] == "blocked_dependency":
            pre["blocked"] += 1
        elif a["state"] == "error":
            pre["error"] += 1
        elif a["state"] == "aborted":
            pre["aborted"] += 1
        elif a["state"] == "complete":
            pre["complete"] += 1
    pre_text = (f"pre-window history (before {_utc(opens)}: attempts of code or a contract that no longer exists, REPORTED and not judged): "
                + (f"{pre['n']} attempt(s), {pre['error']} error(s), {pre['aborted']} abort(s), {pre['complete']} complete, "
                   f"{pre['blocked']} blocked_dependency" if pre["n"] else "none"))
    head = f"window opens {_utc(opens)} ({window['basis']})"
    hw = per.get(aid)
    exercised = [a for a in attempts if a["epoch"] > opens and a["started"] and a["disposition"] not in _NON_EXERCISING_DISPOSITIONS]
    if not exercised:
        since = (f"{hw['runs']} attempt row(s) since (states: {hw['states']}), none of which executed the current code "
                 "(a skip_no_delta, cascade-blocked, queued or never-started row does not)" if hw else "no attempt since")
        return dict(v=NO_DET, measured=f"NO_DETECTOR — nothing has exercised the current code and contract: {since}; {head}; {pre_text}. "
                                       "A forced rebuild (which runs the writer) is what would close it")
    g = _grade_build_history(hw)
    if g["v"] == PASS and not any(a["state"] == "complete" for a in exercised):
        # review fix: PASS needs a REAL completed attempt since the window opened. `hw['complete']` also counts a skip_no_delta row (state complete,
        # not an exercise), and a started attempt may still be in flight (`building`): neither earns a PASS for the current code.
        return dict(v=NO_DET, measured=f"NO_DETECTOR — no exercising attempt completed since the window opened: {len(exercised)} started attempt(s) "
                                       f"of the current code (states: {sorted({a['state'] for a in exercised})}), none complete (in flight, or ended without "
                                       f"completing), and a skip_no_delta row is not an exercise; {head}; {pre_text}. {g['measured']}")
    return dict(v=g["v"], measured=f"{g['measured']} [judged inside the window only; {head}; {pre_text}]")


def _class_source_paths(cls: ast.ClassDef) -> list[str] | None:
    """A registered class's literal `source_paths = [...]` (the engine's `getattr(cls, 'source_paths')` for a class that sets it in its own
    body). None when the class does not set it; Unknown when it sets it to anything but a literal list/tuple of strings."""
    for node in cls.body:
        tgt, val = None, None
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "source_paths" for t in node.targets):
            val = node.value
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == "source_paths":
            val = node.value
        else:
            continue
        if isinstance(val, (ast.List, ast.Tuple)) and all(isinstance(e, ast.Constant) and isinstance(e.value, str) for e in val.elts):
            return [e.value for e in val.elts]
        raise Unknown(f"{cls.name}.source_paths is not a literal list of strings: the writer's source set cannot be read statically")
    return None


def _engine_local_module_path(module: str) -> Path | None:
    """asset_runner._local_module_path: an in-repo sidecar module, resolved without importing it."""
    if not module:
        return None
    rel = Path(*module.split("."))
    f, init = SIDECAR / rel.with_suffix(".py"), SIDECAR / rel / "__init__.py"
    return f if f.is_file() else init if init.is_file() else None


def _engine_local_imports(path: Path) -> list[Path]:
    """asset_runner._local_import_files / _module_name_for_path, reproduced (the engine module imports the database driver at load, so the
    census cannot import it; test_sb1 pins the two together over every registered writer): the direct local imports of one file, including
    each `from a.b import c` as the module `a.b.c` too."""
    try:
        rel = path.resolve().relative_to(SIDECAR.resolve())
    except ValueError:
        return []
    if rel.suffix != ".py":
        return []
    parts = list(rel.with_suffix("").parts)
    if parts[-1] == "__init__":
        parts.pop()
    module_name = ".".join(parts) or None
    if module_name is None:
        return []
    package = module_name if path.name == "__init__.py" else module_name.rpartition(".")[0]
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    except (OSError, SyntaxError, UnicodeDecodeError):
        return []
    imports: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imports.update(a.name for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                pp = package.split(".") if package else []
                base_parts = pp[:len(pp) - node.level + 1]
                if not base_parts:
                    continue
                base = ".".join(base_parts)
                target = f"{base}.{node.module}" if node.module else base
            else:
                target = node.module or ""
            if target:
                imports.add(target)
                imports.update(f"{target}.{a.name}" for a in node.names)
    return [p for m in sorted(imports) if (p := _engine_local_module_path(m)) is not None]


def _writer_code_paths(aid: str, files: list[str], has_writer: bool) -> list[str]:
    """The repo-relative files whose bytes the engine's writer digest (`asset_runner.get_writer_source_hash`) covers for `aid`: the registered
    class's declared `source_paths` (else its own module file), directories expanded to their non-test `*.py`, plus the transitive closure
    of their local imports. An asset with no writer is digested over the generic probe sources (`get_probe_source_hash`). [] when a
    writer-backed asset's registered file is not known; raises Unknown when the set cannot be read statically (never a guess)."""
    if not has_writer:
        return list(_PROBE_SOURCE_PATHS)
    roots: list[Path] = []
    for name in files:
        f = _writer_path(name)
        cls = _writer_class(f, aid) if f.is_file() else None
        declared = _class_source_paths(cls) if cls is not None else None
        for raw in (declared if declared else [str(f)]):
            p = Path(raw) if Path(raw).is_absolute() else ROOT / raw
            if p.is_file():
                roots.append(p)
            elif p.is_dir():
                roots += [x for x in sorted(p.rglob("*.py")) if x.is_file() and "tests" not in x.parts]
            else:
                raise Unknown(f"the writer source path {raw!r} for {aid} is not a file or directory in this checkout")
    if not roots:
        return []
    seen: set[Path] = set()
    pending = sorted(roots, key=lambda x: x.as_posix())
    done: list[Path] = []
    while pending:
        p = pending.pop(0).resolve()
        if p in seen:
            continue
        seen.add(p)
        done.append(p)
        pending.extend(_engine_local_imports(p))
    top = ROOT.resolve()
    out = []
    for p in sorted(done, key=lambda x: x.as_posix()):
        try:
            out.append(p.relative_to(top).as_posix())
        except ValueError:
            raise Unknown(f"the writer source file {p} of {aid} lies outside the repository") from None
    return out


class _WindowedHistory:
    """Per-measure() run: the git reader, the timed attempt log (read once, fault-isolated) and the per-asset window cell."""

    def __init__(self, prefix: str, ids, reader=None):
        self.prefix, self.ids = prefix, ids
        self._reader_arg = reader
        self._bw = None                                # loaded and built on the first asset that needs a window (a layer with none loads nothing)
        self.reader = None
        self._log: dict | None = None
        self._err: str | None = None
        self._read = False

    def _attempts(self) -> None:
        if not self._read:
            self._read = True
            try:
                self._log = build_attempt_log(self.prefix, self.ids)
            except Unknown as exc:
                self._err = str(exc)
            except Exception as exc:                   # noqa: BLE001 -- R41: an unreadable log degrades the cells that need it, never the layer
                self._err = f"{type(exc).__name__}: {' '.join(str(exc).split())[:120]}"

    def _reader_ready(self) -> None:
        if self._bw is None:
            self._bw = _lint_module("build_window")
            self.reader = self._reader_arg if self._reader_arg is not None else self._bw.WindowReader(ROOT, env=_git_env())

    def registry_epoch(self, aid: str) -> tuple[float | None, str | None]:
        """(epoch, basis text) of when the registry row's no-writer DEFINITION began (build_window.has_writer_commit: the commit that last SET has_writer for the row, else the earliest commit
        that created the row), or (None, why) when it cannot be dated (fail closed). Not the Build.history window's registry-identity date: an unrelated later touch of the row must not turn a
        contradicting attempt into a legacy one. Never raises."""
        self._reader_ready()
        try:
            got = self.reader.has_writer_commit(aid)
        except self._bw.WindowUnknown as exc:
            return None, str(exc)
        except Exception as exc:                       # noqa: BLE001 -- a date is evidence, never a crash
            return None, f"{type(exc).__name__}: {' '.join(str(exc).split())[:120]}"
        if got is None:
            return None, f"no migration statement or seed row on main sets or creates the registry row of {aid}, so its no-writer definition cannot be dated"
        if got[2] == "migration set has_writer = false":
            return float(got[0]), (f"the migration that set has_writer = false was added in {got[1][:9]} on main: that commit date is a PROXY for the migration ledger's applied_at "
                                   "(a production value this census does not read)")
        return float(got[0]), (f"no migration ever set has_writer = false: the row was created writer-less (earliest commit {got[1][:9]} on main, a PROXY for when it was applied), so "
                               "any later build attempt contradicts 'never had a writer'")

    def build_attempts(self, aid: str) -> tuple[list | None, str | None]:
        """EVERY started build_run_assets attempt of the asset (not only the latest per chart: a real build followed by a later probe row must stay visible), each dict(epoch, state,
        disposition, when, run_id=None), or (None, why) when the timed attempt log could not be read. Never raises."""
        self._attempts()
        if self._log is None:
            return None, f"the timed attempt log could not be read ({self._err or 'unknown'})"
        return [dict(a, created_epoch=a["epoch"]) for a in self._log.get(aid, []) if a.get("started")], None

    def cell(self, aid: str, h: dict, has_writer: bool, files: list[str]) -> dict:
        if self._bw is None:
            self._bw = _lint_module("build_window")
            self.reader = self._reader_arg if self._reader_arg is not None else self._bw.WindowReader(ROOT, env=_git_env())
        self._attempts()
        try:
            paths = _writer_code_paths(aid, files, has_writer)
            window = self._bw.compute_window(self.reader, aid, paths)
        except Unknown as exc:
            window = dict(ok=False, reason=str(exc))
        except Exception as exc:                       # noqa: BLE001  R41: one asset's check degrades to ERRORED, never aborts the layer
            return dict(v=ERRORED, measured=f"check errored: the Build.history window raised {type(exc).__name__}: {' '.join(str(exc).split())[:160]}")
        return _grade_build_history_windowed(aid, None if self._log is None else self._log.get(aid, []), self._err, window, h)


def duration_instrument_present() -> bool | None:
    """D6 item 1 (feature detection): does `asset_throughput.duration_seconds` exist yet
    (migration 1094)? Returns None (not False) when the check itself cannot run — that is
    "instrument unreachable", a distinct NO_DETECTOR reason from "instrument absent".

    F11 (A_REVIEW.md, tested against the engine at 8edba0533): schema-qualified exactly as the
    engine's own `_duration_columns_present` is (gate review R-7 there) — a same-named table in
    another schema must never make the instrument read as present in `public`."""
    try:
        return (scalar("SELECT (EXISTS(SELECT 1 FROM information_schema.columns "
                       "WHERE table_schema='public' AND table_name='asset_throughput' "
                       "AND column_name='duration_seconds'))::text")
               or "f") in ("t", "true")
    except Unknown:
        return None


def _grade_earn_cost(attempt: dict | None, instrument_present: bool | None, baseline: dict | None,
                      attempt_linkage_wired: bool = False) -> tuple[dict, dict]:
    """D6 (DECISIONS_RECOMMENDATIONS_v2_0.md D6, R55 re-specified): grade `Earn.build_record` and
    `Cost.baseline` — two SEPARATE measurements, neither certifying the whole Earn gate, Cost not
    one of the nine gates at all (tier 4 §1's build-cost baseline only).

    Extracted as a pure function (same discipline as `_grade_build_history`, Packet B1) so every
    branch is unit-testable against a hand-built `attempt`/`baseline`, without a live
    `asset_throughput.duration_seconds` column to test against — which does not exist in this
    environment (migration 1094 not applied, confirmed 2026-09-27 in both production and the
    nikasha_sandbox proof DB) or in production, so this function is EXERCISED here only through
    its own test suite.

    F1 (Lane A gate review, `nikasha_test/wave1/A_REVIEW.md`): `measure()` does NOT query
    `build_run_assets` for a real attempt today — that wiring is R42–R56, a separate lane this
    packet stops short of (§A-4). So `measure()` always calls this with `attempt=None` AND
    `attempt_linkage_wired=False`, regardless of whether the instrument (migration 1094) is
    present. This is deliberately NOT the same claim as "genuinely never attempted": the fixed
    call site's earlier docstring said this "will grade for real the moment migration 1094 lands,
    without any further code change" — that was false. Grading for real needs the attempt query
    (R42–R56) to land too; until then, an instrument-present-but-unwired run must read
    `NO_DETECTOR — attempt linkage not wired`, not the closable `N/A "never attempted"` a genuine
    no-attempt-row case would use — the latter would falsely CLOSE every `Earn.build_record` gap
    for every asset that was in fact built, the instant the column exists.

    R225 (A_REVIEW2 G1): `attempt_linkage_wired` DEFAULTS TO False — the safe value. With the old
    default (True) a call site that merely omitted the argument would read `attempt=None` as
    "confirmed never attempted" and grade the closable N/A the moment migration 1094 lands. Only a
    caller that has genuinely queried build_run_assets may pass True.

    `attempt` is the latest build_run_assets row for (asset, chart scope), or None if the asset
    has never been attempted (only a meaningful "None" when `attempt_linkage_wired` is True — see
    above). Expected keys: `state` ("complete"/"error"/"aborted"/"queued"),
    `disposition` ("skip_no_delta"/"probe_green"/"" ), `reached_completion_write` (bool — did
    execution get far enough that a duration WOULD have been recorded if the instrument were
    working), `duration_seconds` (float/None), `rows_written` (int/None), `is_legacy_telemetry`
    (bool — this attempt's writer is on the pre-1094 `_telemetry` path R34 left as a residual; the
    ONLY currently-known cause of a completion write with no duration. Unclassified so far:
    engine-side, migration-1094-dependent; no such marker exists in this environment either).
    `has_writer` — no registered writer at all (a legacy health-probe service) grades N/A, but under its own
    cause `no-registered-writer`: only a skip/probe DISPOSITION earns `healthy-non-execution`.

    `baseline`, when not None, is the most recent MEASURED completion on record for this asset at
    this scope: `{"rate": float, "attempt_id": str, "age_days": int}` — provenance, not just a number.
    """
    if instrument_present is None:
        reason = "instrument unreachable"
    elif not instrument_present:
        reason = "instrument absent (migration 1094)"
    else:
        reason = None

    if reason is not None:
        nd = dict(v=NO_DET, measured=f"NO_DETECTOR — {reason}, scoped to this run")
        return dict(nd), dict(nd)

    # From here, the instrument genuinely exists — grade Earn.build_record for the latest attempt.
    if attempt is None and not attempt_linkage_wired:
        # F1: the instrument exists but this call site never queried build_run_assets for an
        # attempt at all — `attempt=None` here means "unknown", never "confirmed absent". Reading
        # N/A would close a gap on a fact this run never actually measured.
        nd = dict(v=NO_DET, measured="NO_DETECTOR — attempt linkage not wired")
        return dict(nd), dict(nd)
    if attempt is None:
        earn = _na("never attempted — see Build.exercised", "never-attempted")
    elif attempt.get("disposition") in ("skip_no_delta", "probe_green"):
        # "healthy non-execution" is the DISPOSITION's claim (the engine skipped / probed green): only that
        # disposition earns the slug. A no-writer asset whose attempt failed is not "healthy".
        earn = _na(f"healthy non-execution ({attempt['disposition']}) — no build was due", "healthy-non-execution")
    elif not attempt.get("has_writer", True):
        earn = _na(f"no registered writer (attempt {attempt.get('state', '?')}) — no build record applies",
                   "no-registered-writer")
    elif not attempt.get("reached_completion_write", False):
        earn = _na(f"attempt {attempt.get('state','?')} before completion; see Build.history", "before-completion-write")
    elif attempt.get("duration_seconds") is not None:
        dur = attempt["duration_seconds"]
        rw = attempt.get("rows_written") or 0
        rate = (rw / dur) if dur else 0.0
        earn = dict(v=PASS, measured=f"completion write with duration={dur}s, rows_written={rw}, rate={rate} "
                                     "(a measured rate of 0.0 is a real measurement, not suppressed)")
    elif attempt.get("is_legacy_telemetry"):
        earn = dict(v=FAIL, measured="completion write reached with no duration — the legacy _telemetry "
                                     "path (R34's residual)")
    else:
        earn = dict(v=NO_DET, measured="NO_DETECTOR — unclassified NULL (completion write with no duration "
                                       "and no identified cause)")

    # Cost.baseline: independent of the latest attempt's own outcome — a healthy skip/failure
    # neither erases a prior sanctioned baseline nor creates one.
    if baseline is not None:
        cost = dict(v=PASS, measured=f"sanctioned baseline: rate={baseline['rate']} "
                                     f"(attempt {baseline['attempt_id']}, {baseline['age_days']}d old)")
    else:
        cost = dict(v=FAIL, measured="no sanctioned baseline build on record")
    return earn, cost


LATEST_ATTEMPT_FAIL_STATES = ("error", "aborted")


def _attempt_order_key(a: dict):
    """The total order that picks the latest attempt across run charts (the in-Python twin of the SQL ORDER BY of `latest_attempts`): the epoch the attempt STARTED (the run's creation when the row carries no
    start), then the run's creation, then run_id. A long-lived run created early whose attempt started after a newer run's attempt is therefore the latest."""
    se = a.get("started_epoch")
    return (se if isinstance(se, (int, float)) and se != float("-inf") else a["created_epoch"], a["created_epoch"], a["run_id"])


def latest_attempt_at_scope(by_chart: dict | None, rec_scope: str, chart_id: str):
    """(attempt | None, where): the latest STARTED build_run_assets attempt at the scope of the build record `rec_scope` names (`_attempt_timing`'s own rule: a global build record is written by a run on ANY chart,
    so its attempt is the latest across run charts; any other record is the bound chart's, so its attempt is that chart's latest). `by_chart` is `latest_attempts()` for the asset; None = the read failed."""
    atts = by_chart or {}
    if rec_scope.split(";")[0] == "global":
        return (max(atts.values(), key=_attempt_order_key) if atts else None), "any chart (global build record)"
    return atts.get(chart_id), f"chart {chart_id[:8]}"


def completion_latest_attempt(rec: dict, by_chart: dict | None, rec_scope: str, chart_id: str) -> dict:
    """N-178: Build.completion reads the LATEST started attempt of the asset at the measured scope and FAILs when that attempt ERRORED or ABORTED, whatever the registry state ('lit' left behind by an
    earlier completion) and the row counts say: a build record and a count describe what an earlier attempt left, the latest attempt says whether the asset's build is complete NOW. Measurement side only (no runner
    change). A latest attempt that is complete (a build, a skip_no_delta, a probe-green row) or a cascade-blocked `blocked_dependency` row (the writer never ran) leaves the reading exactly as it was; no attempt at
    all, or an attempt read that failed, leaves it exactly as it was. An N/A stays N/A (nothing to build). NO AGE WINDOW (chosen): unlike Build.history (which judges attempts of the CURRENT code), this asks
    whether the asset is built right now, and a failed latest attempt stays the asset's state until a NEWER attempt completes, however old it is or whatever changed in the code since. The attempt's date is in
    the text. Pure."""
    if not isinstance(rec, dict) or rec.get("v") == NA or by_chart is None:
        return rec
    att, where = latest_attempt_at_scope(by_chart, rec_scope, chart_id)
    if att is None or att.get("state") not in LATEST_ATTEMPT_FAIL_STATES or att.get("disposition") == "blocked_dependency":
        return rec
    prior = f"{rec.get('v')}: {rec.get('measured')}"
    return dict(rec, v=FAIL,
                measured=(f"the latest started build attempt at {where} ended {att['state']} (run {att['run_id'][:8]}, {att['when'] or 'undated'}, "
                          f"disposition {att.get('disposition') or 'none'}): the asset's most recent attempt did not complete, so its build is not complete whatever its registry state and row counts say "
                          f"(N-178; no age window: a failed latest attempt stands until a newer attempt completes). Reading without this rule: {prior}"),
                latest_attempt=dict(checked=True, state=att["state"], disposition=att.get("disposition") or "", run_id=att["run_id"], when=att["when"], scope=where, prior_verdict=rec.get("v")))


def _attempt_timing(by_chart: dict | None, rec: dict, rec_scope: str, chart_id: str,
                    instrument_present: bool | None, has_writer: bool, era: float | None,
                    today: dt.date | None = None) -> tuple[dict, dict]:
    """D6 item 2 — the attempt adapter: Earn.build_record / Cost.baseline attributed to the latest
    STARTED attempt at the build record's scope, then graded by the unchanged D6 classifier
    (`_grade_earn_cost`, attempt linkage genuinely wired).

    `by_chart` is `latest_attempts()` for this asset (None when the attempt read itself failed).
    Scope: a global build record (chart_id NULL) is written by a run on ANY chart, so its attempt is
    the latest across run charts; any other record is the bound chart's, so its attempt is that
    chart's latest. The link between an attempt and the build record's duration is the engine's own:
    the completion write sets `asset_throughput.last_built_at = NOW()` and `build_run_assets.ended_at
    = NOW()` with `disposition='build'` in ONE transaction, so the two are equal — true for all 64
    latest 'build' attempts live (2026-09-27). A duration counts for an attempt only if the attempt
    is 'build' AND that equality holds (skip, probe-green, error and start all refresh
    `last_built_at` without touching the duration — D6 finding 3).

    Nothing here can PASS or N/A while the instrument is absent: `_grade_earn_cost` grades
    NO_DETECTOR first. The linked attempt's identity is appended to that NO_DETECTOR as evidence."""
    atts = by_chart or {}
    if rec_scope == "global":
        att = max(atts.values(), key=_attempt_order_key) if atts else None
        where = "any chart (global build record)"
    else:
        att, where = atts.get(chart_id), f"chart {chart_id[:8]}"
    ident = (f"latest attempt at {where}: run {att['run_id'][:8]} {att['state']}/"
             f"{att['disposition'] or 'no disposition'} ({att['when']})" if att else f"no started attempt at {where}")
    if by_chart is None:
        ident = "the attempt read failed"

    if instrument_present is not True:
        earn, cost = _grade_earn_cost(attempt=None, instrument_present=instrument_present, baseline=None,
                                      attempt_linkage_wired=True)
        return (dict(earn, measured=f"{earn['measured']}; {ident}"),
                dict(cost, measured=f"{cost['measured']}; {ident}"))
    if by_chart is None:
        nd = dict(v=NO_DET, measured="NO_DETECTOR — the build_run_assets attempt read failed; no attempt to link")
        return dict(nd), dict(nd)
    if att is None:
        if atts:
            nd = dict(v=NO_DET, measured=f"NO_DETECTOR — {ident} ({len(atts)} run chart(s) with attempts elsewhere): "
                                         "nothing to time for this scope")
            return dict(nd), dict(nd)
        return _grade_earn_cost(attempt=None, instrument_present=True, baseline=None, attempt_linkage_wired=True)

    disp, state = att["disposition"], att["state"]
    linked = (state == "complete" and disp == "build" and bool(att["ended_epoch"])
              and att["ended_epoch"] == rec.get("built_epoch"))

    def _nd(why: str) -> tuple[dict, dict]:
        nd = dict(v=NO_DET, measured=f"NO_DETECTOR — {ident}: {why}")
        return dict(nd), dict(nd)

    if state == "complete":
        if disp == "build" and not linked:
            return _nd("a completion write, but the build record's last_built_at is not this attempt's completion "
                       "(a later write touched it); its duration cannot be attributed")
        if not disp:
            if not (att["receipt"] and era is not None and att["created_epoch"] >= era):
                return _nd("complete with no disposition and not derivable as probe-green ("
                           + ("no probe receipt names this run" if not att["receipt"] else
                              "it predates the disposition era, so a surviving receipt may be a writer build's")
                           + ") — unclassified")
            disp = "probe_green"                            # derived: complete + no disposition + receipt
        elif disp not in ("build", "skip_no_delta"):
            return _nd(f"complete with an unrecognised disposition '{disp}' — unclassified")
    elif state in ("error", "aborted"):
        if disp in ("build", "skip_no_delta", "probe_green"):
            return _nd(f"state '{state}' with disposition '{disp}' is inconsistent — unclassified")
    else:
        return _nd(f"attempt in state '{state}', no outcome to grade")

    dur = rec.get("duration") if linked else None
    rw = int(rec["rows_written"]) if str(rec.get("rows_written", "")).strip().lstrip("-").isdigit() else 0
    attempt = dict(state=state, disposition=disp, reached_completion_write=(disp == "build"),
                   duration_seconds=dur, rows_written=rw, is_legacy_telemetry=False, has_writer=has_writer)
    baseline = None
    if linked and dur is not None:
        age = ((today or dt.date.today()) - dt.date.fromisoformat(att["when"])).days if att["when"] else 0
        baseline = dict(rate=(rw / dur) if dur else 0.0, attempt_id=att["run_id"][:8], age_days=age)
    earn, cost = _grade_earn_cost(attempt=attempt, instrument_present=True, baseline=baseline,
                                  attempt_linkage_wired=True)
    if baseline is None and rec.get("duration") is not None:
        # D6 item 4: a healthy skip neither erases a prior baseline nor creates one — but a duration
        # this adapter cannot attribute to a completion attempt has no provenance, so it is not a
        # "sanctioned" baseline either, and "none on record" would be false. Unmeasured, said so.
        cost = dict(v=NO_DET, measured=f"NO_DETECTOR — a duration is on record ({rec['duration']}s) but is not "
                                       f"attributable to a completion attempt ({ident})")
    return (dict(earn, measured=f"{earn['measured']}; {ident}"), dict(cost, measured=f"{cost['measured']}; {ident}"))


def declared_keys(table: str) -> list[list[str]]:
    rows = psql("SELECT pg_get_constraintdef(oid) FROM pg_constraint "
                f"WHERE conrelid='{table}'::regclass AND contype IN ('u','p')")
    keys = []
    for (d,) in ((r[0],) for r in rows):
        m = re.search(r"\((.*?)\)", d)
        if m:
            keys.append([c.strip().strip('"') for c in m.group(1).split(",")])
    return keys


def table_exists(t: str) -> bool:
    return (scalar(f"SELECT (to_regclass('public.{t}') IS NOT NULL)::text") or "f") in ("t", "true")


def identity_duplicates(tbl: str, kd: str):
    """(has_dup, figure): the Vocab.identity duplicate probe of the declared key `kd` over `tbl` THROUGH THE READ SCOPE (the measured chart's rows). R40: `count(*) - count(DISTINCT (cols))` requires a full
    sort / hash of every row and does not scale to the estate's largest table (kala_field, 10.3M rows: duplicates = 0 in 47s against the naive form's >180s), so an EXISTS / HAVING probe stops at the first
    duplicate group. F9: the figure ("N duplicate(s) in G duplicate group(s)": rows beyond the first per key) is counted ONLY when the probe found a duplicate, so the clean case keeps R40's cost; a count that
    errors keeps the probe's FAIL and says the figure is missing. Raises Unknown on a failed probe."""
    has_dup = (scalar(f"SELECT EXISTS(SELECT 1 FROM {tbl}{_where_scope(tbl)} GROUP BY {kd} HAVING count(*) > 1)::text") or "f") in ("t", "true")
    if not has_dup:
        return False, "0 duplicate(s)"
    try:
        dup_groups, dup_rows = psql("SELECT count(*)::text, coalesce(sum(n - 1), 0)::text FROM "
                                    f"(SELECT count(*) AS n FROM {tbl}{_where_scope(tbl)} GROUP BY {kd} HAVING count(*) > 1) d")[0]
        return True, f"{dup_rows} duplicate(s) in {dup_groups} duplicate group(s)"
    except Unknown as exc:
        return True, f"duplicate group(s) exist; the count errored ({exc})"


def identity_has_rows(tbl: str) -> bool:
    """One EXISTS probe: does `tbl` hold a row in the read scope (the measured chart's)? A 0-duplicate reading over no rows is vacuous."""
    return (scalar(f"SELECT EXISTS(SELECT 1 FROM {tbl}{_where_scope(tbl)})::text") or "f") in ("t", "true")


def depth_census(table: str, cols: list[str]) -> dict:
    if not cols:
        return dict(columns=0, note="no columns")
    total = int(scalar(f"SELECT count(*)::text FROM {table}{_where_scope(table)}") or 0)
    if total == 0:
        return dict(columns=len(cols), rows=0, full=[], never=[], note="table empty")
    sel = ", ".join(f"count({c})::text" for c in cols)
    vals = psql(f"SELECT {sel} FROM {table}{_where_scope(table)}")[0]
    full = [c for c, v in zip(cols, vals) if int(v) == total]
    never = [c for c, v in zip(cols, vals) if int(v) == 0]
    return dict(columns=len(cols), rows=total, full=full, never=never, note="")


def alias_census(table: str, cols: list[str]) -> dict | None:
    names = set(cols)
    if ALIAS_COLUMN not in names:
        return None
    grp = "entity_class" if "entity_class" in names else "'(all)'"
    rows = psql(f"SELECT {grp}::text, count(*)::text, "
                f"count(*) FILTER (WHERE {ALIAS_COLUMN} IS NULL OR cardinality({ALIAS_COLUMN})=0)::text "
                f"FROM {table}{_where_scope(table)} GROUP BY 1 ORDER BY 1")
    return {r[0]: dict(rows=int(r[1]), no_alias=int(r[2])) for r in rows}


def _no_writer_block(declared: bool, has_writer: bool, files, aid: str | None = None) -> dict:
    """The facts an N-150 R5 release rests on, as measured: the declaration, the registry row, the @register scan (over EVERY layer prefix, see `measure`) and (review fix LOW-2) the modules that
    mention the asset id inside any `register(` call the class-decorator scan cannot see (`register_call_mentions`)."""
    return dict(declared=bool(declared), registry_has_writer=bool(has_writer), register_files=len(files),
                register_mentions=(register_call_mentions(aid) if aid else ["(asset id not supplied)"]))


def attempt_kind(a: dict, era=None) -> str:
    """`probe` | `build` | `unclassified` for one started build_run_assets attempt (pure). The engine never writes the string `probe_green`: its probe-green rows are state `complete` with NO
    disposition and a provenance RECEIPT whose build_id is the run (`_mark_probe_green`; see `latest_attempts`), and only from the disposition `era` onward is that derivation safe (BEFORE it,
    completions carried no disposition, so a surviving receipt may be a real writer build's).
      probe        disposition probe_green / skip_no_delta (a skip is not a run), or state complete + empty disposition + a receipt + created at or after `era`;
      build        disposition `build` (the engine marks every writer completion so from the era on);
      unclassified anything else (complete with no disposition and no usable receipt/era, an error or abort with no disposition, an unrecognised disposition): it may be a probe or a build, so it is never
                   read as a contradiction and never ruled away."""
    disp = a.get("disposition") or ""
    if disp in ("probe_green", "skip_no_delta"):
        return "probe"
    if disp == "build":
        return "build"
    ep = a.get("created_epoch") if a.get("created_epoch") is not None else a.get("epoch")
    if (a.get("state") == "complete" and not disp and a.get("receipt") is True and era is not None
            and isinstance(ep, (int, float)) and ep != float("-inf") and ep >= era):
        return "probe"
    return "unclassified"


def no_writer_attempt_split(by_chart, registry_epoch, era=None):
    """SS 2026-10-05 R-c, pure: the attempts of a declared no-writer asset that could contradict it, split by the no-writer reference instant (`registry_epoch`). A PROBE (`attempt_kind`) never
    contradicts has_writer: false and is dropped. For the rest: `legacy` = created at or before the instant (do NOT contradict), `newer` = a BUILD created after it (contradicts), `undated` = no
    readable creation time or no instant (cannot be placed), `unclassified` = created after it but neither a probe nor a certain build (cannot be read as a contradiction: NO_DETECTOR)."""
    legacy, newer, undated, unclassified = [], [], [], []
    rows = list(by_chart.values()) if isinstance(by_chart, dict) else list(by_chart or [])
    for a in rows:
        if not isinstance(a, dict):
            continue
        kind = attempt_kind(a, era)
        if kind == "probe":
            continue
        ep = a.get("created_epoch") if a.get("created_epoch") is not None else a.get("epoch")
        if registry_epoch is None or not isinstance(ep, (int, float)) or ep == float("-inf"):
            undated.append(a)
        elif ep > registry_epoch:
            (newer if kind == "build" else unclassified).append(a)
        else:
            legacy.append(a)
    return dict(legacy=legacy, newer=newer, undated=undated, unclassified=unclassified)


def _attempt_ids(rows) -> str:
    return ", ".join(f"{a.get('run_id', '?')[:8]} {a.get('state')}/{a.get('disposition') or 'no disposition'} ({a.get('when') or 'undated'})" for a in rows[:3])


def earn_build_record_no_writer(earn: dict, attempts, block: dict, registry_epoch=None, registry_why=None, attempts_why=None, era=None) -> dict:
    """SS 2026-10-05 (build_record no-writer/static, with R-c), applied to the record `_attempt_timing` produced for an asset whose registry row says has_writer false (pure).
    The release is keyed on the asset's own declaration and CHECKED: `block` (`_no_writer_block`) must read declared true, registry has_writer false, no @register class and no `register(` call
    naming the asset (the same facts as N-150 R5); and the engine's own record must not contradict it. `attempts` is EVERY started build_run_assets attempt of the asset (a list of dicts with
    `created_epoch`; a dict of them is accepted), None when the attempt log could not be read (`attempts_why`: NO_DETECTOR, neither a release nor a contradiction). R-c: a build attempt (not
    probe_green / skip_no_delta) OLDER than the registry row's no-writer definition (`registry_epoch`, `WindowReader.has_writer_commit`) predates the declaration and does not contradict it; a
    NEWER one does (FAIL), whatever probe or skip rows follow it; when the definition date cannot be read a build attempt cannot be placed and the cell reads NO_DETECTOR naming why.
    Without the agreeing block the record is returned unchanged. An asset WITH a writer never reaches this function."""
    agree = bool(block.get("declared")) and block.get("registry_has_writer") is False and block.get("register_files") == 0 and block.get("register_mentions") == []
    if not agree:
        return earn
    if attempts is None and attempts_why:
        return dict(v=NO_DET, no_writer=dict(block), measured=f"NO_DETECTOR — declared has_writer: false (registry and @register scan agree) but its build_run_assets attempts could not be read ({attempts_why}): "
                                                               "neither a release nor a contradiction")
    sp = no_writer_attempt_split(attempts, registry_epoch, era)
    if sp["newer"]:
        return dict(v=FAIL, no_writer=dict(block, attempts=len(sp["newer"])),
                    measured=f"declared has_writer: false (registry and @register scan agree) but the orchestrator has {len(sp['newer'])} build_run_assets attempt(s) NEWER than the registry row's "
                             f"no-writer definition ({_attempt_ids(sp['newer'])}); evidence: {registry_why or 'the definition date was supplied by the caller'}: the declaration is contradicted by the engine's own record")
    if sp["undated"]:
        return dict(v=NO_DET, no_writer=dict(block, attempts=len(sp["undated"])),
                    measured=f"NO_DETECTOR — declared has_writer: false (registry and @register scan agree) and {len(sp['undated'])} build_run_assets attempt(s) ({_attempt_ids(sp['undated'])}) cannot be "
                             f"placed against the registry row's no-writer definition ({registry_why or 'an attempt has no readable creation time'}): neither a release nor a contradiction")
    if sp["unclassified"]:
        return dict(v=NO_DET, no_writer=dict(block, attempts=len(sp["unclassified"])),
                    measured=f"NO_DETECTOR — declared has_writer: false (registry and @register scan agree) and {len(sp['unclassified'])} build_run_assets attempt(s) newer than the no-writer reference "
                             f"({_attempt_ids(sp['unclassified'])}) are neither a probe (complete, no disposition, a receipt, from the disposition era on) nor a build (disposition 'build'): they may be "
                             f"probes, so they are neither a contradiction nor a release; evidence: {registry_why or 'the reference was supplied by the caller'}")
    legacy = (f"; {len(sp['legacy'])} legacy attempt(s) ({_attempt_ids(sp['legacy'])}) are OLDER than the registry row's no-writer definition ({registry_why or 'dated'}) and do not contradict it (SS R-c)" if sp["legacy"] else "")
    return dict(_na("no writer (declared has_writer: false; the registry row and the @register scan agree): no build record applies" + legacy, "no-writer-registry-agrees"), no_writer=dict(block, **(dict(legacy_attempts=len(sp["legacy"])) if sp["legacy"] else {})))


def idem_update_only_facts(asset_id: str, files: list[str], targets=()) -> dict:
    """What the writer scope the Idem scan reads does to the asset's OWN tables, for an `update_only` declaration (SS 2026-10-05; pure, offline): `updates` (the cited UPDATE statements),
    the counts of own-table `insert`, `upsert`, `replace` (DELETE / TRUNCATE / CREATE OR REPLACE VIEW) and unnamed `dynamic` writes, `beyond` (delegation chains cut at the hop limit) and the
    `accumulating` assignments `_update_only_reading` finds. Raises Unknown like `_delegation_scope`."""
    units, beyond = _delegation_scope(asset_id, files)
    facts = _write_facts(units)
    tset = {t.lower() for t in targets if t}
    own = {k: [x for x in facts[k] if x[0] in tset] for k in ("replace", "upsert", "insert", "update")}
    acc = list(_update_only_reading(units, tset)["accumulating"]) if own["update"] else []
    return dict(updates=[f"{t} ({rel}:{ln}{f' via {via}' if via else ''})" for t, rel, ln, via in own["update"]], insert=len(own["insert"]), upsert=len(own["upsert"]),
                replace=len(own["replace"]), dynamic=len(facts["dynamic"]), beyond=len(beyond), accumulating=acc)


def update_only_scan_problem(block) -> str | None:
    """None when `block` (`idem_update_only_facts`) shows ONLY UPDATE statements on the own tables (at least one) and nothing that contradicts a declared update-only writer; else why not."""
    if not isinstance(block, dict) or not isinstance(block.get("updates"), list) or not block["updates"]:
        return "the writer scope holds no UPDATE statement on the asset's own table(s)"
    bad = [f"{k} {block.get(k)}" for k in ("insert", "upsert", "replace", "dynamic", "beyond") if block.get(k) != 0]
    if bad:
        return "the writer scope also holds " + ", ".join(bad) + " (an INSERT, an upsert, a DELETE / TRUNCATE of the own table, a dynamic statement the scan cannot name, or a delegation chain it did not follow)"
    if block.get("accumulating"):
        return "an accumulating assignment: " + "; ".join(block["accumulating"])
    return None


def update_only_na_problem(crit: str, meas) -> str | None:
    """None unless an Idem.pattern N/A of cause update-only-by-intent is NOT backed by the agreeing scan (SS 2026-10-05): the record must carry the `update_only` block declared true and
    read by `update_only_scan_problem` as clean. Pure; read by `_check_contribution` and `_na_released`."""
    if crit != "Idem.pattern" or not isinstance(meas, dict) or meas.get("v") != NA or meas.get("cause") != "update-only-by-intent":
        return None
    b = meas.get("update_only")
    if not (isinstance(b, dict) and b.get("declared") is True and update_only_scan_problem(b) is None):
        return ("Idem.pattern N/A rests on a declared update_only that the writer scan AGREES with (SS 2026-10-05): this record does not carry a clean scan block "
                "(UPDATE statements on the own tables and no INSERT / upsert / DELETE / cut chain / accumulating assignment), so the declaration alone is not a release")
    return None


def _no_writer_scanned(aid: str, has_writer: bool, check: str, declared: bool = False) -> dict:
    """R222 / N2 (A_REVIEW2 G2): no writer file was recognised for this asset. That is a genuine
    N/A only when the registry agrees there is no writer. With `has_writer=true` the writer exists
    but its `@register` was not recognised (e.g. `@register(ASSET_ID)`, R43), so the scan never ran:
    NO_DETECTOR, never the closable N/A (one live ledger-copy run closed bg_reference-Idem.pattern
    on exactly this; live today on L3/L4/L5, where 13 writer-backed assets are unrecognised)."""
    if not has_writer:
        return dict(_na("no writer, and the registry agrees (has_writer=false) — nothing to scan" + ("; declared has_writer: false (N-150 R5)" if declared else "; NOT declared has_writer: false, so no release (N-150 R5)"),
                        "no-writer-registry-agrees"), no_writer=_no_writer_block(declared, has_writer, (), aid))
    return dict(v=NO_DET, measured=f"NO_DETECTOR — registry says has_writer=true but no @register('{aid}') "
                                   f"was recognised in writers/; {check} was never scanned (see Build.registered)")


def _measure_contract(aid: str, files: list[str], has_writer: bool, declared_no_writer: bool = False) -> dict:
    """R41 fault isolation for Build.contract, extracted as its own pure-ish function (F3,
    A_REVIEW.md: the inline try/except could only be proven by grepping measure()'s source text,
    which survives a mutation that makes the guard re-raise instead of catching. Extracting it
    lets a test call it directly with `contract_scan` monkeypatched to raise, and assert the
    RETURN VALUE is ERRORED — a mutation that removes or breaks the try/except now fails that
    assertion instead of surviving on source text alone)."""
    if not files:
        return _no_writer_scanned(aid, has_writer, "the contract", declared_no_writer)
    try:
        v, notes = contract_scan(aid, files)
        return dict(v=v, measured="; ".join(notes) or "conformant")
    except Unknown as exc:
        return dict(v=ERRORED, measured=f"check errored: {exc}")


def _measure_idem(aid: str, files: list[str], convention: str, has_writer: bool, targets=(), declared_no_writer: bool = False, update_only=None) -> dict:
    """R41 fault isolation for Idem.pattern — same discipline as `_measure_contract`. `targets`
    (C-KSHETRA): the asset's own tables — target_table ∪ count_sql tables — a counted DELETE must name."""
    if not files:
        return _no_writer_scanned(aid, has_writer, "the idempotency pattern", declared_no_writer)
    try:
        v, notes = idem_scan(aid, files, convention, targets)
        if isinstance(update_only, dict) and v != FAIL:                      # SS 2026-10-05: a measured FAIL is never excused by the declaration
            facts = idem_update_only_facts(aid, files, targets)
            bad = update_only_scan_problem(facts)
            if bad is None:
                return dict(_na(f"update-only by declared intent (reviewed, evidence: {update_only.get('evidence')}): {update_only.get('why')}; the writer scan agrees: "
                                f"UPDATE only, {'; '.join(facts['updates'])}, no INSERT, upsert or DELETE of the own table(s)", "update-only-by-intent"),
                            update_only=dict(facts, declared=True))
            return dict(v=NO_DET, update_only=dict(facts, declared=True), declaration_disagreements=[bad],
                        measured=f"NO_DETECTOR — update_only is declared but {bad}: the declaration is contradicted by the writer scan (the scan read: {'; '.join(notes)[:200]})")
        return dict(v=v, measured="; ".join(notes))
    except Unknown as exc:
        return dict(v=ERRORED, measured=f"check errored: {exc}")


def target_owners() -> dict[str, list[str]]:
    """R53: table -> the active assets (registry-wide, every layer) that declare it as target_table."""
    out: dict[str, list[str]] = {}
    for t, aid in psql("SELECT target_table, asset_id FROM asset_registry WHERE target_table IS NOT NULL "
                       "AND is_active AND NOT coalesce(dead_flag,false) ORDER BY 1, 2"):
        out.setdefault(t, []).append(aid)
    return out


def dependency_graph() -> dict[str, list[str]]:
    """R21: every ACTIVE asset's declared `depends_on`, registry-wide (all six layers), in one read —
    the blocking radius crosses layers (an L0 table blocks L1–L5 builders)."""
    blob = scalar("SELECT coalesce(json_object_agg(asset_id, coalesce(to_json(depends_on), '[]'::json))::text, '{}') "
                  "FROM asset_registry WHERE is_active AND NOT coalesce(dead_flag,false)")
    return {k: [str(d) for d in (v or [])] for k, v in json.loads(blob or "{}").items()}


def blocking_radius(graph: dict[str, list[str]]) -> dict[str, dict]:
    """R21 (triage BT05; register row R21). THE METRIC, per active asset A:

      transitive      the number of DISTINCT active assets (every layer) that depend on A through
                      `asset_registry.depends_on`, directly or through any chain — what a failing A can
                      block. Edges come only from active assets and point only at active assets (a
                      dependency on an inactive/unknown id is no edge); a cycle counts each member once
                      and never A itself.
      direct          those that declare A in their own `depends_on`.
      severity_weight 1 + transitive — the multiplier a Build gap carries: an isolated leaf weighs 1.

    A leaf and a root with the same Build verdict are the same defect with different costs; this is the
    figure that orders their repair."""
    rev: dict[str, set[str]] = {a: set() for a in graph}
    for a, deps in graph.items():
        for d in deps:
            if d in rev and d != a:
                rev[d].add(a)
    out = {}
    for a in graph:
        seen: set[str] = set()
        todo = list(rev[a])
        while todo:
            x = todo.pop()
            if x == a or x in seen:
                continue
            seen.add(x)
            todo.extend(rev[x])
        out[a] = dict(transitive=len(seen), direct=len(rev[a]), severity_weight=1 + len(seen))
    return out


# ─────────── E6 item (h): Build.dag reads-match (T4:275, check 4) ───────────
#
# T4:275: "the declared edges match what the asset actually reads". Until this block Build.dag tested RESOLVABILITY
# only (every depends_on id exists). This reads what the writer's code SELECTs — FROM / JOIN relations of every SQL
# string in the registered class's delegation scope — and compares it with the asset's DECLARED depends_on edges.
#
#   * A read of a table another asset PRODUCES (registry target_table or a table its count_sql names) with no DIRECT
#     depends_on edge to a producer is a FAIL that names the missing edge and the file:line that reads it. A shared
#     table (several producers) is covered by an edge to any one of them. An edge that is only transitively present
#     (ordering still holds through the intermediate asset) is named in the FAIL text, but it is still a missing edge:
#     T4:275 asks for the DECLARED edges to match.
#   * "Reads nothing undeclared" is a PASS only when the parse is demonstrably complete (`reads_scan()['incomplete']`
#     empty): every SQL string parsed, no table named dynamically, every execute() argument traced to a literal, no SQL
#     one hop past the scan limit. Otherwise NO_DETECTOR — never a PASS by the absence of a parse (CLAUDE.md N.8).
#   * Static SQL only. A read through a database view or function is not followed (a view over an asset's table is a
#     read of a relation no asset produces, so it is invisible to the ownership map); the PASS text says so.

# SS ruling 2026-10-01 (alignment with pipeline/orchestrator/dag_edge_guard.py, whose lists this module IMPORTS, never copies):
#   * L0 BEDROCK reads (table names with the guard's _UNGATED_PREFIXES bg_/reference_/brahma_/sutravali_/classical_, _UNGATED_EXACT
#     ephemeris_daily, _EXTERNAL_TABLES life_event*) need no declared edge: not a missing-edge FAIL, recorded as `bedrock_exempt`
#     in the record. THIS IS A PROVISIONAL INTERPRETATION OF T4 (check 4), to be confirmed at the J1 review.
#   * chart_facts (_SHARED_SOFT_TABLES, a polymorphic read whose producer cannot be named) is satisfied by ANY producer in the
#     asset's declared transitive closure (the guard's SOFT tier), recorded as `soft_satisfied`; no producer in the closure
#     keeps the FAIL.
#   * DEVIATION FROM THE GUARD (stricter, earned-signal-conservative, CLAUDE.md N.8): the guard exempts by table NAME alone. Here
#     a table is exempt only when it has a bedrock NAME AND every producer that owns it in the registry is an L0 asset (bg_*); a
#     bedrock-named table with any non-L0 owner (a brahma_* table owned by bo_x, a mixed bg_/bo_ owner set) is an ordinary read
#     needing an edge and its finding carries `bedrock_name_non_l0_owner`.
#   * `soft_satisfied` limit: satisfied by ANY chart_facts producer in the declared closure; fact_category is NOT matched
#     (record: fact_category_matched=False), so it does not prove the READ category is produced upstream.
#   * The guard counts only per_chart producers: global NON-prefixed L0 tables (vidhi_floor_items, vidhi_intent_floors,
#     vidhi_primitives) would FAIL here if a writer read them (they match no ungated prefix and no per_chart owner rule); none does today.
#   * Transitive invariant: for every other table the guard asks for a producer in the transitive closure; this check still
#     asks for a DIRECT edge (SS: transitive-only findings stay FAIL with `transitive_only`; Track I migration 1202 adds them).
# Recorded limits and review notes (E6 review of b24e580cc; counts at table level, 2026-10-01):
#   * Counts are quoted as: "N table-level findings = M distinct (asset, producer-set) pairs, of which B are back-reads; K of the
#     M-B missing-edge pairs are transitive (a back-read pair cannot be transitive); J assets have only transitive findings".
#     A pair can carry several tables; a shared table's producer set is one pair. (Saved censuses: 68 findings = 65 pairs,
#     3 back-read pairs; 41 of 62 missing-edge pairs transitive; 16 assets only-transitive.)
#   * One-directional: an OVER-declared edge (declared, never read) is never flagged (ka_tulana declares 3 edges, reads
#     nothing, and reads PASS). The check asks "is every read declared", not "is every edge read".
#   * Co-owner exemption: another asset registered on the SAME writer class (bg_transit_engine / bg_transit_rules) is not
#     a producer the asset must depend on.
#   * chart_facts remedy ambiguity: chart_facts has ten producing ga_* assets, so a missing edge to it reads "needs
#     ga_ayurdaya | ... (10 assets)"; any ONE edge satisfies the read. A fact_category ownership map could name the right
#     producer; this check does not.
#   * The reconstructed registry edges used offline (seed + migrations 913/1084/730/676, inactive dropped) were verified by
#     the reviewer against the live registry, read-only: md5 of the sorted depends_on of the 127 active rows =
#     045e811d55d6825cf7c7f1fda329bdc4, identical to the reconstruction.
READS_DELEGATION_HOPS = 3            # the code a rebuild runs, as far as it can be read statically; a frontier check one hop past
_EXEC_METHODS = frozenset({"execute", "executemany", "fetch", "fetchrow", "fetchval", "mogrify", "copy_expert", "query"})
# a call that is not an execute-type METHOD but takes SQL all the same (pandas `read_sql`, a `exec_sql` helper, `execute_values`):
# when NONE of its arguments is traced to literal SQL the parse is incomplete — the SQL it runs is not in the text.
_SQL_LIKE_CALLEE = re.compile(r"^(?:read_sql\w*|exec(?:ute)?(?:_\w+)?|run_sql\w*|run_query\w*|raw_sql)$", re.I)
_SQL_CTX = re.compile(r"\b(?:SELECT|UPDATE|DELETE|INSERT|WITH|MERGE)\b", re.I)
_FROM_JOIN = re.compile(r"\b(FROM|JOIN|USING)\b", re.I)
_SQL_LEAD = r"(?:\s|--[^\n]*\n|/\*.*?\*/)*"
_SQL_VERB_START = re.compile(_SQL_LEAD + r"(?:\{\?\}|\(|(?:SELECT|INSERT|UPDATE|DELETE|WITH|MERGE|CREATE|EXPLAIN|COPY|ALTER|DROP|TRUNCATE|VALUES|SET|DO|PERFORM|LOCK|REFRESH|COMMENT|GRANT|REVOKE)\b)", re.I | re.S)
_ID = r"(?:\{\?\}|\"?[A-Za-z_][A-Za-z0-9_$]*\"?(?:\.\"?[A-Za-z_][A-Za-z0-9_$]*\"?)?)"
_TAIL = r"(?:$|;|,|\)|\b(?:WHERE|JOIN|LEFT|RIGHT|INNER|CROSS|FULL|ON|USING|GROUP|ORDER|LIMIT|HAVING|UNION|INTERSECT|EXCEPT|WINDOW|RETURNING|OFFSET|FETCH|FOR)\b)"
_LITERAL = r"(?:[0-9]+(?:\.[0-9]+)?|'(?:[^']|'')*'|%s|%\([A-Za-z_][A-Za-z0-9_]*\)s|\$[0-9]+|:[A-Za-z_][A-Za-z0-9_]*|\{\?\})"
# a comparison that only SQL writes: a symbolic comparator or cast; IS [NOT] NULL|TRUE|FALSE; [NOT] IN (; [NOT] [I]LIKE '...'; BETWEEN <literal> AND. English `is` / `in` / `not` / `any` alone are not.
_CMP = (r"(?:(?:=|<>|!=|<=|>=|<|>|::|@>|<@|&&|@@|!~\*?|~\*?|->>?)"
        r"|IS\s+(?:NOT\s+)?(?:NULL|TRUE|FALSE)\b"
        r"|IS\s+(?:NOT\s+)?DISTINCT\s+FROM\b"
        r"|SIMILAR\s+TO\b|NOT\s+SIMILAR\s+TO\b"
        r"|(?:NOT\s+)?IN\s*\("
        r"|(?:NOT\s+)?I?LIKE\s*(?:'|%s|\$[0-9]+)"
        r"|(?:NOT\s+)?BETWEEN\s+" + _LITERAL + r"\s+AND\b)")
# the left-hand side of a predicate: an identifier (optionally a call), a literal (`%s = ANY(ids)`, `1=1`), a tuple (`(a, b) IN (...)`), or a sub-select
_LHS = (r"(?:(?:\(\s*)*" + _ID + r"(?:\s*\([^()]*\))?"
        r"|" + _LITERAL +
        r"|\(\s*" + _ID + r"(?:\s*,\s*" + _ID + r")+\s*\))")
_REL = r"(?:\(\s*SELECT\b|" + _ID + r"(?:\s+(?:AS\s+)?" + _ID + r")?\s*" + _TAIL + r")"      # a relation: a sub-select, or a table [alias] followed by a SQL tail
_SQL_CLAUSE_START = re.compile(
    _SQL_LEAD + r"(?:"
    r"ON\s+CONFLICT\b"
    r"|(?:(?:LEFT|RIGHT|FULL)(?:\s+OUTER)?|INNER|CROSS|NATURAL)\s+JOIN\s+" + _REL +
    r"|JOIN\s+" + _REL +
    r"|(?:UNION|INTERSECT|EXCEPT)(?:\s+ALL|\s+DISTINCT)?\s+(?:SELECT\b|\(|VALUES\b)"
    r"|FROM\s+" + _REL +
    r"|(?:WHERE|AND|OR|ON)\s+(?:NOT\s+)?(?:EXISTS\s*\(|(?:\(\s*)+SELECT\b|\(\s*\{\?\}|(?:TRUE|FALSE)\s*(?:$|;|\)|\b(?:AND|OR|GROUP|ORDER|LIMIT|HAVING|UNION|INTERSECT|EXCEPT|RETURNING)\b)"
    r"|" + _LHS + r"\s*" + _CMP + r")"
    r")", re.I | re.S)
def _sql_statement_text(text: str) -> bool:
    """SS residual: does this string BEGIN like a SQL statement (after whitespace and SQL comments)? A prose f-string that merely contains the words `insert` and `from`
    (bg_concordance's dry-run note "would insert ~{n} rows from {m} tagged chunks") is not SQL, and used to read as "a table is named dynamically". A text that begins with an
    unresolved `{?}` or a parenthesis is kept as SQL (it may be one: never dropped on a guess). A fragment of a longer statement that begins with a clause word is SQL only with a SQL-shaped
    continuation (`_SQL_CLAUSE_START`): ON CONFLICT; [LEFT|RIGHT|FULL [OUTER]|INNER|CROSS|NATURAL] JOIN <relation>; JOIN <relation>; UNION / INTERSECT / EXCEPT [ALL] SELECT; FROM <relation>;
    WHERE / AND / OR / ON followed by [NOT] EXISTS ( or by an identifier and a SQL-only comparison (a symbolic comparator, cast or operator such as @> && ~ ->, IS [NOT] NULL|TRUE|FALSE|DISTINCT FROM, [NOT] IN (, [NOT] LIKE '...', SIMILAR TO, BETWEEN <literal> AND), a left side that is an identifier, a call, a literal or a tuple, a sub-select, or a bare TRUE/FALSE (a relation is a sub-select, or a table [alias] followed by a clause word, `,`, `)`, `;` or the end). Prose that merely starts
    with those words ("And the moon with Saturn from the 7th house", "From {x} with strength {y}") is not SQL."""
    return _SQL_VERB_START.match(text) is not None or _SQL_CLAUSE_START.match(text) is not None

_SQL_IDENT = r'(?:"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*)'
_SQL_QNAME = re.compile(_SQL_IDENT + r"(?:\s*\.\s*" + _SQL_IDENT + r")*")
_SQL_ITEM_END = frozenset({
    "WHERE", "JOIN", "INNER", "LEFT", "RIGHT", "FULL", "CROSS", "NATURAL", "ON", "USING", "GROUP", "ORDER", "LIMIT",
    "OFFSET", "UNION", "INTERSECT", "EXCEPT", "HAVING", "WINDOW", "FOR", "RETURNING", "SET", "FETCH", "TABLESAMPLE",
    "WITH", "SELECT", "VALUES", "AS", "LATERAL", "OUTER", "WHEN", "THEN", "ELSE", "END", "AND", "OR", "NOT", "IN"})
# ONE left-to-right pass, so whichever starts first wins: a `--` inside a string literal is not a comment, and an
# apostrophe inside a comment does not open a string.
_SQL_MASK = re.compile(r"'(?:[^']|'')*'|/\*.*?\*/|--[^\n]*", re.S)
_SQL_CTE = re.compile(r"(?:\bWITH\b(?:\s+RECURSIVE)?|,)\s*(" + _SQL_IDENT + r")\s*(?:\([^()]*\))?\s+AS\s+"
                      r"(?:NOT\s+)?(?:MATERIALIZED\s*)?\(", re.I)
# a FROM that is not a relation clause: EXTRACT(field FROM x), SUBSTRING/OVERLAY/POSITION(a FROM b), TRIM([BOTH] [c] FROM x),
# and the comparison `IS [NOT] DISTINCT FROM`. The surrounding call is kept; only the keyword is dropped.
_SQL_FROM_NOT_RELATION = [
    re.compile(r"\bEXTRACT\s*\(\s*[A-Za-z_]+\s+FROM\b", re.I),
    re.compile(r"\b(?:SUBSTRING|OVERLAY|POSITION)\s*\((?:[^()]|\([^()]*\))*?\s+(?:FROM|IN)\b", re.I),
    re.compile(r"\bTRIM\s*\(\s*(?:(?:BOTH|LEADING|TRAILING)\s+)?(?:(?:[\w.]+|'')\s+)?FROM\b", re.I),
]
_SQL_IS_DISTINCT = re.compile(r"\bIS\s+(?:NOT\s+)?DISTINCT\s+FROM\b", re.I)
_SQL_DELETE_FROM = re.compile(r"\bDELETE\s+FROM\b", re.I)


def _sql_clean(text: str) -> str:
    """The SQL with comments and string literals blanked, and every `FROM` that does not open a relation clause
    (EXTRACT / SUBSTRING / TRIM / IS DISTINCT FROM / DELETE FROM — a write target) neutralised."""
    t = _SQL_MASK.sub(lambda m: "''" if m.group(0)[0] == "'" else " ", text)
    for rx in _SQL_FROM_NOT_RELATION:
        t = rx.sub(lambda m: re.sub(r"(?:FROM|IN)$", "_", m.group(0), flags=re.I), t)
    t = _SQL_IS_DISTINCT.sub(" <> ", t)
    return _SQL_DELETE_FROM.sub("DELETE _ ", t)


def _skip_parens(t: str, i: int) -> int:
    """`t[i] == '('`: the index just past its matching ')' (end of text when unbalanced)."""
    depth = 0
    while i < len(t):
        if t[i] == "(":
            depth += 1
        elif t[i] == ")":
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return i


def _take_relation(t: str, i: int, ctes: frozenset) -> tuple[str, str, int]:
    """One relation item at `t[i:]`: (kind, name, next index). kind: `table` | `skip` (a subquery, VALUES, function,
    CTE, foreign schema, or a token that is not a relation) | `dynamic` (the table name is not in the text)."""
    n = len(t)
    while i < n and t[i].isspace():
        i += 1
    if i >= n:
        return "dynamic", "end of the string", i
    if t[i] in "{%$:" or t.startswith("{?}", i):
        j = i
        while j < n and not t[j].isspace() and t[j] not in ",)":
            j += 1
        return "dynamic", t[i:j] or t[i], j
    while True:                                                   # LATERAL / ONLY prefixes
        m = re.match(r"(?:LATERAL|ONLY)\b\s*", t[i:], re.I)
        if not m:
            break
        i += m.end()
    if i < n and t[i] == "(":
        return "skip", "", _skip_parens(t, i)
    m = _SQL_QNAME.match(t, i)
    if not m:
        j = i
        while j < n and not t[j].isspace() and t[j] not in ",)":
            j += 1
        return "skip", "", max(j, i + 1)
    j = m.end()
    if j < n and t[j] in "{%$":                                   # `bg_{suffix}` / `t_%s`: a name assembled outside the string
        k = j
        while k < n and not t[k].isspace() and t[k] not in ",)":
            k += 1
        return "dynamic", t[i:k], k
    k = j
    while k < n and t[k].isspace():
        k += 1
    if k < n and t[k] == "(":                                     # a function call
        return "skip", "", _skip_parens(t, k)
    parts = [p.strip().strip('"') for p in re.split(r"\s*\.\s*", m.group(0))]
    name = parts[-1].lower()
    if len(parts) >= 2 and parts[-2].lower() != "public":        # pg_temp / information_schema / pg_catalog: not an asset table
        return "skip", "", j
    if name in ctes or name.upper() in _SQL_ITEM_END:
        return "skip", "", j
    return "table", name, j


def _skip_alias(t: str, i: int) -> int:
    """Past an optional `[AS] alias [(col, ...)]` after a relation item."""
    n = len(t)
    j = i
    while j < n and t[j].isspace():
        j += 1
    m = re.match(r"AS\b\s*", t[j:], re.I)
    had_as = bool(m)
    if m:
        j += m.end()
    m = re.match(_SQL_IDENT, t[j:])
    if m and (had_as or m.group(0).upper() not in _SQL_ITEM_END):
        j += m.end()
        k = j
        while k < n and t[k].isspace():
            k += 1
        if k < n and t[k] == "(":
            j = _skip_parens(t, k)
    return j


_SQL_TAIL_TOKEN = re.compile(r"\b(?:WHERE|GROUP|ORDER|LIMIT|UNION|INTERSECT|EXCEPT|HAVING|WINDOW|OFFSET|FETCH|RETURNING|JOIN|INNER|"
                             r"LEFT|RIGHT|FULL|CROSS|NATURAL)\b|[;,()\[\]]", re.I)


def _next_list_comma(t: str, i: int) -> int:
    """Index of the comma that continues a FROM list after a JOIN's ON/USING condition (`a JOIN b ON x, c`), or -1:
    the first depth-0 comma before the next clause keyword, JOIN, ';' or an unbalanced ')'."""
    depth = 0
    for m in _SQL_TAIL_TOKEN.finditer(t, i):
        tok = m.group(0)
        if tok in "([":
            depth += 1
        elif tok in ")]":
            if depth == 0:
                return -1
            depth -= 1
        elif depth == 0:
            return m.start() if tok == "," else -1
    return -1


def sql_relations(text: str) -> tuple[list[str], list[str]]:
    """The relations a SQL text READS, as (tables, dynamic): FROM / JOIN targets in order, de-duplicated, lower-cased,
    `public.` stripped. Not reads: CTE names, functions, subqueries and VALUES lists (their inner FROM/JOIN is read on
    its own), tables of any schema but `public`, the target of `DELETE FROM`, and the FROM of EXTRACT / SUBSTRING / TRIM
    / `IS DISTINCT FROM`. A relation after USING IS a read only inside a DELETE / MERGE statement (`DELETE FROM x USING y`, `MERGE ... USING y`);
    `JOIN b USING (id)` is a column list, and `ALTER ... TYPE x USING c::int` / `EXECUTE stmt USING p` are not relation clauses. `dynamic` names every relation position whose table name is not in the text (`{?}` — an
    f-string placeholder `_sql_texts` could not resolve — `%s`, `{x}`, a name cut off at the end of the string) and every
    placeholder that follows a relation where a JOIN could sit: a dynamic position is never guessed, it makes the
    caller's parse incomplete. Comma lists (`FROM a, b`, also after a JOIN's ON condition) are followed."""
    t = _sql_clean(text)
    ctes = frozenset(re.sub(r'^"|"$', "", m.group(1)).lower() for m in _SQL_CTE.finditer(t))
    tables: list[str] = []
    dynamic: list[str] = []
    for m in _FROM_JOIN.finditer(t):
        i = m.end()
        if m.group(1).upper() == "USING":
            j = i
            while j < len(t) and t[j].isspace():
                j += 1
            if j < len(t) and t[j] == "(":        # `JOIN b USING (id)`: a column list; `MERGE ... USING (SELECT ..)`: its inner FROM is read on its own
                continue
            if not re.search(r"\b(?:DELETE|MERGE)\b", t[t.rfind(";", 0, m.start()) + 1:m.start()], re.I):
                continue                          # `ALTER ... TYPE x USING c::int`, `EXECUTE stmt USING p`: not a relation clause
        while True:
            kind, name, i = _take_relation(t, i, ctes)
            if kind == "table" and name not in tables:
                tables.append(name)
            elif kind == "dynamic":
                dynamic.append(name)
            i = _skip_alias(t, i)
            j = i
            while j < len(t) and t[j].isspace():
                j += 1
            if j < len(t) and t[j] == ",":
                i = j + 1
                continue
            if m.group(1).upper() == "JOIN":
                c = _next_list_comma(t, i)
                if c >= 0:
                    i = c + 1
                    continue
            if j < len(t) and t[j] in "{%":
                dynamic.append(f"a placeholder {t[j:j + 6].split()[0]!r} follows the relation and may expand to a JOIN or another relation")
            break
    return tables, dynamic


def _walk_ctx(root: ast.AST, fn=None, cls=None):
    """(node, enclosing FunctionDef or None, enclosing ClassDef or None) for every node under `root`."""
    if isinstance(root, (ast.FunctionDef, ast.AsyncFunctionDef)):
        fn = root
    elif isinstance(root, ast.ClassDef):
        cls = root
    yield root, fn, cls
    for c in ast.iter_child_nodes(root):
        yield from _walk_ctx(c, fn, cls)


def _lit_str(n: ast.AST) -> bool:
    """A string expression whose literal parts `_sql_texts` reads: a str constant, an f-string, `a + b`, `a % b`, a
    conditional of those, or a `.format()/.strip()/…` of one. What such an expression hides (a placeholder) is caught
    where it sits at a FROM/JOIN position (`dynamic`)."""
    if isinstance(n, ast.Constant):
        return isinstance(n.value, str)
    if isinstance(n, ast.JoinedStr):
        return True
    if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Mod)):
        return _lit_str(n.left) and (isinstance(n.op, ast.Mod) or _lit_str(n.right))
    if isinstance(n, ast.IfExp):
        return _lit_str(n.body) and _lit_str(n.orelse)
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr in (
            "format", "strip", "lstrip", "rstrip", "replace", "dedent", "join"):
        return _lit_str(n.func.value)
    return False


def _callers(name: str, sites: list) -> list:
    return [s for s in sites if s["callee"] == name]


def _is_param(fn, name: str) -> bool:
    a = fn.args
    return name in [p.arg for p in a.posonlyargs + a.args + a.kwonlyargs] + [x.arg for x in (a.vararg, a.kwarg) if x is not None]


def _enclosing_fn(tree, fn):
    """The innermost function definition that contains `fn` (a nested def) in `tree`, or None."""
    best = None
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n is not fn and any(c is fn for c in ast.walk(n)):
            if best is None or any(c is n for c in ast.walk(best)):
                best = n
    return best


def _sql_arg_traced(a: ast.AST, fn, cls, unit, sites: list, depth: int = 0, seen=None) -> bool:
    """Is the SQL argument of an execute-type call traced to literal SQL text? A literal expression, a Name whose every
    assignment in the function is one (or a module-level literal), a `self.X` whose class assigns a literal X, or a
    parameter of the enclosing function whose every in-scope caller passes a traced argument (at least one caller)."""
    if _lit_str(a):
        return True
    seen = seen or set()
    if isinstance(a, ast.IfExp):                       # `A_SQL if cond else B_SQL`: traced when BOTH branches are (a conditional of two named constants)
        return _sql_arg_traced(a.body, fn, cls, unit, sites, depth, seen) and _sql_arg_traced(a.orelse, fn, cls, unit, sites, depth, seen)
    if isinstance(a, ast.Attribute) and isinstance(a.value, ast.Name) and a.value.id in ("self", "cls") and cls is not None:
        vals = [s.value for s in cls.body if isinstance(s, ast.Assign) and any(isinstance(t, ast.Name) and t.id == a.attr for t in s.targets)]
        vals += [s.value for s in cls.body if isinstance(s, ast.AnnAssign) and isinstance(s.target, ast.Name) and s.target.id == a.attr and s.value is not None]
        return bool(vals) and all(_lit_str(v) for v in vals)
    if not isinstance(a, ast.Name):
        return False
    local = []
    if fn is not None:
        for x in ast.walk(fn):
            if isinstance(x, ast.Assign) and any(isinstance(t, ast.Name) and t.id == a.id for t in x.targets):
                local.append(x.value)
            elif isinstance(x, ast.AnnAssign) and isinstance(x.target, ast.Name) and x.target.id == a.id and x.value is not None:
                local.append(x.value)
            elif isinstance(x, ast.AugAssign) and isinstance(x.target, ast.Name) and x.target.id == a.id:
                local.append(x.value)
    if local:
        return all(_lit_str(v) for v in local)
    if fn is not None and not _is_param(fn, a.id):
        # SS residual: a NESTED function's SQL name assigned in an ENCLOSING function (`insert_sql = \"\"\"...\"\"\"` then `def _flush(): cur.execute(insert_sql, p)`, bg_concordance): the
        # closure variable is traced when every assignment to it in the enclosing function chain is a literal (and it is assigned there at least once)
        outer = _enclosing_fn(unit["tree"], fn)
        while outer is not None:
            vals = [x.value for x in ast.walk(outer) if isinstance(x, ast.Assign) and any(isinstance(t, ast.Name) and t.id == a.id for t in x.targets)]
            vals += [x.value for x in ast.walk(outer) if isinstance(x, ast.AnnAssign) and isinstance(x.target, ast.Name) and x.target.id == a.id and x.value is not None]
            if vals:
                return all(_lit_str(v) for v in vals) and not any(isinstance(x, ast.AugAssign) and isinstance(x.target, ast.Name) and x.target.id == a.id for x in ast.walk(outer))
            if _is_param(outer, a.id):
                return False
            outer = _enclosing_fn(unit["tree"], outer)
    top = _top_defs(unit["tree"]).get(a.id)
    if isinstance(top, (ast.Assign, ast.AnnAssign)) and top.value is not None and _lit_str(top.value):      # an ANNOTATED constant (`X: Final[str] = \"\"\"...\"\"\"`) is an AnnAssign
        return True
    imported = _import_map(unit["tree"], unit["path"].parent).get(a.id)
    if imported is not None and imported[1] is not None:         # `from .sql import READ_SQL`: the constant is read as a unit
        got = _resolve_assign(imported[0], imported[1])
        if got is not None and isinstance(got[2], (ast.Assign, ast.AnnAssign)) and got[2].value is not None and _lit_str(got[2].value):
            return True
    if fn is None or depth >= 3:
        return False
    args = fn.args
    pos = [p.arg for p in args.posonlyargs + args.args]
    kwonly = [p.arg for p in args.kwonlyargs]
    if a.id not in pos and a.id not in kwonly:
        return False
    key = (id(fn), a.id)
    if key in seen:
        return False
    seen = seen | {key}
    calls = _callers(fn.name, sites)
    if not calls:
        return False
    is_method = bool(pos) and pos[0] in ("self", "cls")
    for s in calls:
        call = s["call"]
        arg = None
        if a.id in pos:
            idx = pos.index(a.id) - (1 if is_method and isinstance(call.func, ast.Attribute) else 0)
            if 0 <= idx < len(call.args):
                arg = call.args[idx]
        if arg is None:
            arg = next((k.value for k in call.keywords if k.arg == a.id), None)
        if arg is None or not _sql_arg_traced(arg, s["fn"], s["cls"], s["unit"], sites, depth + 1, seen):
            return False
    return True


def _resolve_assign(path: Path, name: str):
    """A module-level `NAME = <expr>` (an imported SQL constant) that `_resolve_def` deliberately skips: (path, tree,
    assign node) following package re-exports, or None."""
    for _ in range(4):
        tree = _parse(path)
        d = _top_defs(tree).get(name)
        if isinstance(d, (ast.Assign, ast.AnnAssign)):
            return path, tree, d
        nxt = _import_map(tree, path.parent).get(name)
        if not nxt or nxt[1] is None:
            return None
        path, name = nxt
    return None


def _third_party_binding(path: Path, name: str) -> bool:
    """Is `name` bound in the module at `path` by an import that does NOT resolve to first-party code (a re-exported
    third-party module such as `from jhora.panchanga import drik`)? Following first-party re-exports, at most 3."""
    for _ in range(4):
        tree = _parse(path)
        bound = None
        for n in ast.walk(tree):
            if isinstance(n, ast.ImportFrom) and any((a.asname or a.name) == name for a in n.names):
                bound = n
            elif isinstance(n, ast.Import) and any((a.asname or a.name.split(".")[0]) == name for a in n.names):
                bound = n
        if bound is None:
            return False
        nxt = _import_map(tree, path.parent).get(name)
        if not nxt:
            return True
        if nxt[1] is None:
            return False
        path, name = nxt
    return False


def _constant_units(units: list[dict], hops: int) -> tuple[list[dict], list[str]]:
    """Imported module-level constants the scope uses (`from .sql import READ_SQL`): `_delegation_scope` follows
    definitions only, so their SQL would be missed silently. Returns (pseudo-units holding the assignment, reasons) — a
    used first-party name that resolves to neither a definition nor an assignment is a reason (not silently skipped)."""
    out, why, seen = [], [], set()
    for u in units:
        for tp, attr in _external_refs(u["nodes"], _import_map(u["tree"], u["path"].parent)):
            if _resolve_def(tp, attr) is not None:
                continue
            a = _resolve_assign(tp, attr)
            if a is None and _third_party_binding(tp, attr):
                continue            # a shim that re-exports a third-party module (`pyjhora_adapter/_jhora.py`): no SQL of ours behind it
            if a is None:
                why.append(f"{u['rel']}: the imported name {attr!r} (from {_rel(tp)}) is neither a definition nor a constant "
                           "this scan can read, so SQL behind it is not resolvable")
                continue
            ap, atree, anode = a
            if (str(ap.resolve()), attr) in seen:
                continue
            seen.add((str(ap.resolve()), attr))
            if u["hop"] + 1 > hops:
                if any(_SQL_CTX.search(t) and _FROM_JOIN.search(t)
                       for t, _ln in _sql_texts(dict(rel=_rel(ap), path=ap, tree=atree, nodes=[anode], hop=u["hop"] + 1, via=""))):
                    why.append(f"{_rel(ap)}: the constant {attr!r} holds SQL that reads a relation {u['hop'] + 1} hop(s) from the "
                               f"writer ({u['via']}), one past the scan limit of {hops} hop(s)")
                continue
            out.append(dict(rel=_rel(ap), path=ap, tree=atree, nodes=[anode], hop=u["hop"] + 1,
                            via=f"{u['via']} → {_rel(ap)}:{attr}"))
    return out, why


def _scope_sites(units: list[dict]) -> list[dict]:
    sites = []
    for u in units:
        for node in u["nodes"]:
            for x, fn, cls in _walk_ctx(node):
                if isinstance(x, ast.Call):
                    f = x.func
                    callee = f.id if isinstance(f, ast.Name) else f.attr if isinstance(f, ast.Attribute) else None
                    sites.append(dict(call=x, callee=callee, fn=fn, cls=cls, unit=u))
    return sites


def reads_scan(asset_id: str, files: list[str], hops: int | None = None) -> dict:
    """What the writer of `asset_id` READS (static SQL), and whether that parse is complete.

    Returns dict(reads={table: [(file, line, chain)]}, incomplete=[reason, ...], units=int, sql_strings=int, hops=int,
    co_registered=[other asset ids registered on the same writer class]).
    `reads` is every FROM / JOIN relation of every SQL string (an execute-type call's text, f-strings and `a + b`
    resolved by `_sql_texts`) in the registered class's delegation scope, `hops` modules deep (the same scope
    machinery as Idem.pattern; docstrings are not SQL). `incomplete` lists every reason the parse may be missing a
    read, each with file:line: a registered class not found (the whole module would be in scope), a table named
    dynamically, an execute-type call whose SQL argument is not traced to a literal, and SQL that reads a relation
    one hop past the scan limit. Empty `incomplete` = every SQL string in scope was parsed and every relation named."""
    hops = READS_DELEGATION_HOPS if hops is None else hops
    units, _beyond = _delegation_scope(asset_id, files, hops=hops)
    extra_units, unresolved = _constant_units(units, hops)
    units = units + extra_units
    reads: dict[str, list[tuple[str, int, str]]] = {}
    incomplete: list[str] = list(unresolved)
    n_sql = 0
    co_registered: set[str] = set()                  # other assets registered on the SAME writer class (bg_transit_engine / bg_transit_rules)
    for name in files:
        cls = _writer_class(_writer_path(name), asset_id)
        if cls is None:
            incomplete.append(f"{name}: no class registered for {asset_id} found, so the whole module would be in scope")
            continue
        consts = _module_constants(_parse(_writer_path(name)))
        co_registered |= {rid for d in cls.decorator_list if (rid := _register_id(d, consts))} - {asset_id}
    for u in units:
        for text, line in _sql_texts(u):
            if not (_SQL_CTX.search(text) and _FROM_JOIN.search(text) and _sql_statement_text(text)):
                continue
            n_sql += 1
            tables, dynamic = sql_relations(text)
            for t in tables:
                loc = (u["rel"], line, u["via"] if u["hop"] else "")
                if loc not in reads.setdefault(t, []):
                    reads[t].append(loc)
            for d in dynamic:
                incomplete.append(f"{u['rel']}:{line}: a table is named dynamically ({d!r}), so the read is not resolvable")
    sites = _scope_sites(units)
    for s in sites:
        c = s["call"]
        if isinstance(c.func, ast.Attribute) and c.func.attr in _EXEC_METHODS and c.args \
                and not _sql_arg_traced(c.args[0], s["fn"], s["cls"], s["unit"], sites):
            incomplete.append(f"{s['unit']['rel']}:{c.lineno}: {c.func.attr}() is given SQL that is not traced to a "
                              f"literal ({ast.unparse(c.args[0])[:40]!r}), so what it reads is not resolvable")
        elif isinstance(c.func, (ast.Attribute, ast.Name)) and c.args:
            callee = c.func.attr if isinstance(c.func, ast.Attribute) else c.func.id
            if callee not in _EXEC_METHODS and _SQL_LIKE_CALLEE.match(callee) and not any(
                    _sql_arg_traced(a, s["fn"], s["cls"], s["unit"], sites) for a in list(c.args) + [k.value for k in c.keywords]):
                incomplete.append(f"{s['unit']['rel']}:{c.lineno}: {callee}() takes SQL and none of its arguments is traced "
                                  "to a literal, so what it reads is not resolvable")
    frontier, _ = _delegation_scope(asset_id, files, hops=hops + 1)
    for u in frontier:
        if u["hop"] == hops + 1 and any(_SQL_CTX.search(t) and _FROM_JOIN.search(t) for t, _ln in _sql_texts(u)):
            incomplete.append(f"{u['rel']}: holds SQL that reads a relation {hops + 1} hop(s) from the writer ({u['via']}), "
                              f"one past the scan limit of {hops} hop(s)")
    return dict(reads=reads, incomplete=sorted(set(incomplete)), units=len(units), sql_strings=n_sql, hops=hops,
                co_registered=sorted(co_registered))


def build_table_owners(rows) -> dict[str, list[str]]:
    """table -> the active WRITER-BACKED assets that PRODUCE it: each row is (asset_id, target_table, count_sql[,
    has_writer=True]); a table is produced by an asset when it is its target_table or one of the relations its
    count_sql names (a multi-table asset declares its produced tables there; a partition writer such as ga_strength
    declares chart_facts there). An asset with no writer (a user_data table such as lel_events, a static table) produces
    nothing a build waits for: a depends_on edge to it could never reach `lit` (T4 check 9, a permanent DEP-ASSERT
    trap), so a read of its table is never a missing edge."""
    out: dict[str, set[str]] = {}
    for row in rows:
        aid, target, count_sql = row[0], row[1], row[2]
        if len(row) > 3 and not row[3]:
            continue
        for t in ([target] if target else []) + _count_tables(count_sql or ""):
            out.setdefault(t.lower(), set()).add(aid)
    return {t: sorted(a) for t, a in sorted(out.items())}


def produced_table_owners() -> dict[str, list[str]]:
    """Registry-wide (every layer) table -> producing active writer-backed assets, in one JSON read (count_sql holds
    newlines, so a line-oriented read would split rows). Raises Unknown when the registry cannot be read."""
    blob = scalar("SELECT coalesce(json_agg(json_build_object('a',asset_id,'t',target_table,'c',coalesce(count_sql,''),"
                  "'w',coalesce(has_writer,false)) ORDER BY asset_id)::text,'[]') FROM asset_registry "
                  "WHERE is_active AND NOT coalesce(dead_flag,false)")
    return build_table_owners((r["a"], r["t"], r["c"], r["w"]) for r in json.loads(blob or "[]"))


_DAG_GUARD: list = []
_DAG_GUARD_PATH = Path(__file__).resolve().parents[2] / "python-sidecar" / "pipeline" / "orchestrator" / "dag_edge_guard.py"


def _dag_guard():
    """The repo's own `pipeline/orchestrator/dag_edge_guard.py`, loaded by file path (it imports nothing heavy at module
    level: its DB import is deferred). Its exemption lists are the SINGLE source for which tables a read of which needs no
    declared edge — this module never keeps a second list. Raises Unknown when the guard cannot be loaded."""
    if not _DAG_GUARD:
        import importlib.util
        try:
            spec = importlib.util.spec_from_file_location("dag_edge_guard_for_census", _DAG_GUARD_PATH)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            for need in ("_UNGATED_PREFIXES", "_UNGATED_EXACT", "_EXTERNAL_TABLES", "_SHARED_SOFT_TABLES"):
                getattr(mod, need)
        except Exception as exc:
            raise Unknown(f"dag_edge_guard could not be loaded from {_DAG_GUARD_PATH}: {type(exc).__name__}: {exc}") from exc
        _DAG_GUARD.append(mod)
    return _DAG_GUARD[0]


def _is_bedrock(table: str) -> bool:
    """dag_edge_guard's rule (`_UNGATED_PREFIXES` / `_UNGATED_EXACT` / `_EXTERNAL_TABLES`, pipeline/orchestrator/
    dag_edge_guard.py:86-89): always-present L0 bedrock (bg_, reference_, brahma_, sutravali_, classical_, ephemeris_daily)
    and external ingest tables are never gated."""
    guard = _dag_guard()
    t = table.lower()
    return t.startswith(tuple(guard._UNGATED_PREFIXES)) or t in guard._UNGATED_EXACT or t in guard._EXTERNAL_TABLES


def _ancestors(graph: dict[str, list[str]] | None, start: str) -> set[str]:
    out, todo = set(), [start]
    while todo:
        for d in (graph or {}).get(todo.pop(), []):
            if d not in out:
                out.add(d)
                todo.append(d)
    return out


def _dep_path(graph: dict[str, list[str]], start: str, goal: str) -> list[str] | None:
    """The shortest depends_on chain `start -> ... -> goal` (at least one edge, so `start == goal` finds a cycle through
    `start`), or None. Computed from the registry graph handed in, never assumed."""
    prev: dict[str, str] = {}
    todo = []
    for d in graph.get(start, []):
        if d not in prev:
            prev[d] = start
            todo.append(d)
    while todo:
        x = todo.pop(0)
        if x == goal:
            path = [goal]
            while True:
                path.append(prev[path[-1]])
                if path[-1] == start:
                    return path[::-1]
        for d in graph.get(x, []):
            if d not in prev:
                prev[d] = x
                todo.append(d)
    return None


def _reads_clause(aid: str, r: dict, files: list[str], owners_fn, g, static=None) -> tuple[str, str, dict]:
    """The reads-match clause of Build.dag (T4:275): (verdict, text, extra record keys). `g` is the registry-wide
    depends_on graph with this asset's own edges applied, or None when it could not be read.

    A read of another writer-backed asset's table with no DIRECT declared edge is a finding. Two kinds:
      missing_edge  declaring `aid -> producer` is possible: the graph stays acyclic (a shared table is satisfied by an
                    edge to ANY one producer, and only the producers that stay acyclic are named);
      back_read     every producer of the table already depends on `aid` (directly or through a chain): the code reads a
                    DOWNSTREAM asset's product, an edge would close a cycle, so it is NOT a missing edge. The cycle test
                    is computed from the graph plus the candidate edge (`_dep_path`), never listed by name.
    Both keep the verdict FAIL (the evidence stays visible). `transitive_only` marks a FAIL whose every missing edge is
    already reachable through a declared dependency (ordering holds, the edge is undeclared) — SS decides later whether
    that stays a FAIL; the default is FAIL.
    Findings are counted at table level (one per (asset, table) with a producer set); a distinct (asset, producer-set)
    pair can carry several tables.

    An incomplete parse with no undeclared read reads PARTIAL when at least one read resolved and every resolved read is
    covered (the Idem.pattern precedent: a scan that cannot see everything says so), NO_DETECTOR when nothing resolved.
    DEFAULT PENDING SS."""
    deps = list(r["depends_on"])
    if not files:
        if not r["has_writer"] and not deps:
            return PASS, ("no writer (registry has_writer=false and no @register found) and no declared edge — no build code "
                          "reads anything, so there is nothing to match"), {}
        if not r["has_writer"] and static is not None:
            # SS 2026-10-05 R-d: migration-seeded STATIC data (declared kind static + has_writer false, agreed by the registry row, the @register scan and a static_data declaration whose named migrations exist on main and create/seed the declared table) has no build
            # code to read anything: its declared edge(s) are checked for EXISTENCE only (the `exists` and `cycle` clauses of this same record); there is nothing to compare with reads.
            return PASS, (f"static data (declared kind static, has_writer: false; registry row, @register scan and a static_data declaration agree: its named migrations exist on main and create/seed the declared table): no build code, so the {len(deps)} declared edge(s) are "
                          "checked for existence only (SS R-d), not compared with reads"), dict(static_data=dict(static))
        if not r["has_writer"]:
            return NO_DET, (f"not established: no writer code to scan (registry has_writer=false) but {len(deps)} declared "
                            "edge(s) — they cannot be compared with reads"), {}
        return NO_DET, ("not established: the registry says has_writer=true and no @register file was found "
                        "(see Build.registered)"), {}
    try:
        scan = reads_scan(aid, files)
    except Exception as exc:
        return ERRORED, f"check errored: reads-match scan failed: {type(exc).__name__}: {exc}", {}
    own = set(filter(None, [r["target_table"]])) | set(_count_tables(r["count_sql"]))
    owners: dict[str, list[str]] = {}
    if scan["reads"]:
        try:
            owners = owners_fn()
        except Unknown as exc:
            return ERRORED, (f"check errored: table ownership unreadable, so what the writer reads cannot be attributed to "
                             f"assets: {exc}"), {}
    try:
        guard = _dag_guard() if scan["reads"] else None
    except Unknown as exc:
        return ERRORED, f"check errored: {exc}", {}
    anc = {d: _ancestors(g, d) for d in deps} if g is not None else {}
    closure = set(deps).union(*anc.values()) if g is not None else None
    findings, covered, exempt, soft, co_skipped = [], 0, [], [], []
    for t, locs in sorted(scan["reads"].items()):
        prod = [a for a in owners.get(t, []) if a != aid]
        if not prod or aid in owners.get(t, []) or t in own:
            continue                  # nobody produces it / its own table
        if any(p in scan["co_registered"] for p in prod):
            # produced by another asset of the SAME writer class (bg_transit_engine / bg_transit_rules: one class registered
            # twice): one writer, not a dependency. Skipped as a finding, but RECORDED (never silently dropped).
            co_skipped.append(dict(asset=aid, table=t, producers=sorted(prod), kind="co_registered_skipped"))
            continue
        if any(p in deps for p in prod):
            covered += 1
            continue
        f, ln, via = sorted(locs)[0]  # the first location in file order
        bedrock_name = _is_bedrock(t)
        non_l0 = bedrock_name and not all(o.startswith(LAYERS["L0"]["prefix"]) for o in owners.get(t, []))
        if bedrock_name and not non_l0:
            # SS ruling 2026-10-01 (PROVISIONAL interpretation of T4, to be confirmed at the J1 review): a read of an L0 bedrock
            # table needs no declared edge. STRICTER THAN dag_edge_guard, which exempts by table NAME alone: here the table must
            # have a bedrock NAME (the guard's lists) AND every producer that owns it must be an L0 asset (bg_*) — a
            # `brahma_*` table owned by an L2+ asset is an ordinary read (earned-signal-conservative, CLAUDE.md N.8).
            # Kept visible as `bedrock_exempt`, never dropped.
            exempt.append(dict(asset=aid, needs=" | ".join(prod), table=t, file=f, line=ln, via=via, kind="bedrock_exempt"))
            continue
        if t in guard._SHARED_SOFT_TABLES and closure is not None and any(p in closure for p in prod):
            # dag_edge_guard's SOFT tier: a polymorphic multi-producer table (chart_facts) is satisfied by ANY producer in the
            # declared TRANSITIVE closure; with none in the closure at all it stays a finding (below).
            soft.append(dict(asset=aid, needs=" | ".join(prod), table=t, file=f, line=ln, via=sorted(p for p in prod if p in closure),
                             kind="soft_satisfied", fact_category_matched=False))
            continue
        chains = {p: _dep_path(g, p, aid) for p in prod} if g is not None else {}
        viable = [p for p in prod if chains.get(p) is None]
        if g is not None and not viable:
            findings.append(dict(asset=aid, needs=" | ".join(prod), table=t, file=f, line=ln, via=via, transitive_via=[],
                                 kind="back_read", cycle_path=chains[prod[0]], cycle_tested=True))
        else:
            need = viable if g is not None else prod
            findings.append(dict(asset=aid, needs=" | ".join(need), table=t, file=f, line=ln, via=via,
                                 transitive_via=sorted(d for d in deps if any(p in anc.get(d, ()) for p in need)),
                                 kind="missing_edge", cycle_tested=g is not None))
    for fd in findings:
        if _is_bedrock(fd["table"]) and not all(o.startswith(LAYERS["L0"]["prefix"]) for o in owners.get(fd["table"], [])):
            fd["bedrock_name_non_l0_owner"] = True
    if findings:
        parts = []
        for fd in findings:
            at = f"{fd['file']}:{fd['line']}" + (f", via {fd['via']}" if fd["via"] else "")
            if fd["kind"] == "back_read":
                parts.append(f"back-read: {aid} reads {fd['table']} ({at}), the product of {fd['needs']}, which already depends on "
                             f"{aid} (chain {' -> '.join(fd['cycle_path'])}); an edge {aid} -> {fd['needs']} would create a cycle")
            else:
                s = f"missing depends_on edge: {aid} -> {fd['needs']} (reads {fd['table']} at {at}"
                s += (f"; the producer is reachable transitively via {', '.join(fd['transitive_via'])}, so ordering holds but the "
                      "edge is undeclared") if fd["transitive_via"] else ""
                s += "; the cycle test did not run: the registry dependency graph was unreadable, so this could be a back-read" \
                    if not fd["cycle_tested"] else ""
                s += "; bedrock-named table with a non-L0 owner: not exempt (stricter than dag_edge_guard, which exempts by name alone)" \
                    if fd.get("bedrock_name_non_l0_owner") else ""
                parts.append(s + ")")
        extra_ev = {k: v for k, v in (("bedrock_exempt", exempt), ("soft_satisfied", soft), ("co_registered_skipped", co_skipped)) if v}
        miss = [fd for fd in findings if fd["kind"] == "missing_edge"]
        # transitive_only is claimed only when no back-read is present for the asset: a back-read must stay visible in the
        # rollup reason (a mix of a back-read and all-transitive missing edges is NOT "transitive only")
        only_t = bool(miss) and len(miss) == len(findings) and all(fd["transitive_via"] for fd in miss)
        return FAIL, "FAIL — " + "; ".join(parts), dict(missing_edges=findings, transitive_only=only_t, **extra_ev)
    extra_ev = {k: v for k, v in (("bedrock_exempt", exempt), ("soft_satisfied", soft), ("co_registered_skipped", co_skipped)) if v}
    satisfied = covered + len(exempt) + len(soft)
    note = ""
    if co_skipped:
        note += (f"; {len(co_skipped)} read(s) of table(s) produced by an asset registered on the SAME writer class "
                 f"({', '.join(c['table'] + ' <- ' + '/'.join(c['producers']) for c in co_skipped)}) were not compared with the declared "
                 "edges: one class registered for several assets is one writer, not a dependency")
    if exempt:
        note += (f"; {len(exempt)} read(s) of bedrock-named table(s) owned only by L0 assets ({', '.join(e['table'] for e in exempt)}) "
                 "need no declared edge (dag_edge_guard exemption list; stricter than the guard, which exempts by table name alone; "
                 "provisional interpretation of T4, to be confirmed at the J1 review)")
    if soft:
        note += (f"; {len(soft)} chart_facts read(s) satisfied by a producer in the declared transitive closure "
                 f"({', '.join(sorted({v for sf in soft for v in sf['via']}))}; dag_edge_guard SOFT tier): satisfied by ANY chart_facts "
                 "producer in the declared closure; fact_category is not matched, so this does not prove the READ category is "
                 "produced upstream")
    if scan["incomplete"]:
        why = "; ".join(scan["incomplete"][:3]) + (f"; +{len(scan['incomplete']) - 3} more" if len(scan["incomplete"]) > 3 else "")
        if satisfied:
            return PARTIAL, (f"{satisfied} resolved read(s) of other assets' tables are covered by declared edges or exempt (see below), "
                             f"but the parse is incomplete — {why}{note}"), extra_ev
        return NO_DET, (f"not established: the parse is incomplete — {why}. Nothing resolved to compare, so the claim has no "
                        "detector (never a PASS by absence of a parse)"), {}
    return PASS, (f"{covered} read(s) of other assets' tables, every one covered by a declared edge{note}; static scan of "
                  f"{scan['units']} code unit(s), {scan['sql_strings']} SQL string(s), hops<={scan['hops']}, every relation "
                  "named; reads through views and DB functions are not followed"), extra_ev


def _measure_dag(aid: str, r: dict, files: list[str], known: set[str], prefix: str, owners_fn, graph, static=None) -> dict:
    """Build.dag (T4:275, check 4: "every depends_on entry exists; no cycle; the declared edges match what the asset
    actually reads"), three clauses, each stated in the verdict text:

      exists       every depends_on id is an ACTIVE registry asset, in EVERY layer. When the registry-wide graph could not
                   be read only ids with this layer's prefix can be checked against the layer registry; the others are
                   NO_DETECTOR for this clause ("not checked"), never a silent PASS.
      cycle        the asset is on no dependency cycle in the registry graph (the cycle is reported); NO_DETECTOR when the
                   graph could not be read.
      reads-match  see `_reads_clause`.

    The verdict is the worst of the three (FAIL > ERRORED > NO_DETECTOR > PARTIAL > PASS). `owners_fn()` is the lazily read
    registry-wide ownership map (raises Unknown when unreadable); `graph` the registry-wide depends_on map or None."""
    deps = list(r["depends_on"])
    g = None if graph is None else {**graph, aid: deps}
    if g is not None:
        unknown, unverifiable = [d for d in deps if d not in set(g) | known], []
    else:
        unknown = [d for d in deps if d.startswith(prefix) and d not in known]
        unverifiable = [d for d in deps if not d.startswith(prefix)]
    if unknown:
        ev, et = FAIL, f"depends_on references unknown or inactive assets: {unknown}"
    elif unverifiable:
        ev, et = NO_DET, (f"cross-layer id(s) {unverifiable} not checked: the registry-wide dependency read was unavailable")
    else:
        ev, et = PASS, (f"all {len(deps)} are active registry assets (every layer)" if deps else "no declared edge to resolve")
    if g is None:
        cv, ct = NO_DET, "not measured: the registry-wide dependency read was unavailable"
    else:
        cyc = _dep_path(g, aid, aid)
        cv, ct = (FAIL, f"{' -> '.join(cyc)} (a dependency cycle)") if cyc else (PASS, f"{aid} is on no dependency cycle (registry-wide graph)")
    rv, rt, extra = _reads_clause(aid, r, files, owners_fn, g, static=static)
    v = rollup_verdicts([ev, cv, rv])
    return dict(v=v, measured=f"{len(deps)} declared edge(s); exists: {et}; cycle: {ct}; reads-match: {rt}", **extra)


def _declared_kind(declarations, asset_id: str):
    """The kind the asset-declarations file declares for `asset_id`, or None (absent asset / null / unknown kind)."""
    e = (declarations or {}).get(asset_id)
    k = e.get("kind") if isinstance(e, dict) else None
    return k if isinstance(k, str) and k in DECLARED_KINDS else None


def _grade_dep_liveness_none(dag, scanned: bool = True) -> dict:
    """Build.dep_liveness for an asset with an EMPTY declared dependency list (SS N-72, S4; N-22 row 23 re-proposed).

    N/A (cause no-declared-dependencies) ONLY when the reads-match detector is demonstrably present AND clean: this asset's
    own Build.dag record reads PASS (exists, cycle and reads-match: the writer's SQL reads no other asset's table without a
    declared edge, and the scan was COMPLETE) AND it recorded NO `bedrock_exempt` read. An asset that reads another L0 asset's
    table under the ruled bedrock exemption consumes that asset's rows, so "nothing to be live" would be false: the
    CONSERVATIVE reading withholds the N/A (NO_DETECTOR). Anything else (the dag check missing, FAIL on an undeclared read
    or a cycle, PARTIAL/NO_DETECTOR/ERRORED because the scan was incomplete or unavailable) is NO_DETECTOR, never N/A: with
    no declared dependency "nothing to be live" is a claim only a clean reads-match scan can make (CLAUDE.md N.8; the F5
    pattern of `never-run`). `scanned` is False for an asset with no writer code: no scan ran, so the text says "nothing to
    match" and never claims a detector found anything."""
    v = (dag or {}).get("v")
    ex = (dag or {}).get("bedrock_exempt") or ()
    if v == PASS and not (dag or {}).get("missing_edges") and not ex:
        co = (dag or {}).get("co_registered_skipped") or ()
        if scanned:
            text = "no declared dependencies, and the reads-match detector (Build.dag) found no undeclared read of another asset's table"
        else:
            text = ("no declared dependencies, and no writer (no build code to scan): there is nothing to match; the reads-match "
                    "detector did not run")
        if co:
            text += (f" ({len(co)} read(s) of table(s) produced by an asset registered on the same writer class were not compared: "
                     f"{', '.join(c['table'] for c in co)})")
        return _na(text, "no-declared-dependencies")
    if v == PASS and ex:
        return dict(v=NO_DET, measured="NO_DETECTOR — no declared dependencies, but the asset reads another L0 asset's table under the "
                                       "ruled bedrock exemption (" + ", ".join(sorted({str(e.get("table")) for e in ex}))
                                       + "): it consumes that asset's rows, so 'nothing to be live' is not claimed")
    why = "Build.dag was not measured" if v is None else f"Build.dag reads {v}"
    return dict(v=NO_DET, measured=f"NO_DETECTOR — no declared dependencies, but the reads-match detector did not establish "
                                   f"that the asset reads nothing undeclared ({why}), so 'nothing to be live' is not claimed")


def d1_evidence_problem(meas) -> str:
    """"" when a Carr.D1 measurement carries the evidence a D1 PASS/PARTIAL needs, else what is missing (a bare {v: PASS} is not a D1
    result: it has no verified passage behind it). The digest recomputation is over the record's OWN contents (the recorded passage and
    chunk ledger): it catches an accidental edit or a truncated record, it is NOT a forgery barrier (a record forged consistently
    passes it; the measurement itself is what reads the database)."""
    ev = meas.get("d1") if isinstance(meas, dict) else None
    if not isinstance(ev, dict):
        return "no `d1` evidence"
    if not (isinstance(ev.get("passage_sha256"), str) and re.fullmatch(r"[0-9a-f]{64}", ev["passage_sha256"])):
        return "no passage_sha256 (the cut span was not read)"
    ch = ev.get("chunks")
    if not (isinstance(ch, list) and ch and all(isinstance(c, dict) and c.get("verified") is True for c in ch)):
        return "no verified chunk ledger"
    d1m = _carriage_d1()
    if not isinstance(ev.get("passage"), str) or d1m.span_digest(ev["passage"]) != ev["passage_sha256"]:
        return "passage_sha256 does not equal the sha256 of the recorded passage (recomputed)"
    try:
        if d1m.chunks_digest(ch) != ev.get("chunks_sha256"):
            return "chunks_sha256 does not equal the digest of the recorded chunk ledger (recomputed)"
    except (KeyError, TypeError):
        return "the chunk ledger is malformed (the chunks digest cannot be recomputed)"
    if meas.get("citation_state") not in ("sourced", "sourced_ocr_unverified"):
        return f"citation_state {meas.get('citation_state')!r} is not sourced / sourced_ocr_unverified"
    if not (isinstance(ev.get("rows_total"), int) and ev["rows_total"] >= 1):
        return "no rows were matched"
    if meas.get("v") == PASS and not (ev.get("unmatched") == [] and ev.get("rows_matched") == ev["rows_total"]
                                       and ev.get("row_count_ok") is True):
        return "PASS but not every row matched under the declared row count"
    if meas.get("v") == PASS:
        # C1-1 guards (row_scope, column ledger): a PASS record must show them clean wherever it says they ran. A record with neither key reads as before.
        if "out_of_scope_rows" in ev and ev["out_of_scope_rows"] != 0:
            return "PASS but rows lie outside the declared row_scope (they cap D1 at PARTIAL)"
        if "row_scope" in ev and not (isinstance(ev.get("out_of_scope_rows"), int) and not isinstance(ev.get("out_of_scope_rows"), bool) and ev["out_of_scope_rows"] == 0):
            return "PASS but the record declares a row_scope and does not show zero out-of-scope rows (rows outside the scope cap D1 at PARTIAL)"
        if "column_ledger" in ev and not d1m.ledger_block_is_clean(ev["column_ledger"]):
            return "PASS but the column ledger lists unclassified, unexaminable or absent columns (they cap D1 at PARTIAL)"
    return ""


def _service_state_na(declared_kind, registry_kind):
    """Earn.service_state N/A candidate, keyed on the DECLARED kind (SS N-72; N-22 row 9 AMENDED): N/A, cause `not-a-service`,
    only when the asset-declarations file declares a kind that is not `service` AND the registry (`asset_kind`) does not
    say `service` either. An undeclared/null kind, a declared service, or a registry service is never N/A: the census does
    not guess a kind, and the services' own detector is a later design (they keep reading NO_DETECTOR)."""
    if declared_kind is None or declared_kind == "service" or registry_kind == "service":
        return None
    return _na(f"declared kind {declared_kind!r} is not `service`; Earn.service_state is the service-state check "
               "(a service's rows_written cannot tell healthy-and-idle from broken)", "not-a-service")


def service_records(layer_key: str):
    """Earn.service_state's recorded input: for each active SERVICE-kind asset of the layer, what the registry recorded when the engine last ran its health probe: `service_health`
    (healthy / degraded / unhealthy / NULL), `probe_type` (health_probe->>'probe_type'), `selftest_age_hours` (now() - last_selftest_at, computed by the database: no client clock). One read-only
    SELECT, isolated from the main registry read (the columns are the engine's, migration 242): any failure returns None, which the grader reads as NO_DETECTOR, never as healthy."""
    try:
        blob = scalar(
            "SELECT coalesce(json_agg(json_build_object('asset_id',asset_id,'service_health',service_health,'probe_type',health_probe->>'probe_type',"
            "'selftest_age_hours',round((extract(epoch from (now() - last_selftest_at))/3600)::numeric, 2)) ORDER BY asset_id)::text,'[]') "
            f"FROM asset_registry WHERE layer = '{LAYERS[layer_key]['registry_layer']}' AND is_active AND NOT coalesce(dead_flag,false) AND asset_kind = 'service'")
        return {x["asset_id"]: x for x in json.loads(blob or "[]")}
    except Exception:       # noqa: BLE001 -- an unreadable service record is NO_DETECTOR in the grader (the reason text is fixed: a psql error line can carry a host)
        return None


def grade_service_state(aid: str, decl, records) -> dict:
    """Earn.service_state for a registry-`service` asset, from the probe it declares and the registry's recorded result of that probe (`service_records`). PASS only when ALL of: the declaration names a probe,
    the registry's health_probe names the same probe_type, service_health is 'healthy' and the last self-test is no older than the declared max_age_hours. 'unhealthy' reads FAIL, 'degraded' PARTIAL.
    Everything else is NO_DETECTOR and says what is missing. The recorded health is the engine's own probe verdict, read, never re-derived here."""
    nd = lambda why: dict(v=NO_DET, measured=f"NO_DETECTOR — {why}")      # noqa: E731
    sp = decl.get("service_probe") if isinstance(decl, dict) else None
    if not isinstance(sp, dict):
        return nd(f"no `service_probe` declaration for {aid}: declare the probe it is read against (probe_type, max_age_hours) in asset_declarations.json")
    ptype, max_h = sp.get("probe_type"), sp.get("max_age_hours")
    if not (isinstance(ptype, str) and isinstance(max_h, int) and not isinstance(max_h, bool) and max_h > 0):
        return nd(f"the `service_probe` declaration for {aid} is malformed (it was not validated)")
    if records is None:
        return nd(f"the registry's service-health record could not be read (declared probe {ptype})")
    rec = records.get(aid)
    if rec is None:
        return nd(f"the registry holds no active service-kind row for {aid} (declared probe {ptype})")
    if rec.get("probe_type") != ptype:
        return nd(f"declared probe {ptype!r} but the registry's health_probe names {rec.get('probe_type')!r}: no registered probe of that type to read")
    health, age = rec.get("service_health"), rec.get("selftest_age_hours")
    base = f"probe {ptype}: registry service_health={health!r}, last self-test {age}h ago (declared max {max_h}h)"
    if health == "unhealthy":
        return dict(v=FAIL, measured=f"the probe recorded unhealthy — {base}")
    if health == "degraded":
        return dict(v=PARTIAL, measured=f"the probe recorded degraded — {base}")
    if health != "healthy":
        return nd(f"the probe has no recorded healthy/unhealthy result ({base}): never probed")
    if not isinstance(age, (int, float)) or isinstance(age, bool) or age < 0:
        return nd(f"healthy but the last self-test time is missing or in the future ({base}): freshness cannot be told")
    if age > max_h:
        return nd(f"healthy but stale ({base}): re-run the probe")
    return dict(v=PASS, measured=f"healthy and fresh — {base}")


def _measure_target(r: dict, owners, declared_kind) -> dict:
    """Build.target (T4:274: "a `target_table` set, or service / multi-table declared explicitly").

    E6 item (g): an asset with NO target_table that BOTH the registry (`asset_kind`) and the asset-declarations file
    declare `service` reads PASS BY DECLARATION. Nothing measures that verdict — no code path tests the declaration,
    so this branch cannot read false (CLAUDE.md N.8); the text and the record's `basis` say so. Where the file and
    the registry disagree the registry fact decides and the reading is the one it always was (cause-keyed N/A);
    `multi-table` is not a kind, it is the measured count_sql table set (`_grade_target_less`)."""
    if r["target_table"]:
        return dict(v=PASS, measured=f"target_table={r['target_table']}")
    if r["asset_kind"] == "service" or not r["has_writer"]:
        if r["asset_kind"] == "service" and declared_kind == "service":
            return dict(v=PASS, basis="declaration",
                        measured="PASS by declaration (T4:274): no target_table, and both the registry (asset_kind='service') and "
                                 "the asset-declarations file (kind: service) declare a service; no measurement stands behind "
                                 "this verdict — nothing tests the declaration, so this branch has no fail path (CLAUDE.md N.8)")
        return _na(f"no target_table; asset_kind='{r['asset_kind']}', has_writer={r['has_writer']}",
                   "service-no-target-table" if r["asset_kind"] == "service" else "no-writer-no-target-table")
    try:
        # R242 (W2-2 OS-B): the registry-wide read happens only when absent (the caller caches it).
        return _grade_target_less(r, owners)
    except Unknown as exc:
        return dict(v=ERRORED, measured=f"check errored: {exc}")


def _grade_target_less(r: dict, owners) -> dict:
    """R53 (T1 plant build_target_null; W2-1 OS-1/#18): Build.target for a writer-backed data/artifact
    asset with NO target_table. The FAIL branch used to be dead — `asset_kind` is NOT NULL
    CHECK(data|service|artifact), so "no target_table" always read the closable N/A.

    The engine never clears or counts by target_table: its produced-table rule is target_table ∪ the
    tables its count_sql names (`dag_edge_guard._producer_tables`), and target_table otherwise feeds
    cowriter-peer detection. So, from the count_sql (`owners()` is called only when needed):
      ≥2 tables                      → PASS: a multi-table asset, its produced tables declared
                                        (bg_prashna_rules: 5 tables);
      1 table, another asset's target → PASS: a partition writer into that asset's table
                                        (ga_strength, ga_structural → chart_facts, 7 declaring assets);
      1 table nobody declares         → FAIL: the declaration is missing (the plant's exact shape);
      no table                        → FAIL: nothing to aim at."""
    ct = _count_tables(r["count_sql"])
    if len(ct) >= 2:
        return dict(v=PASS, measured=f"no single target_table: a multi-table asset whose count_sql declares the "
                                     f"{len(ct)} tables it produces ({', '.join(ct)}) — the engine's produced-table rule")
    if len(ct) == 1:
        own = [a for a in owners().get(ct[0], []) if a != r["asset_id"]]
        if own:
            return dict(v=PASS, measured=f"no target_table: writes a partition of {ct[0]}, the declared target of "
                                         f"{', '.join(own)} (count_sql counts its share)")
        return dict(v=FAIL, measured=f"target_table not declared: count_sql counts {ct[0]}, which no active asset "
                                     "declares as its target — the declaration is missing")
    return dict(v=FAIL, measured="has a writer and neither a target_table nor a count_sql naming a table — the "
                                 "orchestrator's clear/count steps have nothing to aim at")


def _scope_record(by: dict, chart_id: str):
    """A dependency's build record at the census's chart scope: its row for `chart_id`, else its global (chart_id NULL) row, else None."""
    return by[chart_id] if chart_id in by else by[""] if "" in by else None


def _upstream_closure(graph: dict, start: str) -> list[str]:
    """The declared upstream closure of `start` (every asset it transitively depends on), nearest first, `start` excluded."""
    out, seen, queue = [], {start}, list(graph.get(start, []))
    while queue:
        u = queue.pop(0)
        if u in seen:
            continue
        seen.add(u)
        out.append(u)
        queue.extend(graph.get(u, []))
    return out


def stale_dependency_causes(stale: list[str], graph: dict | None, records: dict | None, chart_id: str, why_unread: str | None = None) -> dict[str, str]:
    """For each dependency whose record reads `stale` at the census's chart scope, WHY: the engine marks a completed build stale when something
    upstream of it completes a build afterwards, so the candidates are the assets in the dependency's declared upstream closure whose build record at
    the same scope is LATER than its own. `records` is asset -> {chart -> record} for the dependencies and their closure. Names the rebuilt
    upstream(s) with their build dates, or says plainly that none is on record (the mark then did not come from a recorded upstream rebuild, e.g. it
    was set by a registry change or by a build on another chart): never a guess. Pure."""
    out: dict[str, str] = {}
    for d in stale:
        if graph is None or records is None:
            out[d] = f"cause not determinable: {why_unread or 'the dependency graph or the upstream build records were not read'}"
            continue
        rec = _scope_record(records.get(d, {}), chart_id)
        built = _epoch(rec.get("built_epoch", "")) if rec else float("-inf")
        if built == float("-inf"):
            out[d] = "cause not determinable: its own build time is not recorded"
            continue
        later = []
        for u in _upstream_closure(graph, d):
            ur = _scope_record(records.get(u, {}), chart_id)
            if ur and _epoch(ur.get("built_epoch", "")) > built:
                later.append(f"{u} (built {ur.get('last_built') or 'undated'}, state {ur.get('state') or 'none'})")
        if later:
            shown = ", ".join(later[:5]) + (f", +{len(later) - 5} more" if len(later) > 5 else "")
            out[d] = f"stale because upstream built after it ({rec.get('last_built') or 'undated'}): {shown}"
        else:
            out[d] = (f"no asset in its upstream closure has a build record later than its own ({rec.get('last_built') or 'undated'}) at this "
                      "scope: the stale mark did not come from a recorded upstream rebuild (a registry change or a build on another chart can set it)")
    return out


def _grade_dep_liveness(deps: list[str], deprec: dict, chart_id: str, causes: dict | None = None, kinds: dict | None = None) -> dict:
    """R45 (L2 handverify; W2-1_REVIEW C2): Build.dep_liveness at the census's CHART SCOPE.

    The claim is "every declared dependency is live for the chart this census measures". It used to
    read a chart-agnostic set — an asset_id `lit` on ANY chart counted — so 10 assets read PASS while a
    dependency was `stale` on the canonical chart and lit only on 1c826d5a. A dependency's record is
    its row for `chart_id`, else its global (chart_id NULL) row — no asset carries both (live,
    2026-09-27). Per dependency: `lit` → live; `stale` (a completed build whose upstream has since
    moved) → stale; no record at this scope, or any other state (error, dormant, incomplete,
    building) → not live; an R44-ambiguous record → undetermined. Verdict: any not live → FAIL;
    else any undetermined → ERRORED (never closable); else any stale → PARTIAL; else PASS, naming
    the scope measured.

    The verdict logic is unchanged by the cause text: `causes` (dep -> why, from `stale_dependency_causes`) only says, for each STALE dependency,
    which upstream was rebuilt after it; every not-live dependency carries its state, scope and last build date.

    SS (service_ok): the engine's dependency gate (asset_runner.deps_unsatisfied) accepts a dependency in state `service_ok` when its registry
    asset_kind is `service` (a service has no data-freshness receipt; its readiness IS a green probe). The census reads that rule: `kinds` (dep ->
    asset_kind, from the registry) makes a `service_ok` record of a `service` dependency live. A `service_ok` record of any other kind (the engine would
    then also need a `fresh` receipt, which this check does not read), or of a dependency whose kind was not read, stays not live and says why."""
    short = chart_id[:8]
    causes = causes or {}
    live, stale, dead, undet = [], [], [], []
    for d in deps:
        by = deprec.get(d, {})
        rec, where = ((by[chart_id], f"chart {short}") if chart_id in by
                      else (by[""], "global") if "" in by else (None, ""))
        if rec is None:
            others = sorted({x.get("state", "?") for c, x in by.items() if c})
            dead.append(f"{d} (no build record on chart {short} or global"
                        + (f"; exists only on {len(by)} other chart(s), state(s) {others})" if by else ")"))
        elif rec.get("ambiguous"):
            undet.append(f"{d} ({where}: {rec.get('n_rows')} tied rows)")
        elif rec.get("state") == "lit":
            live.append(d)
        elif rec.get("state") == "service_ok" and (kinds or {}).get(d) == "service":
            live.append(d)
        elif rec.get("state") == "stale":
            stale.append(f"{d} (stale, {where}; last built {rec.get('last_built') or 'undated'}"
                         + (f"; {causes[d]}" if d in causes else "") + ")")
        else:
            note = ("" if rec.get("state") != "service_ok" else
                    f" — service_ok is live only for a registry asset_kind 'service' (the engine's rule); this dependency's kind is "
                    f"{(kinds or {}).get(d) or 'not read'}, and the engine would also need a fresh receipt, which is not read here")
            dead.append(f"{d} ({rec.get('state') or 'no state'}, {where}; last built {rec.get('last_built') or 'undated'}{note})")
    head = f"{len(live)}/{len(deps)} declared dependencies lit at chart {short} (or global)"
    if dead:
        return dict(v=FAIL, measured=f"{head}; not live: {dead}" + (f"; stale: {stale}" if stale else "")
                                     + " — a DEP-ASSERT trap if no writer can light them")
    if undet:
        return dict(v=ERRORED, measured=f"check errored: {head}; undetermined (R44 tie): {undet}")
    if stale:
        return dict(v=PARTIAL, measured=f"{head}; stale: {stale} — built, but an upstream has moved since")
    return dict(v=PASS, measured=head)


def _grade_count_floor(r: dict, live: int | None, error: str | None, ctables: list[str]) -> dict | None:
    """Count.floor for one asset: the live count against the registry's declared `target_floor`.
    Returns None only when the criterion does not apply (see the branches).

    R56 (T1 differential): on the 57 L1/L2/L4/L5 assets whose count_sql is parameterised (`$1`) or
    multi-table, Count.floor was SILENTLY ABSENT — `live is None` (an unbound `$1`) skipped the
    criterion without a word, while the differential found real breaches it never reported
    (ga_vargas 0 < 22 092; bo_laksana 7 409 < 60 000; ph_sankrama 630 < 2 510, sandbox). With R231
    binding the chart the count is measured; and when a count_sql exists but could not be measured
    the criterion now reads ERRORED with the reason — never absent. A multi-table total is compared
    as a total (the engine compares its writer's multi-table rows_written with the same floor)."""
    floor = r["target_floor"]
    if floor is None:
        return None                     # nothing declared: there is no floor claim to measure
    # R48 (L3 handverify: 20/23 L3 assets declare target_floor, yet Count.floor was absent from the
    # whole L3 census): every asset that DECLARES a floor gets a verdict, whatever else is missing.
    floor = floor.strip()
    if floor == "0":
        # A floor of zero cannot be breached — `live >= 0` is true of every count, so PASS would be
        # a detector that cannot read false (§N.8). The registry's declaration is what applies.
        return _na("target_floor=0: the registry declares zero rows complete — "
                   f"there is no floor to breach (live={'unmeasured' if live is None else live})", "target-floor-zero")
    if not floor.isdigit():
        return dict(v=NO_DET, measured=f"NO_DETECTOR — target_floor {floor!r} is not a whole number of rows")
    if not r["count_sql"].strip():
        return dict(v=NO_DET, measured=f"NO_DETECTOR — target_floor={floor} is declared but no count_sql is "
                                       "registered to measure it")
    if error is not None or live is None:
        return dict(v=ERRORED, measured=f"check errored: {error or 'count_sql produced no value'} — "
                                        f"floor={floor} not measured")
    if not ctables:
        return dict(v=NO_DET, measured=f"NO_DETECTOR — count_sql reads no table (a constant {live}); "
                                       f"floor={floor} cannot be measured against it")
    d = live - int(floor)
    what = "count_sql total" if (len(ctables) > 1 or r["target_table"] not in ctables) else "live"
    return dict(v=(FAIL if d < 0 else PASS), measured=f"{what}={live}, floor={floor}, delta={d:+d}")


# The closed verdict set a registered carriage detector may return (the ledgers' own vocabulary,
# asset_elevation_tracker.VERDICTS). NOT_GENERIC / ERRORED are census-internal and never a detector's.
DETECTOR_VERDICTS = (PASS, FAIL, PARTIAL, NO_DET, NA)


def _run_carriage_detector(aid: str) -> dict:
    """P3/R57 item (d): a per-asset carriage detector registered at <CTRL>/detectors/<asset>_D<1|2|3>.py
    IS the detector — run it and adopt its verdict instead of the blanket NO_DETECTOR.

    META-CHECK SEMANTICS, to rework when the D detectors land: the loop below takes the FIRST of D1, D2, D3 found for
    the asset and returns one verdict for the whole gate — that was the retired `Carr.detector` reading. Per-check
    detectors must feed Carr.D1, Carr.D2 and Carr.D3 individually (one script, one check, one verdict each).

    UNWIRED since REGISTRY_REVISION 8 (E6 item i): its only caller fed the retired `Carr.detector` criterion, and
    measure() no longer calls it — a detector file on disk changes no verdict, by design (a per-asset script named
    `_D1` belongs to the `Carr.D1` check, not to a whole-gate meta-check; binding it there is the detector work
    that lifts D1-D3 off detector NONE, not this retirement). Kept, with its F8 hardening and tests, for that work.

    F8 (A_REVIEW.md): the port adopted the last stdout line's `verdict` without checking the
    process's return code or the verdict's vocabulary, so a detector that crashed AFTER printing
    `{"verdict": "PASS", …}` — or printed a verdict outside the closed set — was adopted as its
    verdict, and a PASS closes a gap. A non-zero exit, an unparseable last line, or a verdict outside
    DETECTOR_VERDICTS now reads NO_DETECTOR with the exact reason: a detector that did not complete
    cleanly has measured nothing."""
    det_dir = CTRL / "detectors"
    det = None
    if det_dir.is_dir():
        for n in (1, 2, 3):
            p = det_dir / f"{aid}_D{n}.py"
            if p.exists():
                det = p
                break
    if det is None:
        return dict(v=NO_DET, measured="no D1/D2/D3 detector exists for this asset; which check applies is per-asset semantics")
    try:
        pr = subprocess.run([sys.executable, str(det)], capture_output=True, text=True,
                            env=os.environ, timeout=120)
    except Exception as exc:  # a registered detector that cannot run is not a pass
        return dict(v=NO_DET, measured=f"{det.name} failed to run: {exc}")
    if pr.returncode != 0:
        tail = (pr.stderr.strip().splitlines() or ["no stderr"])[-1]
        return dict(v=NO_DET, measured=f"{det.name} exited {pr.returncode} ({tail}) — output of a failed "
                                       "detector is not a verdict")
    try:
        out = json.loads(pr.stdout.strip().splitlines()[-1])
        verdict, measured = out["verdict"], out["measured"]
    except Exception as exc:
        return dict(v=NO_DET, measured=f"{det.name} produced no parseable verdict line: {type(exc).__name__}: {exc}")
    if verdict not in DETECTOR_VERDICTS:
        return dict(v=NO_DET, measured=f"{det.name} returned verdict {verdict!r}, outside the closed set "
                                       f"{list(DETECTOR_VERDICTS)}")
    return dict(v=verdict, measured=f"{det.name}: {measured}")


# ─────────────────────────── the census ───────────────────────────

def _layer_read(name: str, fn, *args):
    """F12 (A_REVIEW.md): name the layer-wide read that failed, so the UNKNOWN says which one."""
    try:
        return fn(*args)
    except Unknown as exc:
        raise Unknown(f"layer-wide read '{name}' failed: {exc}") from exc


def _table_scope(t, r, own, shared):
    """(where-tail, scope label) the rows of the owned table `t` are counted under, from the asset's registry count_sql; None when the rows cannot be scoped to this
    asset (a shared table whose count_sql is not a plain count of it)."""
    tail = _count_scope_tail(r["count_sql"], t)
    if tail is not None:
        # chart-scoped only when the predicate BINDS chart_id to the census chart (`chart_id = $1`, no OR); a
        # parseable count_sql without it on a table that carries chart_id counts every chart: an upper bound
        if _chart_pinned(tail):
            scope = "chart-scoped by count_sql"
        elif "chart_id" in (own[t][0] or ()):
            scope = UPPER_BOUND
        else:
            scope = "count_sql predicate (not chart-scoped)"
    elif t in shared:
        return None
    else:
        tail = ""
        scope = (UPPER_BOUND if "chart_id" in (own[t][0] or ()) else "whole-table (table has no chart_id column)")
    return tail, scope


def _group_counts(groups, r, own, shared) -> dict:
    """entry -> dict(checkable, blank, scope) for entries grouped by the owned table that holds them ({table: [entry]}); an entry whose table cannot be scoped is
    absent (unknown). Raises Unknown on a failed read."""
    counts = {}
    for t, es in groups.items():
        sc = _table_scope(t, r, own, shared)
        if sc is None:
            continue
        got = prose_row_counts(t, es, _bind_chart(sc[0], CHART_ID), own[t][1])
        for e in es:
            counts[e] = dict(got[e], scope=sc[1])
    return counts


def _measure_null_convention(decl, nc, r, own, cat, shared, base) -> dict:
    """The Null.schema_default / Null.blank_rows records of an asset that DECLARES `null_convention` (S1, pin 13). `base`: what prose_checks produced. The two
    checks also run over the convention's nullable columns (counted in the DECLARED table); the detector verifies the convention; `earn_null_lift` decides. When
    nothing is lifted and nothing fails, the base records come back exactly as they were, annotated with why the cap stays."""
    sd0, br0 = base["Null.schema_default"], base["Null.blank_rows"]
    table = nc["table"]
    pf = list(decl.get("prose_fields") or [])
    conv_cols = [n["column"] for n in nc["nullable"]]
    entries = list(dict.fromkeys(pf + conv_cols))
    scope = None
    try:
        sc = _table_scope(table, r, own, shared) if table in own else None
        # the tail still holds the `$1` chart parameter: bind it (as _group_counts does) before the read, or every chart-scoped asset would read ERRORED
        scope = None if sc is None else (_bind_chart(sc[0], CHART_ID), sc[1])
        conv = null_convention_check(nc, own, cat.get("exists") or (), scope)
    except Unknown as exc:                                  # an unbindable scope (a phantom chart id ...) degrades only this check
        conv = dict(v=ERRORED, declared=True, measured=f"check errored: {exc}")
    # a declared prose field that lives outside the declared table is not covered by the convention detector (S3's placeholder definition is applied to the declared
    # table only): the lift needs full coverage, so such an asset stays capped (a FAIL still flips the cell)
    table_cols = set(own[table][0] or ()) if table in own and isinstance(own[table][0], (list, tuple, set)) else set()
    uncovered = [e for e in pf if parse_prose_field(e)[0] not in table_cols]
    counts = None
    if table in own and table in (cat.get("exists") or ()) and entries:
        groups: dict = {}
        for e in entries:
            col = parse_prose_field(e)[0]
            if col in conv_cols:
                groups.setdefault(table, []).append(e)
            else:
                held = _holders(col, own)
                if held and held[0] in (cat.get("exists") or ()):
                    groups.setdefault(held[0], []).append(e)
        try:
            counts = {e: None for e in entries}
            counts.update(_group_counts(groups, r, own, shared))
        except Unknown:
            counts = None
    try:
        sd = grade_null_schema_default_tables(entries, own) if entries else dict(v=NO_DET, measured="NO_DETECTOR — the convention declares no nullable column")
        br = grade_null_blank_rows(entries, counts)
    except (Unknown, DeclarationsError):
        return {c: dict(base[c], null_convention=_null_annotation(conv)) for c in NULL_CHECKS}
    got = earn_null_lift(entries, sd, br, conv, nc)
    if got and not (uncovered and all(v.get("v") == PASS for v in got.values())):
        return got
    note = _null_annotation(conv)
    if uncovered:
        note["uncovered_prose_fields"] = uncovered
        note["measured"] = f"{note.get('measured')} [not lifted: declared prose field(s) {', '.join(uncovered)} are outside the declared table {table}]"
    return {"Null.schema_default": dict(sd0, null_convention=dict(note)), "Null.blank_rows": dict(br0, null_convention=dict(note))}


# ───────────── N-189 (SS ruling): the FORWARDED L1 LEAVES detector, a REAL data comparison and not a closed-values declaration ─────────────
# bo_laksana forwards open-ended L1 values into bodha_msr_signals: `_build_signal_row` copies `chart_facts.fact_value_text` / `fact_value_num` / `fact_key` and EVERY non-null top-level key of
# `fact_value_jsonb` (minus the two constituent keys) into `configuration_jsonb`, adds `fact_subject` / `l1_formula_id`, passes `citation_ref` / `citation_human` through and writes
# `signal_type_id` = category:key; the signal cites its L1 fact in `constituent_facts_array` (the fact_id carrier, CLAUDE.md N.5: those ids MUST resolve to chart_facts.fact_id).
# `_load_vichara_divergence_signals` forwards `chart_vichara` {subject, domain, value_text} the same way, and `_build_navamsha_cross_check_signals` forwards the D1 dignity text of a cited
# chart_facts row and the D9 dignity text of a chart_divisionals row. bo_laksana writes exactly three verification methods: L1_fact_projection, chart_vichara_projection and
# L1_divisional_cross_check (its bhavat_bhavam_amplifier class is deliberately unreachable, DP-SD-015); every row of the asset's scope MUST fall in a method measured here, else the cell reads PARTIAL.
# The static writer scan (E5.7) can read none of it: a forwarded value is `x or ''` to it (a literal fallback) and the row dicts are built by dynamic construction (an unresolved path), so the two
# Null cells of such an asset stay PARTIAL however clean the data is. N.5 says an L2 signal never restates an L1 value as its own truth: it REFERENCES the fact_id and INHERITS the value.
# This detector measures exactly that, on the data of the MEASURED chart: ONE set-based comparison of the forwarded leaves against the cited L1 fact at that fact_id.
#
# THE DECLARATION (`forwarded_leaves`) is only the SCOPE of the check, like `produced_tables`: the table, the carrier column, the row forms (which rows are projections of an L1 row, by a declared
# `rows` {column, equals}) and the leaf column of each, the writer code the covered scan findings may sit in (`covered_scope`) and the number of them pinned after review (`pin`), the prose
# entries the forwarding feeds (`covers`), a real why and a checkable evidence pointer. The VERDICT never comes from it: it comes from the comparison. Rules (one place, tested):
#   EQUAL  -> PASS   every compared leaf equals the cited L1 value: text exactly; fact_value_num as float8 (the writer's float()); jsonb by jsonb `=`; JSON null and an absent key both read NULL;
#                    NULL = NULL, NULL vs a value (an empty string included) is DIFFERENT (SS N-194). The EXPECTED leaf is normalised exactly as the writer does (`_strip_random_row_ids`): a value that is a
#                    whole-string uuid-v4 which is not a fact_id of the chart is dropped, in a dict value or a list element, recursively (an emptied container stays), the strip applying to the
#                    copied leaves and NOT to the fact_subject / l1_formula_id the writer adds afterwards. Nothing is skipped by a text pattern: a forged value beside a uuid is a drift.
#   OWN FACT         the forwarded leaves are compared with the signal's OWN fact: the cited fact whose fact_key the signal forwards, in the signal's ayanamsha (or INVARIANT), that is the FIRST cited id
#                    (the writer puts the own id first) or an L1 fact that itself lists constituents (then the writer leaves the own id where the list had it). Leaves that equal a different cited fact
#                    are a drift.
#   KEYS             a signal key that is not a leaf of the cited fact is a drift, except graha / house / target_house, which the writer resolves (from fact_subject, fact_key, the L1 value) and which are
#                    NOT compared: said so in the cell text.
#   DIFFER -> FAIL   (a halt-worthy drift): the cell text names the first few (signal id, fact_id, leaf, forwarded value, L1 value), a bounded sample, never a total.
#   a cited fact_id that is NOT in chart_facts of THIS chart (dangling, or another chart's) is a FAIL; a projection row whose cited facts carry no fact_key equal to the forwarded one is a FAIL.
#   a composite flood roll-up (aggregated, fact_key aggregate_*) is not compared one to one, and is not exempt by its own say-so: its member_count and fact_value_num must equal the number of cited
#   members, which must all resolve and carry the signal's category, else FAIL; it citing none is PARTIAL. The exempted rows are counted in the cell text.
#   a projection row with NO cited fact_id stays PARTIAL with the named cause. A leaf nested deeper than the strip depth, a row of a verification method no declared form measures: PARTIAL, named.
#   an unreadable / timed-out read is NO_DETECTOR (timeout) or ERRORED (any other failure), never PASS; zero rows of the measured chart (or a scope that holds no rows, `_scope_block`) is
#   unmeasured, never PASS; a declared form with no row in the measured chart is PARTIAL (its forwarding is unmeasured).
# THE LIFT (`_apply_forwarded_leaves`, `forwarded_leaves_problem_of`): both Null records read PASS only when the data graders are clean (the `clean` PARTIAL), the detector reads PASS and every finding
# of the static writer scan is of the two classes the scan cannot classify AND sits in the declared covered writer code (located by the AST spans of the declared functions / constants): an EMPTY-STRING
# literal fallback on a covered entry (a forwarded value that is absent), or the scan's own "dynamic row construction could also supply the key" caveat on a covered entry. The number of each is
# pinned by the declaration after review: a new finding, even inside the covered code, breaks the pin and keeps the cap. Any other finding keeps the cap.
DECL_N189_KEYS = ("forwarded_leaves",)
FORWARDED_LEAVES_FIELDS = ("table", "cite_column", "forms", "covered_scope", "pin", "covers", "why", "evidence")
FORWARDED_FORM_FIELDS = ("form", "rows", "leaf_column")
FORWARDED_ROWS_FIELDS = ("column", "equals")
FORWARDED_SCOPE_FIELDS = ("file", "functions", "constants")
FORWARDED_PIN_FIELDS = ("empty_fallbacks", "dynamic_row_caveats")
FORWARDED_FORMS = ("chart_facts_row", "chart_vichara_row", "chart_divisional_row")
FORWARDED_FORM_COLUMNS = {"chart_facts_row": ("signal_id", "ayanamsha_id", "signal_type_id", "citation_ref", "citation_human"),
                          "chart_vichara_row": ("signal_id", "ayanamsha_id", "citation_ref"), "chart_divisional_row": ("signal_id", "ayanamsha_id", "citation_ref")}
FORWARDED_SAMPLE_LIMIT = 3          # offenders named per category (LIMIT, no ORDER BY on the main read: an ORDER BY would force the scan the existence read avoids)
FORWARDED_COUNT_CAP = 250_000       # a population count stops here: beyond it the figure is "at least"
FORWARDED_STRIP_DEPTH = 4           # container levels the writer's recursive strip is mirrored to in SQL (a leaf nested deeper is named, never compared)
_FL_UUID_V4 = "[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}"
_FL_SKIP_KEYS = "('constituent_facts_array', 'constituent_fact_ids')"
_FL_RESOLVED_KEYS = "('graha', 'house', 'target_house')"       # signal keys the writer resolves itself (not forwarded copies)
_FL_FALSY = "('null'::jsonb, 'false'::jsonb, '0'::jsonb, '" + chr(34) * 2 + "'::jsonb, '[]'::jsonb, '{}'::jsonb)"       # the JSON values Python treats as falsy (the writer's `if not fvj.get("aggregated")`)
FORWARDED_OWN_FACT_RULE = ("own fact = the cited fact whose fact_key the signal forwards (signal ayanamsha or INVARIANT) that is the first cited id, or that itself lists constituents; "
                           "leaves equal to another cited fact are a drift")
_FL_NOT_COMPARED = {
    "chart_facts_row": "configuration_jsonb keys graha / house / target_house when the L1 fact does not carry them (the writer resolves them from fact_subject, fact_key or the L1 value: re-derivations, not copies), and every column that is not a forwarded leaf (salience, valence, tiers, the texts built from the leaves)",
    "chart_vichara_row": "the valence and salience columns of a divergence signal (derived from value_num and the class priors, not copies)",
    "chart_divisional_row": "d1_tier / d9_tier / classification / neecha_bhanga of the divisional cross-check (derived by the writer's tier map and L1 verdict lookups, not copies), the graha-name to D1 fact_subject mapping, and the salience columns",
}


def forwarded_leaves_problem(entry):
    """None when `entry` has no `forwarded_leaves` or a sound one; else why it is refused. Sound: {table, cite_column, forms, covered_scope, pin, covers, why, evidence}: `table` / `cite_column`
    identifiers; `forms` 1..3 distinct {form, rows {column, equals}, leaf_column} with `form` one of FORWARDED_FORMS and ONE `rows.column` for all; `covered_scope` {file, functions, constants}: the writer
    code a covered scan finding may sit in; `pin` {empty_fallbacks, dynamic_row_caveats}: how many covered findings the reviewed writer has; `covers` exactly the asset's declared prose_fields; a real
    `why`; `evidence` a repo-relative `path:LINE`. The declaration is the scope of the check, never its verdict."""
    if not isinstance(entry, dict) or entry.get("forwarded_leaves") is None:
        return None
    fl = entry["forwarded_leaves"]
    if not isinstance(fl, dict) or set(fl) != set(FORWARDED_LEAVES_FIELDS):
        return "forwarded_leaves must be an object with exactly the fields " + str(list(FORWARDED_LEAVES_FIELDS))
    for k in ("table", "cite_column"):
        if not (isinstance(fl[k], str) and _D1_SQL_IDENT.fullmatch(fl[k])):
            return k + " must be a plain identifier"
    forms = fl["forms"]
    if not (isinstance(forms, list) and 1 <= len(forms) <= len(FORWARDED_FORMS)):
        return "forms must be a list of 1 to " + str(len(FORWARDED_FORMS)) + " objects"
    seen, cols = set(), set()
    for i, d in enumerate(forms):
        w = "forms[" + str(i) + "]"
        if not isinstance(d, dict) or set(d) != set(FORWARDED_FORM_FIELDS):
            return w + " must be an object with exactly the fields " + str(list(FORWARDED_FORM_FIELDS))
        if d["form"] not in FORWARDED_FORMS:
            return w + ".form must be one of " + str(list(FORWARDED_FORMS))
        if d["form"] in seen:
            return w + ".form " + repr(d["form"]) + " is declared twice"
        seen.add(d["form"])
        rw = d["rows"]
        if not (isinstance(rw, dict) and set(rw) == set(FORWARDED_ROWS_FIELDS) and isinstance(rw["column"], str) and _D1_SQL_IDENT.fullmatch(rw["column"])
                and isinstance(rw["equals"], str) and rw["equals"].strip() and rw["equals"] == rw["equals"].strip() and len(rw["equals"]) <= 80 and "\x00" not in rw["equals"]):
            return w + ".rows must be {column: <identifier>, equals: <one plain non-empty string>}"
        cols.add(rw["column"])
        if not (isinstance(d["leaf_column"], str) and _D1_SQL_IDENT.fullmatch(d["leaf_column"])):
            return w + ".leaf_column must be a plain identifier"
    if len(cols) != 1:
        return "every form's rows.column must be the same column (the guard that no row of the asset is unmeasured reads that one column)"
    cs = fl["covered_scope"]
    if not (isinstance(cs, dict) and set(cs) == set(FORWARDED_SCOPE_FIELDS) and isinstance(cs["file"], str) and re.fullmatch(r"[A-Za-z0-9_./-]+\.py", cs["file"])
            and isinstance(cs["functions"], list) and 1 <= len(cs["functions"]) <= 8 and len(set(cs["functions"])) == len(cs["functions"])
            and all(isinstance(x, str) and _D1_SQL_IDENT.fullmatch(x) for x in cs["functions"])
            and isinstance(cs["constants"], list) and len(cs["constants"]) <= 4 and len(set(cs["constants"])) == len(cs["constants"])
            and all(isinstance(x, str) and _D1_SQL_IDENT.fullmatch(x) for x in cs["constants"])):
        return "covered_scope must be {file: <writer file as the scan names it>, functions: [1..8 distinct names], constants: [0..4 distinct names]}"
    pn = fl["pin"]
    if not (isinstance(pn, dict) and set(pn) == set(FORWARDED_PIN_FIELDS) and all(isinstance(pn[k], int) and not isinstance(pn[k], bool) and 0 <= pn[k] <= 1000 for k in pn)):
        return "pin must be {empty_fallbacks: <int>, dynamic_row_caveats: <int>}"
    cv = fl["covers"]
    declared = entry.get("prose_fields")
    if not (isinstance(cv, list) and cv and len(set(cv)) == len(cv) and isinstance(declared, list) and sorted(cv) == sorted(declared)):
        return "covers must be exactly the asset's declared prose_fields (the lift it earns is the whole Null cell)"
    bad = _s3_text_problem(fl["why"], min_chars=30, min_words=5)
    if bad:
        return "why " + bad
    bad = _s3_evidence_problem(fl["evidence"], allow_unverified=False)
    if bad:
        return "evidence " + repr(fl["evidence"]) + " " + bad
    if not re.search(r":[0-9]+$", str(fl["evidence"])):
        return "evidence " + repr(fl["evidence"]) + " must name a line (repo-relative file:LINE)"
    return None


def validate_forwarded_leaves_declaration(where: str, e: dict) -> None:
    bad = forwarded_leaves_problem(e)
    if bad:
        raise DeclarationsError(where + ".forwarded_leaves: " + bad)


# ── the SQL (pure builders; every identifier is regex-validated, every value a quoted literal) ──

def _fl_chart(chart_id: str) -> str:
    """The measured chart id, validated like every chart binding (a uuid, never the dead phantom)."""
    if str(chart_id).startswith(_PHANTOM_CHART_PREFIX):
        raise Unknown("refusing chart scope " + str(chart_id) + ": the 362f9f17-… chart id is a dead phantom")
    if not re.fullmatch(r"[0-9a-fA-F-]{36}", str(chart_id)):
        raise Unknown("chart scope " + repr(chart_id) + " is not a uuid")
    return str(chart_id)


def _fl_scoped(table: str, chart: str) -> str:
    """The signal table through the engine's read scope for the measured chart (`read_scopes` / `set_read_scope`: the chart, and the asset's own rows on a shared table) AND an explicit
    `chart_id = <measured chart>` of its own, so the reading never rests on the installed scope alone."""
    if not _D1_SQL_IDENT.fullmatch(table or ""):
        raise ValueError("forwarded_leaves needs a table identifier")
    parts = []
    p = _scope_pred(table)
    if p:
        parts.append("(" + p + ")")
    parts.append('"chart_id" = ' + _vocab_lit(_fl_chart(chart)))
    return "(SELECT * FROM " + table + " WHERE " + " AND ".join(parts) + ")"


def _fl_isuuid(v: str, chart: str) -> str:
    """SQL: the jsonb expression `v` is the writer's `_is_random_row_id`: a WHOLE-STRING uuid-v4 (a trailing newline allowed, as Python's `$`) that is not a chart_facts.fact_id of the chart."""
    txt = "(" + v + " #>> '{}')"
    return ("(jsonb_typeof(" + v + ") = 'string' AND CASE WHEN " + txt + " ~* '^" + _FL_UUID_V4 + "\\n?$' THEN NOT EXISTS (SELECT 1 FROM chart_facts g WHERE g.chart_id = '" + chart
            + "' AND g.fact_id::text = " + txt + ") ELSE false END)")


def _fl_strip(x: str, chart: str, depth: int, n: int = 0) -> str:
    """SQL mirror of `_strip_random_row_ids(x)`: dict entries and list elements that are a random row id are dropped, recursively; an emptied container stays. `depth` container levels."""
    if depth <= 0:
        return x
    o, a = "o" + str(n), "a" + str(n)
    io = _fl_strip(o + ".v", chart, depth - 1, n + 1)
    ia = _fl_strip(a + ".v", chart, depth - 1, n + 1)
    return ("(CASE jsonb_typeof(" + x + ") WHEN 'object' THEN coalesce((SELECT jsonb_object_agg(" + o + ".k, " + io + ") FROM jsonb_each(" + x + ") AS " + o + "(k, v) WHERE NOT "
            + _fl_isuuid(o + ".v", chart) + "), '{}'::jsonb) WHEN 'array' THEN coalesce((SELECT jsonb_agg(" + ia + " ORDER BY " + a + ".n) FROM jsonb_array_elements(" + x
            + ") WITH ORDINALITY AS " + a + "(v, n) WHERE NOT " + _fl_isuuid(a + ".v", chart) + "), '[]'::jsonb) ELSE " + x + " END)")


def _fl_expected(f: str, chart: str) -> str:
    """A FROM fragment (CROSS JOIN LATERAL ...) exposing `x.e`: the object of leaves the writer forwards from the L1 fact row `f` (chart_facts), in the writer's own order (later wins): fact_key /
    fact_value_text / fact_value_num (float8: the writer's float()), then every non-null top-level key of fact_value_jsonb except the two constituent keys, then the writer's strip of random row ids,
    then fact_subject / l1_formula_id unless the L1 value is itself an aggregate (Python truthiness). `x.deep`: the copied leaves nest deeper than the mirrored strip."""
    j = f + ".fact_value_jsonb::jsonb"
    e0 = ("jsonb_build_object('fact_key', " + f + ".fact_key, 'fact_value_text', " + f + ".fact_value_text, 'fact_value_num', " + f + ".fact_value_num::float8) "
          "|| coalesce(CASE WHEN jsonb_typeof(" + j + ") = 'object' THEN (SELECT jsonb_object_agg(z.k, z.v) FROM jsonb_each(" + j + ") AS z(k, v) "
          "WHERE z.k NOT IN " + _FL_SKIP_KEYS + " AND jsonb_typeof(z.v) <> 'null') END, '{}'::jsonb)")
    sf = ("CASE WHEN coalesce((" + j + ") -> 'aggregated', 'null'::jsonb) NOT IN " + _FL_FALSY + " THEN '{}'::jsonb ELSE jsonb_strip_nulls(jsonb_build_object('fact_subject', nullif("
          + f + ".fact_subject, ''), 'l1_formula_id', nullif(" + f + ".formula_id::text, ''))) END")
    deep_at = FORWARDED_STRIP_DEPTH + 1
    return ("CROSS JOIN LATERAL (SELECT " + e0 + " AS e0) y CROSS JOIN LATERAL (SELECT " + _fl_strip("y.e0", chart, FORWARDED_STRIP_DEPTH) + " || " + sf
            + " AS e, jsonb_path_exists(y.e0, 'strict $.**{" + str(deep_at) + " to last}') AS deep) x")


def _fl_has_list(f: str) -> str:
    """SQL: the L1 fact lists constituents itself (the writer's `fvj.constituent_facts_array or fvj.constituent_fact_ids`, a non-empty list)."""
    j = "(" + f + ".fact_value_jsonb::jsonb)"
    parts = []
    for k in ("constituent_facts_array", "constituent_fact_ids"):
        parts.append("CASE WHEN jsonb_typeof(" + j + " -> '" + k + "') = 'array' THEN jsonb_array_length(" + j + " -> '" + k + "') > 0 ELSE false END")
    return "(" + " OR ".join(parts) + ")"


def _fl_composite(m: str, leaf: str) -> str:
    """A composite roll-up by the signal's own values (the writer's flood cap): one signal for many facts. Verified, never exempt on this say-so (`fl_composite_sql`)."""
    return "(coalesce(" + m + "." + leaf + " ->> 'aggregated', '') = 'true' AND coalesce(" + m + "." + leaf + " ->> 'fact_key', '') LIKE 'aggregate!_%' ESCAPE '!')"


def _fl_rows_pred(fx: dict, m: str = "m", composite: str = "exclude") -> str:
    """The rows of one form. `composite`: 'exclude' (a facts form compared one to one), 'only' (the composite roll-ups) or 'any' (both)."""
    rw = fx["rows"]
    pred = m + '."' + rw["column"] + '"::text = ' + _vocab_lit(rw["equals"])
    if fx["form"] == "chart_facts_row" and composite != "any":
        comp = _fl_composite(m, '"' + fx["leaf_column"] + '"')
        pred += " AND " + (comp if composite == "only" else "NOT " + comp)
    return pred


def _fl_leaves_equal(m: str, leaf: str) -> str:
    """True when signal row `m` forwards the cited fact exposed by `x` / `f` faithfully: every expected leaf equal, no key beyond the leaves (but the writer-resolved ones), and the forwarded columns."""
    obj = "(CASE WHEN jsonb_typeof(" + m + "." + leaf + ") = 'object' THEN " + m + "." + leaf + " ELSE '{}'::jsonb END)"
    return ("NOT EXISTS (SELECT 1 FROM jsonb_each(x.e) AS e(k, v) WHERE nullif(" + m + "." + leaf + " -> e.k, 'null'::jsonb) IS DISTINCT FROM nullif(e.v, 'null'::jsonb)) "
            "AND NOT EXISTS (SELECT 1 FROM jsonb_each(" + obj + ") AS q(k, v) WHERE NOT (x.e ? q.k) AND q.k NOT IN " + _FL_RESOLVED_KEYS + ") "
            "AND " + m + ".signal_type_id IS NOT DISTINCT FROM left(f.fact_category || ':' || f.fact_key, 80) "
            "AND " + m + ".citation_ref IS NOT DISTINCT FROM coalesce(nullif(f.citation_ref, ''), 'chart_facts/' || f.fact_id::text) "
            "AND " + m + ".citation_human IS NOT DISTINCT FROM coalesce(nullif(f.citation_human, ''), 'L1 chart_facts: ' || f.fact_category || '/' || f.fact_key)")


def _fl_facts_ok(cite: str, leaf: str, chart: str) -> str:
    """SQL boolean for signal row `m`: it forwards its OWN cited L1 fact faithfully (see the rules above)."""
    return ("EXISTS (SELECT 1 FROM unnest(m.\"" + cite + "\") WITH ORDINALITY AS c(fid, n) JOIN chart_facts f ON f.fact_id::text = c.fid::text AND f.chart_id = '" + chart
            + "' AND f.ayanamsha_id IN (m.ayanamsha_id, 'INVARIANT') " + _fl_expected("f", chart) + " WHERE f.fact_key = m.\"" + leaf + "\" ->> 'fact_key' AND (c.n = 1 OR " + _fl_has_list("f")
            + ") AND (x.deep OR (" + _fl_leaves_equal("m", '"' + leaf + '"') + ")))")


def fl_count_sql(table: str, fx: dict, chart: str, composite: str = "exclude") -> str:
    return "SELECT count(*) FROM (SELECT 1 FROM " + _fl_scoped(table, chart) + " m WHERE " + _fl_rows_pred(fx, "m", composite) + " LIMIT " + str(FORWARDED_COUNT_CAP + 1) + ") AS x"


def fl_dangling_sql(table: str, cite: str, chart: str) -> str:
    """Up to FORWARDED_SAMPLE_LIMIT (signal_id, cited id) whose cited id is NULL / empty or names no chart_facts row of the measured chart. Every row of the asset's scope, every form."""
    chart = _fl_chart(chart)
    return ("SELECT m.signal_id::text, coalesce(c.fid::text, '') FROM " + _fl_scoped(table, chart) + " m CROSS JOIN LATERAL unnest(m.\"" + cite + "\") AS c(fid) "
            "WHERE coalesce(c.fid::text, '') = '' OR NOT EXISTS (SELECT 1 FROM chart_facts f WHERE f.fact_id::text = c.fid::text AND f.chart_id = '" + chart + "') LIMIT " + str(FORWARDED_SAMPLE_LIMIT))


def fl_unmeasured_sql(table: str, forms, chart: str) -> str:
    """Up to 5 (verification_method, count) of the asset's rows that fall in NO declared form (the count stops at FORWARDED_COUNT_CAP + 1 rows): rows the detector does not compare."""
    col = forms[0]["rows"]["column"]
    lits = ", ".join(_vocab_lit(f["rows"]["equals"]) for f in forms)
    return ("SELECT coalesce(v.vm, '<NULL>'), count(*) FROM (SELECT m.\"" + col + "\"::text AS vm FROM " + _fl_scoped(table, chart) + " m WHERE coalesce(m.\"" + col + "\"::text, '') NOT IN (" + lits
            + ") LIMIT " + str(FORWARDED_COUNT_CAP + 1) + ") AS v GROUP BY 1 LIMIT 5")


def fl_nocite_sql(table: str, fx: dict, cite: str, chart: str) -> str:
    """Up to FORWARDED_SAMPLE_LIMIT signal ids of a projection (a composite roll-up included) that cite no fact id at all."""
    return ("SELECT m.signal_id::text FROM " + _fl_scoped(table, chart) + " m WHERE " + _fl_rows_pred(fx, "m", "any") + " AND coalesce(cardinality(m.\"" + cite + "\"), 0) = 0 LIMIT "
            + str(FORWARDED_SAMPLE_LIMIT))


def fl_deep_sql(table: str, fx: dict, cite: str, chart: str) -> str:
    """The bounded count of projection rows whose cited fact carries leaves nested deeper than the mirrored strip (they are named, not compared)."""
    chart = _fl_chart(chart)
    leaf = fx["leaf_column"]
    inner = ("EXISTS (SELECT 1 FROM unnest(m.\"" + cite + "\") AS c(fid) JOIN chart_facts f ON f.fact_id::text = c.fid::text AND f.chart_id = '" + chart + "' " + _fl_expected("f", chart)
             + " WHERE f.fact_key = m.\"" + leaf + "\" ->> 'fact_key' AND x.deep)")
    return "SELECT count(*) FROM (SELECT 1 FROM " + _fl_scoped(table, chart) + " m WHERE " + _fl_rows_pred(fx) + " AND " + inner + " LIMIT " + str(FORWARDED_COUNT_CAP + 1) + ") AS z"


def fl_composite_sql(table: str, fx: dict, cite: str, chart: str) -> str:
    """Up to FORWARDED_SAMPLE_LIMIT signal ids of a composite roll-up that is NOT what its own values claim: member_count and fact_value_num must equal the number of cited members, every cited member
    must resolve in chart_facts of the chart and carry the category the signal names."""
    chart = _fl_chart(chart)
    leaf, card = '"' + fx["leaf_column"] + '"', 'cardinality(m."' + cite + '")'
    bad_member = ("EXISTS (SELECT 1 FROM unnest(m.\"" + cite + "\") AS c(fid) WHERE NOT EXISTS (SELECT 1 FROM chart_facts f WHERE f.fact_id::text = c.fid::text AND f.chart_id = '" + chart
                  + "' AND f.fact_category = split_part(m.signal_type_id, ':', 1)))")
    return ("SELECT m.signal_id::text FROM " + _fl_scoped(table, chart) + " m WHERE " + _fl_rows_pred(fx, "m", "only") + " AND coalesce(" + card + ", 0) > 0 AND NOT (m." + leaf
            + " -> 'member_count' = to_jsonb(" + card + ") AND m." + leaf + " -> 'fact_value_num' = to_jsonb(" + card + ") AND NOT " + bad_member + ") LIMIT " + str(FORWARDED_SAMPLE_LIMIT))


def fl_drift_sql(table: str, fx: dict, cite: str, chart: str) -> str:
    """Up to FORWARDED_SAMPLE_LIMIT signal ids of one form whose forwarded leaves are NOT all equal to the signal's own cited L1 fact (the set-based join signals x chart_facts on fact_id,
    NOT EXISTS ... LIMIT: it stops at the 3rd offender; a PASS visits every row, as every proof of 'none' must)."""
    chart = _fl_chart(chart)
    leaf = '"' + fx["leaf_column"] + '"'
    citec = 'm."' + cite + '"'
    if fx["form"] == "chart_facts_row":
        cond = "coalesce(cardinality(" + citec + "), 0) > 0 AND NOT " + _fl_facts_ok(cite, fx["leaf_column"], chart)
    elif fx["form"] == "chart_vichara_row":
        cond = ("NOT EXISTS (SELECT 1 FROM chart_vichara v WHERE v.chart_id = '" + chart + "' AND v.ayanamsha_id = m.ayanamsha_id AND v.vichara_family = 'varga_ratification_divergence' "
                "AND v.subject = m." + leaf + " ->> 'subject' AND v.domain IS NOT DISTINCT FROM m." + leaf + " ->> 'domain' AND v.value_text IS NOT DISTINCT FROM m." + leaf + " ->> 'value_text' "
                "AND array(SELECT u.x FROM unnest(v.constituent_facts_array) WITH ORDINALITY AS u(x, n) WHERE u.x IS NOT NULL AND u.x <> '' ORDER BY u.n) = " + citec + "::text[] "
                "AND m.citation_ref IS NOT DISTINCT FROM 'chart_vichara/' || v.subject || '/' || v.domain)")
    else:
        d9 = ("EXISTS (SELECT 1 FROM chart_divisionals dv WHERE dv.chart_id = '" + chart + "' AND dv.ayanamsha_id = m.ayanamsha_id AND dv.varga = 'D9' AND dv.fact_key = 'dignity' "
              "AND dv.graha = m." + leaf + " ->> 'graha' AND dv.fact_value_text IS NOT DISTINCT FROM m." + leaf + " ->> 'd9_dignity')")
        d1 = ("cardinality(" + citec + ") = 1 AND EXISTS (SELECT 1 FROM unnest(" + citec + ") AS c(fid) JOIN chart_facts f ON f.fact_id::text = c.fid::text AND f.chart_id = '" + chart
              + "' AND f.fact_category = 'graha_dignity_per_varga' AND (f.fact_value_jsonb::jsonb) ->> 'varga' = 'D1' AND f.fact_value_text IS NOT DISTINCT FROM m." + leaf + " ->> 'd1_dignity')")
        cond = ("coalesce(cardinality(" + citec + "), 0) > 0 AND NOT (" + d9 + " AND " + d1 + " AND m.citation_ref IS NOT DISTINCT FROM 'chart_divisionals/D9/' || (m." + leaf + " ->> 'graha'))")
    return "SELECT m.signal_id::text FROM " + _fl_scoped(table, chart) + " m WHERE " + _fl_rows_pred(fx) + " AND " + cond + " LIMIT " + str(FORWARDED_SAMPLE_LIMIT)


def fl_diag_sql(table: str, fx: dict, cite: str, chart: str, ids) -> str:
    """For the offenders named by `fl_drift_sql` (at most FORWARDED_SAMPLE_LIMIT signal ids, validated as uuids): (signal_id, cited fact_id, leaf, forwarded value, L1 value) of the FIRST differing leaf
    of the nearest cited fact (an own fact first); a row citing no fact with that key names that."""
    chart = _fl_chart(chart)
    ids = [str(i) for i in ids]
    if not ids or len(ids) > FORWARDED_SAMPLE_LIMIT or not all(re.fullmatch(r"[0-9a-fA-F-]{36}", i) for i in ids):
        raise ValueError("fl_diag_sql needs 1 to FORWARDED_SAMPLE_LIMIT uuid signal ids")
    inl = ", ".join(_vocab_lit(i) for i in ids)
    leaf, citec = '"' + fx["leaf_column"] + '"', 'm."' + cite + '"'
    tail = " WHERE m.signal_id::text IN (" + inl + ")"
    pick = "SELECT x.leaf, left(x.fwd::text, 80) AS fwd, left(x.l1::text, 80) AS l1 FROM ("
    if fx["form"] == "chart_facts_row":
        own = "(c.n = 1 OR " + _fl_has_list("f") + ")"
        obj = "(CASE WHEN jsonb_typeof(m." + leaf + ") = 'object' THEN m." + leaf + " ELSE '{}'::jsonb END)"
        cand = ("LEFT JOIN LATERAL (SELECT f.*, " + own + " AS own_ok FROM unnest(" + citec + ") WITH ORDINALITY AS c(fid, n) JOIN chart_facts f ON f.fact_id::text = c.fid::text AND f.chart_id = '" + chart
                + "' AND f.ayanamsha_id IN (m.ayanamsha_id, 'INVARIANT') WHERE f.fact_key = m." + leaf + " ->> 'fact_key' ORDER BY " + own + " DESC, c.n LIMIT 1) cand ON true ")
        dsel = (pick + "SELECT 0 AS o, 'own_fact'::text AS leaf, to_jsonb((" + citec + ")[1]::text) AS fwd, to_jsonb('leaves equal cited fact ' || cand.fact_id::text || ', which is neither the first cited fact nor a fact that lists constituents (the writer puts the own fact first)') AS l1 WHERE NOT cand.own_ok "
                "UNION ALL SELECT 1, e.k, nullif(m." + leaf + " -> e.k, 'null'::jsonb), nullif(e.v, 'null'::jsonb) FROM jsonb_each(x.e) AS e(k, v) "
                "UNION ALL SELECT 2, 'signal_type_id', to_jsonb(m.signal_type_id), to_jsonb(left(cand.fact_category || ':' || cand.fact_key, 80)) "
                "UNION ALL SELECT 2, 'citation_ref', to_jsonb(m.citation_ref), to_jsonb(coalesce(nullif(cand.citation_ref, ''), 'chart_facts/' || cand.fact_id::text)) "
                "UNION ALL SELECT 2, 'citation_human', to_jsonb(m.citation_human), to_jsonb(coalesce(nullif(cand.citation_human, ''), 'L1 chart_facts: ' || cand.fact_category || '/' || cand.fact_key)) "
                "UNION ALL SELECT 3, 'extra key ' || q.k, q.v, to_jsonb('(not a leaf of the cited fact)'::text) FROM jsonb_each(" + obj + ") AS q(k, v) WHERE NOT (x.e ? q.k) AND q.k NOT IN " + _FL_RESOLVED_KEYS
                + ") AS x WHERE x.fwd IS DISTINCT FROM x.l1 ORDER BY x.o, x.leaf LIMIT 1")
        return ("SELECT m.signal_id::text, coalesce(cand.fact_id::text, (" + citec + ")[1]::text, ''), coalesce(d.leaf, 'fact_key'), CASE WHEN cand.fact_id IS NULL THEN coalesce(m." + leaf
                + " ->> 'fact_key', '') ELSE d.fwd END, CASE WHEN cand.fact_id IS NULL THEN '(no cited fact carries this fact_key)' WHEN d.leaf IS NULL THEN '(no differing leaf)' ELSE d.l1 END FROM "
                + _fl_scoped(table, chart) + " m " + cand + _fl_expected("cand", chart) + " LEFT JOIN LATERAL (" + dsel
                + ") d ON cand.fact_id IS NOT NULL" + tail)
    if fx["form"] == "chart_vichara_row":
        return ("SELECT m.signal_id::text, coalesce((" + citec + ")[1]::text, ''), coalesce(d.leaf, 'subject'), CASE WHEN cand.id IS NULL THEN coalesce(m." + leaf + " ->> 'subject', '') ELSE d.fwd END, "
                "CASE WHEN cand.id IS NULL THEN '(no chart_vichara row for this subject)' WHEN d.leaf IS NULL THEN '(no differing leaf)' ELSE d.l1 END FROM " + _fl_scoped(table, chart) + " m "
                "LEFT JOIN LATERAL (SELECT v.* FROM chart_vichara v WHERE v.chart_id = '" + chart + "' AND v.ayanamsha_id = m.ayanamsha_id AND v.vichara_family = 'varga_ratification_divergence' "
                "AND v.subject = m." + leaf + " ->> 'subject' ORDER BY (v.domain IS NOT DISTINCT FROM m." + leaf + " ->> 'domain') DESC, v.id LIMIT 1) cand ON true "
                "LEFT JOIN LATERAL (" + pick + "SELECT 1 AS n, 'domain' AS leaf, to_jsonb(m." + leaf + " ->> 'domain') AS fwd, to_jsonb(cand.domain) AS l1 "
                "UNION ALL SELECT 2, 'value_text', to_jsonb(m." + leaf + " ->> 'value_text'), to_jsonb(cand.value_text) "
                "UNION ALL SELECT 3, 'constituent_facts_array', to_jsonb(" + citec + "::text[]), to_jsonb(array(SELECT u.x FROM unnest(cand.constituent_facts_array) WITH ORDINALITY AS u(x, n) WHERE u.x IS NOT NULL AND u.x <> '' ORDER BY u.n)) "
                "UNION ALL SELECT 4, 'citation_ref', to_jsonb(m.citation_ref), to_jsonb('chart_vichara/' || cand.subject || '/' || cand.domain)"
                ") AS x WHERE x.fwd IS DISTINCT FROM x.l1 ORDER BY x.n LIMIT 1) d ON cand.id IS NOT NULL" + tail)
    return ("SELECT m.signal_id::text, coalesce((" + citec + ")[1]::text, ''), coalesce(d.leaf, 'd9_dignity'), d.fwd, coalesce(d.l1, '(no differing leaf)') FROM " + _fl_scoped(table, chart) + " m "
            "LEFT JOIN LATERAL (" + pick + "SELECT 1 AS n, 'd9_dignity' AS leaf, to_jsonb(m." + leaf + " ->> 'd9_dignity') AS fwd, "
            "coalesce(to_jsonb((SELECT dv.fact_value_text FROM chart_divisionals dv WHERE dv.chart_id = '" + chart + "' AND dv.ayanamsha_id = m.ayanamsha_id AND dv.varga = 'D9' AND dv.fact_key = 'dignity' "
            "AND dv.graha = m." + leaf + " ->> 'graha' ORDER BY dv.fact_value_text LIMIT 1)), to_jsonb('(no chart_divisionals D9 dignity row for this graha)'::text)) AS l1 "
            "UNION ALL SELECT 2, 'd1_dignity', to_jsonb(m." + leaf + " ->> 'd1_dignity'), coalesce(to_jsonb((SELECT f.fact_value_text FROM unnest(" + citec + ") AS c(fid) JOIN chart_facts f ON f.fact_id::text = c.fid::text "
            "AND f.chart_id = '" + chart + "' LIMIT 1)), to_jsonb('(no cited D1 fact)'::text)) "
            "UNION ALL SELECT 3, 'citation_ref', to_jsonb(m.citation_ref), to_jsonb('chart_divisionals/D9/' || (m." + leaf + " ->> 'graha'))"
            ") AS x WHERE x.fwd IS DISTINCT FROM x.l1 ORDER BY x.n LIMIT 1) d ON true" + tail)


# ── the reader (read-only, bounded, fault-isolated) and the grader (pure) ──

def _fl_unread(exc) -> dict:
    """timeout / denied (permission denied under the census role: not measurable there, NO_DETECTOR like the integrity read) / error (anything else: ERRORED)."""
    if _is_statement_timeout(exc):
        return dict(kind="timeout", why="exceeded the statement timeout")
    why = " ".join(str(exc).split())[:160]
    if "permission denied" in why.lower():
        return dict(kind="denied", why="is not readable under the census role: " + why)
    return dict(kind="error", why="failed: " + why)


def _fl_count(sql: str):
    n = int((psql(sql) or [["0"]])[0][0])
    return min(n, FORWARDED_COUNT_CAP), n > FORWARDED_COUNT_CAP


def forwarded_leaves_read(ff: dict, cols, chart_id: str) -> dict:
    """The raw readings for `grade_forwarded_leaves` (never raises): per declared form the bounded population count, the first offenders (and their diagnosis) and, for the facts form, the rows that
    cite no fact id, the composite roll-ups and their verification, the rows with leaves nested too deep; for the whole scope the first dangling citations and the rows of no declared form.
    `cols`: the signal table's column names (None = unknown)."""
    out = dict(table=ff["table"], cite=ff["cite_column"], chart=str(chart_id), forms={}, dangling=None, dangling_unread=None, unmeasured=None, unmeasured_unread=None, missing=[], blocked=None,
               scope=(_READ_SCOPE.get(ff["table"].lower()) or {}).get("label"))
    blk = _scope_block(ff["table"])
    if blk:                                                         # the engine's own state: the scope holds no rows (or could not be established): nothing is measured
        out["blocked"] = blk
        return out
    try:
        chart = _fl_chart(chart_id)
    except Unknown as exc:
        out["unread_all"] = _fl_unread(exc)
        return out
    need = {ff["cite_column"], "chart_id"}
    for f in ff["forms"]:
        need |= set(FORWARDED_FORM_COLUMNS[f["form"]]) | {f["leaf_column"], f["rows"]["column"]}
    have = set(cols or ())
    out["missing"] = sorted(c for c in need if c not in have) if cols else sorted(need)
    if out["missing"]:
        return out
    try:
        rows = psql(fl_dangling_sql(ff["table"], ff["cite_column"], chart)) or []
        out["dangling"] = [(r[0], r[1]) for r in rows if r]
    except (Unknown, ValueError, OSError) as exc:
        out["dangling_unread"] = _fl_unread(exc)
    try:
        rows = psql(fl_unmeasured_sql(ff["table"], ff["forms"], chart)) or []
        out["unmeasured"] = [(r[0], int(r[1])) for r in rows if len(r) >= 2]
    except (Unknown, ValueError, OSError) as exc:
        out["unmeasured_unread"] = _fl_unread(exc)
    for f in ff["forms"]:
        rec = dict(count=None, at_least=False, drift=None, nocite=None, unread=None, composite=None, composite_bad=None, deep=None)
        out["forms"][f["form"]] = rec
        try:
            rec["count"], rec["at_least"] = _fl_count(fl_count_sql(ff["table"], f, chart))
            if f["form"] == "chart_facts_row":
                n, al = _fl_count(fl_count_sql(ff["table"], f, chart, "only"))
                rec["composite"] = dict(count=n, at_least=al)
        except (Unknown, ValueError, OSError) as exc:
            rec["unread"] = _fl_unread(exc)
            continue
        if not rec["count"] and not (rec["composite"] or {}).get("count"):
            continue
        try:
            if f["form"] != "chart_vichara_row":                    # a divergence signal may legitimately cite no fact: its own array is compared with chart_vichara's
                rec["nocite"] = [r[0] for r in (psql(fl_nocite_sql(ff["table"], f, ff["cite_column"], chart)) or []) if r]
            if f["form"] == "chart_facts_row":
                rec["composite_bad"] = [r[0] for r in (psql(fl_composite_sql(ff["table"], f, ff["cite_column"], chart)) or []) if r]
                rec["deep"] = _fl_count(fl_deep_sql(ff["table"], f, ff["cite_column"], chart))[0]
            ids = [r[0] for r in (psql(fl_drift_sql(ff["table"], f, ff["cite_column"], chart)) or []) if r] if rec["count"] else []
            rec["drift"] = []
            if ids:
                got = psql(fl_diag_sql(ff["table"], f, ff["cite_column"], chart, ids)) or []
                seen = {r[0] for r in got if r}
                rec["drift"] = [tuple(r[:5]) for r in got if r and len(r) >= 5] + [(i, "", "?", "", "(offender found; diagnosis not read)") for i in ids if i not in seen]
        except (Unknown, ValueError, OSError) as exc:
            rec["unread"] = _fl_unread(exc)
    return out


def _fl_sample(rows, kind: str) -> str:
    if kind == "dangling":
        return "; ".join("(signal " + r[0] + ", cited fact_id " + (r[1] or "<empty>") + " is not in chart_facts of the measured chart)" for r in rows)
    return "; ".join("(signal " + r[0] + ", fact_id " + (r[1] or "<none>") + ", leaf " + r[2] + ": forwarded " + (r[3] or "<NULL>") + " vs L1 " + (r[4] or "<NULL>") + ")" for r in rows)


def grade_forwarded_leaves(ff: dict, got: dict) -> dict:
    """The detector's verdict (pure): {v, measured, + the evidence block fields}. FAIL on any offender (drift, dangling, a composite that is not what it claims) whatever else could not be read; then
    NO_DETECTOR (timeout / denied / a scope with no rows) / ERRORED (other failure) for anything unread; NO_DETECTOR for zero rows of the measured chart; PARTIAL for a declared form with no row, a
    projection citing no fact id, a row of a verification method no declared form measures, a leaf nested too deep; else PASS."""
    chart8 = str(got.get("chart", ""))[:8]
    forms = got.get("forms") or {}
    base = dict(declared=True, table=got.get("table"), cite_column=got.get("cite"), chart=got.get("chart"), read_scope=got.get("scope"),
                forms={k: dict(count=v.get("count"), at_least=bool(v.get("at_least"))) for k, v in forms.items()},
                composites=dict((forms.get("chart_facts_row") or {}).get("composite") or {}), own_fact_rule=FORWARDED_OWN_FACT_RULE,
                not_compared=[_FL_NOT_COMPARED[k] for k in forms])
    if got.get("blocked"):
        return dict(base, v=NO_DET, measured="NO_DETECTOR — " + str(got["blocked"]))
    if got.get("unread_all"):
        return dict(base, v=ERRORED if got["unread_all"]["kind"] == "error" else NO_DET, measured="forwarded-leaf detector not run: " + got["unread_all"]["why"])
    if got.get("missing"):
        return dict(base, v=NO_DET, measured="NO_DETECTOR — the forwarded-leaf detector cannot read table " + str(got.get("table")) + ": column(s) " + ", ".join(got["missing"]) + " absent (or the table's columns were not read)")
    fails = []
    dg = got.get("dangling") or []
    if dg:
        fails.append("dangling citation(s), first of a bounded sample: " + _fl_sample(dg, "dangling"))
    for name, rec in forms.items():
        if rec.get("drift"):
            fails.append(name + ": forwarded leaf differs from the cited L1 fact, first of a bounded sample (not a total): " + _fl_sample(rec["drift"], "drift"))
        if rec.get("composite_bad"):
            fails.append(name + ": composite roll-up is not what its own values claim (member_count / fact_value_num differ from the cited members, or a cited member does not resolve or has another category): signal(s) " + ", ".join(rec["composite_bad"]))
    if fails:
        return dict(base, v=FAIL, offenders=dict(dangling=[list(x) for x in dg], drift={k: [list(x) for x in (r.get("drift") or [])] for k, r in forms.items()}),
                    measured="forwarded L1 leaves DIFFER from L1 (CLAUDE.md N.5: halt-worthy drift): " + " | ".join(fails))
    unread = ([("citations", got["dangling_unread"])] if got.get("dangling_unread") else []) + ([("unmeasured-method guard", got["unmeasured_unread"])] if got.get("unmeasured_unread") else []) \
        + [(k, r["unread"]) for k, r in forms.items() if r.get("unread")]
    if unread:
        kinds = {u["kind"] for _, u in unread}
        return dict(base, v=ERRORED if "error" in kinds else NO_DET, measured="forwarded-leaf detector did not finish: " + "; ".join(k + " read " + u["why"] for k, u in unread) + " (never PASS)")
    counts = {k: (r.get("count") or 0) + ((r.get("composite") or {}).get("count") or 0) for k, r in forms.items()}
    if not any(counts.values()):
        return dict(base, v=NO_DET, measured="NO_DETECTOR — no row of the declared form(s) " + (", ".join(forms) or "-") + " in the measured chart (" + chart8 + ") under the read scope " + str(got.get("scope"))
                    + ": an empty scoped read is unmeasured, never PASS")
    why = []
    empty = [k for k, n in counts.items() if not n]
    if empty:
        why.append("declared form(s) " + ", ".join(empty) + " have no row in the measured chart (" + chart8 + "), so their forwarding is unmeasured")
    for k, r in forms.items():
        if r.get("nocite"):
            why.append(k + ": at least " + str(len(r["nocite"])) + " row(s) cite no fact_id (first signal ids: " + ", ".join(r["nocite"]) + "), so their leaves have no L1 fact to be compared to")
        if r.get("deep"):
            why.append(k + ": " + str(r["deep"]) + " row(s) cite a fact whose copied leaves nest deeper than " + str(FORWARDED_STRIP_DEPTH) + " levels (the writer's recursive strip is mirrored to that depth), not compared")
    um = got.get("unmeasured") or []
    if um:
        why.append("row(s) of verification method(s) no declared form measures are NOT compared: " + ", ".join(str(v) + " (" + str(n) + ("+" if n > FORWARDED_COUNT_CAP else "") + ")" for v, n in um))
    if why:
        return dict(base, v=PARTIAL, measured="forwarded-leaf detector PARTIAL: " + "; ".join(why))
    sizes = "; ".join(k + " " + ("at least " if forms[k].get("at_least") else "") + str(forms[k].get("count") or 0) + " row(s)" for k in forms)
    comp = (forms.get("chart_facts_row") or {}).get("composite") or {}
    ctext = ("; " + ("at least " if comp.get("at_least") else "") + str(comp.get("count", 0)) + " composite roll-up(s) are not compared one to one but verified against their cited members (member_count and fact_value_num equal the "
             "number of cited members, every member resolves and carries the signal's category)") if "chart_facts_row" in forms else ""
    return dict(base, v=PASS, measured=("forwarded L1 leaves equal their own cited L1 fact on every compared row of the measured chart (" + chart8 + "; read scope " + str(got.get("scope")) + "): " + sizes + ctext
                                        + "; every cited fact_id resolves in chart_facts of this chart; no row of the asset falls outside the declared forms (set-based join of the signals to chart_facts on fact_id; text exact, "
                                        "fact_value_num as float8, jsonb by =, NULL = NULL, the writer's whole-string uuid-v4 strip mirrored, no leaf skipped; " + FORWARDED_OWN_FACT_RULE
                                        + "; a signal key beyond the cited fact's leaves is a drift. NOT compared: " + "; ".join(base["not_compared"]) + ")"))


def forwarded_leaves_check(ff: dict, cols) -> dict:
    """Read and grade one asset's declared forwarded leaves for the measured chart (CHART_ID), under the read scope `measure()` installed. Never raises."""
    try:
        return grade_forwarded_leaves(ff, forwarded_leaves_read(ff, cols, CHART_ID))
    except Exception as exc:                                    # fault isolation (R41): a failure here degrades only this detector
        return dict(declared=True, v=ERRORED, measured="forwarded-leaf detector errored: " + type(exc).__name__ + ": " + str(exc)[:160])


# ── the fold into the two Null records and the rollup's re-check ──

_FL_DYNAMIC = "dynamic row construction"


def _fl_spans(units, scope: dict):
    """({name: (first line, last line)}, missing names) of the declared covered functions / constants in the scanned unit whose `rel` is the declared file (AST spans, no hard-coded line numbers)."""
    unit = next((u for u in (units or []) if u.get("rel") == scope["file"]), None)
    spans, want = {}, set(scope["functions"]) | set(scope["constants"])
    if unit is not None:
        for node in ast.walk(unit["tree"]):
            name = None
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in scope["functions"]:
                name = node.name
            elif isinstance(node, (ast.Assign, ast.AnnAssign)):
                tg = node.targets if isinstance(node, ast.Assign) else [node.target]
                name = next((t.id for t in tg if isinstance(t, ast.Name) and t.id in scope["constants"]), None)
            if name is not None:
                spans[name] = (node.lineno, getattr(node, "end_lineno", node.lineno))
    return spans, sorted(want - set(spans))


def forwarded_scan_cover(ws: dict, covers, scope: dict, units) -> dict:
    """Classify the static writer scan's findings (pure). Covered (what the scan cannot classify and the detector measures): a `literal_fallback` whose literal is the EMPTY string on a covered entry,
    and an unresolved path that is the scan's 'dynamic row construction could also supply the key' caveat on a covered entry, EACH LOCATED inside the declared covered code (the AST spans of the
    declared functions / constants of the declared file). Everything else is `uncovered` and keeps the cap."""
    spans, missing = _fl_spans(units, scope)
    fb, dyn, unc = 0, 0, []

    def inside(where: str, names) -> bool:
        m = re.fullmatch(r"(.+):([0-9]+)", str(where))
        return bool(m) and m.group(1) == scope["file"] and any(spans[n][0] <= int(m.group(2)) <= spans[n][1] for n in names if n in spans)
    for p in ws.get("problems") or []:
        if not missing and p.get("kind") == "literal_fallback" and str(p.get("text", "")).endswith(": ''") and p.get("entry") in covers and inside(p.get("where"), scope["functions"]):
            fb += 1
        else:
            unc.append(str(p.get("entry")) + " " + str(p.get("where")) + " (" + str(p.get("kind")) + ") " + str(p.get("text")))
    for u in ws.get("unresolved") or []:
        m = re.match(r"([A-Za-z0-9_]+): (\S+?:[0-9]+) ", str(u))
        if not missing and m and _FL_DYNAMIC in str(u) and m.group(1) in covers and inside(m.group(2), list(scope["functions"]) + list(scope["constants"])):
            dyn += 1
        else:
            unc.append("unresolved: " + str(u))
    if missing:
        unc.append("declared covered code not found in " + scope["file"] + ": " + ", ".join(missing))
    return dict(empty_fallbacks=fb, dynamic_row_caveats=dyn, uncovered=unc)


def _apply_forwarded_leaves(out: dict, pf, ctx: dict) -> None:
    """Fold the forwarded-leaf detector (`ctx['forwarded_leaves']`, set by `_measure_prose` for an asset that declares it) into the two Null records, after the writer scan. FAIL flips Null.blank_rows. A PASS
    lifts BOTH records when the data graders are clean, the writer scan's every finding is covered (`forwarded_scan_cover`) and the covered counts equal the declared pin. Anything else keeps the records and
    says what the detector read. No declaration = no change, byte for byte."""
    ffr, decl = ctx.get("forwarded_leaves"), ctx.get("forwarded_decl")
    if not isinstance(ffr, dict) or not isinstance(decl, dict) or not pf:
        return
    sd, br = out.get("Null.schema_default"), out.get("Null.blank_rows")
    if not (isinstance(sd, dict) and isinstance(br, dict)):
        return
    v = ffr.get("v")
    note = dict(declared=True, verified=False, v=v, measured=ffr.get("measured"))
    if v == FAIL:
        out["Null.blank_rows"] = dict(br, v=FAIL, forwarded_leaves=dict(note, offenders=ffr.get("offenders")), measured=str(ffr["measured"]) + "; " + str(br.get("measured", "")))
        out["Null.schema_default"] = dict(sd, forwarded_leaves=dict(note))
        return
    ws = ctx.get("scan_result")
    cover = forwarded_scan_cover(ws, decl["covers"], decl["covered_scope"], ctx.get("scan_units") or ctx.get("units")) if isinstance(ws, dict) else None
    waived = dict(empty_fallbacks=cover["empty_fallbacks"], dynamic_row_caveats=cover["dynamic_row_caveats"]) if cover else None
    pin_ok = waived is not None and waived == decl["pin"]
    lift = (v == PASS and cover is not None and not cover["uncovered"] and pin_ok and ws.get("v") == PARTIAL and all(r.get("v") == PARTIAL and r.get("clean") is True for r in (sd, br)))
    if not lift:
        extra = ""
        if v == PASS and cover is not None and cover["uncovered"]:
            extra = "; not lifted: the writer scan holds finding(s) the detector does not cover: " + "; ".join(cover["uncovered"][:3])
        elif v == PASS and cover is not None and not pin_ok:
            extra = "; not lifted: the covered scan findings (" + str(waived) + ") differ from the declared pin (" + str(decl["pin"]) + "): a changed finding in the covered code needs a new review"
        for crit in NULL_CHECKS:
            rec = out.get(crit)
            if isinstance(rec, dict) and rec.get("v") == PARTIAL:
                out[crit] = dict(rec, forwarded_leaves=dict(note), measured=str(rec["measured"]) + "; forwarded-leaf detector " + str(v) + ": " + str(ffr.get("measured")) + extra)
        return
    block = dict(declared=True, verified=True, v=PASS, table=ffr.get("table"), cite_column=ffr.get("cite_column"), chart=ffr.get("chart"), read_scope=ffr.get("read_scope"), forms=ffr.get("forms"),
                 composites=ffr.get("composites"), own_fact_rule=ffr.get("own_fact_rule"), not_compared=list(ffr.get("not_compared") or []),
                 covers=list(decl["covers"]), schema_default_clean=True, blank_rows_clean=True, scan_waived=dict(waived), pinned=dict(decl["pin"]),
                 evidence=decl.get("evidence"), why=decl.get("why"), detector=ffr.get("measured"))
    for crit in NULL_CHECKS:
        rec = out[crit]
        head = rec["measured"].split("; schema defaults")[0].split("; writer literal")[0]
        out[crit] = dict(rec, v=PASS, forwarded_leaves=dict(block),
                         measured=("PASS earned by the forwarded-leaf detector (measured chart only): " + head + "; the static writer scan's " + str(waived["empty_fallbacks"]) + " empty-string fallback(s) and "
                                   + str(waived["dynamic_row_caveats"]) + " dynamic-row-construction caveat(s), all inside the declared covered writer code and equal to the reviewed pin, are measured against L1 instead: "
                                   + str(ffr["measured"])))


def forwarded_leaves_problem_of(meas, facts=None) -> str | None:
    """None when this ONE Null record carries a complete verified `forwarded_leaves` block, else why it does not (the rollup re-checks it on both records): declared, verified, PASS, a chart and a read scope,
    at least one form with at least one row measured, the covered entries equal to the asset's declared prose_fields, both data graders clean, the covered scan findings equal to the pin, the statement of
    what is NOT compared and of the own-fact rule, a real why and evidence echoed; no INCONCLUSIVE, no basis, the record itself PASS."""
    if not isinstance(meas, dict):
        return "no record"
    b = meas.get("forwarded_leaves")
    if not isinstance(b, dict):
        return "no forwarded_leaves block"
    if b.get("declared") is not True or b.get("verified") is not True or b.get("v") != PASS:
        return "the forwarded-leaf detector is not declared, verified and PASS"
    for k in ("table", "cite_column", "chart", "evidence", "why", "detector", "own_fact_rule"):
        if not (isinstance(b.get(k), str) and b[k].strip()):
            return "the block carries no " + k
    if not isinstance(b.get("read_scope"), str) or not b["read_scope"].strip():
        return "the block names no read scope (the measured chart's rows)"
    nc = b.get("not_compared")
    if not (isinstance(nc, list) and nc and all(isinstance(x, str) and x.strip() for x in nc)):
        return "the block does not state what is not compared"
    fm = b.get("forms")
    if not (isinstance(fm, dict) and fm and all(isinstance(v, dict) and isinstance(v.get("count"), int) and not isinstance(v["count"], bool) and v["count"] >= 0 for v in fm.values())):
        return "the block names no measured form"
    comp = (b.get("composites") or {}).get("count") if isinstance(b.get("composites"), dict) else 0
    if not all(v["count"] + (comp if isinstance(comp, int) and k == "chart_facts_row" else 0) >= 1 for k, v in fm.items()):
        return "a covered form has no measured row"
    cv = b.get("covers")
    if not (isinstance(cv, list) and cv and all(isinstance(c, str) and c for c in cv) and len(set(cv)) == len(cv)):
        return "the block names no covered prose entry"
    if isinstance(facts, dict) and isinstance(facts.get("declared_prose_fields"), list) and sorted(facts["declared_prose_fields"]) != sorted(cv):
        return "the block's covered entries are not the asset's declared prose_fields"
    if b.get("schema_default_clean") is not True or b.get("blank_rows_clean") is not True:
        return "schema_default and blank_rows are not both clean"
    sw, pn = b.get("scan_waived"), b.get("pinned")
    if not (isinstance(sw, dict) and isinstance(pn, dict) and sw == pn and set(sw) == set(FORWARDED_PIN_FIELDS)
            and all(isinstance(sw[k], int) and not isinstance(sw[k], bool) and sw[k] >= 0 for k in sw)):
        return "the covered writer-scan findings are not equal to the declared pin"
    if meas.get("inconclusive") or meas.get("basis") is not None or meas.get("v") != PASS:
        return "the record is inconclusive, carries a basis, or is not PASS"
    return None


def forwarded_leaves_earned(crit: str, meas, all_meas, facts=None) -> bool:
    """True when the Null cap lifts for `crit` by the forwarded-leaf detector: this record AND its sibling Null record both carry a complete verified block over the same table, chart and covered entries."""
    if forwarded_leaves_problem_of(meas, facts) is not None or not isinstance(all_meas, dict):
        return False
    sib = all_meas.get("Null.blank_rows" if crit == "Null.schema_default" else "Null.schema_default")
    if forwarded_leaves_problem_of(sib, facts) is not None:
        return False
    a, b = meas["forwarded_leaves"], sib["forwarded_leaves"]
    return sorted(a["covers"]) == sorted(b["covers"]) and a["table"] == b["table"] and a["chart"] == b["chart"]


def _measure_prose(aid, decl, r, files, cat, ctables, shared, ptests, vocab) -> dict:
    """measure()'s glue for the six Narr/Null checks: gathers the inputs (catalog columns/types/defaults, the asset's
    row counts from its own count_sql scope, the writer scope, tests) and calls prose_checks. Fault-isolated (R41)."""
    tbl = r["target_table"]
    pf = decl.get("prose_fields") if isinstance(decl, dict) else None
    own = {}
    for t in dict.fromkeys([x for x in [tbl] + list(ctables) if x]):
        own[t] = (_target_columns_fact(t, cat),
                  (cat.get("types") or {}).get(t) if cat.get("types") is not None else None,
                  (cat.get("defaults") or {}).get(t, {}) if cat.get("defaults") is not None else None)
    # the asset's own tables: the registry target plus every table its count_sql reads (a multi-table asset keeps its
    # narration column outside the target_table); a table the catalog lacks is unknown, never 'zero columns'
    ctx = dict(table=tbl, own=own, tests=ptests, vocabulary=vocab, counts=None, paths=[], written=None)
    if isinstance(decl, dict) and decl.get("prose_fields") == [] and decl.get("prose_none") is not None and not prose_none_problem(decl):
        # N-150 R1: the asset's PRODUCED tables (its declared produced_tables when it declares them, else the tables it owns) and, per declared closed column, how many rows leave the vocabulary
        ptables = {t: (v[0], v[1], None) for t, v in own.items()}
        dpt = declared_produced_tables(decl)
        if dpt is not None:
            ptables = {}
            for d in dpt:
                t = d["table"]
                cols = _target_columns_fact(t, cat)
                ptables[t] = (cols, (cat.get("types") or {}).get(t) if cat.get("types") is not None else None, d["filter"] or (ptables.get(t) or (0, 0, None))[2])
        ctx["prose_tables"] = ptables
        ctx["udts"], ctx["keys"] = cat.get("udts"), cat.get("keys")
        ctx["closed_outside"] = prose_none_fetch_outside(ptables, tbl, decl["prose_none"], udts=ctx["udts"])
    if files and pf is not None:
        try:
            units, _beyond = _delegation_scope(aid, files)
            ctx["units"], ctx["beyond"] = units, _beyond
            ctx["paths"] = [u["path"] for u in units]
            if _beyond and isinstance(decl, dict) and decl.get("lint_none") is not None:
                # review fix LOW-1: the lint_none agreement must not rest on a chain the default hop limit cut: scan deeper (PRODUCED_SET_HOPS) and carry what is STILL cut
                _u6, _b6 = _delegation_scope(aid, files, hops=PRODUCED_SET_HOPS)
                ctx["lint_paths"], ctx["lint_beyond"] = [u["path"] for u in _u6], _b6
            ctx["written"] = written_columns(units, [tbl] + list(ctables) + [d["table"] for d in (declared_produced_tables(decl) or [])])
            if pf:
                ctx["scan_units"], ctx["scan_beyond"] = writer_scan_scope(aid, files)        # the Null writer scan reads the deeper scope; Narr.agree's `written` leg keeps the default
        except Unknown:
            pass
    errored = {}
    if pf:
        # each entry is counted in the owned table that HOLDS its column; an entry no owned table holds, or a table
        # whose scope cannot be established (shared + unparseable count_sql), is unknown for that entry
        counts: dict = {e: None for e in pf}
        groups: dict = {}
        for e in pf:
            held = _holders(parse_prose_field(e)[0], own)
            if held and held[0] in cat["exists"]:
                groups.setdefault(held[0], []).append(e)
        try:
            counts.update(_group_counts(groups, r, own, shared))
            ctx["counts"] = counts if any(v is not None for v in counts.values()) else None
        except Unknown as exc:
            errored = {c: dict(v=ERRORED, measured=f"check errored: {exc}") for c in ("Narr.checkable", "Null.blank_rows")}
    _ff = decl.get("forwarded_leaves") if isinstance(decl, dict) else None
    if pf and isinstance(_ff, dict) and not forwarded_leaves_problem(decl):
        # N-189: the forwarded-leaf detector reads the measured chart's rows of the declared (owned) table through the read scope measure() installed
        ctx["forwarded_decl"] = _ff
        ctx["forwarded_leaves"] = (forwarded_leaves_check(_ff, _target_columns_fact(_ff["table"], cat)) if _ff["table"] in own
                                   else dict(declared=True, v=NO_DET, measured=f"NO_DETECTOR — the declared forwarded_leaves table {_ff['table']} is not one of the asset's owned tables"))
    out = prose_checks(aid, decl, ctx)
    lc = decl.get("label_columns") if isinstance(decl, dict) else None
    if lc:
        # E5.7 W2 (SS 2026-10-06): the closed-values LABEL form is checked against the live DISTINCT values, read-only; an undeclared value is a FAIL of Narr.agree
        fetched = {}
        for d in lc:
            held = _holders(parse_prose_field(d["column"])[0], own)
            if held and held[0] in cat["exists"]:
                fetched[d["column"]] = label_read(held[0], d["column"], d["values"])
        rec = grade_label_columns(lc, fetched)
        base_a = out.get("Narr.agree", {})
        if rec["v"] == FAIL:
            out["Narr.agree"] = dict(v=FAIL, measured=rec["measured"], label_columns=rec["label_columns"])
        elif base_a.get("v") == PASS:
            out["Narr.agree"] = dict(base_a, v=rec["v"], measured=f"{base_a['measured']}; {rec['measured']}", label_columns=rec["label_columns"])
        elif isinstance(base_a, dict) and base_a:
            out["Narr.agree"] = dict(base_a, measured=f"{base_a.get('measured', '')}; {rec['measured']}", label_columns=rec["label_columns"])
    if cat.get("types_error"):
        # E1.8: the column types/defaults read failed (a malformed psql row, or any other Unknown): the verdicts that
        # needed them already degrade to "not read"; say WHY on those cells instead of leaving the reason in `cat`
        for crit in ("Narr.agree", "Null.schema_default"):
            if crit in out and out[crit].get("v") in (NO_DET, PARTIAL):
                out[crit] = dict(out[crit], measured=f"{out[crit]['measured']} [column types/defaults read failed: {cat['types_error']}]")
    out.update(errored)
    nc = decl.get("null_convention") if isinstance(decl, dict) else None
    if isinstance(nc, dict):
        # S1 (pin 13): the asset's declared null convention. Fault-isolated: a failure here leaves the Null records as prose_checks wrote them.
        try:
            out.update(_measure_null_convention(decl, nc, r, own, cat, shared, out))
        except (Unknown, OSError, ValueError) as exc:
            out.update({c: dict(out[c], null_convention=dict(declared=True, verified=False, v=ERRORED, measured=f"check errored: {exc}")) for c in NULL_CHECKS})
    return out


# ─────────────────────────── E1.9: `--assets` scope ───────────────────────────
# A level wave measures and emits ONLY its assets. A scoped census is a PARTIAL census: it is labelled
# (`scope: {assets: [...], partial: true}`) in every header it writes and anything that expects the whole
# population refuses it (`require_full_census`). An unscoped run writes no `scope` key at all, so its output is
# byte-identical to what it was before this flag existed.
EXIT_SCOPE = 6
# ONE table of this tool's exit codes. 0 clean · 2 a measured FAIL (and argparse usage errors) · 3 PARTIAL/NO_DETECTOR/ERRORED · 4 UNKNOWN
# (an unreachable instrument) · 5 script error · 6 scope error · 7 RESERVED for the emit_gaps withholding guard (EXIT_WITHHOLDING, PR #3041;
# not defined here) · E6.5 --registry-check: 9 `--check` drift · 10 gate x layer cell count != 54 · 11 uncovered required criteria
# (`--require-covered`; deliberately not 3, whose meaning is PARTIAL/ERRORED) · 12 a registry-declared detector never emitted.
EXIT_REG_DRIFT, EXIT_REG_CELLS, EXIT_REG_UNCOVERED, EXIT_REG_PARITY = 9, 10, 11, 12
_ASSET_ID = re.compile(r"[a-z][a-z0-9_]*")


class ScopeError(Exception):
    """A scope that cannot be honoured exactly (unknown / wrong-layer / empty / duplicate / malformed id), or a scoped
    census handed to something that needs the whole population. Never degraded to 'measure everything'."""


def parse_assets_arg(values) -> list[str]:
    """The `--assets` forms: a comma list, a repeated flag, or `@file` (ids separated by commas and/or newlines;
    blank lines and `#` comments ignored). Entries are whitespace-trimmed; ids are NOT case-normalized (a miscased id
    is a typo, reported as one); an empty list, an empty entry, a duplicate or whitespace inside an id is an error."""
    if not values:
        raise ScopeError("--assets was given no value: an empty scope is not 'everything' (omit the flag for a full run)")
    out: list[str] = []
    for raw in values:
        if raw.strip().startswith("@"):
            path = raw.strip()[1:]
            try:
                text = Path(path).read_text(encoding="utf-8-sig")      # a UTF-8 BOM is accepted
            except UnicodeDecodeError as exc:
                raise ScopeError(f"--assets @{path}: not valid UTF-8 text (a UTF-16 or binary file?) — save the list "
                                 "as UTF-8, one id per line or comma-separated") from exc
            except (OSError, ValueError) as exc:
                raise ScopeError(f"--assets @{path}: cannot read the file ({exc.__class__.__name__})") from exc
            entries = []
            for ln in text.splitlines():
                ln = ln.split("#", 1)[0]
                entries += [e for e in (x.strip() for x in ln.split(",")) if e]
            if not entries:
                raise ScopeError(f"--assets @{path}: the file names no asset")
            if any(e.startswith("@") for e in entries):
                raise ScopeError(f"--assets @{path}: nested @file references are not supported")
        else:
            entries = [x.strip() for x in raw.split(",")]
            if any(not e for e in entries):
                raise ScopeError(f"--assets {raw!r}: empty entry (blank value or stray comma)")
        out += entries
    for e in out:
        if re.search(r"\s", e):
            raise ScopeError(f"--assets: whitespace inside the id {e!r} (separate ids with commas)")
        if not _ASSET_ID.fullmatch(e):
            hint = f" — ids are lowercase (did you mean {e.lower()!r}?)" if e != e.lower() and _ASSET_ID.fullmatch(e.lower()) else ""
            raise ScopeError(f"--assets: malformed asset id {e!r}{hint}")
    dup = sorted(e for e, n in collections.Counter(out).items() if n > 1)
    if dup:
        raise ScopeError(f"--assets: duplicate id(s): {', '.join(dup)}")
    return out


def validate_scope(ids: list[str], layer_keys: list[str]) -> dict[str, list[str]]:
    """Every id must be an ACTIVE registry asset of one of `layer_keys`. Returns {layer: sorted ids}. Reports every bad
    id at once: unknown (in no registry), wrong layer (a registry asset of a layer not selected) or retired/inactive."""
    if not ids:
        raise ScopeError("empty scope")
    by_layer: dict[str, list[str]] = {}
    retired: dict[str, str] = {}
    active: dict[str, str] = {}
    for k in layer_keys:
        reg, pop = _layer_read("registry", registry, k)
        for aid in reg:
            active.setdefault(aid, k)
        for x in pop.get("excluded_inactive", ()):
            retired.setdefault(x["asset_id"] if isinstance(x, dict) else str(x), k)
    problems = []
    for aid in ids:
        if aid in active:
            by_layer.setdefault(active[aid], []).append(aid)
            continue
        if aid in retired:
            problems.append(f"{aid}: retired/inactive in {retired[aid]} (the census measures the active population only)")
            continue
        other = None
        for k in ALL_LAYERS:
            if k in layer_keys:
                continue
            try:
                if aid in registry(k)[0]:
                    other = k
                    break
            except Unknown:
                continue
        problems.append(f"{aid}: belongs to {other}, not in the selected layer(s) {', '.join(layer_keys)}" if other
                        else f"{aid}: unknown asset (not in the registry of {', '.join(layer_keys)})")
    if problems:
        raise ScopeError("; ".join(problems))
    return {k: sorted(v) for k, v in by_layer.items()}


def _is_full_census_path(target, full_out) -> bool:
    """Is `target` the full census file by ANY route: the same path, a case variant (case-insensitive filesystems), a
    hardlink or a symlink? An existing target is compared by inode (`os.path.samefile`); a not-yet-existing one by its
    resolved, normcased, case-folded path (conservative: on a case-sensitive filesystem a case variant is refused too)."""
    t, f = Path(target), Path(full_out)
    try:
        if t.exists() and f.exists() and os.path.samefile(t, f):
            return True
    except OSError:
        pass
    norm = lambda p: os.path.normcase(str(p.resolve())).casefold()      # noqa: E731
    return norm(t) == norm(f)


def _write_atomic(path, text: str) -> None:
    """Write `text` to `path` via a temp file in the same directory and `os.replace` — readers and concurrent writers
    see the old file or the whole new one, never a torn one. The temp file is removed on any failure."""
    d = os.path.dirname(os.path.abspath(path))
    fd, tmp = tempfile.mkstemp(prefix=".asset_census_", suffix=".tmp", dir=d)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(text)
            fh.flush()
            os.fsync(fh.fileno())
        um = os.umask(0)
        os.umask(um)
        os.chmod(tmp, 0o666 & ~um)          # mkstemp's 0600 is not the mode a plain write_text would have given the file
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


_GIT_SHA = re.compile(r"[0-9a-f]{40}|[0-9a-f]{64}")      # sha1 or sha256 object format; abbreviated/garbage is never adopted


def _git_env() -> dict:
    """The environment the provenance git calls run under: every GIT_* variable dropped (GIT_DIR / GIT_WORK_TREE /
    GIT_INDEX_FILE ... override the cwd and would make git answer for a different repository than the one this tool file
    lives in) and optional locks off (a read-only status must not write the index)."""
    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    env["GIT_OPTIONAL_LOCKS"] = "0"
    return env


def _git_provenance(tool_file) -> dict:
    """`tool_commit`, `tool_dirty` (and, when no commit can be certified, `tool_commit_unavailable`) for the checkout
    `tool_file` lives in. Strict: a checkout whose tool code differs from HEAD cannot be certified from, so
    `tool_commit` is HEAD only when (1) git answers from a scrubbed environment, (2) the repository toplevel contains
    `tool_file` and git TRACKS it (a non-git copy nested inside another repo must not report the outer repo's HEAD) and
    (3) no tracked file under the governance directory or the repo module the census loads at runtime is modified.
    Otherwise `tool_commit` is null with a reason (`tool_dirty` true = modified tracked files, null = unknown)."""
    tool_file = Path(tool_file).resolve()
    here = tool_file.parent
    runtime = [here]
    if len(tool_file.parents) > 2:
        runtime.append(tool_file.parents[2] / "python-sidecar" / "pipeline" / "orchestrator" / "dag_edge_guard.py")
    env = _git_env()

    def git(*args):
        return subprocess.run(["git", *args], capture_output=True, text=True, timeout=10, env=env, cwd=str(here), shell=False)

    def unknown(why):
        return dict(tool_commit=None, tool_dirty=None, tool_commit_unavailable=why)

    try:
        p = git("rev-parse", "--show-toplevel", "HEAD")
        lines = p.stdout.strip().splitlines()
        if p.returncode != 0 or len(lines) != 2 or not _GIT_SHA.fullmatch(lines[1].strip()):
            why = (p.stderr or "").strip().splitlines()[-1:] or ["no output"]
            return unknown(f"not a git checkout (git rev-parse HEAD exit {p.returncode}): {why[0][:160]}")
        top, sha = Path(lines[0]).resolve(), lines[1].strip()
        if not tool_file.is_relative_to(top):
            return unknown(f"git toplevel {top} does not contain the tool file {tool_file}")
        if git("ls-files", "--error-unmatch", "--", str(tool_file)).returncode != 0:
            return unknown(f"the tool file {tool_file.name} is not tracked by the enclosing git repository {top}")
        st = git("status", "--porcelain", "--untracked-files=no", "--", *[str(x) for x in runtime])
        if st.returncode != 0:
            return unknown(f"git status could not run (exit {st.returncode}): "
                           f"{((st.stderr or '').strip().splitlines() or ['no output'])[-1][:160]}")
    except (OSError, subprocess.SubprocessError) as exc:      # no git binary, unreadable dir, timeout
        return unknown(f"git could not run: {type(exc).__name__}")
    n = len([ln for ln in st.stdout.splitlines() if ln.strip()])
    if n:
        return dict(tool_commit=None, tool_dirty=True, tool_commit_unavailable=f"dirty checkout: {n} modified files")
    return dict(tool_commit=sha, tool_dirty=False)


def _declarations_provenance() -> dict:
    """`declarations_sha256` (sha256 of the BYTES of asset_declarations.json as read by this call) and `declarations_version` (the
    file's `version`), so a certificate cannot cite a census taken before a declaration existed or changed (the registry fingerprint
    does not cover this file). An unreadable file stamps both null with the reason `declarations_unavailable`; a readable file that
    is not JSON / carries no string `version` keeps the sha of its bytes, stamps the version null and says why. Never a guess."""
    try:
        raw = DECLARATIONS_PATH.read_bytes()
    except OSError as exc:
        return dict(declarations_sha256=None, declarations_version=None,
                    declarations_unavailable=f"{DECLARATIONS_PATH.name} could not be read: {type(exc).__name__}")
    sha = hashlib.sha256(raw).hexdigest()
    try:
        ver = json.loads(raw.decode("utf-8")).get("version")
    except (UnicodeDecodeError, ValueError, AttributeError):
        ver = None
    if not (isinstance(ver, str) and ver.strip()):
        return dict(declarations_sha256=sha, declarations_version=None,
                    declarations_unavailable=f"{DECLARATIONS_PATH.name} has no readable string `version` (its bytes are stamped)")
    return dict(declarations_sha256=sha, declarations_version=ver)


DB_IDENTITY_SCHEMA = "nikasha_db_identity/1"
_DB_NAME_SHAPE = re.compile(r"[A-Za-z0-9_.$-]{1,63}")
_DB_SYSID_SHAPE = re.compile(r"[0-9]{1,30}")


def _db_identity() -> dict:
    """E1.7: a NON-SECRET identity of the database cluster this census reads, so T4's "ran in production" can be PROVEN rather than asserted
    (a census taken on a sandbox clone is otherwise indistinguishable from a production one). `{schema, database, system_id_sha256}`: the
    database name (`current_database()`) and a domain-tagged sha256 of the cluster's `system_identifier` (`pg_control_system()`: set at
    initdb, equal on a physical replica, different on a restored or cloned cluster). NEVER a host, port, user, password or URL, and the raw
    identifier is not stored. Two read-only SELECTs through psql(), asked separately: a role that may not call pg_control_system() keeps the
    database name. A value outside the expected shape (a name that is not a plain identifier, an identifier that is not an integer) is refused,
    never echoed. Never raises and never changes an exit code: an unreachable database or a denied function stamps null plus a FIXED reason
    (a psql error line can carry a host or an address, so it is not quoted). Verdict-neutral: one more head key; the registry, its fingerprint
    and every measurement are untouched. It proves WHICH cluster was read; that it is production needs a registered production identity."""
    ident = dict(schema=DB_IDENTITY_SCHEMA, database=None, system_id_sha256=None)
    try:
        name = scalar("SELECT current_database()")
    except Exception:       # noqa: BLE001 -- a stamp is best-effort provenance: whatever stops the read (no psql, a timeout, a ragged answer), the run goes on
        name = None
    if not (isinstance(name, str) and _DB_NAME_SHAPE.fullmatch(name)):
        ident["unavailable"] = "the database could not be read (psql unreachable or the read failed)"
        return dict(db_identity=ident)
    ident["database"] = name
    try:
        sysid = scalar("SELECT system_identifier::text FROM pg_control_system()")
    except Exception:       # noqa: BLE001 -- as above: a role without EXECUTE on pg_control_system() keeps the name
        sysid = None
    if not (isinstance(sysid, str) and _DB_SYSID_SHAPE.fullmatch(sysid)):
        ident["unavailable"] = "the system identifier could not be read by this role (pg_control_system())"
        return dict(db_identity=ident)
    ident["system_id_sha256"] = hashlib.sha256(f"nikasha-db-identity/1:{sysid}".encode("utf-8")).hexdigest()
    return dict(db_identity=ident)


def census_stamp() -> dict:
    """Strategist ruling N-44 A: the provenance a layer census carries in its head, so a certificate can never be written
    from a census measured under a different registry revision or a different tool. Keys: `registry_revision`
    (REGISTRY_REVISION), `registry_fingerprint` (registry_fingerprint()), `tool_commit` (HEAD of the checkout this module
    runs from, only when that checkout is clean and verifiably the one this file lives in), `tool_dirty` (bool, or null when
    unknown) and, only when `tool_commit` is null, `tool_commit_unavailable` (the reason). Verdict-neutral by construction:
    read-only, touches no measurement, and the rollup reads only a layer's `layer` and `assets`, never its other head keys.
    A null tool_commit is never guessed; consumers (E5.1) refuse it.

    E1.8 declarations stamp: also `declarations_sha256` / `declarations_version` (see `_declarations_provenance`), and
    `declarations_unavailable` only when either is null. They are NOT fingerprinted content (REGISTRY_REVISION is unchanged and no
    cell moves). Interplay with `tool_commit`: asset_declarations.json lives in the governance directory, so a MODIFIED tracked
    declarations file already makes `tool_commit` null + `tool_dirty` true; the sha is always of the bytes actually read, so it also
    distinguishes two CLEAN commits whose declarations differ, and a consumer compares it to the file at the ref it certifies.
    E1.7: also `db_identity` (see `_db_identity`): the database name and a hash of the cluster's system identifier, never a host or credential."""
    return dict(registry_revision=REGISTRY_REVISION, registry_fingerprint=registry_fingerprint(),
                **_git_provenance(__file__), **_declarations_provenance(), **_db_identity())


def census_scope(obj) -> dict | None:
    """The scope label of a layer census, or None (a full census carries none). Fail-closed on a malformed label."""
    if not isinstance(obj, dict) or "scope" not in obj:
        return None
    sc = obj["scope"]
    if not (isinstance(sc, dict) and sc.get("partial") is True and isinstance(sc.get("assets"), list)
            and sc["assets"] and all(isinstance(x, str) and x for x in sc["assets"])):
        raise ScopeError(f"malformed census scope label {sc!r}: expected {{assets: [non-empty ids], partial: true}}")
    return sc


def require_full_census(obj, who: str) -> None:
    """Refuse a SCOPED census (a layer census, a census file, or a file's rollup) — for anything that needs all assets."""
    labels = [("census", obj)]
    if isinstance(obj, dict):
        labels += [(k, v) for k, v in obj.items() if isinstance(v, dict) and k != "scope"]
        if isinstance(obj.get("rollup"), dict):
            labels.append(("rollup", obj["rollup"]))
    for where, o in labels:
        if census_scope(o) is not None:
            raise ScopeError(f"{who}: refuses a SCOPED census ({where} carries scope.partial=true) — it needs the full "
                             "population; re-run without --assets")
        n, pop = (o.get("n_assets"), o.get("population_active")) if isinstance(o, dict) else (None, None)
        if isinstance(n, int) and isinstance(pop, int) and not isinstance(n, bool) and n < pop:
            raise ScopeError(f"{who}: refuses a census whose n_assets ({n}) is below the layer's population_active ({pop}) "
                             f"({where}): a partial census with its scope label stripped — it needs the full population")


def load_full_census(path) -> dict:
    """Read a census JSON for a consumer that expects every asset; a scoped file is refused."""
    obj = json.loads(Path(path).read_text(encoding="utf-8"))
    require_full_census(obj, f"census file {path}")
    return obj


@_memoized_run
def measure(layer_key: str, assets=None) -> dict:
    """Measure one layer — or, with `assets` (E1.9), ONLY those assets of it.

    SCOPE (E1.9). `assets` is validated against the layer's active registry BEFORE anything is measured (ScopeError:
    empty, duplicate, miscased, unknown or not in this layer). The per-asset reads (live counts, build record, build
    history, latest attempts, dependency records, catalog) are made for the selected assets only; the checks that read
    the WHOLE layer (Build.dag's known ids, the shared-table set, the blocking radius, the layer facts) still read the
    whole registry, so a scoped asset measures to exactly what it measures to in a full run. The result carries
    `scope={assets, partial: true}`; a full run carries no `scope` key.

    R41 SCOPE LIMIT (F12, A_REVIEW.md — disclosed, not fixed). R41 isolates PER-ASSET checks: one
    asset's failing check degrades only that criterion to ERRORED. The LAYER-WIDE reads below —
    `registry`, `catalog`, `registered_ids` (the writer scan), `throughput`, `build_history` — are
    not isolated: any of them raising `Unknown` still aborts the whole layer (exit 4, nothing reported
    clean), and under `--layer all` it also stops every layer after it, with no census file written.
    That is fail-closed, never a false PASS, but it is a whole-layer blind spot, not a degraded one.
    (`live_counts` isolates per asset itself — F2; `duration_instrument_present` degrades to
    `instrument unreachable` — D6 item 1.)"""
    cfg = LAYERS[layer_key]
    reg_all, population = _layer_read("registry", registry, layer_key)
    reg, assets_sel = reg_all, None                       # E1.9: `assets_sel` is the scope label (None: a full run)
    if assets is not None:
        sel = list(assets)
        if not sel or len(set(sel)) != len(sel) or any(not isinstance(x, str) or not _ASSET_ID.fullmatch(x) for x in sel):
            raise ScopeError(f"layer {layer_key}: the scope must be a non-empty list of distinct lowercase asset ids, got {sel!r}")
        missing = sorted(set(sel) - set(reg_all))
        if missing:
            raise ScopeError(f"layer {layer_key}: not active registry assets of this layer: {', '.join(missing)}")
        reg = {aid: r for aid, r in reg_all.items() if aid in set(sel)}     # registry order, like a full run
        assets_sel = sorted(sel)
    try:                                                   # N-150: a DECLARED produced table is read by the catalog like a target (its columns and types feed the R1 schema check)
        _early_decls = _run_declarations()
    except DeclarationsError:
        _early_decls = {}
    _produced_decl = [d["table"] for aid_ in reg for d in (declared_produced_tables((_early_decls or {}).get(aid_)) or [])]
    cat = _layer_read("catalog", catalog, [r["target_table"] for r in reg.values()]
                      + [t for r in reg.values() for t in _count_tables(r["count_sql"])] + _produced_decl)
    regd = _layer_read("registered_ids", registered_ids, cfg["prefix"])
    regd_all = _layer_read("registered_ids", registered_ids, "")      # review fix MED: the per-asset @register lookup is prefix-INDEPENDENT (an asset whose id lacks its layer prefix, lel_events under L5, is found)
    # R46 (L2 handverify): a view asset whose registry count_sql is a constant (bo_samvada: `SELECT 0`
    # over vw_chart_digest, which returns 15 rows) is counted by the VIEW — chart-scoped where the view
    # carries chart_id — instead of reading the constant as its live rows.
    view_counts = {aid: _view_count_sql(r["target_table"], cat["cols"].get(r["target_table"], []))
                   for aid, r in reg.items()
                   if r["target_table"] in cat.get("views", set()) and not _count_tables(r["count_sql"])}
    counts, count_errors = _layer_read("live_counts", live_counts, reg, CHART_ID, view_counts)
    ids = sorted(reg)                                      # R224: the layer's measured population
    # D6 item 1: feature-detected ONCE per layer run, not per asset — the instrument either
    # exists or it doesn't; a per-asset re-check would just be the same answer 40 times over.
    # (Detected before the build-record read, which names `duration_seconds` only when present.)
    instrument_present = duration_instrument_present()
    thru = _layer_read("throughput", throughput, cfg["prefix"], ids, instrument_present is True)
    hist = _layer_read("build_history", build_history, cfg["prefix"], ids)
    # D6 item 2: the latest started attempt per (asset, run chart). Fault-isolated like live_counts:
    # a failed read leaves Earn/Cost unlinked (NO_DETECTOR), it never aborts the layer.
    try:
        attempts, era = latest_attempts(ids)
    except Unknown:
        attempts, era = None, None
    # R45: every declared dependency's build record (cross-layer ones included), latest per
    # (asset, chart) by R44's rule — read only when some asset declares a dependency.
    dep_ids = sorted({d for r in reg.values() for d in r["depends_on"]})
    deprec = _layer_read("dependency_records", throughput, "", dep_ids) if dep_ids else {}
    dep_kinds: dict = {}                                   # dep -> registry asset_kind (service_ok is live for a service); a failed read leaves it empty
    if dep_ids and any((x.get("state") == "service_ok") for by in deprec.values() for x in by.values()):
        try:
            _lit = ", ".join("'" + d.replace("'", "''") + "'" for d in dep_ids)
            dep_kinds = {a: k for a, k in psql(f"SELECT asset_id, coalesce(asset_kind,'') FROM asset_registry WHERE asset_id IN ({_lit})")}
        except (Unknown, ValueError):
            dep_kinds = {}
    lmaps = local_map_candidates(cfg["prefix"]) if layer_key == "L0" else -1
    # R21: the blocking radius, registry-wide. Fault-isolated: an unreadable graph leaves every asset's
    # radius UNMEASURED (None, with the reason) — never 0, which would read as "an isolated leaf".
    try:
        dep_graph = dependency_graph()
        radius, radius_note = blocking_radius(dep_graph), None
    except Unknown as exc:
        dep_graph = None
        radius, radius_note = {}, f"unmeasured: the dependency read failed ({exc})"
    # E6 item (g): the asset-declarations file's kinds (a declared service satisfies Build.target by declaration).
    # An unreadable file leaves every declared kind UNKNOWN: Build.target then reads exactly as before.
    try:
        declarations = _run_declarations()
    except DeclarationsError:
        declarations = None
    # R23: every capability module's SQL, read once per layer run.
    try:
        caps_sql, caps_note = capability_sql(), None
    except Unknown as exc:
        caps_sql, caps_note = None, str(exc)

    known = set(reg_all)
    # E6.1 (d): a table (target or count_sql) that MORE THAN ONE active asset of this layer declares is shared.
    # Disclosed limit: only this layer's registry is read here; every share in the estate today sits inside one layer.
    _decl: dict[str, set[str]] = {}
    for _aid, _r in reg_all.items():
        for _t in ([_r["target_table"]] if _r["target_table"] else []) + _count_tables(_r["count_sql"]):
            _decl.setdefault(_t, set()).add(_aid)
    dens_shared = frozenset(t for t, who in _decl.items() if len(who) > 1)
    owners: dict = {}                                     # R53: read lazily, at most once per layer
    try:                                                   # E6 packet (c): read once per layer run
        prose_decls = _run_declarations()
        _others = []
        for _k in ALL_LAYERS:                              # E5.7: the reverse leg is scoped per asset, which needs EVERY layer's table ownership; a registry that cannot be read leaves its assets as wildcards (legacy)
            if _k == layer_key:
                continue
            try:
                _rg, _ = registry(_k)
                _others.append({a: r for a, r in _rg.items() if str(a).startswith(LAYERS[_k]["prefix"])})
            except Exception:                              # noqa: BLE001 (any read failure: the legacy global reading for those assets)
                continue
        prose_vocab = prose_vocabulary(prose_decls, declared_asset_tables(reg_all, _others))
    except DeclarationsError as exc:
        prose_decls, prose_vocab = exc, set()
    prose_tests = None
    produced: dict = {}                                   # E6 (h): registry-wide table -> producers, lazily, once per layer
    _UNREAD = object()
    svc_recs = _UNREAD                                    # Earn.service_state: the registry's recorded probe results, read lazily, once
    vocab_cache: dict = {}                                # N-176: the vocabulary samples / probes of a table are read ONCE per layer run (assets share tables: chart_facts is read by eight)

    def produced_owners():
        if "map" not in produced:                         # an unreadable map raises and is NOT cached as empty
            produced["map"] = produced_table_owners()
        return produced["map"]
    # Build.dep_liveness cause text: why each STALE dependency is stale (the upstream built after it). One batched read of the stale dependencies'
    # upstream closure, once per layer run; a failed read leaves the cause "not determinable" with its reason, the verdict never moves.
    _stale_all = sorted({d for d, by in deprec.items() if (_scope_record(by, CHART_ID) or {}).get("state") == "stale"})
    _cause_cache: dict = {}
    if _stale_all:
        try:
            if dep_graph is None:
                raise Unknown("the dependency graph could not be read")
            _closure = sorted({u for d in _stale_all for u in _upstream_closure(dep_graph, d)} - set(deprec))
            _crec = dict(deprec, **(throughput("", _closure) if _closure else {}))
            _cause_cache.update(stale_dependency_causes(_stale_all, dep_graph, _crec, CHART_ID))
        except Unknown as exc:
            _cause_cache.update(stale_dependency_causes(_stale_all, None, None, CHART_ID, str(exc)))

    def dep_causes(deps):
        return {d: _cause_cache[d] for d in deps if d in _cause_cache}
    whist = _WindowedHistory(cfg["prefix"], ids)             # SS Build.history window: read lazily, once per layer run
    if era is not None:                                      # the engine-deploy floor: a long-lived run or a gap of receipt-bearing dispositionless builds must not read as probes
        whist._reader_ready()
        era, _era_how = _disposition_era(era, whist.reader)
    assets = []
    set_read_scope(None)
    for aid, r in reg.items():
        set_read_scope(None)                                  # the measured-chart scope of the live data reads is per asset (set below, after the owned tables are known)
        _rscopes: dict = {}
        m: dict[str, dict] = {}
        files = regd_all.get(aid) or regd.get(aid, [])
        _nwd = bool(isinstance(declarations, dict) and isinstance(declarations.get(aid), dict) and declarations[aid].get("has_writer") is False)     # N-150 R5: the declared fact

        # Build.registered
        if len(files) == 1 and r["has_writer"]:
            m["Build.registered"] = dict(v=PASS, measured=f"@register in {files[0]}; registry agrees")
        elif len(files) == 1 and not r["has_writer"]:
            m["Build.registered"] = dict(v=FAIL, measured=f"@register in {files[0]} but registry says has_writer=false")
        elif len(files) > 1:
            m["Build.registered"] = dict(v=FAIL, measured=f"registered in {len(files)} files: {', '.join(files)}")
        elif r["has_writer"]:
            m["Build.registered"] = dict(v=FAIL, measured="registry says has_writer=true and no @register found")
        else:
            m["Build.registered"] = dict(_na("no writer, and the registry agrees (service or static)" + ("; declared has_writer: false (N-150 R5)" if _nwd else "; NOT declared has_writer: false, so no release (N-150 R5)"),
                                             "no-writer-registry-agrees"), no_writer=_no_writer_block(_nwd, r["has_writer"], files, aid))

        # R41: a per-check exception must degrade THAT check to ERRORED, never abort the layer.
        m["Build.contract"] = _measure_contract(aid, files, r["has_writer"], _nwd)
        m["Idem.pattern"] = _measure_idem(aid, files, cfg["idem"], r["has_writer"],
                                          [r["target_table"]] + _count_tables(r["count_sql"]), _nwd,
                                          (declarations or {}).get(aid, {}).get("update_only") if isinstance(declarations, dict) and isinstance((declarations or {}).get(aid), dict) else None)

        # Build.target
        m["Build.target"] = _measure_target(
            r, lambda: owners["map"] if "map" in owners else owners.setdefault("map", target_owners()),
            _declared_kind(declarations, aid))

        # SS 2026-10-05 R-d: the CHECKED facts a writer-less service / static-data release rests on (declaration + registry row + @register scan, and for static data the declared migrations checked on main)
        _nwb = _no_writer_block(_nwd, r["has_writer"], files, aid) if (_nwd and not r["has_writer"]) else None
        _nw_agree = bool(_nwb and _nwb["register_files"] == 0 and _nwb["register_mentions"] == [])
        _dk = _declared_kind(declarations, aid)
        _svc = dict(_nwb, service=True, registry_kind="service", declared_kind="service") if (_nw_agree and _dk == "service" and r.get("asset_kind") == "service") else None
        _static = None
        _sd = ((declarations or {}).get(aid) or {}).get("static_data") if isinstance(declarations, dict) else None
        if _nw_agree and _dk == "static" and _sd is not None:
            whist._reader_ready()
            _chk = static_data_check(_sd, whist.reader.file_at_main, {t for t in [r["target_table"]] + _count_tables(r["count_sql"]) if t})
            if _chk["ok"]:
                _static = dict(_nwb, static_data=True, declared_kind="static", migrations=list(_sd["migrations"]), table=_sd["table"], migrations_checked=True, migration_files=_chk["files"])

        # Build.dag: resolvability, and (E6 item h, T4:275) the declared edges against what the writer reads
        m["Build.dag"] = _measure_dag(aid, r, files, known, cfg["prefix"], produced_owners, dep_graph, static=_static)

        ok_ci = bool(r["count_sql"]) and r["has_integrity"]
        ci_text = f"count_sql={'yes' if r['count_sql'] else 'no'}, integrity_check_sql={'yes' if r['has_integrity'] else 'no'}"
        if aid in view_counts:       # R46: a view target whose registry count_sql reads no table (a constant): the count comes from the view
            ci_text += (f"; count_sql reads no table (a constant), so the live count is taken from the view {r['target_table']} (R46) and the "
                        "registered count_sql itself cannot fail")
        if ok_ci and aid in view_counts:
            # SS: a view target whose registered count_sql reads no table is a constant (a stub): it cannot fail, so presence of it is not a detector.
            m["Build.count_integrity"] = dict(v=PARTIAL, measured=ci_text.replace("count_sql reads no table (a constant)", "count_sql is constant (reads no table)", 1)
                                              + " — a constant count_sql cannot fail, so it is not a count detector (the census counts the view itself)")
        elif ok_ci:
            m["Build.count_integrity"] = dict(v=PASS, measured=ci_text)
        elif not r["has_writer"] and not r["count_sql"]:
            m["Build.count_integrity"] = (dict(_na(ci_text, "service-no-writer-no-count-sql"), no_writer=_svc) if _svc is not None else _na(ci_text, "no-writer-no-count-sql"))
        else:
            m["Build.count_integrity"] = dict(v=PARTIAL, measured=ci_text)

        live = counts.get(aid)
        zr_holds = False                                                   # N-149: set True only where a declared zero-row convention was verified
        is_view = aid in view_counts                                       # R46
        ctables = [r["target_table"]] if is_view else _count_tables(r["count_sql"])
        multi = len(ctables) > 1 or (bool(ctables) and r["target_table"] not in ctables)
        # R42: say what the live figure IS. On a multi-table asset it is the count_sql total across
        # every table it reads — compared like-for-like with rows_written (the writer's own total
        # across the same tables, e.g. mi_kula.py:302 `len(_FAMILIES) + len(_CONTROLS)`) — and never
        # presented as the target table's own rows (that figure is appended below, as context).
        basis = (f"counted by the census from the view {r['target_table']} "
                 f"({'chart-scoped' if _chart_scoped(view_counts[aid]) else 'whole view'}); the registry "
                 f"count_sql is a constant ({' '.join(r['count_sql'].split())})" if is_view
                 else f"count_sql total over {len(ctables)} table(s): {', '.join(ctables)}" if multi
                 else "count_sql over the target table")
        pset, pv_done = None, False                                        # N-150: the DECLARED produced-table set replaces count_sql as the comparison
        _dpt = None if is_view else declared_produced_tables((declarations or {}).get(aid) if isinstance(declarations, dict) else None)
        if _dpt is not None:
            pset = produced_set_reading(aid, _dpt, files, CHART_ID, ((declarations or {}).get(aid) or {}).get("produced_tables") if isinstance(declarations, dict) else None)
            if pset.get("error") is None:
                live, ctables, multi, basis = pset["total"], [d["table"] for d in _dpt], True, produced_set_text(pset)
        t, rec_scope = _build_record(thru.get(aid, {}),
                                     _chart_scoped(view_counts[aid] if is_view else r["count_sql"]), CHART_ID)
        if t.get("n_rows", 1) > 1 and not t.get("ambiguous"):
            rec_scope += f"; latest of {t['n_rows']} rows, last_built {t.get('last_built') or 'NULL'}"   # R44
        rw = t.get("rows_written", "")
        zr_decl = ((declarations or {}).get(aid) or {}).get("zero_row_convention") if isinstance(declarations, dict) else None
        zr_out = (zero_row_convention_outcome(zr_decl, CHART_ID)       # read only where the case arises: a writer-backed asset that declares one, counted 0
                  if (zr_decl is not None and live == 0 and r["has_writer"] and aid not in count_errors) else None)
        if pset is not None and pset.get("error"):
            m["Build.completion"] = dict(v=ERRORED, measured=f"check errored: the declared produced-table set could not be counted: {pset['error']}")
        elif aid in count_errors and pset is None:
            # F2 (A_REVIEW.md): a count_sql that RAISED must never read N/A "no count_sql" — that
            # reading is CLOSABLE and a live demonstration (bg_ephemeris) closed the gap on a query
            # that in fact errored. D4 case 1 ("never on an errored check") requires ERRORED here.
            m["Build.completion"] = dict(v=ERRORED, measured=f"check errored: {count_errors[aid]}")
        elif live is None and r["count_sql"].strip() and pset is None:
            # R222 / N1: a count_sql exists but produced no value that live_counts recorded. Never
            # "no count_sql" — that text would be false, and N/A would close a gap.
            m["Build.completion"] = dict(v=ERRORED, measured="check errored: count_sql produced no value")
        elif live is None:
            if not r["has_writer"] or (r["asset_kind"] == "service" and not r["target_table"]):
                m["Build.completion"] = _na(
                    f"no count_sql and nothing to count: has_writer={r['has_writer']}, "
                    f"asset_kind='{r['asset_kind']}', no target_table; build state='{t.get('state','-')}'",
                    ("service-no-writer-no-count-sql" if _svc is not None else "no-writer-no-count-sql") if not r["has_writer"] else "service-no-target-table-no-count-sql")
                if not r["has_writer"] and _svc is not None:
                    m["Build.completion"]["no_writer"] = _svc
            else:
                m["Build.completion"] = dict(
                    v=NO_DET, measured="NO_DETECTOR — no count_sql registered for a writer-backed asset with "
                                       f"asset_kind='{r['asset_kind']}'; completion cannot be measured")
        elif is_view:
            # R46: the view is now counted — but a view has no written rows: the writer creates or
            # preserves the view object (bo_samvada: rows_written=1 "the VIEW itself counts as 1
            # object", WriterResult rows_inserted=0), so rows_written<->live consistency is not
            # measurable. Emptiness still is: a view serving no rows for this chart FAILs unless the
            # registry declares zero rows complete. Never PASS on a comparison that cannot be made.
            if live == 0 and (r["target_floor"] or "").strip() != "0":
                m["Build.completion"] = dict(v=FAIL, measured=f"empty: live=0 ({basis}; {rec_scope}) and the registry "
                                                             "does not declare zero rows complete")
            else:
                m["Build.completion"] = dict(v=NO_DET, measured=f"NO_DETECTOR — view: live={live} ({basis}; {rec_scope}); "
                                                               f"build record rows_written={rw or 'none'} counts the "
                                                               "view object, not rows — completion consistency is not "
                                                               "measurable for a view")
        elif not ctables:
            # R42: a count_sql that reads no relation is a constant — it cannot disagree with anything.
            m["Build.completion"] = dict(v=NO_DET, measured=f"NO_DETECTOR — count_sql reads no table (a constant "
                                                           f"{live}); completion cannot be measured")
        elif (live == 0 and zr_out is not None and zr_out["state"] == "holds" and not t.get("ambiguous") and rw.isdigit() and int(rw) == 0
              and t.get("state") in COMPLETED_STATES):
            # N-149: a DECLARED zero-row convention whose condition the census just verified against the live scope table (the measured chart is
            # absent from it): zero rows is the by-design reading for THIS chart, the completed build record agrees (rows_written 0 = live 0), so
            # the comparison is a PASS whatever the registry floor. The declaration never answers by itself: it is read only where the verification
            # says `holds`, and every record condition (completed, not tied, rows_written 0) is still required.
            zr_holds = True
            m["Build.completion"] = dict(v=PASS, measured=f"rows_written={rw} = live=0 ({basis}; {rec_scope}); zero rows by declared convention "
                                                          f"(zero_row_convention, N-149), verified: {zr_out['detail']}; {zr_decl['why']}")
            m["Build.completion"] = _completion_integrity(m["Build.completion"], r)
        elif live == 0 and (r["target_floor"] or "").strip() != "0":
            # R52 (T1 plant build_completion_truncate): NON-EMPTINESS, measured on its own and first.
            # The check used to be only a rows_written<->live consistency test, so emptying a table
            # whose build record said rows_written=0 made the two AGREE and flipped FAIL -> PASS:
            # destroying data made the asset look healthy. An empty result is a completion only
            # where the registry itself declares zero rows complete (target_floor=0 — the engine's
            # own rule, asset_runner.py `zero_rows_is_complete`); everywhere else it FAILs,
            # whatever the build record says.
            m["Build.completion"] = dict(v=FAIL, measured=f"empty: live=0 ({basis}; {rec_scope}) and the registry "
                                                         f"does not declare zero rows complete (target_floor="
                                                         f"{r['target_floor'] if r['target_floor'] is not None else 'none'}); "
                                                         f"build record rows_written={rw or 'none'}")
        elif t.get("ambiguous"):
            # R44: several build rows for this (asset, chart) tie on (last_built_at, last_measured_at),
            # so which one is the latest is undetermined. Comparing against an arbitrary one would be
            # a verdict on a row nobody chose — ERRORED (neither opens nor closes a gap).
            m["Build.completion"] = dict(v=ERRORED, measured=f"check errored: {t.get('n_rows')} asset_throughput "
                                                             f"rows for this asset ({rec_scope}) tie on "
                                                             "(last_built_at, last_measured_at) — the latest "
                                                             "build record cannot be determined")
        elif rw == "":
            m["Build.completion"] = dict(v=FAIL, measured=f"live={live} and no build record at all ({rec_scope})")
        elif t.get("state") not in COMPLETED_STATES:
            m["Build.completion"] = dict(v=FAIL, measured=f"build record state='{t.get('state')}' is not a completed "
                                                         f"build (rows_written={rw}, live={live}, {rec_scope}) — see "
                                                         "Build.history"
                                                         + _cascade_skip_note(t.get("state"), hist["per"].get(aid)))
        elif int(rw) == 0 and live > 0:
            m["Build.completion"] = dict(v=FAIL, measured=f"build record says rows_written=0 against live={live} ({rec_scope})")
        elif int(rw) != live:
            # R42: the pre-fix final branch read PASS for ANY rows_written > 0 — it never compared
            # (mi_kula's "15 vs 11 scored PASS" was that branch; 15 vs anything would have passed).
            m["Build.completion"] = dict(v=FAIL, measured=f"build record rows_written={rw} disagrees with "
                                                         f"live={live} ({basis}; {rec_scope})")
        elif live == 0 and r["has_writer"]:
            # R99: the uncovered third case (ga_prashna: 51 runs, 0 rows, 0 modules). target_floor=0
            # alone is not "the layer plan declares this asset empty by design" — it is frequently
            # just an unset floor, and R52's fix (below) built its PASS path for a genuinely
            # design-empty asset (bg_sarvatobhadra_grid: has_writer=false, no writer ever attempted).
            # A WRITER-BACKED data asset that has actually run and still produced zero rows is
            # indistinguishable from a writer that has never worked — PASS here would silently
            # launder that ambiguity through the same branch. has_writer is the one existing
            # registry signal honest enough to distinguish the two without inventing a new
            # "empty by design" field nothing populates yet; a writer-backed asset gets PARTIAL —
            # not FAIL (R52's fix must not regress: an empty table under a declared target_floor=0
            # must not read as a new defect beyond what the emptiness itself already is), not PASS
            # (nothing here confirms the emptiness is intended, only that a floor was set to 0).
            m["Build.completion"] = dict(
                v=PARTIAL,
                measured=f"rows_written={rw} = live=0 ({basis}; {rec_scope}); target_floor=0 declares zero "
                         "rows complete, but this is a writer-backed data asset (has_writer=true) with no "
                         "layer-plan claim that the emptiness is by design — indistinguishable from a "
                         "writer that has never produced a row"
                         + ("" if zr_out is None else f"; a zero_row_convention is declared but does not hold here ({zr_out['detail']}): zero rows is not by design for this chart"
                            if zr_out["state"] == "does_not_hold" else
                            f"; a zero_row_convention is declared but could not be verified ({zr_out['detail']})"))
        else:
            # Consistency (R42), reached for live == 0 only under the target_floor=0 declaration (R52)
            # AND (R99) has_writer=false — no writer at all, the one signal honest enough to read as
            # "empty by design" without inventing a field the registry does not carry.
            m["Build.completion"] = dict(v=PASS, measured=f"rows_written={rw} = live={live} ({basis}; {rec_scope})"
                                         + ("; zero rows declared complete by target_floor=0 (has_writer=false "
                                            "— no writer at all, the signal honest enough to read as by-design)"
                                            if live == 0 else ""))
            # N-99 (rev 3): count equality alone is not a completion when the asset DECLARES an integrity_check_sql — it must hold too.
            # The only branch that can read PASS is this one, so the guard is here (downward-only); no declared SQL = the record is untouched.
            if pset is not None and pset.get("error") is None:
                m["Build.completion"] = produced_set_verdict(m["Build.completion"], pset)      # BEFORE the integrity step: an undeclared table is never hidden by it
                pv_done = True
            m["Build.completion"] = _completion_integrity(m["Build.completion"], r)
        if pset is not None and pset.get("error") is None:
            if not pv_done:
                m["Build.completion"] = produced_set_verdict(m["Build.completion"], pset)
            m["Build.completion"]["produced_set"] = dict(parts=pset["parts"], excluded=pset["excluded"], extra=pset["extra"], complete=pset["complete"], unproven=pset.get("unproven") or [])
        m["Build.completion"] = completion_latest_attempt(m["Build.completion"], None if attempts is None else attempts.get(aid, {}), rec_scope, CHART_ID)      # N-178: the latest started attempt of the asset errored: not complete, whatever the record and counts say

        # D6 item 2 (W2-2): Earn/Cost are attributed to the latest STARTED build_run_assets attempt at
        # the build record's scope (`_attempt_timing`), and only then graded by the D6 classifier —
        # the attempt linkage wave 1 left unwired (F1; `attempt_linkage_wired=False` until now). With
        # the instrument absent (migration 1094 not applied — production today) both still read
        # NO_DETECTOR "instrument absent", now naming the attempt they would be linked to.
        m["Earn.build_record"], m["Cost.baseline"] = _attempt_timing(
            None if attempts is None else attempts.get(aid, {}), t, rec_scope.split(";")[0], CHART_ID,
            instrument_present, r["has_writer"], era)
        if not r["has_writer"] and _nwd:
            _al, _aw = whist.build_attempts(aid)          # EVERY started attempt (a real build followed by a later probe row stays visible), not the latest per chart
            _re, _rw = whist.registry_epoch(aid) if any(attempt_kind(a_, era) != "probe" for a_ in (_al or [])) else (None, None)
            m["Earn.build_record"] = earn_build_record_no_writer(m["Earn.build_record"], _al, _no_writer_block(_nwd, r["has_writer"], files, aid), _re, _rw, _aw, era)     # SS 2026-10-05
            _pa = ((declarations or {}).get(aid) or {}).get("probe_attempts") if isinstance(declarations, dict) else None
            if _pa is not None:
                try:
                    _prow, _prc = probe_attempt_rows(aid)
                except Exception:                              # noqa: BLE001 -- R41: an unreadable live read degrades THIS cell to NO_DETECTOR, never the layer
                    _prow, _prc = None, None
                _pg = grade_probe_attempts(_pa, _prow, _prc, _no_writer_block(_nwd, r["has_writer"], files, aid), r.get("asset_kind"))
                if _pg is not None:
                    m["Earn.build_record"] = _pg                  # SS 2026-10-05 probe_attempts: a checked declaration replaces the attempt-log reading for this service

        _ss = _service_state_na(_declared_kind(declarations, aid), r.get("asset_kind"))
        if _ss is None and r.get("asset_kind") == "service":
            if svc_recs is _UNREAD:        # one isolated read per layer run, only when the layer holds a service
                svc_recs = service_records(layer_key)
            _ss = grade_service_state(aid, (declarations or {}).get(aid), svc_recs)
        if _ss is not None:
            m["Earn.service_state"] = _ss

        cf = _grade_count_floor(r, live, count_errors.get(aid), ctables)
        if cf is not None and zr_holds and cf["v"] == FAIL:
            # N-149: Count.floor is an INFO-ONLY family (measured, never a gap, outside the rollup gates). The floor is the registry's, for a chart the
            # asset produces rows for; this chart legitimately has none (the convention was verified above), so the breach is N/A by design, said so.
            cf = _na(f"{cf['measured']} — but this chart legitimately has no rows (zero_row_convention verified, N-149): the floor does not apply to it",
                     "zero-row-convention-holds")
        if cf is not None:
            m["Count.floor"] = cf

        tbl = r["target_table"]
        reach = None
        dc = {}
        # E6 S3: the asset's DECLARED Vocab.alias / Ldgr.source_presence (a declaring asset's record replaces the legacy pattern measurement below)
        _sd = ((declarations or {}).get(aid) or {}) if isinstance(declarations, dict) else {}
        _va, _ls = _sd.get("vocab_alias"), _sd.get("ldgr_source")
        _va_declared = isinstance(_va, dict) and (_va.get("na") is not None or _va.get("class") is not None)
        _ls_declared = isinstance(_ls, dict) and (_ls.get("na") is not None or _ls.get("source_column") is not None)
        _src = _sd.get("source")
        _src_declared = isinstance(_src, dict) and (_src.get("na") is not None or _src.get("level") is not None)
        _own_t = [t_ for t_ in dict.fromkeys(([tbl] if tbl else []) + list(ctables)) if t_ and t_ in cat["exists"]]
        _rscopes = read_scopes(_own_t, r, {t_: _target_columns_fact(t_, cat) for t_ in _own_t}, dens_shared, _sd, CHART_ID) if _own_t else {}
        mark_empty_scopes(_rscopes, convention_holds=zr_holds)    # a scoped table with NO rows for the measured chart is not judged (vacuous), unless a verified zero_row_convention says zero rows is by design here
        set_read_scope(_rscopes)                              # every live data read below (prose closures, label values, Ldgr sources, vocabulary samples, depth, identity) is the measured chart's
        if tbl and tbl in cat["exists"]:
            # R41: each of these four checks queries the target table independently (one of them,
            # on the estate's largest tables, is exactly R40's kala_field timeout case) — a single
            # slow/failing query must degrade only its OWN criterion, never blind the other three.
            try:
                dc = depth_census(tbl, cat["cols"].get(tbl, []))
                if dc.get("note") or not dc.get("rows"):
                    # R222 / N5 (A_REVIEW2 G2): an empty table (or one with no readable columns) has
                    # no column population to measure. It read PASS ("never populated: []" is
                    # vacuously empty), so truncating a table closed its open depth gap.
                    # Non-emptiness is Build.completion's / Count.floor's claim, not depth's.
                    m["Complete.depth"] = dict(v=NO_DET, measured=f"NO_DETECTOR — {dc.get('note') or 'no rows'} "
                                               f"({dc.get('rows', 0)} rows, {dc.get('columns', 0)} cols): column "
                                               "population cannot be measured on no rows")
                else:
                    m["Complete.depth"] = dict(v=(PASS if not dc.get("never") else PARTIAL),
                                               measured=(f"{dc.get('rows',0)} rows, {dc['columns']} cols; "
                                                         f"fully populated {len(dc.get('full',[]))}; NEVER populated "
                                                         f"{dc.get('never',[])}"))
            except Unknown as exc:
                dc = {}
                m["Complete.depth"] = dict(v=ERRORED, measured=f"check errored: {exc}")

            if multi and isinstance(dc.get("rows"), int) and m["Build.completion"]["v"] in (PASS, FAIL):
                # R42: the target table's own rows, stated as context — never the compared figure.
                m["Build.completion"]["measured"] += (f"; target_table {tbl} alone: {dc['rows']} row(s), "
                                                      "whole table — context, not the compared figure")

            keys = cat["keys"].get(tbl, [])
            if keys:
                k = keys[0] if len(keys[0]) > 1 or keys[0][0] != "id" else (keys[1] if len(keys) > 1 else keys[0])
                kd = ", ".join(k)
                try:
                    # R40: `count(*) - count(DISTINCT (cols))` requires a full sort/hash of every row
                    # to materialise BOTH counts and does not scale to the estate's largest table
                    # (kala_field, 10.3M rows; ground truth measured by hand: duplicates = 0 in 47s
                    # against the naive form's >180s). An EXISTS/HAVING duplicate-group probe can
                    # stop at the first violation instead of counting the whole table when one
                    # exists, and never needs the second full DISTINCT pass either way.
                    has_dup, figure = identity_duplicates(tbl, kd)
                    m["Vocab.identity"] = dict(v=(FAIL if has_dup else PASS),
                                               measured=f"declared key ({kd}): {figure}")
                    if not has_dup:
                        # R222 / N5, same class: "0 duplicates" on a table with NO rows is vacuous —
                        # truncating a table would close its open identity gap. Row count from the
                        # depth census when it ran; otherwise one EXISTS probe.
                        nrows = dc.get("rows")
                        if nrows is None:
                            nrows = 1 if identity_has_rows(tbl) else 0
                        if nrows == 0:
                            m["Vocab.identity"] = dict(v=NO_DET, measured=f"NO_DETECTOR — table empty: uniqueness "
                                                                          f"under ({kd}) is vacuous on 0 rows")
                except Unknown as exc:
                    m["Vocab.identity"] = dict(v=ERRORED, measured=f"check errored: {exc}")

            try:
                ac = None if _va_declared else alias_census(tbl, cat["cols"].get(tbl, []))
                if ac:
                    bad = {k: v for k, v in ac.items() if v["no_alias"]}
                    # R54 (T1 plant vocab_alias): the verdict saturates — one empty alias set FAILs as
                    # hard as all of them (79/741 -> 741/741 empty moved nothing at verdict level). The
                    # measured fraction is stated in the evidence and carried as `severity` (0.0-1.0,
                    # rows lacking an alias set / rows), so a worsening is visible below the verdict.
                    rows_t = sum(v["rows"] for v in ac.values())
                    empty_t = sum(v["no_alias"] for v in ac.values())
                    frac = (empty_t / rows_t) if rows_t else 0.0
                    m["Vocab.alias"] = dict(v=(PASS if not bad else FAIL),
                                            measured=(f"{len(ac)} class(es); {empty_t}/{rows_t} row(s) lack an alias set "
                                                      f"({frac:.1%}); empty alias sets: "
                                                      + (", ".join(f"{k} {v['no_alias']}/{v['rows']}" for k, v in bad.items()) or "none")),
                                            severity=round(frac, 4))
            except Unknown as exc:
                m["Vocab.alias"] = dict(v=ERRORED, measured=f"check errored: {exc}")

            # R23: field-level reachability of the target table (reported, not graded).
            m["Reach.fields"], reach = _grade_reach(tbl, cat["cols"].get(tbl, []), dc, caps_sql, caps_note, CHART_ID)

            tcols = set(cat["cols"].get(tbl, []))
            # R60: the singular `classical_citation` (as opposed to the plural `classical_citations`)
            # was missing from this list — bg_nakshatra_medical and at least a dozen other L0 tables
            # (bg_avastha_schemes, bg_combustion_orbs, bg_dignity_reference, bg_graha_dik,
            # bg_graha_naisargika_friendship, bg_medical_mappings, bg_motion_state_thresholds,
            # bg_prashna_* x5, bg_shashtiamsha_deities, bg_sign_medical, bg_transit_av_gates,
            # bg_transit_moorti — measured 2026-09-28 via information_schema) carry it and got no
            # Ldgr.source_presence check at all, despite a populated citation column.
            cit = [c for c in CITATION_COLUMNS if c in tcols]
            if cit and dc.get("rows") and not _ls_declared and not _src_declared:
                col = cit[0]
                try:
                    # C2(ii) (pin 24): a placeholder citation is not a source; ldgr_legacy_presence is the one reading (shared predicate with the declared ldgr_source check)
                    m["Ldgr.source_presence"] = ldgr_legacy_presence(tbl, col, dc["rows"])
                except Unknown as exc:
                    m["Ldgr.source_presence"] = dict(v=ERRORED, measured=f"check errored: {exc}")
        elif tbl:
            m["Complete.depth"] = dict(v=FAIL, measured=f"target_table '{tbl}' does not exist in production")

        # E6 S3: the declared forms (N/A by declaration, or measured against bg_ontology / the declared source column); {} for an undeclared asset
        # (the DECLARED table and, only when it exists in production with known columns, its columns: a table that is absent, or a view, is NO_DETECTOR, never a pass-through)
        m.update(vocab_alias_declared_check(aid, _va, tbl or None, _target_columns_fact(tbl, cat)))
        # N-176: the VALUE reading of Vocab.alias (bounded, read-only samples of every text-capable / json column of the asset's owned tables). It fills an undeclared asset's absent record and OVERRIDES a declared
        # `no_alias_class` (advisory: the data decides); a declared measured alias class, the `synonyms` census and a documented-alias contradiction keep their own readings (`vocab_value_merge`).
        _own_v = {t_: (_target_columns_fact(t_, cat), (cat.get("types") or {}).get(t_) if cat.get("types") is not None else None) for t_ in dict.fromkeys(([tbl] if tbl else []) + list(ctables)) if t_ and t_ in cat["exists"]}
        _va_skip = (isinstance(_va, dict) and _va.get("class") is not None) or (m.get("Vocab.alias") is not None and _va is None)      # a declared measured class / an already-measured `synonyms` census: not re-read
        if _own_v and not _va_skip:
            try:
                _vv = vocab_value_detect(_own_v, cat.get("udts"), declared=_va if isinstance(_va, dict) else None, cache=vocab_cache,
                                       scopes={t_: _rscopes[t_] for t_ in _own_v if t_ in _rscopes})
            except Exception as exc:                          # noqa: BLE001  R41: the value reading degrades only this check (NO_DETECTOR with the cause), never the layer
                _vv = dict(v=NO_DET, measured=f"NO_DETECTOR — the value reading of Vocab.alias could not run ({type(exc).__name__}: {' '.join(str(exc).split())[:160]})")
            _vm = vocab_value_merge(m.get("Vocab.alias"), _va, _vv, columns_known=bool(_own_v))
            if _vm is not None:
                m["Vocab.alias"] = _vm
        m.update(ldgr_source_declared_check(aid, _ls, tbl or None, _target_columns_fact(tbl, cat), cat["keys"].get(tbl, []) if tbl else []))

        # E6.1 (d): every token the asset is served under — target table, asset id, every count_sql table — over every
        # serving root (R23's CAPS_ROOTS, recursive) plus the wider source probe. A table another active asset of this
        # layer also declares is SHARED: it names the table, not this asset, so it never attributes a module.
        dtoks = list(dict.fromkeys([t for t in ([tbl] if tbl else []) + list(ctables) + [aid] if t]))
        # DENS-TIER-GUARD (REGISTRY_REVISION 23): the asset's declared tier columns (its own target table only). The same `density_tier_problem` the validator runs, now
        # WITH the table's catalog columns: a refusal (a declared column the table lacks, a deny-listed name) reads Dens.served NO_DETECTOR with the disagreement reported,
        # never PASS, and the scan then runs on the closed default only (the verdict below is replaced).
        _dt_bad = density_tier_measure_problem(_sd, tbl, _target_columns_fact(tbl, cat) if tbl else None)
        _dt = ({tbl.lower(): [d["column"] for d in _sd["density_tier_columns"]]}
               if (tbl and not _dt_bad and isinstance(_sd.get("density_tier_columns"), list)) else None)
        # DENS-FACET (REGISTRY_REVISION 26): the asset's declared facet on its own (shared) target table; a refusal reads NO_DETECTOR with the disagreement, never PASS
        _df_bad = density_facet_measure_problem(_sd, tbl, _target_columns_fact(tbl, cat) if tbl else None)
        _df = ({tbl.lower(): dict(column=_sd["density_facet"]["column"], values=list(_sd["density_facet"]["values"]))}
               if (tbl and not _df_bad and isinstance(_sd.get("density_facet"), dict)) else None)
        cap = capability_scan(CAPS_ROOTS, dtoks, shared=dens_shared, columns=cat["cols"],
                              outside_roots=DENS_OUTSIDE_ROOTS, service=(r.get("asset_kind") == "service"), tier_declared=_dt, facets=_df)
        _ua_bad = uniform_authority_measure_problem(_sd, tbl, _target_columns_fact(tbl, cat) if tbl else None, aid)
        m["Dens.served"] = _grade_dens(cap, tbl or aid, uniform_authority=(isinstance(_sd, dict) and _sd.get("uniform_authority") is not None and not _ua_bad))
        if _ua_bad:
            m["Dens.served"] = dict(v=NO_DET, measured=f"NO_DETECTOR — the declared uniform_authority is refused ({_ua_bad}); never PASS (graded without it: {m['Dens.served']['v']})")
        if _df_bad:
            m["Dens.served"] = dict(v=NO_DET, measured=f"NO_DETECTOR — the declared density_facet is refused ({_df_bad}); never PASS: the asset is not attributed by facet "
                                                       f"(graded without it: {m['Dens.served']['v']})")
        if _dt_bad:
            m["Dens.served"] = dict(v=NO_DET, measured=f"NO_DETECTOR — the declared density_tier_columns are refused ({_dt_bad}); never PASS: the tier vocabulary stays the closed "
                                                       f"default (tier / verification_pass_status) until the declaration is sound (graded on that default: "
                                                       f"{m['Dens.served']['v']})")

        # E6 packet (c): the Null and Narr checks (declarations file + catalog + writer scope + tests; fault-isolated)
        if isinstance(prose_decls, DeclarationsError):
            for _c in NARR_CHECKS + NULL_CHECKS:
                m[_c] = dict(v=ERRORED, measured=f"check errored: the declarations file is unreadable ({prose_decls})")
        else:
            try:
                if prose_tests is None and (prose_decls.get(aid) or {}).get("prose_fields"):
                    prose_tests = python_tests()
                m.update(_measure_prose(aid, prose_decls.get(aid), r, files, cat, ctables, dens_shared, prose_tests or (),
                                        prose_vocab))
            except (Unknown, DeclarationsError) as exc:
                for _c in NARR_CHECKS + NULL_CHECKS:
                    m[_c] = dict(v=ERRORED, measured=f"check errored: {exc}")

        # N-151: the declared `source` reading (read after the prose checks: `no_claims` rests on the asset's own prose_none check), and the undeclared L0 asset that holds data
        _owned = list(dict.fromkeys(t for t in ([tbl] if tbl else []) + list(ctables) if t and t in cat["exists"]))
        if _src_declared:
            m.update(source_declared_check(aid, _src, tbl or None, _target_columns_fact(tbl, cat), rows=dc.get("rows") if isinstance(dc, dict) else None, owned=_owned,
                                           keys=cat["keys"].get(tbl, []) if tbl else [], prose_record=m.get("Narr.agree"), asset_kind=r.get("asset_kind"),
                                           owned_columns={t: _target_columns_fact(t, cat) for t in dict.fromkeys(_owned + [d_["table"] for d_ in (declared_produced_tables(_sd) or [])])}))
        else:
            _und = ldgr_undeclared_l0_record(layer_key, declared=_ls_declared, measured="Ldgr.source_presence" in m, table=tbl, exists=bool(tbl and tbl in cat["exists"]),
                                             rows=dc.get("rows") if isinstance(dc, dict) else None)
            if _und is not None:
                m["Ldgr.source_presence"] = _und

        _ent = declarations.get(aid) if isinstance(declarations, dict) else None
        if isinstance(_ent, dict) and _ent.get("no_table") is not None:        # SS 2026-10-05 no-table-no-prose: a service that owns no table; the block is MEASURED, never trusted
            m.update(no_table_records(aid, _ent, no_table_block(_ent, r.get("asset_kind"), r["has_writer"], r.get("target_table"), ctables, len(files), register_call_mentions(aid))))
        h = hist["per"].get(aid)
        if not h:
            if r["has_writer"]:
                m["Build.exercised"] = dict(
                    v=FAIL, measured="registered with a writer and the orchestrator has NEVER run it "
                                     "(no build_run_assets row)")
            else:
                m["Build.exercised"] = dict(_na("never run, and it has no writer — consistent" + ("; declared has_writer: false (N-150 R5)" if _nwd else "; NOT declared has_writer: false, so no release (N-150 R5)"),
                                                "never-run-no-writer"), no_writer=_no_writer_block(_nwd, r["has_writer"], files, aid))
            if hist["per"]:
                m["Build.history"] = _na("never run; check 7 owns this", "never-run")
            else:
                # SS N-65 / F5: `never-run` is released as N/A, so it may be emitted only when the build-history source is
                # demonstrably PRESENT: some other asset of this census has build_run_assets rows. With no row for ANY asset
                # of the scope (wiped, unreadable or never populated) "this asset never ran" cannot be told from "there is
                # no history": NO_DETECTOR, never N/A (and so it closes no ledger row).
                m["Build.history"] = dict(
                    v=NO_DET, measured="NO_DETECTOR — build history is absent for the whole census scope (no build_run_assets "
                                       "row for any asset), so `never run` cannot be told from a missing or unreadable history")
        elif not h.get("executed", 0):
            # C1 (W2-1_REVIEW §2 A8): rows exist but none was ever STARTED (queued leftovers, aborted or
            # BLOCKED before start) — the orchestrator never executed this asset. Not a PASS; the
            # history is still graded (its own zero-completion guard keeps it non-closable).
            if r["has_writer"]:
                m["Build.exercised"] = dict(
                    v=FAIL, measured=f"registered with a writer and the orchestrator has NEVER executed it: "
                                     f"{h['runs']} build_run_assets row(s), none ever started "
                                     f"(states: {h.get('states') or 'n/a'})")
            else:
                m["Build.exercised"] = dict(_na(f"never executed ({h['runs']} unstarted row(s)), and it has no "
                                                "writer — consistent" + ("; declared has_writer: false (N-150 R5)" if _nwd else "; NOT declared has_writer: false, so no release (N-150 R5)"),
                                                "never-executed-no-writer"), no_writer=_no_writer_block(_nwd, r["has_writer"], files, aid))
            m["Build.history"] = whist.cell(aid, h, r["has_writer"], files)      # review fix: judged inside the window too (old aborts of code that no longer exists are reported, not judged)
        else:
            m["Build.exercised"] = dict(
                v=PASS, measured=f"{h['executed']} executed run(s) of {h['runs']} build_run_assets row(s), "
                                 f"scope(s): {', '.join(sorted(h['executed_scopes']))}, last executed "
                                 f"{h['last_executed_when']}")
            if not r["has_writer"] and _nwd:
                # SS 2026-10-05 R-c: a declared no-writer asset whose only BUILD attempts are OLDER than the registry row's current definition ran under a definition that no longer exists:
                # they do not contradict has_writer: false, so it reads like a never-run no-writer asset (N/A, with the legacy rows named); a NEWER build attempt keeps the executed reading (the
                # contradiction is Earn.build_record's FAIL); a definition date that cannot be read changes nothing.
                _blk = _no_writer_block(_nwd, r["has_writer"], files, aid)
                if _blk["register_files"] == 0 and _blk["register_mentions"] == []:
                    _al, _aw = whist.build_attempts(aid)
                    _re, _rw = whist.registry_epoch(aid)
                    _sp = no_writer_attempt_split(_al, _re, era)
                    if _al is not None and _re is not None and _sp["legacy"] and not _sp["newer"] and not _sp["undated"] and not _sp["unclassified"]:
                        m["Build.exercised"] = dict(_na(f"declared has_writer: false (registry and @register scan agree); its only build attempt(s) ({_attempt_ids(_sp['legacy'])}) are OLDER than the "
                                                        "registry row's current definition and do not contradict it (SS R-c): nothing has exercised it under its current definition",
                                                        "legacy-attempts-no-writer"), no_writer=dict(_blk, legacy_attempts=len(_sp["legacy"])))
            m["Build.history"] = whist.cell(aid, h, r["has_writer"], files)      # SS window: the attempts since the code / registry identity last changed

        if r["depends_on"] and _static is not None and (m.get("Build.dag") or {}).get("v") == PASS and (m["Build.dag"].get("static_data") or {}).get("static_data") is True:
            # SS 2026-10-05 R-d: migration-seeded static data has no build to wait for its dependency: no liveness requirement (Build.dag, PASS above, checked that the edge exists and is acyclic)
            m["Build.dep_liveness"] = dict(_na(f"static data (declared kind static, has_writer: false; registry row, @register scan and a static_data declaration agree: its named migrations exist on main and create/seed the declared table): the {len(r['depends_on'])} declared "
                                               "edge(s) exist (Build.dag) and have no liveness requirement (SS R-d)", "static-data-existence-only"), no_writer=_static)
        else:
            m["Build.dep_liveness"] = (_grade_dep_liveness(r["depends_on"], deprec, CHART_ID, dep_causes(r["depends_on"]), dep_kinds) if r["depends_on"]
                                       else _grade_dep_liveness_none(m.get("Build.dag"), scanned=bool(files)))

        m["Complete.width"] = dict(v=NOT_GENERIC, measured="no declared universe for this asset — declaring one is the first width gap")
        # E6 item (f): Carr.D1-D3 `no-carriage` candidates, only for an asset that DECLARES terminal_by_construction
        _decl_entry = (declarations or {}).get(aid) if isinstance(declarations, dict) else None
        _ledger_types, _ledger_prose = _carriage_ledger_inputs(_decl_entry, r["target_table"])
        m.update(carriage_declared_checks(aid, (_decl_entry or {}).get("carriage"), r["target_table"],
                                          chart_scoped="chart_id" in (_target_columns_fact(r["target_table"], cat) or ()),
                                          column_types=_ledger_types, prose_columns=_ledger_prose,
                                          asset_rows=live if isinstance(live, int) and not isinstance(live, bool) else None,
                                          source=(_decl_entry or {}).get("source")))
        m.update(carr_checks(dict(declared_facts(declarations, aid), blocking_radius=radius.get(aid),
                                  measured_served=m["Dens.served"]["v"])))
        if "Reach.fields" not in m:
            m["Reach.fields"] = dict(v=NOT_GENERIC, measured=("no target table in production to census at field level"
                                                              if tbl else "no target_table declared: no table to census "
                                                                          "at field level"))

        stamp_read_scope(m, _rscopes)
        set_read_scope(None)
        br = radius.get(aid)
        assets.append(dict(asset_id=aid, layer=layer_key, scoring=cfg["scoring"], live_rows=live,
                           reach=reach,
                           blocking_radius=(dict(br, basis="active assets depending on it, transitively, every layer")
                                            if br else dict(transitive=None, direct=None, severity_weight=None,
                                                            basis=radius_note or "unmeasured: not in the active "
                                                                                 "dependency graph")),
                           live_rows_basis=(basis if live is not None else None), count_sql_tables=ctables,
                           target_table=tbl, has_writer=r["has_writer"], writer_files=files,
                           catalog_status=r["catalog_status"],
                           # E6.1 packet 2a: applicability FACTS for the rollup (additive; no measurement reads them)
                           target_columns=_target_columns_fact(tbl, cat),
                           # N-150: the column data types the R1 schema check read (information_schema data_type); None = unknown. Additive: no criterion reads it from the record.
                           target_column_types=((cat.get("types") or {}).get(tbl) if tbl and cat.get("types") is not None and _target_columns_fact(tbl, cat) is not None else None),
                           asset_kind=(r["asset_kind"].strip() if isinstance(r["asset_kind"], str) and r["asset_kind"].strip()
                                       else None),
                           # DECLARED, not runnable/meaningful: a true value (even `SELECT 0`, the R46 trap) is no
                           # evidence for Count.floor or Build.completion; it says only that count_sql is non-blank.
                           count_sql_declared=bool((r["count_sql"] or "").strip()),
                           measurements=m))

    extra = sorted(set(regd) - known)
    never = [a["asset_id"] for a in assets if a["measurements"]["Build.exercised"]["v"] == FAIL]
    # R15/R29 (hand_row_provenance.py): `generated` below IS the census_run_id a hand-written gap/
    # opportunity/disposition row is required to carry — no second identifier is invented. Everything
    # MEASURABLE belongs to this function; a hand row records only its judgement plus which run of
    # THIS output it was judged against.
    return dict(generated=dt.datetime.now().astimezone().isoformat(timespec="seconds"), layer=layer_key,
                layer_name=cfg["name"], scoring=cfg["scoring"], n_assets=len(assets),
                # R220: the population this census measured, stated explicitly — `n_assets` above IS
                # the active population (`registry()` already excludes inactive/dead rows), but the
                # gap between it and the layer's raw registry row count must never be silent.
                population_active=population["active"], population_registry_total=population["registry_total"],
                population_excluded_inactive=population["excluded_inactive"],
                # R231: the chart every `$1` count_sql was bound to, and how many were.
                chart_scope=CHART_ID,
                chart_scoped_count_sql=sum(1 for r in reg_all.values() if _chart_scoped(r["count_sql"])),
                # E1.9/F4: a scoped run's build history covers the scoped ids only, so its layer-wide run counts would
                # describe the scope, not the layer — omitted there (the unscoped key order and values are unchanged).
                **({} if assets_sel is not None else dict(global_runs=hist["global_runs"],
                                                          global_runs_touching_layer=hist["global_with_layer"])),
                never_exercised_with_writer=never,
                registered_ids=len(regd), registry_has_writer=sum(1 for r in reg_all.values() if r["has_writer"]),
                phantom_registered=extra, local_map_candidates=lmaps, assets=assets,
                **({} if assets_sel is None else dict(scope=dict(assets=assets_sel, partial=True))))


# D4 ruling (DECISIONS_RECOMMENDATIONS_v2_0.md): the verdict a check can return keeps growing
# (NOT_GENERIC today; R41's per-check fault isolation adds an "errored" state; an unmeasured
# criterion is silently absent from `measurements` and never reaches this function at all). A
# gap closes on an EXPLICIT allowlist, never on "whatever isn't in the failing tuple" — the sandbox
# port's own defect (D4 finding #6): closing on "any other verdict" would close on NOT_GENERIC too.
CLOSABLE = (PASS, NA)
FAILING = (FAIL, PARTIAL, NO_DET)
# A gap row's own state vocabulary (asset_gaps.jsonl `_schema`): OPEN and IN_PROGRESS are both
# live/unresolved (D4: "an IN_PROGRESS row transitions on PASS" exactly like an OPEN one); CLOSED
# is resolved; anything else (WITHDRAWN, or a state string this script has never written) is left
# alone rather than re-opened by inference.
LIVE_GAP_STATES = ("OPEN", "IN_PROGRESS")
# E6.4 (N-97(4)): the four NON-GATE families (not among CELL_GATES: the reader's `info_families`) are measurements, never gaps. The
# ledger rows they once opened were re-keyed `kind: info` by ledger_e6_4_info_rekey.py; so that a later emit cannot open them again (a new
# asset, or a CLOSED row that regresses), a FAILING verdict on one of these families appends no OPEN / RE-OPEN row. Stricter only: closure
# by PASS / released N/A, retirement, every gate criterion and every other family are unchanged.
INFO_ONLY_GATES = ("Cost", "Count", "Complete", "Reach")


def _na_released(crit: str, rec: dict, all_meas=None, layer=None, facts=None) -> bool:
    """May this measured record CLOSE a gap? True only for a verdict PASS, or for an N/A whose cause is a
    registered cause of `crit` (NA_CAUSES) AND whose rule id `<crit>#measured:<cause>` is declared in
    NA_RULE_DECISIONS — the same release the rollup applies (`_check_contribution`). Any other N/A (no cause, a
    malformed or unregistered cause, a registered cause no rule declares) is what the rollup reads NO_DETECTOR,
    and closing a ledger row on it would record a closure the cell itself refuses (CLAUDE.md §N.8)."""
    v = rec.get("v")
    if v == PASS:
        return True
    if v != NA:
        return False
    cause = rec.get("cause")
    if not (isinstance(cause, str) and _CAUSE_SLUG.fullmatch(cause)):
        return False
    if not (cause in NA_CAUSES.get(crit, ()) and f"{crit}#measured:{cause}" in NA_RULE_DECISIONS):
        return False
    if no_writer_na_problem(crit, rec):            # N-150 R5: a no-writer N/A closes a ledger row only with the declaration and the agreeing facts
        return False
    if update_only_na_problem(crit, rec):          # SS 2026-10-05: an update-only N/A closes a ledger row only with the declaration and the agreeing scan
        return False
    if no_table_na_problem(crit, rec):             # SS 2026-10-05: a no-table N/A closes a ledger row only with the declaration and the agreeing facts
        return False
    if vocab_values_na_problem(crit, rec):         # N-176: a no-vocabulary-values N/A closes a ledger row only with its checked bounded value reading
        return False
    if unsourced_declared_na_problem(crit, rec):   # N-177: an unsourced-declared N/A closes a ledger row only with its verified residual block
        return False
    if lint_na_problem(crit, rec):                 # N-150 R2: a lint-not-applicable N/A closes a ledger row only with the scan's agreement
        return False
    if prose_none_na_problem(crit, rec, facts):    # N-150 R1: a no-prose N/A closes a ledger row only with its checked prose_none block
        return False
    if crit.startswith("Narr.") and (rec.get("prose_coupling") is not None or (isinstance(facts, dict) and (facts.get("declared_prose_coupling") is not None
                                                                                                          or facts.get("declared_prose_coupling_missing") is True))):
        # NARR-GUARD (pin 16): a coupled Narr N/A closes a ledger row only where the rollup would honour it; with no context to read the Carr.D1 cell it is not released
        return all_meas is not None and layer is not None and narr_coupling_problem(crit, layer, rec, facts, all_meas) is None
    return True


def _emit_facts(a: dict, census: dict):
    """The facts `facts_for_asset` derives for asset record `a` from the declarations file (so the ledger reads the same declared coupling the rollup does: a Narr N/A whose
    record dropped its coupling block is not released). None when the declarations file is unreadable: the record's own block is then all the guard has."""
    try:
        decl = load_asset_declarations()
    except DeclarationsError:
        # unreadable declarations: the record's own block is all the guard has -- EXCEPT for an asset whose coupling is REQUIRED (PROSE_COUPLING_REQUIRED), keyed by asset id: no
        # coupling can be shown, so none of its Narr N/A rows is released (E6.1 follow-up, LOW-2; stricter only, every other asset reads None as before)
        return {"declared_prose_coupling_missing": True} if prose_coupling_required_problem(a.get("asset_id") if isinstance(a, dict) else None, None) else None
    return facts_for_asset(a, decl)


def _emit_scope(census: dict, assets) -> frozenset | None:
    """The set of asset ids emit_gaps may write rows for, or None (every asset of the census: an unscoped run).
    Raises ScopeError — before the ledger is touched — on a malformed label, a census that contradicts its own
    label, an empty / duplicate / non-string `assets`, or an `assets` entry the census did not measure."""
    label = census_scope(census)
    present = {a["asset_id"] for a in census["assets"]}
    scope = None
    if label is not None:
        scope = frozenset(label["assets"])
        stray = sorted(present - scope)
        if stray:
            raise ScopeError(f"the census is labelled scoped to {sorted(scope)} but holds measurements for "
                             f"{', '.join(stray)}: refusing to emit (nothing written)")
    if assets is not None:
        want = list(assets)
        if not want or len(set(want)) != len(want) or any(not isinstance(x, str) or not x for x in want):
            raise ScopeError(f"emit scope must be a non-empty list of distinct asset ids, got {want!r}")
        unmeasured = sorted(set(want) - present)
        if unmeasured:
            raise ScopeError(f"emit scope names asset(s) this census did not measure: {', '.join(unmeasured)}")
        scope = frozenset(want) if scope is None else scope & frozenset(want)
    return scope


# ── E6 / SS ruling N-100: the withholding list, enforced INSIDE the one ledger writer ──────────────────────────
# `NIKASHA_WITHHOLDING.json` (beside the ledger, E5.2 / PR #3012) names (asset, criterion) cells whose PASS is
# unearned. nikasha_fold.py strips them from the census before calling emit_gaps_summary, but a direct
# `asset_census.py --emit-gaps` (or any other caller of emit_gaps / emit_gaps_summary) used to bypass that and could
# write a CLOSED (credit) row for a withheld cell. The rule now lives here, where the rows are written: a withheld
# gap id gets NO row of any kind (no OPEN, no RE-OPEN, no CLOSED, no supersede), whatever the cell now measures.
# ABSENT file = no withholding. A PRESENT file that is not a regular file, malformed, not tracked, not at HEAD or
# different from HEAD (its bytes read differ from `git show HEAD:<file>`, or `git diff --quiet HEAD` reports a content,
# mode or staged difference) makes the emit REFUSE before the ledger is opened; so does a file that is tracked at HEAD
# but missing from the work tree (a deleted withholding list must not silently lift every withholding). HEAD is
# whatever is checked out: a COMMITTED weakening of the list on the current branch passes (the same as the fold; the
# list is changed only by a reviewed PR). A staged edit whose work tree was reverted to HEAD's bytes is not detected
# (the bytes read equal HEAD's and the committed content is what is honoured).
# The list is read beside the ledger's CTRL AND beside the real directory of the ledger file (a ledger relocated by
# NIKASHA_CONTROL_DIR that is a symlink to the canonical one is still governed by the canonical list), under the same
# rules in each place; a relocated ledger with more than one hard link is refused when the canonical list exists (a
# hard link cannot be traced to its twin); a plain COPY of the ledger is a separate ledger and stays allowed. An entry
# naming an asset that is not a well-formed asset id of a known layer is refused; one that is well formed but matches
# no measured cell of the emit (a typo that would silently withhold nothing) is reported in `withheld_unmatched`. This reader is deliberately a minimal re-statement of nikasha_fold.load_withholding's schema
# (fold imports this module, so it cannot be imported from here); __tests__/test_e6_emit_gaps_withholding.py pins the
# two to the same verdict whenever nikasha_fold.py exists.
WITHHOLDING_NAME = "NIKASHA_WITHHOLDING.json"
EXIT_WITHHOLDING = 7


class WithholdingRefused(Exception):
    """The withholding list could not be proven good, so the emit was refused: nothing was written."""

    def __init__(self, code: str, message: str):
        super().__init__(f"{code}: {message}")
        self.code = code
        self.message = message


def _wh_no_dup_keys(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise ValueError(f"duplicate object key {k!r}")
        d[k] = v
    return d


def _wh_no_constant(c):
    raise ValueError(f"non-finite constant {c}")


WH_MAX_JSON_DEPTH = 64      # = nikasha_certify.MAX_JSON_DEPTH, which the fold's strict_json_loads applies


def _wh_max_depth(text: str) -> int:
    depth = best = 0
    in_str = esc = False
    for ch in text:
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch in "[{":
            depth += 1
            best = max(best, depth)
        elif ch in "]}":
            depth -= 1
    return best


def _wh_strict_json(text: str):
    if _wh_max_depth(text) > WH_MAX_JSON_DEPTH:
        raise ValueError(f"nesting deeper than {WH_MAX_JSON_DEPTH}")
    try:
        return json.loads(text, object_pairs_hook=_wh_no_dup_keys, parse_constant=_wh_no_constant)
    except RecursionError as exc:
        raise ValueError("nesting too deep") from exc


def _wh_git(top, *args) -> subprocess.CompletedProcess:
    try:
        return subprocess.run(["git", "-C", str(top), *args], capture_output=True, timeout=30, env=_git_env(), shell=False)
    except (OSError, subprocess.SubprocessError) as exc:
        raise WithholdingRefused("withholding_git_unavailable", f"git could not run ({type(exc).__name__}): the "
                                 "withholding list cannot be proven tracked and clean at HEAD") from None


def _wh_validate(raw: bytes) -> dict:
    try:
        data = _wh_strict_json(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise WithholdingRefused("withholding_malformed", f"{WITHHOLDING_NAME} is not strict JSON ({exc})") from None
    if not isinstance(data, dict) or data.get("version") != 1 or not isinstance(data.get("entries"), dict):
        raise WithholdingRefused("withholding_malformed", "expected {'version': 1, 'entries': {<asset>-<criterion>: {...}}}")
    for key, e in data["entries"].items():
        if not isinstance(e, dict):
            raise WithholdingRefused("withholding_malformed", f"entry {key!r} is not an object")
        asset, crit = e.get("asset"), e.get("criterion")
        if not (isinstance(asset, str) and asset and isinstance(crit, str) and crit):
            raise WithholdingRefused("withholding_malformed", f"entry {key!r} needs a non-empty asset and criterion")
        if not (_ASSET_ID.fullmatch(asset) and any(asset.startswith(v["prefix"]) for v in LAYERS.values())):
            raise WithholdingRefused("withholding_unknown_asset", f"entry {key!r}: {asset!r} is not a well-formed asset id of a known "
                                     "layer (lower-case, <layer prefix>_...): a case variant or typo would silently withhold nothing")
        if key != f"{asset}-{crit}":
            raise WithholdingRefused("withholding_malformed", f"entry key {key!r} is not <asset>-<criterion> = {asset}-{crit}")
        if crit not in CRITERION_REGISTRY:
            raise WithholdingRefused("withholding_unknown_criterion", f"entry {key!r}: {crit!r} is not a registry criterion "
                                     "(a typo would silently withhold nothing; a retired criterion cannot be withheld)")
        for f in ("reason", "condition", "decided_by"):
            if not (isinstance(e.get(f), str) and e[f].strip()):
                raise WithholdingRefused("withholding_malformed", f"entry {key!r} needs a non-empty {f}")
        rr = e.get("register_row")
        if rr is not None and not (isinstance(rr, str) and re.fullmatch(r"R\d+", rr)):
            raise WithholdingRefused("withholding_malformed", f"entry {key!r}: register_row {rr!r} is not R<number>")
    return data["entries"]


def _wh_git_ancestor(d: Path) -> bool:
    """True when `d` or one of its ancestors holds a `.git` entry (it sits inside a git checkout, so "git cannot answer"
    is not the same as "not a repository")."""
    real = Path(os.path.realpath(d))
    return any(os.path.lexists(q / ".git") for q in (real, *real.parents))


def _load_withholding_dir(dirpath) -> dict:
    """The entries of `<dirpath>/NIKASHA_WITHHOLDING.json` ({} when absent), under the fail-closed rules described above."""
    p = Path(dirpath) / WITHHOLDING_NAME
    present = os.path.lexists(p)
    if not present and not p.parent.is_dir():
        return {}
    try:
        r = _wh_git(p.parent, "rev-parse", "--show-toplevel")
    except WithholdingRefused:
        if present or _wh_git_ancestor(p.parent):
            raise                       # a file we cannot prove clean, or a checkout whose git will not answer: refuse
        return {}                       # absent file, not in a checkout, no git: nothing to prove deleted
    if r.returncode != 0:
        if present:
            raise WithholdingRefused("withholding_not_in_git", f"{WITHHOLDING_NAME} is present but not inside a git work tree: "
                                     "it cannot be proven tracked and clean at HEAD")
        if _wh_git_ancestor(p.parent):
            raise WithholdingRefused("withholding_git_unavailable", "git cannot answer for a directory inside a git checkout: "
                                     "a deleted withholding list could not be detected")
        return {}                       # absent and not a repo: no withholding
    top = Path(os.path.realpath(r.stdout.decode("utf-8", "replace").strip()))
    real_dir = Path(os.path.realpath(p.parent))
    if not real_dir.is_relative_to(top):
        raise WithholdingRefused("withholding_not_in_git", "the control directory is outside its own git toplevel")
    rel = (real_dir / WITHHOLDING_NAME).relative_to(top).as_posix()
    tracked = _wh_git(top, "ls-files", "--error-unmatch", "--", rel).returncode == 0
    if not present:
        if tracked or _wh_git(top, "cat-file", "-e", f"HEAD:{rel}").returncode == 0:
            raise WithholdingRefused("withholding_deleted", f"{rel} is tracked but missing from the work tree: a deleted "
                                     "withholding list must not silently lift every withholding")
        return {}
    if p.is_symlink() or not p.is_file():
        raise WithholdingRefused("withholding_not_regular_file", f"{rel} is not a regular file")
    try:
        raw = p.read_bytes()
    except OSError as exc:
        raise WithholdingRefused("withholding_unreadable", f"{rel} cannot be read ({type(exc).__name__})") from None
    if not tracked:
        raise WithholdingRefused("withholding_untracked", f"{rel} is not tracked by git: an untracked withholding list is not a reviewed one")
    head = _wh_git(top, "show", f"HEAD:{rel}")
    if head.returncode != 0:
        raise WithholdingRefused("withholding_not_at_head", f"{rel} has no committed version at HEAD (no HEAD, or a shallow/odd checkout)")
    if _wh_git(top, "diff", "--quiet", "HEAD", "--", rel).returncode != 0:
        raise WithholdingRefused("withholding_dirty", f"{rel} differs from HEAD (a content, mode or staged difference): commit it before emitting")
    if head.stdout != raw:
        raise WithholdingRefused("withholding_dirty", f"{rel}: the bytes read differ from the committed bytes at HEAD "
                                 "(git is not reporting the change: assume-unchanged / skip-worktree?)")
    return _wh_validate(raw)


def load_withholding_entries() -> dict:
    """{gap_id: entry} for the withholding list beside the ledger (`CTRL / NIKASHA_WITHHOLDING.json`) and, when the ledger
    file really lives elsewhere (a symlink, or a symlinked directory), beside its real directory too; {} when absent,
    WithholdingRefused when a list is present (or tracked) and not provably good, or when a relocated ledger has more than
    one hard link while the canonical list exists. Never writes."""
    ledger = CTRL / "asset_gaps.jsonl"
    here = Path(os.path.realpath(CTRL))
    dirs = [CTRL]
    real = Path(os.path.realpath(ledger)).parent
    if real != here:
        dirs.append(real)
    canonical = Path(os.path.realpath(ROOT / "00_ARCHITECTURE" / "control"))
    if here != canonical and os.path.lexists(canonical / WITHHOLDING_NAME):
        try:
            nlink = os.stat(ledger).st_nlink
        except OSError:
            nlink = 1                   # no ledger yet (or unreadable: the append will fail on its own)
        if nlink > 1:
            raise WithholdingRefused("withholding_ledger_hardlinked", f"{ledger} has {nlink} hard links and the canonical "
                                     "withholding list exists: a hard link cannot be traced to its twin, so the ledger is not provably governed")
    out: dict = {}
    for d in dirs:
        out.update(_load_withholding_dir(d))
    return out


def emit_gaps_summary(census: dict, assets=None) -> dict:
    """Append-only ledger with deterministic ids (`<asset>-<criterion>`), closing by measurement.

    D4 ruling (R57 amended), each an acceptance case with its own test in
    __tests__/test_a2_emit_gaps_closure.py:

    - CLOSED only on `PASS` or an explicitly justified `N/A` — never on `NOT_GENERIC`, `UNKNOWN`,
      an errored check, or an unmeasured criterion (i.e. anything outside CLOSABLE is a no-op,
      not an implicit close). "Explicitly justified" is `_na_released`: a registered cause AND a declared
      `<crit>#measured:<cause>` rule. Any other N/A is treated exactly like the rollup's NO_DETECTOR: it
      does not close, it opens (or keeps open) a NO_DETECTOR-type gap whose `what` names why it was not released.
    - check failing (FAIL/PARTIAL/NO_DETECTOR), no row with this gap_id yet     -> append OPEN
    - check failing, latest row OPEN or IN_PROGRESS                            -> skip (already open)
    - check failing, latest row CLOSED                                        -> append OPEN
      ("RE-OPENED by measurement" — the defect regressed; a loop that only counts up is not a loop)
    - check failing, latest row WITHDRAWN (or any other terminal state this script never wrote)
      -> nothing to do; WITHDRAWN is a terminal, human decision (F4, A_REVIEW.md) and is "left
      alone rather than re-opened by inference" exactly as documented below — the code used to
      contradict this comment by re-opening WITHDRAWN rows too.
    - check failing on an INFO-ONLY family (`INFO_ONLY_GATES`: Cost, Count, Complete, Reach; E6.4, N-97(4)),
      whatever the prior row (none, CLOSED, ...)                                -> nothing appended: these are
      measurements, not gaps (their old rows were re-keyed `kind: info`). Counted in the summary's
      `info_only_suppressed` (present only when non-zero), never in `skipped`. A criterion matches when it begins
      `<family>.` exactly (the migration's prefixes): `Completeness.*`, `Costly.*`, `Counter.*`, a bare `Reach` are NOT suppressed.
    - check closable (PASS/N-A) now, latest row OPEN or IN_PROGRESS            -> append CLOSED
      (closure BY MEASUREMENT: the same detector now passes; the row quotes the new measured value)
    - check closable, latest row CLOSED or no row                             -> nothing to do
    - a row carrying `superseded_by` (R80) is a dead identity — never touched, never resurrected,
      regardless of what the census currently measures for that gap_id, and regardless of any
      LATER row for the same gap_id that omits the flag (F5, A_REVIEW.md): once superseded, always
      superseded — the flag is checked across the id's whole history, not only its latest row.
    - hand `change`/`owner`/`gate` are CARRIED FORWARD from the prior row onto every transition
      row (CLOSED or RE-OPENED); only a gap_id's very first OPEN row uses the census's own
      defaults, because there is no prior hand annotation yet to carry.
    - RETIRED criteria (E6 item i; `RETIRED_CRITERIA`): a criterion removed from the registry is never measured, so
      no measurement can close its rows. Every row whose gap_id is EXACTLY the deterministic `<asset>-<criterion>`
      (asset = the row's own `asset`; the row's `criterion` field is not consulted, so a row that lacks it is still
      found and a hand row such as `bg_a-G05` that merely names the criterion is never touched), whose `kind` is
      `gap` (or absent) and whose latest state is OPEN or IN_PROGRESS gets one appended CLOSED row. That row's
      `what` records the retirement, its registry revision, the deciding ruling and the reason, it carries
      `closed_by: "retirement"` and `retired_criterion` (so it is distinguishable from a closure by measurement),
      and hand `change`/`owner`/`gate` are carried forward. It is CLOSED, not WITHDRAWN: WITHDRAWN is a human
      rejection. A live row of any other kind (`opportunity`) is NOT closed — a retirement does not realise an
      opportunity — and is counted in the summary's `retired_opportunity_rows_left`. Closure applies to every
      asset in the ledger whatever layer this run measured — EXCEPT in a SCOPED run (see SCOPE below), which closes
      only the rows of in-scope assets and neither closes nor counts any other asset's row; it counts in `closed`, is
      idempotent, and never touches a CLOSED, WITHDRAWN or superseded id. A retired criterion never opens a gap, even if a stray measurement names it.
    Rows whose gap_id is not a deterministic `<asset>-<criterion>` id (hand-written rows with no
    detector binding, R58) are never touched by this function at all — no census criterion will
    ever produce that gap_id, so `latest` simply never matches them.

    LIMIT (F12, A_REVIEW.md item 4 — disclosed, not detected): "latest" means last in FILE order,
    not by `ts`. For one append-only file that is the truth. A git merge of two branches that both
    appended to the ledger concatenates their rows in merge order, so a stale CLOSED can land after a
    newer OPEN for the same gap_id and be read as current. Neither this function nor the tracker
    detects that; re-running the census after such a merge re-measures and appends the correct
    transition.

    WITHHOLDING (SS ruling N-100). A (asset, criterion) cell whose gap id `<asset>-<criterion>` is an entry of
    `CTRL/NIKASHA_WITHHOLDING.json` gets NO row of any kind: no OPEN, no RE-OPEN, no CLOSED credit, no supersede, even
    when the cell now reads PASS/N-A and an OPEN row exists; the suppressed ids come back in the summary's `withheld`
    (present only when the list has entries); entries that matched no measured cell of the emit come back in
    `withheld_unmatched` (only when non-empty). The withholding check runs BEFORE the superseded and info-only (E6.4) checks: a withheld cell on an info-only family is reported in `withheld`, never in `info_only_suppressed`. An absent file changes nothing; a present file that is malformed,
    untracked, not at HEAD, or different from HEAD raises WithholdingRefused before the ledger is opened (see
    `load_withholding_entries` and the N-100 comment above it for exactly what "different" means and which lists are read). A scoped run applies the same filter. Withholding never touches RETIRED_CRITERIA closure:
    a withheld criterion must be a registry criterion, and the two sets are disjoint (import-time check).

    SCOPE (E1.9). A census carrying `scope` (a scoped measure()), and/or `assets=[...]`, restricts the emit to those
    assets: no row of any other asset is read for a decision, appended, closed, withdrawn or reopened, and the file
    is only ever APPENDED to, so every pre-existing row stays byte-identical and in order (this includes the
    retired-criterion closure above: an out-of-scope asset's OPEN row of a retired criterion is left OPEN). The scope is checked
    before the ledger is opened: a census whose assets contradict its own scope label, an `assets` entry the census
    never measured, an empty list or a malformed label raises ScopeError and writes nothing.
    """
    scope = _emit_scope(census, assets)
    validate_na_rule_decisions()
    withheld = load_withholding_entries()       # N-100: raises WithholdingRefused BEFORE the ledger is opened or read
    suppressed: set[str] = set()
    seen: set[str] = set()          # every (asset, criterion) cell this emit looked at, whatever its verdict
    path = CTRL / "asset_gaps.jsonl"
    latest: dict[str, dict] = {}
    # F5 (A_REVIEW.md, non-blocking correction): `superseded_by` must be a PERMANENT flag on the
    # identity, not just a property of whichever row happens to be latest. Checking only
    # `latest.get(gid)` meant a superseded id could be resurrected the instant any later row
    # (hand-written or otherwise) omitted the flag — demonstrated: an early superseded_by row
    # followed by a later plain row re-opened/re-closed the "dead" id. `ever_superseded` is set
    # once any row for a gid ever carried the flag, and stays set regardless of what follows.
    ever_superseded: set[str] = set()
    if path.exists():
        for ln in path.read_text(encoding="utf-8").split("\n"):
            if ln.strip():
                try:
                    r = json.loads(ln)
                except json.JSONDecodeError:
                    continue
                if r.get("gap_id"):
                    latest[r["gap_id"]] = r  # append-only: last row for an id wins
                    if r.get("superseded_by"):
                        ever_superseded.add(r["gap_id"])
    ts = dt.datetime.now().astimezone().isoformat(timespec="seconds")
    added = skipped = closed = reopened = retired_opps_left = info_suppressed = 0
    with path.open("a", encoding="utf-8") as f:
        # E6 item i: close the OPEN rows of retired criteria (see the docstring); in ledger order, before this run's
        # measurements, and only for gap_ids no measurement below can touch (a retired crit is skipped there).
        for gid, prior in list(latest.items()):
            asset_of = prior.get("asset")
            if scope is not None and asset_of not in scope:
                continue  # E1.9 F1: a scoped run never closes (or counts) another asset's row, retired criterion or not
            crit = next((c for c in RETIRED_CRITERIA if isinstance(asset_of, str) and gid == f"{asset_of}-{c}"), None)
            if crit is None or gid in ever_superseded:
                continue
            ret = RETIRED_CRITERIA[crit]
            if str(prior.get("state", "OPEN")).upper() not in LIVE_GAP_STATES:
                continue
            if str(prior.get("kind", "gap")).lower() != "gap":
                retired_opps_left += 1      # an opportunity is not realised by a retirement: left as is, reported
                continue
            f.write(json.dumps(dict(
                asset=asset_of, gap_id=gid, kind="gap", criterion=crit,
                what=(f"CLOSED by retirement of criterion {crit} (registry revision {ret['retired_in_revision']}; "
                      f"{ret['decision']}): {ret['reason']} / required: nothing — the criterion is no longer part "
                      f"of the {crit.split('.')[0]} gate"),
                change=prior.get("change", ""), detector=f"asset_census.py RETIRED_CRITERIA ({crit})",
                owner=prior.get("owner", "asset_census"),
                gate=prior.get("gate", "this asset's certification"), state="CLOSED", ts=ts,
                closed_by="retirement", retired_criterion=crit),
                ensure_ascii=False) + "\n")
            closed += 1
        for a in census["assets"]:
            if scope is not None and a["asset_id"] not in scope:
                continue  # E1.9: an asset outside the scope is never decided about, never written
            for crit, res in a["measurements"].items():
                seen.add(f"{a['asset_id']}-{crit}")
                if crit in RETIRED_CRITERIA:
                    continue  # a retired criterion never opens, re-opens or closes by measurement
                v = res["v"]
                if v not in FAILING and v not in CLOSABLE:
                    continue  # NOT_GENERIC / UNKNOWN / errored / anything future: never a transition
                if v == NA and not _na_released(crit, res, a["measurements"], a.get("layer") or census.get("layer"), _emit_facts(a, census)):
                    # §N.8: the ledger records closure, so it may not honour an N/A the rollup refuses.
                    res = dict(res, measured=f"NO_DETECTOR — measured N/A not released by a declared rule "
                                             f"(cause={res.get('cause')!r}): {res['measured']}")
                    v = NO_DET
                gid = f"{a['asset_id']}-{crit}"
                if gid in withheld:
                    suppressed.add(gid)
                    continue    # N-100: a withheld cell gets no row of any kind, whatever it measures and whatever is open
                prior = latest.get(gid)
                if gid in ever_superseded:
                    continue  # a superseded id is never resurrected, whatever is measured now,
                              # and whatever any LATER row (with no superseded_by of its own) says
                if v in FAILING and crit.startswith(tuple(g + "." for g in INFO_ONLY_GATES)):
                    info_suppressed += 1        # its own counter: NOT `skipped` (the CLI prints that as "already present")
                    continue  # E6.4: an info-only family is measured, never opened as a gap (no OPEN, no RE-OPEN)
                prior_state = (prior or {}).get("state", "OPEN").upper()
                # Carry hand metadata forward; only the very first OPEN row for a gid has none
                # to carry, so it alone falls back to the census's own defaults.
                change = prior.get("change", "") if prior else ""
                owner = prior.get("owner", "asset_census") if prior else "asset_census"
                gate = prior.get("gate", "this asset's certification") if prior else "this asset's certification"
                # R21: a Build gap carries its asset's blocking radius as its severity — measured by this
                # census run, never carried from a prior row (the DAG moves) and never invented (an
                # unmeasured radius is null with its reason, not 0).
                sev = {}
                if crit.startswith("Build.") and isinstance(a.get("blocking_radius"), dict):
                    br = a["blocking_radius"]
                    sev = dict(blocking_radius=br.get("transitive"), severity_weight=br.get("severity_weight"))
                    if br.get("transitive") is None:
                        sev["blocking_radius_note"] = br.get("basis", "unmeasured")
                if v in FAILING:
                    if prior is None:
                        f.write(json.dumps(dict(
                            asset=a["asset_id"], gap_id=gid, kind="gap", criterion=crit,
                            what=f"measured: {res['measured']} / required: the {crit.split('.')[0]} gate's claim",
                            change=change, detector=f"asset_census.py --layer {census['layer']} ({crit})",
                            owner=owner, gate=gate, state="OPEN", ts=ts, **sev), ensure_ascii=False) + "\n")
                        added += 1
                    elif prior_state in LIVE_GAP_STATES:
                        skipped += 1
                    elif prior_state == "CLOSED":  # regression re-opens
                        f.write(json.dumps(dict(
                            asset=a["asset_id"], gap_id=gid, kind="gap", criterion=crit,
                            what=f"RE-OPENED by measurement: {res['measured']} / required: the {crit.split('.')[0]} gate's claim",
                            change=change, detector=f"asset_census.py --layer {census['layer']} ({crit})",
                            owner=owner, gate=gate, state="OPEN", ts=ts, **sev), ensure_ascii=False) + "\n")
                        reopened += 1
                    else:
                        # F4 (A_REVIEW.md): WITHDRAWN (or any other terminal state this script
                        # never assigned) is a human, out-of-band decision — left alone rather than
                        # re-opened by inference, matching this function's own documented contract.
                        skipped += 1
                else:  # v in CLOSABLE
                    if prior is not None and prior_state in LIVE_GAP_STATES:
                        f.write(json.dumps(dict(
                            asset=a["asset_id"], gap_id=gid, kind="gap", criterion=crit,
                            what=f"CLOSED by measurement: {res['measured']} / required: the {crit.split('.')[0]} gate's claim",
                            change=change, detector=f"asset_census.py --layer {census['layer']} ({crit})",
                            owner=owner, gate=gate, state="CLOSED", ts=ts, **sev), ensure_ascii=False) + "\n")
                        closed += 1
                    # else: no prior, or prior already CLOSED/terminal — nothing to do (idempotent)
    out = dict(added=added, skipped=skipped, closed=closed, reopened=reopened,
               retired_opportunity_rows_left=retired_opps_left,
               **({"info_only_suppressed": info_suppressed} if info_suppressed else {}))
    if withheld:
        out["withheld"] = sorted(suppressed)    # only present when a withholding list is in force: the absent-file result is unchanged
        unmatched = sorted(g for g, e in withheld.items() if g not in seen and (scope is None or e["asset"] in scope))
        if unmatched:
            out["withheld_unmatched"] = unmatched   # entries that matched no measured cell of this emit (a typo withholds nothing)
    return out


def emit_gaps(census: dict, assets=None) -> tuple[int, int, int, int]:
    """`emit_gaps_summary` as the historical (added, skipped, closed, reopened) tuple; see its docstring."""
    r = emit_gaps_summary(census, assets)
    return r["added"], r["skipped"], r["closed"], r["reopened"]


# ─────────────────────────── E6.5: --registry-check (registry-only coverage report) ───────────────────────────
# Offline by construction: reads CRITERION_REGISTRY / NA_RULE_DECISIONS / NA_CAUSES and this file's own source, never psql. The
# report answers one question per core gate x layer cell: does every REQUIRED criterion have a REGISTRY-DECLARED detector? That is a
# registry label and says nothing about whether the detector emits a verdict for any given asset (Carr.D1 is declared for every
# layer yet emitted for the few assets that declare a carriage check). A declared N/A rule is CONDITIONAL (cause- or pattern-keyed:
# it releases only the assets whose measurement or declaration says so), so it never covers a detector-NONE criterion for the assets
# it does not release; rules are listed, never counted as coverage (§N.8). A criterion declared per-asset-pending is excluded from
# `uncovered_required_criteria` but is NOT counted covered: 54 of 54 is reachable only by real detectors.
REGISTRY_COVERAGE_REPORT_REL = "00_ARCHITECTURE/control/registry_coverage_report.json"
REGISTRY_COVERAGE_SCHEMA = 2
EXPECTED_GATE_LAYER_CELLS = 54          # SS ruling N-97(1): the pinned unit is gate x layer (9 x 6); 150 and 1143 are information
# The CLOSED set of detector bindings a registry entry may carry. Anything else (a typo, "bogus") is refused, never counted as a detector.
KNOWN_DETECTORS = ("NONE", "asset_census.py:measure()")
_DECISION_ID = re.compile(r"N-[0-9]{1,6}")
# E6.5 hook for "required, per-asset detector pending" criteria (plan 2.1): criterion id -> decision id ('N-<n>'). Empty today and NOT
# fingerprinted content (no revision bump): a later, separate file feeds it. Until then those criteria are reported UNCOVERED. The
# report carries the decision per criterion (`per_asset_pending_decisions`), so the hook's contents are part of the checked bytes.
PER_ASSET_PENDING: dict[str, str] = {}
# SS N-102 (owner decision): the six L0 assets the OWNER deferred on Carr (their classical sources are not held). They live in a small
# committed input file, never in this module, but the loader pins the gate, the ruling and the EXACT id set: a free-form list would be a
# masking vector, so a further deferral needs a new ruling AND a change here. Schema (schema 1): {"schema": 1, "deferrals":
# [{"asset_id", "criterion_gate", "decision", "state"}]}; every id an ACTIVE asset of the committed registry seed (the same offline
# source the E6.3 reader uses; the seed is a stand-in for the live registry); no other key, no duplicate. A malformed entry, an
# unknown / inactive id, a different gate / ruling / state or a missing or extra id refuses the whole --registry-check.
OWNER_DEFERRAL_GATE, OWNER_DEFERRAL_DECISION = "Carr", "N-102"
OWNER_DEFERRAL_STATE = f"deferred by owner ({OWNER_DEFERRAL_DECISION})"
OWNER_DEFERRAL_IDS = ("bg_gochara_citation_resolution", "bg_kota_chakra_rings", "bg_medical_mappings", "bg_nakshatra_medical",
                      "bg_sign_medical", "bg_vastu_directions")
OWNER_DEFERRALS_PATH = Path(__file__).resolve().parents[3] / "00_ARCHITECTURE" / "control" / "owner_deferrals.json"
REGISTRY_SEED_PATH = Path(__file__).resolve().parents[1] / "seed" / "asset_registry_seed.ts"
_DEFERRAL_KEYS = ("asset_id", "criterion_gate", "decision", "state")
_INSPECTOR_LINE = re.compile(r'("inspector_commit": )(?:"([^"]*)"|null)')


def _inspector_commit() -> str | None:
    """The last commit touching this tool file when the report was generated (a report cannot name the commit that contains it), from
    a scrubbed git environment; None when git cannot say (the generator then refuses: the tracker reads a null commit as an error).
    A provenance pointer, not a reachability claim: after a squash or rebase it may name a commit no longer on any branch, and
    `--check` never compares its value."""
    try:
        here = Path(__file__).resolve()
        p = subprocess.run(["git", "log", "-1", "--format=%H", "--", str(here)], capture_output=True, text=True,
                           timeout=10, env=_git_env(), cwd=str(here.parent), shell=False)
    except (OSError, subprocess.SubprocessError):
        return None
    sha = p.stdout.strip()
    return sha if p.returncode == 0 and _GIT_SHA.fullmatch(sha) else None


_CRIT_LITERAL = re.compile(r"[A-Za-z]+\.[A-Za-z0-9_.]+")


@functools.lru_cache(maxsize=1)
def _emission_sites() -> dict:
    return _emission_sites_from(Path(__file__).read_text(encoding="utf-8"))


def _emission_sites_from(source: str) -> dict:
    """Static registry -> emission parity: {string literal that looks like a criterion id: sorted names of the top-level functions that
    contain it AND are reachable from `measure()` by name (a call or a reference, transitively)}. A criterion whose id appears in no
    such function is never emitted by any code path of the census; one that does is merely EMITTABLE (this says nothing about how many
    assets it is emitted for). `_emission_sites()` reads this file's own source, so it cannot drift from it."""
    tree = ast.parse(source)
    top = {n.name: n for n in tree.body if isinstance(n, ast.FunctionDef)}
    refs = {name: {x.id for x in ast.walk(fn) if isinstance(x, ast.Name) and x.id in top}
            | {x.attr for x in ast.walk(fn) if isinstance(x, ast.Attribute) and x.attr in top} for name, fn in top.items()}
    reach, todo = set(), ["measure"]
    while todo:
        f = todo.pop()
        if f in top and f not in reach:
            reach.add(f)
            todo.extend(refs[f])
    # module-level tuples/lists/sets made only of criterion ids (CARR_D_CHECKS): a reachable function that names one emits those ids
    bundles = {}
    for n in tree.body:
        if (isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name)
                and isinstance(n.value, (ast.Tuple, ast.List, ast.Set)) and n.value.elts
                and all(isinstance(e, ast.Constant) and isinstance(e.value, str) and _CRIT_LITERAL.fullmatch(e.value) for e in n.value.elts)):
            bundles[n.targets[0].id] = [e.value for e in n.value.elts]
    out: dict[str, set] = {}
    for f in reach:
        for x in ast.walk(top[f]):
            if isinstance(x, ast.Constant) and isinstance(x.value, str) and _CRIT_LITERAL.fullmatch(x.value):
                out.setdefault(x.value, set()).add(f)
            elif isinstance(x, ast.Name) and x.id in bundles:
                for v in bundles[x.id]:
                    out.setdefault(v, set()).add(f)
    return {k: tuple(sorted(v)) for k, v in sorted(out.items())}


def _seed_active_asset_ids() -> set[str]:
    """Active asset ids of the committed registry seed, parsed by generate_level_map.parse_seed_text (the E6.3 reader's own source)."""
    import importlib.util
    path = Path(__file__).resolve().parents[3] / "00_ARCHITECTURE" / "control" / "generate_level_map.py"
    spec = importlib.util.spec_from_file_location("_e65_generate_level_map", path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = mod        # registered before exec so any typing/dataclass lookup in that module resolves
    spec.loader.exec_module(mod)
    return {r["asset_id"] for r in mod.parse_seed_text(REGISTRY_SEED_PATH.read_text(encoding="utf-8")) if r["active"]}


def load_owner_deferrals(path=None, registry_ids=None) -> tuple[list[dict], str]:
    """(entries sorted by asset_id, sha256 of the file's bytes). ValueError on anything malformed or off-ruling (the schema above)."""
    p = Path(OWNER_DEFERRALS_PATH if path is None else path)
    try:
        raw = p.read_bytes()
    except OSError as exc:
        raise ValueError(f"owner deferrals file {p.name} cannot be read ({type(exc).__name__}); it is a required input") from exc
    try:
        doc = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError(f"owner deferrals file {p.name} is not valid JSON") from exc
    if not (isinstance(doc, dict) and doc.get("schema") == 1 and isinstance(doc.get("deferrals"), list)):
        raise ValueError(f"owner deferrals file {p.name}: expected an object with schema 1 and a `deferrals` list")
    ids = _seed_active_asset_ids() if registry_ids is None else set(registry_ids)
    out, seen, errs = [], set(), []
    for i, d in enumerate(doc["deferrals"]):
        if not (isinstance(d, dict) and tuple(sorted(d)) == tuple(sorted(_DEFERRAL_KEYS))
                and all(isinstance(d[k], str) and d[k].strip() for k in _DEFERRAL_KEYS)):
            errs.append(f"entry {i}: must be an object with exactly the non-blank string keys {list(_DEFERRAL_KEYS)}")
            continue
        if d["asset_id"] not in ids:
            errs.append(f"entry {i}: {d['asset_id']!r} is not an active registry asset id")
        for key, want in (("criterion_gate", OWNER_DEFERRAL_GATE), ("decision", OWNER_DEFERRAL_DECISION), ("state", OWNER_DEFERRAL_STATE)):
            if d[key] != want:
                errs.append(f"entry {i}: {key} {d[key]!r} must be {want!r} (SS {OWNER_DEFERRAL_DECISION})")
        if d["asset_id"] in seen:
            errs.append(f"entry {i}: duplicate {d['asset_id']}")
        seen.add(d["asset_id"])
        out.append({k: d[k] for k in _DEFERRAL_KEYS})
    if not errs and sorted(seen) != list(OWNER_DEFERRAL_IDS):
        errs.append(f"the deferred set must be exactly {list(OWNER_DEFERRAL_IDS)} (missing {sorted(set(OWNER_DEFERRAL_IDS) - seen)}, "
                    f"extra {sorted(seen - set(OWNER_DEFERRAL_IDS))}); a different set needs a new ruling and a change to this module")
    if errs:
        raise ValueError(f"owner deferrals file {p.name} refused: " + "; ".join(errs))
    return sorted(out, key=lambda d: d["asset_id"]), hashlib.sha256(raw).hexdigest()


def registry_coverage_report(pending=None, deferrals=None, emission=None) -> dict:
    """Deterministic (sorted, no timestamps) registry coverage report; `inspector_commit` is filled by the caller. `pending`
    defaults to PER_ASSET_PENDING, `emission` to the static emission table. Raises ValueError on a registry the inspector cannot read
    (a detector outside KNOWN_DETECTORS, bad N/A ids, a pending entry that is not a core detector-NONE criterion with an 'N-<n>'
    decision, a bad deferrals file)."""
    validate_na_rule_decisions()
    badd = sorted(c for c, e in CRITERION_REGISTRY.items() if e["detector"] not in KNOWN_DETECTORS)
    if badd:
        raise ValueError(f"detector binding outside the closed set {list(KNOWN_DETECTORS)}: {badd!r}")
    deferred, deferred_sha = load_owner_deferrals() if deferrals is None else deferrals
    emission = _emission_sites() if emission is None else emission
    pending = dict(PER_ASSET_PENDING if pending is None else pending)
    core = {c: e for c, e in CRITERION_REGISTRY.items() if e["gate"] in CELL_GATES}
    bad = sorted(c for c in pending if c not in core or core[c]["detector"] != "NONE"
                 or not (isinstance(pending[c], str) and _DECISION_ID.fullmatch(pending[c])))
    if bad:
        raise ValueError(f"per-asset-pending declaration must name a core criterion with detector NONE and an 'N-<n>' decision: {bad!r}")
    rules_by_crit: dict[str, list[str]] = {}
    for rid in sorted(NA_RULE_DECISIONS):
        rules_by_crit.setdefault(rid.partition("#")[0], []).append(rid)
    cells, uncovered = [], set()
    for gate in CELL_GATES:
        for layer in LAYERS:
            req = sorted(c for c, e in core.items() if e["gate"] == gate and layer in e["layers"])
            auto = [c for c in req if core[c]["detector"] != "NONE"]
            none = [c for c in req if core[c]["detector"] == "NONE"]
            pend = [c for c in none if c in pending]
            unc = [c for c in none if c not in pending]
            uncovered.update(unc)
            status = "uncovered" if unc else ("pending" if pend else "covered")
            cells.append(dict(gate=gate, layer=layer, status=status, required=req, auto_measured=auto, detector_none=none,
                              per_asset_pending=pend, uncovered=unc,
                              declared_na_rules=[r for c in req for r in rules_by_crit.get(c, [])]))
    n_cr = sum(len(c["required"]) for c in cells)
    n_none = sum(len(c["detector_none"]) for c in cells)
    undeclared_patterns = sorted(f"{c}#{k}" for c, e in CRITERION_REGISTRY.items() for k in ("columns_any", "asset_kinds")
                                 if e[k] is not None and f"{c}#{k}" not in NA_RULE_DECISIONS)
    undeclared_causes = sorted(f"{c}#measured:{k}" for c, ks in NA_CAUSES.items() for k in ks
                               if f"{c}#measured:{k}" not in NA_RULE_DECISIONS)
    return dict(
        schema=REGISTRY_COVERAGE_SCHEMA,
        registry_revision=REGISTRY_REVISION, registry_fingerprint=registry_fingerprint(), inspector_commit=None,
        inspector_commit_note="the last commit touching asset_census.py when this report was generated; a provenance pointer, not a "
                              "reachability claim (it may be unreachable after a squash or rebase); --check never compares it",
        expected_cells=EXPECTED_GATE_LAYER_CELLS, covered_cells=sum(1 for c in cells if c["status"] == "covered"),
        covered_cells_unit="gate_x_layer cells whose every required criterion has a registry-declared detector (a registry label; says "
                           "nothing about per-asset emission); per-asset-pending cells are reported separately and never counted covered",
        pending_cells=sum(1 for c in cells if c["status"] == "pending"),
        uncovered_required_criteria=sorted(uncovered),
        per_asset_pending=sorted(pending), per_asset_pending_decisions=dict(sorted(pending.items())),
        per_asset_pending_note="declared in PER_ASSET_PENDING (empty until the separate pending file lands; not fingerprinted); "
                               "excluded from uncovered_required_criteria, never counted as covered",
        declared_detector_never_emitted=sorted(c for c, e in CRITERION_REGISTRY.items() if e["detector"] != "NONE" and not emission.get(c)),
        criterion_emission=[dict(criterion=c, detector=CRITERION_REGISTRY[c]["detector"], emitted_by_measure=bool(emission.get(c)),
                                 sites=list(emission.get(c, ()))) for c in sorted(CRITERION_REGISTRY)],
        criterion_emission_note="static reachability from measure(): 'emitted_by_measure' means the id appears in a function measure() reaches; "
                                "it says nothing about how many assets the criterion is emitted for",
        deferred_by_owner=deferred, owner_deferrals_sha256=deferred_sha,
        deferred_by_owner_note="owner-deferred assets (SS N-102): reported apart from `uncovered`; never fail the check, never counted as covered cells",
        na_rules=[dict(rule_id=r, decision=NA_RULE_DECISIONS[r]) for r in sorted(NA_RULE_DECISIONS)],
        na_rules_note="N/A rules are conditional (per asset); listed, never counted as coverage of a detector-NONE criterion",
        undeclared_na_pattern_ids=undeclared_patterns, undeclared_na_causes=undeclared_causes,
        non_core_detector_none=sorted(c for c, e in CRITERION_REGISTRY.items() if e["gate"] not in CELL_GATES and e["detector"] == "NONE"),
        non_core_detector_none_note="the plan's 'no required criterion with detector NONE' is not gate-scoped; a non-core criterion with "
                                    "detector NONE is information here, not uncovered (SS decision, behaviour unchanged)",
        candidate_cell_counts=dict(
            gate_x_layer=dict(total=len(cells), pinned=True, with_auto_detector=sum(1 for c in cells if c["auto_measured"]),
                              fully_covered=sum(1 for c in cells if c["status"] == "covered"),
                              pending_only=sum(1 for c in cells if c["status"] == "pending")),
            core_criterion_x_layer=dict(total=n_cr, pinned=False, auto_measured=n_cr - n_none, detector_none=n_none),
            gate_x_asset=dict(total=None, pinned=False,
                              omitted_reason="no committed registry-wide asset list offline (LEVEL_MAP.json is not committed, "
                                             "FAMILY_ASSETS.json is a 25-asset subset, asset_registry is database-only)")),
        core_gates=list(CELL_GATES), layers=list(LAYERS), cells=cells)


def registry_report_text(report: dict) -> str:
    return json.dumps(report, indent=1, sort_keys=False) + "\n"


def registry_report_problems(report: dict) -> list[tuple[int, str]]:
    """(exit code, message) per gating condition. SS N-97(1): the gate x layer cell count must equal the pinned 54 (EXIT_REG_CELLS);
    a registry-declared detector must be emitted by some code path of measure() (EXIT_REG_PARITY); and no required criterion may stay
    uncovered, i.e. detector NONE and not declared per-asset-pending (EXIT_REG_UNCOVERED, enforced only under --require-covered)."""
    out = []
    n = report["candidate_cell_counts"]["gate_x_layer"]["total"]
    if n != report["expected_cells"] or n != EXPECTED_GATE_LAYER_CELLS:
        out.append((EXIT_REG_CELLS, f"gate x layer cell count {n} != pinned {EXPECTED_GATE_LAYER_CELLS}"))
    if report["declared_detector_never_emitted"]:
        out.append((EXIT_REG_PARITY, "registry-declared detector never emitted by any code path of measure(): "
                    + ", ".join(report["declared_detector_never_emitted"])))
    if report["uncovered_required_criteria"]:
        out.append((EXIT_REG_UNCOVERED, "required criteria with detector NONE and no per-asset-pending declaration: "
                    + ", ".join(report["uncovered_required_criteria"])))
    return out


def registry_report_drift(committed_text: str, fresh_text: str) -> str | None:
    """None when the committed report equals the fresh regeneration byte for byte; otherwise a reason. ONLY the
    `inspector_commit` value is normalised (it names the last commit touching the tool, which a report cannot know about
    itself); it must still be a full git sha. Everything else, formatting included, must be identical."""
    m = _INSPECTOR_LINE.search(committed_text)
    if not m or not _GIT_SHA.fullmatch(m.group(2) or ""):
        return "committed report has no full-sha inspector_commit"
    fresh_norm = _INSPECTOR_LINE.sub(lambda _: m.group(0), fresh_text, count=1)
    if committed_text != fresh_norm:
        return "committed report differs from a fresh regeneration (registry or report format moved): regenerate and commit it"
    return None


def registry_check_main(out_path: str, verify: bool, require_covered: bool = False) -> int:
    """Write (or, with `verify`, check) the report. Exit: 0 clean; EXIT_REG_DRIFT (9) `verify` found drift (DRIFT ONLY: coverage is not
    consulted for the verdict of --check); EXIT_REG_CELLS (10) cell count != 54; EXIT_REG_PARITY (12) a declared detector is never
    emitted; EXIT_REG_UNCOVERED (11) uncovered required criteria, only with `require_covered`; 5 script error."""
    try:
        rep = registry_coverage_report()
        rep["inspector_commit"] = _inspector_commit()
        if rep["inspector_commit"] is None and not verify:
            print("asset_census: registry-check cannot name the inspector commit (git unavailable); refusing to write a "
                  "report the tracker reads as an error", file=sys.stderr)
            return 5
        text = registry_report_text(rep)
    except Exception as exc:  # noqa: BLE001
        print(f"asset_census: registry-check failed — {type(exc).__name__}: {exc}", file=sys.stderr)
        return 5
    if verify:
        try:
            committed = Path(out_path).read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            print(f"asset_census: registry-check --check: cannot read {out_path}: {type(exc).__name__}", file=sys.stderr)
            return EXIT_REG_DRIFT
        why = registry_report_drift(committed, text)
        if why:
            print(f"asset_census: registry-check --check: {why}", file=sys.stderr)
            return EXIT_REG_DRIFT
        print(f"registry report matches a fresh regeneration: {out_path}")
    else:
        try:
            _write_atomic(out_path, text)
        except OSError as exc:
            print(f"asset_census: registry-check could not write {out_path}: {type(exc).__name__}", file=sys.stderr)
            return 5
        print(f"registry coverage report written: {out_path}")
    cc = rep["candidate_cell_counts"]
    print(f"  revision {rep['registry_revision']} · gate x layer {cc['gate_x_layer']['total']} (pinned {rep['expected_cells']}, "
          f"detector-covered {rep['covered_cells']}, pending {rep['pending_cells']}) · core criterion x layer "
          f"{cc['core_criterion_x_layer']['total']} · gate x asset omitted offline · owner-deferred {len(rep['deferred_by_owner'])}")
    codes = []
    for code, msg in registry_report_problems(rep):
        gating = code != EXIT_REG_UNCOVERED or require_covered
        print(f"  {'!!' if gating else '..'} {msg}" + ("" if gating else "  (informational: --require-covered gates it)"))
        if gating:
            codes.append(code)
    return min(codes, key=(EXIT_REG_CELLS, EXIT_REG_PARITY, EXIT_REG_UNCOVERED).index) if codes else 0

def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--layer", default=None, help="default: L0")
    ap.add_argument("--emit-gaps", action="store_true")
    ap.add_argument("--rollup", action="store_true",
                    help="also write the nine-gate cells per asset (key `rollup`) and the non-nine gates as "
                         "information (key `rollup_excluded`) into --out; --emit-gaps neither reads nor changes it")
    ap.add_argument("--assets", action="append", default=None, metavar="ID[,ID...]|@FILE",
                    help="E1.9: measure (and, with --emit-gaps, emit for) ONLY these assets — a comma list, a repeated "
                         "flag, or @file. Every id must be an active registry asset of the selected layer(s). The census "
                         "is labelled SCOPED/partial (`scope`), is written to asset_census_scoped.json unless --out names "
                         "another file, and never replaces the full census file. Exit 6 on a bad scope; nothing is written.")
    ap.add_argument("--registry-check", action="store_true",
                    help="E6.5: registry-only coverage report (no database): per core gate x layer, which required criteria "
                         "have an auto-measured detector; writes --out (default <control>/registry_coverage_report.json)")
    ap.add_argument("--check", action="store_true",
                    help="with --registry-check: verify --out equals a fresh regeneration instead of writing (DRIFT ONLY: exit 0 on a "
                         "match, 9 on drift)")
    ap.add_argument("--require-covered", action="store_true",
                    help="with --registry-check: exit 11 when a required criterion is uncovered (detector NONE and not declared "
                         "per-asset-pending); without it coverage is reported, not gated")
    ap.add_argument("--out", default=None, help="default: <control>/asset_census.json (scoped: asset_census_scoped.json)")
    a = ap.parse_args()
    if (a.check or a.require_covered) and not a.registry_check:
        ap.error("--check / --require-covered require --registry-check")
    if a.registry_check:
        clash = [f for f, v in (("--emit-gaps", a.emit_gaps), ("--rollup", a.rollup), ("--assets", a.assets is not None),
                                ("--layer", a.layer is not None)) if v]
        if clash:
            ap.error(f"--registry-check is registry-only and cannot be combined with {', '.join(clash)}")
        return registry_check_main(a.out if a.out is not None else str(CTRL / "registry_coverage_report.json"), a.check, a.require_covered)
    if a.layer is None:
        a.layer = "L0"
    keys = list(LAYERS) if a.layer.lower() == "all" else [k.strip().upper() for k in a.layer.split(",")]
    for k in keys:
        if k not in LAYERS:
            sys.exit(f"unknown layer {k}; expected one of {list(LAYERS)} or 'all'")

    full_out = CTRL / "asset_census.json"
    by_layer = None
    if a.assets is not None:
        try:
            by_layer = validate_scope(parse_assets_arg(a.assets), keys)
        except ScopeError as exc:
            print(f"asset_census: scope error — {exc}", file=sys.stderr)
            return EXIT_SCOPE
        except Unknown as exc:
            print(f"asset_census: UNKNOWN — cannot validate --assets against the registry: {exc}")
            return 4
        keys = [k for k in keys if k in by_layer]
    out_path = a.out if a.out is not None else str(CTRL / "asset_census_scoped.json" if by_layer is not None else full_out)
    if by_layer is not None and _is_full_census_path(out_path, full_out):
        print(f"asset_census: scope error — the scoped output path {out_path} is the full census file (same file, "
              "case variant, hardlink or symlink): a scoped (partial) census never replaces the full census — name "
              "another --out", file=sys.stderr)
        return EXIT_SCOPE

    if a.emit_gaps:
        try:
            load_withholding_entries()      # N-100: refuse a bad withholding list before any measuring (emit_gaps re-checks it)
        except WithholdingRefused as exc:
            print(f"asset_census: withholding refused — {exc} (nothing written)", file=sys.stderr)
            return EXIT_WITHHOLDING

    stamp = census_stamp()      # once per run: every layer head carries the same revision/fingerprint/tool provenance
    out, worst = {}, 0
    for k in keys:
        try:
            c = measure(k) if by_layer is None else measure(k, assets=by_layer[k])
        except ScopeError as exc:
            print(f"asset_census: scope error — {exc}", file=sys.stderr)
            return EXIT_SCOPE
        except Unknown as exc:
            print(f"asset_census: UNKNOWN — layer {k}: {exc}")
            print("  Nothing is reported clean: an unreachable instrument is not a passing result.")
            print("  R41 isolates per-asset checks only; a failed layer-wide read leaves this whole layer "
                  f"unmeasured{' and stops every layer after it (no census file written)' if len(keys) > 1 else ''}.")
            return 4
        c.update(stamp)              # N-44 A: registry revision + fingerprint + tool commit in every layer head
        out[k] = c
        if by_layer is not None:
            print(f"{k} SCOPED RUN — partial census, not a layer census: {c['n_assets']} of "
                  f"{c['population_active']} active assets ({', '.join(c['scope']['assets'])})")
        fails = sum(1 for x in c["assets"] for r in x["measurements"].values() if r["v"] == FAIL)
        parts = sum(1 for x in c["assets"] for r in x["measurements"].values() if r["v"] in (PARTIAL, NO_DET))
        errored = sum(1 for x in c["assets"] for r in x["measurements"].values() if r["v"] == ERRORED)
        print(f"{k} {c['layer_name']} ({c['scoring']}): {c['n_assets']} assets · "
              f"{c['registered_ids']} registered ids vs {c['registry_has_writer']} has_writer=true")
        if c["population_registry_total"] != c["population_active"]:
            print(f"  population: {c['population_active']} active of {c['population_registry_total']} registry "
                  f"rows for this layer — excluded (inactive/dead): "
                  f"{', '.join(x['asset_id'] for x in c['population_excluded_inactive'])}")
        if c.get("chart_scoped_count_sql"):
            print(f"  chart scope: {c['chart_scoped_count_sql']} chart-scoped count_sql bound to chart {c['chart_scope']}")
        if "global_runs" in c:   # absent in a scoped census (F4): never stated about the layer from scoped-only data
            print(f"  build scope: {c['global_runs']} global run(s), of which {c['global_runs_touching_layer']} "
                  f"touched this layer" + ("  ← the global path never exercises it" if c['global_runs_touching_layer'] == 0 else ""))
        if c["never_exercised_with_writer"]:
            print(f"  !! registered with a writer and NEVER run by the orchestrator: {c['never_exercised_with_writer']}")
        if c["phantom_registered"]:
            print(f"  !! registered but absent from the registry: {c['phantom_registered']}")
        print(f"  FAIL {fails} · PARTIAL/NO_DETECTOR {parts} · ERRORED {errored} · assets measured {c['n_assets']}")
        if errored:
            print(f"  !! {errored} check(s) errored (R41: degraded, not layer-aborting) — "
                  "never counted as PASS; see each asset's measurements for the exception")
        by = {}
        for x in c["assets"]:
            for crit, r in x["measurements"].items():
                if r["v"] == FAIL:
                    by.setdefault(crit, []).append(x["asset_id"])
        for crit in sorted(by):
            n = by[crit]
            print(f"    FAIL {crit}: {len(n)} — {', '.join(n[:6])}{'…' if len(n) > 6 else ''}")
        worst = max(worst, 2 if fails else (3 if (parts or errored) else 0))
        if a.emit_gaps:
            try:
                g = emit_gaps_summary(c)
            except WithholdingRefused as exc:
                print(f"asset_census: withholding refused — {exc} (nothing written)", file=sys.stderr)
                return EXIT_WITHHOLDING
            print(f"  ledger: {g['added']} row(s) appended, {g['skipped']} already present, "
                  f"{g['closed']} closed (by measurement, or by a criterion's retirement), {g['reopened']} re-opened")
            if g.get("info_only_suppressed"):
                print(f"  ledger: {g['info_only_suppressed']} failing cell(s) on info-only families "
                      f"({', '.join(INFO_ONLY_GATES)}) measured, not opened as gaps (E6.4)")
            if g.get("withheld_unmatched"):
                print(f"  ledger: WARNING — withholding entr(ies) matched no measured cell of this run (a typo or a stale entry "
                      f"withholds nothing): {', '.join(g['withheld_unmatched'])}")
            if g.get("withheld"):
                print(f"  ledger: WITHHELD (no row of any kind written): {', '.join(g['withheld'])}")
            if g["retired_opportunity_rows_left"]:
                print(f"  ledger: {g['retired_opportunity_rows_left']} retired-criterion opportunity row(s) left as is "
                      "(a retirement does not realise an opportunity)")

    rollup_error = None
    if a.rollup:
        # computed AFTER measuring and emit_gaps, from the finished census; never fed to emit_gaps. A rollup
        # failure must not lose the measurements: they are written without a `rollup` key and the run exits 5
        # (overriding any measured worst of 2/3; the stderr message names the measured exit).
        try:
            out = {**out, **build_rollup_output(out)}
        except Exception as exc:  # noqa: BLE001
            rollup_error = f"{type(exc).__name__}: {exc}"
            print(f"asset_census: rollup failed — {rollup_error} (census written without a rollup; measured exit "
                  f"{worst} overridden by 5)", file=sys.stderr)
    if by_layer is not None:    # E1.9: the file header says it is partial, before any layer is read
        out = {"scope": dict(assets=sorted(x for k in keys for x in by_layer[k]), partial=True, layers=list(keys)), **out}
    text = json.dumps(out, indent=1, default=str) + "\n"
    if by_layer is not None:
        _write_atomic(out_path, text)       # E1.9: a scoped file is never torn by a crash or a concurrent scoped run
    else:
        Path(out_path).write_text(text, encoding="utf-8")
    print(f"census written: {os.path.relpath(out_path, ROOT)}" + (" (SCOPED: partial census)" if by_layer is not None else ""))
    if rollup_error:
        return 5
    return worst


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001
        print(f"asset_census: script error — {type(exc).__name__}: {exc}", file=sys.stderr)
        sys.exit(5)
